# The pending fields a move keeps as they are -- the player's own mails not yet in the mailbox, delivered to the new
# uid at its first login -- and the cursor it keeps only together with the mailbox it points into (mails that move
# with the account), by name, under the main save.
_MIGRATE_KEPT_PENDING = frozenset(("mail_bin.wait_add_mail_map", "mail_bin.new_wait_add_mail_map"))
_MIGRATE_MAIL_CURSOR = "mail_bin.has_take_attachment_mail_id_list"


def _mig_path(plan, key):
    """The field numbers of the _MIG_PATHS path `key`, held to `plan` by name: _SaveSchemaInvalid when the plan names
    another field there (or none, for a required path); None for an optional path the plan does not have."""
    path, want, required = _MIG_PATHS[key]
    got = plan.name_at(path)
    if got is None and not required:
        return None
    if got != want:
        raise _SaveSchemaInvalid("The save schema of %s names %s %s where the move expects %s -- nothing is moved."
                                 % (plan.version, path, got or "no field", want))
    return tuple(int(x) for x in path.split(".")[1:])


def _mig_fields(buf, where):
    """[(field, wire type, start, tag end, value start, end)] of a message; _SaveSchemaMismatch naming `where` for
    bytes that are not one."""
    out, i, n = [], 0, len(buf)
    try:
        while i < n:
            start = i
            tag, i = _pb_varint(buf, i)
            fn, wt = tag >> 3, tag & 7
            if fn == 0 or fn > _PB_MAX_FIELD:
                raise _PbParseError("an invalid field number")
            tag_end = vs = i
            if wt == 0:
                _v, i = _pb_varint(buf, i)
            elif wt == 1:
                i += 8
            elif wt == 5:
                i += 4
            elif wt == 2:
                ln, vs = _pb_varint(buf, i)
                i = vs + ln
            else:
                raise _PbParseError("wire type %d" % wt)
            if i > n:
                raise _PbParseError("a field cut short")
            out.append((fn, wt, start, tag_end, vs, i))
    except _PbParseError as e:
        raise _SaveSchemaMismatch("%s does not parse (%s)" % (where, e))
    return out


def _mig_not_message(where, wt):
    return _SaveSchemaMismatch("%s holds wire type %d where the save schema has a message" % (where, wt))


def _mig_varint(fn, value):
    """A varint field, tag included."""
    return _pb_enc(fn << 3) + _pb_enc(value)


def _mig_ld(fn, data):
    """A length-delimited field, tag included."""
    return _pb_enc((fn << 3) | 2) + _pb_enc(len(data)) + data


def _mig_edit(buf, path, leaf, where):
    """`buf` with leaf(buf, field) applied to every occurrence of the field at `path` (the field numbers from this
    message), through every occurrence of each message on the way: leaf gets the message's bytes and the field's
    _mig_fields entry and returns None to keep its bytes, else the bytes that take their place (b"" removes it).
    Only a message something changed in is encoded anew. -> (bytes, changed)."""
    head, rest = path[0], path[1:]
    out, changed = bytearray(), False
    for fd in _mig_fields(buf, where):
        fn, wt, s, te, vs, e = fd
        if fn != head:
            out += buf[s:e]
            continue
        if rest:
            if wt != 2:
                raise _mig_not_message(where, wt)
            sub, sub_changed = _mig_edit(buf[vs:e], rest, leaf, where)
            if sub_changed:
                changed = True
                out += buf[s:te] + _pb_enc(len(sub)) + sub
            else:
                out += buf[s:e]
            continue
        new = leaf(buf, fd)
        if new is None:
            out += buf[s:e]
        else:
            changed = True
            out += new
    return (bytes(out) if changed else buf), changed


def _mig_raw_list(buf, path, where):
    """The bytes -- tag included -- of every occurrence of the field at `path`, through every message on the way."""
    head, rest = path[0], path[1:]
    out = []
    for fn, wt, s, _te, vs, e in _mig_fields(buf, where):
        if fn != head:
            continue
        if rest:
            if wt != 2:
                raise _mig_not_message(where, wt)
            out.extend(_mig_raw_list(buf[vs:e], rest, where))
        else:
            out.append(buf[s:e])
    return out


def _mig_bytes(buf, path, where):
    """The value bytes of every occurrence of the length-delimited field (a message, a string) at `path`."""
    head, rest = path[0], path[1:]
    out = []
    for fn, wt, _s, _te, vs, e in _mig_fields(buf, where):
        if fn != head:
            continue
        if wt != 2:
            raise _mig_not_message(where, wt)
        out.extend(_mig_bytes(buf[vs:e], rest, where) if rest else [buf[vs:e]])
    return out


def _mig_values(buf, path, where):
    """Every number at `path` -- a varint, each element of a packed run, a fixed32 / fixed64 value --, through every
    occurrence of each message on the way."""
    head, rest = path[0], path[1:]
    out = []
    for fn, wt, _s, _te, vs, e in _mig_fields(buf, where):
        if fn != head:
            continue
        if rest:
            if wt != 2:
                raise _mig_not_message(where, wt)
            out.extend(_mig_values(buf[vs:e], rest, where))
        elif wt == 0:
            out.append(_pb_varint(buf, vs)[0])
        elif wt == 2:
            vals = _pb_packed(buf[vs:e])
            if vals is None:
                raise _SaveSchemaMismatch("%s is no packed run of varints" % where)
            out.extend(vals)
        else:
            out.append(int.from_bytes(buf[vs:e], "little"))
    return out


def _mig_last(buf, path, where):
    """The number a single field at `path` holds -- its last occurrence, as protobuf reads it --, 0 when it has none."""
    vals = _mig_values(buf, path, where)
    return vals[-1] if vals else 0


def _mig_put(buf, path, raw, where):
    """`buf` with every field at `path` replaced by `raw` (whole fields, tag included; b"" removes them): the
    messages on the way are single ones -- the last occurrence of each takes `raw`, and one that is not there is made
    when `raw` is not empty. Fields that already are `raw`, in its order, are left where they stand. -> (bytes,
    changed)."""
    head, rest = path[0], path[1:]
    fields = _mig_fields(buf, where)
    if not rest:
        if b"".join(buf[s:e] for fn, _wt, s, _te, _vs, e in fields if fn == head) == raw:
            return buf, False
        return b"".join(buf[s:e] for fn, _wt, s, _te, _vs, e in fields if fn != head) + raw, True
    hits = [i for i, fd in enumerate(fields) if fd[0] == head]
    if not hits:
        if not raw:
            return buf, False
        return bytes(buf) + _mig_ld(head, _mig_put(b"", rest, raw, where)[0]), True
    out, changed = bytearray(), False
    for i, (fn, wt, s, te, vs, e) in enumerate(fields):
        if fn != head:
            out += buf[s:e]
            continue
        if wt != 2:
            raise _mig_not_message(where, wt)
        sub, sub_changed = _mig_put(buf[vs:e], rest, raw if i == hits[-1] else b"", where)
        if sub_changed:
            changed = True
            out += buf[s:te] + _pb_enc(len(sub)) + sub
        else:
            out += buf[s:e]
    return (bytes(out), True) if changed else (buf, False)


def _mig_cut(plan, root, path):
    """The index in `path` of the innermost repeated message above its last field -- the entry the class-uid rule
    removes for a single field that names another player --, None when no repeated message holds it."""
    mtype, cut = plan.roots[root], None
    for i, num in enumerate(path[:-1]):
        f = plan.fields[mtype][num]
        if f[0] == "m" and f[2]:
            cut = i
        mtype = f[3]
    return cut


def _mig_guid_tails(plan, root, path):
    """The guid paths of `root` (plan.guid_scalar, plan.guid_list) that lie below `path`, each from below it."""
    n = len(path)
    return sorted(set(p[n:] for p in plan.guid_scalar.get(root, frozenset()) | plan.guid_list.get(root, frozenset())
                      if len(p) > n and p[:n] == path))


def _mig_uid_walk(buf, plan, mtype, paths, depth, own, dst, st, where):
    """The class-uid rule at every path of `paths` below this message, in one walk -- [(the field numbers from this
    message, cut)], cut = the index in the whole path of the innermost repeated message above its last field (None:
    none holds it); `depth` = this message's index in those paths. A value in `own` (the source uid) becomes `dst`;
    every other value names another player of the source's server -- dst too, where it is not the source uid itself
    -- and is removed: an element of a repeated number on its own, else the innermost repeated message entry that
    holds it, else the field. Counts into `st` ("rewritten", "others"). -> (bytes, changed, gone): `gone` = None, or
    the index of the entry above this message that names another player -- the walk at that entry removes it."""
    heads = {}
    for tail, cut in paths:
        heads.setdefault(tail[0], []).append((tail, cut))
    out, changed, gone = bytearray(), False, None
    for fn, wt, s, te, vs, e in _mig_fields(buf, where):
        group = heads.get(fn)
        if group is None:
            out += buf[s:e]
            continue
        f = plan.fields[mtype][fn]
        deeper = [(tail[1:], cut) for tail, cut in group if len(tail) > 1]
        if deeper:
            if wt != 2:
                raise _mig_not_message(where, wt)
            sub, sub_changed, sub_gone = _mig_uid_walk(buf[vs:e], plan, f[3], deeper, depth + 1, own, dst, st, where)
            if sub_gone == depth:
                changed = True
                st["others"] += 1
                continue
            if sub_gone is not None:
                gone = sub_gone if gone is None else min(gone, sub_gone)
            if sub_changed:
                changed = True
                out += buf[s:te] + _pb_enc(len(sub)) + sub
            else:
                out += buf[s:e]
            continue
        cut = group[0][1]
        if wt == 2:
            vals = _pb_packed(buf[vs:e])
            if vals is None:
                raise _SaveSchemaMismatch("%s is no packed run of varints" % where)
            keep = []
            for x in vals:
                if x in own:
                    keep.append(dst)
                    st["rewritten"] += x != dst
                else:
                    st["others"] += 1
            if keep == vals:
                out += buf[s:e]
                continue
            changed = True
            if keep:
                body = b"".join(_pb_enc(x) for x in keep)
                out += buf[s:te] + _pb_enc(len(body)) + body
            continue
        if wt != 0:
            raise _SaveSchemaMismatch("%s holds wire type %d where the save schema has a uid" % (where, wt))
        x = _pb_varint(buf, vs)[0]
        if x in own:
            if x == dst:
                out += buf[s:e]
            else:
                changed = True
                st["rewritten"] += 1
                out += buf[s:te] + _pb_enc(dst)
            continue
        if f[2] or cut is None:
            changed = True
            st["others"] += 1
            continue
        gone = cut if gone is None else min(gone, cut)
        out += buf[s:e]
    return (bytes(out) if changed else buf), changed, gone


def _mig_apply(blobs, plan, root, fn, where):
    """fn(bytes, its message type) -> (bytes, changed) over every message of `root` the rows hold (`blobs` = {stored
    root: [payload, ...]}): a stored root in each row that holds one, a nested root inside every message of each root
    that holds it (plan.nested_in). Each payload that changed is replaced in `blobs`."""
    held = plan.nested_in.get(root)
    if held is None:
        items = blobs.get(root) or []
        for i, b in enumerate(items):
            new, changed = fn(b, plan.roots[root])
            if changed:
                items[i] = new
        return
    inner = plan.roots[root]

    def leaf(buf, fd):
        _fn, wt, s, te, vs, e = fd
        if wt != 2:
            raise _mig_not_message(where, wt)
        new, changed = fn(buf[vs:e], inner)
        return (buf[s:te] + _pb_enc(len(new)) + new) if changed else None

    for holder, path in held:
        items = blobs.get(holder) or []
        for i, b in enumerate(items):
            new, changed = _mig_edit(b, path, leaf, where)
            if changed:
                items[i] = new


def _mig_unwrap(blob):
    """(the message, whether it was stored as "ZLIB" + zlib) of a stored blob -- copy_save's rule."""
    blob = bytes(blob)
    if blob[:4] == b"ZLIB":
        return zlib.decompress(blob[4:]), True
    return blob, False


def _mig_unplaced(facts, scene):
    """Whether the target's SceneData retires `scene` (its block saves or its state record discarded) or has no such
    scene."""
    return scene in facts["blockbinRetired"] or scene in facts["scenebinRetired"] or scene not in facts["scenes"]


def migrate_postcondition(rows, plan):
    """Why the rows of a move do not decode whole on the save schema `plan` (the target's) -- a field it does not
    know, another wire type, an unclassified 64-bit field, bytes cut short, a stored root it has not --: the walk of
    copy_save (_schema_guid_rewrite) run as a validator, src = dst = _NO_GUID_OWNER, over the main save, the extra and
    before-login saves a row holds, every block row (its nested GroupBin with it) and the home row (migrate_transform's
    rows); None when every one decodes. Pure."""
    try:
        for root, row, column in MIGRATE_ROOT_COLUMNS:
            holders = rows.get(row) if row == "blocks" else [rows.get(row)]
            for holder in holders or ():
                blob = holder.get(column) if isinstance(holder, dict) else None
                if blob is None:
                    continue
                payload, _wrapped = _mig_unwrap(blob)
                if root not in plan.roots:
                    if payload:
                        return "it holds a %s, which version %s's server keeps nowhere" % (root, plan.version)
                    continue
                _schema_guid_rewrite(payload, plan, plan.roots[root], root, _NO_GUID_OWNER, _NO_GUID_OWNER, (), [])
    except (_SaveSchemaMismatch, _PbParseError, zlib.error) as e:
        return "it does not decode on the save schema of version %s (%s)" % (plan.version, e)
    return None


def migrate_context(target, source, uid, dst, fresh, facts, dest=None, mail=False, man=None):
    """migrate_transform's ctx for a save of `source` -- the version the source's server program was told as -- that
    moves to `target` as the uid `dst` (`fresh`: a new one; else the existing account of the uid `dst` is overwritten,
    `dest` = {root: the stored blob of its row} for its cursors and pending data, None when it has no row): the allow
    rule, read at the call -- `source` a key of the target manifest's acceptFrom (migrate_rule; `man`, when the caller
    holds the manifest), the target's plan and the source's usable, migration parts included -- and the plan and
    client prefixes of every version of the rule whose plan is usable (a save says by its client string which of them
    wrote it last). AgentError 409 when the target's server does not read saves of `source`, 500 when the target's or
    the source's save schema cannot be used. Reads the payload manifests and save schemas only."""
    man = read_manifest(target) if man is None else man
    plan, why = save_plan(target, man)
    if plan is None or plan.migrate_problem is not None:
        raise AgentError(500, "The save schema of version %s cannot be used (%s) -- nothing is moved."
                         % (target, why or (plan.migrate_problem if plan is not None else "its payload names none")))
    rule = migrate_rule(man)
    if source not in rule:
        raise AgentError(409, "Version %s's server does not read saves of version %s -- progress moves only to a "
                              "version whose server reads that save." % (target, source))
    plans, prefixes = OrderedDict(), OrderedDict()
    for v in rule:
        if v == target:
            plans[v], prefixes[v] = plan, client_prefixes(man)
            continue
        if v not in VERSIONS:
            continue
        p, why = save_plan(v)
        if p is not None and p.migrate_problem is None:
            plans[v], prefixes[v] = p, client_prefixes(read_manifest(v))
        elif v == source:
            raise AgentError(500, "The save schema of version %s cannot be used (%s) -- nothing is moved."
                             % (v, why or (p.migrate_problem if p is not None else "its payload names none")))
    return {"target": target, "plan": plan, "source": source, "rule": rule, "plans": plans, "prefixes": prefixes,
            "uid": uid, "dst": dst, "fresh": bool(fresh), "dest": dest, "facts": facts, "mail": bool(mail)}


def migrate_transform(rows, ctx):
    """One account's rows, made the target's -- pure: no I/O, no docker, no clock but ctx's facts["now"].
    `rows` = {"player": {"bin_data", "extra_bin_data", "before_login_bin_data": the stored blobs (None for NULL), and
    every other column, passed on as it is}, "blocks": [{"block_id", "data_version", "bin_data"}, ...], "home": None
    or {"data_version", "bin_data"}}; `ctx` = migrate_context's. Blobs are unwrapped as copy_save does ("ZLIB" +
    zlib, or raw) and a changed one is wrapped back the same way; a message is encoded anew only where something in
    it changed, every other byte is copied as it is, and the transform of its own result -- taken as the save of the
    destination uid, the uid it now is -- changes nothing more.
    Step 0, the client: the main save's basic_bin.client_app_version names, by the client prefixes of the rule's
    versions, the version whose save it is (an empty one: the source's) -- a save moved once and never logged in
    still names its old one; none of them: skipped, "clientUnknown". Step 1: that version's drop paths
    (acceptFrom.<it>.drop) removed walking with ITS plan, any root. From here on every walk is the TARGET's plan,
    each path held to it by name (_mig_path): the settled records of the events the target keeps open, only while
    its events files are the payload's (strip_settled_activities); every activity record whose conditions --
    cond_state_map keys, meet_cond_list, expired_cond_list -- name an id the target's installed NewActivityCondData
    does not define, removed WHOLE; the daily / durable dungeon records and the current / unsettled dungeon of a
    domain the target has not (the random map: never); a save standing in a scene the target's SceneData retires or
    lacks moved to its own last place in Teyvat (MIGRATE_HOME_SCENE: the current, player and previous scene set,
    the previous position, rotation and area removed, the avatar's position and rotation taken from scene 3's
    owner_player_location -- cur_pos / cur_rot, else last_valid_pos / last_valid_rot; no such place: refused; a field
    the plan has not is not set); a dungeon quit scene and an offline born scene of such a scene removed with their
    positions; every field of the class uid, in every root (the GroupBin of each block row included): the source uid
    becomes the destination uid, and every other value goes -- the destination uid too, where it is not the source
    uid: a save of the source's server holds it only for another of its players -- (an element of a repeated number,
    else the innermost repeated entry holding it, else the field); every cursor and pending field removed for a new
    uid and the destination's own taken for an overwrite (of its pending operations, those that name an item of its
    save by guid left out: that save is the one the overwrite replaces) -- but the player's own undelivered mails
    (_MIGRATE_KEPT_PENDING) and, with the mails, the cursor into their mailbox. Then, never cut: the block rows of
    scenes whose blocks the target discards, the persistent dungeon scenes whose state it discards, the map pins it
    deletes, the bag's items its MaterialDeleteData expires (kind 2 before facts["now"]) or lists under another
    rule, the wish banners it does not have (all reported). The result must decode whole on the target's plan
    (migrate_postcondition) and every id of MIGRATE_ID_CATEGORIES it holds must be the target's (else refused,
    "unknownIds").
    -> (new_rows, report): new_rows the rows' structure with every changed blob replaced (every other the very object
    it was), None when the account is skipped (report["why"] "clientUnknown") or refused ("refused", with "reason" --
    the sentence -- and "unknownIds" when ids are the cause). The report: "client" (the version whose save it was),
    "dropped", "settled" (activity ids), "cut" ([{"activity", "conds"}]), "dungeons", "relocated" ({"from", "to"} or
    None), "quitScene", "bornScene", "rewritten" / "others" (own uids set to the destination's / values and entries
    naming other players removed, pending offline operations among them), "cursors", "pending" (the pending entries
    removed: the save's own, and those of an overwritten destination that name an item of its save), "serverRemoves"
    ({"blocks", "scenes", "marks"}), "expiring", "expiryOther", "gachaUnknown", "unknownIds". _SaveSchemaInvalid when a
    plan names another field at a path a step walks (the caller's 500: nothing is moved)."""
    report = {"client": None, "dropped": 0, "settled": [], "cut": [], "dungeons": [], "relocated": None,
              "quitScene": None, "bornScene": None, "rewritten": 0, "others": 0, "cursors": 0, "pending": 0,
              "serverRemoves": {"blocks": [], "scenes": [], "marks": []}, "expiring": [], "expiryOther": [],
              "gachaUnknown": [], "unknownIds": {}, "why": None, "reason": None}
    try:
        return _migrate_transform(rows, ctx, report)
    except (_SaveSchemaMismatch, _PbParseError, zlib.error) as e:
        report.update(why="refused", reason="it cannot be read as a save (%s)" % e)
        return None, report


def _migrate_transform(rows, ctx, report):
    plan, facts, rule, target = ctx["plan"], ctx["facts"], ctx["rule"], ctx["target"]
    new_rows = dict(rows)
    new_rows["player"] = dict(rows.get("player") or {})
    new_rows["blocks"] = [dict(b) for b in rows.get("blocks") or ()]
    new_rows["home"] = None if rows.get("home") is None else dict(rows["home"])
    blobs, slots = {}, []
    for root, row, column in MIGRATE_ROOT_COLUMNS:
        holders = new_rows["blocks"] if row == "blocks" else [h for h in (new_rows[row],) if h is not None]
        for holder in holders:
            if holder.get(column) is None:
                continue
            payload, wrapped = _mig_unwrap(holder[column])
            blobs.setdefault(root, []).append(payload)
            slots.append((root, len(blobs[root]) - 1, holder, column, payload, wrapped))
    if not blobs.get(SAVE_MAIN_ROOT):
        report.update(why="refused", reason="it holds no main save")
        return None, report
    w = SAVE_MAIN_ROOT

    # step 0: whose save it is, by its client string
    source_plan = ctx["plans"].get(ctx["source"])
    if source_plan is None:
        report.update(why="refused", reason="the save schema of version %s cannot be used" % ctx["source"])
        return None, report
    cpath = _mig_path(source_plan, "client")
    client = ""
    if cpath is not None:
        got = _mig_bytes(blobs[SAVE_MAIN_ROOT][0], cpath, w)
        client = got[-1].decode("utf-8", "replace") if got else ""
    if client:
        version = next((v for v in rule if any(client.startswith(p) for p in ctx["prefixes"].get(v, ()))), None)
    else:
        version = ctx["source"] if ctx["source"] in rule else None
    if version is None:
        report.update(why="clientUnknown", reason="its client (%s) is of no version whose saves version %s's server "
                                                  "reads" % (client, target))
        return None, report
    own_plan = ctx["plans"].get(version)
    if own_plan is None:
        report.update(why="refused", reason="it is a save of version %s, whose save schema cannot be used" % version)
        return None, report
    report["client"] = version

    # step 1: the fields its saves have and the target's have not, walking with ITS plan
    for path_text in rule[version]:
        m = _SCHEMA_PATH_RE.match(path_text)
        if not m or own_plan.field_at(path_text) is None:
            raise _SaveSchemaInvalid("The save schema of %s names no field at %s, which the manifest of %s drops from "
                                     "its saves -- nothing is moved." % (version, path_text, target))
        nums = tuple(int(x) for x in m.group(2)[1:].split("."))

        def dropped(_buf, _fd):
            report["dropped"] += 1
            return b""

        _mig_apply(blobs, own_plan, m.group(1), lambda b, _mt, nums=nums, leaf=dropped, where=path_text:
                   _mig_edit(b, nums, leaf, where), path_text)

    # steps 2 onward walk with the target's plan
    pay = blobs[SAVE_MAIN_ROOT][0]
    amap = _mig_path(plan, "activityMap")
    akey, aval = _mig_path(plan, "activityKey")[-1], _mig_path(plan, "activityValue")[-1]
    for key in ("schedule", "settled"):  # the fields strip_settled_activities reads, held to the plan too
        _mig_path(plan, key)
    if facts["openIds"] and not facts["eventsMissing"]:
        pay, removed = strip_settled_activities(pay, facts["openIds"])
        report["settled"] = sorted(set(a for a, _sched in removed))
    meet, states = _mig_path(plan, "meetConds")[-1], _mig_path(plan, "condStates")[-1]
    state_key = _mig_path(plan, "condStateKey")[-1]
    expired = _mig_path(plan, "expiredConds")

    def cut(buf, fd):
        _fn, wt, _s, _te, vs, e = fd
        if wt != 2:
            raise _mig_not_message("PlayerDataBin.20.1", wt)
        entry, named = buf[vs:e], set()
        for value in _mig_bytes(entry, (aval,), "PlayerDataBin.20.1.2"):
            named.update(_mig_values(value, (meet,), "PlayerDataBin.20.1.2"))
            named.update(_mig_values(value, (states, state_key), "PlayerDataBin.20.1.2"))
            if expired is not None:
                named.update(_mig_values(value, (expired[-1],), "PlayerDataBin.20.1.2"))
        undefined = sorted(c for c in named if c and c not in facts["conds"])
        if not undefined:
            return None
        report["cut"].append({"activity": _mig_last(entry, (akey,), "PlayerDataBin.20.1"), "conds": undefined})
        return b""

    pay = _mig_edit(pay, amap, cut, "PlayerDataBin.20.1")[0]
    for mkey, kkey in (("dungeonDaily", "dungeonDailyKey"), ("dungeonDurable", "dungeonDurableKey")):
        knum = _mig_path(plan, kkey)[-1]

        def lacked(buf, fd, knum=knum):
            _fn, wt, _s, _te, vs, e = fd
            if wt != 2:
                raise _mig_not_message("PlayerDataBin.6.5", wt)
            key = _mig_last(buf[vs:e], (knum,), "PlayerDataBin.6.5")
            if key in facts["dungeons"]:
                return None
            report["dungeons"].append(key)
            return b""

        pay = _mig_edit(pay, _mig_path(plan, mkey), lacked, "PlayerDataBin.6.5")[0]
    for key in ("curDungeon", "lastUnsettled"):
        p = _mig_path(plan, key)
        d = _mig_last(pay, p, w)
        if d and d not in facts["dungeons"]:
            report["dungeons"].append(d)
            pay = _mig_put(pay, p, b"", w)[0]

    # the place the save stands in
    cur = _mig_last(pay, _mig_path(plan, "curScene"), w)
    if cur and _mig_unplaced(facts, cur):
        smap = _mig_path(plan, "sceneMap")
        mkey = _mig_path(plan, "sceneMapKey")[len(smap):]
        loc_p = _mig_path(plan, "location")
        loc = None
        for entry in _mig_bytes(pay, smap, w):
            if _mig_last(entry, mkey, w) == MIGRATE_HOME_SCENE:
                found = _mig_bytes(entry, loc_p[len(smap):], w)
                loc = found[-1] if found else loc

        def at(key):
            got = _mig_bytes(loc, _mig_path(plan, key)[len(loc_p):], w) if loc is not None else []
            return got[-1] if got else None

        pos, rot = at("curPos"), at("curRot")
        pos = pos if pos is not None else at("validPos")
        rot = rot if rot is not None else at("validRot")
        if pos is None:
            report.update(why="refused", reason="it stands in scene %d, which version %s %s, and has no place in "
                                                "Teyvat to move to" % (cur, target, "does not have" if cur not in
                                                                         facts["scenes"] else "retires"))
            return None, report
        for key in ("curScene", "curPlayerScene", "prevScene"):
            p = _mig_path(plan, key)
            if p is not None:
                pay = _mig_put(pay, p, _mig_varint(p[-1], MIGRATE_HOME_SCENE), w)[0]
        for key in ("prevPos", "prevRot", "curArea"):
            p = _mig_path(plan, key)
            if p is not None:
                pay = _mig_put(pay, p, b"", w)[0]
        for key, value in (("avatarPos", pos), ("avatarRot", rot)):
            p = _mig_path(plan, key)
            if p is not None:
                pay = _mig_put(pay, p, b"" if value is None else _mig_ld(p[-1], value), w)[0]
        report["relocated"] = {"from": cur, "to": MIGRATE_HOME_SCENE}
    for scene_key, more in (("quitScene", ("quitTarget", "quitPos", "quitRot")), ("bornScene", ("bornPos",))):
        p = _mig_path(plan, scene_key)
        s = _mig_last(pay, p, w) if p is not None else 0
        if s and _mig_unplaced(facts, s):
            for key in (scene_key,) + more:
                q = _mig_path(plan, key)
                if q is not None:
                    pay = _mig_put(pay, q, b"", w)[0]
            report[scene_key] = s
    blobs[SAVE_MAIN_ROOT][0] = pay

    # the fields bound to the uid, in every root: the source uid is the player's own, every other value -- the
    # destination uid too, where it is not the source uid -- names another player of the source's server
    own, dst, st = {ctx["uid"]}, ctx["dst"], {"rewritten": 0, "others": 0}
    by_root = OrderedDict()
    for (root, path), cls in plan.uid_bound.items():
        if cls == "uid":
            by_root.setdefault(root, []).append((path, _mig_cut(plan, root, path)))
    for root, paths in by_root.items():
        _mig_apply(blobs, plan, root, lambda b, mt, paths=paths, where=root:
                   _mig_uid_walk(b, plan, mt, paths, 0, own, dst, st, where)[:2], root)
    dest = ctx.get("dest") or {}
    for (root, path), cls in plan.uid_bound.items():
        if cls not in ("cursor", "pending"):
            continue
        where = _schema_path_text(root, path)
        name = plan.name_at(where)
        if root == SAVE_MAIN_ROOT and ((cls == "pending" and name in _MIGRATE_KEPT_PENDING)
                                       or (cls == "cursor" and name == _MIGRATE_MAIL_CURSOR and ctx.get("mail"))):
            continue
        raw = b""
        if not ctx["fresh"] and dest.get(root) is not None:
            taken = _mig_raw_list(_mig_unwrap(dest[root])[0], path, where)
            tails = _mig_guid_tails(plan, root, path) if cls == "pending" else []
            if tails:
                # an operation of the destination's that names an item of its save by guid names one the overwrite
                # replaces -- it would fall on the moved save's item of that number: left out
                kept_ = [f for f in taken if not any(x for value in _mig_bytes(f, path[-1:], where) for tail in tails
                                                     for x in _mig_values(value, tail, where))]
                report["pending"] += len(taken) - len(kept_)
                st["others"] += len(taken) - len(kept_)
                taken = kept_
            raw = b"".join(taken)
        items = blobs.get(root) or []
        for i, b in enumerate(items):
            n = len(_mig_raw_list(b, path, where))
            new, changed = _mig_put(b, path, raw, where)
            if changed:
                items[i] = new
                if cls == "cursor":
                    report["cursors"] += 1
                else:
                    report["pending"] += n
                    st["others"] += n
    report["rewritten"], report["others"] = st["rewritten"], st["others"]

    # what the server itself discards at the first login: reported, never cut
    pay = blobs[SAVE_MAIN_ROOT][0]
    for b in new_rows["blocks"]:
        if facts["blockScene"].get(b.get("block_id")) in facts["blockbinRetired"]:
            report["serverRemoves"]["blocks"].append(b.get("block_id"))
    for list_key, id_key, flag, into in (("dungeonScenes", "dungeonSceneId", "scenebinRetired", "scenes"),
                                         ("marks", "markScene", "marksDeleted", "marks")):
        p, q = _mig_path(plan, list_key), _mig_path(plan, id_key)
        if p is not None and q is not None:
            for entry in _mig_bytes(pay, p, w):
                s = _mig_last(entry, q[len(p):], w)
                if s in facts[flag]:
                    report["serverRemoves"][into].append(s)
    for iid in sorted(set(v for v in _mig_values(pay, _mig_path(plan, "itemId"), w) if v)):
        row = facts["expiry"].get(iid)
        if row is None:
            continue
        if row[0] == "2" and facts["now"] and _MIG_STAMP_RE.match(row[1]):
            if row[1] < facts["now"]:
                report["expiring"].append(iid)
        else:
            report["expiryOther"].append(iid)
    gp = _mig_path(plan, "gachaSchedule")
    if gp is not None and facts["gacha"] is not None:
        report["gachaUnknown"] = sorted(set(v for v in _mig_values(pay, gp, w) if v and v not in facts["gacha"]))
    report["dungeons"] = sorted(set(report["dungeons"]))
    for key in ("blocks", "scenes", "marks"):
        report["serverRemoves"][key] = sorted(report["serverRemoves"][key])

    # the rows, wrapped back -- then they must decode whole on the target's plan and hold only the target's ids
    for root, i, holder, column, payload, wrapped in slots:
        new = blobs[root][i]
        if new is not payload and new != payload:
            holder[column] = (b"ZLIB" + zlib.compress(new, 6)) if wrapped else new
    why = migrate_postcondition(new_rows, plan)
    if why:
        report.update(why="refused", reason=why)
        return None, report
    ids, unknown = facts["ids"], {}

    def need(category, values, known):
        miss = set(v for v in values if v and v not in known)
        if miss:
            unknown.setdefault(category, set()).update(miss)

    need("avatar", _mig_values(pay, _mig_path(plan, "avatarId"), w), ids["avatar"])
    need("skillDepot", _mig_values(pay, _mig_path(plan, "skillDepot"), w), ids["skillDepot"])
    items_p, equip_p = _mig_path(plan, "items"), _mig_path(plan, "equipList")
    lists = [items_p]
    if equip_p is not None:
        if plan.field_at(_MIG_PATHS["equipList"][0])[3] != plan.field_at(_MIG_PATHS["items"][0])[3]:
            raise _SaveSchemaInvalid("The save schema of %s names %s a list of other items than %s -- nothing is moved."
                                     % (plan.version, _MIG_PATHS["equipList"][0], _MIG_PATHS["items"][0]))
        lists.append(equip_p)
    sub = dict((key, None if _mig_path(plan, key) is None else _mig_path(plan, key)[len(items_p):])
               for key in ("itemId", "itemMaterial", "itemReliquary", "itemWeapon", "itemFurniture", "mainProp",
                           "affixes"))
    item_known = frozenset().union(*(ids[c] for c in _MIGRATE_ITEM_CATEGORIES))
    for lp in lists:
        for item in _mig_bytes(pay, lp, w):
            iid = _mig_last(item, sub["itemId"], w)
            if iid and iid not in item_known:
                kind = next((c for key, c in (("itemReliquary", "reliquary"), ("itemWeapon", "weapon"),
                                              ("itemFurniture", "furniture"))
                             if sub[key] is not None and _mig_raw_list(item, sub[key], w)), "material")
                unknown.setdefault(kind, set()).add(iid)
            if sub["mainProp"] is not None:
                need("reliquaryMainProp", _mig_values(item, sub["mainProp"], w), ids["reliquaryMainProp"])
            if sub["affixes"] is not None:
                need("reliquaryAffix", _mig_values(item, sub["affixes"], w), ids["reliquaryAffix"])
    need("scene", [_mig_last(pay, _mig_path(plan, "curScene"), w)], ids["scene"])
    if unknown:
        report["unknownIds"] = OrderedDict((c, sorted(unknown[c])) for c, _t in MIGRATE_ID_CATEGORIES if c in unknown)
        report.update(why="refused", reason="it holds ids version %s does not define (%s)" % (target, "; ".join(
            "%s %s" % (c, ", ".join(str(x) for x in ids_[:8]) + (" ..." if len(ids_) > 8 else ""))
            for c, ids_ in report["unknownIds"].items())))
        return None, report
    return new_rows, report


ACCOUNT_SPEC_MAX = 128  # an account name the copy route takes (the vendor's register page sets no limit)


def _copy_name_field(b, key):
    """An account name of a copy request: a string (or, as the route always took, a number), one line of
    plain text, not empty -- 400 otherwise."""
    v = b.get(key)
    if isinstance(v, bool) or not isinstance(v, (str, int)):
        raise AgentError(400, "%s must be an account name" % key)
    v = str(v).strip()
    if not v:
        raise AgentError(400, "%s is empty" % key)
    if len(v) > ACCOUNT_SPEC_MAX or plain_line_problem(v):
        raise AgentError(400, "%s is not an account name (one line of plain text, at most %d characters)"
                         % (key, ACCOUNT_SPEC_MAX))
    return v


def _copy_uid_field(b, key):
    v = b.get(key)
    if isinstance(v, bool) or not isinstance(v, int) or not 1 <= v <= GAME_UID_MAX:
        raise AgentError(400, "%s must be a game uid (a whole number from 1 to %d)" % (key, GAME_UID_MAX))
    return v


def account_copy_preflight(b):
    """POST /server/account/copy's refusals before a job exists, all 400 -- never a 404 (that means "an agent
    without this route" to the launcher). Exactly one source: `from` (an account name, or as ever the digits
    of a game uid), `fromUid` (a game uid) or `fromTemplate` (a progress template the version's manifest
    ships -- whether it is imported on the stack is the job's 409); exactly one target: `to` (an account
    name; a missing one is created by the job) or `toUid` (a game uid), never the uid `fromUid` names;
    `dryRun` true / false / absent. A key whose value is null counts as absent. -> (version, the source as
    do_account_copy's keyword, the target likewise, dry_run)."""
    version = str(b.get("version", "")).strip()
    check_known(version)
    sources = [k for k in ("from", "fromUid", "fromTemplate") if b.get(k) is not None]
    if len(sources) != 1:
        raise AgentError(400, "name exactly one source: from (an account name), fromUid (a game uid) or "
                              "fromTemplate (a progress template)")
    targets = [k for k in ("to", "toUid") if b.get(k) is not None]
    if len(targets) != 1:
        raise AgentError(400, "name exactly one target: to (an account name) or toUid (a game uid)")
    dry = b.get("dryRun")
    if dry is not None and not isinstance(dry, bool):
        raise AgentError(400, "dryRun must be true or false")
    if sources[0] == "from":
        src = {"src_spec": _copy_name_field(b, "from")}
    elif sources[0] == "fromUid":
        src = {"src_uid": _copy_uid_field(b, "fromUid")}
    else:
        tpl = b.get("fromTemplate")
        tpl = tpl.strip() if isinstance(tpl, str) else ""
        if tpl not in {t["id"] for t in manifest_templates(version)}:
            raise AgentError(400, "that template is not available on this server", code="template_unavailable")
        src = {"template": tpl}
    if targets[0] == "to":
        dst = {"dst_spec": _copy_name_field(b, "to")}
    else:
        dst = {"dst_uid": _copy_uid_field(b, "toUid")}
    if "src_uid" in src and src["src_uid"] == dst.get("dst_uid"):
        raise AgentError(400, "Source and destination are the same player (uid %d)." % src["src_uid"])
    return version, src, dst, bool(dry)


# -- the account list (GET /server/accounts) --
# Every account of a version, for the admin, a page at a time, from the three stores a stack keeps: the
# logins from a COPY of sdk/data/sdk.db (the sdk service holds the live file open; a copy works with the stack
# down too), the characters from ONE MySQL query and who is online from ONE redis scan -- those two only while
# the version runs. Read-only: never a job, never _op_lock, no container started or restarted, nothing written
# to the state file, no account name in the agent log. Never a password hash, an e-mail address, a token, an IP
# or a device id in the answer: the sdk.db read selects none of them (of the e-mail only whether this agent's
# register call made it up). Never in /status or /public/status.

ACCOUNTS_LIMIT_DEFAULT = 100
ACCOUNTS_LIMIT_MAX = 500
ACCOUNTS_QUERY_MAX = 64
# The whole read finishes well inside the launcher's 60 s: a second read waits for the one under way at most
# ACCOUNTS_LOCK_WAIT seconds, then 409; each docker call has its own cap and never more than what is left of
# ACCOUNTS_BUDGET, counted from the request (a call with less than a second left is not made).
ACCOUNTS_LOCK_WAIT = 5
ACCOUNTS_BUDGET = 40
ACCOUNTS_T_LS = 8
ACCOUNTS_T_MYSQL = 20
ACCOUNTS_T_REDIS = 10
# A presence key with no save for this long reads as stale -- advisory only, never acted on: a player in game
# is saved at least every 120 s (1.6) / 180 s (2.8, 3.2), and a stack stopped while a player was in game can
# leave the key behind (it has no expiry).
ACCOUNTS_STALE_AFTER = 600
_ACCOUNTS_LOCK = threading.Lock()
# The jobs beside which the list asks the game database and redis: the ones that never stop or start a service
# (SERVICE_REPORT_JOBS) and the account copy, one transaction of its own. Any other job -- a start, a stop, a
# provision, a relocation, a secrets rotation -- has the stack between two states.
ACCOUNTS_READ_BESIDE = SERVICE_REPORT_JOBS + ("accountcopy",)
SDK_DB_READ_TRIES = 4
# The first 8 bytes of a rollback journal that holds a transaction sqlite has not finished: they are written
# when the transaction is about to change the database file -- a journal whose header is still zero has not
# touched it yet.
_SQLITE_JOURNAL_MAGIC = bytes.fromhex("d9d505f920a163d7")
_PRESENCE_KEY_RE = re.compile(r"PlayerStatus:\{([0-9]+)\}")
_SQL_NUMBER_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")
_HEX_TEXT_RE = re.compile(r"(?:[0-9A-Fa-f]{2})*")


class _SdkDbUnreadable(Exception):
    """A sqlite file no consistent copy could be read of; the message is a short reason that names no path."""


class _SqliteTorn(Exception):
    """One copy of a sqlite file met a write under way (read_sqlite_copy tries again)."""


def _sdk_db_pause(seconds):
    time.sleep(seconds)


def _open_shared(path):
    """`path` opened for reading in a way that never stands in the way of its deletion: on Windows through
    CreateFile with FILE_SHARE_DELETE, which Python's open() leaves out -- sqlite commits a transaction by
    deleting its journal, and a commit that met an open of ours would fail with the sdk's request; elsewhere
    open() as ever. FileNotFoundError when it is gone, OSError otherwise."""
    if not IS_WINDOWS:
        return open(path, "rb")
    import _winapi
    import msvcrt
    # GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL
    handle = _winapi.CreateFile(path, 0x80000000, 0x7, 0, 3, 0x80, 0)
    try:
        fd = msvcrt.open_osfhandle(handle, os.O_RDONLY)
    except BaseException:
        _winapi.CloseHandle(handle)
        raise
    return os.fdopen(fd, "rb")


def _copy_shared(src, dst):
    """shutil.copyfile, with `src` read through _open_shared."""
    with _open_shared(src) as fin:
        with open(dst, "wb") as fout:
            shutil.copyfileobj(fin, fout, 1 << 20)


def _sqlite_file_mark(path):
    """(size, mtime, the file change counter of the header) of a sqlite file: in a rollback-journal database
    the counter (4 bytes at offset 24) changes at every commit, and with it the page it lives on -- the first
    one a commit writes. FileNotFoundError when the file is gone."""
    st = os.stat(path)
    with _open_shared(path) as f:
        head = f.read(28)
    return st.st_size, st.st_mtime_ns, head[24:28]


def _sqlite_journal_state(journal):
    """(hot, stamp) of the rollback journal beside a sqlite file: hot = it holds a transaction sqlite has not
    finished (it exists and starts with the journal magic), stamp = its (size, mtime) -- to tell a journal that
    stays from one that is being written --, None when there is none. One that cannot be read counts as hot."""
    try:
        st = os.stat(journal)
    except FileNotFoundError:
        return False, None
    except OSError:
        return True, None
    stamp = (st.st_size, st.st_mtime_ns)
    try:
        with _open_shared(journal) as f:
            head = f.read(len(_SQLITE_JOURNAL_MAGIC))
    except FileNotFoundError:
        return False, None
    except OSError:
        return True, stamp
    return head == _SQLITE_JOURNAL_MAGIC, stamp


def _read_sqlite_snapshot(src, read, stamp):
    """One try of read_sqlite_copy, in a private temp folder that goes away at once: the file copied and
    read(con) on the copy. The file's mark (_sqlite_file_mark) is taken before the copy and again after it,
    the journal looked at in between: a mark that changed, a copy whose counter is not the mark's, or a
    journal that turned hot means a write met the copy. With `stamp` the hot journal is copied first, the file
    after it, and the journal must still be the same one: sqlite then rolls it back inside the copy.
    _SqliteTorn when a write met the copy; FileNotFoundError only when `src` is gone."""
    import tempfile
    journal = src + "-journal"
    tmpd = tempfile.mkdtemp(prefix="gio-sqlite-")
    try:
        copy = os.path.join(tmpd, "copy.db")
        mark = _sqlite_file_mark(src)
        try:
            if stamp is not None:
                _copy_shared(journal, copy + "-journal")
            _copy_shared(src, copy)
        except FileNotFoundError:
            if not os.path.exists(src):
                raise
            raise _SqliteTorn()  # the journal went: the transaction ended under the copy
        # The journal first, the mark after it: a transaction that wrote pages into the copy and ended in
        # between has then changed the counter the mark reads.
        hot, now = _sqlite_journal_state(journal)
        if (stamp is None and hot) or (stamp is not None and now != stamp):
            raise _SqliteTorn()
        try:
            if _sqlite_file_mark(src) != mark:
                raise _SqliteTorn()
        except FileNotFoundError:
            raise _SqliteTorn()
        with open(copy, "rb") as f:
            if f.read(28)[24:28] != mark[2]:
                raise _SqliteTorn()
        con = sqlite3.connect(copy)
        try:
            return read(con)
        finally:
            con.close()
    finally:
        _rmtree_quiet(tmpd)


def read_sqlite_copy(src, read, tries=SDK_DB_READ_TRIES):
    """read(con) on a private copy of the sqlite file `src` -- never on the file itself, which the sdk service
    holds open, and every open of the live file and its journal one that never stands in the way of the
    sdk's own commit (_open_shared). A copy taken while sqlite writes the file can be torn without sqlite
    noticing, so a copy counts only when no hot journal sat beside the file before AND after it and the file
    did not change while it was copied (its size, time and commit counter the same before and after, the
    copy's counter the same as well -- a whole transaction can begin and end under one copy), and is taken
    again after a short pause otherwise -- or when the copy could not be read. A journal that stays exactly as
    it was through every try is a transaction nobody finishes (the sdk stopped in the middle of a write): the
    copy is then taken together with it, and sqlite rolls it back inside the copy -- the last state that was
    committed. FileNotFoundError when `src` does not exist; _SdkDbUnreadable with a short reason otherwise."""
    why, seen = "it cannot be read", []
    for attempt in range(tries):
        if attempt:
            _sdk_db_pause(0.15 * attempt)
        hot, stamp = _sqlite_journal_state(src + "-journal")
        if hot:
            seen.append(stamp)
            why = "it is being written"
            continue
        seen.append(None)
        try:
            return _read_sqlite_snapshot(src, read, None)
        except _SqliteTorn:
            why = "it is being written"
        except sqlite3.DatabaseError:
            why = "it is not an account database"
    if seen and seen[0] is not None and all(s == seen[0] for s in seen):
        try:
            return _read_sqlite_snapshot(src, read, seen[0])
        except (_SqliteTorn, sqlite3.DatabaseError):
            pass
    raise _SdkDbUnreadable(why)


def _sqlite_text(v):
    if v is None or isinstance(v, str):
        return v
    if isinstance(v, bytes):
        return v.decode("utf-8", "replace")
    return str(v)


def _sqlite_lenient_text(b):
    """A connection's text_factory for an sdk.db: a TEXT value that is no UTF-8 (nothing the vendor's
    register page makes, but nothing stops a hand edit) reads with replacement characters instead of failing
    the whole read."""
    return b.decode("utf-8", "replace")


def _whole_or_none(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, int):
        return v
    if isinstance(v, float) and v == v and abs(v) < 1e15:
        return int(v)
    return None


def _sdk_accounts_read(con):
    """([(sdk uid, name, type, epoch_created, made up by this agent's register call)], {sdk uid: last login})
    of an opened sdk.db -- uid, name, type and times only; of the e-mail address only whether it is the kind
    _sdk_register makes up (<name>.<4 digits>@relic.local). Never the password, the e-mail itself, a token, a
    device or an IP. A column the table lacks reads as NULL; no accounts table = sqlite3.DatabaseError."""
    con.text_factory = _sqlite_lenient_text
    cols = {row[1] for row in con.execute("PRAGMA table_info(accounts)")}
    if "uid" not in cols:
        raise sqlite3.DatabaseError("no accounts table")
    picked = ", ".join(c if c in cols else "NULL" for c in ("name", "type", "epoch_created"))
    made = "(email LIKE '%@relic.local')" if "email" in cols else "0"
    accounts = []
    for uid, name, typ, created, here in con.execute("SELECT uid, %s, %s FROM accounts" % (picked, made)):
        if _whole_or_none(uid) is not None:
            accounts.append((int(uid), _sqlite_text(name), _whole_or_none(typ), _whole_or_none(created), bool(here)))
    last = {}
    if con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='combo_tokens'").fetchone():
        for uid, at in con.execute("SELECT uid, epoch_generated FROM combo_tokens"):
            uid, at = _whole_or_none(uid), _whole_or_none(at)
            if uid is not None and at is not None:
                last[uid] = max(at, last.get(uid, at))
    return accounts, last


def _iso_utc(epoch):
    """Seconds since the epoch -> "YYYY-MM-DDTHH:MM:SSZ"; None for a missing, zero or unusable time."""
    v = _whole_or_none(epoch)
    if not v or v < 0:
        return None
    try:
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(v))
    except (OverflowError, OSError, ValueError):
        return None


def accounts_characters_sql():
    """The ONE query behind the characters of the account list: every row of t_player_uid with the save its
    shard holds (t_player_data_<uid % 10>, each joined by its primary key) -- the scan of t_player_uid is the
    only part that is no key lookup (its one index on account_uid starts with account_type). No filter on
    account_type: a guest who played has a row of type 0. Every text column goes through HEX(), so the answer
    is plain ASCII whatever a nickname holds (a tab, a line break) and whatever code page the box's docker
    client output is read with. Pure."""
    shards = range(10)

    def first(col):
        return "COALESCE(%s)" % ", ".join("d%d.%s" % (n, col) for n in shards)

    joins = " ".join("LEFT JOIN t_player_data_%d d%d ON d%d.uid = u.uid AND u.uid %% 10 = %d" % (n, n, n, n)
                     for n in shards)
    return ("SELECT HEX(u.account_uid), u.account_type, u.uid, UNIX_TIMESTAMP(u.create_time), HEX(%s), %s, "
            "UNIX_TIMESTAMP(%s), TIMESTAMPDIFF(SECOND, %s, NOW()) FROM t_player_uid u %s"
            % (first("nickname"), first("level"), first("last_save_time"), first("last_save_time"), joins))


def _sql_cell_number(cell):
    if cell == "NULL":
        return None
    if not _SQL_NUMBER_RE.fullmatch(cell):
        raise ValueError("a cell that is no number")
    return int(float(cell)) if "." in cell else int(cell)


def _sql_cell_text(cell):
    if cell == "NULL":
        return None
    if not _HEX_TEXT_RE.fullmatch(cell):
        raise ValueError("a cell that is no HEX()")
    return bytes.fromhex(cell).decode("utf-8", "replace")


def parse_accounts_characters(text):
    """The answer of accounts_characters_sql() (mysql -N -B: one line per row, tab-separated, NULL as the word)
    -> [{account, type, uid, created, nickname, level, saved, age}] (`account` = t_player_uid.account_uid as
    text, `age` = seconds since the last save). ValueError for an answer of another shape. Pure."""
    rows = []
    for line in (text or "").splitlines():
        if not line.strip():
            continue
        cells = line.split("\t")
        if len(cells) != 8:
            raise ValueError("a line of %d cells" % len(cells))
        row = {"account": _sql_cell_text(cells[0]), "type": _sql_cell_number(cells[1]),
               "uid": _sql_cell_number(cells[2]), "created": _sql_cell_number(cells[3]),
               "nickname": _sql_cell_text(cells[4]), "level": _sql_cell_number(cells[5]),
               "saved": _sql_cell_number(cells[6]), "age": _sql_cell_number(cells[7])}
        if row["uid"] is None:
            raise ValueError("a row without its uid")
        rows.append(row)
    return rows


def parse_presence_scan(text):
    """The answer of `redis-cli -n 7 --scan --pattern PlayerStatus:*` -> the set of uids with a presence key.
    ValueError for a line that is no such key (an error redis-cli printed, an answer of another shape). Pure."""
    out = set()
    for line in (text or "").splitlines():
        line = line.strip()
        if not line:
            continue
        m = _PRESENCE_KEY_RE.fullmatch(line)
        if m:
            out.add(int(m.group(1)))
        elif not line.startswith("PlayerStatus:"):
            raise ValueError("a line that is no presence key")
    return out


def _accounts_timed_out(r):
    return isinstance(r, _Failed) and str(r.stderr).startswith("timed out")


def _accounts_running(version, timeout):
    """Whether the version's compose project runs (`docker compose ls` names the running ones) -- None when
    docker does not answer within `timeout` (_run_capped, like every docker call of the list)."""
    try:
        ls = _run_capped(["docker", "compose", "ls", "--format", "json"], timeout=timeout)
    except Exception:  # noqa: BLE001 -- anything at all: no answer
        return None
    if ls.returncode != 0:
        return None
    names = _parse_ls_json(ls.stdout)
    return None if names is None else VERSIONS[version]["project"] in names


def _accounts_read_characters(version, timeout):
    """(parse_accounts_characters rows, None) -- or (None, a short reason): ONE exec of the mysql client in the
    version's mysql container, nothing else. The reason names no path and quotes no docker text."""
    try:
        argv, env = _mysql_cmd(version, PLAYER_DB)
        r = _run_capped(argv + ["-N", "-B", "-e", accounts_characters_sql()], timeout=timeout, env=env)
    except Exception:  # noqa: BLE001 -- no root password in .env, a folder that went away
        return None, "The game database could not be read."
    if r.returncode != 0:
        if _accounts_timed_out(r):
            return None, "The game database did not answer within %d s." % int(round(timeout))
        dropped = _password_dropped(env, r)
        return None, ("The game database could not be read (%s)." % password_dropped_text(dropped) if dropped
                      else "The game database could not be read.")
    try:
        return parse_accounts_characters(r.stdout), None
    except ValueError:
        return None, "The game database gave an answer the agent could not read."


def _accounts_read_presence(version, timeout):
    """(the uids with a presence key, None) -- or (None, a short reason): ONE `redis-cli --scan` of db 7 in the
    version's redis container, the password in REDISCLI_AUTH (_exec_args: never on an argv, redis-cli's or
    docker's)."""
    try:
        pw = redis_password(version)
        args, env = _exec_args("redis", ["redis-cli", "-n", "7", "--scan", "--pattern", "PlayerStatus:*"],
                               {"REDISCLI_AUTH": pw} if pw else None)
        r = _run_capped(["docker", "compose", "--project-directory", stack_dir(version)] + args, timeout=timeout,
                        env=env)
    except Exception:  # noqa: BLE001
        return None, "Redis could not be read -- who is online is not known."
    dropped = _password_dropped(env, r)
    if dropped:
        return None, "Redis could not be read (%s) -- who is online is not known." % password_dropped_text(dropped)
    if r.returncode != 0:
        if _accounts_timed_out(r):
            return None, "Redis did not answer within %d s -- who is online is not known." % int(round(timeout))
        return None, "Redis could not be read -- who is online is not known."
    try:
        return parse_presence_scan(r.stdout), None
    except ValueError:
        return None, "Redis gave an answer the agent could not read -- who is online is not known."


def _accounts_blocking_job():
    """A running job that has the stack between two states (not one of ACCOUNTS_READ_BESIDE, nor a navmesh /
    navdata job while it only downloads), else None."""
    with _jobs_lock:
        for reg, order in ((JOBS, JOBS_ORDER), (PUBLIC_JOBS, PUBLIC_JOBS_ORDER)):
            for jid in reversed(order):
                j = reg.get(jid)
                if j is not None and j.state == "running" and j.kind not in ACCOUNTS_READ_BESIDE \
                        and not (j.kind in ("navmesh", "navdata") and j.yielding):
                    return j
    return None


def signup_book_all_names(data, version):
    """Every name the signup book of `version` holds for its current generation, whichever launcher created it
    -- lower-cased, from a loaded state. The book's keys (a launcher's id, an address) never leave it. Pure."""
    books = data.get("signupClients") if isinstance(data, dict) else None
    book = books.get(version) if isinstance(books, dict) else None
    if not isinstance(book, dict) or book.get("gen") != _signup_gen(data, version) \
            or not isinstance(book.get("clients"), dict):
        return set()
    return {n.lower() for names in book["clients"].values() if isinstance(names, list)
            for n in names if isinstance(n, str)}


def _accounts_origin_facts(version):
    """What the origin hints of one list read rest on (account_origin), read once. Every part is tolerant: a
    fact nothing can tell is no hint, never a failed list."""
    facts = {"account": "", "defaultHolds": None, "payload": set(), "published": False, "signups": set()}
    try:
        st = load_state()
    except StateUnreadable:
        st = {}
    vs = (st.get("versions") or {}).get(version) or {}
    if "defaultAccount" in vs:
        facts["defaultHolds"] = bool(vs.get("defaultAccount"))
    else:
        try:
            marker = read_provisioned_marker(version)
        except Exception:  # noqa: BLE001
            marker = None
        facts["defaultHolds"] = marker["defaultAccount"] if marker else None
    try:
        man = read_manifest(version)
    except Exception:  # noqa: BLE001
        man = None
    facts["account"] = str((man or {}).get("account") or "")
    if facts["defaultHolds"] is not False:
        for item in _manifest_files(man):
            if effective_stage(item) == "save" and item.get("src") \
                    and str(item.get("dst", "")).replace("\\", "/") == "sdk/data/sdk.db":
                try:
                    accts, _last = read_sqlite_copy(os.path.join(payload_dir(version), str(item["src"])),
                                                    _sdk_accounts_read)
                    facts["payload"] = {(a[0], a[1]) for a in accts}
                except Exception:  # noqa: BLE001
                    pass
                break
    facts["published"] = sdk_db_published(version)
    facts["signups"] = signup_book_all_names(st, version)
    return facts


def account_origin(sdk_uid, name, made_here, facts):
    """Where one account of the list comes from -- a HINT for the admin's eyes, never a permission (the e-mail it
    partly rests on can be typed on the vendor's register page by anyone):
      default -- the version's pre-made account (the manifest's `account`, any case) while the shipped save is
                 in this database (the record's defaultAccount, else the provision marker; unknown counts);
      package -- an account the server package or the shipped save came with: the stack's sdk.db is still, byte
                 for byte, the file its package is published with -- or, while the shipped save is in this
                 database, the account is one of that save's sdk.db (same uid, same name);
      signup  -- registered through this agent (the e-mail its register call makes up) and named in the signup
                 book of the version's current generation, whichever launcher created it;
      relic   -- registered through this agent otherwise: an admin's creation, a target a copy created, a signup
                 whose book is gone (a reset state, another generation);
      other   -- everything else: the vendor's register page, a guest, a package nothing here knows.
    `facts` = _accounts_origin_facts(). Pure."""
    low = name.lower() if isinstance(name, str) else None
    holds = facts.get("defaultHolds") is not False
    if made_here:
        return "signup" if low is not None and low in facts.get("signups", ()) else "relic"
    if holds and low is not None and facts.get("account") and low == facts["account"].lower():
        return "default"
    if facts.get("published") or (holds and (sdk_uid, name) in facts.get("payload", ())):
        return "package"
    return "other"


def accounts_preflight(query):
    """GET /server/accounts' query string -> (version, after, limit, q). Every refusal is a 400 that names the
    parameter -- never a 404 (that means "an agent without this route" to the launcher): an unknown version, a
    parameter given twice, `after` that is no whole number of 0 or more, `limit` outside 1..ACCOUNTS_LIMIT_MAX,
    `q` longer than ACCOUNTS_QUERY_MAX characters or with a control character. An empty parameter is an absent
    one (`limit` then ACCOUNTS_LIMIT_DEFAULT); any other parameter is passed over."""
    got = {}
    for k, v in urllib.parse.parse_qsl(query or "", keep_blank_values=True):
        if k in got:
            raise AgentError(400, "%s is given more than once" % k)
        got[k] = v
    version = got.get("version", "").strip()
    check_known(version)
    after = got.get("after", "").strip()
    if after and (not _DIGITS_RE.fullmatch(after) or len(after) > 18):
        raise AgentError(400, "after must be a whole number of 0 or more (the sdk uid the previous page ended at)")
    limit = got.get("limit", "").strip()
    if limit and (not _DIGITS_RE.fullmatch(limit) or len(limit) > 4 or not 1 <= int(limit) <= ACCOUNTS_LIMIT_MAX):
        raise AgentError(400, "limit must be a whole number from 1 to %d" % ACCOUNTS_LIMIT_MAX)
    q = got.get("q", "")
    if len(q) > ACCOUNTS_QUERY_MAX:
        raise AgentError(400, "q must be at most %d characters" % ACCOUNTS_QUERY_MAX)
    problem = plain_line_problem(q)
    if problem:
        raise AgentError(400, "q %s" % problem)
    return version, int(after or 0), int(limit or ACCOUNTS_LIMIT_DEFAULT), q.strip()


def accounts_list(version, after=0, limit=ACCOUNTS_LIMIT_DEFAULT, q=""):
    """GET /server/accounts: one page of the accounts of `version` -- sdk uid ascending, those after `after`,
    at most `limit`, only those whose login name holds `q` (any case) or, while the characters are known, whose
    nickname does. Everything is read anew (no cache) and the version's state is never changed.

    The answer: version; running (the version's compose project runs -- false also when docker did not say);
    asOf (the box's clock, ISO-8601 UTC -- every time of the answer is one, null when unknown); total = the
    version's logins, matched = those `q` keeps (both over every page);
    withCharacter = logins whose game uid holds a save, online = logins whose game uid has a presence key (null
    when that source is not ok); characters / presence = ok | stopped (the version does not run -- logins only)
    | error, with `reason` (a short sentence that names no path and quotes no docker text) while either is not
    ok; next = the sdk uid to pass as `after` for the next page, null on the last; accounts = the page's rows:
    name (null for a guest), sdkUid, guest, created, lastLogin (the sdk's last combo login), uid (the game uid:
    the t_player_uid row of the account's sdk uid -- the one of its own account type, else the lowest),
    uidCreated (when that uid was allocated -- an allocation may come before the first login), nickname, level
    (= the adventure rank), lastSave, online, presenceStale (online with no save for ACCOUNTS_STALE_AFTER
    seconds: advisory only), origin (account_origin: a hint). Game fields are null while the characters are
    not ok or the account has no such row; online / presenceStale are null while who is online is not known.

    Raises AgentError: 400 unknown version, 409 no stack of the version on this server / another read under
    way past ACCOUNTS_LOCK_WAIT, 500 when the logins cannot be read (no path in the text) -- never a 404:
    a version's folder cleared under the read (a repoint to none) is the 409 as well."""
    t0 = time.time()
    check_known(version)
    not_here = "Version %s is not installed on this server." % version
    if not is_configured(version) or not is_present(version):
        raise AgentError(409, not_here)
    if not _ACCOUNTS_LOCK.acquire(timeout=ACCOUNTS_LOCK_WAIT):
        raise AgentError(409, "The account list is being read for another request -- try again in a moment.")
    try:
        return _accounts_page(version, after, limit, q, t0)
    except AgentError as e:
        if e.status == 404:
            raise AgentError(409, not_here)
        raise
    except Exception as e:  # noqa: BLE001 -- no path, no name: the type of the failure is all the log gets
        log_line("gio-agent: the account list of version %s could not be read (%s)." % (version, type(e).__name__))
        raise AgentError(500, "The account list of version %s could not be read." % version)
    finally:
        _ACCOUNTS_LOCK.release()


def _accounts_page(version, after, limit, q, t0):
    """accounts_list's work, under its lock."""
    try:
        logins, last_login = read_sqlite_copy(_sdk_db_path(version), _sdk_accounts_read)
    except FileNotFoundError:
        logins, last_login = [], {}  # no sdk.db yet: the sdk creates it, empty, when it first runs
    except _SdkDbUnreadable as e:
        raise AgentError(500, "The account database of version %s could not be read (%s) -- try again."
                         % (version, e))
    except OSError:
        raise AgentError(500, "The account database of version %s could not be read (it cannot be opened) -- "
                              "try again." % version)

    def budget(cap):
        left = min(cap, ACCOUNTS_BUDGET - (time.time() - t0))
        return left if left >= 1 else None

    chars = presence = reason = None
    t = budget(ACCOUNTS_T_LS)
    running = _accounts_running(version, t) if t else None
    if running is None:
        chars_state = "error"
        reason = ("Docker did not answer -- the characters and who is online are not known." if t
                  else "There was no time left to ask docker whether the version runs.")
    elif not running:
        chars_state = "stopped"
        reason = ("Version %s is not running." if is_bootstrapped(version)
                  else "Version %s is not prepared on this server yet.") % version
    else:
        busy = _accounts_blocking_job()
        t = budget(ACCOUNTS_T_MYSQL)
        if busy is not None:
            reason = ("A %s job is running -- the characters and who is online can be read once it has ended."
                      % busy.kind)
        elif t is None:
            reason = "There was no time left to read the game database."
        else:
            chars, reason = _accounts_read_characters(version, t)
        chars_state = "ok" if chars is not None else "error"
    presence_state = chars_state
    if chars is not None:
        t = budget(ACCOUNTS_T_REDIS)
        if t is None:
            reason = "There was no time left to ask redis who is online."
        else:
            presence, reason = _accounts_read_presence(version, t)
        presence_state = "ok" if presence is not None else "error"

    by_account = {}
    for row in chars or ():
        acct = row["account"]
        if acct is not None and _DIGITS_RE.fullmatch(acct) and len(acct) <= 18:
            by_account.setdefault(int(acct), []).append(row)
    facts = _accounts_origin_facts(version)
    rows = []
    with_char = online_n = 0
    for sdk_uid, name, typ, created, made_here in sorted(logins, key=lambda a: a[0]):
        cands = by_account.get(sdk_uid) or []
        game = next((c for c in cands if typ is not None and c["type"] == typ), None) \
            or (min(cands, key=lambda c: c["uid"]) if cands else None)
        row = {"name": name, "sdkUid": sdk_uid, "guest": typ == 0, "created": _iso_utc(created),
               "lastLogin": _iso_utc(last_login.get(sdk_uid)),
               "uid": game["uid"] if game else None,
               "uidCreated": _iso_utc(game["created"]) if game else None,
               "nickname": game["nickname"] if game else None,
               "level": game["level"] if game else None,
               "lastSave": _iso_utc(game["saved"]) if game else None,
               "online": None, "presenceStale": None,
               "origin": account_origin(sdk_uid, name, made_here, facts)}
        if game is not None and game["level"] is not None:
            with_char += 1
        if presence is not None:
            row["online"] = game is not None and game["uid"] in presence
            row["presenceStale"] = row["online"] and game["age"] is not None and game["age"] >= ACCOUNTS_STALE_AFTER
            online_n += row["online"]
        rows.append(row)

    needle = q.casefold()

    def kept(row):
        return not needle or (row["name"] is not None and needle in row["name"].casefold()) or (
            chars is not None and row["nickname"] is not None and needle in row["nickname"].casefold())

    hits = [row for row in rows if kept(row)]
    rest = [row for row in hits if row["sdkUid"] > after]
    page = rest[:limit]
    out = {"version": version, "running": running is True,
           "asOf": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
           "total": len(rows), "matched": len(hits),
           "withCharacter": with_char if chars is not None else None,
           "online": online_n if presence is not None else None,
           "characters": chars_state, "presence": presence_state,
           "next": page[-1]["sdkUid"] if len(rest) > limit else None,
           "accounts": page}
    if reason and (chars_state != "ok" or presence_state != "ok"):
        out["reason"] = reason
    return out


# -- admin policy (what players may do without a token) --

MAX_PER_PLAYER_DEFAULT = 5  # accounts one launcher may create per version
MAX_PER_PLAYER_MAX = 1000


def default_version_policy(v):
    """A version's signup defaults: every starting point the manifest ships -- the new account first,
    then the templates in manifest order -- 50 accounts a
    day server-wide, MAX_PER_PLAYER_DEFAULT per launcher. A template that is not imported on the
    stack is not among the choices of /public/status (build_public_status names it under notReady),
    so allowing it costs nothing."""
    return {"templates": ["fresh"] + [t["id"] for t in manifest_templates(v) if t["id"] != "fresh"],
            "maxPerDay": 50, "maxPerPlayer": MAX_PER_PLAYER_DEFAULT}


def default_policy():
    # Player signup and player GM commands are ON by default: a friends server works out
    # of the box; the admin turns either off from the Player accounts card. A stored policy
    # (set_policy persists it: policy_to_store) keeps its own values across upgrades -- a key it does
    # not hold (maxPerPlayer in a record without it, the entry of a version nothing was decided
    # about) takes the default.
    return {
        "name": "",
        "signup": {"enabled": True,
                   "versions": {v: default_version_policy(v) for v in VERSIONS}},
        "playerCommands": True,
        # Open administration: every player who reaches the agent enters Server Admin mode with the
        # key /public/admin/key hands out. Off by default -- the admin opens it from the Server page.
        "openAdmin": False,
        # A /hotpatch/<path> miss under a known branch may be fetched from the manifest's upstreams once
        # (GIO_HOTPATCH_UPSTREAM=0 in the environment overrides this to off).
        "hotpatchUpstream": True,
        # Where the mirror is filled FROM: the archive.org bundles (default) or the manifest's
        # upstreams, file by file. Seeded from GIO_HOTPATCH_SOURCE; changed from the launcher at any time.
        "hotpatchSource": HOTPATCH_SOURCE,
    }


def merge_policy(current, partial, allowed_templates, stored=False):
    """current (full) + partial (anything the admin sent) -> a new full policy, validated.
    `allowed_templates` maps version -> template ids the manifest provides ('fresh' is always
    allowed). `openAdmin` is honoured only when it is the only key of the request: a save of the
    whole policy that still names it is refused, so a stale copy of the flag can never switch the
    option -- and make or delete its key -- without the admin asking for that. `stored=True` is the
    re-validation of the policy as the state file holds it, every key beside the flag, where that
    rule does not apply. Pure; raises AgentError(400) on invalid input."""
    if not isinstance(partial, dict):
        raise AgentError(400, "policy must be a JSON object")
    out = json.loads(json.dumps(current))  # deep copy
    if "name" in partial:
        name = partial["name"]
        if name is None:
            name = ""
        if not isinstance(name, str) or len(name) > 64:
            raise AgentError(400, "policy.name must be a string of at most 64 characters")
        out["name"] = name.strip()
    if "playerCommands" in partial:
        if not isinstance(partial["playerCommands"], bool):
            raise AgentError(400, "policy.playerCommands must be true or false")
        out["playerCommands"] = partial["playerCommands"]
    if "openAdmin" in partial:
        if not stored and len(partial) > 1:
            raise AgentError(400, "policy.openAdmin must be sent on its own -- a full policy save never changes it")
        if not isinstance(partial["openAdmin"], bool):
            raise AgentError(400, "policy.openAdmin must be true or false")
        out["openAdmin"] = partial["openAdmin"]
    if "hotpatchUpstream" in partial:
        if not isinstance(partial["hotpatchUpstream"], bool):
            raise AgentError(400, "policy.hotpatchUpstream must be true or false")
        out["hotpatchUpstream"] = partial["hotpatchUpstream"]
    if "hotpatchSource" in partial:
        src = partial["hotpatchSource"]
        if not isinstance(src, str) or src.strip().lower() not in HOTPATCH_SOURCES:
            raise AgentError(400, "policy.hotpatchSource must be one of %s" % ", ".join(HOTPATCH_SOURCES))
        out["hotpatchSource"] = src.strip().lower()
    signup = partial.get("signup")
    if signup is not None:
        if not isinstance(signup, dict):
            raise AgentError(400, "policy.signup must be an object")
        if "enabled" in signup:
            if not isinstance(signup["enabled"], bool):
                raise AgentError(400, "policy.signup.enabled must be true or false")
            out["signup"]["enabled"] = signup["enabled"]
        versions = signup.get("versions")
        if versions is not None:
            if not isinstance(versions, dict):
                raise AgentError(400, "policy.signup.versions must be an object")
            for v, vp in versions.items():
                if v not in VERSIONS:
                    raise AgentError(400, "unknown version in policy: %s" % v)
                if not isinstance(vp, dict):
                    raise AgentError(400, "policy.signup.versions.%s must be an object" % v)
                cur = out["signup"]["versions"].setdefault(
                    v, {"templates": ["fresh"], "maxPerDay": 50, "maxPerPlayer": MAX_PER_PLAYER_DEFAULT})
                if "templates" in vp:
                    tpls = vp["templates"]
                    if not isinstance(tpls, list) or not all(isinstance(t, str) for t in tpls):
                        raise AgentError(400, "templates must be a list of ids")
                    ok = set(allowed_templates.get(v) or []) | {"fresh"}
                    bad = [t for t in tpls if t not in ok]
                    if bad:
                        raise AgentError(400, "unknown template(s) for %s: %s" % (v, ", ".join(bad)))
                    seen = []
                    for t in tpls:
                        if t not in seen:
                            seen.append(t)
                    cur["templates"] = seen
                if "maxPerDay" in vp:
                    m = vp["maxPerDay"]
                    if isinstance(m, bool) or not isinstance(m, int) or m < 0 or m > 100000:
                        raise AgentError(400, "maxPerDay must be an integer between 0 and 100000")
                    cur["maxPerDay"] = m
                if "maxPerPlayer" in vp:
                    m = vp["maxPerPlayer"]
                    if isinstance(m, bool) or not isinstance(m, int) or m < 0 or m > MAX_PER_PLAYER_MAX:
                        raise AgentError(400, "maxPerPlayer must be an integer between 0 and %d"
                                         % MAX_PER_PLAYER_MAX)
                    cur["maxPerPlayer"] = m
    return out


def get_policy():
    base = default_policy()
    try:
        saved = load_state().get("policy")
    except StateUnreadable:
        # Fail closed while the admin's choices cannot be read: the admin may have switched signup
        # or player commands OFF, so neither is offered until the file reads again (the public
        # routes read this directly, not only the state_ok-ANDed /public/status); the on-demand
        # upstream fetch is switched off too.
        base["signup"]["enabled"] = False
        base["playerCommands"] = False
        base["openAdmin"] = False
        base["hotpatchUpstream"] = False
        return base
    return policy_of_saved(saved)


def policy_of_saved(saved):
    """get_policy's answer for a state file that reads, whose `policy` key holds `saved` (anything): the stored
    object as _policy_current applies it against the template ids each manifest provides, the defaults when there
    is none. The token-less route works its on-demand switch out of the same (route_switches_of)."""
    if isinstance(saved, dict):
        allowed = {v: [t["id"] for t in manifest_templates(v)] for v in VERSIONS}
        return _policy_current(saved, allowed)
    return default_policy()


def _policy_current(saved, allowed):
    """The policy as the agent applies it, from the `policy` object a readable state holds (`saved`,
    anything) and the template ids each manifest provides (`allowed`): the defaults for a state
    without one, else the stored object re-validated. A manifest that lost a template id (redeployed
    payloads, a box without the payload folder) must not brick the policy -- but it must not silently
    REOPEN the server either: the defaults say signup + player commands are ON, so falling back to
    them would re-enable exactly what the admin switched off. So the stored object is retried with
    only the part that cannot be validated dropped (the template lists), and the policy fails closed
    only when even that is refused. The ONE base of the read (get_policy) and of the write
    (set_policy): a save over such a record keeps every stored choice -- open administration and its
    key included -- exactly as a read does."""
    base = default_policy()
    if not isinstance(saved, dict):
        return base
    try:
        return merge_policy(base, saved, allowed, stored=True)
    except AgentError as first:
        safe = json.loads(json.dumps(saved))
        for vp in ((safe.get("signup") or {}).get("versions") or {}).values():
            if isinstance(vp, dict):
                vp.pop("templates", None)
        try:
            out = merge_policy(base, safe, allowed, stored=True)
            log_line("policy: the stored template list was refused (%s) -- keeping every other "
                     "stored choice and offering 'fresh' only." % first)
            return out
        except AgentError as e:
            log_line("policy: the stored policy cannot be applied (%s) -- signups and player "
                     "commands stay OFF until it is fixed." % e)
            base["signup"]["enabled"] = False
            base["playerCommands"] = False
            base["openAdmin"] = False
            return base


def policy_to_store(policy):
    """The policy as the state file keeps it: the full object without the signup entry of a version that
    is not configured on this box while that entry is the default one -- nobody decided anything
    about it, and a read fills a missing entry from the defaults (_policy_current). An agent that does
    not know a version refuses a stored policy that names it and fails closed, so a box that never had
    a version must not carry its key. A configured version's entry, and any entry that differs from
    the default, is a choice and is kept as it is. Returns a copy."""
    out = json.loads(json.dumps(policy))
    versions = (out.get("signup") or {}).get("versions")
    if isinstance(versions, dict):
        for v in [v for v, vp in versions.items() if not is_configured(v) and vp == default_version_policy(v)]:
            del versions[v]
    return out


def set_policy(partial):
    allowed = {v: [t["id"] for t in manifest_templates(v)] for v in VERSIONS}
    with _state_lock:
        try:
            data = load_state()
        except StateUnreadable:
            raise state_unreadable_error()
        # The base is the policy as a READ applies it: a stored choice a read keeps past a template
        # list the manifest does not list is kept by the write too, never taken from the defaults.
        current = _policy_current(data.get("policy"), allowed)
        new = merge_policy(current, partial, allowed)
        # Open administration: the key /public/admin/key hands out is a top-level record beside the
        # policy, never inside it (the policy object travels in /status and the policy answers). Made
        # at a real off -> on of the flag -- never kept from an earlier record: a stale key must not be
        # re-armed --, deleted whenever the saved flag is off (on -> off revokes every launcher that
        # entered with it at once; a key stored beside a flag that is off goes too, so the file never
        # holds one the option does not vouch for) and left alone while the option stays on: a lone
        # re-post of the same value keeps the key (a new one there would throw every open
        # administrator out), and a save of the whole policy never names the flag (merge_policy
        # refuses one that does).
        was_open, is_open = bool(current.get("openAdmin")), bool(new.get("openAdmin"))
        if is_open and not was_open:
            data["openAdminToken"] = secrets.token_hex(24)
        elif not is_open:
            data.pop("openAdminToken", None)
        data["policy"] = policy_to_store(new)
        # strict: the save IS the operation -- answering the new policy for a write that failed
        # would show the admin a setting the next agent restart silently takes back.
        save_state(data, strict=True)
        # The key in memory follows the file only once the file holds it: a failed save (raised above)
        # leaves memory as it was, consistent with the file.
        _OPEN_ADMIN["key"] = _open_admin_key_from(data)
    _invalidate_public_status()
    if is_open != was_open:
        log_line("policy: open administration switched %s" % ("on" if is_open else "off"))
    return new


# The open admin key, in memory. The bearer check runs on every request, so it stays pure: a token-less
# caller must not make the agent read and parse the state file and the payload manifests at every call
# (unthrottled, and on Windows those readers contend with the state file's replace). The record follows
# the file at every write that can change it (set_policy, reset_state) and is loaded once at the agent's
# start -- so a key already handed out keeps working while the file cannot be read: the option is a
# choice the process made, an unreadable file is not a new choice.
_OPEN_ADMIN = {"key": ""}


def _open_admin_key_from(data):
    """The open admin key a state object holds, else "": the policy's `openAdmin` must be True and
    `openAdminToken` a non-empty string (a missing, empty or malformed record reads as none). Pure."""
    if not isinstance(data, dict):
        return ""
    pol = data.get("policy")
    if not isinstance(pol, dict) or pol.get("openAdmin") is not True:
        return ""
    key = data.get("openAdminToken")
    return key if isinstance(key, str) and key else ""


def load_open_admin_key():
    """main(), once, right after recover_state_at_startup(): the key the state file holds goes into
    memory -- only while the policy as the agent applies it (_policy_current, the verdict every read
    gives) says the option is on: a key beside a stored policy that is refused whole would open every
    admin endpoint while the option reads as off everywhere. Any failure -- an unreadable file
    included -- loads none (fail closed at the start) and is said once. Returns what is in memory
    afterwards."""
    try:
        data = load_state()
        allowed = {v: [t["id"] for t in manifest_templates(v)] for v in VERSIONS}
        on = _policy_current(data.get("policy"), allowed).get("openAdmin") is True
        _OPEN_ADMIN["key"] = _open_admin_key_from(data) if on else ""
    except Exception as e:  # noqa: BLE001
        _OPEN_ADMIN["key"] = ""
        log_line("gio-agent: open administration: the stored key could not be loaded (%s) -- no key is "
                 "handed out until the option is switched on again" % getattr(e, "reason", e))
    return _OPEN_ADMIN["key"]


def open_admin_key():
    """The key that opens every admin endpoint while policy.openAdmin is on, else "". Memory only:
    no I/O, cannot raise (the bearer check calls it on the handler thread, before any try block)."""
    return _OPEN_ADMIN["key"]


# -- /public/status: a cached, minimal snapshot (never a docker call per request) --

PUBLIC_STATUS_TTL = 10
_public_cache = {"at": 0.0, "data": None, "gen": 0}
_public_lock = threading.Lock()


def _invalidate_public_status():
    # gen: a refresh that was already building when this ran (it read the OLD policy) must not
    # file its snapshot as fresh -- players would be shown the previous policy for another 10 s.
    _public_cache["gen"] += 1
    _public_cache["at"] = 0.0


def build_public_status(full, policy):
    """Project the admin status + policy onto what a token-less player may see. Pure."""
    # An unreadable state file: no generation (null = "unknown" to the launcher, never "changed")
    # and no signup, whatever policy object was passed in.
    state_ok = (full.get("state") or {}).get("ok", True)
    out = {"ok": True, "agent": AGENT_VERSION.split(".")[0],
           "name": policy.get("name") or SERVER_NAME,
           "platform": full.get("platform"),
           "versions": {}, "signup": {"enabled": bool(policy["signup"]["enabled"]) and state_ok, "versions": {},
                                      "notReady": {}},
           "playerCommands": bool(policy.get("playerCommands")) and state_ok,
           # the launcher offers "Enter admin mode" on this flag; the key itself is never here
           "openAdmin": bool(policy.get("openAdmin")) and state_ok}
    # docker compose ls failed / timed out: every up:false below is fabricated. A fixed flag, never the
    # raw error text (docker output stays off the token-less endpoint); the per-version fields keep
    # their shape for launchers that do not know it, and present stays true to fact (a filesystem check).
    if full.get("error"):
        out["statusUnknown"] = True
    for v, entry in (full.get("versions") or {}).items():
        if not entry.get("present"):
            out["versions"][v] = {"present": False}
            continue
        out["versions"][v] = {
            "present": True,
            "up": bool(entry.get("up")),
            "healthy": entry.get("healthy") if entry.get("up") else False,
            "defaultAccount": entry.get("account") or "",
            "passwordVerify": bool(entry.get("passwordVerify")),
            "generation": entry.get("provisionedAt"),
        }
        # The game server of the version that is up has not finished loading its data: a client that
        # connects is turned away until it has. Said only while it is known to be so -- the key is absent
        # otherwise, so the entry keeps its shape for a launcher that does not know it.
        if entry.get("up") and entry.get("loading") is True:
            out["versions"][v]["loading"] = True
        hp = entry.get("hotpatch") or {}
        if hp.get("available"):
            # Enough for the launcher's "official fixes served here" badge; the revisions are
            # public knowledge (the client sends them to every dispatch), never a path or an IP.
            # "enabled" here means ADVERTISED: an enabled-but-pending mirror (database half owed,
            # or an unusable URL) serves nobody yet and must not be announced to players.
            out["versions"][v]["hotpatch"] = {"enabled": bool(hp.get("enabled")) and not bool(hp.get("pending")),
                                              "res": hp.get("res"), "data": hp.get("data"),
                                              "silence": hp.get("silence"),
                                              # voice languages whose base packs the mirror serves (names)
                                              "voice": list(hp.get("voice") or [])}
        vp = (policy["signup"]["versions"] or {}).get(v)
        if vp is not None and entry.get("present"):
            labels = {t["id"]: t["label"] for t in manifest_templates(v)}
            labels["fresh"] = "New account"
            # A progress template is offered only once it is imported on THIS stack (the
            # template_ready test, read from the status entry's record so this stays pure) -- one
            # the policy lists but the stack lacks would only ever answer template_not_ready on Create.
            recs = entry.get("templates") or {}
            offered = [{"id": t, "label": labels.get(t, t)} for t in vp.get("templates", [])
                       if t == "fresh" or template_record_ready(recs.get(t))]
            # An empty list is left out, never published: launchers read a missing version as "no
            # signup here", while an empty one crashes a launcher whose account card reads templates[0]
            # unguarded (a policy without 'fresh' whose templates are not imported yet, or an
            # explicit `templates: []`).
            if offered:
                # maxPerPlayer: how many accounts one launcher may create on this version
                # -- the launcher shows "2 of 5" from its own list; the agent enforces it.
                out["signup"]["versions"][v] = {"templates": offered, "maxPerDay": vp.get("maxPerDay", 50),
                                                "maxPerPlayer": vp.get("maxPerPlayer", MAX_PER_PLAYER_DEFAULT)}
            # The rest of the policy's list -- allowed, but not imported on this stack -- goes out in a
            # list of its own, id + label only: the launcher draws those greyed with the reason, so a
            # player sees what the admin opened instead of a choice that silently is not there. Only
            # what the manifest ships: an id it does not name can never be imported. Kept apart from
            # `templates`, which stays "what Create accepts" for a launcher that reads nothing else.
            # Nothing is named while the state file is unreadable: neither the admin's list nor the
            # import records are known then.
            waiting = [{"id": t, "label": labels[t]} for t in vp.get("templates", [])
                       if t != "fresh" and t in labels and not template_record_ready(recs.get(t))]
            if waiting and state_ok:
                out["signup"]["notReady"][v] = waiting
    return out


def public_status():
    """The cached snapshot. Refreshed lazily, at most every PUBLIC_STATUS_TTL seconds, by one
    caller at a time; everyone else gets the last snapshot (a stale 10 s view beats a docker
    call per request -- /public/status is what every player's launcher polls)."""
    now = time.time()
    data = _public_cache["data"]
    if data is not None and now - _public_cache["at"] < PUBLIC_STATUS_TTL:
        return data
    if not _public_lock.acquire(blocking=data is None):
        return data  # someone else is refreshing; serve the previous snapshot meanwhile
    try:
        if _public_cache["data"] is not None and time.time() - _public_cache["at"] < PUBLIC_STATUS_TTL:
            return _public_cache["data"]
        gen = _public_cache["gen"]
        fresh = build_public_status(status(), get_policy())
        # Invalidated while it was being built: served to this caller, but left stale for the next.
        _public_cache["data"], _public_cache["at"] = fresh, (time.time() if gen == _public_cache["gen"] else 0.0)
        return fresh
    finally:
        _public_lock.release()


# -- rate limiting (token buckets per client IP, LRU-bounded) --

class RateLimiter:
    def __init__(self, cap=10000):
        self._buckets = OrderedDict()
        self._lock = threading.Lock()
        self.cap = cap

    @staticmethod
    def _rule(rule):
        """(key, limit, per[, code]) -> (key, limit, per, code)."""
        return rule[0], rule[1], rule[2], (rule[3] if len(rule) > 3 else None)

    def _level(self, key, limit, per, now):
        """Caller holds the lock. The bucket's tokens refilled up to `now` (a new bucket is full)."""
        tokens, last = self._buckets.get(key, (float(limit), now))
        return min(float(limit), tokens + max(0.0, now - last) * limit / float(per))

    def _evict(self):
        """Caller holds the lock."""
        while len(self._buckets) > self.cap:
            # LRU-evict per-address buckets only: a global quota ("create-d:*") must not be
            # reset by a caller churning through thousands of source addresses.
            victim = next((k for k in self._buckets if "*" not in k), None)
            if victim is None:
                break
            del self._buckets[victim]

    def take(self, key, limit, per, now=None):
        """Take one token from bucket `key` (capacity `limit`, refilled evenly over `per`
        seconds). Returns (allowed, retry_after_seconds). A refused call consumes nothing."""
        ok, wait, _code = self.take_all([(key, limit, per)], now=now)
        return ok, wait

    def take_all(self, rules, now=None):
        """All or nothing over rules = [(key, limit, per[, code]), ...]: when every bucket holds a
        token, take one from each and return (True, 0, None); otherwise take from NONE and return
        (False, wait, code) of the refusing bucket with the longest wait. A drained global bucket
        must not also burn the caller's own per-address tokens on every refused attempt."""
        now = time.time() if now is None else now
        rules = [self._rule(r) for r in rules]
        with self._lock:
            refusal, levels = None, []
            for key, limit, per, code in rules:
                if limit <= 0:
                    wait = int(per)  # a zero quota (maxPerDay=0) never admits anyone
                else:
                    tokens = self._level(key, limit, per, now)
                    levels.append((key, tokens))
                    if tokens >= 1.0:
                        continue
                    wait = max(1, int((1.0 - tokens) * per / float(limit) + 0.999))
                if refusal is None or wait > refusal[0]:
                    refusal = (wait, code)
            if refusal is not None:
                for key, _tokens in levels:
                    if key in self._buckets:
                        self._buckets.move_to_end(key)  # recency only: a refused caller stays tracked
                return False, refusal[0], refusal[1]
            for key, tokens in levels:
                self._buckets.pop(key, None)
                self._buckets[key] = (tokens - 1.0, now)
            self._evict()
            return True, 0, None

    def give(self, rules, now=None):
        """Hand back the tokens a successful take_all(rules) took, for work that then never ran:
        +1 per bucket, never above its limit. A bucket that is gone (LRU-evicted) already starts
        full again -- nothing to give back to."""
        now = time.time() if now is None else now
        with self._lock:
            for key, limit, per, _code in (self._rule(r) for r in rules):
                if limit <= 0 or key not in self._buckets:
                    continue
                self._buckets[key] = (min(float(limit), self._level(key, limit, per, now) + 1.0), now)


LIMITER = RateLimiter()
# The token-less mirror has its own limiter: at 600 hits/min per address it is the cheapest way to
# churn buckets, and it must never share an LRU with the signup quotas.
HOTPATCH_LIMITER = RateLimiter(cap=4096)


def enforce_limits(rules, limiter=None):
    """rules = [(key, limit, per_seconds[, code]), ...], all or nothing (RateLimiter.take_all): a
    refusal spends no bucket and raises 429 with the longest wait and that rule's public code."""
    ok, wait, code = (limiter or LIMITER).take_all(rules)
    if not ok:
        raise AgentError(429, "too many requests, try again later", retry_after=wait, code=code)


# -- moving progress to another version (migration): the request, the reader, the check --
# POST /server/migrate moves accounts of a server of another version on this box -- or of another server of the same
# version, kept in a folder -- one at a time into the target, which keeps running for its players. The source is only
# ever READ and never through its compose project: a throwaway MariaDB (no network, no port, nothing pulled) opens a
# COPY of its mysql/, in a volume of its own, made through a read-only mount while no container of the source exists and
# while the size and time of every file below mysql/ stay what they were. All of it carries the label
# relic.migrate=<job> and goes on every exit path; what a killed agent left goes after its next start (migrate_sweep).
# The source phase yields the whole time, without _op_lock: the watchdogs' jobs and the signups run beside it, admin jobs
# wait. A check (dryRun) ends there: nothing registered, allocated or written on the target, the source unchanged.

MIGRATE_ACCOUNTS_MAX = 100  # the accounts a request names, and the accounts with a save one check reads
MIGRATE_LIST_MAX = 2000     # the entries one result holds
MIGRATE_IDS_MAX = 32        # the ids one list of an entry holds
# One answer of the reader: it is held in memory, hex-decoded and parsed beside a running target. Saves are far smaller.
MIGRATE_READ_MAX = 32 << 20
MIGRATE_ERR_MAX = 1 << 20   # what is kept of a docker call's stderr
# The reader's limit (--memory = --memory-swap) and what must stay available beside it.
MIGRATE_READER_MEMORY = 512 << 20
MIGRATE_MEMORY_RESERVE = 1 << 30
MIGRATE_BACKUPS_ROOM = 256 << 20  # the room a real run's backups need beside the state file
MIGRATE_STAMP_MAX = 200000  # the entries a stamp of the source's database folder takes
MIGRATE_RECENT_SAVE = 180   # a save younger than this many seconds: copy_save's own gate, the longest save gap
MIGRATE_RACE_WAIT = 10      # seconds from the last write of a real run to its look at who entered the game meanwhile
T_MIGRATE_DOCKER = 60       # ps / inspect / image / volume / rm / the probe
T_MIGRATE_COPY = 1800       # the copy of the source's mysql/
T_MIGRATE_READY = 180       # the reader's start
T_MIGRATE_QUERY = 120       # one query of the reader
MIGRATE_LABEL = "relic.migrate"
MIGRATE_DATADIR = "/var/lib/mysql"  # the image's own VOLUME: mounted by name in every container of a job, so that
#                                     none of them leaves an anonymous volume behind that nothing could find again
MIGRATE_NEEDED_SERVICES = ("mysql", "redis", "sdk")  # what a move needs of the target
_MIGRATE_JOB_ID_RE = re.compile(r"[0-9]{10,16}-[0-9a-f]{4}\Z")
_MIGRATE_IMAGE_RE = re.compile(r"[a-z0-9][a-z0-9._/-]{0,127}(?::[A-Za-z0-9._-]{1,128})?\Z")
_MIGRATE_BODY_KEYS = ("version", "source", "accounts", "dryRun", "keepPassword", "keepUid", "cancel")
_MIGRATE_DIR_QUOTE_TEXT = "source.dir cannot hold a comma or a double quote -- docker's --mount option cannot name " \
                          "such a folder"
# The way Docker Desktop names a folder of the Windows host in a mount or a label, beside the folder's own spelling.
_MIGRATE_HOST_MNT_RE = re.compile(r"/(?:run/desktop/mnt/host|host_mnt)/([A-Za-z])(?:/(.*))?\Z")
_MIGRATE_UID_TABLES = ("t_login_black_uid_config", "t_chat_block_config", "t_feature_block_config",
                       "t_account_cancellation_config", "t_client_watchdog_uid_list_config",
                       "t_anti_offline_whitelist")  # hk4e_db_config's tables a uid has rows of
_MIGRATE_PLAYER_SQL = ("SELECT uid, HEX(nickname), level, exp, vip_point, HEX(json_data), HEX(bin_data), "
                       "HEX(extra_bin_data), data_version, HEX(tag_list), UNIX_TIMESTAMP(last_save_time), is_delete, "
                       "HEX(before_login_bin_data) FROM t_player_data_%d WHERE uid=%d")
_MIGRATE_PLAYER_COLUMNS = (("uid", 0), ("nickname", 1), ("level", 0), ("exp", 0), ("vip_point", 0), ("json_data", 1),
                           ("bin_data", 1), ("extra_bin_data", 1), ("data_version", 0), ("tag_list", 1),
                           ("last_save_time", 0), ("is_delete", 0), ("before_login_bin_data", 1))  # 1 = through HEX()
_MIGRATE_BLOCK_SQL = "SELECT block_id, data_version, HEX(bin_data) FROM t_block_data_%d WHERE uid=%d ORDER BY block_id"
_MIGRATE_HOME_SQL = "SELECT data_version, HEX(bin_data) FROM t_home_data_%d WHERE uid=%d"
# What a job line says of a skipped account. `refused`, `clientUnknown` and `nameNotAllowed` say it in their `reason`.
_MIGRATE_SKIP_TEXTS = {
    "guest": "a guest has no name to move by",
    "noSave": "it never played on the old server",
    "deleted": "it is marked deleted on the old server",
    "nameTaken": "its name is an account of version %(target)s already",
    "noTarget": "no account is named so on version %(target)s",
    "targetOnline": "that account is in the game on version %(target)s",
    "targetRecent": "that account saved moments ago on version %(target)s and may still be in the game",
    "batchDuplicate": "an earlier account of this move goes to that name",
    "notChecked": "beyond the accounts one check reads",
    "notInSource": "no such account on the old server",
    "takenMeanwhile": "the name was taken while the move ran",
}


class _MigrateStopped(Exception):
    """A stop request met in the source phase: never an error, the job ends with what it has."""


class _MigrateTooLarge(_Failed):
    """migrate_docker's answer for an output past its cap."""


class _MigrateReadTooLarge(Exception):
    """An answer of the reader past MIGRATE_READ_MAX: that account cannot be moved, the job goes on."""


def _migrate_pause(seconds):
    time.sleep(seconds)


def _migrate_stop_point():
    if _migrate_cancel.is_set():
        raise _MigrateStopped()


def _migrate_version_field(v):
    """A version id of a move's body: a string this agent knows, 400 otherwise."""
    if not isinstance(v, str):
        raise AgentError(400, "Unknown version: %s." % json.dumps(v), code="unknown_version")
    check_known(v)
    return v


def _migrate_name_field(item, key, i):
    """The login `key` of accounts[i] exactly as it stands -- it is matched exactly --, 400 unless it is one line of
    plain text of at most ACCOUNT_SPEC_MAX characters."""
    v = item.get(key)
    if not isinstance(v, str) or not v.strip() or len(v) > ACCOUNT_SPEC_MAX or plain_line_problem(v):
        raise AgentError(400, "accounts[%d].%s must be an account name (one line of plain text, at most %d characters)"
                         % (i, key, ACCOUNT_SPEC_MAX))
    return v


def migrate_new_name_problem(name, reserved):
    """(code, reason) when a move may not create an account of this name, else None: what a signup could not take
    (validate_account_name: its public code) and digits alone (no code: no launcher has a text of its own for it).
    Pure."""
    why = validate_account_name(name, reserved)
    if why:
        return why
    if _DIGITS_RE.fullmatch(name):
        return None, "a move never creates an account named with digits alone"
    return None


def _migrate_is_absolute(path):
    return bool(_WIN_DRIVE_PATH_RE.match(path)) if IS_WINDOWS else os.path.isabs(path)


def migrate_source_dir(raw, target):
    """The folder of a {dir} source, checked against this box without opening it -> its normalised path; 400 for what
    no folder of a server could be: not one line, not absolute, what docker's --mount cannot name, a drive Docker Desktop
    cannot share, a stack folder of this agent -- the target's above all -- or one of the agent's own folders, equal, in
    it or holding it. Whether it holds a server at all is the job's 409."""
    if not isinstance(raw, str) or len(raw) > SETTING_PATH_MAX or plain_line_problem(raw) \
            or not _migrate_is_absolute(raw):
        raise AgentError(400, "source.dir must be the absolute path of a folder on this machine (one line of plain "
                              "text, at most %d characters)" % SETTING_PATH_MAX)
    if "," in raw or '"' in raw:
        raise AgentError(400, _MIGRATE_DIR_QUOTE_TEXT)
    if IS_WINDOWS:
        why = _WIN_DRIVE_REFUSED.get(_win_drive_type(raw[0]))
        if why:
            raise AgentError(400, "source.dir is on drive %s:, which %s" % (raw[0].upper(), why))
    folder = os.path.normpath(os.path.abspath(raw))

    def nested(a, b):
        return _path_within(a, b) or _path_within(b, a)

    stacks = [(v, meta["dir"]) for v, meta in list(VERSIONS.items()) if meta["dir"]]
    for v, d in stacks:
        if v == target and nested(folder, d):
            raise AgentError(400, "source.dir is version %s's own stack folder, or lies in it or holds it -- name the "
                                  "folder of another server." % v)
    for v, d in stacks:
        if _real_norm(folder) == _real_norm(d):
            raise AgentError(400, "source.dir is the folder of version %s -- choose version %s as the source instead."
                             % (v, v))
    for v, d in stacks:
        if nested(folder, d):
            raise AgentError(400, "source.dir lies in, or holds, the folder of version %s -- name a folder that holds "
                                  "one server." % v)
    for label, d in _agent_folders():
        if d and nested(folder, d):
            raise AgentError(400, "source.dir lies in, or holds, %s -- the agent's own folders are never a source."
                             % label)
    return folder


def migrate_preflight(b, auth_kind):
    """POST /server/migrate's refusals before a job exists, in their order -- each a 400, and a 403 for a folder source
    without the agent's token, decided before anything of the path is looked at; never a 404 (that means "an agent
    without this route" to the launcher). No docker call, no MySQL call, no write: a version or a folder that is not
    on this box is the job's own 409. `auth_kind` = Handler._auth_kind()'s word. A key whose value is null counts as
    absent. -> (the target, the request do_migrate takes: {"source": {"kind": "version" | "folder", "version", "dir"},
    "accounts": None or [{"from", "to" (None: the same login), "overwrite"}], "dryRun", "keepPassword", "keepUid"})."""
    for key in b:
        if key not in _MIGRATE_BODY_KEYS:
            raise AgentError(400, "unknown field %s" % key)
    version = _migrate_version_field(b.get("version"))
    source = b.get("source")
    picked = [k for k in ("version", "dir") if isinstance(source, dict) and source.get(k) is not None]
    if len(picked) != 1 or any(k not in ("version", "dir") for k in source):
        raise AgentError(400, "source names exactly one of version (a version of this agent) or dir (a folder on this "
                              "machine)")
    if picked == ["dir"] and auth_kind != "token":
        raise AgentError(403, "A server folder as the source needs the agent's token -- the open administration key "
                              "cannot read folders on this machine.", code="folder_needs_token")
    if picked == ["version"]:
        src = {"kind": "version", "version": _migrate_version_field(source["version"]), "dir": None}
        if src["version"] == version:
            raise AgentError(400, "The source is the target itself -- name another version, or the folder of another "
                                  "server of version %s." % version)
    else:
        src = {"kind": "folder", "version": None, "dir": migrate_source_dir(source["dir"], version)}
    accounts = b.get("accounts")
    items = None
    real = b.get("dryRun") is not True
    if accounts is not None:
        if not isinstance(accounts, list) or not 1 <= len(accounts) <= MIGRATE_ACCOUNTS_MAX:
            raise AgentError(400, "accounts must be a list of 1 to %d accounts" % MIGRATE_ACCOUNTS_MAX)
        for i, item in enumerate(accounts):
            if not isinstance(item, dict) or any(k not in ("from", "to", "overwrite") for k in item):
                raise AgentError(400, "accounts[%d] must be an object {from, to?, overwrite?}" % i)
        items = [{"from": _migrate_name_field(item, "from", i),
                  "to": None if item.get("to") is None else _migrate_name_field(item, "to", i)}
                 for i, item in enumerate(accounts)]
        for i, item in enumerate(accounts):
            over = item.get("overwrite")
            if over is not None and not isinstance(over, bool):
                raise AgentError(400, "accounts[%d].overwrite must be true or false" % i)
            items[i]["overwrite"] = bool(over)
        if real:
            _migrate_manifest(version)
            reserved = reserved_names(version)
            for i, item in enumerate(items):
                why = None if item["overwrite"] else migrate_new_name_problem(item["to"] or item["from"], reserved)
                if why:
                    raise AgentError(400, "accounts[%d]: %s" % (i, why[1]), code=why[0])
        for i, item in enumerate(items):
            for j in range(i):
                if items[j]["from"] == item["from"]:
                    raise AgentError(400, "accounts[%d].from names the account accounts[%d] names" % (i, j))
        for i, item in enumerate(items):
            for j in range(i):
                if (items[j]["to"] or items[j]["from"]).casefold() == (item["to"] or item["from"]).casefold():
                    raise AgentError(400, "accounts[%d] and accounts[%d] go to the same name" % (j, i))
    elif real:
        raise AgentError(400, "a move names the accounts it moves -- run its check (dryRun: true) first")
    flags = {}
    for key in ("dryRun", "keepPassword", "keepUid"):
        flag = b.get(key)
        if flag is not None and not isinstance(flag, bool):
            raise AgentError(400, "%s must be true or false" % key)
        flags[key] = bool(flag)
    return version, dict(flags, source=src, accounts=items)


def migrate_docker(args, timeout, max_out=None):
    """The one runner of the reader's docker calls: _run_capped's -- stdin empty, two threads read the output, the
    whole process tree killed at `timeout`, the output decoded as UTF-8 -- with a cap on the output: past `max_out`
    bytes of stdout the reading stops and the tree is killed (-> _MigrateTooLarge, nothing of the output held);
    stderr is kept up to MIGRATE_ERR_MAX. -> an object with returncode / stdout / stderr, or _Failed: a missing
    executable, "timed out (<n>s): ...", an output that did not end with the process."""
    kw = dict(_popen_kwargs())
    if not IS_WINDOWS:
        kw["start_new_session"] = True
    try:
        p = subprocess.Popen(args, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kw)
    except FileNotFoundError:
        return _Failed("executable not found: %s" % args[0])
    except OSError as e:
        return _Failed("%s could not be started (%s)" % (args[0], e))
    out, err = [], []
    over = threading.Event()

    def drain_out():
        held = 0
        try:
            for chunk in iter(lambda: p.stdout.read(65536), b""):
                held += len(chunk)
                if max_out is not None and held > max_out:
                    over.set()
                    _kill_tree(p)
                    return
                out.append(chunk)
        except Exception:  # noqa: BLE001 -- the pipe closing under a kill
            pass

    def drain_err():
        held = 0
        try:
            for chunk in iter(lambda: p.stderr.read(65536), b""):
                held += len(chunk)
                if held <= MIGRATE_ERR_MAX:
                    err.append(chunk)
        except Exception:  # noqa: BLE001 -- the pipe closing under a kill
            pass

    readers = [threading.Thread(target=drain_out, daemon=True), threading.Thread(target=drain_err, daemon=True)]
    for t in readers:
        t.start()

    def wait_readers():
        until = time.time() + RUN_CAPPED_GRACE
        for t in readers:
            t.join(max(0.0, until - time.time()))
        return not any(t.is_alive() for t in readers)

    try:
        rc = p.wait(timeout)
    except subprocess.TimeoutExpired:
        _kill_tree(p)
        wait_readers()
        return _Failed("timed out (%ss): %s" % (timeout, _cmd_words(args)))
    if not wait_readers():
        _kill_tree(p)
        return _Failed("the output of %s did not end with the process" % _cmd_words(args, 1))
    if over.is_set():
        return _MigrateTooLarge("the output of %s passed %d bytes" % (_cmd_words(args, 1), max_out))
    return _CappedResult(rc, b"".join(out).decode("utf-8", "replace"), b"".join(err).decode("utf-8", "replace"))


def migrate_object_names(job_id):
    """The names of a job's docker objects: the probe, the copy, the reader (a container, and the volume of that name)
    and their label. 500 for a job id of another shape: the id reaches an argv and a folder's name."""
    if not isinstance(job_id, str) or not _MIGRATE_JOB_ID_RE.match(job_id):
        raise AgentError(500, "A move runs only under a job id of the agent's own making -- nothing was moved.")
    return {"probe": "relic-migprobe-" + job_id, "copy": "relic-migcopy-" + job_id, "read": "relic-migread-" + job_id,
            "label": "%s=%s" % (MIGRATE_LABEL, job_id)}


def _migrate_run(names, name, detached=True):
    """The start of every `docker run` of a job: no network, nothing pulled, its label -- never a port or a restart
    policy, and a host folder only as a read-only --mount (a missing path is then an error, never a folder made)."""
    return ["docker", "run", "-d" if detached else "--rm", "--name", name, "--network", "none", "--pull", "never",
            "--label", names["label"]]


def _migrate_volume_mount(names):
    return ["--mount", "type=volume,src=%s,dst=%s" % (names["read"], MIGRATE_DATADIR)]


def _migrate_no_such(text):
    """Whether every line of a docker error says a thing is not there (what a removal counts as done)."""
    lines = [l for l in _clean_cmd_output(text).splitlines() if l.strip()]
    return bool(lines) and all("no such" in l.lower() for l in lines)


def migrate_reader_remove(job_id, job):
    """Remove a job's containers and its volume -- on every exit path, whatever exists of them by then: "no such" is
    done, anything else ONE WARNING line (the sweep after the agent's next start takes it). Never raises."""
    failed = []
    try:
        names = migrate_object_names(job_id)
        for args in (["docker", "rm", "-f", "-v", names["read"], names["copy"], names["probe"]],
                     ["docker", "volume", "rm", "-f", names["read"]]):
            try:
                r = migrate_docker(args, T_MIGRATE_DOCKER)
                if r.returncode != 0 and not _migrate_no_such(r.stderr):
                    failed.append(_cmd_err(r, 200, fallback="no answer"))
            except Exception as e:  # noqa: BLE001 -- the next removal still runs
                failed.append(str(e) or e.__class__.__name__)
        if failed:
            job.log("WARNING: the reader of the source's database could not be removed (%s) -- left for the agent's "
                    "clean-up after its next start." % "; ".join(failed))
    except Exception as e:  # noqa: BLE001 -- a cleanup, never a reason to fail the job
        job.log("WARNING: the reader of the source's database could not be removed (%s) -- left for the agent's "
                "clean-up after its next start." % (str(e) or e.__class__.__name__))


def _migrate_state_dir():
    return os.path.dirname(STATE_PATH) or "."


def migrate_spool_dir(job_id):
    """The job's folder of source rows: <state dir>/migrate/<job>/."""
    return os.path.join(_migrate_state_dir(), "migrate", job_id)


def _migrate_bytes_to_json(value):
    if isinstance(value, (bytes, bytearray)):
        return {"b64": base64.b64encode(bytes(value)).decode("ascii")}
    raise TypeError("a value the spool does not hold: %s" % value.__class__.__name__)


def _migrate_json_to_bytes(obj):
    return base64.b64decode(obj["b64"]) if set(obj) == {"b64"} else obj


def migrate_spool_put(job_id, n, entry, rows):
    """Keep the source rows of the account at place `n` of a real run, as read -- phase T transforms them with the real
    uid -- with its entry, in one private JSON file of the job's private folder: blobs in base64, never a password
    hash, gone with the job (migrate_spool_remove; a killed agent's: migrate_sweep)."""
    folder = migrate_spool_dir(job_id)
    if not os.path.isdir(folder):
        os.makedirs(folder, exist_ok=True)
        protect_path(os.path.dirname(folder), 0o700)
        protect_path(folder, 0o700)
    fd = os.open(os.path.join(folder, "%d.json" % n), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        json.dump({"entry": entry, "rows": rows}, f, default=_migrate_bytes_to_json)


def migrate_spool_get(job_id, n):
    """(entry, rows) as migrate_spool_put kept them."""
    with open(os.path.join(migrate_spool_dir(job_id), "%d.json" % n), encoding="utf-8") as f:
        kept = json.load(f, object_hook=_migrate_json_to_bytes)
    return kept["entry"], kept["rows"]


def migrate_spool_remove(job_id):
    _rmtree_quiet(migrate_spool_dir(job_id))


def _migrate_job_running(job_id):
    with _jobs_lock:
        j = JOBS.get(job_id)
        return j is not None and j.state == "running"


def migrate_sweep(keep=None):
    """What an earlier process left of its moves -- containers and volumes by their label, the folders of source rows
    -- removed unless its job runs (`keep`: the job that sweeps; its own id). Runs on a thread of its own after the
    agent listens, never before it, and at every migrate job's start. Docker's short timeouts, one WARNING line in
    the agent's log per failure, never fatal, and no database: MySQL is down at the agent's start (migrate_drop_scratch
    takes the scratch databases)."""
    def warn(what, why):
        log_line("gio-agent: WARNING: what a move left behind: %s (%s)." % (what, why))

    def done(job_id):
        return job_id != keep and not _migrate_job_running(job_id)

    try:
        r = migrate_docker(["docker", "ps", "-a", "--filter", "label=" + MIGRATE_LABEL, "--format",
                            "{{.ID}}\t{{.Label \"%s\"}}" % MIGRATE_LABEL], T_MIGRATE_DOCKER)
        if r.returncode != 0:
            warn("docker does not list its containers", _cmd_err(r, 200, fallback="no answer"))
        else:
            ids = [cells[0] for cells in (l.split("\t") for l in (r.stdout or "").splitlines() if l.strip())
                   if len(cells) == 2 and done(cells[1].strip())]
            if ids:
                r = migrate_docker(["docker", "rm", "-f", "-v"] + ids, T_MIGRATE_DOCKER)
                if r.returncode != 0 and not _migrate_no_such(r.stderr):
                    warn("its containers cannot be removed", _cmd_err(r, 200, fallback="no answer"))
            r = migrate_docker(["docker", "volume", "ls", "--filter", "label=" + MIGRATE_LABEL, "--format",
                                "{{.Name}}\t{{.Labels}}"], T_MIGRATE_DOCKER)
            if r.returncode != 0:
                warn("docker does not list its volumes", _cmd_err(r, 200, fallback="no answer"))
            else:
                names = []
                for line in (r.stdout or "").splitlines():
                    name, _tab, labels = line.partition("\t")
                    mark = next((l[len(MIGRATE_LABEL) + 1:] for l in labels.split(",")
                                 if l.startswith(MIGRATE_LABEL + "=")), None)
                    if name.strip() and mark is not None and done(mark.strip()):
                        names.append(name.strip())
                if names:
                    r = migrate_docker(["docker", "volume", "rm", "-f"] + names, T_MIGRATE_DOCKER)
                    if r.returncode != 0 and not _migrate_no_such(r.stderr):
                        warn("its volumes cannot be removed", _cmd_err(r, 200, fallback="no answer"))
    except Exception as e:  # noqa: BLE001 -- a cleanup, never a reason to stop anything
        warn("docker cannot be asked", str(e) or e.__class__.__name__)
    try:
        root = os.path.join(_migrate_state_dir(), "migrate")
        for name in (os.listdir(root) if os.path.isdir(root) else ()):
            if _MIGRATE_JOB_ID_RE.match(name) and done(name):
                _rmtree_quiet(os.path.join(root, name))
    except OSError as e:
        warn("its folders cannot be read", e.strerror or e.__class__.__name__)


def _migrate_manifest(version):
    try:
        return read_manifest(version)
    except (OSError, ValueError):
        raise AgentError(500, "The payload manifest of version %s cannot be read -- nothing is moved." % version)


def migrate_target_ready(target, man):
    """The target of a move, as the job finds it: configured, installed, running with its database, redis and account
    service, and its folder holding the server of its version -- 409 otherwise. Never stack_dir on a version without
    a folder (its 404 means "no route" to a launcher). A target whose save plan is unusable is left to the allow rule
    (migrate_context), which names why."""
    if not is_configured(target):
        raise AgentError(409, "Version %s has no folder on this server." % target)
    if not is_bootstrapped(target):
        raise AgentError(409, "The %s stack is not installed on the box." % target)
    names, _err = running_projects()
    if names is None or VERSIONS[target]["project"] not in names or not mysql_reachable(target):
        raise AgentError(409, "Server %s is not running -- start it first: the move writes into its database while its "
                              "players stay online." % target)
    dead, _states = dead_services(target)
    down = list(MIGRATE_NEEDED_SERVICES) if dead is None else [s for s in MIGRATE_NEEDED_SERVICES if s in dead]
    if down:
        raise AgentError(409, "Version %s's %s are not running -- the move needs its database, redis and account "
                              "service." % (target, ", ".join(down)))
    plan = save_plan(target, man)[0]
    if plan is not None and plan.migrate_problem is None:
        try:
            own = build_matches(plan, VERSIONS[target]["dir"])
        except OSError:
            own = False
        if not own:
            raise AgentError(409, "The folder of version %s holds the server of another build -- the move writes only "
                                  "into a version's own server." % target)


def migrate_source_folder(req):
    """The folder of the request's source: the one it names, or the configured folder of its version -- 409 when that
    has none, or one docker's --mount cannot name."""
    source = req["source"]
    if source["kind"] == "folder":
        return source["dir"]
    v = source["version"]
    if not is_configured(v):
        raise AgentError(409, "Version %s has no folder on this server -- name the folder of its server instead." % v)
    folder = VERSIONS[v]["dir"]
    if "," in folder or '"' in folder:
        raise AgentError(409, _MIGRATE_DIR_QUOTE_TEXT)
    return folder


def migrate_folder_shape(src):
    """409 unless `src` holds a server package of this game: a compose file, a database folder that is no link, its
    system tablespace and player tables, the account database, the server program."""
    def have(*parts):
        return os.path.isfile(os.path.join(src, *parts))

    mysql = os.path.join(src, "mysql")
    missing = None
    if not have("docker-compose.yml") and not have("docker-compose.yml.tmpl"):
        missing = "a compose file (docker-compose.yml)"
    elif os.path.islink(mysql) or not os.path.isdir(mysql):
        missing = "the database folder (mysql/)"
    elif not have("mysql", "ibdata1"):
        missing = "mysql/ibdata1"
    elif os.path.islink(os.path.join(mysql, PLAYER_DB)) or not os.path.isdir(os.path.join(mysql, PLAYER_DB)):
        missing = "mysql/%s/" % PLAYER_DB
    elif not have("sdk", "data", "sdk.db"):
        missing = "sdk/data/sdk.db"
    elif not have("server", "gameserver", "gameserver"):
        missing = "server/gameserver/gameserver"
    if missing:
        raise AgentError(409, "The source folder holds no server package of this game: %s is missing." % missing)


def migrate_docker_path(path, windows):
    """The folder of this machine that a path docker names (a mount's Source, a compose label) stands for, in the
    machine's own spelling; None for a form that names none -- not a match: the label checks and the stamps still
    guard. Elsewhere than on Windows the path is that folder. On Windows it is D:\\x as it stands, or Docker Desktop's
    /run/desktop/mnt/host/d/x or /host_mnt/d/x. Pure."""
    text = str(path or "").strip()
    if not text:
        return None
    if not windows:
        return text
    m = _MIGRATE_HOST_MNT_RE.match(text)
    if m:
        return "%s:\\%s" % (m.group(1).upper(), (m.group(2) or "").replace("/", "\\"))
    return text if _WIN_DRIVE_PATH_RE.match(text) else None


def _migrate_on(path, folder):
    """A path docker names is `folder` or lies in it (_path_within: by realpath + normcase); False for a form that
    names no folder of this machine."""
    p = migrate_docker_path(path, IS_WINDOWS)
    return p is not None and _path_within(p, folder)


def _migrate_over(path, folder):
    """A path docker names holds `folder`, or is it."""
    p = migrate_docker_path(path, IS_WINDOWS)
    return p is not None and _path_within(folder, p)


def _migrate_is(path, folder):
    return _migrate_on(path, folder) and _migrate_over(path, folder)


def _migrate_mute(why):
    return AgentError(409, "Docker does not answer (%s) -- the move cannot tell whether the source is at rest." % why)


def migrate_compose_projects():
    """[(name, config files -- comma-separated)] of EVERY compose project docker knows, stopped ones included: what
    compose_projects_all asks, through the funnel like every other docker call of the reader. AgentError 409 when
    docker does not answer, or gives an answer of another shape: nothing may then be said of the source."""
    r = migrate_docker(["docker", "compose", "ls", "-a", "--format", "json"], T_MIGRATE_DOCKER)
    if r.returncode != 0:
        raise _migrate_mute(_cmd_err(r, 200, fallback="no answer"))
    entries = _parse_ls_entries(r.stdout)
    if entries is None:
        raise _migrate_mute("an answer the agent cannot read")
    return [(str(e.get("Name") or ""), str(e.get("ConfigFiles") or "")) for e in entries]


def migrate_containers():
    """[{"name", "state", "labels", "mounts"}] of every container docker knows, in any state: one `docker ps -a` and ONE
    `docker inspect`. One that goes away between the two is none. AgentError 409 when docker does not answer, or gives
    an answer of another shape: nothing may then be said of the source."""
    r = migrate_docker(["docker", "ps", "-a", "--no-trunc", "--format", "{{.ID}}"], T_MIGRATE_DOCKER)
    if r.returncode != 0:
        raise _migrate_mute(_cmd_err(r, 200, fallback="no answer"))
    ids = [line.strip() for line in (r.stdout or "").splitlines() if line.strip()]
    if not ids:
        return []
    r = migrate_docker(["docker", "inspect", "--format", "\t".join((
        "{{.Id}}", "{{.Name}}", "{{json .State.Status}}", "{{json .Config.Labels}}", "{{json .Mounts}}"))] + ids,
        T_MIGRATE_DOCKER, max_out=MIGRATE_READ_MAX)
    if r.returncode != 0 and not _migrate_no_such(r.stderr):
        raise _migrate_mute(_cmd_err(r, 200, fallback="no answer"))
    out = []
    for line in (r.stdout or "").splitlines():
        if not line.strip():
            continue
        cells = line.split("\t")
        try:
            if len(cells) != 5:
                raise ValueError("a line of %d cells" % len(cells))
            state, labels, mounts = json.loads(cells[2]), json.loads(cells[3]) or {}, json.loads(cells[4]) or []
            if not isinstance(labels, dict) or not isinstance(mounts, list):
                raise ValueError("labels or mounts of another shape")
        except ValueError:
            raise _migrate_mute("an answer the agent cannot read")
        out.append({"name": cells[1].lstrip("/"), "state": str(state), "labels": labels, "mounts": mounts})
    return out


def migrate_at_rest(src, job):
    """409 unless the source is at rest -- asked of docker before the source is read and once more after its copy,
    docker mute = refused: no compose project whose files lie at or under it, NO container of its project in any state
    (the label naming the folder; one without that label by the project's name) and no container, this job's own
    aside, with a writable mount at, under or above it; a read-only mount is harmless. A stopped pathfindingserver is
    named as what it is: a leftover of a stop, which does not touch the database folder -- it is refused all the same,
    and the admin removes it."""
    listed = [name for name, files in migrate_compose_projects()
              if any(_migrate_on(f.strip(), src) for f in files.split(",") if f.strip())]
    project, theirs, writers = _project_name(src), [], []
    for c in migrate_containers():
        labels = c["labels"]
        if labels.get(MIGRATE_LABEL) == job.id:
            continue
        folder = labels.get("com.docker.compose.project.working_dir")
        if _migrate_is(folder, src) if folder else labels.get("com.docker.compose.project") == project:
            theirs.append(c)
        elif any(isinstance(m, dict) and m.get("RW") and (_migrate_on(m.get("Source"), src)
                                                          or _migrate_over(m.get("Source"), src))
                 for m in c["mounts"]):
            writers.append(c)
    if theirs:
        said = []
        for c in theirs:
            service = c["labels"].get("com.docker.compose.service") or c["name"]
            said.append("%s: %s%s" % (service, c["state"],
                                      " (a leftover of a stop; it does not touch the database folder)"
                                      if service == PATHFINDING_SERVICE and c["state"] != "running" else ""))
        raise AgentError(409, "The source server is not at rest: docker still has %d container(s) of it (%s) -- the "
                              "move reads only a server with no container at all; remove them (docker rm %s) and try "
                              "again." % (len(theirs), ", ".join(said), " ".join(c["name"] for c in theirs)))
    if listed:
        raise AgentError(409, "The source server is not at rest: docker still knows its compose project %s -- the move "
                              "reads only a server with no container at all; remove its containers and try again."
                         % listed[0])
    if writers:
        raise AgentError(409, "A container (%s) can write into the source folder -- stop and remove it first."
                         % writers[0]["name"])


def migrate_mysql_service(text):
    """(its image, what of it the reader would not reproduce, or None) of the `mysql` service of a compose file's text,
    read from the service's own block: a `command:` or an `entrypoint:` must not be there, and no volume but
    ./mysql:/var/lib/mysql. (None, why) without such a service. Pure."""
    blk = _service_block(text, "mysql")
    if blk is None:
        return None, "it has no mysql service"
    start, end, _indent, child, _eol = blk
    image, what, section = None, [], None
    for line in text[start:end].splitlines()[1:]:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        # (a list may stand at the indent of its own key: an item is the section's whatever its indent)
        if _line_indent(line) == child and not s.startswith("-"):
            key, _colon, rest = s.partition(":")
            section, rest = key.strip(), rest.split(" #")[0].strip()
            if section == "image":
                image = rest.strip("\"'")
            elif section in ("command", "entrypoint") or (section == "volumes" and rest not in ("", "[]")):
                what.append(section)
        elif section == "volumes" and (not s.startswith("-") or s[1:].strip().strip("\"'") != "./mysql:/var/lib/mysql"):
            what.append("another volume")
    return image, ", ".join(OrderedDict.fromkeys(what)) or None


def migrate_image(target, src):
    """The image the reader runs: the source's mysql service's, which must be the one the target's rendered compose file
    names -- a database is read only with the server program that wrote it -- and a plain image name, on this box
    (nothing is ever pulled); the service set up as the reader sets its own up. 409 otherwise."""
    image, what = None, "it has no compose file"
    for name in ("docker-compose.yml", "docker-compose.yml.tmpl"):
        try:
            image, what = migrate_mysql_service(read_text(os.path.join(src, name)))
            break
        except (OSError, ValueError):
            continue
    try:
        own = migrate_mysql_service(read_text(_compose_paths(target)[1]))[0]
    except (OSError, ValueError):
        own = None
    if not image or image != own or not _MIGRATE_IMAGE_RE.match(image):
        raise AgentError(409, "The source's database image (%s) is not the one version %s runs (%s) -- the move reads a "
                              "database only with the server program that wrote it."
                         % ((image or "none")[:140], target, (own or "none")[:140]))
    if what:
        raise AgentError(409, "The source's database service is set up in a way the reader does not reproduce (%s) -- "
                              "nothing was moved." % what)
    r = migrate_docker(["docker", "image", "inspect", "--format", "{{.Id}}", image], T_MIGRATE_DOCKER)
    if r.returncode != 0:
        raise AgentError(409, "The image %s is not on this box -- the move never downloads one." % image)
    return image


def migrate_stamp(folder):
    """{relative path: (size, st_mtime_ns)} of every regular file below `folder` and {relative path + "/": None} of every
    folder, links never followed -- what must read the same before and after the copy. 409 for anything else in it (a
    link, a device), past MIGRATE_STAMP_MAX entries and for a folder that cannot be read: a stamp with a hole in it
    guards nothing. The paths are relative: they may reach a message."""
    out = {}

    def unreadable(e):
        raise e

    try:
        for dp, dns, fns in os.walk(folder, onerror=unreadable, followlinks=False):
            for name in dns + fns:
                path = os.path.join(dp, name)
                rel = os.path.relpath(path, folder).replace(os.sep, "/")
                st = os.lstat(path)
                if (st.st_mode & 0o170000) == 0o040000:
                    out[rel + "/"] = None
                elif (st.st_mode & 0o170000) == 0o100000:
                    out[rel] = (st.st_size, st.st_mtime_ns)
                else:
                    raise AgentError(409, "The source's database folder holds %s, which is no plain file -- nothing "
                                          "was moved." % rel)
                if len(out) > MIGRATE_STAMP_MAX:
                    raise AgentError(409, "The source's database folder holds more than %d entries -- nothing was "
                                          "moved." % MIGRATE_STAMP_MAX)
    except OSError as e:
        raise AgentError(409, "The source's database folder cannot be read (%s) -- nothing was moved."
                         % (e.strerror or e.__class__.__name__))
    return out


def migrate_sdk_stamp(src):
    """migrate_stamp's record of the source's account database and its rollback journal (None: not there)."""
    out = {}
    for name in ("sdk.db", "sdk.db-journal"):
        try:
            st = os.lstat(os.path.join(src, "sdk", "data", name))
            out[name] = (st.st_size, st.st_mtime_ns)
        except FileNotFoundError:
            out[name] = None
        except OSError as e:
            raise AgentError(409, "The source's account database cannot be read (%s) -- nothing was moved."
                             % (e.strerror or e.__class__.__name__))
    return out


def _migrate_stamp_diff(a, b):
    """How many entries of two stamps differ."""
    return sum(1 for k in set(a) | set(b) if k not in a or k not in b or a[k] != b[k])


def _migrate_size(n):
    return "%.1f GB" % (n / 1e9) if n >= 1e8 else "%d MB" % round(n / 1e6)


def parse_migrate_probe(text):
    """(free bytes, available memory in bytes) from the probe's output: `df -Pk`'s row of the volume and /proc/meminfo's
    MemAvailable line -- None for what it does not hold. Pure."""
    free = mem = None
    for line in (text or "").splitlines():
        cells = line.split()
        if len(cells) >= 2 and cells[0] == "MemAvailable:" and _DIGITS_RE.fullmatch(cells[1]):
            mem = int(cells[1]) << 10
        elif len(cells) >= 6 and _DIGITS_RE.fullmatch(cells[3]):
            free = int(cells[3]) << 10
    return free, mem


def migrate_probe(target, names, image, size):
    """The room the copy and the reader need, asked inside docker -- the virtual machine's on Docker Desktop, the
    host's on Linux, one rule for both: the reader's volume is made, and a probe in the image says what is free where
    docker keeps it and how much memory is available. 507 for the copy's `size` + the box's own reserve, 409 for the
    memory, 507 for the room of a real run's backups beside the state file."""
    r = migrate_docker(["docker", "volume", "create", "--label", names["label"], names["read"]], T_MIGRATE_DOCKER)
    if r.returncode != 0:
        raise AgentError(500, "The reader's volume could not be made (%s) -- nothing was moved."
                         % _cmd_err(r, 200, fallback="no answer"))
    r = migrate_docker(_migrate_run(names, names["probe"], detached=False) + _migrate_volume_mount(names) + [
        image, "sh", "-c", "df -Pk %s; grep -E '^MemAvailable:' /proc/meminfo" % MIGRATE_DATADIR], T_MIGRATE_DOCKER)
    free, mem = parse_migrate_probe(r.stdout) if r.returncode == 0 else (None, None)
    if free is None or mem is None:
        raise AgentError(500, "The look at docker's disk and memory gave no answer the agent can read (%s) -- nothing "
                              "was moved." % _cmd_err(r, 200, fallback="no answer"))
    need = size + FETCH_DISK_RESERVE
    if free < need:
        raise AgentError(507, "Not enough room for the copy of the source's database: %s needed, %s free where docker "
                              "keeps its volumes (the copy is %s plus the %s kept free)."
                         % (_migrate_size(need), _migrate_size(free), _migrate_size(size),
                            _migrate_size(FETCH_DISK_RESERVE)))
    want = MIGRATE_READER_MEMORY + MIGRATE_MEMORY_RESERVE
    if mem < want:
        raise AgentError(409, "Not enough memory for the reader beside version %s: %s available, %s needed -- move the "
                              "accounts when the box is less busy." % (target, _migrate_size(mem), _migrate_size(want)))
    room = _free_bytes_at(os.path.join(_migrate_state_dir(), "backups"))
    if room is not None and room < MIGRATE_BACKUPS_ROOM:
        raise AgentError(507, "Not enough room for the backups of a move: %s free beside the agent's state, %s needed."
                         % (_migrate_size(room), _migrate_size(MIGRATE_BACKUPS_ROOM)))


def _migrate_tail(names, name):
    """The last 20 lines a container of the job wrote, the tool's own notices dropped, one line -- the source's folder
    is /src in there."""
    r = migrate_docker(["docker", "logs", "--tail", "20", name], T_MIGRATE_DOCKER, max_out=MIGRATE_ERR_MAX)
    text = _clean_cmd_output("%s\n%s" % (r.stdout or "", r.stderr or ""))
    return " / ".join(l.strip() for l in text.splitlines()[-20:] if l.strip()) or "no output"


def migrate_copy(names, image, src):
    """The copy of the source's mysql/ into the reader's volume, in a detached container so that a stop reaches it: the
    source through a read-only --mount alone. Its state is asked once a second, against the stop flag and T_MIGRATE_COPY:
    a stop or the limit removes it at once. exited 0 is required. _MigrateStopped on a stop, 500 otherwise. docker's
    words on a start it refused are not quoted: they name the folder, in whatever form Docker Desktop has for it."""
    r = migrate_docker(_migrate_run(names, names["copy"]) + [
        "--mount", "type=bind,src=%s,dst=/src,readonly" % os.path.join(src, "mysql")] + _migrate_volume_mount(names) + [
            image, "sh", "-c", "cp -a /src/. %s/" % MIGRATE_DATADIR], T_MIGRATE_DOCKER)
    if r.returncode != 0:
        raise AgentError(500, "The copy of the source's database could not start -- nothing was moved.")
    until = time.time() + T_MIGRATE_COPY
    while True:
        stopping = _migrate_cancel.is_set()
        if stopping or time.time() >= until:
            migrate_docker(["docker", "rm", "-f", "-v", names["copy"]], T_MIGRATE_DOCKER)
            if stopping:
                raise _MigrateStopped()
            raise AgentError(500, "The copy of the source's database did not end within %d s -- nothing was moved."
                             % T_MIGRATE_COPY)
        r = migrate_docker(["docker", "inspect", "-f", "{{.State.Status}} {{.State.ExitCode}}", names["copy"]],
                           T_MIGRATE_DOCKER)
        if r.returncode != 0 and _migrate_no_such(r.stderr):
            raise AgentError(500, "The copy of the source's database was removed while it ran -- nothing was moved.")
        state = (r.stdout or "").split() if r.returncode == 0 else []
        if state[:1] in (["exited"], ["dead"]):
            break
        _migrate_pause(1)
    if state != ["exited", "0"]:
        raise AgentError(500, "The copy of the source's database failed (%s) -- nothing was moved."
                         % _migrate_tail(names, names["copy"]))
    migrate_docker(["docker", "rm", "-v", names["copy"]], T_MIGRATE_DOCKER)


def migrate_start_reader(names, image):
    """The throwaway MariaDB over the copy: no grant tables, no networking, its memory capped, the image's own entrypoint
    taking the existing data folder (crash recovery runs in the copy). It is asked once a second whether it answers,
    against the stop flag and T_MIGRATE_READY. _MigrateStopped on a stop, 500 otherwise."""
    limit = "%dm" % (MIGRATE_READER_MEMORY >> 20)
    r = migrate_docker(_migrate_run(names, names["read"]) + ["--memory", limit, "--memory-swap", limit]
                       + _migrate_volume_mount(names) + [image, "mariadbd", "--skip-grant-tables", "--skip-networking",
                                                         "--innodb-buffer-pool-size=64M", "--performance-schema=OFF"],
                       T_MIGRATE_DOCKER)
    if r.returncode != 0:
        raise AgentError(500, "The reader of the source's database could not start (%s) -- nothing was moved."
                         % _cmd_err(r, 300, fallback="no answer"))
    until = time.time() + T_MIGRATE_READY
    while True:
        _migrate_stop_point()
        r = migrate_docker(["docker", "inspect", "-f", "{{.State.Status}}", names["read"]], T_MIGRATE_DOCKER)
        if r.returncode == 0 and (r.stdout or "").strip() in ("exited", "dead"):
            raise AgentError(500, "The reader of the source's database did not start (%s) -- nothing was moved."
                             % _migrate_tail(names, names["read"]))
        if migrate_docker(["docker", "exec", names["read"], "mysqladmin", "ping"], T_MIGRATE_DOCKER).returncode == 0:
            return
        if time.time() >= until:
            raise AgentError(500, "The reader of the source's database did not answer within %d s -- nothing was moved."
                             % T_MIGRATE_READY)
        _migrate_pause(1)


def migrate_query(names, sql):
    """The answer of ONE query of the reader -- built from constants and validated integers only, every text and blob
    column through HEX() -- as the mysql client prints it: a line per row, tab-separated, NULL as the word.
    _MigrateReadTooLarge past MIGRATE_READ_MAX; 409 when the source has no player tables, 500 otherwise."""
    r = migrate_docker(["docker", "exec", names["read"], "mysql", "-N", "-B", "--default-character-set=utf8mb4",
                        PLAYER_DB, "-e", sql], T_MIGRATE_QUERY, max_out=MIGRATE_READ_MAX)
    if isinstance(r, _MigrateTooLarge):
        raise _MigrateReadTooLarge()
    if r.returncode != 0:
        if re.search(r"ERROR (?:1049|1146)\b", r.stderr or ""):
            raise AgentError(409, "The source's database has no player tables -- nothing to move.")
        raise AgentError(500, "The reader of the source's database refused a query (%s) -- nothing was moved."
                         % _cmd_err(r, 200, fallback="no answer"))
    return r.stdout or ""


def _migrate_cells(line, n):
    cells = line.split("\t")
    if len(cells) != n:
        raise ValueError("a line of %d cells" % len(cells))
    return cells


def _sql_cell_blob(cell):
    return None if cell == "NULL" else bytes.fromhex(cell)


def migrate_parse_player(line):
    """{column: value} of a line of _MIGRATE_PLAYER_SQL's answer: the HEX() columns as bytes, the rest as numbers, a NULL
    as None -- as the source's database holds them. ValueError for a line of another shape. Pure."""
    cells = _migrate_cells(line, len(_MIGRATE_PLAYER_COLUMNS))
    return dict((name, (_sql_cell_blob if hexed else _sql_cell_number)(cell))
                for (name, hexed), cell in zip(_MIGRATE_PLAYER_COLUMNS, cells))


def migrate_read_account(names, uid):
    """The rows of the game uid `uid` as the source's database holds them (migrate_transform's rows), None when it has
    no player row: three queries of its shard. ValueError for an answer of another shape, _MigrateReadTooLarge."""
    shard = uid % 10
    lines = [l for l in migrate_query(names, _MIGRATE_PLAYER_SQL % (shard, uid)).splitlines() if l.strip()]
    if not lines:
        return None
    rows = {"player": migrate_parse_player(lines[0]), "blocks": [], "home": None}
    for line in migrate_query(names, _MIGRATE_BLOCK_SQL % (shard, uid)).splitlines():
        if line.strip():
            block, version, blob = _migrate_cells(line, 3)
            rows["blocks"].append({"block_id": _sql_cell_number(block), "data_version": _sql_cell_number(version),
                                   "bin_data": _sql_cell_blob(blob)})
    home = [l for l in migrate_query(names, _MIGRATE_HOME_SQL % (shard, uid)).splitlines() if l.strip()]
    if home:
        version, blob = _migrate_cells(home[0], 2)
        rows["home"] = {"data_version": _sql_cell_number(version), "bin_data": _sql_cell_blob(blob)}
    return rows


def sdk_names(path):
    """[(sdk uid, name, type)] of the accounts of the account database `path`, by sdk uid: a private copy of it
    (read_sqlite_copy), and nothing but those three columns. FileNotFoundError, _SdkDbUnreadable, sqlite3.Error."""
    def read(con):
        con.text_factory = _sqlite_lenient_text
        cols = {row[1] for row in con.execute("PRAGMA table_info(accounts)")}
        if "uid" not in cols:
            raise sqlite3.DatabaseError("no accounts table")
        picked = ", ".join(c if c in cols else "NULL" for c in ("name", "type"))
        return [(int(uid), _sqlite_text(name), _whole_or_none(typ))
                for uid, name, typ in con.execute("SELECT uid, %s FROM accounts ORDER BY uid" % picked)
                if _whole_or_none(uid) is not None]
    return read_sqlite_copy(path, read)


def sdk_password_hashes(path, uids):
    """{sdk uid: the stored password hash, as bytes} of the accounts `uids` of the account database `path`, read like
    sdk_names. A hash stays in the memory of the job that asked: never a file, a line, a result, an argv or an event."""
    wanted = frozenset(uids)

    def read(con):
        con.text_factory = _sqlite_lenient_text
        out = {}
        for uid, value in con.execute("SELECT uid, password FROM accounts"):
            if uid in wanted and value is not None:
                out[uid] = bytes(value) if isinstance(value, (bytes, memoryview)) else str(value).encode("utf-8")
        return out
    return read_sqlite_copy(path, read)


def _migrate_sdk_read(read, status, whose, after="nothing was moved"):
    """read() of an account database a move depends on: AgentError `status` naming `whose` it is, never a path, and
    ending in `after`: what the read's failure leaves."""
    try:
        return read()
    except (OSError, sqlite3.Error, _SdkDbUnreadable) as e:
        raise AgentError(status, "%s account database (sdk/data/sdk.db) could not be read (%s) -- %s."
                         % (whose, e if isinstance(e, _SdkDbUnreadable) else e.__class__.__name__, after))


def sdk_exact_lookup(version, name):
    """(sdk uid, name) of the type-1 account of EXACTLY this login, None when the version has none: no other letter
    case, no guest. A move names an account by nothing else (no NOCASE fallback, unlike _sdk_db_lookup): it asks right
    after a registration, so a file that cannot be read leaves the name perhaps registered."""
    for uid, login, typ in _migrate_sdk_read(lambda: sdk_names(_sdk_db_path(version)), 500, "The stack's",
                                             after="the account may be registered"):
        if login == name and typ == 1:
            return uid, login
    return None


def migrate_name_verdict(name, overwrite, logins, reserved):
    """What a move does with the target login `name`, judged against the target's `logins` (sdk_names) and the names a
    signup may not take -> {"verdict": "create" | "overwrite" | "skip", "why", "reason", "existing": the login it
    meets, "sdkUid": that login's, "caseOnly"}. Without `overwrite` any login equal to it in any letter case is a
    conflict (nameTaken; caseOnly = only in another case), and a name the move would create must be one a signup could
    take and not digits alone (nameNotAllowed). With it, the login must exist exactly, as an account of type 1 (noTarget
    otherwise): another letter case does not matter. Pure."""
    exact = next((row for row in logins if row[1] == name and row[2] == 1), None) \
        or next((row for row in logins if row[1] == name), None)
    fold = name.casefold()
    case = next((row for row in logins if isinstance(row[1], str) and row[1] != name and row[1].casefold() == fold), None)
    out = {"verdict": "skip", "why": None, "reason": None, "existing": None, "sdkUid": None, "caseOnly": None}
    if overwrite:
        if exact is None or exact[2] != 1:
            return dict(out, why="noTarget")
        return dict(out, verdict="overwrite", existing=exact[1], sdkUid=exact[0], caseOnly=False)
    if exact is not None or case is not None:
        met = exact or case
        return dict(out, why="nameTaken", existing=met[1], sdkUid=met[0], caseOnly=exact is None)
    why = migrate_new_name_problem(name, reserved)
    if why:
        return dict(out, why="nameNotAllowed", reason=why[1])
    return dict(out, verdict="create")


def migrate_stand_in(planned, earlier, uid):
    """(the uid a new account's checks run against, whether it is the predicted one): what t_player_uid hands out next
    (`planned`, _next_game_uid) after the `earlier` new accounts of the run; the source's uid plus one when that
    cannot be read, as do_account_copy. Pure."""
    if planned is None or planned + earlier > GAME_UID_MAX:
        return (uid + 1 if uid < GAME_UID_MAX else uid - 1), False
    return planned + earlier, True


def migrate_uid_free(target, uid):
    """Whether the source's game uid can stay a new account's on the target: no t_player_uid row of it, no save, block
    or home row, no row of it in the config database's per-uid tables (hk4e_db_config: a table a version has not holds
    none; one that keeps no column `uid` cannot be judged) and no key naming it in redis db 7. Only reads; what cannot
    be asked counts as not free: the account then gets the next free uid, and says so."""
    shard = uid % 10
    try:
        if _mysql_q(target, "SELECT uid FROM t_player_uid WHERE uid=%d" % uid):
            return False
        for table in ("t_player_data", "t_block_data", "t_home_data"):
            if _mysql_q(target, "SELECT uid FROM %s_%d WHERE uid=%d LIMIT 1" % (table, shard, uid)):
                return False
        columns = {}
        for line in _mysql_q(target, "SELECT TABLE_NAME, COLUMN_NAME FROM information_schema.COLUMNS WHERE "
                                     "TABLE_SCHEMA='hk4e_db_config' AND TABLE_NAME IN (%s)"
                                     % ", ".join("'%s'" % t for t in _MIGRATE_UID_TABLES)).splitlines():
            table, _tab, column = line.partition("\t")
            columns.setdefault(table.strip(), set()).add(column.strip())
        for table, names in columns.items():
            if "uid" not in names or _mysql_q(target, "SELECT uid FROM %s WHERE uid=%d LIMIT 1" % (table, uid),
                                              db="hk4e_db_config"):
                return False
        pw = redis_password(target)
        args, env = _exec_args("redis", ["redis-cli", "-n", "7", "--scan", "--pattern", "*{%d}*" % uid],
                               {"REDISCLI_AUTH": pw} if pw else None)
        r = _run_capped(["docker", "compose", "--project-directory", stack_dir(target)] + args,
                        timeout=T_MIGRATE_DOCKER, env=env)
        return r.returncode == 0 and not (r.stdout or "").strip() and not _password_dropped(env, r)
    except AgentError:
        return False


def migrate_save_age(target, uid):
    """Seconds since the game uid's save on the target (copy_save's own question), None without a save."""
    age = _mysql_q(target, "SELECT TIMESTAMPDIFF(SECOND, last_save_time, NOW()) FROM t_player_data_%d WHERE uid=%d"
                   % (uid % 10, uid))
    return int(age) if re.fullmatch(r"-?[0-9]+", age or "") else None


def migrate_dest_blobs(target, uid):
    """{root: its stored blob, None without a row} of the existing account of the game uid `uid` on the target -- what
    an overwrite keeps of it (migrate_context's `dest`): the main save and the home row."""
    def blob(table):
        b64 = _mysql_q(target, "SELECT TO_BASE64(bin_data) FROM %s_%d WHERE uid=%d" % (table, uid % 10, uid)) \
            .replace("\\n", "").replace("\n", "")
        return base64.b64decode(b64) if b64 and b64 != "NULL" else None
    return {SAVE_MAIN_ROOT: blob("t_player_data"), "HomeDataBin": blob("t_home_data")}


def _migrate_ids(values):
    values = list(values)
    return {"n": len(values), "ids": values[:MIGRATE_IDS_MAX]}


def migrate_entry(login):
    """One account's entry of a move's result, nothing said of it yet."""
    return {"from": login, "srcUid": None, "nickname": None, "level": None, "to": None, "verdict": "skip", "why": None,
            "reason": None, "existing": None, "existingUid": None, "existingNickname": None, "existingLevel": None,
            "caseOnly": None, "dstUid": None, "wouldGetUid": None, "keepsUid": None, "relocated": None, "dropped": 0,
            "others": 0, "cut": [], "settled": _migrate_ids(()), "dungeons": _migrate_ids(()),
            "serverRemoves": {"blocks": 0, "scenes": 0, "marks": 0}, "expiring": _migrate_ids(()),
            "expiryOther": _migrate_ids(()), "gachaUnknown": _migrate_ids(()), "kept": {}, "unknownIds": {},
            "password": None, "passwordWhy": None, "passwordNeeded": False, "backup": False, "online": None}


def migrate_report_into(entry, report):
    """migrate_transform's report, as an entry of the result says it (MIGRATE_IDS_MAX ids of a list, its whole count)."""
    entry.update(relocated=report["relocated"], dropped=report["dropped"], others=report["others"],
                 cut=[{"activity": c["activity"], "conds": _migrate_ids(c["conds"])} for c in report["cut"]],
                 settled=_migrate_ids(report["settled"]), dungeons=_migrate_ids(report["dungeons"]),
                 serverRemoves=dict((k, len(v)) for k, v in report["serverRemoves"].items()),
                 expiring=_migrate_ids(report["expiring"]), expiryOther=_migrate_ids(report["expiryOther"]),
                 gachaUnknown=_migrate_ids(report["gachaUnknown"]),
                 unknownIds=OrderedDict((c, _migrate_ids(ids)) for c, ids in report["unknownIds"].items()))


def _migrate_skip(entry, why, reason=None):
    entry.update(verdict="skip", why=why, reason=reason)
    return entry


class _MigrateCheckLog:
    """Where copy_check's lines go in a move's check: its entry says what they say, its WARNINGs reach the job."""

    def __init__(self, job):
        self.job = job

    def log(self, msg):
        if str(msg).startswith("WARNING"):
            self.job.log(msg)


def migrate_try_save(rows, ctx, uid, dst, fresh, dest, job, entry):
    """One account's source rows against the destination uid `dst`, nothing written: the transform, its post-condition
    and copy_save's byte checks (copy_check) -> the rows made the target's, None when the save cannot move -- the entry
    then says why (clientUnknown, refused). A plan that names another field at a path a step walks is no account's
    fault: AgentError 500, nothing is moved."""
    try:
        new_rows, report = migrate_transform(rows, dict(ctx, uid=uid, dst=dst, fresh=fresh, dest=dest))
    except _SaveSchemaInvalid as e:
        raise AgentError(500, str(e))
    migrate_report_into(entry, report)
    if new_rows is None:
        _migrate_skip(entry, report["why"], report["reason"])
        return None
    try:
        checked = copy_check(ctx["plan"], _mig_unwrap(new_rows["player"]["bin_data"])[0], uid, dst, _MigrateCheckLog(job),
                             uid == dst, version=ctx["target"])
    except AgentError as e:
        _migrate_skip(entry, "refused", e.message)
        return None
    entry.update(others=entry["others"] + checked["drops"], kept=checked["kept"])
    return new_rows


def migrate_password_fields(entry, keep, verify, stored):
    """What an entry says of a password: only an account the move creates can bring its own (`keep`), a bcrypt hash of
    the source's sdk (`stored`, bytes or None) -- and it needs one, on a target that verifies passwords (`verify`), when
    it does not. An account the move goes over keeps the one it has. Pure."""
    if entry["verdict"] == "overwrite" and keep:
        entry.update(password="notCopied", passwordWhy="an existing account keeps its own password")
    if entry["verdict"] != "create":
        return
    if keep:
        text = stored.decode("latin-1") if stored else ""
        if BCRYPT_RE.match(text):
            entry["password"] = "copied"
        else:
            entry.update(password="notCopied", passwordWhy="the old server holds no password for it that can be moved")
    entry["passwordNeeded"] = bool(verify) and entry["password"] != "copied"


def migrate_check_account(target, job, req, st, names, item):
    """One account of the source phase -> its entry: read, judged by its name (migrate_name_verdict) and tried as the
    save the target would get (migrate_try_save) -- against the uid an overwrite writes, the source's own where keepUid
    finds it free, else the stand-in of a new account. A check takes at most MIGRATE_ACCOUNTS_MAX accounts with a save.
    `st` = do_migrate's state; the rows of an account that is to move are left in st["read"]."""
    facts, count = st["facts"], st["count"]
    entry = migrate_entry(item["from"])
    login = item["login"]
    if login is None:
        return _migrate_skip(entry, "notInSource")
    sdk_uid, name, typ = login
    if not name or typ == 0:
        return _migrate_skip(entry, "guest")
    row = st["chars"].get(str(sdk_uid))
    if row is None:
        return _migrate_skip(entry, "noSave")
    uid = row["uid"]
    entry.update(srcUid=uid, nickname=row["nickname"], level=row["level"])
    if item["implicit"] and count["read"] >= MIGRATE_ACCOUNTS_MAX:
        return _migrate_skip(entry, "notChecked")
    count["read"] += 1
    to = item["to"] or name
    entry["to"] = to
    try:
        rows = migrate_read_account(names, uid)
    except _MigrateReadTooLarge:
        return _migrate_skip(entry, "refused", "too large to move in one piece")
    except ValueError:
        return _migrate_skip(entry, "refused", "its rows cannot be read")
    if rows is None:
        entry["to"] = None
        return _migrate_skip(entry, "noSave")
    if rows["player"].get("is_delete") == 1:
        entry["to"] = None
        return _migrate_skip(entry, "deleted")
    verdict = migrate_name_verdict(to, item["overwrite"], st["logins"], facts["reserved"])
    entry.update(verdict=verdict["verdict"], why=verdict["why"], reason=verdict["reason"],
                 existing=verdict["existing"], caseOnly=verdict["caseOnly"])
    met = st["targetChars"].get(str(verdict["sdkUid"])) if verdict["sdkUid"] is not None else None
    if met is not None:
        entry.update(existingUid=met["uid"], existingNickname=met["nickname"], existingLevel=met["level"])
    fold = to.casefold()
    if item["implicit"] and entry["verdict"] == "create" and fold in count["taken"]:
        _migrate_skip(entry, "batchDuplicate")
    dst, dest, keeps = None, None, False
    if entry["verdict"] == "overwrite" and met is not None:
        dst = entry["dstUid"] = met["uid"]
        if _uid_online(target, dst):
            _migrate_skip(entry, "targetOnline")
        else:
            age = migrate_save_age(target, dst)
            if age is not None and age < MIGRATE_RECENT_SAVE:
                _migrate_skip(entry, "targetRecent")
        dest = migrate_dest_blobs(target, dst)
    if req["keepUid"]:
        keeps = entry["keepsUid"] = entry["verdict"] == "create" and migrate_uid_free(target, uid)
    allocates = dst is None and not keeps  # a new uid: the account the move creates, or a target that never played
    if keeps:
        dst = entry["wouldGetUid"] = uid
    elif allocates:
        dst, predicted = migrate_stand_in(count["planned"], count["new"], uid)
        entry["wouldGetUid"] = dst if predicted else None
    wanted = entry["verdict"]
    if migrate_try_save(rows, st["ctx"], uid, dst, not item["overwrite"], dest, job, entry) is None:
        return entry
    if wanted == "create":
        count["taken"].add(fold)
    if allocates and wanted in ("create", "overwrite"):
        count["new"] += 1
    migrate_password_fields(entry, req["keepPassword"], facts["passwordVerify"], st["hashes"].get(sdk_uid))
    st["read"] = rows if wanted in ("create", "overwrite") else None
    return entry


def migrate_changes(entry, target, check):
    """What the move does to an account's save, as a job line says it: the things that are not what it was. Pure."""
    def said(done, would):
        return would if check else done

    out = []
    moved = entry["relocated"]
    if moved:
        out.append(said("moved from scene %d to Teyvat" % moved["from"], "it would move from scene %d to Teyvat"
                        % moved["from"]))
    if entry["dropped"]:
        out.append(said("%d field(s) version %s's saves do not have dropped" % (entry["dropped"], target),
                        "%d field(s) version %s's saves do not have would be dropped" % (entry["dropped"], target)))
    for cut in entry["cut"]:
        out.append(said("the record of event %d cut (%d condition id(s) %s does not define)"
                        % (cut["activity"], cut["conds"]["n"], target),
                        "the record of event %d would be cut (%d condition id(s) %s does not define)"
                        % (cut["activity"], cut["conds"]["n"], target)))
    if entry["settled"]["n"]:
        out.append(said("%d settled event record(s) dropped" % entry["settled"]["n"],
                        "%d settled event record(s) would be dropped" % entry["settled"]["n"]))
    if entry["dungeons"]["n"]:
        out.append(said("%d record(s) of domains %s does not have dropped" % (entry["dungeons"]["n"], target),
                        "%d record(s) of domains %s does not have would be dropped" % (entry["dungeons"]["n"], target)))
    gone = [(entry["serverRemoves"]["blocks"], "scene record(s)"), (entry["serverRemoves"]["scenes"],
                                                                    "domain scene record(s)"),
            (entry["serverRemoves"]["marks"], "map pin(s)"), (entry["expiring"]["n"], "expired item(s)")]
    gone = ["%d %s" % g for g in gone if g[0]]
    if gone:
        text = ", ".join(gone[:-1]) + " and " + gone[-1] if len(gone) > 1 else gone[0]
        out.append(said("at the first login the server discards %s" % text,
                        "at the first login the server would discard %s" % text))
    if entry["gachaUnknown"]["n"]:
        ids = ", ".join(str(i) for i in entry["gachaUnknown"]["ids"])
        out.append(said("wish banners %s unknown to %s -- kept" % (ids, target),
                        "wish banners %s unknown to %s would be kept" % (ids, target)))
    return out


def migrate_line(entry, target, check):
    """The one line a job gives an account; a check's says CHECK: and what would happen. Pure."""
    who = "Account '%s'" % entry["from"] if entry["from"] else "An account without a name"
    if entry["srcUid"] is not None:
        char = " %s" % entry["nickname"] if entry["nickname"] else ""
        lv = ", Lv %s%s" % (entry["level"], char) if entry["level"] is not None else char and "," + char
        who += " (source uid %d%s)" % (entry["srcUid"], lv)
    head = "CHECK: " if check else ""
    if entry["verdict"] == "skip":
        why = entry["reason"] or _MIGRATE_SKIP_TEXTS.get(entry["why"], entry["why"]) % {"target": target}
        return "%s%s: skipped -- %s." % (head, who, why)
    goes = "new account '%s'" % entry["to"] if entry["verdict"] == "create" \
        else "existing account '%s' (its save replaced, a backup kept)" % entry["to"]
    changes = "; ".join(migrate_changes(entry, target, check))
    return "%s%s %s %s%s." % (head, who, "would go to" if check else "->", goes, ": " + changes if changes else "")


def _migrate_items(req):
    return [dict(a, implicit=False, login=None) for a in req["accounts"] or ()]


def migrate_state(req):
    """do_migrate's state, what phase T goes on from: "src" (the source's folder), "build" (the version its server
    program is), "man" (the target's manifest), "ctx" (migrate_context's, with the target's facts; a uid, a destination
    and fresh / dest are the account's: dict(ctx, uid=U, dst=D, fresh=..., dest=...)), "facts", "logins" (the target's,
    sdk_names, as read at the check), "chars" / "targetChars" ({account_uid text: parse_accounts_characters row} of both
    servers' type-1 accounts), "items" (the accounts in order: {"from", "to", "overwrite", "implicit", "login": (sdk uid,
    name, type) or None}), "entries" (their entries, in that order), "spooled" (the places in those lists of the
    accounts whose rows wait in the spool: migrate_spool_get(job.id, n)), "hashes" ({sdk uid: password hash} of a real
    run with keepPassword -- memory only), "verify" (passwordVerify of the result), "stopped", "failed" (None or
    {"from", "reason"}) and "leftRegistered" ([{"name", "inGame"}]), the last three as the result says them."""
    return {"src": None, "build": req["source"]["version"], "man": None, "ctx": None, "facts": None, "logins": [],
            "chars": {}, "targetChars": {}, "items": _migrate_items(req), "entries": [], "spooled": [], "hashes": {},
            "read": None, "count": {"read": 0, "new": 0, "taken": set(), "planned": None},
            "verify": {"source": None, "target": None}, "stopped": False, "failed": None, "leftRegistered": []}


def migrate_mark_unreached(req, st):
    """The accounts a stop left unread: not checked in a check, not moved in a real run."""
    for item in st["items"][len(st["entries"]):]:
        entry = migrate_entry(item["from"])
        if req["dryRun"]:
            _migrate_skip(entry, "notChecked")
        else:
            entry.update(verdict="notDone", to=item["to"] or item["from"])
        st["entries"].append(entry)


def migrate_result(target, req, st):
    """The job's result (docs/AGENT-API.md, Account migration): the same object for a check and a real run. Names no
    box path, no password or hash, no e-mail, no IP."""
    entries = st["entries"]
    totals = dict((k, 0) for k in ("create", "overwrite", "skip", "moved", "failed", "notDone"))
    unread = 0
    for entry in entries:
        totals[entry["verdict"]] += 1
        unread += entry["why"] == "notChecked" or entry["verdict"] == "notDone"
    return {"dryRun": req["dryRun"], "target": target,
            "source": {"kind": req["source"]["kind"], "version": st["build"]}, "passwordVerify": dict(st["verify"]),
            "keepPassword": req["keepPassword"], "keepUid": req["keepUid"], "listed": len(entries),
            "checked": len(entries) - unread, "notChecked": unread, "totals": totals, "stopped": st["stopped"],
            "failed": st["failed"], "leftRegistered": st["leftRegistered"], "accounts": entries[:MIGRATE_LIST_MAX]}


def migrate_phase_s(target, job, req, st):
    """The source phase of a move: nothing of the target or the source is written, no _op_lock is held and the job
    yields. The target, the source's folder and what its server program is, the allow rule, the source at rest and
    its database service; the target's facts and logins, read once; the stamps, the reader over a copy of the source's
    mysql/, the stamps again and the guard once more; each account checked as the save the target would get, and a
    real run's rows spooled as read; the account database's stamp a third time; the reader gone on every exit path.
    _MigrateStopped on a stop (it is looked for between every step); AgentError for every refusal: nothing was moved."""
    src_kind = req["source"]["kind"]
    man = st["man"] = _migrate_manifest(target)
    job.log("Checking version %s..." % target)
    migrate_target_ready(target, man)
    _migrate_stop_point()
    src = st["src"] = migrate_source_folder(req)
    migrate_folder_shape(src)
    build = server_build_of(src)
    if src_kind == "version" and build != req["source"]["version"]:
        raise AgentError(409, "The folder of version %s holds the server of version %s -- choose version %s, or that "
                              "folder." % (req["source"]["version"], build, build))
    st["build"] = build
    ctx = st["ctx"] = migrate_context(target, build, 0, 0, True, None, mail=False, man=man)
    job.log("The source is a server of version %s." % build)
    _migrate_stop_point()
    migrate_at_rest(src, job)
    _migrate_stop_point()
    image = migrate_image(target, src)
    _migrate_stop_point()
    job.log("Reading the tables and the accounts of version %s..." % target)
    facts = st["facts"] = ctx["facts"] = migrate_target_facts(target, man)
    st["logins"] = _migrate_sdk_read(lambda: sdk_names(_sdk_db_path(target)), 500, "The stack's")
    rows, why = _accounts_read_characters(target, T_MIGRATE_QUERY)
    if rows is None:
        raise AgentError(500, "%s Nothing was moved." % why)
    st["targetChars"] = dict((r["account"], r) for r in rows if r["type"] == 1)
    st["count"]["planned"] = _next_game_uid(target)
    _migrate_stop_point()
    stamp, sdk_stamp = migrate_stamp(os.path.join(src, "mysql")), migrate_sdk_stamp(src)
    size = sum(v[0] for v in stamp.values() if v)
    src_db = os.path.join(src, "sdk", "data", "sdk.db")
    logins = _migrate_sdk_read(lambda: sdk_names(src_db), 409, "The source's")
    st["verify"] = {"source": sdk_password_verify_at(src), "target": facts["passwordVerify"]}
    if req["accounts"] is None:
        st["items"] = [{"from": name, "to": None, "overwrite": False, "implicit": True, "login": (uid, name, typ)}
                       for uid, name, typ in logins]
    else:
        by_name = {}
        for row in logins:
            by_name.setdefault(row[1], row)
        for item in st["items"]:
            item["login"] = by_name.get(item["from"])
    if req["keepPassword"]:
        st["hashes"] = _migrate_sdk_read(lambda: sdk_password_hashes(src_db, [
            i["login"][0] for i in st["items"] if i["login"] is not None and i["login"][2] == 1]), 409, "The source's")
    _migrate_stop_point()
    names = migrate_object_names(job.id)
    try:
        job.log("Looking at docker's disk and memory...")
        migrate_probe(target, names, image, size)
        _migrate_stop_point()
        job.log("Copying the source's database (%s) -- the source is only read..." % _migrate_size(size))
        migrate_copy(names, image, src)
        differs = _migrate_stamp_diff(stamp, migrate_stamp(os.path.join(src, "mysql")))
        if differs:
            raise AgentError(409, "The source's database folder changed while it was copied (%d file(s)) -- something "
                                  "writes into it; nothing was moved." % differs)
        migrate_at_rest(src, job)
        _migrate_stop_point()
        job.log("Starting the reader...")
        migrate_start_reader(names, image)
        job.log("Reading the source's accounts...")
        try:
            chars = parse_accounts_characters(migrate_query(names, accounts_characters_sql()))
        except _MigrateReadTooLarge:
            raise AgentError(500, "The source's account list is too large to read in one piece -- nothing was moved.")
        st["chars"] = dict((r["account"], r) for r in chars if r["type"] == 1)
        for item in st["items"]:
            _migrate_stop_point()
            st["read"] = None
            entry = migrate_check_account(target, job, req, st, names, item)
            n = len(st["entries"])
            st["entries"].append(entry)
            if not req["dryRun"] and st["read"] is not None:
                migrate_spool_put(job.id, n, entry, st["read"])
                st["spooled"].append(n)
            st["read"] = None
            # (an account a real run writes gets its one line when it is written: here nothing has happened to it)
            if entry["why"] != "notChecked" and (req["dryRun"] or entry["verdict"] == "skip"):
                job.log(migrate_line(entry, target, req["dryRun"]))
        differs = _migrate_stamp_diff(sdk_stamp, migrate_sdk_stamp(src))
        if differs:
            raise AgentError(409, "The source's account database changed while it was read (%d file(s)) -- something "
                                  "writes into it; nothing was moved." % differs)
    except ValueError as e:
        raise AgentError(500, "The reader's answer cannot be read (%s) -- nothing was moved." % e)
    finally:
        job.log("Removing the reader...")
        migrate_reader_remove(job.id, job)


# -- moving progress to another version (migration): the writes --
# A real run goes on from what the source phase left (migrate_state) and its spool, the reader gone: ONE account per
# _op_lock hold, the job yielding between two, so a revive or a signup waits for one account at most. The target's
# account database is copied first. Each account is then registered (or its existing save looked at), given its game
# uid, transformed once with that uid from its rows as they were read, put into the scratch database relic_mig_<job> of
# the target's MySQL as one transaction of parsed values -- dump text never reaches the target -- and written from there
# by copy_save, which backs up what it replaces. The first write that fails stops the batch. In every outcome the tail
# runs: the moved accounts looked at for a player who entered meanwhile, then their password hashes, last, through the
# sdk container -- a target that verifies passwords lets nobody in before the progress is there --, then the scratch
# database goes. No service is booted, stopped or restarted, and nothing of the source is touched.

_MIGRATE_SCRATCH_RE = re.compile(r"relic_mig_[0-9]{10,16}_[0-9a-f]{4}\Z")
_MIGRATE_SHARD_TABLES = ("t_player_data", "t_block_data", "t_home_data")
# The columns of a player row in the scratch database, and how each is spelled there.
_MIGRATE_SCRATCH_COLUMNS = (("nickname", "text"), ("level", "number"), ("exp", "number"), ("vip_point", "number"),
                            ("json_data", "text"), ("bin_data", "blob"), ("extra_bin_data", "blob"),
                            ("data_version", "number"), ("tag_list", "text"), ("last_save_time", "time"),
                            ("before_login_bin_data", "blob"))
_COPY_BACKUP_LINE = "Destination progress backup: "  # how copy_save names the backup it made


def migrate_scratch_name(job_id):
    """The job's scratch database, made of its id: relic_mig_<digits>_<hex>. 500 for an id of another shape: the name
    reaches SQL."""
    name = "relic_mig_" + str(job_id).replace("-", "_")
    if not _MIGRATE_SCRATCH_RE.match(name):
        raise AgentError(500, "A move runs only under a job id of the agent's own making -- nothing was moved.")
    return name


def migrate_drop_scratch(version, job, keep=None):
    """Drop the scratch databases moves left in a version's MySQL, `keep` -- the running move's own -- excepted: an
    agent killed during a move leaves one. Only names of the scratch's exact shape go. One line per drop, silent when
    there is none, never fatal; MySQL must be up, so this runs at a move's first write and after the database stage of
    a Start or a provision, never at the agent's start."""
    try:
        for name in _mysql_q(version, "SHOW DATABASES LIKE 'relic\\_mig\\_%'").split():
            if name != keep and _MIGRATE_SCRATCH_RE.match(name):
                _mysql_q(version, "DROP DATABASE IF EXISTS `%s`" % name)
                job.log("Dropped the scratch database %s of a move that did not end." % name)
    except Exception as e:  # noqa: BLE001 -- a clean-up, never a reason to stop what called it
        job.log("WARNING: what an earlier move left in the database of version %s could not be dropped (%s) -- the next "
                "move or start tries again." % (version, _migrate_why(e)))


def migrate_scratch_ddl(scratch, shards):
    """The statements of a scratch database for the save shards `shards`: DDL alone, each one repeatable (a dying
    service: _write_copy_sql), the tables the player database's own. Pure."""
    sqls = ["CREATE DATABASE IF NOT EXISTS `%s` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;" % scratch]
    for shard in sorted(shards):
        for table in _MIGRATE_SHARD_TABLES:
            sqls.append("CREATE TABLE IF NOT EXISTS `%s`.`%s_%d` LIKE `%s`.`%s_%d`;"
                        % (scratch, table, shard, PLAYER_DB, table, shard))
    return sqls


def _migrate_sql_value(kind, value):
    """One value of a scratch row as SQL, made of what was parsed and nothing else: digits, hex, a time through
    FROM_UNIXTIME -- the moment of the write for a time the source does not hold --, NULL. Pure."""
    if kind == "time":
        return "FROM_UNIXTIME(%d)" % value if value and value > 0 else "NOW()"
    if value is None:
        return "NULL"
    if kind == "number":
        return "%d" % value
    if not value:
        return "''"  # 0x without digits is no literal
    return "CONVERT(0x%s USING utf8mb4)" % bytes(value).hex() if kind == "text" else "0x" + bytes(value).hex()


def migrate_scratch_rows(scratch, uid, rows):
    """The statements of one account in the scratch database, under the source's uid -- what copy_save reads --: ONE
    transaction that first clears the uid, so the second run of a service that died never meets a row of the first.
    `rows` = what migrate_transform made of the rows as read; every value goes through _migrate_sql_value. Pure."""
    shard = uid % 10
    sqls = ["START TRANSACTION;"]
    for table in _MIGRATE_SHARD_TABLES:
        sqls.append("DELETE FROM `%s`.`%s_%d` WHERE uid=%d;" % (scratch, table, shard, uid))
    player = rows["player"]
    sqls.append("INSERT INTO `%s`.`t_player_data_%d` (uid, %s) VALUES (%d, %s);" % (
        scratch, shard, ", ".join(c for c, _kind in _MIGRATE_SCRATCH_COLUMNS), uid,
        ", ".join(_migrate_sql_value(kind, player.get(c)) for c, kind in _MIGRATE_SCRATCH_COLUMNS)))
    for block in rows["blocks"]:
        sqls.append("INSERT INTO `%s`.`t_block_data_%d` (uid, block_id, data_version, bin_data) VALUES (%d, %s, %s, %s);"
                    % (scratch, shard, uid, _migrate_sql_value("number", block["block_id"]),
                       _migrate_sql_value("number", block["data_version"]), _migrate_sql_value("blob", block["bin_data"])))
    if rows["home"] is not None:
        sqls.append("INSERT INTO `%s`.`t_home_data_%d` (uid, bin_data, data_version) VALUES (%d, %s, %s);"
                    % (scratch, shard, uid, _migrate_sql_value("blob", rows["home"]["bin_data"]),
                       _migrate_sql_value("number", rows["home"]["data_version"])))
    sqls.append("COMMIT;")
    return sqls


def _migrate_why(e):
    """What a failed step of the writes says of itself: an AgentError's sentence, of anything else the system's words or
    its kind -- never its text, which may name a path."""
    if isinstance(e, AgentError):
        return e.message
    return getattr(e, "strerror", None) or e.__class__.__name__


def _migrate_sql(target, job, sqls, db=PLAYER_DB):
    """`sqls` as one private SQL file of the job's spool folder -- what an agent killed over it leaves goes with the
    spool (migrate_sweep), and a save is in there --, gone at once, through _write_copy_sql: its wait for a dying MySQL
    and its one retry serve the scratch database as they serve copy_save."""
    import tempfile
    try:
        fd, tmp = tempfile.mkstemp(suffix=".sql", dir=migrate_spool_dir(job.id))
    except OSError as e:
        raise AgentError(500, "The statements of the move could not be written (%s)." % _migrate_why(e))
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            f.write("\n".join(sqls) + "\n")
        _write_copy_sql(target, job, tmp, db=db)
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass  # the spool folder goes with the job


def sdk_db_backup(version, job):
    """A copy of the version's account database in the agent's backups folder, before a move writes anything: taken
    from a private copy (read_sqlite_copy: one no write of the sdk tore) with sqlite's own backup, private from its first
    byte, named migrate_<version without its dot>_sdk_<time>.db. One line, the file's name alone, as copy_save names its
    backup. AgentError 500 when it cannot be made, and nothing of it stays. -> the file's name."""
    bdir = os.path.join(_migrate_state_dir(), "backups")
    name = "migrate_%s_sdk_%s.db" % (version.replace(".", ""), time.strftime("%Y%m%d_%H%M%S"))
    path = os.path.join(bdir, name)

    def keep(con):
        out = sqlite3.connect(path)
        try:
            con.backup(out)
        finally:
            out.close()

    try:
        os.makedirs(bdir, exist_ok=True)
        protect_path(bdir, 0o700)  # full player saves live here -- not for every local user's eyes
        os.close(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600))
        protect_path(path, 0o600)
        _migrate_sdk_read(lambda: read_sqlite_copy(_sdk_db_path(version), keep), 500, "The stack's")
    except (AgentError, OSError) as e:
        try:
            os.remove(path)
        except OSError:
            pass
        if isinstance(e, AgentError):
            raise
        raise AgentError(500, "The stack's account database could not be backed up (%s) -- nothing was moved."
                         % _migrate_why(e))
    job.log("Account database backup: %s" % name)
    return name


def _migrate_held(job, step):
    """step() under _op_lock: the job does not yield while it holds the lock and yields again once it let go of it."""
    try:
        with _op_lock:
            job.yielding = False
            return step()
    finally:
        job.yielding = True


class _MigrateCopyLog:
    """The job as the writes of one account see it: every line goes on to it, and the name of the backup copy_save made
    is kept, for a failure after it to name. A wait for MySQL that ran out (_write_copy_sql) stays on this object, for
    the rollback of the same account."""

    def __init__(self, job):
        self.job, self.id, self.backup = job, job.id, None

    def log(self, msg):
        text = str(msg)
        if text.startswith(_COPY_BACKUP_LINE):
            self.backup = text[len(_COPY_BACKUP_LINE):]
        self.job.log(msg)


def migrate_writes_begin(target, job, st, scratch):
    """Before a real run's first account, under the lock: the target as the source phase found it, a copy of its account
    database -- before any write, whatever else the run asks --, what an earlier move left, the scratch database of
    the save shards this run's accounts need. An AgentError here ends the job with nothing moved."""
    job.log("Checking version %s before the first write..." % target)
    migrate_target_ready(target, st["man"])
    sdk_db_backup(target, job)
    migrate_drop_scratch(target, job, keep=scratch)
    _migrate_sql(target, job, migrate_scratch_ddl(scratch, set(st["entries"][n]["srcUid"] % 10 for n in st["spooled"])))


def migrate_game_uid(target, job, req, entry, sdk_uid, at):
    """The game uid of a new account the sdk has just registered, in at["dst"] as soon as a row of it exists: the row a
    first login made meanwhile (at["login"]: copy_save then judges the player, and a failure leaves that row alone), the
    source's uid where keepUid asks for it and migrate_uid_free finds it free -- the row dbgate would make, under that
    uid, read back --, else the next one, _allocate_game_uid's."""
    to, uid = entry["to"], entry["srcUid"]
    at["dst"] = _account_game_uid(target, job, sdk_uid, to, allocate=False)
    at["login"] = at["dst"] is not None
    if at["dst"] is None and req["keepUid"] and migrate_uid_free(target, uid):
        _mysql_q(target, "INSERT INTO t_player_uid (uid, account_type, account_uid, ext) "
                         "VALUES (%d, 1, '%d', '{\"reg_platform\":3}\\n')" % (uid, sdk_uid))
        at["dst"] = uid
        row = _mysql_q(target, "SELECT uid FROM t_player_uid WHERE account_type=1 AND account_uid='%d'" % sdk_uid)
        if row.split()[:1] != [str(uid)]:
            raise AgentError(500, "The game uid %d of '%s' did not read back." % (uid, to))
        job.log("Game uid %d kept for '%s'." % (uid, to))
    if at["dst"] is None:
        at["dst"] = _allocate_game_uid(target, job, sdk_uid, to)
    if req["keepUid"]:
        entry["keepsUid"] = at["dst"] == uid


def migrate_prepare_new(target, job, req, entry, at):
    """A new account, up to its game uid: the sdk's register page, then the exact login it must now hold. False when the
    account is skipped: the name was taken after all, or the page refuses it -- nothing was written for it. AgentError
    for what stops the batch: a page that does not answer, a login that does not appear."""
    to = entry["to"]
    try:
        _sdk_register(target, to, job)
    except AgentError as e:
        if e.status == 409:
            _migrate_skip(entry, "takenMeanwhile")
            return False
        if e.status == 400:
            _migrate_skip(entry, "refused", e.message)
            return False
        # A page that did not answer in time may have written the account all the same: a name left registered is
        # named, and one that cannot be looked at may be one.
        try:
            at["registered"] = sdk_exact_lookup(target, to) is not None
        except AgentError:
            at["registered"] = True
        raise
    at["registered"] = True
    found = sdk_exact_lookup(target, to)
    if found is None:
        raise AgentError(500, "Account '%s' did not appear after its registration -- it may be registered." % to)
    migrate_game_uid(target, job, req, entry, found[0], at)
    return True


def migrate_prepare_over(target, job, entry, judged, at):
    """The existing account an overwrite goes over: its game uid -- allocated when it never played --, offline and not
    saved moments ago (the check's verdicts again: nothing was written for it, the batch goes on), what it holds of its
    own that the save keeps (migrate_dest_blobs). False when the account is skipped."""
    exact, sdk_uid = judged["existing"], judged["sdkUid"]
    uid = _account_game_uid(target, job, sdk_uid, exact, allocate=False)
    if uid is not None:
        if _uid_online(target, uid):
            _migrate_skip(entry, "targetOnline")
            return False
        age = migrate_save_age(target, uid)
        if age is not None and age < MIGRATE_RECENT_SAVE:
            _migrate_skip(entry, "targetRecent")
            return False
    at["dst"] = _allocate_game_uid(target, job, sdk_uid, exact) if uid is None else uid
    at["dest"] = migrate_dest_blobs(target, at["dst"])
    return True


def migrate_save_mark(target, uid):
    """What tells a later write of a save from the one a move made: (MD5(bin_data), UNIX_TIMESTAMP(last_save_time)) as
    the database holds them, () without a row."""
    return tuple(_mysql_q(target, "SELECT MD5(bin_data), UNIX_TIMESTAMP(last_save_time) FROM t_player_data_%d WHERE uid=%d"
                          % (uid % 10, uid)).split())


def migrate_in_game(target, uid):
    """The presence key of a game uid, for a decision that must not be taken over a player: True or False, None when it
    cannot be asked. Never raises."""
    try:
        return bool(_uid_online(target, uid))
    except Exception:  # noqa: BLE001 -- the caller treats "cannot be asked" as "someone may be there"
        return None


def migrate_write_failed(target, log, item, entry, st, at, e):
    """A write that failed stops the batch. A new account's game side is rolled back and its name, which stays
    registered, is named -- unless a player may be on it: copy_save found one in the game, a first login made its row,
    or the presence key, asked right before the rollback, says one came in after those gates or cannot be asked. A
    player the game server holds in memory keeps what it has: a DELETE would orphan the save it writes when they leave,
    and a game uid left allocated is harmless. An overwrite is never rolled back: its transaction did not commit, or
    the failure names the backup of what the account held. Nothing here may stop the report of the accounts before it:
    a rollback that raises leaves the uid where it is."""
    reason = _migrate_why(e)
    in_game = at["login"] or (isinstance(e, AgentError) and e.status == 409 and reason.startswith("The destination "))
    seen = True if in_game else None
    if item["overwrite"]:
        if log.backup and reason.startswith("Verification failed"):
            reason = "%s -- what it held is in the backup %s" % (reason.rstrip("."), log.backup)
    elif at["registered"]:
        if at["dst"] is not None and not in_game:
            seen = migrate_in_game(target, at["dst"])
            in_game = seen is not False
            try:
                if not in_game:
                    _signup_rollback(target, log, at["dst"], entry["to"])
                    at["dst"] = None
            except Exception as ex:  # noqa: BLE001 -- the first reason stands; a uid left allocated is harmless
                log.log("WARNING: the game side of '%s' could not be rolled back (%s)."
                        % (entry["to"], _migrate_why(ex).rstrip(".")))
        st["leftRegistered"].append({"name": entry["to"], "inGame": in_game})
    entry.update(verdict="failed", why=None, reason=reason, dstUid=at["dst"], wouldGetUid=None,
                 backup=log.backup is not None)
    if seen:
        entry["online"] = True
    st["failed"] = {"from": item["from"], "reason": reason}
    log.log("WARNING: The move stopped at '%s': %s -- the accounts before it moved, the ones after it were not touched."
            % (item["from"], reason.rstrip(".")))


def migrate_write_account(target, job, req, st, n, scratch, moved):
    """The account at place `n` of a real run, under _op_lock: the stop flag, the target's logins read again (a signup
    may have taken the name), the account made ready (migrate_prepare_new / _over), its rows as read transformed once,
    with the real uid, and checked, the scratch rows, copy_save, the mark of what it wrote (migrate_save_mark, into
    `moved` with the place). -> False when the batch ends here, stopped or failed; a skip goes on."""
    if _migrate_cancel.is_set():
        job.log("Stopped on request -- the accounts not written yet stay as they are.")
        st["stopped"] = True
        return False
    item, entry = st["items"][n], st["entries"][n]
    uid, over = entry["srcUid"], item["overwrite"]
    at = {"registered": False, "login": False, "dst": None, "dest": None}
    log = _MigrateCopyLog(job)
    try:
        rows = migrate_spool_get(job.id, n)[1]
        logins = _migrate_sdk_read(lambda: sdk_names(_sdk_db_path(target)), 500, "The stack's",
                                   after="the account was not moved")
        judged = migrate_name_verdict(entry["to"], over, logins, st["facts"]["reserved"])
        if judged["verdict"] == "skip":
            entry.update(existing=judged["existing"], caseOnly=judged["caseOnly"])
            _migrate_skip(entry, "takenMeanwhile" if judged["why"] == "nameTaken" else judged["why"], judged["reason"])
            ready = False
        else:
            ready = migrate_prepare_over(target, job, entry, judged, at) if over \
                else migrate_prepare_new(target, job, req, entry, at)
        if not ready:
            job.log(migrate_line(entry, target, False))
            return True
        dst = at["dst"]
        new_rows = migrate_try_save(rows, st["ctx"], uid, dst, not over, at["dest"], job, entry)
        if new_rows is None:
            raise AgentError(500, entry["reason"] or "its save cannot be moved")
        _migrate_sql(target, log, migrate_scratch_rows(scratch, uid, new_rows), db=scratch)
        copied = copy_save(target, log, uid, dst, src_db=scratch)
    except Exception as e:  # noqa: BLE001 -- the accounts before it moved: the report must reach the admin
        migrate_write_failed(target, log, item, entry, st, at, e)
        return False
    try:
        mark = migrate_save_mark(target, dst)
    except Exception:  # noqa: BLE001 -- the account is moved; the look at the presence key still stands
        mark = None
    job.log(migrate_line(entry, target, False))
    entry.update(verdict="moved", dstUid=dst, wouldGetUid=None, backup=bool(copied.get("backup")))
    moved.append((n, mark))
    return True


def migrate_race_check(target, job, entry, mark):
    """A moved account, after the wait, without the lock: a player who entered before its write may be held in the game
    server's memory, and that write over the moved progress when they leave. In the game now, or a save that is not
    the one the move wrote (`mark`, None when it could not be read) -> online and a WARNING; the source is untouched,
    so a second move with overwrite is always possible."""
    dst = entry["dstUid"]
    try:
        seen = _uid_online(target, dst) or (mark is not None and migrate_save_mark(target, dst) != mark)
    except Exception as e:  # noqa: BLE001 -- the account is moved: the report must reach the admin
        job.log("WARNING: whether '%s' was in the game right after its progress was written could not be looked at (%s)."
                % (entry["to"], _migrate_why(e).rstrip(".")))
        return
    entry["online"] = bool(seen)
    if seen:
        job.log("WARNING: '%s' was in the game right after its progress was written -- if the player entered before, the "
                "game may write over the moved progress when they leave: ask them to leave, check, and move it again "
                "with Overwrite." % entry["to"])


def migrate_write_hash(target, job, st, n):
    """The password hash of a moved account, under the lock. A failure leaves the account moved and says so; the rest go
    on."""
    entry = st["entries"][n]
    try:
        sdk_store_hash_in_sdk(target, entry["to"], st["hashes"][st["items"][n]["login"][0]])
        job.log("The password of '%s' moved with it." % entry["to"])
    except Exception as e:  # noqa: BLE001 -- the progress is in place, and no hash reaches a line
        why = _migrate_why(e)
        entry.update(password="notCopied", passwordWhy=why, passwordNeeded=bool(st["facts"]["passwordVerify"]))
        job.log("WARNING: the password of '%s' did not move (%s) -- the account is moved." % (entry["to"], why.rstrip(".")))


def migrate_tail(target, job, st, moved):
    """What every outcome of a real run still owes the accounts it moved: MIGRATE_RACE_WAIT after the last write, the
    race check (reads only: no lock), then each password hash under the lock -- last, so a target that verifies passwords
    lets nobody in before the progress is in place."""
    if not moved:
        return
    _migrate_pause(MIGRATE_RACE_WAIT)
    for n, mark in moved:
        migrate_race_check(target, job, st["entries"][n], mark)
    for n, _mark in moved:
        if st["entries"][n]["password"] == "copied":
            _migrate_held(job, lambda: migrate_write_hash(target, job, st, n))


def migrate_settle(req, st, todo):
    """What the entries of accounts a real run did not move say once it ended: not done, for those it never reached;
    of a password, only that an account left registered has none of its own."""
    for n in todo:
        entry = st["entries"][n]
        if entry["verdict"] in ("create", "overwrite"):
            entry["verdict"] = "notDone"
        if entry["verdict"] != "moved":
            left = any(r["name"] == entry["to"] for r in st["leftRegistered"])
            keep = left and req["keepPassword"]
            entry.update(password="notCopied" if keep else None, passwordWhy="its move did not finish" if keep else None,
                         passwordNeeded=left and bool(st["facts"]["passwordVerify"]))


def migrate_drop_own(target, job, scratch):
    """The scratch database gone, never fatal: what stays is migrate_drop_scratch's at the next move or Start."""
    try:
        _mysql_q(target, "DROP DATABASE IF EXISTS `%s`" % scratch)
    except Exception as e:  # noqa: BLE001 -- the job's own outcome stands
        job.log("WARNING: the scratch database %s could not be dropped (%s) -- the next move or start of version %s drops "
                "it." % (scratch, _migrate_why(e).rstrip("."), target))


def migrate_phase_t(target, job, req, st):
    """The writes of a real run (the section's comment), from what the source phase left in `st` (migrate_state) and the
    spool. Nothing to write: nothing is touched, no backup, no scratch database. An AgentError before the first account
    ends the job with nothing moved; from there on the job ends done with its report -- `stopped`, `failed`,
    `leftRegistered` -- whatever happens to an account, and `finally` drops the scratch database. -> the result."""
    todo = list(st["spooled"])
    if not todo:
        job.log("Nothing to move: no account passed its check.")
        return migrate_result(target, req, st)
    scratch = migrate_scratch_name(job.id)
    moved = []
    try:
        _migrate_held(job, lambda: migrate_writes_begin(target, job, st, scratch))
        for n in todo:
            if not _migrate_held(job, lambda: migrate_write_account(target, job, req, st, n, scratch, moved)):
                break
        migrate_settle(req, st, todo)
        migrate_tail(target, job, st, moved)
    finally:
        _migrate_held(job, lambda: migrate_drop_own(target, job, scratch))
    result = migrate_result(target, req, st)
    totals = result["totals"]
    job.log("%d account(s) moved, %d failed, %d not moved, %d skipped."
            % (totals["moved"], totals["failed"], totals["notDone"], totals["skip"]))
    return result


def do_migrate(target, job, req):
    """POST /server/migrate (job `migrate`, lock=False). The source phase (migrate_phase_s) yields and holds no lock; a
    check ends with it -- nothing registered, allocated or written on the target, no scratch database, no backup, no
    spool, the reader and its volume gone --, a real run goes on into the writes (migrate_phase_t). A stop is never an
    error: the job ends done with `stopped`, a real run's accounts not done. Every refusal of the source phase is an
    error: nothing was written. A job's error reaches every client of GET /jobs/<id> and an OSError's text names its
    file, so such a failure is said in the move's own words. The job boots, stops and restarts no service, of the
    target or the source."""
    migrate_object_names(job.id)  # the id reaches an argv and a folder's name: its shape first
    _migrate_cancel.clear()
    job.yielding = True
    st = migrate_state(req)
    try:
        migrate_sweep(keep=job.id)
        try:
            migrate_phase_s(target, job, req, st)
        except _MigrateStopped:
            job.log("Stopped on request -- nothing was moved.")
            st["stopped"] = True
            if not req["dryRun"]:
                migrate_settle(req, st, range(len(st["entries"])))
            migrate_mark_unreached(req, st)
        if req["dryRun"] or st["stopped"]:
            result = migrate_result(target, req, st)
            if req["dryRun"] and not st["stopped"]:
                job.log("CHECK: %d account(s) would be created, %d overwritten, %d skipped (%d of them not checked) -- "
                        "nothing was moved." % (result["totals"]["create"], result["totals"]["overwrite"],
                                                result["totals"]["skip"], result["notChecked"]))
            return result
        return migrate_phase_t(target, job, req, st)
    except OSError as e:
        raise AgentError(500, "The move could not go on (%s) -- nothing was moved." % _migrate_why(e))
    finally:
        migrate_spool_remove(job.id)


# -- player self-service accounts --

NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{2,19}$")
PASSWORD_RE = re.compile(r"^[\x21-\x7e]{8,64}$")
RESERVED_PREFIXES = ("relic", "tpl", "admin", "gm")


def validate_account_name(name, reserved=()):
    """None when the name is acceptable, else (code, reason): a PUBLIC_ERROR_CODES code and a
    short English phrase."""
    if not isinstance(name, str) or not NAME_RE.match(name):
        return ("name_invalid",
                "name must be 3-20 characters: letters, digits, '_', '.', '-' (starting with a letter or digit)")
    low = name.lower()
    if any(low.startswith(p) for p in RESERVED_PREFIXES) or low in {str(r).lower() for r in reserved if r}:
        return "name_reserved", "that name is reserved"
    return None


def reserved_names(version):
    man = read_manifest(version) or {}
    return [man.get("account") or ""]


def template_record_ready(rec):
    """One `templates` record ({md5, createdAt, error}) says the database was created and its last
    creation did not fail. Pure: build_public_status applies it to the /status entry's record."""
    return isinstance(rec, dict) and bool(rec.get("createdAt")) and not rec.get("error")


def template_ready(version, template):
    """A progress template database was created on this stack and its last creation did not fail."""
    return template_record_ready((version_state(version).get("templates") or {}).get(template))


def progress_copy_refusal(version):
    """Why no save can be copied onto an account of `version`: the save schema its payload names cannot be used
    (save_plan), so copy_save refuses every copy; None when a copy may go ahead. An account creation from a
    progress template asks it before the name is registered -- a name registered first is never free again, and
    the account would be left without the progress it was created for."""
    return save_plan(version)[1]


def signup_quota_rules(ip, version, vp):
    """The signup quotas one request takes (per address, then server-wide), as enforce_limits rules."""
    return [("create-h:" + ip, 3, 3600, "quota_ip_hour"), ("create-d:" + ip, 5, 86400, "quota_ip_day"),
            ("create-h:*", 20, 3600, "quota_server_hour"),
            ("create-d:*:" + version, max(0, int(vp.get("maxPerDay", 50))), 86400, "quota_server_day")]


def namecheck_rules(ip):
    """The small budget of the pre-quota 'is this name taken' lookup (see Handler._public_create)."""
    return [("namecheck:" + ip, 6, 600, "rate_limited"), ("namecheck:*", 60, 600, "rate_limited_server")]


# -- accounts per launcher --
# A player may create up to maxPerPlayer accounts on a version (policy, 5 by default). "A player" is
# the launcher that asks: it sends `client`, a random id of its own, derived per server so two servers
# cannot match one launcher -- there is no per-player authentication on this friends-server API, and a
# new id (a reinstalled launcher) starts from zero, exactly like its own list of accounts does. A
# launcher that sends none is counted by its address. The names are kept per version in
# state.signupClients, tagged with the generation (provisionedAt) they were created in: a re-provision
# with the default save wipes the accounts, and with them what they counted. The admin's own account
# creation (do_account_create) never counts.

CLIENT_ID_RE = re.compile(r"^[A-Za-z0-9_-]{16,64}$")
SIGNUP_CLIENTS_MAX = 20000  # launchers remembered per version; the least recently seen goes first


def signup_client_key(raw, ip):
    """'c:<id>' for a well-formed launcher id, else 'ip:<address>'. Pure."""
    if isinstance(raw, str) and CLIENT_ID_RE.match(raw):
        return "c:" + raw
    return "ip:" + str(ip)


def _signup_gen(data, version):
    return ((data.get("versions") or {}).get(version) or {}).get("provisionedAt")


def signup_book_names(data, version, key):
    """The names `key` created on `version` in the current generation, from a loaded state. Pure."""
    books = data.get("signupClients")
    book = books.get(version) if isinstance(books, dict) else None
    if not isinstance(book, dict) or book.get("gen") != _signup_gen(data, version):
        return []
    names = (book.get("clients") or {}).get(key) if isinstance(book.get("clients"), dict) else None
    return [n for n in names if isinstance(n, str)] if isinstance(names, list) else []


def signup_book_add(data, version, key, name, cap=SIGNUP_CLIENTS_MAX):
    """Count `name` against `key` inside a loaded state (a book of another generation starts over;
    the key moves to the end, and past `cap` keys the least recently used goes). Pure but for
    mutating `data`. Returns the key's names."""
    books = data.get("signupClients")
    if not isinstance(books, dict):
        books = data["signupClients"] = {}
    gen = _signup_gen(data, version)
    book = books.get(version)
    if not isinstance(book, dict) or book.get("gen") != gen or not isinstance(book.get("clients"), dict):
        book = books[version] = {"gen": gen, "clients": {}}
    clients = book["clients"]
    names = clients.pop(key, None)
    names = [n for n in names if isinstance(n, str)] if isinstance(names, list) else []
    if name.lower() not in {n.lower() for n in names}:
        names.append(name)
    clients[key] = names
    while len(clients) > cap:
        clients.pop(next(iter(clients)))
    return names


def check_player_limit(version, key, vp):
    """403 account_limit once `key` has created the version's maxPerPlayer accounts. The state is
    readable here: an unreadable one already closed signups (get_policy fails closed)."""
    limit = vp.get("maxPerPlayer", MAX_PER_PLAYER_DEFAULT)
    try:
        used = len(signup_book_names(load_state(), version, key))
    except StateUnreadable:
        raise state_unreadable_error()
    if used >= limit:
        raise AgentError(403, "this launcher has already created %d account(s) on version %s -- the "
                              "server allows %d" % (used, version, limit), code="account_limit")
    return used


def record_signup(version, key, name):
    """Count a created account (best effort: one that exists but went uncounted only makes the limit
    looser -- it must never fail the signup that created it)."""
    try:
        with _state_lock:
            data = load_state()
            signup_book_add(data, version, key, name)
            save_state(data)
    except Exception as e:  # noqa: BLE001
        log_line("gio-agent: could not count the signup of '%s' against its launcher (%s) -- the "
                 "per-player limit does not see it." % (name, e))


def generated_password():
    return "".join(secrets.choice(string.ascii_letters + string.digits) for _ in range(16))


def _signup_rollback(version, job, uid, name=None):
    """Best effort: undo the GAME-side half of a signup whose progress copy failed, so the player is
    left with a clean fresh account instead of a half-written save. The sdk account itself STAYS --
    the agent never writes the stack's sdk.db (the sdk service holds it open, see _sdk_db_lookup), so
    the name remains registered and the player can log in and play; only the chosen progress is
    missing. `name` is the account's exact name, for the closing line only (the admin reads it live
    in the accountcreate job). Nothing here may raise: the caller is already failing and the
    original reason wins."""
    shard = uid % 10
    if getattr(job, "mysql_wait_expired", False):
        # The copy already waited its full budget for this service and it never came back: waiting
        # again would only hold the job slot (and the watchdog that could revive the stack) longer.
        job.log("Rollback: the database service is still down -- uid %d stays as it is." % uid)
        return
    try:
        if not mysql_reachable(version):
            # Whatever failed may have taken the database service with it (see copy_save): every DELETE
            # below would fail too, and the log would read as if the rollback itself were broken.
            wait_for_mysql(version, job, timeout=120)
    except Exception as e:  # noqa: BLE001 -- the look itself may fail, on a .env that names no password
        job.log("Rollback: the database service did not come back (%s) -- uid %d stays as it is."
                % (_migrate_why(e), uid))
        return
    for table in ("t_player_data_%d", "t_block_data_%d", "t_home_data_%d"):
        try:
            _mysql_q(version, "DELETE FROM %s WHERE uid=%d" % (table % shard, uid))
        except Exception as e:  # noqa: BLE001
            job.log("Rollback: could not clear %s for uid %d (%s)."
                    % (table % shard, uid, _short_err(e)))
    try:
        _mysql_q(version, "DELETE FROM t_player_uid WHERE uid=%d" % uid)
    except Exception as e:  # noqa: BLE001
        job.log("Rollback: could not release uid %d (%s) -- it stays allocated, which only means the "
                "account keeps that uid at first login." % (uid, _short_err(e)))
        return
    job.log("Rolled back: uid %d released and no save written, so %s is a plain fresh account."
            % (uid, ("'%s'" % name) if name else "the account"))


def do_signup(version, job, name, password, template, client_ip, refund=None, client=None):
    """Create a player account and, unless `template` is 'fresh', give it a template's progress.
    Everything is re-checked INSIDE the job (the request-time checks only filter the obvious):
    the stack must be up, the name must still be free, the template must still be allowed, the
    launcher must still be under the version's maxPerPlayer (`client` = its signup_client_key; the
    created account is counted against it the moment it is registered).
    `refund` = the signup quota rules the request took: handed back when the job fails BEFORE the
    registration (nothing was created) for any reason but a taken name -- a refunded 'name taken'
    would turn take + refund into a free name oracle -- or version_down: that probe is a docker exec
    of up to 30 s holding the job slot, so a free one would let failing signups keep admin jobs out
    while MySQL hangs. Never refunded once registration started."""
    job.log("Signup request from %s: name=%s version=%s template=%s" % (client_ip, name, version, template))
    try:
        policy = get_policy()
        vp = (policy["signup"]["versions"] or {}).get(version)
        if not policy["signup"]["enabled"] or vp is None:
            raise AgentError(403, "account creation is disabled on this server", code="signup_disabled")
        if template not in (vp.get("templates") or []):
            raise AgentError(400, "that template is not available on this server", code="template_unavailable")
        if client:
            check_player_limit(version, client, vp)
        why = validate_account_name(name, reserved_names(version))
        if why:
            raise AgentError(400, why[1], code=why[0])
        if not is_bootstrapped(version) or not mysql_reachable(version):
            raise AgentError(503, "this server version is not running right now", code="version_down")
        if _sdk_db_lookup(version, name) is not None:
            raise AgentError(409, "name taken", code="name_taken")
        if template != "fresh" and not template_ready(version, template):
            raise AgentError(503, "that progress template is not ready on this server", code="template_not_ready")
        unusable = progress_copy_refusal(version) if template != "fresh" else None
        if unusable:
            job.log("The save schema of version %s cannot be used (%s) -- no progress can be copied, nothing is "
                    "created." % (version, unusable))
            raise AgentError(503, "that progress template is not ready on this server", code="template_not_ready")
        verify = bool(version_state(version).get("passwordVerify"))
        if verify and not (isinstance(password, str) and PASSWORD_RE.match(password)):
            raise AgentError(400, "a password of 8-64 printable characters is required", code="password_required")
    except Exception as e:
        if refund and not (isinstance(e, AgentError) and e.code in ("name_taken", "version_down")):
            LIMITER.give(refund)
            job.log("Nothing was created -- the signup quota was handed back.")
        raise
    pwd = password if (isinstance(password, str) and PASSWORD_RE.match(password)) else generated_password()
    counted = (lambda exact: record_signup(version, client, exact)) if client else None
    return _register_and_seed(version, job, name, pwd, template, on_registered=counted)


def _register_and_seed(version, job, name, pwd, template, on_registered=None):
    """The half of an account creation that WRITES: register `name` with `pwd` through the sdk,
    then, unless `template` is 'fresh', allocate its game uid and copy the template's progress
    onto it. Shared by the player signup (do_signup) and the admin's creation (do_account_create);
    each caller has done its own checks first. `on_registered(exact_name)` runs as soon as the sdk
    account exists -- before the progress copy, which may fail and still leave the account there.
    Returns {name, uid, template, nickname}."""
    _sdk_register(version, name, job, password=pwd)
    acc = _sdk_db_lookup(version, name)
    if acc is None:
        raise AgentError(500, "the account did not appear after registration")
    exact = acc[1]
    if on_registered is not None:
        on_registered(exact)
    result = {"name": exact, "uid": None, "template": template, "nickname": None}
    if template == "fresh":
        job.log("Fresh account -- the game allocates the uid at first login.")
        return result
    # Past this point the sdk account EXISTS, so a failure may not leave the game database half
    # written: roll the game side back and say plainly that the account is there without the
    # progress. The name cannot be handed back (sdk.db is not ours to write), so it is never
    # reported as free again -- and a signup's quota stays spent, because something WAS created.
    uid = _account_game_uid(version, job, acc[0], exact, allocate=True)
    try:
        copy_save(version, job, 1, uid, src_db=template_db_name(template))
        nick = _mysql_q(version, "SELECT nickname FROM t_player_data_%d WHERE uid=%d" % (uid % 10, uid))
    except Exception as e:  # noqa: BLE001
        job.log("ERROR: the starting progress was NOT applied to '%s': %s" % (exact, _short_err(e)))
        _signup_rollback(version, job, uid, name=exact)
        raise AgentError(500, "the account was created, but the starting progress could not be "
                              "applied to it", code="progress_failed")
    result.update({"uid": uid, "nickname": nick.strip() or None})
    job.log("Account '%s' (uid %d) created from template '%s'." % (exact, uid, template))
    return result


# -- admin account creation --

def admin_create_preflight(b):
    """POST /server/account/create's synchronous refusals, before a job exists. Returns
    (version, name, password or None, template). Every refusal is a 400 with a public code, NEVER a
    404: on this route a 404 must keep meaning "an agent that does not know the route" to the
    launcher. The name obeys a signup's rules (reserved names and prefixes included); the template
    may be any the manifest ships -- whether it is imported on the stack is the job's 409."""
    version = str(b.get("version", "")).strip()
    check_known(version)
    name = b.get("name")
    name = name.strip() if isinstance(name, str) else ""
    why = validate_account_name(name, reserved_names(version))
    if why:
        raise AgentError(400, why[1], code=why[0])
    template = str(b.get("template") or "fresh").strip() or "fresh"
    if template != "fresh" and template not in {t["id"] for t in manifest_templates(version)}:
        raise AgentError(400, "that template is not available on this server", code="template_unavailable")
    password = b.get("password")
    if password is None or password == "":
        password = None
    elif not (isinstance(password, str) and PASSWORD_RE.match(password)):
        raise AgentError(400, "the password must be 8-64 printable characters", code="password_invalid")
    return version, name, password, template


def do_account_create(version, job, name, password, template):
    """The ADMIN creates a player account -- for themselves or a friend -- starting from 'fresh' or
    any progress template imported on this stack. No signup policy, no LIMITER, no quota: the bearer
    token is the authorisation. Everything is re-checked here, inside the job and under _op_lock
    (the preflight only refused a malformed request). The password never reaches a log line; the
    job result carries it only while the server verifies passwords (the admin must hand it to the
    player) -- admin jobs never enter PUBLIC_JOBS, and public_snapshot whitelists its fields anyway.
    With verification off a typed password is still stored (valid if verification is switched on
    later) but not returned."""
    require_state_readable()
    job.log("Admin account creation: name=%s version=%s template=%s" % (name, version, template))
    if not is_bootstrapped(version):
        raise AgentError(409, "version %s is not installed on this server" % version)
    if not mysql_reachable(version):
        raise AgentError(409, "version %s is not running -- start it first" % version, code="version_down")
    if _sdk_db_lookup(version, name) is not None:
        raise AgentError(409, "name taken", code="name_taken")
    if template != "fresh" and not template_ready(version, template):
        # Only NON-destructive ways out: a `default` prepare would also import the template, but it
        # wipes every player account on the stack.
        raise AgentError(409, "the progress template '%s' is not imported on the %s stack (never imported, "
                              "or its last import failed) -- import it (the launcher's Import button on "
                              "Server -> Players -> Create a player account, or POST /server/templates/ensure; "
                              "nothing is stopped) and retry" % (template, version),
                         code="template_not_ready")
    unusable = progress_copy_refusal(version) if template != "fresh" else None
    if unusable:
        raise AgentError(500, "The save schema of version %s cannot be used (%s) -- no progress can be copied, the "
                              "account is not created." % (version, unusable))
    verify = bool(version_state(version).get("passwordVerify"))
    pwd = password or generated_password()
    result = _register_and_seed(version, job, name, pwd, template)
    result.update(passwordVerify=verify, passwordGenerated=bool(verify and password is None),
                  password=(pwd if verify else None))
    return result


# -- secrets (stack passwords and the MUIP sign key) --

SECRET_KNOBS = ("mysqlRoot", "flask", "internal", "muip")
# \Z, not $: `$` also matches before a trailing newline, and a value is written into KEY=VALUE files.
SECRET_VALUE_RE = re.compile(r"^[A-Za-z0-9_-]{8,128}\Z")
# The MySQL root password must also START WITH A LETTER: the vendor render puts it UNQUOTED
# into docker-compose.yml (`      MYSQL_ROOT_PASSWORD: <value>`), where docker compose reads a value that
# starts with a digit or '-' as a number or a date (01234567 -> 342391, 1234_5678 -> 12345678,
# 2026-10-01 -> a timestamp) -- MariaDB would be initialised with another string than .env holds. A
# letter-first value of 8+ characters is a string to every YAML reader. One rule on every input:
# GIO_MYSQL_ROOT_PASSWORD, POST /server/secrets `mysqlRoot`, both installers, the launcher.
MYSQL_ROOT_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_-]{7,127}\Z")
_SECRET_VALUE_RULE = "it must be 8-128 characters (letters, digits, '_' or '-')"


def _warn_secret_ignored(key, why, what):
    """The start-log WARNING for a configured secret that cannot be used (`what` = "key" | "password"),
    ending with what a stack gets in its place: a random value -- or, with "Keep .env settings" on
    when the agent starts, nothing at all (no key or password of a stack is replaced while it is on)."""
    log_line("gio-agent: WARNING: %s ignored -- %s; %s."
             % (key, why, ("while \"Keep .env settings\" is on (GIO_KEEP_ENV) each stack keeps the %s it has"
                           if KEEP_ENV else "a random %s will be used") % what))


# GIO_MUIP_KEY obeys the same rule as a key set through /server/secrets. A bad value is dropped with
# a WARNING (a random key applies), never a refusal to boot: systemd's Restart=always would loop.
if MUIP_KEY and not SECRET_VALUE_RE.match(MUIP_KEY):
    _warn_secret_ignored("GIO_MUIP_KEY", _SECRET_VALUE_RULE, "key")
    MUIP_KEY = ""
# GIO_MYSQL_ROOT_PASSWORD / GIO_FLASK_SECRET_KEY likewise -- and a configured value that is
# itself one of the archives' published literals is no private value at all: dropped the same way.
if MYSQL_ROOT_PASSWORD and not MYSQL_ROOT_RE.match(MYSQL_ROOT_PASSWORD):
    _warn_secret_ignored("GIO_MYSQL_ROOT_PASSWORD", _SECRET_VALUE_RULE + " and start with a letter", "password")
    MYSQL_ROOT_PASSWORD = ""
elif MYSQL_ROOT_PASSWORD in VENDOR_MYSQL_ROOT_PASSWORDS:
    _warn_secret_ignored("GIO_MYSQL_ROOT_PASSWORD", "it is the vendor's published default", "password")
    MYSQL_ROOT_PASSWORD = ""
if FLASK_SECRET_KEY and not SECRET_VALUE_RE.match(FLASK_SECRET_KEY):
    _warn_secret_ignored("GIO_FLASK_SECRET_KEY", _SECRET_VALUE_RULE, "key")
    FLASK_SECRET_KEY = ""
elif FLASK_SECRET_KEY in VENDOR_FLASK_KEYS:
    _warn_secret_ignored("GIO_FLASK_SECRET_KEY", "it is the vendor's published default", "key")
    FLASK_SECRET_KEY = ""


def replace_sql_identified_by(text, old, new):
    return re.subn(r"(IDENTIFIED BY ')%s(')" % re.escape(old), r"\g<1>%s\g<2>" % new, text)


def replace_requirepass(text, old, new):
    return re.subn(r"(--requirepass[ \t]+)%s(?=[ \t\r\n]|$)" % re.escape(old), r"\g<1>%s" % new, text)


def replace_sh_password(text, old, new):
    # prepare-db.sh: `mysql ... -u hk4e_work -p<literal> < data.sql`
    return re.subn(r"((?<=\s)-p)%s(?=[ \t\r\n]|$)" % re.escape(old), r"\g<1>%s" % new, text)


def replace_xml_pwd(text, old, new):
    return re.subn(r'(\bpwd=")%s(")' % re.escape(old), r"\g<1>%s\g<2>" % new, text)


def replace_sign_key(text, new):
    return re.subn(r'(\bsign_key=")[^"]*(")', r"\g<1>%s\g<2>" % new, text)


def _rewrite(path, fn):
    """Apply fn(text) -> (new_text, n) to a file in place (line endings preserved). Returns n; a
    missing file counts as 0."""
    if not os.path.isfile(path):
        return 0
    text = read_text(path)
    new, n = fn(text)
    if n and new != text:
        write_text_atomic(path, new)
    return n


# -- pathfinding server on/off: the compose profile `donotstart` on pathfindingserver --
# Pure text editors over a compose file, in the vendor's own syntax (oaserver ships
# "    profiles:\n      - donotstart" under a 2-space service key): the key line's indent decides
# everything, line endings are the file's, the block form is inserted/removed byte-exact so that
# disable -> enable round-trips to the original bytes, and no other service block is ever touched.
# The inline form (`profiles: [donotstart]`) is understood when READING and appended to when it is
# what the file already uses.

def _line_indent(line):
    return line[:len(line) - len(line.lstrip(" \t"))]


def _compose_services_indent(text):
    """The indent of the service keys under the top-level `services:` (None when there is no such
    section, or it has no children)."""
    m = re.search(r"^services:[ \t]*(?:#[^\r\n]*)?\r?$", text, re.M)
    if not m:
        return None
    for line in text[m.end():].splitlines():
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        ind = _line_indent(line)
        return ind or None
    return None


def _service_block(text, service):
    """(start, end, indent, child_indent, eol) of the `<indent>service:` block, or None when the
    service is absent. Under a `services:` section only a key at the services' indent counts (a
    same-named key nested under another service's depends_on/networks never does); the block runs
    to the next non-blank, non-comment line indented no deeper than the key."""
    want = _compose_services_indent(text)
    best = None
    for m in re.finditer(r"^(?P<i>[ \t]+)%s:[ \t]*(?:#[^\r\n]*)?\r?$" % re.escape(service), text, re.M):
        if want is not None:
            if m.group("i") == want:
                best = m
                break
            continue
        if best is None or len(m.group("i")) < len(best.group("i")):
            best = m  # no services: section (a fragment): the shallowest occurrence
    if best is None:
        return None
    indent = best.group("i")
    eol = "\r\n" if "\r\n" in text else "\n"
    nl = text.find("\n", best.end())
    i = len(text) if nl < 0 else nl + 1
    end, child_indent = len(text), None
    while i < len(text):
        j = text.find("\n", i)
        nxt = len(text) if j < 0 else j + 1
        line = text[i:nxt]
        s = line.strip()
        if s and not s.startswith("#"):
            ind = _line_indent(line)
            if len(ind) <= len(indent):
                end = i
                break
            if child_indent is None:
                child_indent = ind
        i = nxt
    return best.start(), end, indent, child_indent or (indent + "  "), eol


_PROFILE_ITEM_RE = re.compile(r"^(?P<ii>[ \t]+)-[ \t]*(?P<q>[\"']?)(?P<n>[^\"'\r\n#]*?)(?P=q)[ \t]*(?:#[^\r\n]*)?\r?$")


def _profiles_section(body, ci):
    """Inside one service block: its `profiles:` key at the child indent -- {"start", "end" (the
    char span of the key line plus its list items), "inline", "names", "items": [(s, e, name)]} --
    or None. The block-form items are the consecutive `- name` lines right under the key."""
    m = re.search(r"^%sprofiles:[ \t]*(?P<rest>[^\r\n]*?)[ \t]*\r?$" % re.escape(ci), body, re.M)
    if not m:
        return None
    nl = body.find("\n", m.end())
    line_end = len(body) if nl < 0 else nl + 1
    rest = m.group("rest")
    if rest and not rest.startswith("#"):
        names = []
        if rest.startswith("[") and rest.endswith("]"):
            names = [x.strip().strip("\"'") for x in rest[1:-1].split(",") if x.strip()]
        return {"start": m.start(), "end": line_end, "inline": True, "names": names, "items": []}
    items = []
    i = line_end
    while i < len(body):
        j = body.find("\n", i)
        nxt = len(body) if j < 0 else j + 1
        mi = _PROFILE_ITEM_RE.match(body[i:nxt])
        if not mi or len(mi.group("ii")) <= len(ci):
            break
        items.append((i, nxt, mi.group("n").strip()))
        i = nxt
    return {"start": m.start(), "end": items[-1][1] if items else line_end, "inline": False,
            "names": [n for _s, _e, n in items], "items": items}


def compose_service_profiled(text, service, profile=DONOTSTART_PROFILE):
    """True / False whether the service's block carries `profile`; None when there is no such service."""
    blk = _service_block(text, service)
    if blk is None:
        return None
    start, end, _indent, ci, _eol = blk
    sec = _profiles_section(text[start:end], ci)
    return bool(sec and profile in sec["names"])


def set_pathfinding_text(text, enabled):
    """(new_text, n): n = 1 when the pathfindingserver block changed, 0 when it is already in the
    wanted state or absent. Disable inserts exactly `<ci>profiles:<eol><ci>  - donotstart<eol>` right
    under the service key (or appends the item to an existing list); enable removes that item and the
    key it leaves empty. Everything else stays byte-identical."""
    blk = _service_block(text, PATHFINDING_SERVICE)
    if blk is None:
        return text, 0
    start, end, _indent, ci, eol = blk
    body = text[start:end]
    sec = _profiles_section(body, ci)
    have = bool(sec and DONOTSTART_PROFILE in sec["names"])
    if have == (not enabled):
        return text, 0
    if not enabled:
        if sec is None:
            nl = body.find("\n")
            key_end = len(body) if nl < 0 else nl + 1
            ins = "%sprofiles:%s%s  - %s%s" % (ci, eol, ci, DONOTSTART_PROFILE, eol)
            if nl < 0:
                ins = eol + ins[:-len(eol)]  # the key line ends the file without a newline: keep that
            new_body = body[:key_end] + ins + body[key_end:]
        elif sec["inline"]:
            line = body[sec["start"]:sec["end"]]
            new_line = line.replace("]", (", %s]" if sec["names"] else "%s]") % DONOTSTART_PROFILE, 1)
            new_body = body[:sec["start"]] + new_line + body[sec["end"]:]
        else:
            ii = _line_indent(body[sec["items"][0][0]:sec["items"][0][1]]) if sec["items"] else ci + "  "
            new_body = body[:sec["end"]] + "%s- %s%s" % (ii, DONOTSTART_PROFILE, eol) + body[sec["end"]:]
    elif sec["inline"]:
        names = [n for n in sec["names"] if n != DONOTSTART_PROFILE]
        if names:
            line = body[sec["start"]:sec["end"]]
            new_line = re.sub(r"\[[^\]]*\]", "[" + ", ".join(names) + "]", line, count=1)
            new_body = body[:sec["start"]] + new_line + body[sec["end"]:]
        else:
            new_body = body[:sec["start"]] + body[sec["end"]:]
    elif any(n != DONOTSTART_PROFILE for _s, _e, n in sec["items"]):
        new_body = body
        for s, e, n in reversed(sec["items"]):
            if n == DONOTSTART_PROFILE:
                new_body = new_body[:s] + new_body[e:]
    else:
        new_body = body[:sec["start"]] + body[sec["end"]:]  # the item and the key it leaves empty
    return text[:start] + new_body + text[end:], 1


def _compose_service_names(text):
    """The keys at the services' indent (with no `services:` section: the shallowest indented keys)."""
    want = _compose_services_indent(text)
    found = [(m.group("i"), m.group("n")) for m in
             re.finditer(r"^(?P<i>[ \t]+)(?P<n>[A-Za-z0-9_.-]+):[ \t]*(?:#[^\r\n]*)?\r?$", text, re.M)]
    if want is None and found:
        want = min((ind for ind, _n in found), key=len)
    names = []
    for ind, n in found:
        if ind == want and n not in names:
            names.append(n)
    return names


def compose_disabled_services(text):
    """Every service whose block carries the donotstart profile (the vendor's oaserver, a switched-off
    pathfindingserver): what compose's own `config --services` leaves out."""
    return {n for n in _compose_service_names(text) if compose_service_profiled(text, n)}


def muip_key_file(version):
    d = stack_dir(version)
    tmpl = os.path.join(d, "server", "muipserver", "conf", "muipserver.xml.tmpl")
    return tmpl if os.path.isfile(tmpl) else os.path.join(d, "server", "muipserver", "conf", "muipserver.xml")


def _read_sign_key_file(path):
    try:
        m = re.search(r'sign_key\s*=\s*"([^"]*)"', read_text(path))
    except OSError:
        return ""
    return m.group(1) if m else ""


def is_vendor_muip_key(key):
    """The archive's published key -- or none at all: both mean anyone can sign GM commands."""
    return (not key) or key in VENDOR_MUIP_KEYS


def random_muip_key():
    return "".join(secrets.choice(string.ascii_letters + string.digits) for _ in range(36))


def muip_fingerprint(key):
    return hashlib.sha256(key.encode()).hexdigest()[:8] if key else None


def ensure_muip_key(version, job):
    """Replace the vendor's published sign_key (or a missing one) in muipserver.xml.tmpl + the
    rendered muipserver.xml with GIO_MUIP_KEY or a random key. A key that is not a vendor one is
    never touched (chosen here earlier, or rotated through /server/secrets). The value goes to
    creds.txt on the box and into the state as secrets.muipChangedAt/muipSource; the log line
    carries the fingerprint only. With "Keep .env settings" on (KEEP_ENV) nothing is replaced:
    the key stays as it is, no file and no state is written, and a vendor key that is really there
    gets one job line. Returns "config" | "random" | None (nothing done)."""
    key_file = muip_key_file(version)
    cur = _read_sign_key_file(key_file)
    if not is_vendor_muip_key(cur):
        return None
    if KEEP_ENV:
        if cur:
            job.log("MUIP sign key: still the vendor's published key -- kept as it is (GIO_KEEP_ENV).")
        return None
    source = "config" if MUIP_KEY else "random"
    new = MUIP_KEY or random_muip_key()
    if new == cur:
        return None
    if _rewrite(key_file, lambda t: replace_sign_key(t, new)) == 0:
        # A stack the agent cannot secure must not be prepared: the bootstrap would render the
        # published key (or nothing) into a muipserver that accepts anyone's commands.
        raise AgentError(500, "sign_key not found in muipserver.xml.tmpl -- the vendor's MUIP key "
                              "could not be replaced. Check %s." % key_file)
    rendered = os.path.join(stack_dir(version), "server", "muipserver", "conf", "muipserver.xml")
    if os.path.isfile(rendered) and rendered != key_file:
        _rewrite(rendered, lambda t: replace_sign_key(t, new))
    # tolerant: "" for whatever cannot be read -- creds.txt is a note, not a source
    write_creds_file(version, dict(current_secrets(version), muip=new))
    sec = dict(version_state(version).get("secrets") or {})
    sec["muipChangedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    sec["muipSource"] = source
    version_state_set(version, secrets=sec)
    job.log("MUIP sign key: the vendor's published key replaced with a %s one (fingerprint %s) -- only "
            "this agent can sign GM commands from now on; the value is in creds.txt on the box."
            % (source, muip_fingerprint(new)))
    return source


def restore_muip_key(version, job):
    """The restore half of the MUIP rule, where a render is about to copy the template's sign key into
    the muipserver.xml the service loads (do_secrets before its re-render): muipserver.xml.tmpl names a
    vendor key again, or none (a re-extracted archive), while the RENDERED muipserver.xml still names
    this stack's own key -- a private one that obeys SECRET_VALUE_RE -- so the template takes that key.
    Restore only, whatever "Keep .env settings" says: the key the stack runs on is put back, a vendor
    key the rendered file does not contradict is never replaced here. Returns the key put back, "" when
    there is none to put back, None when the template did not take it (one WARNING line: the re-render
    then copies the template's key over the stack's own)."""
    conf = os.path.join(stack_dir(version), "server", "muipserver", "conf")
    tmpl = os.path.join(conf, "muipserver.xml.tmpl")
    if not os.path.isfile(tmpl):
        return ""  # nothing renders muipserver.xml: the file keeps its key
    cur = _read_sign_key_file(tmpl)
    if not is_vendor_muip_key(cur):
        return ""
    kept = _read_sign_key_file(os.path.join(conf, "muipserver.xml"))
    if is_vendor_muip_key(kept) or not SECRET_VALUE_RE.match(kept):
        return ""
    try:
        n = _rewrite(tmpl, lambda t: replace_sign_key(t, kept))
        # the read-back: the key the render is about to copy is the one just written
        problem = None if n and _read_sign_key_file(tmpl) == kept else "it holds no sign_key this agent can set"
    except OSError as e:
        problem = "it could not be rewritten (%s)" % e
    if problem:
        job.log("WARNING: the MUIP sign key this stack runs on was NOT put back into muipserver.xml.tmpl -- %s. "
                "The re-render replaces it with what the template holds (%s)."
                % (problem, "the vendor's published key" if cur else "no key"))
        return None
    job.log("MUIP sign key: muipserver.xml.tmpl %s -- the key this stack's muipserver.xml names was put back."
            % ("carried the vendor's published key again (a re-extracted archive)" if cur else "named no key"))
    return kept


def internal_literal(version):
    """The one password shared by redis requirepass, hk4e_work and hk4e_readonly -- read from the
    compose template, falling back to bootstrap.sql: what the next render or bootstrap uses (what the
    stack RUNS on is stack_internal_password)."""
    d = stack_dir(version)
    for path, rx in ((os.path.join(d, "docker-compose.yml.tmpl"), r"--requirepass[ \t]+(\S+)"),
                     (os.path.join(d, "docker-compose.yml"), r"--requirepass[ \t]+(\S+)"),
                     (os.path.join(d, "bootstrap.sql"), r"IDENTIFIED BY '([^']+)'")):
        try:
            m = re.search(rx, read_text(path))
        except OSError:
            continue
        if m:
            return m.group(1)
    return ""


# -- the stack internal password: where it lives --
# ONE value in four kinds of places: bootstrap.sql (CREATE USER of hk4e_work + hk4e_readonly), redis'
# `--requirepass` in docker-compose.yml.tmpl AND the rendered docker-compose.yml, prepare-db.sh (the two
# imports as hk4e_work -- bootstrap time only), and every pwd="..." of server/*/conf/*.xml.tmpl AND of the
# rendered *.xml (141 per file in 1.6, 144 in 2.8: all of them this password). The editors work on
# POSITIONS, never on an old value: each sets every position of its kind to the new value whatever it holds
# -- a file a crash left mixed or a hand edit changed comes out like a vendor one -- and every other byte
# stays as it was, CRLF / LF included (no render: OUTER_IP, the advertised-IP pass, the verify flag, the
# pathfinding profile and the compose root line of the rendered files are never touched). The read-back
# (internal_positions) follows every rewrite; run over the rewritten texts in memory it is the dry run
# before anything is recorded or sent.
_INTERNAL_POSITION_RES = {
    # the CREATE USER lines of the two game accounts -- never another account's password
    "sql": re.compile(r"^[ \t]*CREATE[ \t]+USER[ \t]+(?:IF[ \t]+NOT[ \t]+EXISTS[ \t]+)?"
                      r"'(?P<user>hk4e_work|hk4e_readonly)'@'[^'\r\n]*'[ \t]+IDENTIFIED[ \t]+BY[ \t]+"
                      r"'(?P<value>[^'\r\n]*)'", re.M),
    # redis' command line: `--requirepass <value>` (a quote that closes the line is not part of it)
    "compose": re.compile(r"--requirepass[ \t]+(?P<value>[^\s\"']+)"),
    # the imports as hk4e_work -- never root's `-u root -p"$MYSQL_ROOT_PASSWORD"`
    "sh": re.compile(r"(?<![\w-])-u[ \t]*hk4e_work[ \t]+-p(?P<value>[^\s\"'<>;|&]+)"),
    "xml": re.compile(r'\bpwd="(?P<value>[^"]*)"'),
}


def internal_position_values(kind, text):
    """(the values the internal-password positions of one file's text hold, in order; whether the text lacks
    a position it must have -- bootstrap.sql: the CREATE USER of BOTH game accounts; a compose file: the
    requirepass; prepare-db.sh: an import as hk4e_work; a server XML: one pwd). Pure."""
    found = list(_INTERNAL_POSITION_RES[kind].finditer(text))
    if kind == "sql":
        missing = {m.group("user") for m in found} != {"hk4e_work", "hk4e_readonly"}
    else:
        missing = not found
    return [m.group("value") for m in found], missing


def set_internal_positions(kind, text, value):
    """(new_text, n): every internal-password position of one file's text set to `value`, whatever it held,
    and nothing else changed; n = the positions whose value changed (0 = already in the wanted state). The
    caller passes a plain value (MYSQL_ROOT_RE): it is written as it is, unquoted. Pure."""
    changed = [0]

    def repl(m):
        if m.group("value") == value:
            return m.group(0)
        changed[0] += 1
        s = m.start()
        return m.group(0)[:m.start("value") - s] + value + m.group(0)[m.end("value") - s:]

    return _INTERNAL_POSITION_RES[kind].sub(repl, text), changed[0]


def internal_password_files(version):
    """[(path, kind, source)] of every file of the stack that holds the internal password AND exists: the
    sources first (what a bootstrap or a re-render reads), then the rendered files (what redis and the game
    services run on). Raises OSError when a server folder cannot be listed."""
    d = stack_dir(version)
    sources = [(os.path.join(d, "bootstrap.sql"), "sql"), (os.path.join(d, "docker-compose.yml.tmpl"), "compose"),
               (os.path.join(d, "dockerfiles", "prepare-db", "prepare-db.sh"), "sh")]
    rendered = [(os.path.join(d, "docker-compose.yml"), "compose")]
    conf_root = os.path.join(d, "server")
    for entry in sorted(os.listdir(conf_root)) if os.path.isdir(conf_root) else []:
        conf = os.path.join(conf_root, entry, "conf")
        if not os.path.isdir(conf):
            continue
        for name in sorted(os.listdir(conf)):
            if name.endswith(".xml.tmpl"):
                sources.append((os.path.join(conf, name), "xml"))
            elif name.endswith(".xml"):
                rendered.append((os.path.join(conf, name), "xml"))
    return [(p, k, True) for p, k in sources if os.path.isfile(p)] + \
        [(p, k, False) for p, k in rendered if os.path.isfile(p)]


def internal_positions(version, sources_only=False):
    """The read-back: {path relative to the stack: (values, missing)} of every file internal_password_files
    lists (only the sources with sources_only); a file that cannot be read lacks its positions. Raises
    OSError when a server folder cannot be listed."""
    d = stack_dir(version)
    out = {}
    for path, kind, source in internal_password_files(version):
        if sources_only and not source:
            continue
        try:
            out[os.path.relpath(path, d)] = internal_position_values(kind, read_text(path))
        except OSError:
            out[os.path.relpath(path, d)] = ([], True)
    return out


def positions_value(pos):
    """The ONE value every position of a read-back names -- None when they name several, a file lacks its
    positions or there is no file at all. Pure."""
    vals = {v for values, _missing in pos.values() for v in values}
    if len(vals) != 1 or any(missing for _values, missing in pos.values()):
        return None
    return next(iter(vals))


def _layout_problem(pos):
    """Why the files of a read-back cannot take any value -- no file at all, or the first one that lacks its
    positions (a relative path, never a value) -- None when every file has them. Pure."""
    if not pos:
        return "no file of the stack holds it"
    for rel, (_values, missing) in sorted(pos.items()):
        if missing:
            return "%s does not hold it where this agent expects it (the stack layout is not the one this agent " \
                   "knows)" % rel
    return None


def _positions_problem(pos, value):
    """Why a read-back does not name `value` in every position -- _layout_problem, else the first file that
    names another value (a relative path, never a value) -- None when every file names it. Pure."""
    problem = _layout_problem(pos)
    if problem:
        return problem
    for rel, (values, _missing) in sorted(pos.items()):
        if any(v != value for v in values):
            return "%s names another value" % rel
    return None


def rendered_internal_password(version):
    """The requirepass of the RENDERED docker-compose.yml -- what redis was created with; "" when the file is
    missing, unreadable or names none."""
    try:
        values, _missing = internal_position_values("compose", read_text(_compose_paths(version)[1]))
    except OSError:
        return ""
    return values[0] if values else ""


def stack_internal_password(version):
    """The internal password as the stack USES it: once bootstrapped, what the rendered docker-compose.yml
    names (redis runs with it, and every change rewrites the rendered XMLs with it); before that, the
    templates' (internal_literal: what the bootstrap will render). "" = none found. The one reader behind
    creds.txt, GET /server/secrets and /status internalPassword -- after a re-extraction the templates name
    the vendor's value again while everything that runs still uses the stack's own."""
    if is_bootstrapped(version):
        return rendered_internal_password(version)
    return internal_literal(version)


# -- the two .env secrets: MySQL root password + Flask secret key --
# The MUIP rule applied to the values the archives publish in .env: whenever the agent prepares a stack
# that still carries the vendor's literal, it is replaced with the configured value
# (GIO_MYSQL_ROOT_PASSWORD / GIO_FLASK_SECRET_KEY) or -- none configured -- a random one per stack. A
# value that is not a vendor literal is NEVER touched (chosen earlier, or rotated through
# /server/secrets); an empty / missing value and a missing or unreadable .env are left alone on every
# path, silently. While "Keep .env settings" is on (KEEP_ENV) neither stage replaces a vendor literal
# -- one job line where it is kept --; the record, the capture and the recovery work all the same.
# Two stages:
#   file level -- ensure_env_secrets, right after ensure_muip_key: the Flask key; the root password only
#       while <stack>/mysql is absent or empty (MariaDB reads the variable only when it CREATES the data
#       dir; an initialised one holds its own password);
#   db stage   -- ensure_db_root_password, right after a successful wait_for_mysql: ONE `ALTER USER`
#       statement in ONE connection, then .env (proven writable before anything is sent).
# <stack>/.relic-creds remembers what the SERVER accepted, because a re-extracted archive overwrites .env
# and creds.txt (never a rendered file, never mysql/, never a .relic-* file): wait_for_mysql learns the
# password there and, refused, recovers from it. The VALUES never reach a job line, the agent log, the
# state file or /status -- the admin reads them in <stack>/creds.txt and through GET /server/secrets.
# Everything below runs inside jobs that already hold _op_lock, and reads .env through
# read_env(...).get(...) -- never mysql_password(), which raises on a missing value.

def random_secret_value(n=32):
    """A random secret of n characters: the first a letter, the rest letters + digits -- valid under
    MYSQL_ROOT_RE and SECRET_VALUE_RE alike."""
    return secrets.choice(string.ascii_letters) + "".join(
        secrets.choice(string.ascii_letters + string.digits) for _ in range(n - 1))


def _json_text(raw):
    """The string a JSON reader makes of the text between two double quotes (`raw` itself when that
    text is not valid there)."""
    try:
        return json.loads('"%s"' % raw)
    except ValueError:
        return raw


def _yaml_scalar(raw):
    """What a YAML reader makes of one scalar as _compose_env_re captured it: the text between double
    quotes (JSON escapes) or single quotes ('' = one quote), else the plain text itself."""
    if len(raw) >= 2 and raw[0] == raw[-1] == '"':
        return _json_text(raw[1:-1])
    if len(raw) >= 2 and raw[0] == raw[-1] == "'":
        return raw[1:-1].replace("''", "'")
    return raw


def _compose_env_re(key):
    # `<indent>KEY: value   # comment` -- the value double-quoted, single-quoted, plain (it ends before a
    # " #" comment and before trailing blanks) or empty; a commented-out line never matches.
    return re.compile(r"""^(?P<head>[ \t]+%s:)(?P<gap>[ \t]*)"""
                      r"""(?P<value>"(?:[^"\\\r\n]|\\[^\r\n])*"|'(?:[^'\r\n]|'')*'|[^\s#"'][^\r\n]*?|)"""
                      r"""(?P<tail>(?:[ \t]+#[^\r\n]*)?[ \t]*)(?P<cr>\r?)$""" % re.escape(key), re.M)


def compose_env_value(text, key):
    """The value of a compose file's first `<indent>KEY: value` mapping line, quotes removed: "" for
    an empty one, None when the text has no such line. Pure."""
    m = _compose_env_re(key).search(text)
    return None if m is None else _yaml_scalar(m.group("value"))


def set_compose_env_value(text, key, value):
    """(new_text, n): the VALUE of every `<indent>KEY: <anything>` mapping line set to `value`, written
    as a plain scalar -- the caller passes one YAML reads back as that very string (MYSQL_ROOT_RE).
    n = the lines whose text changed, 0 when already in the wanted state (like set_pathfinding_text).
    The indent, a trailing `# comment`, CRLF / LF and every other line stay byte-identical. For the
    RENDERED docker-compose.yml only: a .tmpl keeps its %PLACEHOLDER%. Pure."""
    changed = [0]

    def repl(m):
        if _yaml_scalar(m.group("value")) == value:
            return m.group(0)
        changed[0] += 1
        return m.group("head") + (m.group("gap") or " ") + value + m.group("tail") + m.group("cr")

    new = _compose_env_re(key).sub(repl, text)
    return new, changed[0]


_SDK_SECRET_KEY_RE = re.compile(r'("secret_key"\s*:\s*")((?:[^"\\\r\n]|\\[^\r\n])*)(")')


def sdk_secret_key(text):
    """The "secret_key" of the sdk's config.json the way its JSON reader gets it: "" for an empty one,
    None when the text names none. Pure."""
    m = _SDK_SECRET_KEY_RE.search(text)
    return None if m is None else _json_text(m.group(2))


def set_sdk_secret_key_text(text, value):
    """(new_text, n): the `"secret_key": "<anything>"` of the RENDERED sdk/data/config.json set to
    `value` with a regex -- the file is never re-serialised (it carries RSA keys and the vendor's
    formatting). n = the entries whose text changed, 0 when already in the wanted state. Pure."""
    changed = [0]

    def repl(m):
        if _json_text(m.group(2)) == value:
            return m.group(0)
        changed[0] += 1
        return m.group(1) + json.dumps(value)[1:-1] + m.group(3)

    new = _SDK_SECRET_KEY_RE.sub(repl, text)
    return new, changed[0]


def rendered_root_password(version):
    """MYSQL_ROOT_PASSWORD as the RENDERED docker-compose.yml names it -- what the mysql container is
    created with; "" when the file is missing, unreadable or names none."""
    try:
        return compose_env_value(read_text(_compose_paths(version)[1]), "MYSQL_ROOT_PASSWORD") or ""
    except OSError:
        return ""


def rendered_flask_key(version):
    """secret_key as the RENDERED sdk/data/config.json names it -- what the sdk loads when it starts;
    "" when the file is missing, unreadable or names none."""
    try:
        return sdk_secret_key(read_text(os.path.join(stack_dir(version), "sdk", "data", "config.json"))) or ""
    except OSError:
        return ""


def current_secrets(version):
    """The four secrets as the stack's own files hold them NOW ({"mysqlRoot", "flask", "internal",
    "muip"}, "" for whatever is missing or unreadable) -- what creds.txt is rewritten from. The internal
    password is the one the stack uses (stack_internal_password): after a re-extraction the templates
    name the vendor's again, and creds.txt must not hand an admin a password the database refuses."""
    try:
        env = read_env(version)
    except OSError:
        env = {}
    return {"mysqlRoot": env.get("MYSQL_ROOT_PASSWORD", ""), "flask": env.get("FLASK_SECRET_KEY", ""),
            "internal": stack_internal_password(version), "muip": _read_sign_key_file(muip_key_file(version))}


def secret_kinds(version, env=None):
    """(mysqlPassword, flaskKey) as GET /status reports them: "vendor" | "custom" | None each (None =
    no value, or a file that cannot be read). ONE tolerant read of .env -- read_env itself only
    forgives a missing file. The Flask key is judged where the sdk loads it: the rendered
    sdk/data/config.json when that names one, else .env."""
    if env is None:
        try:
            env = read_env(version)
        except OSError:
            env = {}

    def kind(value, vendor):
        return None if not value else ("vendor" if value in vendor else "custom")

    return (kind(env.get("MYSQL_ROOT_PASSWORD", ""), VENDOR_MYSQL_ROOT_PASSWORDS),
            kind(rendered_flask_key(version) or env.get("FLASK_SECRET_KEY", ""), VENDOR_FLASK_KEYS))


# <stack>/.relic-creds -- the agent's own note of the MySQL root password. Two possible lines:
#   mysql/root: <value>            the last value the SERVER accepted (proven by a successful SELECT 1)
#   mysql/root (pending): <value>  a value that MAY be what the server holds but is not proven yet: the
#                                  target of a change, written BEFORE its ALTER USER; the value put into
#                                  .env over a data dir MariaDB has not created yet; a value captured
#                                  from the rendered compose file
# ...and one of the stack internal password (ensure_internal_password):
#   internal (pending): <value>    a change of it in progress: written BEFORE anything is changed (its ALTER
#                                  USER, or the sources ahead of a fresh bootstrap), removed only once the
#                                  database, every file and the running redis agree on it -- while it is
#                                  there no game service is booted (do_start finishes the change first);
#                                  a record that cannot be read may hold it: nothing boots on trust then
#                                  (the stack is proven consistent first, or the job is refused)
# It has its OWN reader and writer -- write_creds_file never touches it -- and nothing ever copies .env's
# value into it without the server having accepted that value: after a re-extraction .env is the
# vendor's again, and this record is then the one place that still names the real password. A line
# this agent does not know (a newer agent's) is kept as it is.
CREDS_RECORD = ".relic-creds"
_CREDS_ROOT, _CREDS_PENDING = "mysql/root: ", "mysql/root (pending): "
_CREDS_INTERNAL_PENDING = "internal (pending): "
_CREDS_RECORD_HEAD = ("# The Relic GIO agent's own note of the MySQL root password this server last accepted (and of a "
                      "change of the\n# stack internal password in progress) -- kept because a re-extracted archive "
                      "overwrites .env and\n# creds.txt but never this file. Do not edit or delete it.\n")


def creds_record_path(version):
    return os.path.join(stack_dir(version), CREDS_RECORD)


def _parse_creds_record(text):
    """({"root", "pending", "internalPending"}, [every other line that is not a comment, as it is]). Pure."""
    out, other = {"root": "", "pending": "", "internalPending": ""}, []
    for raw in text.split("\n"):
        line = raw.strip()
        if line.startswith(_CREDS_PENDING):
            out["pending"] = line[len(_CREDS_PENDING):].strip()
        elif line.startswith(_CREDS_ROOT):
            out["root"] = line[len(_CREDS_ROOT):].strip()
        elif line.startswith(_CREDS_INTERNAL_PENDING):
            out["internalPending"] = line[len(_CREDS_INTERNAL_PENDING):].strip()
        elif line and not line.startswith("#"):
            other.append(raw.rstrip("\r"))
    return out, other


def read_creds_record(version):
    """{"root", "pending", "internalPending"} -- "" for a line the record does not hold; a missing record
    reads as all empty. A record that exists but cannot be read RAISES OSError: read as empty,
    a writer would rebuild it without the lines it could not see -- every caller decides what a record
    it cannot read means (an unreadable record is an unwritable one)."""
    try:
        text = read_text(creds_record_path(version))
    except FileNotFoundError:
        return {"root": "", "pending": "", "internalPending": ""}
    return _parse_creds_record(text)[0]


def write_creds_record(version, root=None, pending=None, internal_pending=None):
    """Rewrite the record: `root` / `pending` / `internal_pending` = None keeps that line as it is, ""
    removes it; a line this agent does not know is kept as it is. Written through a temp file CREATED
    0600 (never readable by others, not even for a moment), fsync'ed, renamed into place, the folder
    fsync'ed, then kept private like creds.txt. Raises OSError -- also for a record that exists but
    cannot be read: every caller decides what a record that cannot be written means."""
    try:
        old, other = _parse_creds_record(read_text(creds_record_path(version)))
    except FileNotFoundError:
        old, other = {"root": "", "pending": "", "internalPending": ""}, []
    root = old["root"] if root is None else root
    pending = old["pending"] if pending is None else pending
    internal_pending = old["internalPending"] if internal_pending is None else internal_pending
    if plain_line_problem(root) or plain_line_problem(pending) or plain_line_problem(internal_pending):
        raise OSError(errno.EINVAL, "a password with a line break or a control character cannot be recorded")
    text = _CREDS_RECORD_HEAD + "".join(label + value + "\n" for label, value in
                                        ((_CREDS_ROOT, root), (_CREDS_PENDING, pending),
                                         (_CREDS_INTERNAL_PENDING, internal_pending)) if value) \
        + "".join(line + "\n" for line in other)
    path = creds_record_path(version)
    write_text_durable(path, text, private=True)
    protect_path(path, 0o600)


def internal_change_pending(version):
    """Whether the creds record holds an unfinished change of the stack internal password: ("yes" | "no" |
    "unknown", the OSError of "unknown" -- else None). "unknown" = a record that exists but cannot be read
    (read_creds_record): a change on record there is invisible, so every gate treats it as one that may be
    there -- fail CLOSED: the game services never boot over a change nobody can see."""
    try:
        return ("yes" if read_creds_record(version)["internalPending"] else "no"), None
    except OSError as e:
        return "unknown", e


def refuse_while_internal_pending(version):
    """409 for a job that would (re)start game services while a change of the stack internal password has
    not finished -- or while the record that would say so cannot be read: they would boot on files and a
    database that may disagree. Only a Start (or a provision) finishes the change, with no game service
    running."""
    pending, err = internal_change_pending(version)
    if pending == "yes":
        raise AgentError(409, "A change of the stack internal password has not finished -- Start the version to "
                              "complete it.")
    if pending == "unknown":
        raise AgentError(409, "Stack internal password: %s cannot be read (%s) -- make it readable, then try again."
                         % (CREDS_RECORD, err))


def internal_kind(version):
    """/status internalPassword: "pending" while the creds record holds an unfinished change of the internal
    password, else "vendor" | "custom" of what the stack uses (stack_internal_password); None = no value, or
    a record that cannot be read. Never a value."""
    try:
        if read_creds_record(version)["internalPending"]:
            return "pending"
    except OSError:
        return None
    value = stack_internal_password(version)
    return None if not value else ("vendor" if value in VENDOR_INTERNAL_PASSWORDS else "custom")


def _note_secret_source(version, job, **kv):
    """secrets.<x>Source / <x>ChangedAt into the state (None removes that key). Best effort: the value is
    already in place, so a state that cannot record who chose it is one WARNING line."""
    try:
        sec = dict(version_state(version).get("secrets") or {})
        for k, v in kv.items():
            if v is None:
                sec.pop(k, None)
            else:
                sec[k] = v
        version_state_set(version, secrets=sec)
    except AgentError as e:
        job.log("WARNING: could not record %s in the agent state (%s)." % (", ".join(sorted(kv)), e.message))


def _note_internal_chooser(version, chooser):
    """secrets.internalPendingSource = who chose the value of a change of the internal password that is about to
    go on record -- STRICTLY before its pending line (raises the 507 / 503 of a state that cannot take it): the
    Start that completes a change a failure left unfinished names this chooser as the value's source. Returns
    what it replaced ({key: its value before, None = absent}) for a caller whose pending line then cannot be
    written: put back as it was (_note_secret_source), an earlier change still on record keeps its own chooser."""
    sec = dict(version_state(version).get("secrets") or {})
    before = {k: sec.get(k) for k in ("internalPendingSource", "internalPendingFresh")}
    sec["internalPendingSource"] = chooser
    sec.pop("internalPendingFresh", None)
    version_state_set(version, strict=True, secrets=sec)
    return before


def rendered_root_to_note(version, env_root):
    """The root password the RENDERED docker-compose.yml names, when it has to go on record before
    that line is replaced with .env's value (a re-render, or a cold site's step 3): .env holds a
    value, the rendered file names ANOTHER, non-vendor password -- what the database was created with
    or last followed -- and the record holds neither line. That is .env carrying a vendor literal
    again (a re-extracted archive) and just as well an .env that names a value the record does not
    prove (edited by hand, without an ALTER USER): either way the rendered line may be the last file
    that names the database's real password. "" = nothing to note -- also for a stack whose .env
    has no root value, which every path leaves alone, and for a record that cannot be read (nobody
    can tell what it holds; it could not be written either)."""
    if not env_root:
        return ""
    named = rendered_root_password(version)
    if not named or named == env_root or named in VENDOR_MYSQL_ROOT_PASSWORDS \
            or plain_line_problem(named) is not None:
        return ""
    try:
        rec = read_creds_record(version)
    except OSError:
        return ""
    return "" if rec["root"] or rec["pending"] else named


def restore_flask_key(version, job, env_flask):
    """The restore half of the Flask rule, wherever a render is about to copy .env's key into the file
    the sdk loads (ensure_env_secrets, step 2; do_secrets before its re-render): .env carries a vendor
    literal again (a re-extracted archive) while the RENDERED sdk/data/config.json still names this
    stack's own key -- a private one that obeys SECRET_VALUE_RE -- so that key is put back into .env.
    Restore only: a vendor key the rendered file does not contradict is never replaced here. Returns
    the key put back, "" when there is none to put back, None when .env could not be written (one
    WARNING line)."""
    if env_flask not in VENDOR_FLASK_KEYS:
        return ""
    kept = rendered_flask_key(version)
    if not kept or kept in VENDOR_FLASK_KEYS or not SECRET_VALUE_RE.match(kept):
        return ""
    try:
        write_env_value(version, "FLASK_SECRET_KEY", kept)
    except OSError as e:
        job.log("WARNING: the vendor's published Flask secret key was NOT replaced -- .env cannot be written "
                "(%s)." % e)
        return None
    job.log("Flask secret key: .env carried the vendor's published key again (a re-extracted archive) "
            "-- the key this stack's sdk/data/config.json names was put back.")
    return kept


def ensure_env_secrets(version, job, cold):
    """The file level of the rule above, called right after ensure_muip_key at its four sites. `cold` =
    no container of this stack runs and the staged `up -d mysql redis` follows (a fresh bootstrap, a
    provision after down_all, a start of a stack that was definitely down); cold=False is the loopback
    heal, where the stack may be running and a full re-render follows.
      1. capture: the rendered compose file still names another root password than .env -- which
         carries the vendor's again (a re-extracted archive) or names a value the record does not
         prove (an .env edited by hand) -- and the record holds nothing -> that value becomes the
         record's pending line, before a re-render or step 3 can overwrite the line;
      2. the Flask key: a vendor literal in .env is replaced -- with the key the rendered
         sdk/data/config.json still names (restore_flask_key -- re-extraction: the sdk keeps its
         key), else with the configured / a random one; when cold, the rendered config.json then
         follows .env;
      3. the root password, only when cold: a vendor literal over an absent / empty mysql/ is replaced
         in .env, the pending line FIRST (MariaDB is created with it; the first wait_for_mysql proves
         it), and the rendered compose file follows a private .env value -- harmless on an
         initialised data dir, and it happens BEFORE the staged up, which then (re)creates the mysql
         container while only mysql / redis are being started. Never an `up` or a wait of its own.
    A vendor root password over an INITIALISED data dir is the db stage's. A write that fails is one
    WARNING line and the job goes on (/status keeps saying "vendor"). With "Keep .env settings" on
    (KEEP_ENV) no vendor literal is replaced: step 2 leaves a vendor Flask key alone -- no restore
    either, .env is not written -- with one job line, and step 3 leaves a vendor root password alone
    without one (the db stage is the one that says it); the capture, and the rendered files following
    a PRIVATE .env value, stay as they are. Returns what changed, {} for nothing: {"flask": "random" |
    "config" | "restored", "mysqlRoot": "random" | "config", "captured": True, "sdkConfig": True,
    "compose": True} -- only the keys that apply."""
    out = {}
    try:
        env = read_env(version)
    except OSError:
        return out
    d = stack_dir(version)
    root, flask = env.get("MYSQL_ROOT_PASSWORD", ""), env.get("FLASK_SECRET_KEY", "")
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    where = "read it under Server secrets in the launcher or in creds.txt on the box"

    def attempt(failed, write):
        try:
            write()
            return True
        except OSError as e:
            job.log("WARNING: %s (%s)." % (failed, e))
            return False

    # 1. capture
    named = rendered_root_to_note(version, root)
    if named and attempt("the root password the rendered docker-compose.yml names could not be noted in %s"
                         % CREDS_RECORD, lambda: write_creds_record(version, pending=named)):
        out["captured"] = True
    # 2. the Flask key
    if flask in VENDOR_FLASK_KEYS and KEEP_ENV:
        job.log("Flask secret key: still the vendor's published key -- kept as it is (GIO_KEEP_ENV).")
    elif flask in VENDOR_FLASK_KEYS:
        kept = restore_flask_key(version, job, flask)
        if kept:
            flask, out["flask"] = kept, "restored"
        elif kept is not None:  # (None: there is a key to put back and .env refused it -- never replaced then)
            failed = "the vendor's published Flask secret key was NOT replaced -- .env cannot be written"
            source = "config" if FLASK_SECRET_KEY else "random"
            new = FLASK_SECRET_KEY or random_secret_value()
            if new != flask and attempt(failed, lambda: write_env_value(version, "FLASK_SECRET_KEY", new)):
                flask, out["flask"] = new, source
                _note_secret_source(version, job, flaskSource=source, flaskChangedAt=now)
                job.log("Flask secret key: the vendor's published key replaced with a %s one -- %s." % (source, where))
    if cold and flask and flask not in VENDOR_FLASK_KEYS:
        try:
            if _rewrite(os.path.join(d, "sdk", "data", "config.json"), lambda t: set_sdk_secret_key_text(t, flask)):
                out["sdkConfig"] = True
                job.log("sdk/data/config.json: secret_key follows .env (the login service reads it when it starts).")
        except OSError as e:
            job.log("WARNING: sdk/data/config.json could not follow .env's Flask secret key (%s)." % e)
    # 3. the root password -- only where the staged `up -d mysql redis` follows
    if cold:
        if root in VENDOR_MYSQL_ROOT_PASSWORDS and not KEEP_ENV and _dir_absent_or_empty(os.path.join(d, "mysql")):
            source = "config" if MYSQL_ROOT_PASSWORD else "random"
            new = MYSQL_ROOT_PASSWORD or random_secret_value()
            failed = "the vendor's published MySQL root password was NOT replaced -- %s cannot be written"
            # the record FIRST: a random value must be on disk before it becomes the only password the
            # new database accepts
            if new != root and attempt(failed % CREDS_RECORD, lambda: write_creds_record(version, pending=new)) \
                    and attempt(failed % ".env", lambda: write_env_value(version, "MYSQL_ROOT_PASSWORD", new)):
                root, out["mysqlRoot"] = new, source
                _note_secret_source(version, job, mysqlRootSource=source, mysqlRootChangedAt=now)
                job.log("MySQL root password: the vendor's published password replaced with a %s one before the "
                        "database is created -- %s." % (source, where))
        # MYSQL_ROOT_RE: only a value YAML is sure to read back as the same string is written unquoted
        # (every value this agent chooses or accepts is one; a hand-made one outside the rule stays put)
        if root and root not in VENDOR_MYSQL_ROOT_PASSWORDS and MYSQL_ROOT_RE.match(root):
            try:
                if _rewrite(_compose_paths(version)[1],
                            lambda t: set_compose_env_value(t, "MYSQL_ROOT_PASSWORD", root)):
                    out["compose"] = True
                    job.log("docker-compose.yml: MYSQL_ROOT_PASSWORD follows .env (the line only counts when the "
                            "database folder is created).")
            except OSError as e:
                job.log("WARNING: docker-compose.yml could not follow .env's MySQL root password (%s)." % e)
    # 4. creds.txt mirrors the files
    if "flask" in out or "mysqlRoot" in out:
        attempt("creds.txt could not be rewritten -- GET /server/secrets has the current values",
                lambda: write_creds_file(version, current_secrets(version)))
    return out


# The MySQL accounts a password change alters: the two root accounts the mariadb image creates with
# MYSQL_ROOT_HOST "%" (the agent itself logs in as 'root'@'localhost', through the socket), and the two
# game accounts of bootstrap.sql that share the stack's internal password.
MYSQL_ROOT_ACCOUNTS = ("'root'@'%'", "'root'@'localhost'")
MYSQL_GAME_ACCOUNTS = ("'hk4e_work'@'172.10.%'", "'hk4e_readonly'@'172.10.%'")


def _alter_users_sql(pairs):
    """ONE statement for [(account, password)]: `ALTER USER IF EXISTS a IDENTIFIED BY 'x', b IDENTIFIED
    BY 'y'` (the multi-user form, valid on MariaDB 10.9). One statement = one connection = one login
    with the old root password: mysql_exec is a NEW connection as 'root'@'localhost' per call, so a
    second statement sent with the old password is refused the moment that account is altered. No
    FLUSH PRIVILEGES -- ALTER USER takes effect for new connections at once. The passwords obey
    SECRET_VALUE_RE (no quote, no backslash): nothing to escape."""
    return "ALTER USER IF EXISTS " + ", ".join("%s IDENTIFIED BY '%s'" % (account, pw) for account, pw in pairs)


def _scrubbed_err(r, limit, *values):
    """_cmd_err for a command that carried passwords: every given value is cut out of the tool's
    output BEFORE the tail is taken (a truncation must not leave half a password behind) -- a client
    or a server may quote the statement it failed on. Longest first: a value that starts another one
    must not leave that one's tail behind."""
    def scrub(text):
        for v in sorted(set(values), key=len, reverse=True):
            if v:
                text = text.replace(v, "***")
        return text

    return _cmd_err(subprocess.CompletedProcess([], getattr(r, "returncode", 1),
                                                stdout=scrub(getattr(r, "stdout", "") or ""),
                                                stderr=scrub(getattr(r, "stderr", "") or "")), limit)


def _root_password_verdict(version, old, new):
    """After an ALTER USER of root sent with `old`: which password the server accepts NOW -- "new",
    "old", or None for neither. Decided by logging in, never by the statement's exit code (a transport
    error after the server applied it and a refusal before it look the same)."""
    if mysql_exec(version, "SELECT 1", timeout=30, password=new).returncode == 0:
        return "new"
    if mysql_exec(version, "SELECT 1", timeout=30, password=old).returncode == 0:
        return "old"
    return None


def _env_behind_error(e):
    """The 500 for an .env that refuses the new root password right after its ALTER USER: probe_env_writable
    proved the file replaceable before the statement, so this is one that stopped being writable since."""
    return AgentError(500, "The database now has the new MySQL root password, but .env could not be written (%s). "
                           "The password is recorded as pending in %s in the stack folder -- the next Start finds it "
                           "there and repairs .env." % (e, CREDS_RECORD))


def ensure_db_root_password(version, job):
    """The db stage of the rule above. Precondition: wait_for_mysql has just succeeded, i.e. the server
    accepts .env's root password. A vendor literal is replaced with GIO_MYSQL_ROOT_PASSWORD or a random
    value: .env is proven replaceable (probe_env_writable -- a file that cannot be written ends the
    stage here with a WARNING, nothing recorded, nothing sent), then the record's pending line (a
    random value that only lived in memory would be lost for good by a kill right after the ALTER),
    then ONE statement for both root accounts with the old password (_alter_users_sql; never through
    run_sql, which logs its statements), then the verdict by logging in, whatever the statement's
    exit code:
      the new password works   -> .env, the record (root, no pending), creds.txt, the state;
      the old one still works  -> nothing changed: a WARNING, the job goes on;
      neither                  -> 500: the rest of the job must not run on a dead password (the pending
                                  line is what the next Start tries).
    No service logs in as root, so a running stack does not notice; the rendered compose file follows
    .env at the next cold site (ensure_env_secrets) -- no `up`, no wait here. With "Keep .env settings"
    on (KEEP_ENV) a vendor literal is left in place: one job line -- no probe, no record line, no SQL.
    Returns True when the password was changed."""
    try:
        cur = read_env(version).get("MYSQL_ROOT_PASSWORD", "")
    except OSError:
        return False
    if cur not in VENDOR_MYSQL_ROOT_PASSWORDS:
        return False
    if KEEP_ENV:
        job.log("MySQL root password: still the vendor's published password -- kept as it is (GIO_KEEP_ENV).")
        return False
    source = "config" if MYSQL_ROOT_PASSWORD else "random"
    new = MYSQL_ROOT_PASSWORD or random_secret_value()
    if new == cur:
        return False
    try:
        # BEFORE the pending line and the irreversible ALTER: once the database has the new password,
        # an .env that cannot take it locks this agent out of a database it could use until now.
        probe_env_writable(version)
    except OSError as e:
        job.log("WARNING: the vendor's published MySQL root password was NOT replaced -- .env cannot be written "
                "(%s)." % e)
        return False
    try:
        write_creds_record(version, pending=new)
    except OSError as e:
        job.log("WARNING: the vendor's published MySQL root password was NOT replaced -- %s cannot be written "
                "(%s)." % (CREDS_RECORD, e))
        return False
    r = mysql_exec(version, _alter_users_sql([(account, new) for account in MYSQL_ROOT_ACCOUNTS]), password=cur)
    verdict = _root_password_verdict(version, cur, new)
    if verdict != "new":
        why = _scrubbed_err(r, 200, cur, new) if r.returncode != 0 else "the statement reported no error"
        if verdict == "old":
            job.log("WARNING: the vendor's published MySQL root password was NOT replaced -- after ALTER USER the "
                    "server still accepts only the old one (%s). Nothing was changed." % why)
            return False
        raise AgentError(500, "After ALTER USER neither the old nor the new MySQL root password works (%s). The new "
                              "one is recorded as pending in %s in the stack folder -- the next Start tries it and "
                              "repairs .env." % (why, CREDS_RECORD))
    try:
        write_env_value(version, "MYSQL_ROOT_PASSWORD", new)
    except OSError as e:
        raise _env_behind_error(e)
    try:
        write_creds_record(version, root=new, pending="")
    except OSError as e:
        job.log("WARNING: %s could not be updated (%s) -- it keeps the new password as pending." % (CREDS_RECORD, e))
    try:
        write_creds_file(version, current_secrets(version))
    except OSError as e:
        job.log("WARNING: creds.txt could not be rewritten (%s) -- GET /server/secrets has the current values." % e)
    _note_secret_source(version, job, mysqlRootSource=source, mysqlRootChangedAt=time.strftime("%Y-%m-%d %H:%M:%S"))
    job.log("MySQL root password: the vendor's published password replaced with a %s one (ALTER USER; no service "
            "logs in as root, nothing is restarted) -- read it under Server secrets in the launcher or in creds.txt "
            "on the box." % source)
    return True


def _learn_mysql_root(version, job):
    """wait_for_mysql's success branch: the server has just accepted .env's root password. A private
    one (non-empty, not a vendor literal) becomes the record's `root` when the record names another
    or still carries a pending line -- this seeds a stack that has no record at its first wait, converges
    after any crash window and clears a stale pending. Never raises."""
    try:
        cur = read_env(version).get("MYSQL_ROOT_PASSWORD", "")
        if not cur or cur in VENDOR_MYSQL_ROOT_PASSWORDS:
            return
        rec = read_creds_record(version)
        if rec["root"] != cur or rec["pending"]:
            write_creds_record(version, root=cur, pending="")
    except Exception as e:  # noqa: BLE001 -- MySQL IS ready; a note that cannot be written must not undo that
        job.log("WARNING: the MySQL root password could not be noted in %s (%s)." % (CREDS_RECORD, _short_err(e)))


_RECOVERED_WITH = {
    "pending": "the password recorded as pending in " + CREDS_RECORD,
    "record": "the password on record in " + CREDS_RECORD,
    "compose": "the password the rendered docker-compose.yml names",
    "config": "the configured GIO_MYSQL_ROOT_PASSWORD",
    "vendor": "the vendor's published default",
}


def recover_mysql_root_env(version, job):
    """MySQL keeps refusing the root password in .env (wait_for_mysql): try the other passwords this
    agent knows, in this order -- the record's pending line (a change that died between its ALTER and
    the .env write), the record's root (a re-extracted archive put the vendor's .env back), what the
    rendered compose file names (the same, on a stack that has no record yet), GIO_MYSQL_ROOT_PASSWORD,
    the vendor literals (a data dir older than the change) -- each non-empty, one plain line, different
    from .env's value and tried once. The first one the SERVER accepts is written into .env; the
    record becomes root=<it> without a pending line and creds.txt follows. Returns its kind ("pending"
    | "record" | "compose" | "config" | "vendor"), or None when none works -- nothing is written then.
    An .env that cannot be written raises OSError: wait_for_mysql wraps this call. A record that cannot
    be read offers no candidate (the others are still asked)."""
    cur = read_env(version).get("MYSQL_ROOT_PASSWORD", "")
    try:
        rec = read_creds_record(version)
    except OSError:
        rec = {"root": "", "pending": ""}
    tried = set()
    for kind, value in [("pending", rec["pending"]), ("record", rec["root"]),
                        ("compose", rendered_root_password(version)), ("config", MYSQL_ROOT_PASSWORD)] \
            + [("vendor", v) for v in sorted(VENDOR_MYSQL_ROOT_PASSWORDS)]:
        if not value or value == cur or value in tried or plain_line_problem(value) is not None:
            continue
        tried.add(value)
        if mysql_exec(version, "SELECT 1", timeout=30, password=value).returncode != 0:
            continue
        write_env_value(version, "MYSQL_ROOT_PASSWORD", value)
        try:
            write_creds_record(version, root=value, pending="")
        except OSError as e:
            job.log("WARNING: %s could not be updated (%s)." % (CREDS_RECORD, e))
        try:
            write_creds_file(version, current_secrets(version))
        except OSError as e:
            job.log("WARNING: creds.txt could not be rewritten (%s) -- GET /server/secrets has the current values." % e)
        job.log("MySQL refused the root password in .env but accepts %s -- .env repaired." % _RECOVERED_WITH[kind])
        return kind
    return None


def _recover_mysql_root(version, job):
    """wait_for_mysql's recovery round. Never raises: a failure is one WARNING line and the wait goes
    on exactly as it would have."""
    try:
        return bool(recover_mysql_root_env(version, job))
    except Exception as e:  # noqa: BLE001 -- the callers of wait_for_mysql expect nothing but its timeout
        job.log("WARNING: the MySQL root password in .env could not be repaired (%s)." % _short_err(e))
        return False


# -- the stack internal password: the db stage and the two file levels --
# The rule of the root password and the Flask key, for the value the archives publish as redis' requirepass
# and the password of hk4e_work + hk4e_readonly (VENDOR_INTERNAL_PASSWORDS): a stack that still carries it
# gets a RANDOM one (the admin chooses one any time under Server secrets), in every progress mode -- it is
# configuration, not player data -- and only while NO game service runs: every service must start on the new
# value. A private value is never touched. While "Keep .env settings" is on (KEEP_ENV) the vendor's value is
# left as it is at the db stage (one job line, nothing asked of docker or MySQL) and at the file level
# (silently); a change on record is finished all the same, and the re-renders' restore is not affected.
# Three places:
#   db stage    -- ensure_internal_password: do_provision right after ensure_db_root_password, and do_start
#                  while no game service runs. The database first (ALTER USER is the one change that cannot
#                  be made in a file), then every position of every file, then redis -- before the final
#                  `up -d`, which then sees no change but redis' command line, already applied.
#   file level  -- ensure_internal_sources: right before a FRESH bootstrap creates the accounts.
#   re-renders  -- restore_internal_sources: before the loopback heal's and do_secrets' re-render, the sources
#                  follow what the stack runs on (a re-extracted archive put the vendor's value back).
# The record's `internal (pending): <value>` is the change in progress: while it is there no game service
# boots -- do_start finishes the change first, every other path that would start one refuses with 409
# (refuse_while_internal_pending), and a failure after it was written takes the version down. A record that
# cannot be read may hold that line: every gate fails CLOSED on it -- the 409s refuse, and a Start / provision
# boots the game services only over a stack PROVEN consistent (_internal_record_unreadable). The VALUE never
# reaches a job line, the agent log, an error text, the state file or /status: creds.txt and GET
# /server/secrets only. Every login it takes goes through the NON-logging runner (_compose), never through
# _compose_stream (it writes the argv into the job log).

GAME_DB_HOST = "172.10.3.100"  # the mysql container's pinned address -- what prepare-db.sh and every XML use
# The services that do not use the internal password. With only these up (a box rebooted under a stack --
# restart: always brings mysql, redis and sdk back, never the on-failure game services -- or a start that
# failed) a Start still changes it.
INTERNAL_FREE_SERVICES = frozenset(("mysql", "redis", "adminer", "phpmyadmin", "sdk"))
REDIS_READY_WAIT = 30  # seconds a redis recreated with a new password has to answer PONG with it
_GAME_ACCOUNT_ROWS = sorted(tuple(re.match(r"'([^']*)'@'([^']*)'", a).groups()) for a in MYSQL_GAME_ACCOUNTS)
_INTERNAL_WHERE = "read it under Server secrets in the launcher or in creds.txt on the box"


class InternalChangeUnfinished(AgentError):
    """The 500 of a change of the internal password that could not be finished -- or of a stack that could not
    be proven consistent over a record that cannot be read: the version was taken down first
    (_take_version_down)."""


def game_services_up(version):
    """Whether a service of THIS stack that uses the internal password runs -- any but INTERNAL_FREE_SERVICES
    in a state other than exited / dead / created (`docker compose ps -a` of the project); None when docker
    does not answer."""
    r = _compose(stack_dir(version), "ps", "-a", "--format", "json", timeout=60)
    states = _parse_ps_json(r.stdout) if r.returncode == 0 else None
    if states is None:
        return None
    return any(s not in INTERNAL_FREE_SERVICES and st not in ("exited", "dead", "created", "")
               for s, st in states.items())


def game_account_login(version, user, password):
    """ONE login as a game account the way the game services log in: over TCP from the stack network -- the
    accounts exist only at host 172.10.% -- to the mysql container's own address, with `password` (MYSQL_PWD,
    handed over by _exec_args as every root login of this agent; no shell inside the container). "ok" |
    "refused" (ERROR 1045 for that account) | "unknown" (anything else: no container, a timeout, a server
    restarting -- or a server that saw no password at all, which says nothing of this one: _password_dropped).
    The non-logging runner: never a job line."""
    args, env = _exec_args("mysql", ["mysql", "-h" + GAME_DB_HOST, "-u" + user, "-N", "-e", "SELECT 1"],
                           {"MYSQL_PWD": password})
    r = _compose(stack_dir(version), *args, timeout=30, env=env)
    if r.returncode == 0 and (r.stdout or "").strip() == "1":
        return "ok"
    err = getattr(r, "stderr", "") or ""
    if "ERROR 1045" in err and ("Access denied for user '%s'@" % user) in err and not _password_dropped(env, r):
        return "refused"
    return "unknown"


def _game_logins(version, password):
    """(hk4e_work's verdict, hk4e_readonly's verdict) for one password -- the services log in as both."""
    return (game_account_login(version, "hk4e_work", password),
            game_account_login(version, "hk4e_readonly", password))


def _redis_ping(version, password):
    """redis' answer to a `ping` with `password` -- REDISCLI_AUTH (_exec_args): the value is never on an argv,
    redis-cli's inside the container or docker's on the box. "PONG"; "dropped" when redis saw no password although
    one was handed over (_password_dropped: the box's compose); "no" for anything else. The non-logging runner."""
    args, env = _exec_args("redis", ["redis-cli", "ping"], {"REDISCLI_AUTH": password})
    r = _compose(stack_dir(version), *args, timeout=15, env=env)
    if r.returncode == 0 and (r.stdout or "").strip() == "PONG":
        return "PONG"
    return "dropped" if _password_dropped(env, r) else "no"


def redis_answers(version, password):
    """Whether redis answers PONG with `password` (_redis_ping)."""
    return _redis_ping(version, password) == "PONG"


def game_accounts_known(version):
    """The layout check: True when the mysql.user rows of hk4e_work / hk4e_readonly are exactly the two
    accounts this agent alters (MYSQL_GAME_ACCOUNTS), False when they are others, None = no answer. Root,
    through the socket."""
    try:
        r = mysql_exec(version, "SELECT User, Host FROM mysql.user WHERE User IN ('hk4e_work', 'hk4e_readonly')",
                       timeout=30)
    except AgentError:
        return None
    if r.returncode != 0:
        return None
    rows = sorted(tuple(line.split("\t")) for line in (r.stdout or "").splitlines()
                  if line.split("\t")[0] in ("hk4e_work", "hk4e_readonly"))
    return rows == _GAME_ACCOUNT_ROWS


def _internal_candidates(version, pending):
    """What the database may hold, in this order: the pending value, what redis was created with (the
    rendered compose file), the templates' value, the vendor literals -- de-duplicated, plain values only."""
    out = []
    for c in [pending, rendered_internal_password(version), internal_literal(version)] \
            + sorted(VENDOR_INTERNAL_PASSWORDS):
        if c and c not in out and SECRET_VALUE_RE.match(c):
            out.append(c)
    return out


def _learn_internal_password(version, candidates):
    """(D, unknown): D = the first candidate BOTH game accounts accept, None when none does; unknown = a
    login got no clear answer -- nothing can be decided on that."""
    for c in candidates:
        work = game_account_login(version, "hk4e_work", c)
        if work == "unknown":
            return None, True
        if work != "ok":
            continue
        readonly = game_account_login(version, "hk4e_readonly", c)
        if readonly == "unknown":
            return None, True
        if readonly == "ok":
            return c, False
    return None, False


def _take_version_down(version, job):
    """D5: the version DOWN before a 500 of the internal password -- no game service may boot on files and a
    database that may disagree. runningOk False on record first (the watchdogs tend nothing; best effort --
    every caller set it already), then `down --remove-orphans` (best effort, logged: no game service runs at
    this point). Returns the exit code of the down (0 = the version is down)."""
    version_state_set(version, best_effort=True, runningOk=False)
    job.log("Stopping version %s: the stack internal password could not be brought in line..." % version)
    rc = _compose_stream(stack_dir(version), job, "down", "--remove-orphans", prefix="  ")
    if rc != 0:
        job.log("WARNING: docker compose down failed (code %d) -- stop the version before anything else." % rc)
    return rc


def _down_sentence(rc):
    """What a 500 says about _take_version_down's exit code -- never "stopped" when the down failed."""
    if rc == 0:
        return "The version was stopped."
    return "Stopping the version failed (code %d) -- stop it, then Start it again." % rc


def _internal_unfinished(version, job, reason, recorded=True):
    """A change of the internal password that cannot be finished leaves the version DOWN (_take_version_down);
    returns the 500 to raise. The Start that follows finishes the change (do_start, ensure_internal_password)."""
    rc = _take_version_down(version, job)
    return InternalChangeUnfinished(
        500, "Stack internal password: %s.%s %s Start the server again -- the change is finished at that Start."
             % (reason, (" The change is recorded as pending in %s in the stack folder." % CREDS_RECORD)
                if recorded else "", _down_sentence(rc)))


def _internal_unreadable_running_text(err, game_up):
    """The 500 of a Start over a record that cannot be read while the version's game services run -- game_up
    True -- or docker cannot tell (None): the stack can be proven consistent only while none runs."""
    return ("Stack internal password: %s cannot be read (%s) -- %s, so the files and the database cannot be "
            "proven to agree. Make the file readable, then Start again."
            % (CREDS_RECORD, err, "the version's game services run" if game_up
               else "docker cannot tell whether the version's game services run"))


def _failure_text(e):
    return getattr(e, "message", None) or str(e)


def _write_stack_file_durable(path, text):
    """write_text_durable (mode -- prepare-db.sh's exec bit -- and owner kept), through a link: the stack's
    own file is replaced, never the link."""
    if os.path.islink(path):
        path = os.path.realpath(path)
    write_text_durable(path, text)


def _internal_plan(version, value, sources_only=False):
    """What setting every internal-password position to `value` would write -- ([(path, new text)] of the
    files whose positions change, the read-back those texts give) -- with nothing written: the dry run.
    Raises OSError for a file that cannot be read."""
    d = stack_dir(version)
    plan, after = [], {}
    for path, kind, source in internal_password_files(version):
        if sources_only and not source:
            continue
        new, n = set_internal_positions(kind, read_text(path), value)
        after[os.path.relpath(path, d)] = internal_position_values(kind, new)
        if n:
            plan.append((path, new))
    return plan, after


def _probe_internal_plan(plan):
    """Every file of a plan rewritten with its OWN bytes, the way the plan will write it (probe_env_writable's
    idea): one that cannot be replaced is found before anything is recorded or sent. Raises OSError."""
    for path, _new in plan:
        _write_stack_file_durable(path, read_text(path))


def _apply_internal_plan(plan):
    """The plan written, durably: on disk before the record that guards it is cleared. Raises OSError."""
    for path, new in plan:
        _write_stack_file_durable(path, new)


def _redis_answers_within(version, value):
    """(answered, dropped): whether redis answers PONG with `value` within REDIS_READY_WAIT seconds (a redis just
    (re)created may still be loading its data: LOADING) -- and, when it does not, whether its last answer says it
    saw no password at all although one was handed over (_redis_ping "dropped": the box's compose, not the
    value)."""
    deadline = time.time() + REDIS_READY_WAIT
    while True:
        answer = _redis_ping(version, value)
        if answer == "PONG":
            return True, False
        if time.time() >= deadline:
            return False, answer == "dropped"
        time.sleep(1)


def _redis_dropped_why(dropped):
    """What a 500 about a redis that did not answer adds when it saw no password at all (_redis_answers_within)."""
    return " (%s)" % password_dropped_text("redis") if dropped else ""


def _redis_follows(version, job, value):
    """Redis on the value its rendered command line names now, BEFORE any game service boots: `up -d redis`
    recreates redis alone when that line changed (it has no depends_on; `--save 60 1` saves its data when it
    stops and the new container loads it) and changes nothing otherwise; then it must answer PONG with the
    value within REDIS_READY_WAIT seconds. Raises AgentError."""
    rc = _compose_stream(stack_dir(version), job, "up", "-d", "redis", prefix="  ")
    if rc != 0:
        raise AgentError(500, "docker compose up redis failed (code %d)" % rc)
    answered, dropped = _redis_answers_within(version, value)
    if not answered:
        raise AgentError(500, "redis did not answer with the new password within %ds%s"
                         % (REDIS_READY_WAIT, _redis_dropped_why(dropped)))


def _internal_done(version, job, chooser, line):
    """A change of the internal password is complete: creds.txt follows, the state records who chose the value
    and the ONE job line is written -- line None = the hand-off of a fresh bootstrap, whose file level already
    did both."""
    try:
        write_creds_file(version, current_secrets(version))
    except OSError as e:
        job.log("WARNING: creds.txt could not be rewritten (%s) -- GET /server/secrets has the current values." % e)
    if line is None:
        _note_secret_source(version, job, internalPendingSource=None, internalPendingFresh=None)
        return
    _note_secret_source(version, job, internalSource=chooser, internalChangedAt=time.strftime("%Y-%m-%d %H:%M:%S"),
                        internalPendingSource=None, internalPendingFresh=None)
    job.log(line)


def _internal_record_unreadable(version, job, err, game_up):
    """ensure_internal_password over a record that cannot be read (fail closed): a change on record there would
    be invisible, and nothing could go on record either -- so nothing is changed, and instead of trusting the
    record the stack is PROVEN consistent before any game service boots: every position of every file names ONE
    value X, both game accounts accept X over the stack network, and redis -- every caller has just started it
    (the staged `up`) -- answers PONG with X. Proven: one WARNING, the start goes on as it is (a vendor value
    stays until the record can be written). Not proven, a login without a clear answer included: the version
    DOWN and a 500 that says which half failed -- the files and the database, or a redis that did not answer
    with the value the files name. Only while no game service runs: game_up None is asked of docker, and one that
    runs (or no answer) is a 500 -- do_start refuses that case before it changes anything. Returns False."""
    if game_up is None:
        game_up = game_services_up(version)
    if game_up is not False:
        raise AgentError(500, _internal_unreadable_running_text(err, game_up))
    try:
        value = positions_value(internal_positions(version))
    except OSError:
        value = None
    if not (value and SECRET_VALUE_RE.match(value) and _game_logins(version, value) == ("ok", "ok")):
        why = "the files and the database do not agree"
    else:
        answered, dropped = _redis_answers_within(version, value)
        if answered:
            job.log("WARNING: Stack internal password: %s cannot be read (%s) -- the files and the database agree, "
                    "starting anyway." % (CREDS_RECORD, err))
            return False
        why = ("redis did not answer with the password the files name within %ds%s"
               % (REDIS_READY_WAIT, _redis_dropped_why(dropped)))
    rc = _take_version_down(version, job)
    raise InternalChangeUnfinished(
        500, "Stack internal password: %s cannot be read (%s) and %s -- make the file readable, then Start again.%s"
             % (CREDS_RECORD, err, why, "" if rc == 0 else " " + _down_sentence(rc)))


def ensure_internal_password(version, job, game_up=False):
    """The db stage of the stack internal password. Precondition: MySQL has just accepted .env's root password
    (wait_for_mysql, ensure_db_root_password) -- and, game_up False, no game service runs: do_provision after
    down_all; do_start of a stack that was down or ran nothing but INTERNAL_FREE_SERVICES. game_up None (do_start
    of a stack that was up) is asked of docker only when there is something to do; True or no answer = the
    running stack is left alone (changing it restarts every service; /status keeps reporting it).
      cheap exit -- every position of every file names ONE private value and no change is pending: the steady
                    state of a secured stack, nothing asked;
      keep       -- "Keep .env settings" is on (KEEP_ENV) and no change is on record: nothing is replaced or put
                    back and nothing is asked -- not docker, not MySQL --, with one job line when every position
                    names ONE vendor value. A change on record, or a record that cannot be read, goes on below
                    exactly as without the switch: it is finished, or fails closed;
      learn      -- the layout (exactly the two game accounts this agent alters), then D = the first of the
                    pending value, the rendered requirepass, the templates' value, the vendor literals that
                    BOTH accounts accept over the stack network;
      decide     -- a pending change is completed (at once when the database and every file already hold it);
                    a private D the files do not name everywhere is put back, no SQL (a re-extracted archive,
                    a hand edit); a vendor D, or none, is replaced with a random value.
    Whatever stops it before a change is on record is one WARNING and the start goes on as it would have; once a
    change is on record, a failure leaves the version DOWN (InternalChangeUnfinished, 500: the next Start
    finishes it). A record that cannot be read is trusted for nothing: the stack is proven consistent, or the
    version goes down (_internal_record_unreadable). Returns True when it changed or completed something."""
    try:
        pending = read_creds_record(version)["internalPending"]
    except OSError as e:
        return _internal_record_unreadable(version, job, e, game_up)
    try:
        pos, listing_err = internal_positions(version), None
    except OSError as e:
        pos, listing_err = None, e
    held = positions_value(pos) if pos is not None else None
    if not pending and held and held not in VENDOR_INTERNAL_PASSWORDS:
        return False
    if KEEP_ENV and not pending:
        if held:  # (one value everywhere, and the cheap exit above took every private one: the vendor's)
            job.log("Stack internal password: still the vendor's published password -- kept as it is (GIO_KEEP_ENV).")
        return False
    if game_up is None:
        game_up = game_services_up(version)
    if game_up is not False:
        return False

    def give_up(reason):
        """Nothing was changed. Over a change on record nothing may boot either."""
        if pending:
            raise _internal_unfinished(version, job, reason)
        job.log("WARNING: Stack internal password: not replaced -- %s. Nothing was changed." % reason)
        return False

    if pos is None:
        return give_up("the stack's server folders cannot be listed (%s)" % listing_err)
    problem = _layout_problem(pos)
    if problem:
        return give_up(problem)
    known = game_accounts_known(version)
    if known is None:
        return give_up("the game accounts could not be listed (MySQL gave no answer)")
    if not known:
        # a foreign layout is never a reason to fail a start -- unless a change is on record already
        return give_up("this stack's game accounts are not the ones this agent knows")
    learned, unknown = _learn_internal_password(version, _internal_candidates(version, pending))
    if unknown:
        return give_up("the game accounts could not be checked (a login over the stack network got no clear answer)")
    if pending:
        try:
            sec = version_state(version).get("secrets") or {}
        except AgentError:
            sec = {}
        chooser = sec.get("internalPendingSource") or "random"
        if learned == pending and held == pending:
            # the database and every file hold it already (the hand-off of a fresh bootstrap, or a change that
            # died after its last file): redis follows, the record is cleared
            try:
                _redis_follows(version, job, pending)
                write_creds_record(version, internal_pending="")
            except InternalChangeUnfinished:
                raise
            except Exception as e:  # noqa: BLE001 -- a change on record must never end in a stack that boots
                raise _internal_unfinished(version, job, _failure_text(e))
            _internal_done(version, job, chooser, None if sec.get("internalPendingFresh") else
                           "Stack internal password: a change that had not finished was completed -- %s." % _INTERNAL_WHERE)
            return True
        return _change_internal_password(version, job, pending, chooser, learned, pos, previous=True)
    if learned is not None and learned not in VENDOR_INTERNAL_PASSWORDS:
        return _restore_internal_password(version, job, learned, pos)
    return _change_internal_password(version, job, random_secret_value(), "random", learned, pos, previous=False)


def _change_internal_password(version, job, target, chooser, learned, pos, previous):
    """Change the internal password to `target`. learned = what both game accounts accept now (None: none);
    pos = the read-back before; previous = the change is on record already (a run that died, the admin's
    rotation that did not finish). In this order: the dry run (every file can take the value) and the probe
    (every file it writes can be replaced) -- a failure there changes nothing --, the record (who chose the
    value, then the pending line), ONE `ALTER USER` statement for both accounts in one connection (skipped
    when they hold it already), the verdict by logging in as both (never the exit code), every position of
    every file (durably), the read-back, redis, the record cleared. An ALTER the accounts did not take is
    taken back to D -- proven by logging in again, with every file still on D: one WARNING, the start goes
    on; anything else unproven is a 500 with the version down. Returns True when changed."""

    def not_now(reason):
        """Nothing of THIS change was sent or written."""
        if not previous:
            job.log("WARNING: Stack internal password: NOT replaced -- %s. Nothing was changed." % reason)
            return False
        if learned is None or positions_value(pos) != learned:
            raise _internal_unfinished(version, job, reason)
        # the change on record never reached the database or a file: the stack is consistent on D, the wish goes
        try:
            write_creds_record(version, internal_pending="")
        except OSError as e:
            raise _internal_unfinished(version, job, "%s; %s could not be updated (%s)" % (reason, CREDS_RECORD, e))
        _note_secret_source(version, job, internalPendingSource=None, internalPendingFresh=None)
        job.log("WARNING: Stack internal password: NOT replaced -- %s. Nothing was changed: the change that had not "
                "finished is dropped, the stack keeps its current password." % reason)
        return False

    try:
        plan, after = _internal_plan(version, target)
    except OSError as e:
        return not_now("a file that holds it could not be read (%s)" % e)
    problem = _positions_problem(after, target)
    if problem:
        return not_now(problem)
    try:
        _probe_internal_plan(plan)
    except OSError as e:
        return not_now("a file that holds it cannot be written (%s)" % e)
    if not previous:
        # Who chose it goes on record WITH the change (strict), then the change itself -- both before anything
        # is sent: a random value that only lived in memory would be lost for good by a kill after the ALTER.
        try:
            _note_internal_chooser(version, chooser)
        except AgentError as e:
            return not_now("the agent state cannot be written (%s)" % e.message)
        try:
            write_creds_record(version, internal_pending=target)
        except OSError as e:
            _note_secret_source(version, job, internalPendingSource=None)
            return not_now("%s cannot be written (%s)" % (CREDS_RECORD, e))
    vendor_before = learned in VENDOR_INTERNAL_PASSWORDS \
        or any(v in VENDOR_INTERNAL_PASSWORDS for values, _m in pos.values() for v in values)
    try:
        if learned != target:
            try:
                root = read_env(version).get("MYSQL_ROOT_PASSWORD", "")
            except OSError:
                root = ""
            scrub = [target, root] + _internal_candidates(version, "")  # what an error text must never quote
            r = mysql_exec(version, _alter_users_sql([(account, target) for account in MYSQL_GAME_ACCOUNTS]),
                           timeout=60)
            verdicts = _game_logins(version, target)
            if verdicts != ("ok", "ok"):
                why = _scrubbed_err(r, 200, *scrub) if r.returncode != 0 else "the statement reported no error"
                if "unknown" in verdicts or learned is None:
                    raise _internal_unfinished(version, job, "after ALTER USER the game accounts could not be proven "
                                                             "to use either password (%s)" % why)
                # not taken (or by one account only): the old value goes back -- and must be proven back
                mysql_exec(version, _alter_users_sql([(account, learned) for account in MYSQL_GAME_ACCOUNTS]),
                           timeout=60)
                if _game_logins(version, learned) != ("ok", "ok") \
                        or positions_value(internal_positions(version)) != learned:
                    raise _internal_unfinished(version, job, "after ALTER USER the game accounts did not take the new "
                                                             "password (%s), and the old one could not be proven "
                                                             "back everywhere" % why)
                write_creds_record(version, internal_pending="")
                _note_secret_source(version, job, internalPendingSource=None, internalPendingFresh=None)
                job.log("WARNING: Stack internal password: NOT replaced -- after ALTER USER the game accounts did not "
                        "take the new password (%s). Nothing was changed." % why)
                return False
        _apply_internal_plan(plan)
        problem = _positions_problem(internal_positions(version), target)
        if problem:
            raise AgentError(500, "after the rewrite %s" % problem)
        _redis_follows(version, job, target)
        write_creds_record(version, internal_pending="")
    except InternalChangeUnfinished:
        raise
    except Exception as e:  # noqa: BLE001 -- a change on record must never end in a stack that boots
        raise _internal_unfinished(version, job, _failure_text(e))
    if previous:
        line = "Stack internal password: a change that had not finished was completed -- %s." % _INTERNAL_WHERE
    elif vendor_before:
        line = ("Stack internal password (redis, hk4e_work, hk4e_readonly): the vendor's published password replaced "
                "with a random one -- %s." % _INTERNAL_WHERE)
    else:
        line = ("Stack internal password (redis, hk4e_work, hk4e_readonly): the database and the configuration files "
                "did not agree on it -- replaced with a random one everywhere -- %s." % _INTERNAL_WHERE)
    _internal_done(version, job, chooser, line)
    return True


def _restore_line(pos):
    """The job line of a restore: the files carried a vendor literal (a re-extracted archive) or not."""
    if any(v in VENDOR_INTERNAL_PASSWORDS for values, _m in pos.values() for v in values):
        return ("Stack internal password: the configuration files carried the vendor's published password again (a "
                "re-extracted archive) -- the one this stack's database uses was put back.")
    return "Stack internal password: the configuration files were brought back in line with the database."


def _restore_internal_password(version, job, value, pos):
    """RESTORE: the database uses the private `value` while the files no longer all name it (a re-extracted
    archive put the vendor's templates back over a secured stack, a hand edit): every position is set to it
    -- no SQL, no record -- proven by the read-back, and redis follows when its command line changed.
    Stopped before a write = one WARNING; a failure after one = the version down (500). Returns True when
    put back."""
    failed = "WARNING: Stack internal password: the configuration files were NOT brought back in line with the " \
             "database -- %s. Nothing was changed."
    try:
        plan, after = _internal_plan(version, value)
    except OSError as e:
        job.log(failed % ("a file that holds it could not be read (%s)" % e))
        return False
    problem = _positions_problem(after, value)
    if problem:
        job.log(failed % problem)
        return False
    try:
        _probe_internal_plan(plan)
    except OSError as e:
        job.log(failed % ("a file that holds it cannot be written (%s)" % e))
        return False
    redis_changed = rendered_internal_password(version) != value
    try:
        _apply_internal_plan(plan)
        problem = _positions_problem(internal_positions(version), value)
        if problem:
            raise AgentError(500, "after the rewrite %s" % problem)
        if redis_changed:
            _redis_follows(version, job, value)
    except InternalChangeUnfinished:
        raise
    except Exception as e:  # noqa: BLE001 -- files half rewritten must never boot
        raise _internal_unfinished(version, job, "the configuration files could not be brought back in line with "
                                                 "the database (%s)" % _failure_text(e), recorded=False)
    try:
        write_creds_file(version, current_secrets(version))
    except OSError as e:
        job.log("WARNING: creds.txt could not be rewritten (%s) -- GET /server/secrets has the current values." % e)
    job.log(_restore_line(pos))
    return True


def restore_internal_sources(version, job):
    """Before a re-render that is not the db stage's -- the loopback heal (do_bootstrap) and do_secrets without
    `internal` -- which copies the templates into every rendered file: when the SOURCES name a vendor literal
    (or disagree) while the rendered docker-compose.yml names a private plain value -- a re-extracted archive
    over a stack that runs on its own value -- every source position is set to that value first (durably, no
    login: what the running services use is the truth -- the restore_flask_key pattern), or the re-render
    would hand every service a password the database and redis refuse. Skipped while a change is pending
    (the provision / Start that follows completes it). A record that cannot be read does not stop it: it
    writes no record, the sources follow what the running services use either way, and do_secrets refuses such
    a stack before it gets here -- the heal's provision then proves the stack before anything boots. A failure
    is a 500 BEFORE the re-render. Returns True when the sources were put back."""
    if internal_change_pending(version)[0] == "yes":
        return False
    kept = rendered_internal_password(version)
    if not kept or kept in VENDOR_INTERNAL_PASSWORDS or not SECRET_VALUE_RE.match(kept):
        return False
    try:
        pos = internal_positions(version, sources_only=True)
        vals = {v for values, _m in pos.values() for v in values}
        if not (vals & VENDOR_INTERNAL_PASSWORDS or len(vals) > 1):
            return False
        plan, after = _internal_plan(version, kept, sources_only=True)
        problem = _positions_problem(after, kept)
        if problem is None:
            _apply_internal_plan(plan)
            problem = _positions_problem(internal_positions(version, sources_only=True), kept)
    except OSError as e:
        problem = str(e)
    if problem:
        raise AgentError(500, "Stack internal password: the configuration templates no longer name the one this "
                              "stack runs on (a re-extracted archive), and it could not be put back (%s) -- nothing "
                              "was re-rendered: the re-render would hand every service a password the database "
                              "refuses." % problem)
    try:
        write_creds_file(version, current_secrets(version))
    except OSError as e:
        job.log("WARNING: creds.txt could not be rewritten (%s) -- GET /server/secrets has the current values." % e)
    job.log(_restore_line(pos))
    return True


def ensure_internal_sources(version, job):
    """The file level of the internal password, right before a FRESH bootstrap (a forced reinstall included) --
    the one place the vendor bootstrap runs: it creates hk4e_work / hk4e_readonly from bootstrap.sql, imports
    data.sql + adjust.sql AS hk4e_work with prepare-db.sh's value and renders redis and every XML from the
    templates, so the SOURCES must name one value before it starts. When the record holds a pending change, the
    sources name several values, or the one they name is a vendor literal over a database that will certainly
    be created from them (<stack>/mysql absent or empty, or Windows -- see below): the pending value -- else a
    random one -- goes on record FIRST (with who chose it), then into every source position (durably), proven
    by the read-back; the state, creds.txt and one job line when a source changed. No SQL, no render, no `up`:
    the provision's db stage then proves the value silently (over a data dir the vendor script did not wipe,
    CREATE USER IF NOT EXISTS kept the old accounts -- that stage ALTERs them). One vendor value over a data dir
    that may survive the bootstrap is left to that stage. With "Keep .env settings" on (KEEP_ENV) one vendor
    value is left as it is over ANY data dir, silently -- the provision's db stage is the one that says it --,
    while a pending change and sources that name several values are brought in line all the same (the database
    must be created from ONE value). Stopped before a write = one WARNING over sources that agree, a 500 over
    sources that disagree (the database would be created with one value and imported with another) -- a record
    that cannot be read included (nothing can go on record); a failure after a write = 500, the value stays
    pending. Returns the chooser ("random" | "admin") when a source changed, else None."""
    try:
        pos = internal_positions(version, sources_only=True)
    except OSError as e:
        job.log("WARNING: Stack internal password: the source files were not checked before the database is created "
                "(%s)." % e)
        return None
    vals = {v for values, _m in pos.values() for v in values}

    def cannot(reason):
        if len(vals) > 1:
            raise AgentError(500, "Stack internal password: the source files name different values and could not be "
                                  "brought in line (%s) -- not installing: the database would be created with one "
                                  "and imported with another." % reason)
        job.log("WARNING: Stack internal password: not replaced before the database is created -- %s. Nothing was "
                "changed." % reason)
        return None

    try:
        pending = read_creds_record(version)["internalPending"]
    except OSError as e:
        # An unreadable record is an unwritable one: nothing can go on record, so nothing is changed -- sources that
        # disagree stop the install (500), sources that agree are left as they are: the vendor bootstrap runs on
        # their value (the provision that follows proves the stack before its game services boot).
        if len(vals) > 1:
            return cannot("%s cannot be read (%s)" % (CREDS_RECORD, e))
        job.log("WARNING: Stack internal password: %s cannot be read (%s) -- the source files are left as they are "
                "before the database is created." % (CREDS_RECORD, e))
        return None
    if not pending and len(vals) == 1:
        if not vals & VENDOR_INTERNAL_PASSWORDS:
            return None
        if KEEP_ENV:
            return None  # "Keep .env settings": the vendor's value stays in every source, whatever the data dir
        if not IS_WINDOWS and not _dir_absent_or_empty(os.path.join(stack_dir(version), "mysql")):
            # One vendor value over a data dir that may survive the bootstrap: bootstrap.sh's `sudo rm -rf mysql
            # redis` has no `set -e` -- without a working sudo it fails and the script goes on, CREATE USER IF NOT
            # EXISTS keeps both accounts on their old value, and prepare-db.sh's imports AS hk4e_work with a new
            # one would be refused (the config databases left empty). Left alone: the vendor bootstrap runs
            # on the vendor's value, and the provision's db stage replaces the value by ALTER right after it.
            # (Windows: _bootstrap_windows deletes mysql/ itself -- bootstrap_plan_windows' rmtree comes before
            # the `up` that creates the database, and one that fails is a 500 before anything is created -- so
            # the database is always created from the sources there.)
            return None

    if pending:
        try:
            sec = version_state(version).get("secrets") or {}
        except AgentError:
            sec = {}
        target, chooser = pending, sec.get("internalPendingSource") or "random"
    else:
        target, chooser = random_secret_value(), "random"
    try:
        plan, after = _internal_plan(version, target, sources_only=True)
    except OSError as e:
        return cannot("a source file could not be read (%s)" % e)
    problem = _positions_problem(after, target)
    if problem:
        return cannot(problem)
    try:
        _probe_internal_plan(plan)
    except OSError as e:
        return cannot("a source file cannot be written (%s)" % e)
    try:
        # (internalPendingFresh: the database is about to be created with it -- the db stage's proof is silent)
        sec = dict(version_state(version).get("secrets") or {})
        sec.update(internalPendingSource=chooser, internalPendingFresh=True)
        version_state_set(version, strict=True, secrets=sec)
    except AgentError as e:
        return cannot("the agent state cannot be written (%s)" % e.message)
    if not pending:
        try:
            write_creds_record(version, internal_pending=target)
        except OSError as e:
            _note_secret_source(version, job, internalPendingSource=None, internalPendingFresh=None)
            return cannot("%s cannot be written (%s)" % (CREDS_RECORD, e))
    try:
        _apply_internal_plan(plan)
        problem = _positions_problem(internal_positions(version, sources_only=True), target)
    except OSError as e:
        problem = "a source file could not be written (%s)" % e
    if problem:
        raise AgentError(500, "Stack internal password: the source files could not all be brought to the new value "
                              "(%s) -- not installing. The value is recorded as pending in %s in the stack folder; "
                              "run Prepare server again." % (problem, CREDS_RECORD))
    if not plan:
        return None
    _note_secret_source(version, job, internalSource=chooser, internalChangedAt=time.strftime("%Y-%m-%d %H:%M:%S"))
    try:
        write_creds_file(version, current_secrets(version))
    except OSError as e:
        job.log("WARNING: creds.txt could not be rewritten (%s) -- GET /server/secrets has the current values." % e)
    if chooser == "random" and vals & VENDOR_INTERNAL_PASSWORDS:
        job.log("Stack internal password (redis, hk4e_work, hk4e_readonly): the vendor's published password replaced "
                "with a random one before the database is created -- %s." % _INTERNAL_WHERE)
    else:
        job.log("Stack internal password (redis, hk4e_work, hk4e_readonly): every source file names the same value "
                "now, before the database is created -- %s." % _INTERNAL_WHERE)
    return chooser


def secrets_info(version):
    """What GET /server/secrets answers. The MUIP key itself never leaves the box: only whether it
    is set, a short fingerprint and when the agent last changed it."""
    check_known(version)
    if not is_present(version):
        raise AgentError(404, "Version %s does not exist on this server." % version)
    env = read_env(version)
    key = _read_sign_key_file(muip_key_file(version))
    try:
        # Readable over a broken state file on purpose: the current passwords are what an admin
        # needs to repair things by hand. Only the agent's own records become unknown.
        vs = (load_state().get("versions") or {}).get(version) or {}
    except StateUnreadable:
        vs = {}
    sec = vs.get("secrets") or {}
    mysql_kind, flask_kind = secret_kinds(version, env)
    int_kind = internal_kind(version)
    return {
        "mysqlRoot": env.get("MYSQL_ROOT_PASSWORD", ""),
        "flask": env.get("FLASK_SECRET_KEY", ""),
        # what the stack runs on (the rendered compose file once bootstrapped), never only the templates'
        "internal": stack_internal_password(version),
        "muip": {"set": bool(key),
                 "fingerprint": muip_fingerprint(key),
                 "changedAt": sec.get("muipChangedAt"),
                 # still the archive's published key? and who chose the current one
                 # (config = GIO_MUIP_KEY, random = the agent, admin = /server/secrets)
                 "vendorDefault": is_vendor_muip_key(key) if key else None,
                 "source": sec.get("muipSource")},
        "bootstrapped": is_bootstrapped(version),
        "changedAt": sec.get("changedAt"),
        "pending": vs.get("secretsPending"),
        # still the archive's published value? -- the judgement of /status (mysqlPassword /
        # flaskKey: the Flask key where the sdk loads it) -- and who chose the current one (config =
        # GIO_MYSQL_ROOT_PASSWORD / GIO_FLASK_SECRET_KEY, random = the agent, admin = /server/secrets)
        "mysqlRootVendorDefault": mysql_kind == "vendor",
        "mysqlRootSource": sec.get("mysqlRootSource"),
        "flaskVendorDefault": flask_kind == "vendor",
        "flaskSource": sec.get("flaskSource"),
        # ...and the stack internal password (/status internalPassword): still the vendor's? a change of it
        # that has not finished (never its VALUE -- a manual repair reads <stack>/.relic-creds on the box)?
        # who chose the current one (random = the agent, admin = /server/secrets)
        "internalVendorDefault": int_kind == "vendor",
        "internalPending": int_kind == "pending",
        "internalSource": sec.get("internalSource"),
    }


def write_creds_file(version, values):
    """creds.txt is the vendor's plaintext note of every password; rewrite it so it never holds a
    stale copy, mark it as managed, keep it private. Its callers pass current_secrets(version) --
    what the files hold. The creds record (.relic-creds) is NOT its business: that file has its own
    writer and its own rule."""
    path = os.path.join(stack_dir(version), "creds.txt")
    nl = "\n"
    try:
        if "\r\n" in read_text(path):
            nl = "\r\n"
    except OSError:
        pass
    lines = ["# Managed by the Relic GIO agent -- rewritten whenever a secret changes.",
             "mysql/root: %s" % values.get("mysqlRoot", ""),
             "Flask: %s" % values.get("flask", ""),
             "MUIP_KEY: %s" % values.get("muip", ""),
             "h4ke pass: %s" % values.get("internal", "")]
    write_text(path, nl.join(lines) + nl)
    protect_path(path, 0o600)


def do_secrets(version, job, values):
    """Rotate any of the four secrets. On a stack that is not bootstrapped yet only the SOURCES are
    edited (the bootstrap renders them). On a bootstrapped stack the MySQL users are altered with
    the OLD root password BEFORE .env changes, then the sources are edited, the configs re-rendered,
    the advertised IP re-applied (the render reverts the XML IP pass) and the stack restarted
    (players are dropped). A `secretsPending` marker in state tells a diagnosing admin where a
    run that died in the middle got to.

    Every account of the run is altered by ONE statement in ONE connection (sent one per
    login, the old root password would be refused right after 'root'@'localhost' had changed -- a root +
    internal rotation could never finish); for a new root password .env is proven replaceable
    (probe_env_writable) and the value is on record as pending (<stack>/.relic-creds) BEFORE that
    statement, and the outcome is decided by logging in; the root password is re-read after the wait
    (a recovery inside it may have repaired .env); a run that ends before anything was altered takes
    its markers back; and before the re-render overwrites them, the root password the rendered compose
    file still names is noted (rendered_root_to_note) and -- in a run that does not rotate the Flask
    key -- a private key the rendered sdk config still names is put back into .env (restore_flask_key).
    The MUIP sign key likewise: in a run that sets none, a private key the rendered muipserver.xml
    still names is put back into its template before the re-render (restore_muip_key).

    The internal password (the db stage's rules): letter first (redis-server reads a value that
    starts with '-' as an option of its own); every POSITION of every file is set to it -- proven possible
    in memory before anything changes, read back after the re-render; on a bootstrapped stack the game
    accounts must be the two this agent alters (game_accounts_known -- else 500, nothing changed); the
    change is on record as `internal (pending)` in .relic-creds before its ALTER (before the source rewrite
    on a stack that is not bootstrapped), its source "admin" on record before that line, and the line is
    cleared only once the stack RUNS on it -- after verify_stack; on a stopped stack after both game
    accounts accepted the value (logged in while mysql is still up) and the final down; after the read-back
    of one never bootstrapped -- or on an exit proven to have altered nothing (take_back). A bootstrapped
    stack with an unfinished change of it on record -- or a record that cannot be read -- is refused (409):
    its restart would boot the game services over it -- a Start finishes that change first. A run without
    `internal` puts the stack's own value back into the templates before its re-render
    (restore_internal_sources)."""
    require_state_readable()
    if not is_present(version):
        raise AgentError(404, "Version %s does not exist on this server." % version)
    d = stack_dir(version)
    wanted = {}
    for k in SECRET_KNOBS:
        v = values.get(k)
        if v is None or v == "":
            continue
        if k in ("mysqlRoot", "internal"):
            # letter first (MYSQL_ROOT_RE): the rendered compose file carries mysqlRoot unquoted, and
            # redis-server reads an internal password that starts with '-' as an option of its own
            if not isinstance(v, str) or not MYSQL_ROOT_RE.match(v):
                raise AgentError(400, "%s must be 8-128 characters: letters, digits, '_' or '-', "
                                      "starting with a letter." % k)
        elif not isinstance(v, str) or not SECRET_VALUE_RE.match(v):
            raise AgentError(400, "%s must be 8-128 characters: letters, digits, '_' or '-'." % k)
        wanted[k] = v
    if not wanted:
        raise AgentError(400, "Nothing to change (accepted keys: %s)." % ", ".join(SECRET_KNOBS))
    env = read_env(version)
    old_root = env.get("MYSQL_ROOT_PASSWORD", "")
    # what the stack RUNS on (the rendered compose file once bootstrapped), not only the templates'
    old_internal = stack_internal_password(version)
    old_muip = _read_sign_key_file(muip_key_file(version))
    if wanted.get("mysqlRoot") == old_root:
        wanted.pop("mysqlRoot")
    if wanted.get("flask") == env.get("FLASK_SECRET_KEY", ""):
        wanted.pop("flask")
    if wanted.get("internal") == old_internal:
        wanted.pop("internal")
    if wanted.get("muip") == old_muip:
        wanted.pop("muip")
    if not wanted:
        job.log("Every requested value is already in place -- nothing to do.")
        return {"changed": []}
    bootstrapped = is_bootstrapped(version)
    if bootstrapped:
        refuse_while_internal_pending(version)
    if "internal" in wanted:
        # every position of every file must be able to take it -- proven in memory, before anything changes
        try:
            _plan, after = _internal_plan(version, wanted["internal"])
        except OSError as e:
            raise AgentError(500, "A file that holds the stack internal password cannot be read (%s) -- nothing "
                                  "was changed." % e)
        problem = _positions_problem(after, wanted["internal"])
        if problem:
            raise AgentError(500, "The stack internal password cannot be set: %s. Nothing was changed." % problem)
    elif bootstrapped:
        # the re-render below copies the templates into every rendered file: over a re-extracted archive they
        # name the vendor's value again while the database and redis use the stack's own (a 500 here: nothing
        # was changed yet)
        restore_internal_sources(version, job)
    was_up = False
    started_db = False
    internal_noted = False  # this run's `internal (pending)` line is on record

    def drop_internal_note():
        """The change of the internal password is done -- or proven not made: its record goes. One that cannot
        be written is one WARNING (the line then names a value nothing uses -- or what everything uses -- and
        the next Start settles it)."""
        if not internal_noted:
            return
        try:
            write_creds_record(version, internal_pending="")
        except OSError as e:
            job.log("WARNING: %s could not be updated (%s) -- it still lists a change of the stack internal password "
                    "as pending; the next Start of this version settles it." % (CREDS_RECORD, e))
            return
        _note_secret_source(version, job, internalPendingSource=None, internalPendingFresh=None)

    job.log("Changing: %s (stack %s)." % (", ".join(sorted(wanted)),
                                           "bootstrapped" if bootstrapped else "not bootstrapped yet"))
    if bootstrapped:
        projects, ls_err = running_projects()
        if ls_err is not None:
            raise AgentError(500, "Cannot read the docker state (%s) -- retry." % ls_err)
        was_up = VERSIONS[version]["project"] in (projects or [])
        ok_before = version_state(version).get("runningOk")
        # strict, both: the admin's only recovery path for a run that dies in the middle is this
        # marker -- 507 before the down / ALTER USER when it cannot be recorded.
        version_state_set(version, strict=True,
                          secretsPending={"startedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                                          "knobs": sorted(wanted), "stage": "start"})
        version_state_set(version, strict=True, runningOk=False)

        def take_back():
            """Nothing was altered: stop the mysql this run started and take its markers back -- the two
            state markers and this run's internal pending line (fail-safe writes -- the reason the run ends
            must not be replaced by a state error)."""
            if started_db:
                job.log("Stopping mysql again (the stack was down before)...")
                _compose_stream(d, job, "down", "--remove-orphans", prefix="  ")
            drop_internal_note()
            if was_up:
                version_state_set(version, best_effort=True, runningOk=ok_before)
            version_state_set(version, best_effort=True, secretsPending=None)

        pairs = []  # (account, new password) of every MySQL user this run alters -- ONE statement
        if "mysqlRoot" in wanted or "internal" in wanted:
            try:
                if not was_up:
                    down_all(job, keep=version)
                    job.log("Starting mysql to alter the database users...")
                    rc = _compose_stream(d, job, "up", "-d", "mysql", "redis", prefix="  ")
                    if rc != 0:
                        raise AgentError(500, "Could not start mysql (code %d)." % rc)
                    started_db = True
                wait_for_mysql(version, job)
            except AgentError:
                take_back()
                raise
            # A recovery inside the wait may have repaired .env (a re-extracted archive over a running
            # stack): the password to log in with -- and to compare the request with -- is the one
            # .env holds NOW. Nothing may carry a root password across a wait_for_mysql.
            old_root = read_env(version).get("MYSQL_ROOT_PASSWORD", "")
            if wanted.get("mysqlRoot") == old_root:
                wanted.pop("mysqlRoot")
            if not wanted:
                take_back()
                job.log("Every requested value is already in place -- nothing to do.")
                return {"changed": []}
            if "mysqlRoot" in wanted:
                pairs += [(account, wanted["mysqlRoot"]) for account in MYSQL_ROOT_ACCOUNTS]
            if "internal" in wanted:
                # The db stage's layout check, before anything is recorded or sent: `ALTER USER IF EXISTS` answers
                # 0 and changes nothing for game accounts that live at another host -- every file would then name
                # a value the database never had.
                known = game_accounts_known(version)
                if known is not True:
                    take_back()
                    raise AgentError(500, "Stack internal password: %s -- nothing was changed."
                                     % ("this stack's game accounts are not the ones this agent knows" if known is False
                                        else "the game accounts could not be listed (MySQL gave no answer)"))
                pairs += [(account, wanted["internal"]) for account in MYSQL_GAME_ACCOUNTS]
        if pairs:
            passwords = [old_root] + [pw for _account, pw in pairs]  # what an error text must never quote
            if "mysqlRoot" in wanted:
                # .env must be able to take the new password right after the statement: proven first
                # (the same bytes, written the same way) -- nothing is altered for a file that cannot.
                try:
                    probe_env_writable(version)
                except OSError as e:
                    take_back()
                    raise AgentError(500, ".env cannot be written (%s) -- nothing was changed." % e)
                # On record BEFORE the statement: a kill right after it leaves a database whose root
                # password is in no other file -- the next wait_for_mysql finds it here.
                try:
                    write_creds_record(version, pending=wanted["mysqlRoot"])
                except OSError as e:
                    take_back()
                    raise AgentError(500, "%s cannot be written (%s) -- nothing was changed: the new root password "
                                          "must be on record there before the database is altered."
                                     % (CREDS_RECORD, e))
            if "internal" in wanted:
                # The internal password likewise: a run that dies after the statement leaves game
                # accounts that may already have it -- the next Start finds the change here and finishes it
                # (no game service is booted over it meanwhile). Who chose it goes on record FIRST (strict, like
                # the db stage's): the Start that completes it must not call the admin's value the agent's. A
                # line that cannot be written puts the chooser back as it was.
                try:
                    chooser_before = _note_internal_chooser(version, "admin")
                except AgentError:
                    take_back()
                    raise
                try:
                    write_creds_record(version, internal_pending=wanted["internal"])
                except OSError as e:
                    _note_secret_source(version, job, **chooser_before)
                    take_back()
                    raise AgentError(500, "%s cannot be written (%s) -- nothing was changed: the new internal "
                                          "password must be on record there before the database is altered."
                                     % (CREDS_RECORD, e))
                internal_noted = True
            job.log("Altering the MySQL users with the current root password...")
            r = mysql_exec(version, _alter_users_sql(pairs), password=old_root)
            why = _scrubbed_err(r, 300, *passwords) if r.returncode != 0 else "the statement reported no error"
            unproven = ("whether the game accounts took the new internal password could not be proven -- it is "
                        "recorded as pending in %s in the stack folder: the next Start of this version completes "
                        "that change." % CREDS_RECORD)
            if "mysqlRoot" in wanted:
                verdict = _root_password_verdict(version, old_root, wanted["mysqlRoot"])
                if verdict == "old":
                    # the root accounts did not take it; an ALTER USER of several accounts is not atomic, so
                    # "nothing was changed" needs the game accounts' answer too
                    if "internal" in wanted and _game_logins(version, wanted["internal"]) != ("refused", "refused"):
                        raise AgentError(500, "ALTER USER failed for the root accounts (%s), the old root password "
                                              "still applies -- and %s" % (why, unproven))
                    take_back()
                    raise AgentError(500, "ALTER USER failed -- nothing was changed, the old root password still "
                                          "applies: %s" % why)
                if verdict is None:
                    raise AgentError(500, "After ALTER USER neither the old nor the new root password works (%s). The "
                                          "new one is recorded as pending in %s in the stack folder -- the next "
                                          "Start tries it and repairs .env." % (why, CREDS_RECORD))
                if r.returncode != 0 and "internal" in wanted:
                    # The one statement answered an error although root WAS altered: whether the game
                    # accounts got their password is in doubt. Say that half again, logged in with the
                    # new root password -- the same values, harmless where they were already applied.
                    r = mysql_exec(version, _alter_users_sql([(account, wanted["internal"])
                                                              for account in MYSQL_GAME_ACCOUNTS]),
                                   password=wanted["mysqlRoot"])
                    if r.returncode != 0:
                        raise AgentError(500, "The root password was changed, but ALTER USER failed for the game "
                                              "accounts: %s. Both new passwords are recorded as pending in %s in "
                                              "the stack folder -- the next Start puts the root one into .env and "
                                              "completes the change of the internal one."
                                         % (_scrubbed_err(r, 300, *passwords), CREDS_RECORD))
            elif r.returncode != 0:
                # internal only: the exit code is no verdict (a transport error after the server applied it
                # looks like a refusal) -- logging in as both game accounts is
                verdicts = _game_logins(version, wanted["internal"])
                if verdicts == ("refused", "refused"):
                    take_back()
                    raise AgentError(500, "ALTER USER failed -- nothing was changed: %s" % why)
                if verdicts != ("ok", "ok"):
                    raise AgentError(500, "ALTER USER failed (%s) -- and %s" % (why, unproven))
            for account, _pw in pairs:
                job.log("  ok: ALTER USER " + account)
            if "mysqlRoot" in wanted:
                job.log("New root password verified.")
            # strict: 507 before .env changes -- "start" on record would claim the users were not
            # altered yet, while the old root password no longer works.
            version_state_set(version, strict=True,
                              secretsPending={"startedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                                              "knobs": sorted(wanted), "stage": "users-altered"})
    elif "internal" in wanted:
        # No database yet -- the sources are all there is. On record before any file changes all the same (who
        # chose it first, strict -- a 507 / 503 here changed nothing): the next Prepare server completes a value
        # a run that died half way through them was writing. A line that cannot be written puts the chooser back
        # as it was: an earlier change may still be on record here (a fresh install whose bootstrap failed after
        # its sources took a value), and it keeps its own.
        chooser_before = _note_internal_chooser(version, "admin")
        try:
            write_creds_record(version, internal_pending=wanted["internal"])
        except OSError as e:
            _note_secret_source(version, job, **chooser_before)
            raise AgentError(500, "%s cannot be written (%s) -- nothing was changed." % (CREDS_RECORD, e))
        internal_noted = True

    changed = []
    if "mysqlRoot" in wanted:
        if bootstrapped:
            try:
                write_env_value(version, "MYSQL_ROOT_PASSWORD", wanted["mysqlRoot"])
            except OSError as e:
                raise _env_behind_error(e)
        else:
            # File only: there is no database yet whose answer could prove the value -- pending on
            # record until the first wait_for_mysql after the bootstrap learns it.
            try:
                write_creds_record(version, pending=wanted["mysqlRoot"])
            except OSError as e:
                job.log("WARNING: the new root password could not be noted in %s (%s)." % (CREDS_RECORD, e))
            write_env_value(version, "MYSQL_ROOT_PASSWORD", wanted["mysqlRoot"])
        changed.append("mysqlRoot")
        job.log(".env MYSQL_ROOT_PASSWORD updated.")
        if bootstrapped:
            try:
                write_creds_record(version, root=wanted["mysqlRoot"], pending="")  # the server accepted it above
            except OSError as e:
                job.log("WARNING: %s could not be updated (%s) -- it keeps the new password as pending."
                        % (CREDS_RECORD, e))
    if "flask" in wanted:
        write_env_value(version, "FLASK_SECRET_KEY", wanted["flask"])
        changed.append("flask")
        job.log(".env FLASK_SECRET_KEY updated.")
    if "internal" in wanted:
        new = wanted["internal"]
        # Every POSITION of every file -- sources and rendered files alike, whatever value each held (the
        # re-render below then renders the templates' value into the rendered ones again).
        try:
            plan, _after = _internal_plan(version, new)
            _apply_internal_plan(plan)
        except OSError as e:
            raise AgentError(500, "The stack internal password could not be written into every file (%s). The new "
                                  "value is recorded as pending in %s in the stack folder -- %s"
                             % (e, CREDS_RECORD, "the next Start of this version completes the change." if bootstrapped
                                else "the next Prepare server completes the change."))
        job.log("Stack internal password set in %d file(s): bootstrap.sql, the compose files, prepare-db.sh, the "
                "server XMLs." % len(plan))
        if not bootstrapped:
            problem = _positions_problem(internal_positions(version), new)
            if problem:
                raise AgentError(500, "The stack internal password was not set everywhere: %s. The new value is "
                                      "recorded as pending in %s in the stack folder -- the next Prepare server "
                                      "completes the change." % (problem, CREDS_RECORD))
            drop_internal_note()
        changed.append("internal")
    if "muip" in wanted:
        n = _rewrite(muip_key_file(version), lambda t: replace_sign_key(t, wanted["muip"]))
        if n == 0:
            raise AgentError(500, "sign_key not found in muipserver.xml.tmpl -- the MUIP key was not changed.")
        rendered = os.path.join(d, "server", "muipserver", "conf", "muipserver.xml")
        if os.path.isfile(rendered):
            _rewrite(rendered, lambda t: replace_sign_key(t, wanted["muip"]))
        changed.append("muip")
        job.log("MUIP sign key replaced (fingerprint %s)." % hashlib.sha256(wanted["muip"].encode()).hexdigest()[:8])
    if bootstrapped:
        # The re-render replaces the compose file's MYSQL_ROOT_PASSWORD line with .env's value. When .env
        # is the vendor's again (a re-extracted archive) or names a value the record does not prove (an
        # .env edited by hand) on a stack that has no record yet, that line is the last place that names
        # the database's real root password -- and a Flask / MUIP-only run has waited for no MySQL that
        # could have put it back into .env. On record first, exactly as before the loopback heal's
        # re-render (ensure_env_secrets, step 1): the next wait finds it.
        named = rendered_root_to_note(version, read_env(version).get("MYSQL_ROOT_PASSWORD", ""))
        if named:
            try:
                write_creds_record(version, pending=named)
            except OSError as e:
                job.log("WARNING: the root password the rendered docker-compose.yml names could not be noted "
                        "in %s (%s)." % (CREDS_RECORD, e))
        if "flask" not in wanted:
            # The Flask key likewise (the heal does it in step 2): over a re-extracted archive .env
            # carries the vendor's key again while the rendered sdk/data/config.json still names this
            # stack's own -- back into .env first, or the re-render hands the sdk the published key.
            # Restore only: a vendor key nobody asked to change is not replaced by a rotation.
            restore_flask_key(version, job, read_env(version).get("FLASK_SECRET_KEY", ""))
        if "muip" not in wanted:
            # ...and the MUIP sign key: over a re-extracted archive muipserver.xml.tmpl carries the
            # vendor's key again while the rendered muipserver.xml still names this stack's own -- back
            # into the template first, or the re-render hands muipserver the published key, which
            # anyone can sign GM commands with (and with "Keep .env settings" on no later Start
            # replaces it). Restore only, like the Flask key.
            restore_muip_key(version, job)
        job.log("Re-rendering the stack configs from the templates...")
        render_stack_configs(version, job)
        # The render reverts the XML half of the advertised-IP pass -- 4206 for everyone outside
        # the LAN otherwise.
        apply_advertised_ip(version, job, with_sql=False)
        if "internal" in wanted:
            # the read-back after the re-render: every source and every rendered file names the new value
            problem = _positions_problem(internal_positions(version), wanted["internal"])
            if problem:
                raise AgentError(500, "After the re-render the stack internal password is not set everywhere: %s. "
                                      "The new value is recorded as pending in %s in the stack folder -- the next "
                                      "Start of this version completes the change." % (problem, CREDS_RECORD))
    # What the files hold NOW, not the values captured before the wait: a recovery inside it may have
    # repaired .env's root password.
    write_creds_file(version, current_secrets(version))
    job.log("creds.txt rewritten (private).")
    sec = dict(version_state(version).get("secrets") or {})
    sec["changedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
    if "muip" in wanted:
        sec["muipChangedAt"] = sec["changedAt"]
        sec["muipSource"] = "admin"
    if "mysqlRoot" in wanted:
        sec["mysqlRootChangedAt"] = sec["changedAt"]
        sec["mysqlRootSource"] = "admin"
    if "flask" in wanted:
        sec["flaskChangedAt"] = sec["changedAt"]
        sec["flaskSource"] = "admin"
    if "internal" in wanted:
        sec["internalChangedAt"] = sec["changedAt"]
        sec["internalSource"] = "admin"
    version_state_set(version, secrets=sec)
    if bootstrapped:
        version_state_set(version, secretsPending={"startedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
                                                   "knobs": sorted(wanted), "stage": "restart"})
        if was_up:
            job.log("Restarting the stack so every service picks the new secrets up (players are "
                    "dropped)...")
            rc = _compose_stream(d, job, "down", "--remove-orphans", prefix="  ")
            if rc != 0:
                raise AgentError(500, "docker compose down failed (code %d)." % rc)
            # The game services boot again below: a data file of the gameplay settings that the game
            # server never confirmed goes back to its original first (silent without such settings).
            tweaks_before_boot(version, job)
            rc = _compose_stream(d, job, "up", "-d", "mysql", "redis", prefix="  ")
            if rc != 0:
                raise AgentError(500, "docker compose up mysql/redis failed (code %d)." % rc)
            wait_for_mysql(version, job)
            rc = _compose_stream(d, job, "up", "-d", prefix="  ")
            if rc != 0:
                raise AgentError(500, "docker compose up failed (code %d)." % rc)
            verify_stack(version, job)
            drop_internal_note()  # the stack RUNS on the new internal password: the change is done
            version_state_set(version, runningOk=True)
        elif started_db:
            # Nothing boots here to prove the change, and an ALTER USER that answered 0 may have changed nothing:
            # both game accounts must accept the new value -- asked while mysql is still up -- before the record
            # of the change may go. Unproven: the line stays, and the next Start completes the change.
            proven = "internal" not in wanted or _game_logins(version, wanted["internal"]) == ("ok", "ok")
            job.log("Stopping mysql again (the stack was down before)...")
            _compose_stream(d, job, "down", "--remove-orphans", prefix="  ")
            if not proven:
                raise AgentError(500, "Stack internal password: after ALTER USER the game accounts could not be "
                                      "proven to use the new password -- it is recorded as pending in %s in the "
                                      "stack folder: the next Start of this version completes that change."
                                 % CREDS_RECORD)
            drop_internal_note()  # down, every file and the database on it: its next start runs on it
        version_state_set(version, secretsPending=None)
    return {"changed": changed}


# -- in-game password verification + account passwords --

PW_VERIFY_RE = re.compile(r'("enable_password_verify"\s*:\s*)(true|false)')
BCRYPT_RE = re.compile(r"^\$2[aby]\$\d\d\$[./A-Za-z0-9]{53}$")
# Runs INSIDE the sdk container (bcrypt is in its image, never on the host): same formula as the
# vendor's utils.password_hash -- bcrypt over the sha256 hexdigest. The password arrives on stdin as the
# bytes _run hands over, ended by "\n"; a password holds no CR or LF (PASSWORD_RE), so every one at its
# end goes -- a line end a runner turned into "\r\n" never becomes part of the hash.
BCRYPT_SCRIPT = ("import sys, hashlib, bcrypt\n"
                 "pw = sys.stdin.read().rstrip('\\r\\n')\n"
                 "h = bcrypt.hashpw(hashlib.sha256(pw.encode()).hexdigest().encode(), bcrypt.gensalt(12))\n"
                 "sys.stdout.write(h.decode())\n")
# Runs INSIDE the sdk container, the one process that keeps sdk.db open (the vendor mounts ./sdk at /app): one JSON
# line on stdin, {name, hash in base64}; the hash goes in as BYTES, a sqlite BLOB -- the sdk calls
# bcrypt.checkpw(bytes, hashed) -- and the row count comes back.
SDK_SET_HASH_SCRIPT = ("import base64, json, sqlite3, sys\n"
                       "line = json.loads(sys.stdin.readline())\n"
                       "con = sqlite3.connect('/app/data/sdk.db', timeout=10)\n"
                       "cur = con.execute('UPDATE accounts SET password=? WHERE name=? AND type=1',\n"
                       "                  (base64.b64decode(line['hash']), line['name']))\n"
                       "con.commit()\n"
                       "print(cur.rowcount)\n")


def set_password_verify_text(text, on):
    """Flip the one boolean in config.json(.tmpl) with a regex -- the file is never re-serialised
    (it carries RSA keys and the vendor's formatting). Returns (new_text, n)."""
    return PW_VERIFY_RE.subn(r"\g<1>%s" % ("true" if on else "false"), text)


def sdk_password_verify_at(folder):
    """sdk_password_verify_setting's rule on any server folder -- a configured stack, or the folder a move reads a
    save from: what its sdk/data/config.json.tmpl says, True/False; None when it has no such file or flag."""
    try:
        m = PW_VERIFY_RE.search(read_text(os.path.join(folder, "sdk", "data", "config.json.tmpl")))
    except (OSError, ValueError):  # ValueError: not UTF-8
        return None
    return None if m is None else m.group(2) == "true"


def sdk_password_verify_setting(version):
    """What sdk/data/config.json.tmpl (the file do_auth rewrites) says: True/False, None when the
    stack has no such file or flag."""
    if not is_configured(version):
        return None
    return sdk_password_verify_at(stack_dir(version))


def reconcile_password_verify(data):
    """A state rebuilt without the last writes (reset, .bak restore): take passwordVerify from the
    sdk config of every configured stack. Mutates `data`; returns the "<version>=<bool>" changes."""
    if not isinstance(data.get("versions"), dict):
        data["versions"] = {}
    changed = []
    for v in configured_versions():
        on = sdk_password_verify_setting(v)
        vs = data["versions"].get(v)
        if on is None or bool((vs or {}).get("passwordVerify")) == on:
            continue
        data["versions"].setdefault(v, {})["passwordVerify"] = on
        changed.append("%s=%s" % (v, "true" if on else "false"))
    if not data["versions"]:
        del data["versions"]
    return changed


def _manifest_password(version):
    """The manifest's password when it is a real one (the 2.8 payload says 'any')."""
    pw = (read_manifest(version) or {}).get("password") or ""
    return pw if PASSWORD_RE.match(pw) else ""


def bcrypt_hash_in_sdk(version, password):
    d = stack_dir(version)
    r = _run(["docker", "compose", "--project-directory", d, "exec", "-T", "sdk", "python", "-c",
              BCRYPT_SCRIPT], input_text=password + "\n", timeout=120)
    if r.returncode != 0:
        raise AgentError(503, "Could not compute the password hash inside the sdk container (is the "
                              "stack up?): %s" % _cmd_err(r, 200))
    h = (r.stdout or "").strip()
    if not BCRYPT_RE.match(h):
        raise AgentError(500, "Unexpected bcrypt output from the sdk container.")
    return h.encode("ascii")


def sdk_store_password(version, name, hash_bytes):
    """UPDATE accounts SET password=<BLOB> on the live sdk.db (sqlite locks the write; the sdk
    calls bcrypt.checkpw(bytes, hashed), so the hash MUST be stored as bytes). Returns the exact
    account name."""
    acc = _sdk_db_lookup(version, name)
    if acc is None:
        raise AgentError(404, "Account '%s' does not exist on the server." % name)
    exact = acc[1]
    con = sqlite3.connect(_sdk_db_path(version), timeout=10)
    try:
        cur = con.execute("UPDATE accounts SET password = ? WHERE name = ?", (hash_bytes, exact))
        con.commit()
        if cur.rowcount != 1:
            raise AgentError(500, "The password row for '%s' was not updated." % exact)
    finally:
        con.close()
    return exact


def sdk_store_hash_in_sdk(version, name, hash_bytes):
    """Store a password hash a move brought for the account of EXACTLY this login, through the sdk container
    (SDK_SET_HASH_SCRIPT), never from the host: the hash travels on stdin alone -- never an argv, a line or a log -- and
    the script's row count must say the one account was written. AgentError otherwise, naming neither."""
    line = json.dumps({"name": name, "hash": base64.b64encode(hash_bytes).decode("ascii")}) + "\n"
    r = _run(["docker", "compose", "--project-directory", stack_dir(version), "exec", "-T", "sdk", "python", "-c",
              SDK_SET_HASH_SCRIPT], input_text=line, timeout=120)
    if r.returncode != 0:
        raise AgentError(503, "the sdk container did not write it: %s" % _cmd_err(r, 200, fallback="no answer"))
    written = (r.stdout or "").strip()
    if written != "1":
        raise AgentError(500, "the account database changed %s row(s) instead of one" % (written or "no"))


def set_account_password(version, job, name, password):
    if not (isinstance(password, str) and PASSWORD_RE.match(password)):
        raise AgentError(400, "The password must be 8-64 printable characters.")
    if VERSIONS[version]["project"] not in (running_projects()[0] or []):
        raise AgentError(409, "Version %s is not running -- the password hash is computed inside the "
                              "sdk container." % version)
    h = bcrypt_hash_in_sdk(version, password)
    exact = sdk_store_password(version, name, h)
    job.log("Password set for account '%s'." % exact)
    return exact


def do_account_password(version, job, name, password):
    if not is_bootstrapped(version):
        raise AgentError(409, "Version %s is not installed on the server." % version)
    exact = set_account_password(version, job, str(name).strip(), password)
    return {"name": exact}


def apply_pending_password(version, job):
    """A verify-ON switch done while the stack was down deferred the default account's password
    to the next start -- set it now (never fatal)."""
    vs = version_state(version)
    if not vs.get("passwordPending"):
        return
    if not vs.get("defaultAccount"):
        # A keep/fixes stack (or one bootstrapped afresh) has no pre-made account: without this the
        # sdk answers "does not exist" at every start and the pending flag never clears.
        job.log("No pre-made account on this server -- nothing to set.")
        version_state_set(version, passwordPending=False)
        return
    acc = (read_manifest(version) or {}).get("account")
    pw = vs.get("defaultPassword") or _manifest_password(version)
    if not acc or not pw:
        version_state_set(version, passwordPending=False)
        return
    try:
        set_account_password(version, job, acc, pw)
        version_state_set(version, passwordPending=False)
    except AgentError as e:
        job.log("WARNING: could not set the default account's password (%s) -- will retry at the "
                "next start." % e.message)


def do_auth(version, job, verify, default_password=None):
    """Turn in-game password verification on/off: edit the sdk config template AND the rendered
    file (the sdk re-reads its config per request, no restart needed), persist the choice and,
    when turning it on, set the default account's password so the shipped account stays usable."""
    require_state_readable()
    if not is_present(version):
        raise AgentError(404, "Version %s does not exist on this server." % version)
    if default_password is not None and default_password != "" and \
            not (isinstance(default_password, str) and PASSWORD_RE.match(default_password)):
        raise AgentError(400, "defaultPassword must be 8-64 printable characters.")
    d = stack_dir(version)
    tmpl = os.path.join(d, "sdk", "data", "config.json.tmpl")
    rendered = os.path.join(d, "sdk", "data", "config.json")
    if not os.path.isfile(tmpl):
        raise AgentError(500, "sdk/data/config.json.tmpl is missing in %s." % d)
    n = _rewrite(tmpl, lambda t: set_password_verify_text(t, verify))
    if n == 0:
        raise AgentError(500, "enable_password_verify not found in sdk/data/config.json.tmpl.")
    if os.path.isfile(rendered):
        _rewrite(rendered, lambda t: set_password_verify_text(t, verify))
    job.log("enable_password_verify = %s written to the sdk config%s."
            % ("true" if verify else "false", " (template + rendered)" if os.path.isfile(rendered) else " (template)"))
    st = {"passwordVerify": bool(verify)}
    if default_password:
        st["defaultPassword"] = default_password
    version_state_set(version, **st)
    result = {"passwordVerify": bool(verify), "defaultPasswordSet": False}
    if verify:
        acc = (read_manifest(version) or {}).get("account")
        pw = default_password or version_state(version).get("defaultPassword") or _manifest_password(version)
        if not version_state(version).get("defaultAccount"):
            # keep/fixes stack: the manifest names an account this database does not hold
            job.log("No pre-made account on this server -- nothing to set.")
            version_state_set(version, passwordPending=False)
        elif not acc:
            job.log("No default account in the manifest -- nothing to set.")
        elif not pw:
            job.log("No default password known for '%s' -- it keeps its current one (set one with "
                    "the account-password action)." % acc)
        elif VERSIONS[version]["project"] in (running_projects()[0] or []):
            try:
                set_account_password(version, job, acc, pw)
                version_state_set(version, passwordPending=False)
                result["defaultPasswordSet"] = True
            except AgentError as e:
                version_state_set(version, passwordPending=True)
                job.log("WARNING: %s -- the password will be set at the next start." % e.message)
        else:
            version_state_set(version, passwordPending=True)
            job.log("The stack is down -- the default account's password will be set at the next start.")
    else:
        version_state_set(version, passwordPending=False)
    _invalidate_public_status()
    return result


# -- agent settings: GET/POST /agent/config, POST /agent/restart --
# An allowlist of the GIO_* keys the launcher's "Agent settings" card may change. POST /agent/config
# writes them into the file this agent was started from (CONFIG_PATH: --config, else the systemd
# EnvironmentFile) and applies the `live` ones to the running process at once -- the code reads those
# globals at every use --; a `restart` one is read once at start and waits for POST /agent/restart.
# What identifies the box or guards it (token, listen address, MUIP key, state / payload paths, region)
# is never editable here, and a stack folder moves only through POST /server/relocate. A key the
# process environment sets to something else than the file (an exported variable, another EnvironmentFile=
# of a systemd drop-in -- env_overridden) is shown but refused: editing the file would change nothing.
# The spike reads the tuple below with a regex (every key needs agentCfg.key.<KEY> +
# agentCfg.key.<KEY>.sub in en.json): keep it a literal on consecutive lines, with no parenthesis inside.
AGENT_SETTING_KEYS = (
    "GIO_SERVER_NAME", "GIO_PROVISION_MODE", "GIO_TXT_FIXES_MODE", "GIO_PATHFINDING", "GIO_KEEP_ENV",
    "GIO_BIND_IP", "GIO_ADVERTISED_IP", "GIO_ADVERTISED_HOST", "GIO_ADVERTISED_ALLOW_PRIVATE",
    "GIO_ADVERTISED_CHECK", "GIO_MUIP_HOST", "GIO_HOTPATCH_URL", "GIO_TRUST_PROXY",
    "GIO_HOTPATCH_DIR", "GIO_HOTPATCH_BUNDLE_DIR", "GIO_7Z",
    "GIO_FETCH_DISK_RESERVE", "GIO_HOTPATCH_DISK_RESERVE", "GIO_HOTPATCH_ONDEMAND_MAX",
    "GIO_HOTPATCH_UPSTREAM", "GIO_HOTPATCH_BUNDLES", "GIO_TLS_PINNED_FALLBACK", "GIO_CA_FILE",
)
SETTING_MIB_MAX = 10485760       # 10 TiB -- any reserve / budget beyond it is a typo
SETTING_SECONDS = (30, 86400)    # GIO_ADVERTISED_CHECK: the watchdog's floor .. once a day
SETTING_TEXT_MAX = 64
# A path or URL value (and a relocation folder) longer than this is a paste accident: Windows refuses an
# environment variable over 32767 characters and Linux an argument over 128 KiB (systemd's execve).
SETTING_PATH_MAX = 4096
# Line breaks beyond the C0 controls: str.splitlines() breaks at them, systemd / bash / the launcher do not.
_UNICODE_LINE_BREAKS = "\x85\u2028\u2029"


def plain_line_problem(v):
    """Why v cannot be stored as one KEY=value line of the config file -- None when it can. A control
    character (C0, DEL, C1 -- NEL among them), a Unicode line or paragraph separator (every character
    str.splitlines() breaks at is one of these), or a lone surrogate (a JSON "\\udc80": it would land in
    the file as a raw byte no UTF-8 reader accepts). Shared by the settings and the stack relocation."""
    if any(ord(c) < 32 or 127 <= ord(c) <= 159 or c in _UNICODE_LINE_BREAKS for c in v):
        return "must be one line of plain text (no newline, tab, line separator or control character)"
    try:
        v.encode("utf-8")
    except UnicodeEncodeError:
        return "must be valid text (no unpaired surrogate)"
    return None


def _show_flag(v):
    return "1" if v else "0"


def _show_mib(v):
    return str(int(v) >> 20)


def _strip(raw):
    return (raw or "").strip()


def _setting(group, type_, apply, var, parse, show=str, choices=None, check=None):
    """One registry row. parse(raw) turns the config string (None = the key is absent) into exactly
    what the import-time code above produces for it -- the live apply and the next-start view both
    use it (selftest-locked against those expressions); show() turns the global back into a string;
    check narrows a path: "file" (an existing file), "pem" (a loadable PEM bundle), "dir" (not a file)."""
    return {"group": group, "type": type_, "apply": apply, "var": var, "parse": parse, "show": show,
            "choices": choices, "check": check}


AGENT_SETTINGS = {
    "GIO_SERVER_NAME": _setting("general", "text", "live", "SERVER_NAME",
                                lambda raw: (raw or "").strip() or socket.gethostname()),
    "GIO_PROVISION_MODE": _setting("general", "enum", "live", "PROVISION_MODE",
                                   lambda raw: ("once" if raw is None else raw).strip().lower(),
                                   choices=("once", "switch", "never")),
    "GIO_TXT_FIXES_MODE": _setting("general", "enum", "live", "TXT_FIXES_MODE",
                                   lambda raw: ("now" if raw is None else raw).strip().lower(),
                                   choices=("now", "later")),
    # the setup-time default of a stack prepared without an explicit choice; never changes a stack
    "GIO_PATHFINDING": _setting("general", "bool", "live", "PATHFINDING_DEFAULT", _flag_on, _show_flag),
    # "Keep .env settings": read at every Prepare / Start; a stack already changed is not changed back
    "GIO_KEEP_ENV": _setting("general", "bool", "live", "KEEP_ENV", _flag_off, _show_flag),
    # read by ensure_bind_ip before a bootstrap renders .env (and by the loopback heal); an installed
    # stack keeps the OUTER_IP it was set up with
    "GIO_BIND_IP": _setting("network", "ip", "live", "BIND_IP", _strip),
    # the running value is the one this process started with (ADVERTISED_IP follows a DDNS host)
    "GIO_ADVERTISED_IP": _setting("network", "ip", "restart", "_BOOT_ADVERTISED_IP", _strip),
    # the advertise watchdog thread exists only when a host was set at start
    "GIO_ADVERTISED_HOST": _setting("network", "host", "restart", "ADVERTISED_HOST",
                                    lambda raw: (raw or "").strip().rstrip(".")),
    "GIO_ADVERTISED_ALLOW_PRIVATE": _setting("network", "bool", "live", "ADVERTISED_ALLOW_PRIVATE", _flag_off,
                                             _show_flag),
    "GIO_ADVERTISED_CHECK": _setting("network", "seconds", "live", "ADVERTISED_CHECK", _parse_check_every),
    "GIO_MUIP_HOST": _setting("network", "url", "live", "MUIP_HOST", _strip),
    # lands in t_region_config at the next hotpatch apply
    "GIO_HOTPATCH_URL": _setting("network", "url", "live", "HOTPATCH_URL",
                                 lambda raw: (raw or "").strip().rstrip("/")),
    "GIO_TRUST_PROXY": _setting("network", "bool", "live", "TRUST_PROXY", _flag_off, _show_flag),
    # the files already mirrored are NOT moved
    "GIO_HOTPATCH_DIR": _setting("storage", "path", "restart", "HOTPATCH_DIR",
                                 lambda raw: _hotpatch_dir_from(raw, STATE_PATH), check="dir"),
    "GIO_HOTPATCH_BUNDLE_DIR": _setting("storage", "path", "restart", "HOTPATCH_BUNDLE_DIR",
                                        lambda raw: _bundle_dir_from(raw, HOTPATCH_DIR)[0], check="dir"),
    "GIO_7Z": _setting("storage", "path", "live", "EXTRACTOR_PATH", _strip, check="file"),
    "GIO_FETCH_DISK_RESERVE": _setting("downloads", "mib", "live", "FETCH_DISK_RESERVE",
                                       lambda raw: _parse_mib(raw, 4096) << 20, _show_mib),
    "GIO_HOTPATCH_DISK_RESERVE": _setting("downloads", "mib", "live", "HOTPATCH_DISK_RESERVE",
                                          lambda raw: _parse_mib(raw, 2048) << 20, _show_mib),
    "GIO_HOTPATCH_ONDEMAND_MAX": _setting("downloads", "mib", "live", "HOTPATCH_ONDEMAND_MAX",
                                          lambda raw: _parse_mib(raw, 2048) << 20, _show_mib),
    # a hard off, AND-ed with the policy's hotpatchUpstream
    "GIO_HOTPATCH_UPSTREAM": _setting("downloads", "bool", "live", "HOTPATCH_UPSTREAM", _flag_on, _show_flag),
    "GIO_HOTPATCH_BUNDLES": _setting("downloads", "bool", "live", "HOTPATCH_BUNDLES", _flag_on, _show_flag),
    "GIO_TLS_PINNED_FALLBACK": _setting("downloads", "bool", "live", "TLS_PINNED_FALLBACK", _flag_on, _show_flag),
    # a change re-installs the process-wide opener
    "GIO_CA_FILE": _setting("downloads", "path", "live", "CA_FILE", _strip, check="pem"),
}
# Known keys POST /agent/config refuses (400) with a reason; any other unknown key is refused too.
# Every version's folder key is one of them: a stack folder changes only through the relocation.
_RELOCATE_ONLY = "a server's folder is changed with POST /server/relocate (Agent settings, Server folders)"
_SETTING_REFUSED = {
    **{dir_setting_key(_v): _RELOCATE_ONLY for _v in VERSIONS},
    "GIO_HOTPATCH_SOURCE": "the hotpatch card's Mirror source sets it (the server's policy)",
    "GIO_AGENT_TOKEN": "set when the agent is installed -- not editable here",
    "GIO_AGENT_LISTEN": "set when the agent is installed -- not editable here",
    "GIO_MUIP_KEY": "set when the agent is installed -- not editable here",
    "GIO_MYSQL_ROOT_PASSWORD": "set when the agent is installed -- not editable here",
    "GIO_FLASK_SECRET_KEY": "set when the agent is installed -- not editable here",
    "GIO_STATE_PATH": "set when the agent is installed -- not editable here",
    "GIO_PAYLOAD_DIR": "set when the agent is installed -- not editable here",
    "GIO_AGENT_REGION": "set when the agent is installed -- not editable here",
}
_DNS_LABEL_RE = re.compile(r"^(?!-)[A-Za-z0-9-]{1,63}(?<!-)$")
_config_lock = threading.RLock()  # the config file's one writer + the live apply that follows it


def runs_from_systemd_file():
    """True when systemd started this process with the config file as its EnvironmentFile (no --config,
    the unit's own child): then the FILE wins over the unit's Environment= lines and the manager's
    environment (systemd.exec: "Settings from these files override settings made with Environment=")."""
    return not CONFIG_FILE and CONFIG_PATH == SYSTEMD_CONFIG and restart_mode() == "systemd"


def env_overridden(key, boot_env=None, boot_file=None, systemd_file=None):
    """True when the environment this process started with sets key to something else than the config
    file did, so editing the file changes nothing at the next start. With --config (and a manual run)
    every exported value wins over the file (apply_config_file never overrides one). Under systemd's
    EnvironmentFile the file wins over Environment= / the manager's environment, so only a key the file
    DOES set that arrived with another value is overridden (another EnvironmentFile= of a drop-in, read
    later); a key the file does not set is not -- writing it there would win. Pure given its arguments
    (defaults: the boot snapshots, runs_from_systemd_file())."""
    boot_env = _BOOT_ENV if boot_env is None else boot_env
    boot_file = _BOOT_FILE if boot_file is None else boot_file
    systemd_file = runs_from_systemd_file() if systemd_file is None else systemd_file
    if key not in boot_env:
        return False
    if systemd_file:
        return key in boot_file and boot_file[key] != boot_env[key]
    return boot_file.get(key) != boot_env[key]


def env_beneath_file(key, boot_env=None, boot_file=None, systemd_file=None):
    """The value the next start takes for key when the config file does NOT set it: under systemd the
    unit's Environment= / manager value this process received for a key the file did not set; else None
    (a self-restart hands the new process only what the file does not own, respawn_env). Pure given its
    arguments."""
    boot_env = _BOOT_ENV if boot_env is None else boot_env
    boot_file = _BOOT_FILE if boot_file is None else boot_file
    systemd_file = runs_from_systemd_file() if systemd_file is None else systemd_file
    if systemd_file and key in boot_env and key not in boot_file:
        return boot_env[key]
    return None


def read_config_values(path=None):
    """{key: value} of the config file as the NEXT start reads it (first line wins with --config,
    the last for systemd); {} when there is none or it cannot be read."""
    path = CONFIG_PATH if path is None else path
    if not path:
        return {}
    try:
        return config_dict(read_config_pairs(path), first_wins=bool(CONFIG_FILE))
    except (OSError, ValueError):
        return {}


def config_writable(path=None):
    """(writable, why-not) for the file this agent would save its settings to."""
    path = CONFIG_PATH if path is None else path
    if not path:
        return False, "it was started without a configuration file (no --config%s)" % (
            "" if IS_WINDOWS else ", no " + SYSTEMD_CONFIG)
    folder = os.path.dirname(os.path.abspath(path)) or "."
    if os.path.islink(path):
        return False, "%s is a symbolic link" % path  # a rename would replace the link, not its target
    if os.path.lexists(path):
        if not os.path.isfile(path):
            return False, "%s is not a regular file" % path
        if not os.access(path, os.W_OK):
            return False, "%s is not writable by this process" % path
    if not os.path.isdir(folder) or not os.access(folder, os.W_OK):
        return False, "its folder %s is not writable by this process" % folder
    return True, None


def render_config_update(text, updates, explicit_empty=()):
    """The config text with `updates` ({KEY: value}, "" = drop the key) applied. Pure. Comments, blank
    lines, unknown keys and the line order stay; the newline style is the file's (CRLF when any line
    has one); a BOM is dropped. Per updated key the FIRST matching line is rewritten KEY=value (or
    dropped for "") and every later line of that key is dropped -- --config reads the first, systemd
    the last, so after a write only one line may exist. New keys are appended. A line counts as a key
    exactly when parse_config_text would read it. A key in `explicit_empty` is written "KEY=" for ""
    instead of dropped: a stack folder taken off the agent on Linux, where an ABSENT GIO_DIR_xx means
    the /home/<v>_live default."""
    text = text.lstrip("\ufeff")
    nl = "\r\n" if "\r\n" in text else "\n"
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()  # the newline that ended the last line, not an empty line of its own
    out, seen = [], set()
    for raw in lines:
        raw = raw[:-1] if raw.endswith("\r") else raw
        s = raw.strip()
        key = None
        if s and not s.startswith("#") and "=" in s:
            k = s.partition("=")[0].strip()
            if k in updates and re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", k):
                key = k
        if key is None:
            out.append(raw)
            continue
        if key not in seen and (updates[key] != "" or key in explicit_empty):
            out.append("%s=%s" % (key, updates[key]))
        seen.add(key)
    for k, v in updates.items():
        if k not in seen and (v != "" or k in explicit_empty):
            out.append("%s=%s" % (k, v))
    return nl.join(out) + (nl if out else "")


def update_config_file(path, updates, explicit_empty=()):
    """Apply `updates` to the config file at path (render_config_update) with an atomic write: a temp
    file created 0600 beside it, the original's mode (and owner, when running as root on POSIX)
    copied onto it, fsync, rename over the original, directory fsync. A missing file is created (0600).
    Bytes that are not UTF-8 round-trip untouched. Returns the new text; OSError is the caller's."""
    try:
        text = read_text(path)
    except FileNotFoundError:
        text = ""
    new = render_config_update(text, updates, explicit_empty)
    folder = os.path.dirname(os.path.abspath(path)) or "."
    tmp = os.path.join(folder, "." + os.path.basename(path) + ".relic-tmp")
    _remove_quiet(tmp)  # a leftover of a crashed write (the caller holds _config_lock)
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0), 0o600)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(new.encode("utf-8", "surrogateescape"))
            f.flush()
            os.fsync(f.fileno())
        st = _stat_or_none(path)
        if st is not None and os.name != "nt":
            os.chmod(tmp, st.st_mode & 0o7777)
            if hasattr(os, "geteuid") and os.geteuid() == 0:
                os.chown(tmp, st.st_uid, st.st_gid)
        replace_file(tmp, path)
    except BaseException:
        _remove_quiet(tmp)
        raise
    _fsync_dir(folder)
    return new


def _config_not_writable(why):
    return AgentError(409, "This agent cannot save its configuration: %s -- edit %s by hand and restart it."
                      % (why, CONFIG_PATH or "its configuration"))


def save_config_values(updates, explicit_empty=()):
    """THE writer of this agent's config file (POST /agent/config, the stack relocation): {KEY: value},
    "" removes the key (or writes "KEY=" for a key in explicit_empty). AgentError 409 when this agent
    cannot save it, 500 when the write fails. Returns the new text."""
    writable, why = config_writable()
    if not writable:
        raise _config_not_writable(why)
    with _config_lock:
        try:
            return update_config_file(CONFIG_PATH, updates, explicit_empty)
        except OSError as e:
            raise AgentError(500, "Saving %s failed: %s" % (CONFIG_PATH, e))


def _is_abs_path(v):
    # Windows: a drive or UNC path (Python < 3.13 calls "\x" absolute: it is relative to the drive)
    return os.path.isabs(v) and (os.name != "nt" or bool(os.path.splitdrive(v)[0]))


def _ca_file_problem(path):
    """None when path is a PEM bundle OpenSSL loads, else why not."""
    if ssl is None:
        return "this Python has no ssl module"
    try:
        ssl.create_default_context().load_verify_locations(cafile=path)
    except (OSError, ValueError) as e:
        return "not a loadable PEM bundle (%s)" % e
    return None


def normalise_setting(key, value):
    """A POSTed value -> the string to store ("" = remove the key), or AgentError 400 "KEY: why".
    Values travel as strings (a JSON bool / integer is accepted and spelled as one): bools become
    1/0, numbers plain decimals, URLs lose a trailing slash, a DNS name its trailing dot."""
    spec = AGENT_SETTINGS[key]

    def bad(why):
        return AgentError(400, "%s: %s" % (key, why))

    if isinstance(value, bool):
        value = "1" if value else "0"
    elif isinstance(value, int):
        value = str(value)
    elif not isinstance(value, str):
        raise bad("must be a string")
    v = value.strip()
    why = plain_line_problem(v)
    if why:
        raise bad(why)
    if v[:1] in ("'", '"'):
        # the config readers strip one pair of surrounding quotes, and systemd reads an opening one up
        # to its closing partner -- a value is stored unquoted
        raise bad("must not start with a quote")
    if "\\" in v and not CONFIG_FILE and not IS_WINDOWS:
        raise bad("a backslash is an escape character in the systemd EnvironmentFile -- not supported here")
    if v == "":
        return ""
    t = spec["type"]
    if t == "bool":
        if v.lower() in _TRUTHY:
            return "1"
        if v.lower() in _FALSY:
            return "0"
        raise bad("must be on or off (1/0, true/false, yes/no, on/off)")
    if t == "enum":
        if v.lower() in spec["choices"]:
            return v.lower()
        raise bad("must be one of %s" % ", ".join(spec["choices"]))
    if t in ("mib", "seconds"):
        lo, hi = (0, SETTING_MIB_MAX) if t == "mib" else SETTING_SECONDS
        if not re.match(r"^[0-9]{1,12}$", v) or not lo <= int(v) <= hi:
            raise bad("must be a whole number from %d to %d%s" % (lo, hi, " (MiB)" if t == "mib" else " (seconds)"))
        return str(int(v))
    if t == "ip":
        try:
            return str(ipaddress.IPv4Address(v))
        except ValueError:
            raise bad("must be an IPv4 address like 192.0.2.10 (or empty)")
    if t == "host":
        v = v.rstrip(".")
        try:
            ipaddress.ip_address(v)
            is_ip = True
        except ValueError:
            is_ip = False
        if is_ip:
            raise bad("is an IP address -- a fixed address belongs in GIO_ADVERTISED_IP")
        if not (0 < len(v) <= 253 and all(_DNS_LABEL_RE.match(p) for p in v.split("."))):
            raise bad("must be a DNS name like game.example.com (or empty)")
        return v
    if t in ("url", "path") and len(v) > SETTING_PATH_MAX:
        raise bad("must be at most %d characters" % SETTING_PATH_MAX)
    if t == "url":
        v = v.rstrip("/")
        try:
            p = urllib.parse.urlsplit(v)
            ok_url = (p.scheme.lower() in ("http", "https") and bool(p.hostname) and not p.query
                      and not p.fragment and " " not in v)
            p.port  # noqa: B018 -- raises ValueError on a malformed port
        except ValueError:
            ok_url = False
        if not ok_url:
            raise bad("must be an http:// or https:// URL without a query (or empty)")
        return v
    if t == "path":
        if not _is_abs_path(v):
            raise bad("must be an absolute path%s (or empty)" % (" with a drive letter" if os.name == "nt" else ""))
        if spec["check"] in ("file", "pem") and not os.path.isfile(v):
            raise bad("%s is not an existing file" % v)
        if spec["check"] == "dir" and os.path.isfile(v):
            raise bad("%s is a file, not a folder" % v)
        if spec["check"] == "pem":
            why = _ca_file_problem(v)
            if why:
                raise bad("%s is %s" % (v, why))
        return v
    if len(v) > SETTING_TEXT_MAX:
        raise bad("must be at most %d characters" % SETTING_TEXT_MAX)
    return v


def _setting_value(key):
    spec = AGENT_SETTINGS[key]
    return spec["show"](globals()[spec["var"]])


def _setting_default(key):
    spec = AGENT_SETTINGS[key]
    return spec["show"](spec["parse"](None))


def _next_raw(key, stored, updates=None):
    """The raw value the NEXT start reads for key (None = absent): a pending update, else an
    environment override, else the file -- and where the file will not set the key, what the environment
    supplies beneath it (env_beneath_file: a systemd Environment= line)."""
    if updates and key in updates:
        raw = updates[key] or None
    elif env_overridden(key):
        return _BOOT_ENV[key]
    else:
        raw = stored.get(key)
    return env_beneath_file(key) if raw is None else raw


def _next_hotpatch_dirs(stored, updates=None):
    """(mirror, bundle folder, refusals) of the NEXT start: _hotpatch_dirs_from over the next raw values and
    the folders as they are now."""
    return _hotpatch_dirs_from(_next_raw("GIO_HOTPATCH_DIR", stored, updates),
                               _next_raw("GIO_HOTPATCH_BUNDLE_DIR", stored, updates), STATE_PATH,
                               _agent_owned_folders(CONFIG_PATH, STATE_PATH, PAYLOAD_DIR), _stack_dir_pairs())


def _stack_dir_pairs():
    return [(v, meta["dir"]) for v, meta in list(VERSIONS.items())]


def _same_path(a, b):
    def norm(p):
        return os.path.normcase(os.path.normpath(os.path.abspath(p)))
    return norm(a) == norm(b)


def restart_pending(stored, updates=None):
    """The restart-only keys whose next-start value differs from what this process runs with."""
    # the two folders as the next start derives them: its refusals, and the bundle folder's default (and its
    # inside-the-mirror refusal) following the NEXT mirror folder
    next_mirror, next_bundle, _refused = _next_hotpatch_dirs(stored, updates)
    out = []
    for key in AGENT_SETTING_KEYS:
        spec = AGENT_SETTINGS[key]
        if spec["apply"] != "restart":
            continue
        if key == "GIO_HOTPATCH_DIR":
            nxt = next_mirror
        elif key == "GIO_HOTPATCH_BUNDLE_DIR":
            nxt = next_bundle
        else:
            nxt = spec["parse"](_next_raw(key, stored, updates))
        cur = globals()[spec["var"]]
        if not (_same_path(nxt, cur) if spec["type"] == "path" else nxt == cur):
            out.append(key)
    return out


def format_listen(host, port):
    return "[%s]:%d" % (host, port) if ":" in host else "%s:%d" % (host, port)


def restart_mode(env=None, is_windows=None, argv=None, executable=None, ppid=None):
    """How POST /agent/restart would bring this process back: "systemd" (a system service -- the unit's
    Restart=always restarts it after an exit, with the EnvironmentFile read again), "self" (start a new
    copy of this script, then exit) or None (neither is possible). Pure given its arguments. systemd is
    believed only for a child of PID 1: INVOCATION_ID can leak into a shell a terminal service started,
    and exiting there would leave no agent at all (a "self" restart under systemd still ends well: the
    unit's cgroup is restarted as a whole)."""
    env = _BOOT_ENV if env is None else env
    is_windows = IS_WINDOWS if is_windows is None else is_windows
    argv = sys.argv if argv is None else argv
    executable = sys.executable if executable is None else executable
    if not is_windows and ("INVOCATION_ID" in env or "JOURNAL_STREAM" in env):
        if (os.getppid() if ppid is None else ppid) == 1:
            return "systemd"
    if executable and argv and argv[0] and os.path.isfile(argv[0]):
        return "self"
    return None


def respawn_env(boot_env=None, boot_file=None, file_now=None):
    """The environment a self-restart hands the new process: the BOOT environment (os.environ holds the old
    config file's values, which would win over the rewritten file) minus what the config file owned -- a
    variable that arrived with exactly the value the file held at boot (exported from it, `set -a; . config`)
    takes the file's CURRENT value, or goes when the file no longer sets it. A value the file did not hold is
    an explicit override and stays (POST /agent/config refused to edit it). Pure given its arguments
    (defaults: the boot snapshots and read_config_values())."""
    boot_env = _BOOT_ENV if boot_env is None else boot_env
    boot_file = _BOOT_FILE if boot_file is None else boot_file
    file_now = read_config_values() if file_now is None else file_now
    out = dict(boot_env)
    for k, v in boot_env.items():
        if k in boot_file and boot_file[k] == v:
            if k in file_now:
                out[k] = file_now[k]
            else:
                del out[k]
    return out


def respawn_command(argv=None, executable=None, env=None, is_windows=None, cwd=None):
    """(command, Popen kwargs) of a self-restart: this interpreter + this script + the same arguments,
    respawn_env() (the boot environment with the config file authoritative for what it owned), the same
    working directory, no inherited handles, detached from this process."""
    argv = list(sys.argv if argv is None else argv)
    executable = sys.executable if executable is None else executable
    env = respawn_env() if env is None else env
    is_windows = IS_WINDOWS if is_windows is None else is_windows
    cmd = [executable, os.path.abspath(argv[0])] + argv[1:]
    kw = {"env": dict(env), "cwd": os.getcwd() if cwd is None else cwd, "close_fds": True,
          "stdin": subprocess.DEVNULL, "stdout": subprocess.DEVNULL, "stderr": subprocess.DEVNULL}
    if is_windows:
        kw["creationflags"] = (getattr(subprocess, "DETACHED_PROCESS", 0x8)
                               | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0x200))
    else:
        kw["start_new_session"] = True
    return cmd, kw


def _addr_in_use(e):
    return getattr(e, "errno", None) in (errno.EADDRINUSE, 10048) or getattr(e, "winerror", None) == 10048


def bind_http_server(host, port, factory=None, wait=10.0, sleep=None):
    """The listening server, retrying "address in use" for up to `wait` seconds: after a restart the
    previous process may still be closing its socket."""
    factory = factory or (lambda addr: ThreadingHTTPServer(addr, Handler))
    sleep = sleep or time.sleep
    deadline = time.monotonic() + wait
    while True:
        try:
            return factory((host, port))
        except OSError as e:
            if not _addr_in_use(e) or time.monotonic() >= deadline:
                raise
            sleep(0.5)


def write_pid_file(config_file=None, is_windows=None, pid=None):
    """Windows: agent.pid beside --config (the launcher's LocalAgent reads it) -- written by the agent
    too, so a self-restarted agent keeps it truthful. Never fatal. Returns the path written or None."""
    config_file = CONFIG_FILE if config_file is None else config_file
    is_windows = IS_WINDOWS if is_windows is None else is_windows
    if not (is_windows and config_file):
        return None
    path = os.path.join(os.path.dirname(os.path.abspath(config_file)), "agent.pid")
    try:
        write_text(path, str(os.getpid() if pid is None else pid))
        return path
    except OSError as e:
        log_line("gio-agent: WARNING: could not write %s (%s)" % (path, e))
        return None


def agent_config_info():
    """GET /agent/config."""
    stored = read_config_values()
    writable, why = config_writable()
    settings = []
    for key in AGENT_SETTING_KEYS:
        spec = AGENT_SETTINGS[key]
        item = {"key": key, "group": spec["group"], "type": spec["type"]}
        if spec["choices"]:
            item["choices"] = list(spec["choices"])
        item.update({"value": _setting_value(key), "stored": stored.get(key), "default": _setting_default(key),
                     "apply": spec["apply"], "env": env_overridden(key)})
        settings.append(item)
    running = running_projects()[0] or []
    versions = {}
    for v in list(VERSIONS):
        meta = VERSIONS[v]  # one read: a relocation swaps the whole dict
        versions[v] = {"dir": meta["dir"], "configured": bool(meta["dir"]), "present": is_present(v),
                       "up": bool(meta["dir"]) and meta["project"] in running, "project": meta["project"]}
    with _tls_lock:
        hosts = sorted(_TLS_FALLBACK_HOSTS)
    strict = bool(_TLS_CONTEXT is not None
                  and int(_TLS_CONTEXT.verify_flags) & int(getattr(ssl, "VERIFY_X509_STRICT", 0)))
    return {
        "agent": AGENT_VERSION, "platform": "windows" if IS_WINDOWS else "linux", "started": round(_STARTED, 3),
        "file": CONFIG_PATH, "writable": writable, "writableReason": why, "restart": restart_mode(),
        "listen": format_listen(LISTEN_HOST, LISTEN_PORT),
        "restartPending": restart_pending(stored),
        # caFile: the extra roots the installed opener really carries ("" when none loaded); caFileError: why
        # GIO_CA_FILE did not load (the opener then runs without it), else null
        "tls": {"strict": strict, "caFile": _TLS_CA_LOADED, "caFileError": _TLS_CA_ERROR,
                "pinnedFallback": TLS_PINNED_FALLBACK, "fallbackHosts": hosts},
        "settings": settings,
        "versions": versions,
    }


def set_agent_config(body):
    """POST /agent/config {"set": {KEY: value}}. Everything is validated before anything is written:
    400 naming the key (unknown, not editable here, an invalid value, both advertised keys set, the
    bundle folder inside the mirror, a mirror / bundle folder that is a drive root, is or contains one of
    the agent's own folders or overlaps a server folder), 409 for an environment-overridden key, a file
    this agent cannot save or a restart under way. Then the file is written, the live keys are applied, and the GET body
    comes back with `applied` (live keys set) and `restartRequired` (restart keys set whose next-start
    value differs from the running one)."""
    sets = body.get("set")
    if not isinstance(sets, dict) or not sets:
        raise AgentError(400, "set must be a non-empty object of setting: value")
    updates = {}
    for key, value in sets.items():
        if key in AGENT_SETTINGS:
            updates[key] = normalise_setting(key, value)
        elif key in _SETTING_REFUSED:
            raise AgentError(400, "%s: %s" % (key, _SETTING_REFUSED[key]))
        else:
            raise AgentError(400, "%s: unknown setting" % key)
    stored = read_config_values()
    if "GIO_ADVERTISED_IP" in updates or "GIO_ADVERTISED_HOST" in updates:
        ip = _strip(_next_raw("GIO_ADVERTISED_IP", stored, updates))
        host = _strip(_next_raw("GIO_ADVERTISED_HOST", stored, updates)).rstrip(".")
        if ip and host:
            key = "GIO_ADVERTISED_HOST" if "GIO_ADVERTISED_HOST" in updates else "GIO_ADVERTISED_IP"
            raise AgentError(400, "%s: GIO_ADVERTISED_IP and GIO_ADVERTISED_HOST cannot both be set (the host would "
                                  "win and the IP be ignored) -- clear one of them" % key)
    if "GIO_HOTPATCH_DIR" in updates or "GIO_HOTPATCH_BUNDLE_DIR" in updates:
        mirror = _hotpatch_dir_from(_next_raw("GIO_HOTPATCH_DIR", stored, updates), STATE_PATH)
        bundle = _strip(_next_raw("GIO_HOTPATCH_BUNDLE_DIR", stored, updates))
        if bundle and _bundle_dir_inside_mirror(bundle, mirror):
            key = "GIO_HOTPATCH_BUNDLE_DIR" if "GIO_HOTPATCH_BUNDLE_DIR" in updates else "GIO_HOTPATCH_DIR"
            raise AgentError(400, "%s: the bundle folder %s would lie inside the hotpatch mirror %s, which serves "
                                  "everything under it" % (key, bundle, mirror))
        # the mirror is served to anyone without a token and the agent writes + empties the bundle folder: a
        # folder of their own only (the next start would ignore anything else with a WARNING)
        owned, stacks = _agent_owned_folders(CONFIG_PATH, STATE_PATH, PAYLOAD_DIR), _stack_dir_pairs()
        for key, folder, what in (("GIO_HOTPATCH_DIR", mirror, "the hotpatch mirror is served to anyone without a "
                                                               "token"),
                                  ("GIO_HOTPATCH_BUNDLE_DIR", bundle, "the agent writes and empties the bundle "
                                                                      "folder")):
            if updates.get(key):
                problem = _served_folder_problem(folder, owned, stacks)
                if problem:
                    raise AgentError(400, "%s: %s -- %s, so it must be a folder of its own." % (key, problem, what))
    for key in updates:
        if env_overridden(key):
            raise AgentError(409, "%s is set by this agent's environment (an exported variable, or another "
                                  "EnvironmentFile= of a systemd drop-in), which wins over the configuration file "
                                  "-- change it there." % key)
    writable, why = config_writable()
    if not writable:
        raise _config_not_writable(why)
    with _config_lock:
        if _restarting:
            raise _restarting_error()
        save_config_values(updates)
        applied = []
        for key in AGENT_SETTING_KEYS:
            spec = AGENT_SETTINGS[key]
            if key in updates and spec["apply"] == "live":
                globals()[spec["var"]] = spec["parse"](updates[key] or None)  # "" = removed = the default
                applied.append(key)
        if "GIO_CA_FILE" in applied:
            install_http_opener()
        info = agent_config_info()
    _invalidate_public_status()
    log_line("gio-agent: settings saved to %s: %s" % (CONFIG_PATH, ", ".join(
        "%s=%s" % (k, updates[k] or "(default)") for k in AGENT_SETTING_KEYS if k in updates)))
    info["applied"] = applied
    info["restartRequired"] = [k for k in AGENT_SETTING_KEYS if k in updates
                               and AGENT_SETTINGS[k]["apply"] == "restart" and k in info["restartPending"]]
    return info


# The server main() serves (POST /agent/restart shuts it down); None in the selftest and the CLI modes.
_HTTPD = None


def request_restart():
    """POST /agent/restart's refusals, then the flag that stops every new job: 409 when this agent
    cannot restart itself, is not serving, or any job runs (a yielding one included). Returns how."""
    global _restarting
    how = restart_mode()
    if how is None:
        raise AgentError(409, "This agent cannot restart itself (it does not run under systemd and its script "
                              "path is not a file it can start again) -- restart it by hand.")
    if _HTTPD is None:
        raise AgentError(409, "This agent process is not serving -- nothing to restart.")
    with _jobs_lock:
        if _restarting:
            raise _restarting_error()
        busy = _current_job_locked()
        if busy is not None:
            raise _busy_error(busy)
        _restarting = True
    return how


def _launch_restart(how):
    """After the 202 went out. Module level so the selftest can swap it (it never restarts anything)."""
    threading.Thread(target=_restart_worker, args=(how,), name="gio-agent-restart", daemon=True).start()


def _restart_worker(how):
    global _HTTPD, _restarting
    time.sleep(0.5)  # the 202 is on its way
    log_line("gio-agent: restarting on request (%s) ..." % how)
    try:
        _HTTPD.shutdown()
        _HTTPD.server_close()  # the port is free for the next process
    except Exception as e:  # noqa: BLE001
        log_line("gio-agent: restart: closing the server: %s" % e)
    # A settings write in flight finishes first; a short critical section a watchdog runs outside any
    # job (the advertise swap) gets a moment too. Both files are written tmp + rename anyway.
    _config_lock.acquire()
    got_op = _op_lock.acquire(timeout=30)
    if how == "systemd":
        os._exit(0)  # Restart=always: back in RestartSec with the EnvironmentFile read again
    try:
        cmd, kw = respawn_command()  # inside: a vanished working directory raises here too
        subprocess.Popen(cmd, **kw)
    except Exception as e:  # noqa: BLE001 -- whatever failed, this process must keep serving
        # Never leave the box without an agent: serve again from this thread (main() is parked).
        log_line("gio-agent: ERROR: the restart could not start a new process (%s) -- this one keeps serving." % e)
        if got_op:
            _op_lock.release()
        _config_lock.release()
        try:
            _HTTPD = bind_http_server(LISTEN_HOST, LISTEN_PORT)
        except Exception as e2:  # noqa: BLE001
            # Serving again is impossible: end the process rather than linger with no listener (systemd's
            # Restart=always, or the launcher's Start, brings a fresh one up).
            log_line("gio-agent: ERROR: could not listen again on %s (%s) -- exiting."
                     % (format_listen(LISTEN_HOST, LISTEN_PORT), e2))
            os._exit(1)
        _restarting = False
        _HTTPD.serve_forever()
        return
    os._exit(0)


# -- stack relocation: POST /server/relocate, job `relocate` --
# GIO_DIR_xx changes only here, never through /agent/config: the folder's basename IS the docker compose
# project name, and docker keeps every container's absolute bind paths, so a config-only change would
# orphan the old project -- still holding the ports and the 172.10.3.0/24 subnet, invisible to every
# up-check and watchdog, which look for the new name. The job, under _op_lock, brings the version down
# under its CURRENT project name with the full grace (the game server saves the players' data), then
#   move    -- takes the tree along: one rename on the same volume; across volumes a copy into the
#              sibling .relic-move-<name> (cp -a on Linux: owner, mode, links, xattrs -- MariaDB's and
#              redis' data need them; a Python walk on Windows), verified by counts + bytes and renamed
#              into place, the old tree deleted only once the config file names the new folder, or
#   repoint -- touches no file: the version is pointed at a folder that already holds a stack (moved by
#              hand, a second copy), at one still empty or absent (a later download fills it), or at
#              nothing ("" = the version leaves this agent),
# persists GIO_DIR_xx (the config file first: a restart must never revert it), swaps VERSIONS[v] in one
# assignment and starts the stack again when it was running. Nothing inside a stack holds its own
# absolute path (the renders substitute .env values, every bind mount is relative), so a moved stack
# needs no re-render.

RELOCATE_MODES = ("move", "repoint")
RELOCATE_RENAME_WAIT = 30              # seconds a rename is retried while Windows still holds the tree
RELOCATE_COPY_TIMEOUT = 6 * 3600       # a cross-volume `cp -a` still running after this is killed
RELOCATE_PROGRESS_EVERY = 15           # seconds between two progress lines of a `cp -a` copy
RELOCATE_PROGRESS_BYTES = 500 << 20    # bytes between two progress lines of the Windows copy
_WIN_DRIVE_PATH_RE = re.compile(r"^[A-Za-z]:[\\/]")
# A repoint at a folder that is NOT the same server (its .relic-provisioned does not say what the state's
# provisionedAt says) keeps only the admin's decisions about the version -- re-asserted onto the new stack
# by the next start (the pathfinding profile, the hotpatch files + URL columns) or not bound to a stack at
# all (the mirror's voice languages, where the mirror's files came from, the toggle times). Everything else
# every version_state_set() caller writes describes the old folder's CONTENT and is dropped:
#   runningOk, provisionedAt, progress, defaultAccount, txtFixes (its database and payload files),
#   advertisedIp, advertisedIpSql, advertisedIpSqlOwed (its XMLs and URL columns), towerRestartPending (its
#   gameserver), templates (its relic_tpl_* databases), secrets (changedAt, muipChangedAt, muipSource: its
#   .env / muipserver.xml), secretsPending, passwordVerify (re-read from the new stack's sdk config),
#   passwordPending, defaultPassword (its sdk accounts), fetchedAt, fetchedFrom (what was downloaded there),
#   and inside `hotpatch` what was APPLIED to it: url, res, data, silence -- `pending` is set again for an
#   enabled hotpatch (the new stack advertises nothing until the next start re-asserts it).
# The provisioning record is then filled in from the new folder's marker (provision_record /
# needs_provision), as for any lost record -- and an INSTALLED folder without a marker gets autoProvision
# False (dropped like the rest by the next repoint, cleared by an explicit provision): nothing could re-seed
# its record, and the next Start must not import the save over a database that may hold players. The
# selftest checks every keyword a version_state_set() call in this file writes against these lists.
_RELOCATE_DROP = ("runningOk", "provisionedAt", "progress", "defaultAccount", "txtFixes", "advertisedIp",
                  "advertisedIpSql", "advertisedIpSqlOwed", "towerRestartPending", "templates", "secrets",
                  "secretsPending", "passwordVerify", "passwordPending", "defaultPassword", "fetchedAt",
                  "fetchedFrom", "autoProvision")
_RELOCATE_KEEP = ("pathfinding", "hotpatch")
_RELOCATE_HOTPATCH_KEEP = ("enabled", "voice", "source", "appliedAt", "disabledAt")


class RelocateStopped(Exception):
    """POST /server/relocate {"cancel": true} arrived while the tree was being copied."""


# (_real_norm / _path_within live at the top of the file: the import-time hotpatch folder check uses them.)


def _existing_ancestor(path):
    """path when it exists, else its nearest existing parent (a missing drive root comes back as it is)."""
    p = os.path.abspath(path)
    while not os.path.exists(p):
        parent = os.path.dirname(p)
        if parent == p:
            break
        p = parent
    return p


def _same_volume(a, b):
    """Do a and b (its nearest existing ancestor) sit on one volume (st_dev)? None when unreadable. A
    rename may still refuse (EXDEV: a bind mount, another btrfs subvolume) -- the move copies then.
    Module level: the selftest forces the cross-volume path through it."""
    try:
        return os.stat(a).st_dev == os.stat(_existing_ancestor(b)).st_dev
    except OSError:
        return None


def _is_mount(path):
    """os.path.ismount -- module level: the selftest swaps it (a temp folder is never a mount point)."""
    try:
        return os.path.ismount(path)
    except (OSError, ValueError):
        return False


def _sync_filesystems():
    """POSIX: sync(2) -- blocks until every filesystem has written its dirty data (a copied tree included)
    and the renames. Windows has none (_copy_tree_py fsyncs each file instead). Module level: the selftest
    swaps it."""
    if hasattr(os, "sync"):
        os.sync()


def _cross_device(e):
    # EXDEV (POSIX, and what Python maps Windows' ERROR_NOT_SAME_DEVICE = 17 to)
    return getattr(e, "errno", None) == errno.EXDEV or getattr(e, "winerror", None) == 17


def _tree_counts(path):
    """(files, folders, bytes) of a tree, symbolic links counted as themselves and never followed, sizes
    from lstat -- what a copy is verified with. os.scandir: on Windows the listing already carries the
    sizes (no open per file on a 26k-file stack). OSError is the caller's."""
    files = folders = nbytes = 0
    todo = [path]
    while todo:
        with os.scandir(todo.pop()) as it:
            for e in it:
                if e.is_dir(follow_symlinks=False):
                    folders += 1
                    todo.append(e.path)
                else:
                    files += 1
                    nbytes += e.stat(follow_symlinks=False).st_size
    return files, folders, nbytes


def relocate_target_kind(d):
    """What is at a relocation target: "absent" | "empty" (a folder) | "stack" (a compose file or its
    template) | "other" (a non-empty folder without one, a file, an unreadable folder)."""
    if not os.path.lexists(d):
        return "absent"
    try:
        if not os.path.isdir(d):
            return "other"
        if not os.listdir(d):
            return "empty"
    except OSError:
        return "other"
    if os.path.isfile(os.path.join(d, "docker-compose.yml.tmpl")) or os.path.isfile(os.path.join(d, "docker-compose.yml")):
        return "stack"
    return "other"


def _agent_folders():
    """The agent's own folders, which a stack folder must neither lie in nor contain: its configuration,
    state, payload and script folders, and the hotpatch mirror + bundle folder -- both the ones this process
    uses and the ones the next start will use (a changed GIO_HOTPATCH_DIR waiting for the restart). The
    settings refuse the same nesting from the other side (_served_folder_problem)."""
    out = [(label, folder) for label, folder in _agent_owned_folders(CONFIG_PATH, STATE_PATH, PAYLOAD_DIR)]
    out += [("the hotpatch mirror", HOTPATCH_DIR), ("the hotpatch bundle folder", HOTPATCH_BUNDLE_DIR)]
    try:
        next_mirror, next_bundle, _refused = _next_hotpatch_dirs(read_config_values())
    except Exception:  # noqa: BLE001 -- the running folders above are checked either way
        next_mirror = next_bundle = None
    if next_mirror and not _same_path(next_mirror, HOTPATCH_DIR):
        out.append(("the hotpatch mirror (after the agent's restart)", next_mirror))
    if next_bundle and not _same_path(next_bundle, HOTPATCH_BUNDLE_DIR):
        out.append(("the hotpatch bundle folder (after the agent's restart)", next_bundle))
    return tuple(out)


# GetDriveTypeW answers a stack folder must not get (Docker Desktop shares local fixed drives only, and
# a RAM disk loses the database at the next reboot); DRIVE_UNKNOWN (0) -- or no answer -- is let through.
_WIN_DRIVE_REFUSED = {
    1: "is not a drive on this machine",
    4: "is a network drive (Docker Desktop cannot bind-mount it)",
    5: "is a CD/DVD drive",
    6: "is a RAM disk (its files are gone after a reboot)",
}


def _win_drive_type(letter):
    """Windows' GetDriveTypeW for "<letter>:\\" (0 = unknown / not Windows / ctypes unavailable -- never
    fatal). Module level: the selftest swaps it."""
    if os.name != "nt":
        return 0
    try:
        import ctypes
        return int(ctypes.windll.kernel32.GetDriveTypeW(ctypes.c_wchar_p(letter.upper() + ":\\")))
    except Exception:  # noqa: BLE001
        return 0


def relocate_target(raw, mode, version):
    """The requested folder -> a normalised absolute path, "" (repoint only: the version leaves this
    agent), or AgentError 400. Windows: a drive-letter path only -- Docker Desktop cannot bind-mount a
    network share, and a drive-relative path is a typo. The value lands in the config file as it is: no
    quotes, no control characters (and, in the systemd EnvironmentFile, no backslash)."""
    if not isinstance(raw, str):
        raise AgentError(400, "dir must be a string: an absolute folder, or \"\" with mode repoint.")
    v = raw.strip()
    if not v:
        if mode != "repoint":
            raise AgentError(400, "A move needs the folder to move the server to (an empty dir goes only with "
                                  "repoint: it takes the version off this agent).")
        return ""
    if plain_line_problem(v) or '"' in v or "'" in v:
        # the settings' own rule (a line separator would split the config line, a lone surrogate break the file)
        raise AgentError(400, "The folder must be one plain line without quotes.")
    if len(v) > SETTING_PATH_MAX:
        raise AgentError(400, "The folder path must be at most %d characters." % SETTING_PATH_MAX)
    if "\\" in v and not CONFIG_FILE and not IS_WINDOWS:
        raise AgentError(400, "A backslash is an escape character in the systemd EnvironmentFile -- choose a "
                              "folder without one.")
    if os.name == "nt":
        if not _WIN_DRIVE_PATH_RE.match(v):
            raise AgentError(400, "The folder must be a full path on a local drive, like C:\\relic_servers\\%s_live "
                                  "(Docker Desktop cannot bind-mount a network path)." % version)
        # a letter mapped to a network share passes the spelling test above: ask Windows what it is
        why = _WIN_DRIVE_REFUSED.get(_win_drive_type(v[0]))
        if why:
            raise AgentError(400, "%s %s -- choose a folder on a local drive, like C:\\relic_servers\\%s_live."
                             % (v[:2].upper(), why, version))
    elif not os.path.isabs(v):
        raise AgentError(400, "The folder must be an absolute path, like /home/%s_live." % version)
    new = os.path.normpath(os.path.abspath(v))
    if os.path.dirname(new) == new:
        raise AgentError(400, "The folder must not be the root of a drive -- pick a folder inside it.")
    if _project_name(new) == "default":
        # compose's name for the folder: empty after normalisation (or literally "default") is no name
        raise AgentError(400, "The folder name %s gives docker no usable project name -- use letters or digits "
                              "(like %s_live)." % (os.path.basename(new), version))
    return new


def _relocate_refusal(version, cur, new, mode, rep, ls_err, in_job, projects_all=None):
    """Raise the first thing that refuses this relocation: 400 for the request itself, 409 for the state
    of the box, 500 when docker cannot say whether the stack runs. rep holds what relocate_check measured;
    projects_all is compose_projects_all()'s list (None = docker did not answer: that check is skipped)."""
    if new:
        if cur and _real_norm(new) == _real_norm(cur):
            raise AgentError(400, "%s already is the folder of version %s." % (new, version))
        proj = _project_name(new)
        for v, meta in list(VERSIONS.items()):
            if v == version or not meta["dir"]:
                continue
            if proj == meta["project"]:
                raise AgentError(400, "The folder name %s gives the docker project the same name as version %s's (%s) "
                                      "-- the two stacks would take each other over. Pick another folder name."
                                 % (os.path.basename(new), v, proj))
            if _path_within(new, meta["dir"]) or _path_within(meta["dir"], new):
                raise AgentError(400, "%s and version %s's folder %s would lie inside one another." % (new, v, meta["dir"]))
        # Another compose project on this box (running or stopped) that already carries the name: docker would
        # treat the two as one -- the up-checks would see it as this server, and the next down --remove-orphans
        # would remove its containers. The version's own name stays allowed, and so does a project whose
        # compose files live in the new folder (the very stack being pointed at, started by hand).
        own = VERSIONS[version]["project"]
        for name, config_files in (projects_all or ()):
            if name != proj or name == own:
                continue
            files = [p.strip() for p in str(config_files or "").split(",") if p.strip()]
            if not any(_path_within(p, new) for p in files):
                raise AgentError(409, "The folder name %s gives the docker project the name of another compose project "
                                      "on this box (%s, compose files %s) -- docker would treat the two as one and a "
                                      "stop would remove its containers. Pick another folder name."
                                 % (os.path.basename(new), name, ", ".join(files) or "unknown"))
        for label, folder in _agent_folders():
            if _path_within(new, folder) or _path_within(folder, new):
                raise AgentError(400, "%s would lie inside %s %s (or contain it) -- pick a folder of its own."
                                 % (new, label, folder))
        if mode == "move" and cur and (_path_within(new, cur) or _path_within(cur, new)):
            raise AgentError(400, "The new folder must not lie inside the current one %s, nor contain it." % cur)
    elif not cur:
        raise AgentError(400, "Version %s is not configured on this agent already." % version)
    key = dir_setting_key(version)
    if env_overridden(key):
        raise AgentError(409, "%s is set by this agent's environment (an exported variable, or another "
                              "EnvironmentFile= of a systemd drop-in), which wins over the configuration file -- "
                              "change it there." % key)
    writable, why = config_writable()
    if not writable:
        raise _config_not_writable(why)
    if new:
        base = _existing_ancestor(os.path.dirname(new))  # a missing drive, a file where a parent folder goes
        if not os.path.isdir(base):
            raise AgentError(409, "Nothing can be created at %s: %s is not a folder on this machine." % (new, base))
    if ls_err is not None:
        raise AgentError(500, "Cannot read the docker state (%s) -- the stack may be running; retry once docker "
                              "answers." % ls_err)
    if new and os.path.lexists(new) and not os.path.isdir(new):
        raise AgentError(409, "%s is a file, not a folder." % new)
    target = rep["target"]
    if mode == "move":
        if not cur:
            raise AgentError(409, "Version %s has no folder on this agent yet -- nothing to move; point it at a "
                                  "folder with repoint." % version)
        # A move takes the WHOLE current tree along -- and across drives deletes it after the copy: whatever else
        # lives inside it (the other server, the mirror, the agent's own folders) would go with it.
        for v, meta in list(VERSIONS.items()):
            if v != version and meta["dir"] and _path_within(meta["dir"], cur):
                raise AgentError(409, "%s holds version %s's folder %s -- a move would take that server along (and "
                                      "delete it after a copy to another drive). Move version %s out of it first."
                                 % (cur, v, meta["dir"], v))
        for label, folder in _agent_folders():
            if _path_within(folder, cur):
                raise AgentError(409, "%s contains %s %s -- a move would take it along. Move it out of the server "
                                      "folder first." % (cur, label, folder))
        if not is_present(version):
            raise AgentError(409, "%s holds no server (no docker-compose.yml.tmpl) -- nothing to move. Use repoint to "
                                  "point version %s at another folder." % (cur, version))
        if os.path.islink(new):
            raise AgentError(409, "%s is a symbolic link -- move the server to a real folder." % new)
        if os.path.isdir(new) and _is_mount(new):
            # the job would copy onto the parent's filesystem and then fail to replace the mount point
            raise AgentError(409, "%s is a mount point -- a move cannot replace it; move the server into a folder "
                                  "inside it, like %s." % (new, os.path.join(new, "%s_live" % version)))
        if target not in ("absent", "empty"):
            raise AgentError(409, "%s is not empty -- a move needs a folder that does not exist yet or is empty%s."
                             % (new, " (it holds a server already: repoint switches to it)" if target == "stack" else ""))
        need, free = rep["needBytes"], rep["freeBytes"]
        if need is not None and free is not None and free < need:
            raise AgentError(409, "Not enough free disk space on the target drive: %.1f GB needed (%.1f GB of server "
                                  "files + %d MiB reserve, GIO_FETCH_DISK_RESERVE), %.1f GB free at %s."
                             % (need / 1e9, rep["stackBytes"] / 1e9, FETCH_DISK_RESERVE >> 20, free / 1e9,
                                _existing_ancestor(new)))
    elif new and target == "other":
        raise AgentError(409, "The folder is not empty and holds no server: %s" % new)
    if not in_job:
        busy = current_job()
        if busy is not None:
            raise _busy_error(busy)


def relocate_check(version, raw_dir, mode, in_job=False, measure=True):
    """POST /server/relocate {"check": true}, the real request's synchronous refusals and the job's first
    step (again, under _op_lock). Returns (report, refusal): the report is the check reply -- what was
    measured, `ok`, and `problem` (the refusal's text) -- and refusal the AgentError the real request
    raises (None = go). An unknown version or mode is raised at once (400): nothing to report on.
    stackBytes / needBytes: a move across volumes only (on one volume nothing is copied); measure=False
    (the job) skips that walk -- the move measures the stopped tree itself. With measure, a repoint also
    reports, as optional facts: `carry` -- away from a configured folder that holds no server: what a download
    left beside it and the repoint takes along ({name, size, fits}; [] for nothing) -- and `download` -- to a
    folder still absent or empty, with a usable catalogue: a download into that folder as fetch_brief would
    report it once the version points there (fetch_download_block). Neither ever refuses a repoint."""
    check_known(version)
    if mode not in RELOCATE_MODES:
        raise AgentError(400, "mode must be move or repoint")
    meta = VERSIONS[version]  # one read: a relocation swaps the whole dict
    cur = meta["dir"]
    rep = {"version": version, "mode": mode, "from": cur, "to": raw_dir.strip() if isinstance(raw_dir, str) else "",
           "target": None, "running": None, "sameVolume": None, "stackBytes": None, "freeBytes": None,
           "needBytes": None, "ok": False, "problem": None}
    try:
        new = relocate_target(raw_dir, mode, version)
        rep["to"] = new
        ls_err = None
        if cur:
            projects, err = running_projects()
            if err is None:
                rep["running"] = meta["project"] in projects
            elif is_present(version) or is_bootstrapped(version):
                ls_err = err  # a stack that may be running is never moved blind
        else:
            rep["running"] = False
        projects_all = None
        if new:
            rep["target"] = relocate_target_kind(new)
            rep["freeBytes"] = _free_bytes_at(new)
            projects_all = compose_projects_all()[0]  # None (docker mute): ls_err covers a stack that may run
        if mode == "move" and new and cur and is_present(version) and rep["target"] in ("absent", "empty"):
            rep["sameVolume"] = _same_volume(cur, new)
            if rep["sameVolume"] is not True and measure:
                try:
                    rep["stackBytes"] = _tree_counts(cur)[2]
                except OSError as e:
                    raise AgentError(500, "Cannot measure %s (%s)." % (cur, e))
                rep["needBytes"] = rep["stackBytes"] + FETCH_DISK_RESERVE
        plan_ = []
        if measure and mode == "repoint" and new and cur and not _stack_present_at(cur):
            plan_ = relocate_carry_plan(version, cur, new, rep["target"], usable_stack_catalog(version))
            rep["carry"] = [{"name": os.path.basename(e["src"]), "size": e["size"], "fits": e["fits"]} for e in plan_]
        if measure and mode == "repoint" and new and rep["target"] in ("absent", "empty"):
            cat_ = usable_stack_catalog(version)
            if cat_ is not None:
                block = fetch_download_block(version, new, cat_, [e for e in plan_ if e["fits"]])
                if block is not None:
                    rep["download"] = block
        _relocate_refusal(version, cur, new, mode, rep, ls_err, in_job, projects_all)
    except AgentError as e:
        rep["problem"] = e.message
        return rep, e
    rep["ok"] = True
    return rep, None


def relocate_carry_plan(version, old, new, target, cat):
    """What a repoint of `version` from `old` (a folder that holds no server) to `new` carries along, from stats
    alone -- the rule do_relocate applies: [] unless target is "absent" or "empty"; else, for each format the
    version's downloads may leave (the formats of the catalogue `cat`, every known one without a usable
    catalogue -- stack_archive_exts) in that order, <old><ext> and <old><ext>.part when it is a file and nothing
    stands at the <new> name: every .part, a complete archive only of the catalogue's size for that format (no
    usable catalogue: none) -- and, for a complete archive that has to go to another drive, only while nothing
    stands at <new><ext>.part either (the copy goes through that name; the job leaves the archive where it is
    otherwise). Each {"suffix", "src", "dst", "size", "sameVolume", "fits"}: fits = a rename on one volume, or
    room on the new drive for its size + FETCH_DISK_RESERVE after the entries before it (room that cannot be
    read counts as room). Never raises (an entry it cannot judge is left out)."""
    out = []
    if target not in ("absent", "empty") or not old or not new:
        return out
    try:
        archives = stack_archives(cat) if cat is not None else []
        sizes = {a["ext"]: a["size"] for a in archives}
        exts = tuple(a["ext"] for a in archives) if cat is not None else STACK_ARCHIVE_EXTS
        old_s, new_s = old.rstrip("/\\"), new.rstrip("/\\")
        free, read, used = None, False, 0
        for suffix in [ext + tail for ext in exts for tail in ("", ".part")]:
            try:
                src, dst = old_s + suffix, new_s + suffix
                if not os.path.isfile(src) or os.path.lexists(dst):
                    continue
                size = os.path.getsize(src)
                complete = not suffix.endswith(".part")
                if complete and sizes.get(suffix) != size:
                    continue  # a complete file of another size is somebody's own: it stays
                same = _same_volume(src, dst) is True
                if complete and not same and os.path.lexists(dst + ".part"):
                    continue  # its copy to the other drive would go through a name that is taken: it stays
                fits = same
                if not same:
                    if not read:
                        free, read = _free_bytes_at(os.path.dirname(os.path.abspath(dst))), True
                    fits = free is None or free >= used + size + FETCH_DISK_RESERVE
                    if fits:
                        used += size
                out.append({"suffix": suffix, "src": src, "dst": dst, "size": size, "sameVolume": same, "fits": fits})
            except Exception:  # noqa: BLE001 -- an entry it cannot judge is left out
                continue
    except Exception:  # noqa: BLE001 -- an optional fact
        pass
    return out


def fetch_download_block(version, d, cat, carried=()):
    """relocate_check's `download`: a download of `version` into the candidate folder d, as fetch_brief would
    report it once the version points there -- {archive, size, extractedSize, reserve, need, free, tool,
    problem}; `carried` = what the repoint brings beside d (relocate_carry_plan's entries that fit). None on any
    failure (the key is then left out)."""
    try:
        found = find_extractor()
        arc = planned_stack_archive_at(d, cat, found, carried)
        ref = arc or stack_archives(cat)[0]
        n = fetch_disk_need_at(d, cat, arc, carried) if arc is not None else None
        err = fetch_refusal(version, d, cat, found, carried=carried)
        return {"archive": arc["ext"][1:] if arc is not None else None, "size": ref["size"],
                "extractedSize": int(cat.get("extractedSize") or 0), "reserve": FETCH_DISK_RESERVE,
                "need": n["need"] if n else None, "free": n["free"] if n else _free_bytes_at(_stack_parent(d)),
                "tool": None if arc is None else "zipfile" if arc["ext"] == ".zip" else os.path.basename(found[0]),
                "problem": err.message if err is not None else None}
    except Exception:  # noqa: BLE001 -- an optional fact
        return None


def _rename_retry(src, dst, should_stop=None, wait=None):
    """os.rename, retried for up to RELOCATE_RENAME_WAIT seconds while the OS reports the tree in use
    (Windows: Docker Desktop and antivirus scanners let go of a stack's files a few seconds after the
    down -- the same wait _rmtree_retry gives them). A cross-volume refusal and anything else raise at once."""
    deadline = time.monotonic() + (RELOCATE_RENAME_WAIT if wait is None else wait)
    while True:
        try:
            os.rename(src, dst)
            return
        except OSError as e:
            if _cross_device(e):
                raise
            in_use = isinstance(e, PermissionError) or getattr(e, "winerror", None) in (5, 32, 33) \
                or getattr(e, "errno", None) == errno.EBUSY
            if not in_use or time.monotonic() >= deadline or (should_stop is not None and should_stop()):
                raise
            time.sleep(1.0)


def _copy_tree(src, dst, job, should_stop, total):
    """The cross-volume copy of a stopped stack into dst (created): `cp -a` on POSIX -- owner, mode,
    symbolic and hard links, xattrs kept, which MariaDB's and redis' data folders need -- a Python walk
    on Windows. Module level: the selftest swaps it. RelocateStopped on a stop request, OSError else."""
    if os.name == "nt":
        return _copy_tree_py(src, dst, job, should_stop, total)
    return _copy_tree_cp(src, dst, job, should_stop, total)


def _copy_progress(job, done, total):
    job.log("  %.1f of %.1f GB copied (%d%%)" % (done / 1e9, total / 1e9, done * 100 // max(total, 1)))


def _copy_tree_cp(src, dst, job, should_stop, total):
    """POSIX: `cp -a <src>/. <dst>/`, polled every 0.5 s (a stop request kills it), a progress line from
    measuring dst every RELOCATE_PROGRESS_EVERY seconds. Returns the bytes of the tree."""
    os.makedirs(dst, exist_ok=True)
    argv = ["cp", "-a", os.path.join(src, "."), dst.rstrip(os.sep) + os.sep]
    job.log("$ cp -a %s %s" % (argv[2], argv[3]))
    p = subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         **_popen_kwargs())
    tail = []

    def drain():
        # an error per file on a damaged tree must not block cp on a full pipe; keep only the end
        try:
            buf = b""
            for chunk in iter(lambda: p.stdout.read(4096), b""):
                buf = (buf + chunk)[-2048:]
            tail.append(buf)
        except Exception:  # noqa: BLE001 -- the pipe closing under a kill
            pass

    t = threading.Thread(target=drain, daemon=True)
    t.start()
    started = last = time.time()
    while True:
        rc = p.poll()
        if rc is not None:
            break
        if should_stop():
            _kill_quiet(p)
            raise RelocateStopped("stopped on request")
        now = time.time()
        if now - started > RELOCATE_COPY_TIMEOUT:
            _kill_quiet(p)
            raise OSError("cp -a did not finish within %d hours" % (RELOCATE_COPY_TIMEOUT // 3600))
        if now - last >= RELOCATE_PROGRESS_EVERY:
            last = now
            try:
                _copy_progress(job, _tree_counts(dst)[2], total)
            except OSError:
                pass
        time.sleep(0.5)
    t.join(5)
    if rc != 0:
        text = (tail[0] if tail else b"").decode("utf-8", "replace").strip()
        text = " | ".join(l.strip() for l in text.splitlines()[-4:] if l.strip())
        raise OSError("cp -a exited with code %d%s" % (rc, (": " + text) if text else ""))
    return total


def _copy_file_durable(src, dst, should_stop=None):
    """shutil.copy2 whose data is ON DISK when it returns: the bytes copied into a new file, fsync'ed (the
    only copy of the database is deleted after the move -- a lazy writer must not be holding it), THEN the
    times and the read-only bit (copystat: fsync needs a writable handle, so the read-only bit comes last).
    `should_stop` (a stop request) is asked before every MiB: RelocateStopped then, the partial dst is the
    caller's to remove."""
    with open(src, "rb") as fsrc, open(dst, "wb") as fdst:
        if should_stop is None:
            shutil.copyfileobj(fsrc, fdst, 1 << 20)
        else:
            while True:
                if should_stop():
                    raise RelocateStopped("stopped on request")
                chunk = fsrc.read(1 << 20)
                if not chunk:
                    break
                fdst.write(chunk)
        fdst.flush()
        os.fsync(fdst.fileno())
    shutil.copystat(src, dst, follow_symlinks=False)


def _copy_tree_py(src, dst, job, should_stop, total):
    """Windows: the tree copied entry by entry -- _copy_file_durable (data fsync'ed, times, the read-only
    bit), a symbolic link recreated as one --, the stop request honoured between two files, a progress line
    every RELOCATE_PROGRESS_BYTES. Folder metadata is not copied (a Windows stack folder carries none that
    matters; the caller restores the ACL of creds.txt and the creds record). Returns the bytes copied."""
    copied, next_log = 0, RELOCATE_PROGRESS_BYTES
    os.makedirs(dst, exist_ok=True)
    todo = [(src, dst)]
    while todo:
        s, d = todo.pop()
        with os.scandir(s) as it:
            entries = sorted(it, key=lambda e: e.name)
        for e in entries:
            if should_stop():
                raise RelocateStopped("stopped on request")
            target = os.path.join(d, e.name)
            if e.is_symlink():
                os.symlink(os.readlink(e.path), target, target_is_directory=os.path.isdir(e.path))
            elif e.is_dir():
                os.mkdir(target)
                todo.append((e.path, target))
            else:
                _copy_file_durable(e.path, target)
                copied += e.stat(follow_symlinks=False).st_size
                if copied >= next_log:
                    _copy_progress(job, copied, total)
                    next_log = copied + RELOCATE_PROGRESS_BYTES
    return copied


def _relocate_restart(version, job):
    """Start the version again after a relocation -- or the rollback of one -- found it running: the start
    job's own routine (the job already holds _op_lock), never with an import (provision "never": moving a
    folder must not provision anything). A failure is logged, never raised: by then the relocation is
    decided either way. Returns (started, the error text or None)."""
    job.log("Starting version %s again ..." % version)
    try:
        do_start(version, job, provision="never")
        return True, None
    except AgentError as e:
        err = e.message
    except Exception as e:  # noqa: BLE001 -- the relocation's outcome must still be reported
        err = str(e)
    job.log("WARNING: version %s did not start again (%s) -- start it from the Server page." % (version, err))
    return False, err


def _relocate_down(version, job, old, new, project, was_up):
    """Bring the version down under its CURRENT project name: `down --remove-orphans` with the full grace
    (the game server flushes the players' data) -- containers left merely stopped would keep the old bind
    paths and, with restart: always, come back on the next docker start. A project still running whose
    folder no longer holds its compose file (the tree moved by hand) is brought down by name with the
    compose file of the folder it is being re-pointed at. Then docker must no longer list it."""
    compose_dir, extra = old, ()
    if not os.path.isfile(os.path.join(old, "docker-compose.yml")):
        if new and os.path.isfile(os.path.join(new, "docker-compose.yml")):
            compose_dir, extra = new, ("-p", project)
        else:
            raise AgentError(409, "The docker project %s is running, but %s no longer holds its docker-compose.yml -- "
                                  "stop it by hand (docker compose -p %s down) and retry." % (project, old, project))
    # strict: 507 before the down -- a stack in transition must never look "supposed to be up" to the watchdog
    version_state_set(version, strict=True, runningOk=False)
    job.log("Stopping version %s (docker compose down of project %s -- every grace period is waited out so the "
            "game server saves the players' data) ..." % (version, project))
    # (a failure below has stopped the server, or part of it: "nothing was moved" -- do_relocate starts it
    # again when it was running)
    rc = _compose_stream(compose_dir, job, *extra, "down", "--remove-orphans", prefix="  ")
    if rc != 0:
        raise AgentError(500, "docker compose down failed (code %d) -- nothing was moved." % rc)
    projects, err = running_projects()
    if err is not None:
        raise AgentError(500, "Cannot read the docker state after the down (%s) -- nothing was moved; retry." % err)
    if project in projects:
        raise AgentError(500, "docker still lists the %s project after the down -- nothing was moved. Stop it in "
                              "Docker and retry." % project)
    job.log("Version %s is down." % version)


def _relocate_move_tree(version, job, old, new, was_up):
    """move: the stopped stack's tree from old to new. Returns (cross_volume, bytes copied or None). On
    a failure or a stop request nothing is left behind -- the temp copy removed, an empty target folder
    the admin made put back, created parents pruned --, the stack is started again where it was when it
    was running, and the job fails (a stop: 409 "Stopped on request")."""
    parent = os.path.dirname(new)
    target_existed = os.path.isdir(new)  # validated: absent or empty
    created, tmp = [], None
    try:
        created = _makedirs_tracked(parent)
        if _same_volume(old, new):
            if target_existed:
                os.rmdir(new)
            job.log("Moving %s -> %s (the same drive: one rename) ..." % (old, new))
            try:
                _rename_retry(old, new, should_stop=_relocate_cancel.is_set)
                return False, None
            except OSError as e:
                if not _cross_device(e):
                    raise
                job.log("The rename crosses a volume boundary after all (%s) -- copying instead." % e)
        files, folders, total = _tree_counts(old)
        free = _free_bytes_at(parent)
        if free is not None and free < total + FETCH_DISK_RESERVE:
            raise AgentError(409, "Not enough free disk space on the target drive: %.1f GB needed (%.1f GB of server "
                                  "files + %d MiB reserve), %.1f GB free at %s."
                             % ((total + FETCH_DISK_RESERVE) / 1e9, total / 1e9, FETCH_DISK_RESERVE >> 20,
                                free / 1e9, parent))
        tmp = os.path.join(parent, ".relic-move-" + os.path.basename(new))
        _rmtree_retry(tmp)  # the leftover of a run that died half-way
        job.log("Copying %d files (%.1f GB) to the other drive into %s -- the old copy stays until the new one is "
                "verified and the configuration names it ..." % (files, total / 1e9, tmp))
        _copy_tree(old, tmp, job, _relocate_cancel.is_set, total)
        # The copy must be ON DISK before the configuration names it and the old tree is deleted: cp -a and the
        # page cache leave it dirty for up to ~30 s (delayed allocation), and a power cut then would leave the
        # new database files empty with the old ones already gone. (Windows: each file was fsync'ed.)
        job.log("Flushing the copy to disk ...")
        _sync_filesystems()
        got = _tree_counts(tmp)
        if got != (files, folders, total):
            raise OSError("the copy does not match the original (%d files, %d folders, %d bytes; expected %d, %d, %d)"
                          % (got + (files, folders, total)))
        job.log("Copy verified: %d files, %d folders, %d bytes." % (files, folders, total))
        if os.path.isdir(new):
            os.rmdir(new)
        _rename_retry(tmp, new)
        tmp = None
        _fsync_dir(parent)  # the rename durable too, before the config write that follows
        return True, total
    except BaseException as e:
        if tmp is not None:
            _rmtree_quiet(tmp)
        if target_existed and not os.path.lexists(new):
            try:
                os.mkdir(new)
            except OSError:
                pass
        _prune_dirs(created)
        if isinstance(e, RelocateStopped) or (isinstance(e, OSError) and _relocate_cancel.is_set()):
            if was_up:
                _relocate_restart(version, job)
            raise AgentError(409, "Stopped on request -- nothing was moved; %s stays the folder of version %s."
                             % (old, version))
        if isinstance(e, (AgentError, OSError)):
            if was_up:
                _relocate_restart(version, job)
            if isinstance(e, AgentError):
                raise
            raise AgentError(500, "Moving %s to %s failed (%s) -- nothing was moved; the server stays in %s."
                             % (old, new, e, old))
        raise


def _rename_file(src, dst, should_stop=None):
    """The rename of one file beside a stack folder, retried while the OS reports it in use (_rename_retry: a
    scanner that holds a large .part a moment longer; another drive raises at once) -- module level: the selftest
    swaps it (a carry that has to cross to another drive)."""
    _rename_retry(src, dst, should_stop=should_stop)


def _relocate_siblings(old, new, job, exts=STACK_ARCHIVE_EXTS, should_stop=None, header=None, sizes=None):
    """What a download left beside the old folder follows the version to the new one -- <old>.7z (a verified
    archive a retry adopts) and <old>.7z.part (a resumable download) become <new>.7z(.part), a .zip likewise
    -- and a stale extraction folder of the old name is removed. After a move `sizes` is None: every file of
    the version's formats follows the tree. After a repoint away from a folder that holds no server `sizes` =
    {ext: the catalogue's size}: a .part follows, a complete archive only of that size (a file of another size
    is somebody's own; no usable catalogue = an empty dict: none). `exts` = the archive formats that are this
    version's (stack_archive_exts: the ones its catalogue names); a file of another format beside the folder is
    nothing a download of it left, and stays. Each file goes by one rename; to another drive it is copied
    durably once that drive has room for it and FETCH_DISK_RESERVE -- a complete archive through
    <new><ext>.part, so a copy cut short is a partial download the next fetch continues -- and the original is
    removed after. The parent folder of `new` is created for the first file that goes (taken back when none
    did; the line that says so comes with the first file that arrived); `should_stop` (a stop request) leaves
    the rest where it is, one line each; `header` is logged once, before the first line of the call. Best
    effort, logged; never raises."""
    old_s, new_s = old.rstrip("/\\"), new.rstrip("/\\")
    parent = os.path.dirname(os.path.abspath(new_s))
    said = [header is None]

    def say(line):
        if not said[0]:
            said[0] = True
            job.log(header)
        job.log(line)

    def stopped(src_):
        say("  %s left where it is (stopped on request) -- move it beside %s by hand to continue that download."
            % (src_, new_s))

    created, moved = None, 0
    for suffix in [ext + tail for ext in exts for tail in ("", ".part")]:
        src, dst = old_s + suffix, new_s + suffix
        try:
            if not os.path.isfile(src):
                continue
            if os.path.lexists(dst):
                say("  %s is already there -- %s left where it is." % (dst, src))
                continue
            size = os.path.getsize(src)
            complete = not suffix.endswith(".part")
            if sizes is not None and complete and sizes.get(suffix) != size:
                say("  %s left where it is: it is not the catalogue's archive (its size differs)." % src)
                continue
            if should_stop is not None and should_stop():
                stopped(src)
                continue
            if created is None:
                created = _makedirs_tracked(parent)
            try:
                _rename_file(src, dst, should_stop=should_stop)
            except OSError as e:
                if not _cross_device(e):
                    if should_stop is not None and should_stop():
                        stopped(src)  # a stop request ended the wait for a file the OS still held
                        continue
                    raise
                # another drive: room first, then a copy that is on disk before the original goes
                free = _free_bytes_at(os.path.dirname(os.path.abspath(dst)))
                if free is not None and free < size + FETCH_DISK_RESERVE:
                    say("  %s left where it is: %.1f GB do not fit on the drive of %s (%.1f GB free there, %d MiB "
                        "kept in reserve) -- move it by hand." % (src, size / 1e9, new_s, free / 1e9,
                                                                  FETCH_DISK_RESERVE >> 20))
                    continue
                target = dst + ".part" if complete else dst
                if complete and os.path.lexists(target):
                    say("  %s is already there -- %s left where it is." % (target, src))
                    continue
                try:
                    _copy_file_durable(src, target, should_stop=should_stop)
                    got = os.path.getsize(target)
                    if got != size:
                        raise OSError("the copy of %s has %d bytes, not %d" % (src, got, size))
                except RelocateStopped:
                    _remove_quiet(target)
                    stopped(src)
                    continue
                except BaseException:
                    _remove_quiet(target)
                    raise
                if complete:
                    os.rename(target, dst)  # one folder: the verified copy takes the archive's name
                os.remove(src)
            if created and not moved:
                say("  created %s for what follows the version" % parent)
            moved += 1
            say("  moved %s -> %s" % (src, dst))
        except Exception as e:  # noqa: BLE001 -- best effort: the relocation itself is decided by now
            say("  WARNING: could not move %s (%s) -- move or delete it by hand." % (src, e))
    if not moved and created:
        _prune_dirs(created)  # nothing followed: the folders made for it go again, unnamed in the log
    try:
        stale = os.path.join(os.path.dirname(os.path.abspath(old_s)), ".relic-extract-" + os.path.basename(old_s))
        if os.path.isdir(stale):
            try:
                _rmtree_retry(stale)
                say("  removed the stale extraction folder %s" % stale)
            except OSError as e:
                say("  WARNING: could not remove %s (%s) -- delete it by hand." % (stale, e))
    except Exception:  # noqa: BLE001 -- never raises
        pass


def _relocate_left_behind(old, new, job, exts, version=None):
    """A repoint from a folder that holds no server to one that holds a server -- or to none (`new` "", the
    version taken off): what a download left beside the old folder stays where it is -- nothing continues it
    there --, one line each. Never raises."""
    try:
        old_s = old.rstrip("/\\")
        for suffix in [ext + tail for ext in exts for tail in ("", ".part")]:
            src = old_s + suffix
            if not os.path.isfile(src):
                continue
            if new:
                job.log("  %s stays where it is: %s holds a server, so no download continues there -- delete it "
                        "once it is not needed." % (src, new))
            else:
                job.log("  %s stays where it is: version %s no longer has a folder -- point it at %s again to "
                        "continue that download, or delete it." % (src, version, old_s))
    except Exception:  # noqa: BLE001
        pass


def relocated_version_state(vs):
    """The record a version keeps when it is re-pointed at ANOTHER server's folder (see _RELOCATE_DROP):
    the admin's decisions only, runningOk off, an enabled hotpatch pending again. Pure."""
    out = {"runningOk": False}
    if "pathfinding" in vs:
        out["pathfinding"] = vs["pathfinding"]
    hp = vs.get("hotpatch")
    if isinstance(hp, dict):
        kept = {k: hp[k] for k in _RELOCATE_HOTPATCH_KEEP if k in hp}
        kept["pending"] = bool(hp.get("enabled"))
        out["hotpatch"] = kept
    return out


def _repoint_state(version, new, job):
    """repoint: the version's record follows the folder only when the folder IS the same server -- its
    .relic-provisioned says what the state's provisionedAt says (the tree was moved by hand). Otherwise
    it starts over (relocated_version_state), passwordVerify is read from the new stack's sdk config (a
    signup must know whether a password is enforced), and the marker logic fills the provisioning record
    in from the new folder. Runs after VERSIONS was swapped. Returns True when the record was reset."""
    marker = marker_at(new)
    with _state_lock:
        try:
            data = load_state()
        except StateUnreadable:
            raise state_unreadable_error()
        versions = data.setdefault("versions", {})
        vs = versions.get(version) or {}
        at = vs.get("provisionedAt")
        if at and marker is not None and str(marker["at"]) == str(at):
            job.log("%s holds the same server (its %s says provisioned %s, as the agent's record does) -- the "
                    "version's record is kept." % (new, PROVISIONED_MARKER, at))
            return False
        rec = relocated_version_state(vs)
        pv = sdk_password_verify_setting(version)
        if pv is not None:
            rec["passwordVerify"] = pv
        no_record = marker is None and is_bootstrapped(version)  # VERSIONS already names the new folder
        if no_record:
            # An installed server this agent holds no provisioning record of (a vendor bootstrap.sh stack, a
            # copy without its marker): its database may hold players, and nothing could re-seed the record
            # -- the next Start (provision "auto") would import the shipped save over it. Only an explicit
            # Provision clears this (do_provision); needs_provision honours it.
            rec["autoProvision"] = False
        versions[version] = rec
        try:
            save_state(data, strict=True)
        except AgentError as e:
            raise AgentError(507, "Version %s now uses %s, but the agent state could not be updated (%s) -- it still "
                                  "describes the previous server. Fix the state folder and re-point again."
                             % (version, new, e.message), code="state_write_failed")
    if marker is not None:
        job.log("%s is another server than the one on record -- the version's record starts over from its %s "
                "(provisioned %s, progress %s); the admin's choices (pathfinding, hotpatch) are kept."
                % (new, PROVISIONED_MARKER, marker["at"], marker["progress"]))
    elif no_record:
        job.log("%s holds an installed server but no provisioning record of this agent -- the version's record "
                "starts over; the admin's choices (pathfinding, hotpatch) are kept. Automatic provisioning is OFF "
                "for it: no Start imports the save over that database -- only an explicit Provision (Re-apply the "
                "progress) touches it." % new)
    else:
        job.log("%s holds no provisioning record of this agent -- the version's record starts over; the admin's "
                "choices (pathfinding, hotpatch) are kept." % new)
    return True


def do_relocate(version, job, raw_dir, mode):
    """POST /server/relocate (job `relocate`, under _op_lock) -- see the section comment. Returns {version,
    from, to, mode, moved, crossVolume, bytes, restarted, stateReset, restartError}."""
    _relocate_cancel.clear()
    require_state_readable()
    rep, err = relocate_check(version, raw_dir, mode, in_job=True, measure=False)
    if err is not None:
        raise err
    old, new = rep["from"], rep["to"]
    old_holds_stack = bool(old) and _stack_present_at(old)  # before anything is moved or stopped
    key = dir_setting_key(version)
    project = VERSIONS[version]["project"]
    was_up = bool(rep["running"])
    job.log("%s version %s: %s -> %s." % ("Moving" if mode == "move" else "Re-pointing", version,
                                          old or "(not configured)", new or "(not configured)"))
    # 1. down under the OLD project name (a stack merely installed too: its stopped containers must go)
    if old and (was_up or is_bootstrapped(version)):
        try:
            _relocate_down(version, job, old, new, project, was_up)
        except AgentError as e:
            # a 409 / 507 is raised before anything is stopped; a failed down (500) may have stopped all or part
            # of a running server, with runningOk already off -- no watchdog would bring it back
            if e.status != 500 or not was_up:
                raise
            started, rerr = _relocate_restart(version, job)
            raise AgentError(500, "%s The server had been stopped for the move; %s." % (
                e.message, "it was started again" if started
                else "it did not start again (%s) -- start it from the Server page" % rerr))
    if _relocate_cancel.is_set():
        if was_up:
            _relocate_restart(version, job)
        raise AgentError(409, "Stopped on request -- nothing was moved or changed.")
    # 2. the files (move only)
    moved = cross = False
    nbytes = None
    if mode == "move":
        cross, nbytes = _relocate_move_tree(version, job, old, new, was_up)
        moved = True
    # 3. the config file BEFORE anything old is deleted: a restart must find the server where it is
    try:
        save_config_values({key: new}, explicit_empty=(key,))
    except AgentError as e:
        undo = "nothing had been moved"
        if moved and not cross:
            try:
                _rename_retry(new, old)
                undo = "the folder was moved back to %s" % old
            except OSError as e2:
                raise AgentError(500, "Saving %s failed (%s), and moving the folder back failed too (%s): the server "
                                      "is now in %s while the configuration still names %s -- set %s=%s in %s by hand "
                                      "and restart the agent." % (key, e.message, e2, new, old, key, new, CONFIG_PATH))
        elif moved:
            _rmtree_quiet(new)
            undo = "the copy was deleted, %s is untouched" % old
        if was_up:
            _relocate_restart(version, job)
        raise AgentError(500, "Saving %s in %s failed (%s) -- %s." % (key, CONFIG_PATH, e.message, undo))
    # 4. this process follows: one assignment (status() and the watchdogs read VERSIONS without a lock)
    set_version_dir(version, new)
    job.log("Configuration saved: %s=%s. Version %s %s." % (
        key, new, version, ("now uses %s (docker project %s)" % (new, VERSIONS[version]["project"])) if new
        else "is no longer configured on this agent (its files are untouched)"))
    # 5. what a download left beside the old folder follows the version: after a move it follows the tree; after a
    #    repoint away from a folder that holds no server to one still absent or empty, nothing would ever continue
    #    it beside the old folder. Before the record is looked at: a state write that fails must not strand it.
    carry = mode == "repoint" and bool(old) and bool(new) and not old_holds_stack and rep["target"] in ("absent", "empty")
    if moved or carry:
        cat = usable_stack_catalog(version)
        _relocate_siblings(old, new, job, stack_archive_exts(version), should_stop=_relocate_cancel.is_set,
                           header=None if moved else "%s holds no server -- what a download left beside it follows "
                                                     "version %s to %s:" % (old, version, new),
                           sizes=None if moved else ({a["ext"]: a["size"] for a in stack_archives(cat)} if cat else {}))
    elif mode == "repoint" and old and not old_holds_stack:
        # the target holds a server, or the version leaves the agent ("")
        _relocate_left_behind(old, new, job, stack_archive_exts(version), version)
    # 6. repoint: whose record is it?
    state_reset = _repoint_state(version, new, job) if mode == "repoint" and new else False
    # 7. the old copy of a cross-volume move
    if cross:
        job.log("Deleting the old copy %s ..." % old)
        try:
            _rmtree_retry(old)
            job.log("  deleted.")
        except OSError as e:
            job.log("WARNING: the old copy %s could not be deleted completely (%s) -- delete it by hand; the server "
                    "runs from %s now." % (old, e, new))
    # 8. heal what a hand-extracted or copied tree may lack
    if new and is_present(version):
        ensure_data_layout(version, job)
        ensure_exec_bits(version, job)
        for name in ("creds.txt", CREDS_RECORD):
            creds = os.path.join(new, name)
            if IS_WINDOWS and os.path.isfile(creds):
                protect_path(creds, 0o600)  # a copied file inherits the new folder's ACL
    # 9. back up where it was running
    restarted, restart_err = False, None
    if was_up:
        if new and is_present(version) and is_bootstrapped(version):
            restarted, restart_err = _relocate_restart(version, job)
        else:
            job.log("Version %s was running; %s, so it stays down -- %s." % (
                version, ("%s holds no installed server" % new) if new else "it has no folder any more",
                "Prepare the server there" if new else "point it at a folder again to use it"))
    elif new:
        job.log("Version %s was not running -- it stays down." % version)
    return {"version": version, "from": old, "to": new, "mode": mode, "moved": moved, "crossVolume": cross,
            "bytes": nbytes, "restarted": restarted, "stateReset": state_reset, "restartError": restart_err}


# -- gameplay settings ("tweaks") --
# An admin's changes to a version's own game data: the resin cap and its regeneration speed, the Spiral
# Abyss enemy line-up and enemy level per chamber, the enemy line-up and the enemy level of a domain, what
# the domains hand out and cost, what the quests reward. ONE document per version says what is wanted (every
# key optional, an absent key = the server's original value); the catalogue payloads/<version>/tweaks.json
# says which files, rows and ids exist and pins every file the feature may rewrite to the md5 of the
# vendor's original. A line-up is the monsters table of a Lua script, the script of ONE monster group: each
# half of an Abyss chamber spawns from one, and so does a domain (the catalogue's domains.lineups, which a
# catalogue may lack -- the weekday variants of one difficulty share theirs). Both are edited the same way,
# a spawn slot at a time. The enemy level of a domain is a cell of its own row of the dungeon table -- one
# per weekday variant --, which the server adds to the level of every levelled entry of the domain's scene:
# it can be set where the catalogue says how far that scene can be raised (the `top` of the line-up, read off
# the vendor's scripts of the scene) and while the line-up's own script -- the one of them the agent
# rewrites -- is the original or an output of the agent. A hand edit of another script of the scene is not
# seen: the agent never writes those, and the catalogue pins none of them.
#
# The game services rebuild their whole config from disk on SIGHUP, and by themselves where their build
# reloads on a timer (tweaks_reload_timer); where it does not, the agent asks each of them in turn. A reload that
# fails keeps the previous config and only logs it; the same files end the process at its next boot. So:
#   a game service never boots from a tweaked file the server's own loader has not accepted. A tweaked
#   (non-original) file is written ONLY while the game server runs and is followed by a reload whose
#   verdict is read from the server's log; a refusal or a missing verdict puts the previous bytes back at
#   once. While the stack is down the only write allowed is putting ORIGINAL bytes back.
# What an apply that was cut off leaves behind -- files written, no verdict on record -- is taken back by
# the LEFTOVER RULE (tweaks_before_boot): every file of the record built on the vendor's original gets that
# original back; a file whose base was taken over gets the bytes it held before the write that had no verdict
# -- never that base (tweaks_restore_originals). It runs in front of
# EVERY docker call of the agent that boots or restarts a service that loads those files -- a Start, a
# provision, the vendor bootstrap, the watchdogs' revive and towerfix, events, txt fixes, the restarts of
# netfix, of the advertise follow and of the hotpatch, a secrets rotation, the pathfinding enable (a
# selftest holds every such call to it) -- and once when the agent itself starts, when no apply can be
# under way.
#
# Nothing about it lives in the agent's state file: the record and the bases stay WITH the stack, so they
# follow a moved, re-pointed or re-extracted folder.
#   <stack>/.relic-tweaks/record.json  {"schema", "tweaks": the wanted document, "active": the document the
#                                       files on disk correspond to (the last one the server accepted),
#                                       "refused": null | {"at", "error", "digest"},
#                                       "files": {"<path>": ENTRY}[, "unread": true]}
#                                       unread (only while true) = the data files changed while a service that
#                                       does not reload by itself ran, and not every such service that runs was
#                                       asked to read them since
#     ENTRY = {"base": md5 of the BASE the agent builds the file's output from, "out": md5 of what the agent
#              last had in the file, "ok": false while it was written and no verdict came yet[, "prev": md5 of
#              what the agent had there before a rewrite that has no verdict -- a run that dies between the
#              record and the file still knows the file as its own][, "taken": {"at", "hand": md5 of the
#              hand-changed file as it was found, "vendor": the catalogue's md5 of the file when it was first
#              taken over} -- while the base is not the vendor's original][, "kept": [the row ids no multiplier
#              and no extra item touches]][, "undo": {"base", "kept", "keys": {document path: {"active",
#              "tweaks"}}} -- what the base, the kept rows and the settings were before the first take-over
#              since the agent's last accepted write of the file][, "released": [md5s of what a Revert or a
#              Reset let go -- the bytes the file held and, of a base taken over it let go, the change as found and
#              that base --, never taken over again; the latest TWEAKS_RELEASED_MAX]][, "away": true -- the file is
#              changed or missing; the entry stays, it is what proves the agent's own part of the file]}
#   <stack>/.relic-tweaks/base/<path>     the vendor's original of a file, copied there before its first rewrite
#   <stack>/.relic-tweaks/adopted/<path>  an ADOPTED base: the base with the rows and spawn slots a hand
#                                         changed taken from the hand-changed file (<path>.undo beside it: the
#                                         adopted base an `undo` still names)
#   <stack>/.relic-tweaks/hand/<path>     ONE copy of the bytes a hand-changed file held before the agent put
#                                         the vendor's original over them (a Revert, a Reset, the leftover rule)
#   <stack>/.relic-tweaks/prev/<path>     ONE copy of what a file on an adopted base held before the agent's last
#                                         write of it: what the leftover rule gives it back when that write got no
#                                         verdict (the copy whose md5 the entry names as `prev`)
# The vendor's original (V) of a file -- its md5 the catalogue's -- is the file itself while it is that, the
# base copy, or the member of payloads/<version>/tweaks-originals.tar.gz (tweaks_vendor_bytes); nothing else
# is ever taken for it. A target file is `original` (its md5 is the catalogue's, and no entry names it as the
# agent's output on another base), `ours` (the record names its md5 as the agent's and the base it was built
# from is there with that md5), `missing` or `changed`. A changed file is TAKEN OVER when what the agent had
# in it is proven and the rest is a change the agent can keep (tweaks_take_over): its rows and spawn slots
# that differ become part of the base, the settings they held give way, a row a multiplier touched is KEPT as
# the hand left it -- and the settings in effect, built on that base, give the file back byte for byte; a table
# put back outside Relic and changed (none of what the settings gave it left in it) becomes the base whole, the
# settings that write it applying on it again. A take-over writes no data file: tweaks_take_overs computes it
# with nothing written, and every job that plans the files stores it first (tweaks_store_take_overs). One that
# cannot be taken over stays `changed`. What the agent had in a file is proven from `active`, so `active` always
# describes every file: it loses every setting that writes a file put back to its original.
# Settings are applied ONE AT A TIME (tweaks_plan): a file that cannot carry settings -- changed and not taken
# over, missing, built on another original, refused by an editor -- blocks the settings that rest on it, the
# rest is applied, and `active` stays the EFFECTIVE document: the blocked settings at their value in effect. A
# Revert or a Reset of a card puts the card's files back at once, in two phases (_tweaks_phase_one): the
# vendor's originals first -- the hand's bytes kept in .relic-tweaks/hand/ and `released` --, then what is left
# applied on them like an Apply.
# The output of a file is a PURE function of (its base, the document, the catalogue, its kept rows) -- never
# derived from what is on disk, so applying twice changes nothing and a multiplier never compounds. Only a
# vendor's original is written without the game server's verdict (a "restore"); an adopted base and every
# other output is a judged write.
# A file the record names that the catalogue does not vouch for -- the path is not one of its files, or it
# pins another md5 for it: the record of an agent that shipped another catalogue -- is judged by its own
# entry (_tweaks_foreign): nothing is built on it. One whose base is a vendor's original still is the
# agent's, so it goes back to its base copy and keeps its entry until it has; one whose base was adopted is
# left as it is until a Reset.

TWEAKS_DIR = ".relic-tweaks"
TWEAKS_SCHEMA = 1
TWEAK_SECTIONS = ("resin", "abyss", "domains", "quests")
# ...of which the ones with a `slots` key: their cards also live on monster-group scripts (_tweaks_groups)
TWEAK_SLOT_SECTIONS = ("abyss", "domains")
TWEAK_QUEST_KINDS = ("archon", "story", "world", "event", "commission", "hangout")
# The cards as a job line names them -- the titles the launcher gives them
TWEAKS_CARD_NAMES = {"resin": "Resin", "abyss": "Spiral Abyss", "domains": "Domains", "quests": "Quest rewards"}
# What a Revert / Reset request names: the cards whose files are put back (POST /server/tweaks)
TWEAKS_FILE_OPS = ("revert", "reset")
# Why a target file cannot carry settings (GET /server/tweaks `reasons`, the job line of the settings it blocks)
TWEAKS_WHY_MISSING = "it is missing from the server's files"
TWEAKS_WHY_CHANGED = "it was changed outside Relic"
TWEAKS_WHY_FOREIGN = "Relic wrote it from another original of the file than the one its catalogue names"
TWEAKS_WHY_UNREAD = "Relic cannot read it as the file its catalogue describes"
TWEAKS_WHY_BASE_GONE = "it holds what Relic wrote, but the base Relic built it on is not there any more"
TWEAKS_WHY_CHANGING = "the data files are being changed at this moment -- read the settings again in a moment"
# The ranges GET /server/tweaks reports as `limits` and normalise_tweaks enforces: multiplierMax bounds every
# multiplier (a domain's own maximum may be lower), extraMax the items added to one domain, customMax the
# quest rewards one document replaces, domainLevel the level a domain shows -- its enemy-level cell + 1; what
# its scene places above level 1 lowers the upper end for that domain (_tweaks_domain_levels).
TWEAK_LIMITS = {"multiplierMax": 10, "extraMax": 8, "customMax": 200, "resinCap": [1, 2000],
                "minutes": [1, 1440], "level": [1, 199], "cost": [1, 200], "domainLevel": [2, 200]}
TWEAK_REWARD_ITEMS_MAX = 15  # entries of one custom quest reward...
TWEAK_REWARD_SLOTS = 9       # ...of which the items that are not virtual: a reward row has nine item slots
TWEAKS_GAME_SERVICE = "gameserver"  # the service whose own loader judges a change of the data files
# payloads/<version>/<this>: the vendor's original of every file the catalogue names, a member each (the agent's
# third source of an original -- tweaks_vendor_bytes)
TWEAKS_ORIGINALS = "tweaks-originals.tar.gz"
TWEAKS_ORIGINAL_MAX = 64 << 20  # bytes of one member read at most: no data file of a catalogue comes near it
TWEAKS_RELEASED_MAX = 16  # md5s of let-go bytes an entry remembers (`released`), the latest ones
# Header names of the vendor tables -- the server finds its columns by name, and so do the editors below.
# The names are Chinese; they are written as escapes so that this file stays ASCII.
_COL_CONST = "\u5e38\u91cf\u503c%d"  # ConstValueData: value cell 1..6 of a row
_COL_TOWER_LEVEL = "\u602a\u7269\u7b49\u7ea7"  # TowerLevelData: the enemy level of a chamber
_COL_STATUE_COST = "\u6d88\u8017\u6570\u91cf"  # DungeonData: the resin taken at the reward statue
# DungeonData: the enemy-level cell of a dungeon. The server adds it to the level every levelled entry of the
# dungeon's scene carries in its group script -- a spawn slot, an object the challenge guards.
_COL_DUNGEON_REVISE = "\u7b49\u7ea7\u4fee\u6b63"
# DropTreeData: child N of a row -- its id, its count ("N", "A;B" or "N.F") and its weight (10000 = always)
_COL_DROP_ID = "\u5b50\u6389\u843d%dID"
_COL_DROP_COUNT = "\u5b50\u6389\u843d%d\u6570\u91cf\u533a\u95f4"
_COL_DROP_WEIGHT = "\u5b50\u6389\u843d%d\u6743\u91cd"
# RewardData: item slot N of a row -- its id and its count
_COL_REWARD_ID = "Reward\u9053\u5177%dID"
_COL_REWARD_COUNT = "Reward\u9053\u5177%d\u6570\u91cf"
# RewardData: the six scalar cells of a row and the virtual item the server turns each into when it loads
# the row -- primogems, mora, adventure EXP, character EXP, companionship EXP, resin.
TWEAK_REWARD_SCALARS = (("\u539f\u77f3", 201), ("\u6469\u62c9", 202), ("\u5192\u9669\u9605\u5386", 102),
                        ("\u89d2\u8272\u7ecf\u9a8c", 101), ("\u597d\u611f\u7ecf\u9a8c", 105), ("\u6811\u8102", 106))
# TowerScheduleData: the floors every period has, and floor list N of one period
_COL_SCHEDULE_ENTRANCE = "\u5165\u53e3\u5c42ID"
_COL_SCHEDULE_FLOORS = "[\u6392\u671f]%d\u5c42ID"
_COL_SCHEDULE_FLOORS_RE = re.compile(re.escape(_COL_SCHEDULE_FLOORS).replace("%d", "[0-9]+"))
_TWEAK_PATH_RE = re.compile(r"server/data(?:/[A-Za-z0-9_][A-Za-z0-9._\-]*)+")
_TWEAK_ID_RE = re.compile(r"0|[1-9][0-9]{0,17}")
_TWEAK_MD5_RE = re.compile(r"[0-9a-fA-F]{32}")
# (kind, path, extra) -> ((mtime_ns, size, inode), value): the parsed catalogue, the md5 of a target file and
# what GET /server/tweaks reads out of an original, each remembered while its file keeps that stamp.
_tweaks_cache = {}
_tweaks_cache_lock = threading.Lock()


def _tweaks_cached(kind, path, load, extra=None):
    """load(path), remembered per (kind, path, extra) for as long as the file keeps its mtime, size and inode
    (a file replaced by a rename is a new inode even inside one clock tick). A file that cannot be stat'ed is
    never remembered: load runs, and what it raises is the caller's."""
    st = _stat_or_none(path)
    if st is None:
        return load(path)
    key, stamp = (kind, path, extra), (st.st_mtime_ns, st.st_size, st.st_ino)
    with _tweaks_cache_lock:
        hit = _tweaks_cache.get(key)
    if hit is not None and hit[0] == stamp:
        return hit[1]
    value = load(path)
    with _tweaks_cache_lock:
        _tweaks_cache[key] = (stamp, value)
    return value


def _tweak_path_ok(rel):
    """A path the feature may act on: relative, "/"-separated, under server/data/, plain segments (none
    starts with a ".", so no "..", no hidden file) and nothing Windows would read as another name."""
    return (isinstance(rel, str) and len(rel) <= 300 and _TWEAK_PATH_RE.fullmatch(rel) is not None
            and ".." not in rel and not any(seg.endswith(".") for seg in rel.split("/")))


def validate_tweaks_catalog(cat):
    """Refuse a gameplay-settings catalogue the feature cannot work from: the file ships inside the payloads,
    but a damaged or tampered copy must neither send a write outside the stack's server/data/ nor break a
    reader half-way (GET /server/tweaks walks all of it). Checked: the shape, and the cross references the
    code relies on -- every file a section names is one of `files`, one script per monster group (the groups
    of the Abyss and of the domain line-ups counted together) and each named after its group, one reward row
    per domain, every dungeon of a line-up a listed domain and in that line-up alone, the `top` of a line-up
    (the largest level an entry of its scene carries) not below the line-up's own level, and every domain of
    such a line-up listed with a level it can be set to (_tweaks_domain_levels: a document that states the
    original must never be refused). `domains.lineups` may be absent: such a catalogue lists no domain
    line-up. So may the `top` of a line-up: the enemy level of its domains cannot be set. Not checked: the
    game data itself -- the md5 of each file pins that. Pure; raises ValueError with the reason."""
    def need(cond, why):
        if not cond:
            raise ValueError(why)

    def num(x, lo=None):
        return not isinstance(x, bool) and isinstance(x, int) and (lo is None or x >= lo)

    def nums(x):
        return isinstance(x, list) and all(num(i, 0) for i in x)

    def table(value, what):
        need(isinstance(value, dict), "%s must be an object" % what)
        need(all(isinstance(k, str) and _TWEAK_ID_RE.fullmatch(k) for k in value),
             "%s: every key must be a plain decimal id" % what)
        return value

    need(isinstance(cat, dict), "not a JSON object")
    need(num(cat.get("schema")) and cat["schema"] == TWEAKS_SCHEMA, "schema must be %d" % TWEAKS_SCHEMA)
    need(isinstance(cat.get("version"), str) and cat["version"], "version must be a non-empty string")
    files = cat.get("files")
    need(isinstance(files, dict) and files, "files must be a non-empty object")
    for rel, md5 in files.items():
        need(_tweak_path_ok(rel), "files: %r is not a plain path under server/data/" % (rel,))
        need(isinstance(md5, str) and _TWEAK_MD5_RE.fullmatch(md5), "files: %s needs an md5 of 32 hex digits" % rel)

    def listed(rel, what):
        need(isinstance(rel, str) and rel in files, "%s must be one of files" % what)
        return rel

    def named(rel, group, what):
        # (GET /server/tweaks names a script it cannot rewrite by its path, in sections.<card>.files: the
        #  group id that path ends in tells its reader whose slots are out)
        need(rel.endswith("_group%d.lua" % group),
             "%s: group %d needs a script named *_group%d.lua, not %s" % (what, group, group, rel))

    resin = cat.get("resin")
    need(isinstance(resin, dict), "resin must be an object")
    listed(resin.get("file"), "resin.file")
    need(isinstance(resin.get("row"), str) and _TWEAK_ID_RE.fullmatch(resin["row"]), "resin.row must be a row id")
    need(all(num(resin.get(k), 1) for k in ("cap", "minutes", "hardMax")) and resin["cap"] <= resin["hardMax"],
         "resin: cap, minutes and hardMax must be positive integers, cap not above hardMax")
    for mid, m in table(cat.get("monsters"), "monsters").items():
        need(isinstance(m, dict) and num(m.get("tier")) and m["tier"] in (1, 2) and num(m.get("boss", 0))
             and m.get("boss", 0) in (0, 1) and ("pose" not in m or num(m["pose"], 0))
             and ("affix" not in m or nums(m["affix"])),
             "monsters.%s: tier 1 or 2, boss 0 or 1, pose an id, affix a list of ids" % mid)
    need(nums(cat.get("genericAffixes")), "genericAffixes must be a list of ids")
    abyss = cat.get("abyss")
    need(isinstance(abyss, dict), "abyss must be an object")
    listed(abyss.get("levelFile"), "abyss.levelFile")
    need(_tweak_path_ok(abyss.get("scheduleFile")), "abyss.scheduleFile must be a plain path under server/data/")
    for fid, floor in table(abyss.get("floors"), "abyss.floors").items():
        need(isinstance(floor, dict) and num(floor.get("number"), 1) and num(floor.get("teams"), 1)
             and nums(floor.get("chambers")), "abyss.floors.%s: number, teams and chambers are required" % fid)
    group_file, file_group, slot_monster = {}, {}, {}
    for lid, chamber in table(abyss.get("chambers"), "abyss.chambers").items():
        what = "abyss.chambers.%s" % lid
        need(isinstance(chamber, dict) and num(chamber.get("floor"), 0) and num(chamber.get("index"), 0)
             and num(chamber.get("level"), 1) and isinstance(chamber.get("halves"), list),
             what + ": floor, index, level and halves are required")
        for half in chamber["halves"]:
            need(isinstance(half, dict) and num(half.get("group"), 1), what + ": a half needs its monster group")
            group = half["group"]
            rel = listed(half.get("file"), "%s: the script of group %d" % (what, group))
            need(group_file.setdefault(group, rel) == rel and file_group.setdefault(rel, group) == group,
                 "%s: group %d and %s do not belong to each other alone" % (what, group, rel))
            named(rel, group, what)
            for cfg, monster in table(half.get("slots"), "%s: slots of group %d" % (what, group)).items():
                need(num(monster, 1) and slot_monster.setdefault((group, cfg), monster) == monster,
                     "%s: slot %s of group %d needs ONE monster id" % (what, cfg, group))
            waves = half.get("waves")
            need(isinstance(waves, list) and all(
                isinstance(w, list) and all(isinstance(s, list) and len(s) == 2 and num(s[0], 0) and num(s[1], 0)
                                            for s in w) for w in waves),
                 "%s: waves of group %d must be lists of [config id, times]" % (what, group))
    domains = cat.get("domains")
    need(isinstance(domains, dict), "domains must be an object")
    listed(domains.get("file"), "domains.file")
    listed(domains.get("dropFile"), "domains.dropFile")
    roots = set()
    for did, d in table(domains.get("list"), "domains.list").items():
        what = "domains.list.%s" % did
        need(isinstance(d, dict) and isinstance(d.get("kind"), str) and num(d.get("root"), 1)
             and num(d.get("cost"), 0) and num(d.get("max"), 1) and num(d.get("level"), 0),
             what + ": kind, root, cost, max and level are required")
        need(d["root"] not in roots, "%s: reward row %d belongs to another domain too" % (what, d["root"]))
        roots.add(d["root"])
        preview = d.get("preview", [])
        need(isinstance(preview, list) and all(
            isinstance(p, list) and len(p) == 2 and num(p[0], 0) and isinstance(p[1], (int, float))
            and not isinstance(p[1], bool) for p in preview), what + ": preview must be a list of [item, amount]")
    # (a line-up: the monster group a domain's fight spawns from -- ONE script, shared by nothing of the Abyss)
    in_lineup = set()
    for gid, lineup in table(domains.get("lineups", {}), "domains.lineups").items():
        what, group = "domains.lineups.%s" % gid, int(gid)
        need(group >= 1, what + ": a monster group has a positive id")
        need(isinstance(lineup, dict) and num(lineup.get("level"), 1), what + ": level must be a positive integer")
        need("top" not in lineup or num(lineup["top"], lineup["level"]),
             what + ": top must be an integer, at least the level of the line-up")
        rel = listed(lineup.get("file"), what + ": the script")
        need(group not in group_file and rel not in file_group,
             "%s: group %d and %s do not belong to each other alone" % (what, group, rel))
        named(rel, group, what)
        group_file[group], file_group[rel] = rel, group
        dungeons = lineup.get("dungeons")
        need(isinstance(dungeons, list) and dungeons and all(num(did, 0) for did in dungeons),
             what + ": dungeons must be a non-empty list of dungeon ids")
        for did in dungeons:
            need(str(did) in domains["list"], "%s: dungeon %d is not one of domains.list" % (what, did))
            need(did not in in_lineup, "%s: dungeon %d is listed twice or belongs to another line-up too" % (what, did))
            in_lineup.add(did)
        slots = table(lineup.get("slots"), what + ".slots")
        need(slots and all(num(monster, 1) for monster in slots.values()),
             what + ": slots must name at least one spawn slot, each with a monster id")
        if "waves" in lineup:
            waves = lineup["waves"]
            need(isinstance(waves, list) and waves and all(
                isinstance(w, list) and w and all(isinstance(s, list) and len(s) == 2 and num(s[0], 0) and num(s[1], 1)
                                                  for s in w) for w in waves),
                 what + ": waves must be a non-empty list of waves, each a non-empty list of [config id, times]")
            need(all(str(s[0]) in slots for w in waves for s in w), what + ": a wave names a spawn slot that is not in slots")
    # (the level a domain is listed with is one it can be set to: the range normalise_tweaks enforces holds
    #  the original)
    for did, (low, high) in _tweaks_domain_levels(cat).items():
        need(low <= domains["list"][did]["level"] <= high,
             "domains.list.%s: level %d is outside %d..%d, the levels the top of its line-up allows"
             % (did, domains["list"][did]["level"], low, high))
    for iid, item in table(cat.get("items"), "items").items():
        need(isinstance(item, list) and len(item) == 2 and num(item[0], 0) and num(item[1]) and item[1] in (0, 1),
             "items.%s must be [cap, drop]" % iid)
    quests = cat.get("quests")
    need(isinstance(quests, dict), "quests must be an object")
    listed(quests.get("file"), "quests.file")
    for rid, reward in table(quests.get("rewards"), "quests.rewards").items():
        need(isinstance(reward, dict) and isinstance(reward.get("kind"), str) and nums(reward.get("quests"))
             and num(reward.get("edit")) and reward["edit"] in (0, 1),
             "quests.rewards.%s: kind, quests and edit are required" % rid)
    need(nums(quests.get("keep", [])), "quests.keep must be a list of item ids")
    daily = quests.get("daily")
    need(isinstance(daily, dict) and nums(daily.get("drops")) and nums(daily.get("items")),
         "quests.daily: file, drops and items are required")
    listed(daily.get("file"), "quests.daily.file")
    need(len(set(daily["drops"])) == len(daily["drops"]) and not set(daily["drops"]) & roots,
         "quests.daily.drops: a row is listed twice or is a domain's reward row")
    return True


def read_tweaks_catalog(version):
    """payloads/<version>/tweaks.json -- what the gameplay settings of this version may touch (the files and
    their original md5, the resin row, the Abyss chambers and their spawn slots, the monsters a slot may hold,
    the domains, the spawn slots of their line-ups and what bounds the enemy level of each, the items and
    their caps, the quest reward rows, the items a reward multiplier leaves at their count); None when this
    version ships none. A file that does not parse, does not pass validate_tweaks_catalog or belongs to
    another version reads as none too, with one WARNING per file as found (GET /server/tweaks calls this
    unguarded): every caller gets a catalogue it can walk. Parsed once per file stamp (_tweaks_cached); the
    object is shared -- never change it."""
    path = os.path.join(payload_dir(version), "tweaks.json")
    if not os.path.isfile(path):
        return None

    def load(p):
        try:
            with open(p, "r", encoding="utf-8") as f:
                cat = json.load(f)
            validate_tweaks_catalog(cat)
            if cat["version"] != version:
                raise ValueError("it describes version %s" % cat["version"])
            return cat
        except Exception as e:  # noqa: BLE001 -- a catalogue that cannot be used is no catalogue, never a 500
            log_line("gio-agent: WARNING: %s cannot be used (%s) -- version %s has no gameplay settings."
                     % (p, e, version))
            return None

    return _tweaks_cached("catalogue", path, load, version)


def _tweaks_groups(cat, section):
    """{group id: {"file": path, "slots": {config id: the vendor's monster id}}} of the monster groups the
    catalogue names for `section`: "abyss" -- the groups of the chambers, a group both halves of a chamber
    spawn from being one entry with the slots of both --, "domains" -- the line-ups, none in a catalogue
    without them -- or "all": both, as no group and no script belongs to two (validate_tweaks_catalog). The
    section is always named: the slots of one card are never looked up among the groups of the other."""
    if section != "all" and section not in TWEAK_SLOT_SECTIONS:
        raise ValueError("no monster groups under %r" % (section,))
    out = {}
    if section in ("abyss", "all"):
        for chamber in cat["abyss"]["chambers"].values():
            for half in chamber["halves"]:
                group = out.setdefault(str(half["group"]), {"file": half["file"], "slots": {}})
                group["slots"].update(half["slots"])
    if section in ("domains", "all"):
        for gid, lineup in (cat["domains"].get("lineups") or {}).items():
            out[gid] = {"file": lineup["file"], "slots": dict(lineup["slots"])}
    return out


def _tweaks_domain_levels(cat):
    """{dungeon id: (lowest, highest)} -- the domains whose enemy level can be set and the levels each can be
    set to. The level is the one a domain shows, its enemy-level cell + 1: what an enemy of a spawn slot of
    level 1 stands at. The server adds that cell to the level of EVERY levelled entry of the domain's scene,
    and its growth curves end at the upper end of TWEAK_LIMITS["domainLevel"]: an entry raised past their
    last row -- the object a challenge guards, say -- stands there without health. So the highest level of a
    domain is that end + 1 less the `top` of its line-up, the largest level an entry of its scene carries: a
    spawn slot of the line-up, an object of any of its groups. A domain without a line-up, and one whose
    line-up names no top, is not listed: nothing says how far its scene can be raised. Pure."""
    low, high = TWEAK_LIMITS["domainLevel"]
    return {str(did): (low, high + 1 - lineup["top"])
            for lineup in (cat["domains"].get("lineups") or {}).values() if "top" in lineup
            for did in lineup["dungeons"]}


def _tweaks_level_scripts(cat, doc):
    """The monster-group scripts the enemy levels of a canonical document rest on -- a set of paths: the
    script of every line-up one of whose domains the document gives a level. The range of such a level comes
    from the `top` of the line-up (_tweaks_domain_levels), and `top` was read off the vendor's scripts of the
    scene, the line-up's own among them: a line-up script that is neither that original nor an output of the
    agent -- which leaves the level of every entry as it was -- may place an entry above it, and for such a
    script nothing says how far the scene can be raised. So a document that sets the level needs the script
    as one that changes a slot of it does, although it writes no byte of it. The scene's other scripts are
    not held to it: the agent never writes them and the catalogue pins none of them, so a hand edit of one
    is not seen. A level the document does not set (the one a domain is listed with) needs nothing. Pure."""
    levelled = set(did for did, own in ((doc.get("domains") or {}).get("byId") or {}).items() if "level" in own)
    return set(lineup["file"] for lineup in (cat["domains"].get("lineups") or {}).values()
               if levelled & set(str(did) for did in lineup["dungeons"]))


# -- the editors: bytes in, bytes out, each ends by proving its own result --
# Every one of them works on the file's BASE (the vendor's original, or a base taken over from a change made
# outside Relic) and keeps what the server's loader depends on: UTF-8 without a byte order mark, every line's own
# ending (CRLF in the vendor files), the final line break as it was (the group scripts have none), the same number
# of lines and of TABs per line. Columns are found by header name, rows by the id in their first cell, exactly one
# row per id. Anything else raises and nothing is written.

def _tweak_text(data, name):
    """The bytes of a data file as text: UTF-8 without a byte order mark, as every file the editors know is.
    `name` names the file in a refusal."""
    if data.startswith(b"\xef\xbb\xbf"):
        raise AgentError(500, "%s starts with a byte order mark -- not a file the editor understands, not editing it."
                         % name)
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise AgentError(500, "%s is not valid UTF-8 -- not editing it." % name)


def _tweak_table(data, name):
    """A server table (bytes) taken apart for an edit in place: (lines, line ends, {header name: column}).
    Joining the two lists (_tweak_join) gives the file back byte for byte."""
    text = _tweak_text(data, name)
    pieces = text.split("\n")
    tail = pieces.pop()  # what follows the last line break: "" for a file that ends with one
    lines, ends = [], []
    for piece in pieces:
        cr = piece.endswith("\r")
        lines.append(piece[:-1] if cr else piece)
        ends.append("\r\n" if cr else "\n")
    if tail:
        cr = tail.endswith("\r")
        lines.append(tail[:-1] if cr else tail)
        ends.append("\r" if cr else "")
    if not lines or not lines[0]:
        raise AgentError(500, "%s has no header line -- not editing it." % name)
    cols = {}
    for i, title in enumerate(lines[0].split("\t")):
        cols.setdefault(title, i)
    return lines, ends, cols


def _tweak_join(lines, ends):
    return "".join(line + end for line, end in zip(lines, ends)).encode("utf-8")


def _tweak_column(cols, title, name, what):
    if title not in cols:
        raise AgentError(500, "%s has no column for %s -- not editing it." % (name, what))
    return cols[title]


def _tweak_rows(lines, ids, name):
    """{row id: line number} of the data rows whose first cell is one of `ids` (strings) -- exactly one row
    each, else the file is not the one the catalogue describes."""
    want, found = set(ids), {}
    for n in range(1, len(lines)):
        first = lines[n].split("\t", 1)[0]
        if first in want:
            if first in found:
                raise AgentError(500, "%s holds row %s more than once -- not editing it." % (name, first))
            found[first] = n
    for rid in ids:
        if rid not in found:
            raise AgentError(500, "%s has no row %s -- not editing it." % (name, rid))
    return found


def _tweak_cells(lines, n, name):
    """The cells of data line n, which must be as many as the header's (the server refuses the whole table
    over one short row)."""
    cells = lines[n].split("\t")
    if len(cells) != lines[0].count("\t") + 1:
        raise AgentError(500, "%s: row %s has %d cells where the header has %d -- not editing it."
                         % (name, cells[0], len(cells), lines[0].count("\t") + 1))
    return cells


def _tweak_number(cell, name, what):
    """A cell that must hold a plain unsigned integer (the server trims it the same way)."""
    value = cell.strip()
    if not value.isdigit() or not value.isascii():
        raise AgentError(500, "%s: %s holds %r, not a number -- not editing it." % (name, what, cell))
    return int(value)


def _tweak_proof(old, new, touched, name):
    """What every editor ends with: the result has the lines of the input, every line outside `touched` (line
    numbers) byte for byte, and each touched one with its line end and its number of TABs. Returns `new`."""
    a, b = old.split(b"\n"), new.split(b"\n")
    if len(a) != len(b) or any(
            (x.count(b"\t") != y.count(b"\t") or x.endswith(b"\r") != y.endswith(b"\r")) if n in touched else x != y
            for n, (x, y) in enumerate(zip(a, b))):
        raise AgentError(500, "Editing %s would change more than the cells asked for -- not writing the file." % name)
    return new


def tweak_resin(data, row, cap=None, minutes=None, name="ConstValueData.txt"):
    """ConstValueData.txt (bytes) with the resin row's recovery cap (its third cell) and / or minutes per point
    (its fourth cell) replaced; None keeps a value. The row is the one whose first cell is `row`; its second
    cell, the hard limit no player's resin may pass, stays and must not be below the cap -- the server
    refuses the table otherwise, as it refuses 0 minutes."""
    lines, ends, cols = _tweak_table(data, name)
    row = str(row)
    n = _tweak_rows(lines, [row], name)[row]
    cells = _tweak_cells(lines, n, name)
    c_hard, c_cap, c_minutes = (_tweak_column(cols, _COL_CONST % i, name, "value %d of a row" % i) for i in (1, 2, 3))
    hard = _tweak_number(cells[c_hard], name, "the resin row's hard limit")
    new_cap = _tweak_number(cells[c_cap], name, "the resin row's cap") if cap is None else cap
    new_minutes = _tweak_number(cells[c_minutes], name, "the resin row's minutes per point") if minutes is None \
        else minutes
    if new_cap > hard:
        raise AgentError(400, "tweaks.resin.cap: must not be above %d, the hard limit of resin on this server" % hard)
    if cap is not None:
        cells[c_cap] = str(cap)
    if minutes is not None:
        cells[c_minutes] = str(minutes)
    lines[n] = "\t".join(cells)
    out = _tweak_join(lines, ends)
    again = _tweak_table(out, name)[0][n].split("\t")
    if not (again[0] == row and _tweak_number(again[c_hard], name, "the hard limit") >= int(again[c_cap]) >= 1
            and int(again[c_minutes]) >= 1 and int(again[c_cap]) == new_cap and int(again[c_minutes]) == new_minutes):
        raise AgentError(500, "Editing %s did not give the resin row asked for -- not writing the file." % name)
    return _tweak_proof(data, out, {n}, name)


def _tweak_set_column(data, title, values, name, what):
    """A server table (bytes) with ONE named column set in the rows `values` names ({row id: integer})."""
    lines, ends, cols = _tweak_table(data, name)
    col = _tweak_column(cols, title, name, what)
    values = {str(rid): int(value) for rid, value in values.items()}
    rows = _tweak_rows(lines, sorted(values), name)
    for rid, n in rows.items():
        cells = _tweak_cells(lines, n, name)
        cells[col] = str(values[rid])
        lines[n] = "\t".join(cells)
    out = _tweak_join(lines, ends)
    again = _tweak_table(out, name)[0]
    if any(again[n].split("\t")[col] != str(values[rid]) or again[n].split("\t", 1)[0] != rid
           for rid, n in rows.items()):
        raise AgentError(500, "Editing %s did not give the values asked for -- not writing the file." % name)
    return _tweak_proof(data, out, set(rows.values()), name)


def tweak_abyss_levels(data, levels, name="TowerLevelData.txt"):
    """TowerLevelData.txt (bytes) with the enemy level of the chambers in `levels` ({level id: level}) set --
    the cell the server adds to each spawned monster's own level."""
    return _tweak_set_column(data, _COL_TOWER_LEVEL, levels, name, "the enemy level")


def tweak_domain_costs(data, costs, name="DungeonData.txt"):
    """DungeonData.txt (bytes) with the resin a domain's reward statue takes set for the domains in `costs`
    ({dungeon id: resin}). Never 0: the server could not take the cost and the statue would hand out nothing."""
    return _tweak_set_column(data, _COL_STATUE_COST, costs, name, "the cost of the reward statue")


def tweak_domain_levels(data, cells, name="DungeonData.txt"):
    """DungeonData.txt (bytes) with the enemy-level cell of the domains in `cells` ({dungeon id: cell}) set --
    the cell the server adds to the level of every levelled entry of the domain's scene, a spawn slot as much
    as an object: one less than the level the domain is to show."""
    return _tweak_set_column(data, _COL_DUNGEON_REVISE, cells, name, "the enemy level")


# One entry of a monster-group script's `monsters` table, as every script the catalogue lists writes it: one
# entry per line, the fields in this order -- those after the level only where an entry carries them,
# vision_level the last of them --, a comma after every entry but the last.
_TWEAK_SLOT_RE = re.compile(
    rb"^(?P<ind>[ \t]*)\{ config_id = (?P<cfg>\d+), monster_id = (?P<mid>\d+), "
    rb"pos = \{ x = [-0-9.]+, y = [-0-9.]+, z = [-0-9.]+ \}, rot = \{ x = [-0-9.]+, y = [-0-9.]+, z = [-0-9.]+ \}, "
    rb"level = (?P<lvl>\d+)"
    rb"(?P<wander>, disableWander = true)?"
    rb"(?:, affix = \{ (?P<affix>\d+(?:, \d+)*) \})?"
    rb"(?P<elite>, isElite = true)?"
    rb"(?:, pose_id = (?P<pose>\d+))?"
    rb"(?P<vision>, vision_level = VisionLevelType\.[A-Z][A-Z0-9_]*)?"
    rb" \}(?P<comma>,?)(?P<eol>\r?)\Z")


def _tweak_slot_lines(data, name):
    """[(offset, length, match)] of the entries between `monsters = {` and its closing brace at column 0 of a
    group script (bytes). A designer's comment line between two entries is fine; any other line the strict
    entry pattern does not cover means this is not a script the editor understands."""
    _tweak_text(data, name)
    start = re.search(rb"(?m)^monsters = \{\r?\n", data)
    end = re.compile(rb"(?m)^\}").search(data, start.end()) if start else None
    if not start or not end:
        raise AgentError(500, "%s has no monsters table the editor understands -- not editing it." % name)
    out, pos = [], start.end()
    for line in data[start.end():end.start()].split(b"\n"):
        if line.strip() and not line.strip().startswith(b"--"):
            m = _TWEAK_SLOT_RE.match(line)
            if not m:
                raise AgentError(500, "%s: a line of the monsters table is not a plain entry -- not editing it." % name)
            out.append((pos, len(line), m))
        pos += len(line) + 1
    return out


def tweak_group_slots(data, slots, monsters, generic, name="the group script"):
    """One monster-group script (bytes) -- any the catalogue lists -- with the monster of the spawn slots in
    `slots` ({config id: monster id}) replaced. What belongs to the MONSTER follows it: pose_id becomes the new
    monster's catalogue `pose` (removed when it has none) and affix = the slot's affixes that are in `generic`
    (not tied to one monster family) plus the new monster's catalogue `affix` -- the field removed when that
    list is empty. What belongs to the SLOT stays: its config id (the scripts' triggers and kill counts name
    it), position, rotation, level (whatever it is), disableWander, isElite and the trailing vision_level of an
    entry that carries one, byte for byte. A slot asked to hold the monster it already holds is left as it is.
    Every other byte of the file is identical; `monsters` is the catalogue's monsters object."""
    entries = _tweak_slot_lines(data, name)
    by_cfg = {}
    for entry in entries:
        by_cfg.setdefault(int(entry[2].group("cfg")), []).append(entry)
    generic, edits, wanted = set(generic), [], {}
    for cfg, monster in slots.items():
        hits = by_cfg.get(int(cfg)) or []
        if len(hits) != 1:
            raise AgentError(500, "%s holds spawn slot %s %d times -- not editing it." % (name, cfg, len(hits)))
        pos, length, m = hits[0]
        wanted[int(cfg)] = int(monster)
        if int(m.group("mid")) == int(monster):
            continue
        info = monsters.get(str(monster))
        if not isinstance(info, dict):
            raise AgentError(400, "tweaks: monster %s cannot be placed in a spawn slot" % monster)
        line = data[pos:pos + length]
        head_end = m.end("wander") if m.group("wander") else m.end("lvl")
        head = line[:m.start("mid")] + str(int(monster)).encode() + line[m.end("mid"):head_end]
        affix = [a for a in (int(x) for x in m.group("affix").split(b", ")) if a in generic] if m.group("affix") else []
        affix += [a for a in info.get("affix") or [] if a not in affix]
        tail = b""
        if affix:
            tail += b", affix = { " + b", ".join(str(a).encode() for a in affix) + b" }"
        if m.group("elite"):
            tail += b", isElite = true"
        if info.get("pose") is not None:
            tail += b", pose_id = " + str(info["pose"]).encode()
        tail += m.group("vision") or b""
        new_line = head + tail + b" }" + m.group("comma") + m.group("eol")
        if not _TWEAK_SLOT_RE.match(new_line):
            raise AgentError(500, "%s: the rewritten entry of slot %s is not a plain entry -- not writing the file."
                             % (name, cfg))
        edits.append((pos, length, new_line))
    out = data
    for pos, length, new_line in sorted(edits, reverse=True):
        out = out[:pos] + new_line + out[pos + length:]
    # proof: the same lines but the rewritten entries, the same slots in the same order, each holding what was asked
    a, b = data.split(b"\n"), out.split(b"\n")
    changed = [n for n, (x, y) in enumerate(zip(a, b)) if x != y]
    after = [(int(e[2].group("cfg")), int(e[2].group("mid"))) for e in _tweak_slot_lines(out, name)]
    if (len(a) != len(b) or len(changed) != len(edits) or out.count(b"\r\n") != data.count(b"\r\n")
            or [c for c, _m in after] != [int(e[2].group("cfg")) for e in entries]
            or any(mid != wanted[cfg] for cfg, mid in after if cfg in wanted)):
        raise AgentError(500, "Editing %s would change more than the slots asked for -- not writing the file." % name)
    return out


def _tweak_scale_count(cell, m, name):
    """A count cell of a drop row times the integer m, in the server's own syntax: "N" -> N*m; "A;B" (a range)
    -> both ends; "N.F" (N, or N + 1 with the chance .F) -> the product with at most four decimals, no trailing
    zero -- and no "." at all when it is whole: a "." alone makes the server read max = min + 1."""
    if re.fullmatch(r"[0-9]+", cell):
        return str(int(cell) * m)
    if re.fullmatch(r"[0-9]+;[0-9]+", cell):
        low, high = cell.split(";")
        return "%d;%d" % (int(low) * m, int(high) * m)
    frac = re.fullmatch(r"([0-9]*)\.([0-9]+)", cell)
    if not frac:
        raise AgentError(500, "%s: a count cell holds %r -- not editing it." % (name, cell))
    digits = len(frac.group(2))
    scaled = int((frac.group(1) or "0") + frac.group(2)) * m  # in units of 10 ** -digits
    if digits > 4:
        scaled, rest = divmod(scaled, 10 ** (digits - 4))
        scaled += 1 if 2 * rest >= 10 ** (digits - 4) else 0
        digits = 4
    whole, part = divmod(scaled, 10 ** digits)
    return str(whole) if part == 0 else "%d.%s" % (whole, ("%0*d" % (digits, part)).rstrip("0"))


def _tweak_count_max(cell, name):
    """The largest count a cell can give -- what the server's caps are checked against."""
    if re.fullmatch(r"[0-9]+(?:;[0-9]+)?", cell):
        return int(cell.split(";")[-1])
    if re.fullmatch(r"[0-9]*\.[0-9]+", cell):
        return int(cell.split(".")[0] or "0") + 1
    raise AgentError(500, "%s: a count cell holds %r -- not editing it." % (name, cell))


def _tweak_drop_children(cols, name):
    """[(id column, count column, weight column)] of the child slots a drop table has, 1 upwards."""
    out = []
    while all((title % (len(out) + 1)) in cols for title in (_COL_DROP_ID, _COL_DROP_COUNT, _COL_DROP_WEIGHT)):
        k = len(out) + 1
        out.append((cols[_COL_DROP_ID % k], cols[_COL_DROP_COUNT % k], cols[_COL_DROP_WEIGHT % k]))
    if not out:
        raise AgentError(500, "%s has no child columns -- not editing it." % name)
    return out


def tweak_drops(data, roots, daily, items, name="DropTreeData.txt"):
    """DropTreeData.txt (bytes) with the reward rows of domains and of the daily commissions changed ->
    (bytes, the number of cells a server cap limited).
    roots: {row id: (multiplier, [(item, count)], label)} -- the row a domain's reward statue rolls. Every child
    in use gets its count times the multiplier (_tweak_scale_count); then each extra item takes the lowest free
    child slot with its exact count and the weight 10000 (always dropped). Refused (400, `label` = the
    document path of that domain): an extra item that already is a direct child of the row, more extra items
    than free slots.
    daily: None or (row ids, item ids, multiplier) -- the rows of the daily commissions: the count of the
    children whose id is one of the item ids times the multiplier, never above the item's cap.
    items: the catalogue's {item id: [cap, drop]}."""
    lines, ends, cols = _tweak_table(data, name)
    children = _tweak_drop_children(cols, name)
    daily_rows, daily_items, daily_mult = daily or ((), (), 1)
    daily_items = set(str(i) for i in daily_items)
    rows = _tweak_rows(lines, [str(r) for r in roots] + [str(r) for r in daily_rows], name)
    touched, clamped = set(), 0

    def cap_of(item):
        entry = items.get(item)
        return entry[0] if entry else None

    for rid, (mult, extra, label) in roots.items():
        n = rows[str(rid)]
        cells = _tweak_cells(lines, n, name)
        if mult != 1:
            for c_id, c_count, c_weight in children:
                if cells[c_id] not in ("", "0") and cells[c_weight] not in ("", "0"):
                    cells[c_count] = _tweak_scale_count(cells[c_count], mult, name)
        present = set(cells[c[0]] for c in children) - {"", "0"}
        free = [c for c in children if cells[c[0]] in ("", "0")]
        if len(extra) > len(free):
            raise AgentError(400, "tweaks%s.extra: this domain's reward has room for %d more items"
                             % (label, len(free)))
        for (item, count), (c_id, c_count, c_weight) in zip(extra, free):
            if str(item) in present:
                raise AgentError(400, "tweaks%s.extra: item %s already is part of this domain's reward" % (label, item))
            present.add(str(item))
            cells[c_id], cells[c_count], cells[c_weight] = str(item), str(count), "10000"
        for c_id, c_count, c_weight in children:  # proof: no item child above the cap the server checks
            cap = cap_of(cells[c_id])
            if cap is not None and cells[c_weight] not in ("", "0") and _tweak_count_max(cells[c_count], name) > cap:
                raise AgentError(500, "%s: row %s would hand out more of item %s than the server accepts -- not "
                                      "writing the file." % (name, rid, cells[c_id]))
        lines[n] = "\t".join(cells)
        touched.add(n)
    for rid in daily_rows:
        n = rows[str(rid)]
        cells = _tweak_cells(lines, n, name)
        for c_id, c_count, c_weight in children:
            if cells[c_id] not in daily_items or cells[c_weight] in ("", "0") or daily_mult == 1:
                continue
            cap, before = cap_of(cells[c_id]), _tweak_count_max(cells[c_count], name)
            scaled = _tweak_scale_count(cells[c_count], daily_mult, name)
            if cap is None:
                clamped += 1  # an item the catalogue has no cap for keeps its count
            elif _tweak_count_max(scaled, name) <= cap:
                cells[c_count] = scaled
            else:
                clamped += 1
                cells[c_count] = str(max(cap, before)) if ";" not in scaled else \
                    ";".join(str(min(int(x), max(cap, before))) for x in scaled.split(";"))
        lines[n] = "\t".join(cells)
        touched.add(n)
    return _tweak_proof(data, _tweak_join(lines, ends), touched, name), clamped


def _tweak_reward_layout(cols, name):
    """([(column, virtual item id)] of the six scalar cells, [(id column, count column)] of the item slots)
    of a reward table."""
    scalars = [(_tweak_column(cols, title, name, "a reward's own currency or EXP"), item)
               for title, item in TWEAK_REWARD_SCALARS]
    slots = []
    while (_COL_REWARD_ID % (len(slots) + 1)) in cols and (_COL_REWARD_COUNT % (len(slots) + 1)) in cols:
        k = len(slots) + 1
        slots.append((cols[_COL_REWARD_ID % k], cols[_COL_REWARD_COUNT % k]))
    if not slots:
        raise AgentError(500, "%s has no item slots -- not editing it." % name)
    return scalars, slots


def _tweak_reward_cells(cells, scalars, slots, name):
    """[(count column, item id, count)] of what a reward row hands out, the scalar cells first, then the item
    slots in use (id neither empty nor 0). A slot in use needs a count of at least 1 and an item no other slot
    of the row holds -- the server refuses the table otherwise."""
    out, seen = [], set()
    for col, item in scalars:
        if cells[col].strip() not in ("", "0"):
            out.append((col, item, _tweak_number(cells[col], name, "a cell of reward %s" % cells[0])))
    for c_id, c_count in slots:
        if cells[c_id].strip() in ("", "0"):
            continue
        item = _tweak_number(cells[c_id], name, "an item id of reward %s" % cells[0])
        count = _tweak_number(cells[c_count], name, "a count of reward %s" % cells[0])
        if count < 1 or item in seen:
            raise AgentError(500, "%s: reward %s holds item %d twice or without a count -- not editing it."
                             % (name, cells[0], item))
        seen.add(item)
        out.append((c_count, item, count))
    return out


def _tweak_reward_content(cells, scalars, slots, name):
    """{item id: count} of what a reward row hands out, as the server builds it: a scalar cell and an item slot
    that hold the same virtual item add up. None for a row _tweak_reward_cells does not read."""
    try:
        used = _tweak_reward_cells(cells, scalars, slots, name)
    except AgentError:
        return None
    content = {}
    for _col, item, count in used:
        content[item] = content.get(item, 0) + count
    return content


def tweak_rewards(data, multiplied, custom, items, name="RewardData.txt", keep=()):
    """RewardData.txt (bytes) with quest reward rows multiplied or replaced -> (bytes, the number of cells a
    server cap limited).
    multiplied: {row id: multiplier}. The six scalar cells and the count of every item slot in use are
    multiplied; what one item adds up to in the row (the server adds a scalar and a slot that hold the same
    virtual item) never passes the item's cap, no cell ever goes below its original count, and an item the
    catalogue has no cap for keeps its count. So does an item in `keep` -- a character, a constellation item:
    more of it is not "more reward" -- and that is no cell a cap limited. Ids, the source type and the three
    limit cells are not touched.
    custom: {row id: [(item, count)]}, the complete reward of that row: a virtual item goes into its scalar
    cell, the others into the item slots 1..n in the order given, every other scalar and slot cell is emptied.
    A custom row is exact -- it wins over a multiplier of the same row, and it may name an item in `keep`. A
    row that hands out exactly that already (the same items, each with the same count in all) is left as it
    is, byte for byte.
    items: the catalogue's {item id: [cap, drop]}; keep: the catalogue's item ids a multiplier leaves alone."""
    lines, ends, cols = _tweak_table(data, name)
    scalars, slots = _tweak_reward_layout(cols, name)
    custom = {str(rid): list(entries) for rid, entries in custom.items()}
    multiplied = {str(rid): m for rid, m in multiplied.items() if str(rid) not in custom}
    rows = _tweak_rows(lines, sorted(multiplied) + sorted(custom), name)
    virtual = dict((item, col) for col, item in scalars)
    keep, touched, clamped, limits = set(keep), set(), 0, {}
    for rid, mult in multiplied.items():
        n = rows[rid]
        cells = _tweak_cells(lines, n, name)
        used = _tweak_reward_cells(cells, scalars, slots, name)
        total, room = {}, {}
        for _col, item, count in used:
            total[item] = total.get(item, 0) + count
        for item, count in total.items():
            cap = items.get(str(item))
            # what the item's cells may add up to
            room[item] = count if cap is None or item in keep else max(cap[0], count)
        limits[rid] = (dict(total), dict(room))
        for col, item, count in used:
            total[item] -= count  # the original counts of this item's cells still to come
            new = min(count * mult, room[item] - total[item])
            room[item] -= new
            clamped += 1 if new < count * mult and item not in keep else 0
            cells[col] = str(new)
        lines[n] = "\t".join(cells)
        touched.add(n)
    for rid, entries in custom.items():
        n = rows[rid]
        cells = _tweak_cells(lines, n, name)
        others = [(item, count) for item, count in entries if item not in virtual]
        if len(others) > len(slots) or len(set(item for item, _c in entries)) != len(entries) or not entries:
            raise AgentError(400, "tweaks.quests.byReward.%s.items: 1 to %d different items besides the currencies "
                                  "and EXP" % (rid, len(slots)))
        given = dict(entries)
        if _tweak_reward_content(cells, scalars, slots, name) == given:
            continue  # the row hands out exactly this as it is: not a byte of it changes
        for col, item in scalars:
            cells[col] = str(given[item]) if item in given else ""
        for k, (c_id, c_count) in enumerate(slots):
            cells[c_id], cells[c_count] = (str(others[k][0]), str(others[k][1])) if k < len(others) else ("", "")
        lines[n] = "\t".join(cells)
        touched.add(n)
    out = _tweak_join(lines, ends)
    # proof: read the rows back the way the server will -- a custom row hands out exactly what was asked, a
    # multiplied one at least its original and at most what the caps allow
    again = _tweak_table(out, name)[0]
    for rid, n in rows.items():
        got = {}
        for _col, item, count in _tweak_reward_cells(again[n].split("\t"), scalars, slots, name):
            got[item] = got.get(item, 0) + count
        if rid in custom:
            good = got == dict(custom[rid])
        else:
            total, room = limits[rid]
            good = set(got) == set(total) and all(total[i] <= got[i] <= room[i] for i in got)
        if not good or again[n].split("\t", 1)[0] != rid:
            raise AgentError(500, "Editing %s did not give the reward asked for in row %s -- not writing the file."
                             % (name, rid))
    return _tweak_proof(data, out, touched, name), clamped


# -- what a base holds: the values a document is compared with --
# A document names what CHANGES: a value equal to the one the file's base already holds is no change, and the
# editors write a cost or an enemy level only where it differs from the base's. While every base is the
# vendor's original those values are the catalogue's; a file whose base was adopted (tweaks_take_over) is read
# for them.

def _tweaks_read_facts(cat, groups, rel, data):
    """What the BASE of one target file (bytes) holds of the values the documents are compared with, read the
    way the editors read it -- and the proof that it is a file they can edit and the server's own rules accept
    (AgentError otherwise): every row, column and spawn slot the catalogue names is there once, every value the
    editors read is a number, the resin row's hard limit is not below its cap, cap and minutes are at least 1,
    the count of every child in use of a domain's reward row and of a daily row parses, every quest reward row
    reads as one. `groups` = _tweaks_groups(cat, "all"). Returns {"resin": {cap, minutes, hardMax}} of the
    constant table, {"levels": {chamber: enemy level}} of the chamber table, {"slots": {group: {slot:
    monster}}, "maxLevel": {group: the largest level of an entry}} of a monster-group script, {"costs":
    {domain: statue cost}, "domainLevels": {domain: enemy-level cell + 1}} of the dungeon table (the cell only
    of a domain whose level can be set), {"free", "own"} of the drop table and {"rewards": {row: [[item,
    count]]}} of the reward table -- what GET /server/tweaks reads out of those two. Pure."""
    name, facts = rel.rsplit("/", 1)[-1], {}

    def column(title, ids, what):
        lines, _ends, cols = _tweak_table(data, name)
        col = _tweak_column(cols, title, name, what)
        return {rid: _tweak_number(_tweak_cells(lines, n, name)[col], name, "%s of row %s" % (what, rid))
                for rid, n in _tweak_rows(lines, sorted(ids), name).items()}

    if rel == cat["resin"]["file"]:
        row = cat["resin"]["row"]
        lines, _ends, cols = _tweak_table(data, name)
        cells = _tweak_cells(lines, _tweak_rows(lines, [row], name)[row], name)
        hard, cap, minutes = (_tweak_number(cells[_tweak_column(cols, _COL_CONST % i, name, "value %d of a row" % i)],
                                            name, "value %d of the resin row" % i) for i in (1, 2, 3))
        if not hard >= cap >= 1 or minutes < 1:
            raise AgentError(500, "%s: the resin row holds a cap of %d, a hard limit of %d and %d minutes per point "
                                  "-- the server refuses that." % (name, cap, hard, minutes))
        facts["resin"] = {"cap": cap, "minutes": minutes, "hardMax": hard}
    if rel == cat["abyss"]["levelFile"]:
        facts["levels"] = column(_COL_TOWER_LEVEL, cat["abyss"]["chambers"], "the enemy level")
    for gid, group in groups.items():
        if group["file"] == rel:
            have, levels = {}, []
            for entry in _tweak_slot_lines(data, name):
                have.setdefault(entry[2].group("cfg").decode(), []).append(int(entry[2].group("mid")))
                levels.append(int(entry[2].group("lvl")))
            for cfg in group["slots"]:
                if len(have.get(cfg) or []) != 1:
                    raise AgentError(500, "%s: spawn slot %s is not there once." % (name, cfg))
            facts.setdefault("slots", {})[gid] = {cfg: have[cfg][0] for cfg in group["slots"]}
            facts.setdefault("maxLevel", {})[gid] = max(levels or [0])
    if rel == cat["domains"]["file"]:
        facts["costs"] = column(_COL_STATUE_COST, cat["domains"]["list"], "the cost of the reward statue")
        settable = _tweaks_domain_levels(cat)
        facts["domainLevels"] = {did: cell + 1 for did, cell in
                                 column(_COL_DUNGEON_REVISE, settable, "the enemy level").items()} if settable else {}
    daily = cat["quests"]["daily"]
    if rel in (cat["domains"]["dropFile"], daily["file"]):
        lines, _ends, cols = _tweak_table(data, name)
        children = _tweak_drop_children(cols, name)
        roots = [str(d["root"]) for d in cat["domains"]["list"].values()] if rel == cat["domains"]["dropFile"] else []
        drops = [str(r) for r in daily["drops"]] if rel == daily["file"] else []
        rows = _tweak_rows(lines, roots + drops, name)
        for rid in roots + drops:
            cells = _tweak_cells(lines, rows[rid], name)
            for c_id, c_count, c_weight in children:
                if cells[c_id] not in ("", "0") and cells[c_weight] not in ("", "0"):
                    _tweak_count_max(cells[c_count], name)
        if rel == cat["domains"]["dropFile"]:
            facts["free"], facts["own"] = {}, {}
            for root in roots:
                cells = lines[rows[root]].split("\t")
                facts["free"][root] = sum(1 for c in children if cells[c[0]] in ("", "0"))
                # (a child that is an item, not another drop row: what tweak_drops refuses as an extra item)
                facts["own"][root] = sorted(set(int(cells[c[0]]) for c in children if cells[c[0]] in cat["items"]))
    if rel == cat["quests"]["file"]:
        lines, _ends, cols = _tweak_table(data, name)
        scalars, slots = _tweak_reward_layout(cols, name)
        rows = _tweak_rows(lines, sorted(cat["quests"]["rewards"]), name)
        facts["rewards"] = {rid: [[item, count] for _col, item, count in
                                  _tweak_reward_cells(_tweak_cells(lines, n, name), scalars, slots, name)]
                            for rid, n in rows.items()}
    return facts


def tweaks_facts(cat, bases=None):
    """The values a document is compared with, and the editors edit against -- per kind: {"resin": {"cap",
    "minutes", "hardMax"}, "levels": {chamber: enemy level}, "slots": {group: {slot: monster}}, "costs":
    {domain: statue cost}, "domainLevels": {domain: level}, "maxLevel": {line-up group: the largest level an
    entry of its script carries}}: the catalogue's original values, with each file of `bases` ({path: bytes |
    None} -- the files whose base is not the vendor's original) read in its place (_tweaks_read_facts). A file
    whose bytes are None, or cannot be read, has None for every value of it: the base of that file is not
    known, nothing of it is "no change", its ranges are the catalogue's. Pure."""
    groups = _tweaks_groups(cat, "all")
    lineups = cat["domains"].get("lineups") or {}
    facts = {"resin": {k: cat["resin"][k] for k in ("cap", "minutes", "hardMax")},
             "levels": {lid: c["level"] for lid, c in cat["abyss"]["chambers"].items()},
             "slots": {gid: dict(group["slots"]) for gid, group in groups.items()},
             "costs": {did: d["cost"] for did, d in cat["domains"]["list"].items()},
             "domainLevels": {did: d["level"] for did, d in cat["domains"]["list"].items()},
             "maxLevel": {gid: lineup["level"] for gid, lineup in lineups.items()}}
    for rel, data in sorted((bases or {}).items()):
        read = None
        if data is not None:
            try:
                read = _tweaks_read_facts(cat, groups, rel, data)
            except Exception:  # noqa: BLE001 -- a base that cannot be read is one whose values are not known
                read = None
        _tweaks_put_facts(cat, groups, facts, rel, read)
    return facts


def _tweaks_facts_with(cat, groups, facts, rel, read):
    """`facts` (tweaks_facts) with the values of ONE file replaced by what _tweaks_read_facts read off its base
    (`read`; None = not known: None for each of its values) -- a new object, `facts` untouched. Pure."""
    facts = dict((kind, dict(values)) for kind, values in facts.items())
    facts["slots"] = dict((gid, dict(slots)) for gid, slots in facts["slots"].items())
    return _tweaks_put_facts(cat, groups, facts, rel, read)


def _tweaks_put_facts(cat, groups, facts, rel, read):
    """_tweaks_facts_with in place: `facts` itself changed and returned."""
    if rel == cat["resin"]["file"]:
        facts["resin"] = dict(read["resin"]) if read else dict.fromkeys(facts["resin"])
    if rel == cat["abyss"]["levelFile"]:
        facts["levels"] = dict(read["levels"]) if read else dict.fromkeys(facts["levels"])
    for gid, group in groups.items():
        if group["file"] == rel:
            facts["slots"][gid] = dict(read["slots"][gid]) if read else dict.fromkeys(group["slots"])
            if gid in (cat["domains"].get("lineups") or {}):
                facts["maxLevel"][gid] = read["maxLevel"][gid] if read else None
    if rel == cat["domains"]["file"]:
        facts["costs"] = dict(read["costs"]) if read else dict.fromkeys(facts["costs"])
        facts["domainLevels"] = dict.fromkeys(facts["domainLevels"])
        facts["domainLevels"].update(read["domainLevels"] if read else {})
    return facts


def tweaks_unknown_facts(cat):
    """tweaks_facts of a stack whose bases are not known -- what the synchronous half of POST /server/tweaks
    checks a document against: nothing that could be the value of a base is dropped as "no change" (the job
    decides that against the stack's own bases), every range is the catalogue's (normalise_tweaks with unread:
    a domain's own cost held to its type alone). Pure."""
    facts = tweaks_facts(cat)
    return dict((kind, dict((key, dict.fromkeys(value) if kind == "slots" else None) for key, value in values.items()))
                for kind, values in facts.items())


# -- the document --

def _tweaks_sorted(value):
    """A document with the keys of every object in sorted order; a list keeps its own (it is the order the
    items of a reward are written in)."""
    if isinstance(value, dict):
        return {k: _tweaks_sorted(value[k]) for k in sorted(value)}
    if isinstance(value, list):
        return [_tweaks_sorted(v) for v in value]
    return value


def normalise_tweaks(cat, doc, base=None, unread=False):
    """A gameplay-settings document checked against the catalogue and returned in its canonical form: what the
    agent stores, compares and answers. Every section and every key is optional; an absent key is the value the
    file's base holds. `base` = what the bases of the stack hold (tweaks_facts; None = the catalogue's: every
    base is the vendor's original). unread: the bases were not read at all (the synchronous half of POST
    /server/tweaks, with tweaks_unknown_facts): a domain's own statue cost is held to its type alone (an integer,
    not below 0) -- the one value a canonical document states where it equals its base (a domain kept at its own
    cost while the cost for all domains is another one), which a take-over may have put outside the range (a
    domain made free by hand); the job holds it to the bases. Every other value keeps the catalogue's range there:
    a canonical document drops a value its base holds.
    Refused (AgentError 400 whose text names the path,
    `tweaks.abyss.slots.<group>.<slot>: ...`): an unknown key, a value that is not an integer (a bool, a float
    and a string of digits are none), a value that changes something and is outside its range (TWEAK_LIMITS --
    the cap of resin up to the base's hard limit; for `domains.byId.<id>.level`, the level that domain is to
    show, the levels _tweaks_domain_levels gives it), an id the catalogue does not list -- a monster group
    (`abyss.slots` knows the groups of the Abyss, `domains.slots` the line-ups of the domains, neither the
    other's), a spawn slot of it, a monster (one the catalogue lets a slot hold, or the one the base holds
    there), a chamber, a domain, an item (for a domain's extra items only one that may be a direct child of a
    reward row), a quest reward row that is not one quest's own --, the level of a domain whose enemy level
    cannot be set (it has no line-up, or its line-up names no top: whatever the value), a count above the
    item's cap, an item twice in one list, a list that is too long. Canonical: what changes nothing is left out
    (a value equal to the base's -- compared FIRST, before any range: a base a hand put outside the range must
    not make a document that merely states it a 400 --, a multiplier of 1, a domain's own multiplier or cost
    equal to what it gets anyway, an empty list or object, a section left empty by that) and keys are sorted. A
    value of a base that is not known (None in `base`) is never "no change". A custom reward that names what
    its row hands out anyway stays in the document -- only the row itself can tell -- and changes no byte of
    the file (tweak_rewards). Pure."""
    lim, virtual = TWEAK_LIMITS, set(item for _title, item in TWEAK_REWARD_SCALARS)
    base = tweaks_facts(cat) if base is None else base

    def bad(path, why):
        raise AgentError(400, "tweaks%s: %s" % (path, why))

    def obj(value, path, keys=None):
        if not isinstance(value, dict):
            bad(path, "must be an object")
        for k in value:
            if not isinstance(k, str) or (keys is not None and k not in keys):
                bad("%s.%s" % (path, k), "unknown key")
        return value

    def integer(value, path, low, high):
        if isinstance(value, bool) or not isinstance(value, int) or not low <= value <= high:
            bad(path, "must be an integer between %d and %d" % (low, high))
        return value

    def typed(value, path, low, high):
        # a value a base the job has not read yet may hold: its type alone
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            bad(path, "must be an integer between %d and %d" % (low, high))
        return value

    def change(value, path, low, high, held):
        # a value the base may hold: the integer itself when it changes something (None: it equals what the
        # base holds -- `held`, None when that is not known), checked against the range only then
        if isinstance(value, bool) or not isinstance(value, int):
            bad(path, "must be an integer between %d and %d" % (low, high))
        if held is not None and value == held:
            return None
        return integer(value, path, low, high)

    def item_list(value, path, most, drop_only):
        if not isinstance(value, list):
            bad(path, "must be a list")
        if len(value) > most:
            bad(path, "at most %d items" % most)
        seen, entries = set(), []
        for i, entry in enumerate(value):
            at = "%s.%d" % (path, i)
            obj(entry, at, ("item", "count"))
            if "item" not in entry or "count" not in entry:
                bad(at, "needs item and count")
            item = entry["item"]
            info = None if isinstance(item, bool) or not isinstance(item, int) else cat["items"].get(str(item))
            if info is None:
                bad(at + ".item", "unknown item")
            if info[0] < 1 or (drop_only and info[1] != 1):
                bad(at + ".item", "item %d cannot be given here" % item)
            if item in seen:
                bad(at + ".item", "item %d is listed twice" % item)
            seen.add(item)
            entries.append({"item": item, "count": integer(entry["count"], at + ".count", 1, info[0])})
        return entries

    def slot_edits(value, path, section):
        # {group: {slot: monster}} of one card: only the monster groups of THAT section (an Abyss group under
        # domains.slots, a line-up under abyss.slots, is an unknown monster group), their listed slots, the
        # catalogue's monsters -- or the one the base holds in the slot (the catalogue's own while the base is not
        # known); a slot asked to hold the monster the base holds changes nothing
        groups, slots = _tweaks_groups(cat, section), {}
        for gid, entries in obj(value, path).items():
            at = "%s.%s" % (path, gid)
            if gid not in groups:
                bad(at, "unknown monster group")
            kept = {}
            for cfg, monster in obj(entries, at).items():
                if cfg not in groups[gid]["slots"]:
                    bad("%s.%s" % (at, cfg), "unknown spawn slot")
                held = (base["slots"].get(gid) or {}).get(cfg)
                if isinstance(monster, bool) or not isinstance(monster, int) or (
                        monster != (groups[gid]["slots"][cfg] if held is None else held)
                        and str(monster) not in cat["monsters"]):
                    bad("%s.%s" % (at, cfg), "must be the id of a monster a spawn slot can hold")
                if held is None or monster != held:
                    kept[cfg] = monster
            if kept:
                slots[gid] = kept
        return slots

    obj(doc, "", TWEAK_SECTIONS)
    out = {}
    if "resin" in doc:
        sec, cur, resin = obj(doc["resin"], ".resin", ("cap", "minutes")), base["resin"], {}
        hard = cat["resin"]["hardMax"] if cur["hardMax"] is None else cur["hardMax"]
        if "cap" in sec and change(sec["cap"], ".resin.cap", lim["resinCap"][0], min(lim["resinCap"][1], hard),
                                   cur["cap"]) is not None:
            resin["cap"] = sec["cap"]
        if "minutes" in sec and change(sec["minutes"], ".resin.minutes", lim["minutes"][0], lim["minutes"][1],
                                       cur["minutes"]) is not None:
            resin["minutes"] = sec["minutes"]
        if resin:
            out["resin"] = resin
    if "abyss" in doc:
        sec, abyss = obj(doc["abyss"], ".abyss", ("slots", "levels")), {}
        if "slots" in sec:
            slots = slot_edits(sec["slots"], ".abyss.slots", "abyss")
            if slots:
                abyss["slots"] = slots
        if "levels" in sec:
            chambers, levels = cat["abyss"]["chambers"], {}
            for lid, level in obj(sec["levels"], ".abyss.levels").items():
                if lid not in chambers:
                    bad(".abyss.levels.%s" % lid, "unknown chamber")
                if change(level, ".abyss.levels.%s" % lid, lim["level"][0], lim["level"][1],
                          base["levels"].get(lid)) is not None:
                    levels[lid] = level
            if levels:
                abyss["levels"] = levels
        if abyss:
            out["abyss"] = abyss
    if "domains" in doc:
        sec, listed, dom = obj(doc["domains"], ".domains", ("multiplier", "cost", "byId", "slots")), cat["domains"]["list"], {}
        if "multiplier" in sec and integer(sec["multiplier"], ".domains.multiplier", 1, lim["multiplierMax"]) != 1:
            dom["multiplier"] = sec["multiplier"]
        if "cost" in sec:
            # (no change only when every domain's base holds that cost already)
            held = sec["cost"] if all(base["costs"].get(did) == sec["cost"] for did in listed) else None
            if change(sec["cost"], ".domains.cost", lim["cost"][0], lim["cost"][1], held) is not None:
                dom["cost"] = sec["cost"]
        if "byId" in sec:
            by, levels = {}, _tweaks_domain_levels(cat)
            for did, own in obj(sec["byId"], ".domains.byId").items():
                at = ".domains.byId.%s" % did
                if did not in listed:
                    bad(at, "unknown domain")
                d, entry = listed[did], {}
                obj(own, at, ("multiplier", "cost", "level", "extra"))
                most = min(lim["multiplierMax"], d["max"])
                if "multiplier" in own and integer(own["multiplier"], at + ".multiplier", 1, most) \
                        != min(dom.get("multiplier", 1), most):
                    entry["multiplier"] = own["multiplier"]
                # (what the domain costs anyway: the cost for all domains, else what its base holds -- and a cost
                #  equal to what its base holds while the cost for all domains is another one is what keeps the
                #  domain as its base has it: kept, a value of the base, whatever the range)
                if "cost" in own:
                    held = base["costs"].get(did)
                    anyway = dom.get("cost", held)
                    value = own["cost"]
                    if unread and held is None:
                        if typed(value, at + ".cost", lim["cost"][0], lim["cost"][1]) != anyway:
                            entry["cost"] = value
                    elif held is not None and not isinstance(value, bool) and isinstance(value, int) \
                            and value == held and value != anyway:
                        entry["cost"] = value
                    elif change(value, at + ".cost", lim["cost"][0], lim["cost"][1], anyway) is not None:
                        entry["cost"] = value
                if "level" in own:
                    # (the level the domain is to show: taken only where the domain has a range of its own, and
                    #  left out when it is the one its base holds -- no level for all domains exists that it
                    #  could set the domain apart from)
                    if did not in levels:
                        bad(at + ".level", "the enemy level of this domain cannot be set")
                    if change(own["level"], at + ".level", levels[did][0], levels[did][1],
                              base["domainLevels"].get(did)) is not None:
                        entry["level"] = own["level"]
                if "extra" in own:
                    extra = item_list(own["extra"], at + ".extra", lim["extraMax"], True)
                    if extra:
                        entry["extra"] = extra
                if entry:
                    by[did] = entry
            if by:
                dom["byId"] = by
        if "slots" in sec:
            slots = slot_edits(sec["slots"], ".domains.slots", "domains")
            if slots:
                dom["slots"] = slots
        if dom:
            out["domains"] = dom
    if "quests" in doc:
        sec, quests = obj(doc["quests"], ".quests", ("multiplier", "byReward")), {}
        if "multiplier" in sec:
            mult = {}
            for kind, m in obj(sec["multiplier"], ".quests.multiplier", TWEAK_QUEST_KINDS).items():
                if integer(m, ".quests.multiplier.%s" % kind, 1, lim["multiplierMax"]) != 1:
                    mult[kind] = m
            if mult:
                quests["multiplier"] = mult
        if "byReward" in sec:
            rewards, by = cat["quests"]["rewards"], {}
            for rid, own in obj(sec["byReward"], ".quests.byReward").items():
                at = ".quests.byReward.%s" % rid
                if rid not in rewards:
                    bad(at, "unknown quest reward")
                if rewards[rid]["edit"] != 1:
                    bad(at, "this reward is shared by several quests and cannot be replaced")
                obj(own, at, ("items",))
                entries = item_list(own["items"], at + ".items", TWEAK_REWARD_ITEMS_MAX, False) if "items" in own else []
                if sum(1 for e in entries if e["item"] not in virtual) > TWEAK_REWARD_SLOTS:
                    bad(at + ".items", "at most %d items besides the currencies and EXP" % TWEAK_REWARD_SLOTS)
                if entries:
                    by[rid] = {"items": entries}
            if len(by) > lim["customMax"]:
                bad(".quests.byReward", "at most %d quest rewards can be replaced" % lim["customMax"])
            if by:
                quests["byReward"] = by
        if quests:
            out["quests"] = quests
    return _tweaks_sorted(out)


def tweaks_digest(doc):
    """What identifies a canonical document (the record keeps it for a refused one)."""
    return hashlib.sha256(json.dumps(doc, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def tweaks_edits(cat, doc, base=None):
    """{path: what a canonical document does to that file} -- the files the document rewrites and, per file,
    the arguments of its editors: "resin" {cap?, minutes?}, "levels" {level id: level}, "slots" {config id:
    monster id} (the script of a monster group, whichever card names it: `abyss.slots` or `domains.slots`),
    "costs" {dungeon id: resin}, "revise" {dungeon id: enemy-level cell} (the level the document gives a
    domain, less one -- in the table the costs go into: one output of it carries both), "roots" {reward row:
    (multiplier, [(item, count)], the domain's document path)}, "daily" the commission multiplier, "rewards"
    ({row: multiplier}, {row: [(item, count)]}). A domain's own multiplier / cost wins over the one for all
    domains, and no domain is multiplied beyond what its reward row tolerates (the catalogue's `max`). A cost
    and an enemy level are written where they differ from what the base holds (`base`: tweaks_facts, None =
    the catalogue's -- the document must have been normalised against the same). Pure."""
    base = tweaks_facts(cat) if base is None else base
    edits = {}

    def put(rel, key, value):
        edits.setdefault(rel, {})[key] = value

    if doc.get("resin"):
        put(cat["resin"]["file"], "resin", doc["resin"])
    abyss = doc.get("abyss") or {}
    if abyss.get("levels"):
        put(cat["abyss"]["levelFile"], "levels", abyss["levels"])
    dom = doc.get("domains") or {}
    for section, wanted in (("abyss", abyss.get("slots")), ("domains", dom.get("slots"))):
        if wanted:
            groups = _tweaks_groups(cat, section)
            for gid, slots in wanted.items():
                edits.setdefault(groups[gid]["file"], {}).setdefault("slots", {}).update(slots)
    if dom:
        costs, revise, roots = {}, {}, {}
        for did, d in cat["domains"]["list"].items():
            own = (dom.get("byId") or {}).get(did) or {}
            held_cost, held_level = base["costs"].get(did), base["domainLevels"].get(did)
            cost = own.get("cost", dom.get("cost", held_cost))
            if cost is not None and cost != held_cost:
                costs[did] = cost
            if "level" in own and own["level"] != held_level:
                revise[did] = own["level"] - 1
            mult = min(own.get("multiplier", dom.get("multiplier", 1)), TWEAK_LIMITS["multiplierMax"], d["max"])
            extra = [(e["item"], e["count"]) for e in own.get("extra") or []]
            if mult != 1 or extra:
                roots[str(d["root"])] = (mult, extra, ".domains.byId.%s" % did)
        if costs:
            put(cat["domains"]["file"], "costs", costs)
        if revise:
            put(cat["domains"]["file"], "revise", revise)
        if roots:
            put(cat["domains"]["dropFile"], "roots", roots)
    quests = doc.get("quests") or {}
    mult, custom = quests.get("multiplier") or {}, quests.get("byReward") or {}
    daily = cat["quests"]["daily"]
    if mult.get("commission", 1) != 1 and daily["drops"]:
        put(daily["file"], "daily", mult["commission"])
    rows = {rid: mult[r["kind"]] for rid, r in cat["quests"]["rewards"].items()
            if mult.get(r["kind"], 1) != 1 and rid not in custom}
    if rows or custom:
        put(cat["quests"]["file"], "rewards",
            (rows, {rid: [(e["item"], e["count"]) for e in own["items"]] for rid, own in custom.items()}))
    return edits


def tweaks_output(cat, edit, original, rel, kept=()):
    """The bytes ONE file must hold -- its BASE (`original`: the vendor's original or an adopted base) run
    through the editors its entry of tweaks_edits names, one after the other where it names several (the statue
    costs and the enemy levels of the domains are two columns of one table) -> (bytes, the number of cells a
    server cap limited). `kept` = the row ids of the file a hand changed while a multiplier applied to them: no
    multiplier and no extra item touches them -- an own reward of a quest still replaces such a row while it is
    in the document. Pure."""
    name, out, clamped, kept = rel.rsplit("/", 1)[-1], original, 0, set(str(r) for r in kept)
    if "resin" in edit:
        out = tweak_resin(out, cat["resin"]["row"], edit["resin"].get("cap"), edit["resin"].get("minutes"), name)
    if "levels" in edit:
        out = tweak_abyss_levels(out, edit["levels"], name)
    if "slots" in edit:
        out = tweak_group_slots(out, edit["slots"], cat["monsters"], cat["genericAffixes"], name)
    if "costs" in edit:
        out = tweak_domain_costs(out, edit["costs"], name)
    if "revise" in edit:
        out = tweak_domain_levels(out, edit["revise"], name)
    if "roots" in edit or "daily" in edit:
        daily = cat["quests"]["daily"]
        roots = dict((rid, root) for rid, root in (edit.get("roots") or {}).items() if str(rid) not in kept)
        out, n = tweak_drops(out, roots,
                             ([r for r in daily["drops"] if str(r) not in kept], daily["items"], edit["daily"])
                             if "daily" in edit else None,
                             cat["items"], name)
        clamped += n
    if "rewards" in edit:
        out, n = tweak_rewards(out, {rid: m for rid, m in edit["rewards"][0].items() if str(rid) not in kept},
                               edit["rewards"][1], cat["items"], name, cat["quests"].get("keep") or ())
        clamped += n
    return out, clamped


def tweaks_leaves(doc):
    """{path: value} of a canonical document, one entry per SETTING: "resin.cap", "resin.minutes",
    "abyss.levels.<chamber>", "abyss.slots.<group>.<slot>", "domains.multiplier", "domains.cost",
    "domains.byId.<domain>.<multiplier | cost | level | extra>" (the extra items of a domain are one setting),
    "domains.slots.<group>.<slot>", "quests.multiplier.<kind>", "quests.byReward.<row>" (one own reward, whole).
    Pure."""
    out = {}
    for key, value in (doc.get("resin") or {}).items():
        out["resin." + key] = value
    for lid, level in ((doc.get("abyss") or {}).get("levels") or {}).items():
        out["abyss.levels." + lid] = level
    for section in TWEAK_SLOT_SECTIONS:
        for gid, slots in ((doc.get(section) or {}).get("slots") or {}).items():
            for cfg, monster in slots.items():
                out["%s.slots.%s.%s" % (section, gid, cfg)] = monster
    dom = doc.get("domains") or {}
    for key in ("multiplier", "cost"):
        if key in dom:
            out["domains." + key] = dom[key]
    for did, own in (dom.get("byId") or {}).items():
        for key, value in own.items():
            out["domains.byId.%s.%s" % (did, key)] = value
    quests = doc.get("quests") or {}
    for kind, m in (quests.get("multiplier") or {}).items():
        out["quests.multiplier." + kind] = m
    for rid, own in (quests.get("byReward") or {}).items():
        out["quests.byReward." + rid] = own
    return out


def tweaks_from_leaves(leaves):
    """The document of tweaks_leaves' {path: value} -- a copy, keys sorted, not checked: normalise_tweaks checks
    it. Pure."""
    doc = {}
    for path, value in leaves.items():
        parts, node = path.split("."), doc
        for part in parts[:-1]:
            node = node.setdefault(part, {})
        node[parts[-1]] = json.loads(json.dumps(value))
    return _tweaks_sorted(doc)


def tweaks_setting_files(cat, paths):
    """{path: (the files the setting writes, the files it needs besides)} for the settings `paths` names (paths
    of tweaks_leaves): resin -> the constant table; a chamber's level -> the chamber table; a slot -> its group's
    script; the cost for all domains, a domain's cost and its enemy level -> the dungeon table, the level also
    NEEDING the script of the domain's line-up (_tweaks_level_scripts); the multiplier for all domains, a
    domain's own multiplier and extra items -> the drop table; a quest multiplier -> the reward table (and, for
    the daily commissions, the drop table); an own reward -> the reward table. A path the catalogue does not
    know writes nothing. Pure."""
    groups = {section: _tweaks_groups(cat, section) for section in TWEAK_SLOT_SECTIONS}
    daily, out = cat["quests"]["daily"], {}
    for path in paths:
        parts, writes, needs = path.split("."), set(), set()
        if parts[0] == "resin":
            writes.add(cat["resin"]["file"])
        elif parts[0] == "abyss" and parts[1:2] == ["levels"]:
            writes.add(cat["abyss"]["levelFile"])
        elif parts[0] in TWEAK_SLOT_SECTIONS and parts[1:2] == ["slots"] and len(parts) == 4:
            if parts[2] in groups[parts[0]]:
                writes.add(groups[parts[0]][parts[2]]["file"])
        elif parts[0] == "domains" and (parts[1:] == ["cost"] or (parts[1:2] == ["byId"] and parts[3:] in (["cost"],
                                                                                                           ["level"]))):
            writes.add(cat["domains"]["file"])
            if parts[3:] == ["level"]:
                needs = _tweaks_level_scripts(cat, {"domains": {"byId": {parts[2]: {"level": 0}}}})
        elif parts[0] == "domains":
            writes.add(cat["domains"]["dropFile"])
        elif parts[0] == "quests":
            writes.add(cat["quests"]["file"])
            if parts[1:] == ["multiplier", "commission"] and daily["drops"]:
                writes.add(daily["file"])
        out[path] = (writes, needs)
    return out


# -- the record, the base copies and the file states --

def tweaks_path(version, rel):
    """Where a catalogue path lives in this version's stack."""
    return os.path.join(stack_dir(version), *rel.split("/"))


def tweaks_base_path(version, rel):
    """Where the original of a catalogue path is kept once the agent has rewritten the file."""
    return os.path.join(stack_dir(version), TWEAKS_DIR, "base", *rel.split("/"))


def tweaks_adopted_path(version, rel, undo=False):
    """Where the ADOPTED base of a catalogue path is kept (tweaks_take_over) -- never under base/: an agent that
    knows no take-over must not read it as the vendor's original. undo: the adopted base an entry's `undo`
    still names once a later take-over replaced it."""
    return os.path.join(stack_dir(version), TWEAKS_DIR, "adopted", *rel.split("/")) + (".undo" if undo else "")


def tweaks_hand_path(version, rel):
    """Where ONE copy of the bytes a hand-changed file held is kept before the agent puts an original over them."""
    return os.path.join(stack_dir(version), TWEAKS_DIR, "hand", *rel.split("/"))


def tweaks_prev_path(version, rel):
    """Where ONE copy of the bytes a file whose base was adopted held is kept before the agent writes it again
    (_apply_tweaks_plan): what the leftover rule gives it back when that write gets no verdict -- never its base,
    and never anything else than the copy whose md5 the entry names as `prev`."""
    return os.path.join(stack_dir(version), TWEAKS_DIR, "prev", *rel.split("/"))


def tweaks_originals_path(version):
    """payloads/<version>/tweaks-originals.tar.gz: the vendor's original of every file the catalogue names."""
    return os.path.join(payload_dir(version), TWEAKS_ORIGINALS)


def tweaks_record_path(version):
    return os.path.join(stack_dir(version), TWEAKS_DIR, "record.json")


def tweaks_blank_record():
    """The record of a stack that has none: no gameplay settings, every file the vendor's."""
    return {"schema": TWEAKS_SCHEMA, "tweaks": {}, "active": {}, "refused": None, "files": {}}


def _tweaks_record_problem(rec):
    """Why a parsed record cannot be used, or None. Pure."""
    if not isinstance(rec, dict):
        return "not a JSON object"
    schema = rec.get("schema")
    if isinstance(schema, bool) or not isinstance(schema, int) or schema < 1:
        return "it has no schema number"
    if schema > TWEAKS_SCHEMA:
        return "it was written by a newer agent (schema %d)" % schema
    if not isinstance(rec.get("tweaks"), dict) or not isinstance(rec.get("active"), dict):
        return "tweaks and active must be objects"
    refused = rec.get("refused")
    if refused is not None and not (isinstance(refused, dict) and isinstance(refused.get("error"), str)
                                    and isinstance(refused.get("digest"), str)
                                    and isinstance(refused.get("at"), (int, float))
                                    and not isinstance(refused.get("at"), bool)):
        return "refused must be null or {at, error, digest}"
    if "unread" in rec and not isinstance(rec["unread"], bool):
        return "unread must be true or false"
    files = rec.get("files")
    if not isinstance(files, dict):
        return "files must be an object"

    def md5(value):
        return isinstance(value, str) and _TWEAK_MD5_RE.fullmatch(value) is not None

    def rows(value):
        return isinstance(value, list) and all(isinstance(r, str) and _TWEAK_ID_RE.fullmatch(r) for r in value)

    for rel, entry in files.items():
        if not _tweak_path_ok(rel) or not isinstance(entry, dict) or not isinstance(entry.get("ok"), bool) or any(
                not md5(entry.get(k)) for k in ("base", "out") + (("prev",) if "prev" in entry else ())):
            return "files: the entry of %r is not {base, out, ok}" % (rel,)
        taken, undo = entry.get("taken"), entry.get("undo")
        if "taken" in entry and not (isinstance(taken, dict) and md5(taken.get("hand")) and md5(taken.get("vendor"))
                                     and isinstance(taken.get("at"), (int, float))
                                     and not isinstance(taken["at"], bool)):
            return "files: the entry of %r has a taken that is not {at, hand, vendor}" % (rel,)
        if "kept" in entry and not rows(entry["kept"]):
            return "files: the entry of %r has kept rows that are not a list of row ids" % (rel,)
        if "undo" in entry and not (isinstance(undo, dict) and md5(undo.get("base")) and rows(undo.get("kept"))
                                    and isinstance(undo.get("keys"), dict)
                                    and all(isinstance(k, str) and isinstance(v, dict)
                                            and set(v) == {"active", "tweaks"} for k, v in undo["keys"].items())):
            return "files: the entry of %r has an undo that is not {base, kept, keys}" % (rel,)
        released = entry.get("released")
        if "released" in entry and not (md5(released) or (isinstance(released, list) and released
                                                           and all(md5(m) for m in released))):
            return "files: the entry of %r has a released that is not a list of md5s" % (rel,)
        if "away" in entry and not isinstance(entry["away"], bool):
            return "files: the entry of %r has an away that is not true or false" % (rel,)
    return None


def read_tweaks_record(version):
    """<stack>/.relic-tweaks/record.json. A stack without one has no gameplay settings (tweaks_blank_record).
    One that exists but cannot be read, parsed or understood RAISES AgentError(500) naming the file: read as
    blank, a writer would forget which files hold content the agent wrote and which document the admin wants.
    Every caller decides what that means -- GET /server/tweaks reports it, a job fails with it, a hook of a
    Start does nothing. Keys this agent does not know are kept as they are."""
    path = tweaks_record_path(version)
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        return tweaks_blank_record()
    except OSError as e:
        raise AgentError(500, "Gameplay settings: %s cannot be read (%s)." % (path, e))
    try:
        rec = json.loads(raw.decode("utf-8-sig"))
        problem = _tweaks_record_problem(rec)
    except (ValueError, RecursionError) as e:
        problem = "not valid JSON: %s" % e
    if problem:
        raise AgentError(500, "Gameplay settings: %s cannot be used (%s) -- repair it; until then the server's "
                              "data files are left as they are." % (path, problem))
    rec.setdefault("refused", None)
    return rec


def _tweaks_makedirs(version, folder):
    """The agent's own folders under <stack>/.relic-tweaks, created 0755 with the stack folder's owner: they
    travel with the stack, and whoever owns the stack must be able to copy or remove them."""
    owner, missing = _stat_or_none(stack_dir(version)), []
    while not os.path.isdir(folder) and os.path.dirname(folder) != folder:
        missing.append(folder)
        folder = os.path.dirname(folder)
    for path in reversed(missing):
        try:
            os.mkdir(path)
        except FileExistsError:
            continue
        if os.name == "posix" and owner is not None:
            try:
                os.chmod(path, 0o755)
                os.chown(path, owner.st_uid, owner.st_gid)
            except OSError:
                pass


def _write_tweaks_own(version, path, data):
    """A file of the agent's own under <stack>/.relic-tweaks (the record, a base copy): written durably
    (write_text_durable: temp file, fsync, rename, directory fsync), a NEW one 0644 with its folder's owner.
    Raises OSError."""
    _tweaks_makedirs(version, os.path.dirname(path))
    was_new = not os.path.isfile(path)
    write_text_durable(path, data.decode("utf-8", "surrogateescape"))  # the bytes as they are, both ways
    if was_new:
        _restore_owner_mode(path, None)


def write_tweaks_record(version, record):
    """The record written durably; returns it. Raises AgentError(507)."""
    path = tweaks_record_path(version)
    try:
        _write_tweaks_own(version, path, (json.dumps(record, sort_keys=True, indent=1) + "\n").encode("utf-8"))
    except OSError as e:
        raise AgentError(507, "Gameplay settings: %s could not be written (%s)." % (path, e))
    return record


def _tweaks_read(path):
    """The bytes of a file, None when it is not there; any other failure is an AgentError(500) naming it."""
    try:
        with open(path, "rb") as f:
            return f.read()
    except FileNotFoundError:
        return None
    except OSError as e:
        raise AgentError(500, "Gameplay settings: %s cannot be read (%s)." % (path, e))


def _tweaks_taken(entry):
    """Whether a record entry is the one of a file whose base was ADOPTED (tweaks_take_over): it names `taken`.
    Pure."""
    return isinstance(entry, dict) and isinstance(entry.get("taken"), dict)


def _tweaks_released(entry):
    """[md5, ...] of the bytes a Revert or a Reset let go that a record entry names (`released`: a list, or one md5
    as a string), lower case, oldest first; [] for none. Pure."""
    value = (entry or {}).get("released") if isinstance(entry, dict) else None
    if isinstance(value, str):
        value = [value]
    return [str(m).lower() for m in value or []]


def _tweaks_base_value(facts, path):
    """The value the bases hold for ONE setting (a path of tweaks_leaves): the resin row's cap or minutes, a chamber's
    enemy level, a spawn slot's monster, a domain's statue cost or enemy level -- what a take-over leaves a document
    at where it sets a key (tweaks_take_over); None for a setting no base holds a value of (a multiplier, extra
    items, an own reward, the cost for all domains) and for one whose base is not known. Pure."""
    parts = path.split(".")
    if parts[0] == "resin" and len(parts) == 2:
        return facts["resin"].get(parts[1])
    if parts[:2] == ["abyss", "levels"] and len(parts) == 3:
        return facts["levels"].get(parts[2])
    if parts[0] in TWEAK_SLOT_SECTIONS and parts[1:2] == ["slots"] and len(parts) == 4:
        return (facts["slots"].get(parts[2]) or {}).get(parts[3])
    if parts[:2] == ["domains", "byId"] and len(parts) == 4 and parts[3] in ("cost", "level"):
        return facts["costs" if parts[3] == "cost" else "domainLevels"].get(parts[2])
    return None


def tweaks_shipped_originals(version, wanted):
    """{path: bytes} of the members of payloads/<version>/tweaks-originals.tar.gz that `wanted` ({path: md5})
    names and whose bytes have that md5 -- ONE pass over the archive, read as a stream (a member at a time, held
    in memory, nothing written anywhere), nothing remembered beyond the call -> (found, None), or (what was found
    before the damage, why) when the archive cannot be read -- the originals it holds are not available then.
    No archive, or nothing wanted: ({}, None)."""
    path, found = tweaks_originals_path(version), {}
    wanted = {rel: str(md5).lower() for rel, md5 in wanted.items()}
    if not wanted or not os.path.isfile(path):
        return found, None
    try:
        with open(path, "rb") as raw, gzip.GzipFile(fileobj=raw, mode="rb") as unzipped, \
                tarfile.open(fileobj=unzipped, mode="r|") as archive:
            for member in archive:
                rel = member.name
                if rel not in wanted or rel in found or not member.isreg() or member.size > TWEAKS_ORIGINAL_MAX:
                    continue
                f = archive.extractfile(member)
                data = f.read() if f is not None else b""
                if hashlib.md5(data).hexdigest() == wanted[rel]:
                    found[rel] = data
                    if len(found) == len(wanted):
                        break
    except (zlib.error, EOFError, OSError, tarfile.TarError, ValueError) as e:
        return found, "%s cannot be read (%s)" % (path, _failure_text(e))
    return found, None


def _tweaks_archive_md5s(version):
    """{member: md5} of the shipped originals archive as GET /server/tweaks needs it -- what an original found
    nowhere else would be read from; remembered per stamp of the archive (only the md5s, never the bytes); {}
    without an archive, the members read before the damage of one that cannot be read whole."""
    path = tweaks_originals_path(version)
    if not os.path.isfile(path):
        return {}

    def load(p):
        out = {}
        try:
            with open(p, "rb") as raw, gzip.GzipFile(fileobj=raw, mode="rb") as unzipped, \
                    tarfile.open(fileobj=unzipped, mode="r|") as archive:
                for member in archive:
                    if member.isreg() and member.size <= TWEAKS_ORIGINAL_MAX:
                        f = archive.extractfile(member)
                        out[member.name] = hashlib.md5(f.read() if f is not None else b"").hexdigest()
        except (zlib.error, EOFError, OSError, tarfile.TarError, ValueError):
            pass
        return out

    return _tweaks_cached("archive", path, load)


def tweaks_vendor_bytes(version, rel, md5, disk=None, memo=None):
    """The VENDOR'S ORIGINAL of one target file, by its md5 (the catalogue's, or the one a record entry names as
    the original it was built from) -- in this order the file's own bytes (`disk`) while they are it, the base
    copy, the member of the shipped archive (tweaks_shipped_originals) -- or None: nothing else is ever taken
    for it. memo: a dict the caller keeps for one job or one answer -- the archive is read once per file then,
    and memo[None] says why it could not be read. Raises AgentError(500) for a base copy that cannot be read."""
    md5 = str(md5 or "").lower()
    if not md5:
        return None
    if disk is not None and hashlib.md5(disk).hexdigest() == md5:
        return disk
    data = _tweaks_read(tweaks_base_path(version, rel))
    if data is not None and hashlib.md5(data).hexdigest() == md5:
        return data
    if memo is not None and (rel, md5) in memo:
        return memo[(rel, md5)]
    found, why = tweaks_shipped_originals(version, {rel: md5})
    if memo is not None:
        memo[(rel, md5)] = found.get(rel)
        if why and None not in memo:
            memo[None] = why
    return found.get(rel)


def _tweaks_adopted_read(version, rel, md5):
    """The adopted base of a catalogue path whose md5 is `md5` -- adopted/<path>, else the copy beside it that an
    `undo` names (adopted/<path>.undo: a Revert builds on it again) -- or None. Raises AgentError(500) for a copy
    that cannot be read."""
    for undo in (False, True):
        data = _tweaks_read(tweaks_adopted_path(version, rel, undo=undo))
        if data is not None and hashlib.md5(data).hexdigest() == md5:
            return data
    return None


def _tweaks_entry_base(version, rel, entry, memo=None):
    """The base a record entry names, when it is there with the entry's md5 -- the adopted base of a taken entry
    (_tweaks_adopted_read; one a take-over computed and nobody stored yet: memo[("adopted", path, md5)]), else
    the vendor's original by that md5 (tweaks_vendor_bytes) -- or None. Raises AgentError(500) for a copy that
    cannot be read."""
    want = entry["base"].lower()
    if _tweaks_taken(entry):
        if memo is not None and ("adopted", rel, want) in memo:
            return memo[("adopted", rel, want)]
        return _tweaks_adopted_read(version, rel, want)
    return tweaks_vendor_bytes(version, rel, want, memo=memo)


def _tweaks_state(want, disk, entry, base):
    """The state of one target file from its md5s -- the vendor's original (`want`), the file's (`disk`, None =
    not there), the record's entry for it and the md5 of the base that entry names, as found (`base`, None = not
    there): "original" | "ours" (the record names the md5 as what the agent wrote, or as what it had written
    before a rewrite that did not finish, and the base it was built from is there) | "changed" | "missing". A
    file that holds the vendor's original is `original` -- unless the entry names those very bytes as the
    agent's output on ANOTHER base (an adopted one): the agent put the original there itself, and builds on
    its base. Pure."""
    if disk is None:
        return "missing"
    own = isinstance(entry, dict) and disk in (entry.get("out"), entry.get("prev")) and base is not None \
        and base == str(entry.get("base") or "").lower()
    if own and str(entry["base"]).lower() != want:
        return "ours"
    if want and disk == want:
        return "original"
    if own and want:
        return "ours"
    return "changed"


def _tweaks_file(version, rel, want, entry, memo=None):
    """tweaks_file for one path, the md5 of its vendor's original (`want`) and its entry of the record (or None)."""
    disk = _tweaks_read(tweaks_path(version, rel))
    if disk is None:
        return "missing", None, None
    md5 = hashlib.md5(disk).hexdigest()
    mine = isinstance(entry, dict) and md5 in (entry.get("out"), entry.get("prev"))
    if want and md5 == want and not (mine and entry["base"].lower() != want):
        return "original", disk, disk
    base = _tweaks_entry_base(version, rel, entry, memo) if entry is not None else None
    state = _tweaks_state(want, md5, entry, None if base is None else hashlib.md5(base).hexdigest())
    return state, disk, (base if state == "ours" else None)


def _tweaks_foreign(cat, record, rel):
    """Whether the record names `rel` as written from an original this catalogue does not vouch for: the
    path is not one of its files, or it pins another md5 for it -- the record of an agent that shipped
    another catalogue. For an entry whose base was adopted (_tweaks_taken) that is the vendor's original it
    was taken over from (`taken.vendor`). No output can be built on such a file; one whose base is a vendor's
    original is the agent's own all the same: its entry names that original (`base`) and the base copy holds
    it. Pure."""
    entry = record["files"].get(rel)
    if entry is None:
        return False
    want = str(cat["files"].get(rel) or "").lower()
    if _tweaks_taken(entry):
        return entry["taken"]["vendor"].lower() != want
    return entry["base"].lower() != want


def _tweaks_foreign_md5(cat, record, rel, md5):
    """_tweaks_foreign for a file as it is (`md5`: its md5, None when it is missing): an entry built on another
    original than the catalogue's -- unless the file holds the original THIS catalogue pins and the entry does not
    name it as the agent's output (a package extracted again: the entry is stale, the file this catalogue's
    original). Pure."""
    if not _tweaks_foreign(cat, record, rel):
        return False
    entry = record["files"][rel]
    return not (md5 is not None and md5 == str(cat["files"].get(rel) or "").lower()
                and md5 not in (entry.get("out"), entry.get("prev")))


def tweaks_file(version, cat, record, rel, memo=None):
    """(state, the bytes on disk, the BASE bytes) of one target file -- read and hashed at this moment, never
    from a cache: a write is decided on it. The base bytes are the file's own while it is `original`, the base
    its entry names while it is `ours` (the adopted copy of a taken file, the vendor's original otherwise), None
    otherwise. The original is the one the catalogue pins -- for a file the record names that the catalogue does
    not vouch for (_tweaks_foreign) and whose base is a vendor's original, the one its own entry names: `ours`
    there means "still the agent's, and its base copy is what it goes back to", never that a document may be
    applied to it. A file such an entry names that holds the original THIS catalogue pins -- and that the entry
    does not name as the agent's own output -- is `original`: a package extracted again, the entry stale.
    memo: tweaks_vendor_bytes."""
    entry = record["files"].get(rel)
    foreign = _tweaks_foreign(cat, record, rel)
    want = entry["base"] if foreign and not _tweaks_taken(entry) else cat["files"].get(rel)
    state, disk, base = _tweaks_file(version, rel, str(want or "").lower(), entry, memo)
    if foreign and state == "changed" and disk is not None:
        md5 = hashlib.md5(disk).hexdigest()
        if md5 == str(cat["files"].get(rel) or "").lower() and md5 not in (entry.get("out"), entry.get("prev")):
            return "original", disk, disk
    return state, disk, base


def _tweaks_unusable(rel, state):
    """The 409 of a write that finds a file of its plan gone (`state` "missing") or changed outside Relic (any other
    state) after the plan was made -- nothing of the change is written; the next job takes the change over or
    leaves out what rests on the file."""
    if state == "missing":
        return AgentError(409, "Gameplay settings: %s is missing from the server's files -- nothing of the change was "
                               "written; apply again: the settings that need it are left out." % rel)
    return AgentError(409, "Gameplay settings: %s was changed outside Relic while the job ran -- nothing of the change "
                           "was written; apply again: the next job takes the change over or leaves out what rests on "
                           "it." % rel)


def tweaks_unconfirmed(record):
    """Whether the record names a file written without a verdict of the server: an apply that was interrupted."""
    return any(not entry.get("ok") for entry in record["files"].values())


# -- plan, probe, apply: the file layer --

def _write_tweak_files(version, items):
    """[(path, bytes)] written into the stack as ONE change set: every temp file first -- beside its target,
    flushed and fsync'ed, with the mode and owner of the file it replaces (a data file keeps its own) -- then
    the renames, back to back. A service may begin a load at any moment (a signal, its own timer where its
    build has one): the time in which it could load half a change set is a handful of renames, not the
    writing of every file. A target that is a link is written through. Raises OSError: nothing was renamed
    when a temp file could not be written; a rename that fails leaves the files before it replaced (the
    caller puts them back)."""
    staged = []
    try:
        for rel, data in items:
            path = tweaks_path(version, rel)
            if os.path.islink(path):
                path = os.path.realpath(path)
            tmp, st = path + ".tmp", _stat_or_none(path)
            _remove_quiet(tmp)  # a leftover of a write that died (one job at a time writes a stack's files)
            staged.append((tmp, path))
            fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0),
                         0o600 if st is not None else 0o666)
            with os.fdopen(fd, "wb") as f:
                f.write(data)
                f.flush()
                os.fsync(f.fileno())
            if st is not None and os.name != "nt":
                try:
                    os.chmod(tmp, st.st_mode & 0o7777)
                    os.chown(tmp, st.st_uid, st.st_gid)
                except OSError:
                    pass
        for n, (tmp, path) in enumerate(staged):
            replace_file(tmp, path)
            staged[n] = (None, path)
    except BaseException:
        for tmp, _path in staged:
            if tmp:
                _remove_quiet(tmp)
        raise
    for folder in sorted(set(os.path.dirname(path) for _tmp, path in staged)):
        _fsync_dir(folder)


def _put_back_tweak_files(version, items):
    """[(path, bytes)] written by a caller that puts files BACK -- the previous bytes after a refusal or a
    failed write, the originals of the leftover rule -- and so must not stop at one file that cannot be
    replaced (on Windows: one another program holds open) and leave the files behind it as they are. The
    whole set in one go first (_write_tweak_files: the renames back to back); when that fails, file by
    file, each one that does not hold its bytes already. Returns [(path, why)] of the files that still hold
    other bytes -- empty when every file holds what it was given. Never raises."""
    try:
        _write_tweak_files(version, items)
        return []
    except OSError:
        pass
    stuck = []
    for rel, data in items:
        try:
            if _tweaks_read(tweaks_path(version, rel)) != data:
                _write_tweak_files(version, [(rel, data)])
        except (OSError, AgentError) as e:
            stuck.append((rel, _failure_text(e)))
    return stuck


def _tweaks_stuck_text(stuck):
    """The files a put-back could not write, as an error names them: up to three paths, how many more, and
    why the first one could not be written."""
    names = [rel for rel, _why in stuck]
    return "%s%s: %s" % (", ".join(names[:3]), " and %d more" % (len(names) - 3) if len(names) > 3 else "",
                         stuck[0][1])


# Who takes the files back once a put-back has failed: said by every 507 that leaves an unconfirmed file.
_TWEAKS_LEFTOVER_NOTE = ("the original files are put back by the next Apply, and before the agent starts a game "
                         "service again")


def tweaks_record_bases(version, cat, record, memo=None, seen=None):
    """{path: the bytes of its base | None} of the files whose base is not the vendor's original -- the files of
    the record's taken entries (_tweaks_taken) that are not back at the original (an `original` file is built
    on the vendor's original again); None for a base that is not there. What tweaks_facts reads the values a
    document is compared with from. Read at this moment. memo: tweaks_vendor_bytes; seen: {path: what
    tweaks_file answered} the caller already looked at, filled with what this looks at."""
    seen = {} if seen is None else seen
    bases = {}
    for rel, entry in sorted(record["files"].items()):
        if not _tweaks_taken(entry) or rel not in cat["files"]:
            continue
        if rel not in seen:
            seen[rel] = tweaks_file(version, cat, record, rel, memo)
        state, _disk, base = seen[rel]
        if state != "original":
            bases[rel] = base if state == "ours" else _tweaks_entry_base(version, rel, entry, memo)
    return bases


def tweaks_record_facts(version, cat, record, memo=None, seen=None):
    """tweaks_facts of the stack as its record names the bases (tweaks_record_bases): what a document of this
    stack is normalised and edited against."""
    return tweaks_facts(cat, tweaks_record_bases(version, cat, record, memo, seen))


def _tweaks_level_reason(level):
    """Why the enemy level of a line-up's domains cannot be set while its script, taken over, carries an entry
    above the level the line-up is listed with (the range of that level holds for the vendor's script)."""
    return ("an entry of it stands above level %d, the level its line-up is listed with -- the enemy level of its "
            "domains cannot be set while it does" % level)


# -- settings that cannot be applied: one setting at a time, never all-or-nothing --
# A setting (one path of tweaks_leaves) rests on the files tweaks_setting_files names. One of them that cannot
# carry settings -- missing, changed outside Relic and not taken over, built on another original than the
# catalogue's, one an editor refuses -- BLOCKS every setting that rests on it, whole; so does the script of a
# line-up taken over with an entry above the line-up's level for the enemy level of its domains. The rest is
# applied. What the files are brought in line with is the EFFECTIVE document: the wanted one with every blocked
# setting replaced by its value in `active` (absent where `active` has none), so `active` keeps describing what
# every file holds -- a blocked setting is not taken out of the usable files it also writes. A blocked setting
# waits for a Revert or a Reset of its card, not for a Start: it is never `pending`.

def tweaks_blocked(cat, paths, unusable, locked=()):
    """{path: whether the value in effect stays} of the settings among `paths` (tweaks_leaves paths) that cannot be
    applied: one a file it writes or needs (tweaks_setting_files) is in `unusable` ({path: (why, reason,
    restorable)}) for, and the enemy level of a domain whose line-up script is in `locked`. The value in effect
    stays (True) while one such file is left as it is; a setting blocked only by files that go back to their own
    original (restorable: built on another original than the catalogue's) is taken out (False) -- those files
    are put back. Pure."""
    locked, out = set(locked), {}
    for path, (writes, needs) in tweaks_setting_files(cat, paths).items():
        hit = [rel for rel in sorted(writes | needs) if rel in unusable]
        level = path.startswith("domains.byId.") and path.endswith(".level") and bool(needs & locked)
        if hit or level:
            out[path] = level or not all(unusable[rel][2] for rel in hit)
    return out


def tweaks_effective(doc, active, blocked):
    """The EFFECTIVE document: `doc` with every setting of `blocked` (tweaks_blocked) replaced by its value in
    `active` -- absent where `active` has none, or where the setting is taken out. Not canonical: the caller
    normalises it. Pure."""
    wanted, held = tweaks_leaves(doc), tweaks_leaves(active)
    out = dict((path, value) for path, value in wanted.items() if path not in blocked)
    out.update((path, held[path]) for path, keep in blocked.items() if keep and path in held)
    return tweaks_from_leaves(out)


def _tweaks_changed_why(entry, md5):
    """Why a `changed` file (`md5`: its md5) cannot carry settings when no take-over said why: it holds what the agent
    wrote on a base that is gone (the md5 its entry names as its output), or it was changed outside Relic. Pure."""
    if isinstance(entry, dict) and md5 is not None and md5 in (entry.get("out"), entry.get("prev")):
        return TWEAKS_WHY_BASE_GONE
    return TWEAKS_WHY_CHANGED


def tweaks_blocked_line(cat, info):
    """The ONE job line of a run whose settings are not all applied (tweaks_plan's info): the cards whose settings
    stay unapplied, the files why (three at most named) and what helps -- None when nothing is blocked."""
    blocked, why = info.get("blocked") or [], info.get("unusable") or {}
    if not blocked:
        return None
    rests = tweaks_setting_files(cat, blocked)
    files = sorted(set(rel for writes, needs in rests.values() for rel in writes | needs if rel in why))
    cards = [TWEAKS_CARD_NAMES[c] for c in TWEAK_SECTIONS if any(p.split(".", 1)[0] == c for p in blocked)]

    def phrase(rel):
        kind, reason = why[rel][0], why[rel][1]
        if kind == "missing":
            return "%s is missing" % rel
        if kind == "refused":
            return "%s cannot be edited (%s)" % (rel, reason)
        if kind == "changed" and reason in ("", TWEAKS_WHY_CHANGED):
            return "%s was changed outside Relic" % rel
        if kind == "changed" and reason not in (TWEAKS_WHY_FOREIGN, TWEAKS_WHY_BASE_GONE):
            return "%s was changed outside Relic (%s)" % (rel, reason)
        return "%s: %s" % (rel, reason)  # (a level lock; a file Relic wrote from another original, or on a base gone)

    named = "; ".join(phrase(rel) for rel in files[:3])
    if len(files) > 3:
        named += "; and %d more files" % (len(files) - 3)
    n = len(blocked)
    return ("Gameplay settings: %d setting%s of the %s card%s %s not applied -- %s; Revert or Reset %s on %s."
            % (n, "" if n == 1 else "s", _tweaks_and(cards), "" if len(cards) == 1 else "s", "is" if n == 1 else "are",
               named, "it" if len(files) == 1 else "them", "that card" if len(cards) == 1 else "those cards"))


def tweaks_plan(version, cat, record, doc, reasons=None, info=None, memo=None):
    """What bringing the stack's files in line with `doc` would write, with nothing written: ([(path, new
    bytes, kind)], clamped). Every output is built in memory, on the file's BASE -- the vendor's original, or
    the base the record names for it: adopted by a take-over (tweaks_take_over), with the rows it keeps -- for
    the files the document rewrites and for the files the record names (one the document does not touch goes
    back to its base); the document is normalised against what those bases hold (tweaks_record_facts). A file
    is listed only when its bytes on disk differ: kind "restore" (the new bytes ARE a vendor's original: the
    catalogue's, or the one a record entry of a file the catalogue does not vouch for names; allowed at any
    time) or "write" (anything else, an adopted base too; only while the game server runs and can judge it).
    clamped = the reward and drop cells of the document a server cap limited.
    ONE SETTING AT A TIME: a file the document or the settings in effect rest on that cannot carry settings --
    missing, `changed` (`reasons`: {path: why the agent cannot take that change over}), built on another
    original than the catalogue's, a line-up script taken over with an entry above the line-up's level (for the
    enemy level of its domains alone), one whose output an editor refuses on an adopted base -- blocks the
    settings that rest on it (tweaks_blocked) and is never written; the plan brings the files in line with the
    EFFECTIVE document (tweaks_effective) -- the blocked settings at their value in effect. A `changed` or
    missing file is left alone; one the record names that the catalogue does not vouch for (_tweaks_foreign) is
    never forgotten while it still is the agent's: on a vendor's original it goes back to its own base copy
    ("restore"), on an adopted base it is left as it is.
    Raises AgentError: 400 for a document the catalogue does not allow, 400 / 500 from an editor (a row, a
    column or a slot that is not there; an extra item the reward already holds) on the vendor's original.
    info: a dict filled for the caller -- "doc" (the document, canonical), "effective" (canonical), "blocked"
    (the paths of the settings that are not applied, sorted), "unusable" ({path: (why, reason)}: why is
    "missing" | "changed" | "refused" | "level"), "facts" (what the bases hold: tweaks_facts). memo:
    tweaks_vendor_bytes -- and the bytes of an adopted base a take-over computed and nobody stored yet
    (memo[("adopted", path, md5)]: GET /server/tweaks)."""
    memo, seen = ({} if memo is None else memo), {}

    def look(rel):
        if rel not in seen:
            seen[rel] = tweaks_file(version, cat, record, rel, memo)
        return seen[rel]

    facts = tweaks_record_facts(version, cat, record, memo, seen)
    doc = normalise_tweaks(cat, doc, facts)
    active = record["active"]
    settings = set(tweaks_leaves(doc)) | set(tweaks_leaves(active))
    lineups = dict((lineup["file"], (gid, lineup["level"]))
                   for gid, lineup in (cat["domains"].get("lineups") or {}).items())
    rests = tweaks_setting_files(cat, settings)

    def foreign_file(rel, disk):
        return _tweaks_foreign_md5(cat, record, rel, None if disk is None else hashlib.md5(disk).hexdigest())

    unusable, locked = {}, {}
    for rel in sorted(set(r for writes, needs in rests.values() for r in writes | needs)):
        state, disk, _base = look(rel)
        entry = record["files"].get(rel)
        if state == "missing":
            unusable[rel] = ("missing", TWEAKS_WHY_MISSING, False)
        elif foreign_file(rel, disk):
            unusable[rel] = ("changed", TWEAKS_WHY_FOREIGN, state == "ours" and not _tweaks_taken(entry))
        elif state == "changed":
            unusable[rel] = ("changed", (reasons or {}).get(rel) or _tweaks_changed_why(
                entry, None if disk is None else hashlib.md5(disk).hexdigest()), False)
        elif rel in lineups and state == "ours" and _tweaks_taken(entry):
            gid, level = lineups[rel]
            if facts["maxLevel"].get(gid) is None or facts["maxLevel"][gid] > level:
                locked[rel] = ("level", _tweaks_level_reason(level))
    while True:
        blocked = tweaks_blocked(cat, settings, unusable, locked)
        effective = normalise_tweaks(cat, tweaks_effective(doc, active, blocked), facts)
        edits = tweaks_edits(cat, effective, facts)
        needed = set(edits) | _tweaks_level_scripts(cat, effective)
        changes, clamped, failed = [], 0, None
        for rel in sorted(needed | set(record["files"])):
            state, disk, base = look(rel)
            entry = record["files"].get(rel)
            foreign = foreign_file(rel, disk)
            if state in ("changed", "missing") or (foreign and _tweaks_taken(entry)) \
                    or (rel in unusable and not unusable[rel][2]):
                continue
            new = base
            if rel in edits and not foreign:
                # (the rows a take-over keeps, while the entry's base is the base built on)
                kept = entry.get("kept") or () if entry is not None and state in ("ours", "original") \
                    and entry["base"].lower() == hashlib.md5(base).hexdigest() else ()
                try:
                    new, n = tweaks_output(cat, edits[rel], base, rel, kept)
                except AgentError as e:
                    if e.status != 500 or not (state == "ours" and _tweaks_taken(entry)):
                        raise
                    failed = (rel, e.message.split(" -- ")[0])  # (an adopted base the editor refuses)
                    break
                clamped += n
            if new != disk:
                # (a restore only when the bytes ARE a vendor's original -- for a file the catalogue does not vouch
                #  for, the one its entry was built on, or taken over from: never an adopted base)
                vendor = str(((entry["taken"]["vendor"] if _tweaks_taken(entry) else entry["base"]) if foreign
                              else cat["files"].get(rel)) or "").lower()
                changes.append((rel, new, "restore" if hashlib.md5(new).hexdigest() == vendor else "write"))
        if failed is None:
            break
        unusable[failed[0]] = ("refused", failed[1], False)
    if info is not None:
        why = dict((rel, u[:2]) for rel, u in unusable.items())
        why.update(locked)
        info.update(doc=doc, effective=effective, blocked=sorted(blocked), unusable=why, facts=facts)
    return changes, clamped


def _probe_tweaks_plan(version, changes):
    """Every target of a plan rewritten with its OWN bytes, the way the plan will write it
    (_probe_internal_plan's idea): a file that cannot be replaced -- read-only, held open by another program
    -- is found before anything is recorded. Returns [(path, the bytes it holds)], last target first: what
    _undo_tweaks_plan puts back when the server refuses the change. Raises AgentError (409 a target that is
    gone, 500 one that cannot be replaced); nothing changed."""
    previous = []
    for rel, _new, _kind in changes:
        data = _tweaks_read(tweaks_path(version, rel))
        if data is None:
            raise _tweaks_unusable(rel, "missing")
        previous.append((rel, data))
    try:
        _write_tweak_files(version, previous)
    except OSError as e:
        raise AgentError(500, "Gameplay settings: a data file of the server cannot be replaced (%s) -- nothing of "
                              "the change was written." % e)
    return previous[::-1]


def _apply_tweaks_plan(version, cat, record, doc, changes):
    """A plan carried out in the order that keeps every moment recoverable:
    1. the base copy of each `original` file that is about to be rewritten -- the original is in
       <stack>/.relic-tweaks/base before its file changes --, and a copy of what each file on an adopted base
       holds before it is rewritten (.relic-tweaks/prev/<path>: what the leftover rule gives it back);
    2. the record: `tweaks` = the wanted document and, per file about to be written, its entry with `out` = the
       md5 of the new bytes and ok: false (+ prev = the md5 of the agent's own earlier output it replaces) --
       BEFORE the first file, so a run that dies in the middle leaves a record that knows every file as its own
       and says which ones no server has confirmed. A file that was `ours` keeps everything else of its entry --
       its base (an adopted one too), taken, kept rows, undo, released --; one that was `original` gets a new
       entry on the vendor's original, which keeps `released` -- and the kept rows of an entry on that very
       original. The entry of a file that is restored stays until tweaks_mark_confirmed;
    3. the files, back to back (_write_tweak_files).
    `doc` None leaves `tweaks` as it is: the files are brought back in line with the document in effect while
    the stored one stands refused (tweaks_after_start); a document is normalised against the stack's bases.
    Returns the record as written; `active` and `refused` are the caller's (tweaks_mark_confirmed /
    tweaks_mark_refused). Raises AgentError: 409 for a target that is neither `original` nor `ours` by then,
    507 for a write that failed -- the files step 3 had replaced are put back first (every one that can be:
    _put_back_tweak_files) and, once they all are, the record; while one is not, the record goes on naming
    every written file as unconfirmed."""
    doc = record["tweaks"] if doc is None else normalise_tweaks(cat, doc, tweaks_record_facts(version, cat, record))
    files = {rel: dict(entry) for rel, entry in record["files"].items()}
    previous = []
    for rel, new, kind in changes:
        state, disk, _original = tweaks_file(version, cat, record, rel)
        if state not in ("original", "ours"):
            raise _tweaks_unusable(rel, state)  # it changed after the plan was made
        previous.append((rel, disk))
        if kind != "write":
            continue
        old = record["files"].get(rel) or {}
        if state == "ours":
            entry = {k: v for k, v in old.items() if k != "away"}
            entry.update(out=hashlib.md5(new).hexdigest(), ok=False, prev=hashlib.md5(disk).hexdigest())
            if _tweaks_taken(old) and _tweaks_read(tweaks_prev_path(version, rel)) != disk:
                # (what the leftover rule gives a file on an adopted base back when this write gets no verdict)
                try:
                    _write_tweaks_own(version, tweaks_prev_path(version, rel), disk)
                except OSError as e:
                    raise AgentError(507, "Gameplay settings: what %s holds could not be kept (%s) -- nothing of the "
                                          "change was written." % (rel, e))
        else:
            entry = {"base": cat["files"][rel].lower(), "out": hashlib.md5(new).hexdigest(), "ok": False}
            for key in ("released", "kept") if str(old.get("base") or "").lower() == entry["base"] else ("released",):
                if key in old:
                    entry[key] = old[key]
            if _tweaks_read(tweaks_base_path(version, rel)) != disk:
                try:
                    _write_tweaks_own(version, tweaks_base_path(version, rel), disk)
                except OSError as e:
                    raise AgentError(507, "Gameplay settings: the original of %s could not be kept (%s) -- nothing of "
                                          "the change was written." % (rel, e))
        files[rel] = entry
    after = write_tweaks_record(version, dict(record, tweaks=doc, files=files))
    try:
        _write_tweak_files(version, [(rel, new) for rel, new, _kind in changes])
    except OSError as e:
        back = "the previous files are back in place"
        stuck = _put_back_tweak_files(version, previous[::-1])
        if stuck:
            back = "the previous files could NOT all be put back (%s); %s" % (_tweaks_stuck_text(stuck),
                                                                            _TWEAKS_LEFTOVER_NOTE)
        else:
            try:
                write_tweaks_record(version, record)
            except AgentError:
                back += ", but the record still lists them as unconfirmed; " + _TWEAKS_LEFTOVER_NOTE
        raise AgentError(507, "Gameplay settings: the server's data files could not be written (%s) -- %s." % (e, back))
    return after


def tweaks_mark_wanted(version, record, doc):
    """A document stored without a file being touched: it is what the admin wants (`tweaks`), nothing says the
    server refused it, and `active` stays what the files hold -- the next Start applies it. Returns the record
    as written."""
    return write_tweaks_record(version, dict(record, tweaks=doc, refused=None))


def _tweaks_held_files(version, cat, record):
    """`files` as a record says it once the server accepted what is on disk: every file that holds an output of
    the agent at this moment, ok, with everything its entry says of its base -- base, taken, kept rows,
    released -- and `undo` only while this was no write of it (an ACCEPTED write of a file makes the agent's
    output on its base the state the settings are in); the entry of a file that is the vendor's original again
    (a restore, a re-extracted archive) leaves the record -- unless it is an entry on that very original that
    keeps rows or names bytes a Revert or a Reset let go (`released`): it stays, ok; a file taken over that is
    back at the original its take-over names keeps an entry on it for the bytes it let go. PROVENANCE IS NEVER
    DROPPED: the entry of a file somebody else changed, or that is missing, stays as it was (`away`, ok, no prev
    -- what is on disk was made on top of what the agent last wrote, `out`): it is what proves the agent's own
    part of the file to a take-over (tweaks_take_over). The entry of a file the catalogue does not vouch for
    (_tweaks_foreign) stays as it is for as long as the file still is the agent's: no verdict was about it, and
    forgetting it would leave the file tweaked for good."""
    files = {}
    for rel, entry in record["files"].items():
        state, disk, _original = tweaks_file(version, cat, record, rel)
        if state == "ours" and _tweaks_foreign(cat, record, rel):
            files[rel] = dict(entry)
        elif state == "ours":
            held = {k: v for k, v in entry.items() if k not in ("prev", "away")}
            held.update(out=hashlib.md5(disk).hexdigest(), ok=True)
            if not entry["ok"]:
                held.pop("undo", None)
            files[rel] = held
        elif state in ("changed", "missing"):
            files[rel] = dict({k: v for k, v in entry.items() if k != "prev"}, ok=True, away=True)
        elif state == "original" and (entry.get("kept") or entry.get("released")) \
                and entry["base"].lower() == hashlib.md5(disk).hexdigest():
            files[rel] = dict(((k, entry[k]) for k in ("kept", "released") if entry.get(k)),
                              base=entry["base"], out=hashlib.md5(disk).hexdigest(), ok=True)
        elif state == "original" and _tweaks_taken(entry) and entry.get("released") \
                and entry["taken"]["vendor"].lower() == hashlib.md5(disk).hexdigest():
            # (a file taken over that is back at its vendor's original: what it let go stays known)
            md5 = hashlib.md5(disk).hexdigest()
            files[rel] = {"base": md5, "out": md5, "ok": True, "released": entry["released"]}
    return files


def tweaks_mark_confirmed(version, cat, record, active=None):
    """The files on disk are what `tweaks` asks for -- as far as its settings can be applied: `active` (given)
    is the EFFECTIVE document (tweaks_plan's info), `tweaks` itself when not given -- and the server accepted
    them (or only originals were put back, or nothing had to change): `active` = that document, nothing
    refused, and `files` = the files that hold an output of the agent at this moment (_tweaks_held_files).
    Returns the record as written."""
    return write_tweaks_record(version, dict(record, active=record["tweaks"] if active is None else active,
                                             refused=None, files=_tweaks_held_files(version, cat, record)))


def _tweaks_unread(record, flag):
    """The record with `unread` set (flag) or gone: the key is written only while it is true. Pure."""
    return dict(record, unread=True) if flag else {k: v for k, v in record.items() if k != "unread"}


def _tweaks_mark_read(version, record, job=None):
    """The record without `unread`, written only when it had the key. Returns the record as it is now. With a job,
    a record that cannot be written is a WARNING instead of the 507 -- the mark stays, and the next Apply asks
    the services again."""
    if not record.get("unread"):
        return record
    try:
        return write_tweaks_record(version, _tweaks_unread(record, False))
    except AgentError as e:
        if job is None:
            raise
        job.log("WARNING: %s The record still says that not every service read the data files: the next Apply asks "
                "them again." % e.message)
        return record


def tweaks_mark_refused(version, record, files_before, error):
    """The server refused what was written and the previous bytes are back: `files` as it was before the
    apply, `tweaks` stays the refused document and `refused` = {at, error, digest} -- the digest is what keeps
    a Start from handing the server the same document again. Returns the record as written."""
    refused = {"at": int(time.time()), "error": str(error)[:2000], "digest": tweaks_digest(record["tweaks"])}
    return write_tweaks_record(version, dict(record, files=files_before, refused=refused))


def _undo_tweaks_plan(version, previous):
    """What _probe_tweaks_plan handed back, written again: the bytes every target held before the apply, last
    target first -- every file that can be written, past one that cannot (_put_back_tweak_files). Raises
    AgentError(507) naming the files that still hold what the apply wrote; the record _apply_tweaks_plan
    wrote goes on naming every written file as unconfirmed then, which is what puts the originals back
    before a game service boots."""
    stuck = _put_back_tweak_files(version, previous)
    if stuck:
        raise AgentError(507, "Gameplay settings: the previous data files could not all be put back (%s) -- %s."
                         % (_tweaks_stuck_text(stuck), _TWEAKS_LEFTOVER_NOTE))


def tweaks_prune_active(cat, active, lost):
    """`active` without every setting that writes a file of `lost` (paths): the files that no longer hold what the
    agent had in them as the server accepted it -- the vendor's original put back (the leftover rule, a Revert, a
    Reset) or the bytes a refused write replaced put back. Such a setting is not in that file any more, so
    `active` -- what EVERY file holds -- loses it, whatever its other files hold (tweaks_setting_files): what the
    agent had in a file is proven from `active` (tweaks_take_over), and a setting a file does not hold would make
    rows of it look changed by hand. Without a catalogue nothing says which file a setting writes: none of
    `active` once a file was lost, all of it otherwise. Pure."""
    lost = set(lost)
    if not lost:
        return active
    if cat is None:
        return {}
    leaves = tweaks_leaves(active)
    writes = tweaks_setting_files(cat, leaves)
    return tweaks_from_leaves(dict((path, value) for path, value in leaves.items() if not writes[path][0] & lost))


def _tweaks_on_original(cat, rel, entry, md5, fields):
    """The entry of a file that holds a vendor's original again -- `md5`: the one `entry` was built on, or the one a
    take-over of it names -- when that entry still says something of it: {"base": md5, "out": md5, "ok": true} with
    what of `fields` it names (the rows a take-over keeps on that very original, the md5s of bytes a Revert or a
    Reset let go, the revert point) -- None when it names none of them, and for an original the catalogue does
    not pin (`cat`; nothing is built on such a file again). Pure."""
    md5 = md5.lower()
    if cat is not None and md5 != str(cat["files"].get(rel) or "").lower():
        return None
    carried = dict((k, entry[k]) for k in fields if entry.get(k))
    return dict(carried, base=md5, out=md5, ok=True) if carried else None


def tweaks_restore_originals(version, record, unread=False, cat=None, job=None):
    """The rule for a record that names a file no server has confirmed -- THE LEFTOVER RULE. Every file of the
    record that still holds the agent's output goes back to what no verdict is missing for -- the one write that
    is allowed while a stack is down:
    - an entry on the vendor's original (the md5 its entry names as `base`: the base copy, the shipped
      archive) gets that original back, confirmed or not -- what the server accepted was the set; its entry
      stays, on that original, while it names rows a take-over keeps, bytes a Revert or a Reset let go or a revert
      point (_tweaks_on_original), and leaves the record otherwise;
    - an entry whose base was adopted (_tweaks_taken) never gets that base: confirmed (ok), its bytes are the
      agent's accepted output or the admin's own and stay; unconfirmed, it gets back the bytes it held before the
      write that no verdict came for -- the copy kept before that write (.relic-tweaks/prev/<path>, see
      _apply_tweaks_plan), else its output of the settings in effect on its base with its kept rows, built again
      -- when their md5 is the entry's `prev`; when no such bytes are there (or the catalogue is not there to build
      them), a copy of what it holds goes to <stack>/.relic-tweaks/hand/ and the vendor's original replaces it
      (the md5 its take-over names, `taken.vendor`). One back at that original keeps an entry on it for the bytes
      it let go (`released`).
    A file somebody else changed in the meantime is left alone, and so is one that is missing: their entries
    stay (`away`, ok -- the provenance of a later take-over). `active` loses every setting that writes a file
    the rule leaves on a vendor's original (tweaks_prune_active): such a file does not hold it any more. The
    wanted document stays. unread: the services that run may not read the files by themselves -- once a file was
    written the record says so (`unread`). cat: the catalogue (read when not given; the rule works without one:
    an original is what an entry names). job: where the copies kept and an archive that cannot be read are said.
    Returns (the record as written, [paths written], [paths left alone]). A file that cannot be written -- or
    whose original is not available -- does not stop the others (_put_back_tweak_files): every file that can be
    is put back, the record keeps the entries of the ones that are not -- each as unconfirmed, so the rule runs
    again before the next boot -- and AgentError(507) names them."""
    cat = read_tweaks_catalog(version) if cat is None else cat
    items, left, keep, lost, hands, fail, memo, facts = [], [], {}, set(), [], [], {}, None
    for rel in sorted(record["files"]):
        entry = record["files"][rel]
        if not _tweaks_taken(entry):
            state, _disk, original = _tweaks_file(version, rel, entry["base"].lower(), entry, memo)
            if state in ("ours", "original"):
                if state == "ours":
                    items.append((rel, original))
                lost.add(rel)
                on = _tweaks_on_original(cat, rel, entry, entry["base"], ("kept", "released", "undo"))
                if on is not None:
                    keep[rel] = on
            else:
                left.append(rel)
                keep[rel] = dict({k: v for k, v in entry.items() if k != "prev"}, ok=True, away=True)
            continue
        disk = _tweaks_read(tweaks_path(version, rel))
        md5 = None if disk is None else hashlib.md5(disk).hexdigest()
        mine = md5 is not None and md5 in (entry["out"], entry.get("prev"))
        vendor = entry["taken"]["vendor"].lower()
        if not mine and md5 == vendor:
            # (back at the vendor's original: nothing of the agent is left in it -- only what it let go stays known)
            lost.add(rel)
            on = _tweaks_on_original(cat, rel, entry, vendor, ("released",))
            if on is not None:
                keep[rel] = on
            continue
        if not mine:
            left.append(rel)
            keep[rel] = dict({k: v for k, v in entry.items() if k != "prev"}, ok=True, away=True)
            continue
        if entry["ok"]:
            keep[rel] = entry
            continue
        before = None
        try:
            copy = _tweaks_read(tweaks_prev_path(version, rel))
        except AgentError:
            copy = None
        if copy is not None and hashlib.md5(copy).hexdigest() == entry.get("prev"):
            before = copy
        elif entry.get("prev") == vendor:
            # (the vendor's original held it before: a Revert put it there, its base waiting on the write)
            before = tweaks_vendor_bytes(version, rel, vendor, memo=memo)
        elif cat is not None and "prev" in entry:
            try:
                base = _tweaks_entry_base(version, rel, entry, memo)
                if facts is None:
                    facts = tweaks_record_facts(version, cat, record, memo)
                edits = tweaks_edits(cat, normalise_tweaks(cat, record["active"], facts), facts)
                if base is not None:
                    before = tweaks_output(cat, edits[rel], base, rel, entry.get("kept") or ())[0] \
                        if rel in edits else base
            except Exception:  # noqa: BLE001 -- what cannot be rebuilt is not put back: the original goes in
                before = None
        if before is not None and hashlib.md5(before).hexdigest() == entry["prev"]:
            if before != disk:
                items.append((rel, before))
            keep[rel] = dict({k: v for k, v in entry.items() if k not in ("prev", "away")}, out=entry["prev"], ok=True)
            continue
        original = tweaks_vendor_bytes(version, rel, vendor, memo=memo)
        if original is None:
            fail.append((rel, "its original is not available"))
            keep[rel] = entry
            continue
        hands.append((rel, disk))
        items.append((rel, original))
        lost.add(rel)
    for rel, data in hands:
        try:
            _write_tweaks_own(version, tweaks_hand_path(version, rel), data)
        except OSError as e:
            # (no copy, no original over the bytes: the entry stays unconfirmed, the rule comes back for it)
            items = [(r, d) for r, d in items if r != rel]
            fail.append((rel, "a copy of it could not be kept (%s)" % e))
            keep[rel] = record["files"][rel]
    if job is not None:
        kept_copies = [rel for rel, _data in hands if rel not in dict(fail)]
        if kept_copies:
            job.log("Gameplay settings: what %s held is kept in %s before the original goes back."
                    % (", ".join(kept_copies), os.path.join(stack_dir(version), TWEAKS_DIR, "hand")))
        if memo.get(None):
            job.log("WARNING: Gameplay settings: %s -- the originals it holds are not available." % memo[None])
    stuck = _put_back_tweak_files(version, items) + fail
    files = dict(keep)
    for rel, _why in stuck:
        # (still holding what no verdict was about: unconfirmed, the rule runs again -- `active` already says what
        #  the file holds once it has: the original for one that goes back to it, what it held before otherwise)
        files[rel] = dict(record["files"][rel], ok=False)
    try:
        after = write_tweaks_record(version, dict(record, files=files, active=tweaks_prune_active(
            cat, record["active"], lost), **({"unread": True} if unread and items else {})))
    except AgentError:
        if not stuck:
            raise
    if stuck:
        raise AgentError(507, "Gameplay settings: the original data files could not all be put back (%s)."
                         % _tweaks_stuck_text(stuck))
    return after, [rel for rel, _data in items], left


# -- a file changed outside Relic: the take-over --
# A file somebody changed by hand (H: neither the vendor's original nor what the record names as the agent's) is
# TAKEN OVER when every check of tweaks_take_over holds: what the agent last had in it (O) is proven -- built
# again from the entry's base and the settings in effect, it has the md5 the entry names --, the change is one
# the agent can keep (the same columns, rows of the right width, every row and spawn slot the catalogue names
# there once, a script changed in its spawn slots alone), and the base it would build on is one the server
# accepts. O and H are paired line by line WITHOUT their line ends: table rows by their first cell (the k-th
# occurrence of an id with the k-th), spawn slots by their config id, every other line of a script by its place.
# A row or slot equal to its pair is the agent's: the new base gets the line of the old base (the agent's own
# part taken out) with H's line end. One that differs -- or that only H has -- is the hand's: the new base gets
# it whole, and what the documents say of it gives way: a value set on it (the resin row, a chamber's level, a
# domain's cost and enemy level, a slot's monster) leaves both documents -- the line holds it now --, a row a
# multiplier or an extra item touched is KEPT (no multiplier and no extra item touches it from then on, and the
# extra items and own multiplier of a domain whose reward row is kept leave the documents), and an own reward of
# a hand-changed reward row leaves them unless the row hands out exactly that. A table that holds not one row as
# the settings in effect gave it, with rows of a multiplier or of the cost for all domains back at the base, was
# put back outside Relic and changed (a package extracted again, a copy restored): the change is the one from the
# base -- H is the new base whole -- and the settings that write the file leave the document in effect, to apply
# on it again (_tweaks_replaced). Then the proof: the settings left in effect, built on the new base, give H back
# byte for byte -- else nothing is taken over. Without an entry nothing proves a part of the agent's in the file:
# O must be the vendor's original. A take-over writes no data file.
TWEAKS_UNPROVEN = "Relic cannot tell its own changes from the ones made by hand"


class _TakeOverRefused(Exception):
    """Why a file is not taken over (tweaks_take_over): a stable code and the sentence that says it."""

    def __init__(self, code, reason):
        super().__init__(reason)
        self.code, self.reason = code, reason


def _tweaks_foreign_entry(cat, rel, entry):
    """_tweaks_foreign for one entry of the record. Pure."""
    want = str(cat["files"].get(rel) or "").lower()
    if _tweaks_taken(entry):
        return entry["taken"]["vendor"].lower() != want
    return entry["base"].lower() != want


def _tweaks_catalogue_rows(cat, rel):
    """The ids of the rows of a table the catalogue names (the editors and the readers ask for each of them
    exactly once). Pure."""
    rows, daily = set(), cat["quests"]["daily"]
    if rel == cat["resin"]["file"]:
        rows.add(cat["resin"]["row"])
    if rel == cat["abyss"]["levelFile"]:
        rows.update(cat["abyss"]["chambers"])
    if rel == cat["domains"]["file"]:
        rows.update(cat["domains"]["list"])
    if rel == cat["domains"]["dropFile"]:
        rows.update(str(d["root"]) for d in cat["domains"]["list"].values())
    if rel == daily["file"]:
        rows.update(str(r) for r in daily["drops"])
    if rel == cat["quests"]["file"]:
        rows.update(cat["quests"]["rewards"])
    return rows


def _tweaks_doc_drop(doc, *path):
    """The setting at `path` taken out of a document (in place), the objects it leaves empty with it."""
    nodes = [doc]
    for key in path[:-1]:
        node = nodes[-1].get(key)
        if not isinstance(node, dict):
            return
        nodes.append(node)
    nodes[-1].pop(path[-1], None)
    for depth in range(len(path) - 1, 0, -1):
        if nodes[depth]:
            break
        nodes[depth - 1].pop(path[depth - 1], None)


def _tweaks_doc_set(doc, value, *path):
    """The setting at `path` of a document set (in place)."""
    node = doc
    for key in path[:-1]:
        node = node.setdefault(key, {})
    node[path[-1]] = value


def _tweaks_output_of(cat, doc, facts, base, rel, kept=()):
    """The bytes one file must hold for a canonical document on a base (tweaks_edits + tweaks_output). Pure."""
    edits = tweaks_edits(cat, doc, facts)
    return tweaks_output(cat, edits[rel], base, rel, kept)[0] if rel in edits else base


def _tweaks_merge_table(cat, rel, base, mine, hand):
    """The new base of a hand-changed TABLE: (bytes, [(row id, the hand's line)] of the rows that differ) -- O
    (`mine`) and H paired by the first cell of their rows (the k-th occurrence of an id with the k-th), compared
    without their line ends: a row equal to its pair takes the line of the old base, any other takes H's line; H's
    order and H's line ends. Raises _TakeOverRefused for a change the agent cannot keep. Pure."""
    name = rel.rsplit("/", 1)[-1]
    _tweaks_take_text(hand, name)
    try:
        h_lines, h_ends, _cols = _tweak_table(hand, name)
    except AgentError:
        raise _TakeOverRefused("columns", "it has no header line")
    o_lines = _tweak_table(mine, name)[0]
    b_lines = _tweak_table(base, name)[0]
    if len(o_lines) != len(b_lines):
        raise _TakeOverRefused("unproven", TWEAKS_UNPROVEN)
    if h_lines[0] != o_lines[0]:
        raise _TakeOverRefused("columns", "the columns of this table were changed outside Relic")
    width = h_lines[0].count("\t")
    for n in range(1, len(h_lines)):
        if h_lines[n].strip() and h_lines[n].count("\t") != width:
            raise _TakeOverRefused("shape", "line %d has %d cells where the header has %d -- the server refuses the "
                                            "whole table over it" % (n + 1, h_lines[n].count("\t") + 1, width + 1))
    count = {}
    for line in h_lines[1:]:
        first = line.split("\t", 1)[0]
        count[first] = count.get(first, 0) + 1
    for rid in sorted(_tweaks_catalogue_rows(cat, rel), key=lambda r: (len(r), r)):
        if count.get(rid, 0) != 1:
            raise _TakeOverRefused("rows", "row %s %s" % (rid, "is missing" if not count.get(rid)
                                                          else "is there %d times" % count[rid]))
    paired, seen = {}, {}
    for n in range(1, len(o_lines)):
        first = o_lines[n].split("\t", 1)[0]
        paired[(first, seen.get(first, 0))] = n
        seen[first] = seen.get(first, 0) + 1
    lines, hands, seen = [b_lines[0]], [], {}
    for n in range(1, len(h_lines)):
        first = h_lines[n].split("\t", 1)[0]
        mate = paired.get((first, seen.get(first, 0)))
        seen[first] = seen.get(first, 0) + 1
        if mate is not None and o_lines[mate] == h_lines[n]:
            lines.append(b_lines[mate])
        else:
            lines.append(h_lines[n])
            hands.append((first, h_lines[n]))
    return _tweak_join(lines, h_ends), hands


def _tweaks_take_text(data, name):
    """A hand-changed file must be text the editors read: UTF-8 without a byte order mark (_tweak_text) --
    _TakeOverRefused otherwise. Pure."""
    if data.startswith(b"\xef\xbb\xbf"):
        raise _TakeOverRefused("encoding", "it starts with a byte order mark")
    try:
        data.decode("utf-8")
    except UnicodeDecodeError:
        raise _TakeOverRefused("encoding", "it is not valid UTF-8")


def _tweaks_script_lines(data):
    """(lines without their ends, their ends, the byte offset each starts at) of a script (bytes) -- the
    pieces _tweak_table cuts a table into, as bytes: what follows the last line break is a line of its own
    when it is not empty. Pure."""
    pieces = data.split(b"\n")
    tail = pieces.pop()
    lines, ends, starts, pos = [], [], [], 0
    for n, piece in enumerate(pieces + ([tail] if tail else [])):
        cr = piece.endswith(b"\r")
        lines.append(piece[:-1] if cr else piece)
        ends.append((b"\r" if cr else b"") + (b"\n" if n < len(pieces) else b""))
        starts.append(pos)
        pos += len(piece) + 1
    return lines, ends, starts


def _tweaks_merge_script(cat, rel, group, base, mine, hand):
    """The new base of a hand-changed monster-group SCRIPT: (bytes, [config ids of the spawn slots that differ])
    -- the spawn-slot entries of O (`mine`) and H paired by config id (the k-th entry of an id with the k-th),
    compared without their line ends: an entry equal to its pair takes the line of the old base, any other takes
    H's; every other line must be O's, in O's order. H's order, H's line ends. Raises _TakeOverRefused for a
    change the agent cannot keep. Pure."""
    name = rel.rsplit("/", 1)[-1]
    _tweaks_take_text(hand, name)
    try:
        h_slots = _tweak_slot_lines(hand, name)
    except AgentError:
        raise _TakeOverRefused("script", "its monsters table is not one Relic can edit")
    have = {}
    for _pos, _length, m in h_slots:
        cfg = m.group("cfg").decode()
        have[cfg] = have.get(cfg, 0) + 1
    for cfg in sorted(group["slots"], key=lambda c: (len(c), c)):
        if have.get(cfg, 0) != 1:
            raise _TakeOverRefused("rows", "spawn slot %s %s" % (cfg, "is missing" if not have.get(cfg)
                                                                 else "is there %d times" % have[cfg]))

    def parts(data):
        lines, ends, starts = _tweaks_script_lines(data)
        at = dict((pos, n) for n, pos in enumerate(starts))
        slots = dict((at[pos], m.group("cfg").decode()) for pos, _length, m in _tweak_slot_lines(data, name))
        return lines, ends, slots

    o_lines, _o_ends, o_slots = parts(mine)
    b_lines, _b_ends, b_slots = parts(base)
    h_lines, h_ends, h_slots = parts(hand)
    if len(o_lines) != len(b_lines) or o_slots != b_slots:
        raise _TakeOverRefused("unproven", TWEAKS_UNPROVEN)
    if [line for n, line in enumerate(o_lines) if n not in o_slots] \
            != [line for n, line in enumerate(h_lines) if n not in h_slots]:
        raise _TakeOverRefused("script", "it was changed outside Relic beyond its spawn slots")
    paired, seen = {}, {}
    for n in sorted(o_slots):
        cfg = o_slots[n]
        paired[(cfg, seen.get(cfg, 0))] = n
        seen[cfg] = seen.get(cfg, 0) + 1
    lines, hands, seen = [], [], {}
    for n, line in enumerate(h_lines):
        if n not in h_slots:
            lines.append(line)
            continue
        cfg = h_slots[n]
        mate = paired.get((cfg, seen.get(cfg, 0)))
        seen[cfg] = seen.get(cfg, 0) + 1
        if mate is not None and o_lines[mate] == line:
            lines.append(b_lines[mate])
        else:
            lines.append(line)
            hands.append(cfg)
    return b"".join(line + end for line, end in zip(lines, h_ends)), hands


def _tweaks_hand_effects(cat, rel, header, hands, active, tweaks, kept):
    """What the hand-changed rows of a table do to the documents and to the kept rows -> (active, tweaks, kept):
    new objects. A value set on a hand row leaves both documents (the base holds it now) -- the cost of a
    domain whose cost came from the one for all domains becomes its own, the value the row holds, so that the
    common one does not reach it; a row a multiplier or an extra item touched in O (the settings in effect) is
    kept, and a kept reward row of a domain takes the domain's extra items and own multiplier out of both
    documents; an own reward of a hand row leaves a document unless the row hands out exactly what it names;
    a reward row a multiplier would touch with its own reward gone is kept. Raises AgentError for a cell that
    is not a number. Pure."""
    active, tweaks = json.loads(json.dumps(active)), json.loads(json.dumps(tweaks))
    kept, name = set(kept), rel.rsplit("/", 1)[-1]
    cols = {}
    for i, title in enumerate(header.split("\t")):
        cols.setdefault(title, i)
    roots = dict((str(d["root"]), did) for did, d in cat["domains"]["list"].items())
    daily, rewards = cat["quests"]["daily"], cat["quests"]["rewards"]
    for rid, line in hands:
        cells = line.split("\t")
        if rel == cat["resin"]["file"] and rid == cat["resin"]["row"]:
            for doc in (active, tweaks):
                _tweaks_doc_drop(doc, "resin", "cap")
                _tweaks_doc_drop(doc, "resin", "minutes")
        if rel == cat["abyss"]["levelFile"] and rid in cat["abyss"]["chambers"]:
            for doc in (active, tweaks):
                _tweaks_doc_drop(doc, "abyss", "levels", rid)
        if rel == cat["domains"]["file"] and rid in cat["domains"]["list"]:
            cost = _tweak_number(cells[_tweak_column(cols, _COL_STATUE_COST, name, "the cost of the reward statue")],
                                 name, "the cost of the reward statue of row %s" % rid)
            for doc in (active, tweaks):
                if "cost" in (doc.get("domains") or {}):
                    _tweaks_doc_set(doc, cost, "domains", "byId", rid, "cost")
                else:
                    _tweaks_doc_drop(doc, "domains", "byId", rid, "cost")
                _tweaks_doc_drop(doc, "domains", "byId", rid, "level")
        if rel == cat["domains"]["dropFile"] and rid in roots:
            did = roots[rid]
            dom = active.get("domains") or {}
            own = (dom.get("byId") or {}).get(did) or {}
            mult = min(own.get("multiplier", dom.get("multiplier", 1)), TWEAK_LIMITS["multiplierMax"],
                       cat["domains"]["list"][did]["max"])
            if rid in kept or mult != 1 or own.get("extra"):
                kept.add(rid)
                for doc in (active, tweaks):
                    _tweaks_doc_drop(doc, "domains", "byId", did, "extra")
                    _tweaks_doc_drop(doc, "domains", "byId", did, "multiplier")
        if rel == daily["file"] and rid in set(str(r) for r in daily["drops"]):
            if rid in kept or ((active.get("quests") or {}).get("multiplier") or {}).get("commission", 1) != 1:
                kept.add(rid)
        if rel == cat["quests"]["file"] and rid in rewards:
            scalars, slots = _tweak_reward_layout(cols, name)
            given = _tweak_reward_content(cells, scalars, slots, name)
            for doc in (active, tweaks):
                own = ((doc.get("quests") or {}).get("byReward") or {}).get(rid)
                if own is not None and given != dict((e["item"], e["count"]) for e in own.get("items") or []):
                    _tweaks_doc_drop(doc, "quests", "byReward", rid)
            quests = active.get("quests") or {}
            if rid in kept or ((quests.get("multiplier") or {}).get(rewards[rid]["kind"], 1) != 1
                               and rid not in (quests.get("byReward") or {})):
                kept.add(rid)
    return active, tweaks, kept


def tweaks_take_over(cat, rel, entry, base, hand, active, tweaks, facts):
    """THE TAKE-OVER of one hand-changed target file, computed -- PURE: nothing is read or written. `entry` =
    the record's entry for the file (None: the agent never wrote it, or an agent that knew no take-over forgot
    it); `base` = the bytes of the base that entry names (the vendor's original without an entry), None when
    they are not there; `hand` = the file's bytes (H); `active` / `tweaks` = the record's documents, canonical
    against `facts` (tweaks_facts of the bases as the record names them). Returns {"ok": True, "base": the new
    base, "kept": [row ids], "active", "tweaks": the documents after it (canonical against the new base),
    "keys": {setting path: {"active", "tweaks": its values before -- None = absent}} of every setting it changed,
    "rows": [the row ids / slot config ids the hand changed], "facts": tweaks_facts with the new base,
    "replaced": the file was put back outside Relic and changed (_tweaks_replaced) -- the change is the one from the
    base, and the settings that write the file left the document in effect: they apply on it again} -- or
    {"ok": False, "code", "reason"} when the file is NOT taken over, and why:
      foreign   -- the entry was built on another vendor's original than the catalogue's (only a Reset helps);
      released  -- H is the bytes a Revert or a Reset let go;
      unproven  -- what the agent last had in the file cannot be told (its base is gone, or built again from it
                   and the settings in effect it does not have the md5 the entry names);
      encoding  -- not UTF-8 without a byte order mark;
      columns   -- not a table, or its header line is not O's;
      shape     -- a row that has not the header's number of cells (named);
      rows      -- a row or a spawn slot the catalogue names that is not there once (named);
      script    -- a script whose monsters table cannot be read, or changed outside its spawn slots;
      values    -- the base the agent would keep is not one the editors read or the server accepts (named);
      proof     -- the settings in effect, built on the new base, do not give H back byte for byte.
    An editor that raises anywhere in it is a reason, never an error of the caller."""
    try:
        return _tweaks_take_over(cat, rel, entry, base, hand, active, tweaks, facts)
    except _TakeOverRefused as r:
        return {"ok": False, "code": r.code, "reason": r.reason}
    except Exception as e:  # noqa: BLE001 -- a change the agent cannot keep is a reason, never a failed job or answer
        return {"ok": False, "code": "proof", "reason": "Relic cannot keep the file as it is (%s)" % _failure_text(e)}


def _tweaks_take_over(cat, rel, entry, base, hand, active, tweaks, facts):
    if rel not in cat["files"] or (entry is not None and _tweaks_foreign_entry(cat, rel, entry)):
        raise _TakeOverRefused("foreign", "Relic built it on another original of the file than the one its catalogue "
                                          "names -- only putting the original back helps")
    md5_hand = hashlib.md5(hand).hexdigest()
    if md5_hand in _tweaks_released(entry):
        raise _TakeOverRefused("released", "these are the bytes a Revert or a Reset of its card let go -- Relic does "
                                           "not take them over again")
    if base is None:
        raise _TakeOverRefused("unproven", TWEAKS_UNPROVEN)
    kept_before = list(entry.get("kept") or []) if entry is not None else []
    try:
        mine = _tweaks_output_of(cat, active, facts, base, rel, kept_before)
    except Exception:  # noqa: BLE001 -- what cannot be built again cannot be told apart from the hand's change
        raise _TakeOverRefused("unproven", TWEAKS_UNPROVEN)
    if entry is not None and hashlib.md5(mine).hexdigest() != entry["out"]:
        raise _TakeOverRefused("unproven", TWEAKS_UNPROVEN)
    # (without an entry nothing proves a part of the agent's in the file: what it had there can only be the vendor's
    #  original -- a document in effect that would have put more there describes a file this one never was)
    if entry is None and mine != base:
        raise _TakeOverRefused("unproven", TWEAKS_UNPROVEN)
    groups = _tweaks_groups(cat, "all")
    gid = next((g for g, group in groups.items() if group["file"] == rel), None)
    if gid is not None:
        new_base, slots = _tweaks_merge_script(cat, rel, groups[gid], base, mine, hand)
        section = "abyss" if gid in _tweaks_groups(cat, "abyss") else "domains"
        active2, tweaks2 = json.loads(json.dumps(active)), json.loads(json.dumps(tweaks))
        for cfg in slots:
            for doc in (active2, tweaks2):
                _tweaks_doc_drop(doc, section, "slots", gid, cfg)
        rows, kept, replaced = ["slot %s" % cfg for cfg in slots], set(kept_before), False
    else:
        new_base, hands = _tweaks_merge_table(cat, rel, base, mine, hand)
        replaced, effects_on = _tweaks_replaced(cat, rel, base, mine, hand, active, facts, kept_before), active
        kept_on = kept_before
        if replaced:
            # (put back outside Relic, then changed: the change is the one from the base -- the settings that write
            #  the file leave the document in effect, it holds none of them, and apply on it again; no row is kept
            #  anew, and a row an earlier take-over kept stays kept only while it holds the line it was kept with)
            new_base, hands = _tweaks_merge_table(cat, rel, base, base, hand)
            gone = set(rid for rid, _line in hands)
            effects_on = tweaks_prune_active(cat, active, [rel])
            kept_on = [rid for rid in kept_before if rid not in gone]
        try:
            header = _tweak_table(new_base, rel.rsplit("/", 1)[-1])[0][0]
            active2, tweaks2, kept = _tweaks_hand_effects(cat, rel, header, hands, effects_on, tweaks, kept_on)
        except AgentError as e:
            raise _TakeOverRefused("values", "the file Relic would keep is not one the game server accepts (%s)"
                                             % e.message.split(" -- ")[0])
        rows = [rid for rid, _line in hands]
    try:
        read = _tweaks_read_facts(cat, groups, rel, new_base)
    except AgentError as e:
        raise _TakeOverRefused("values", "the file Relic would keep is not one the game server accepts (%s)"
                                         % e.message.split(" -- ")[0])
    facts2 = _tweaks_facts_with(cat, groups, facts, rel, read)
    try:
        active2, tweaks2 = normalise_tweaks(cat, active2, facts2), normalise_tweaks(cat, tweaks2, facts2)
        again = _tweaks_output_of(cat, active2, facts2, new_base, rel, kept)
    except Exception as e:  # noqa: BLE001 -- settings that cannot be built on the new base: not taken over
        raise _TakeOverRefused("proof", "Relic cannot keep the file as it is with the settings in effect (%s)"
                                        % _failure_text(e))
    if again != hand:
        raise _TakeOverRefused("proof", "Relic cannot keep the file as it is with the settings in effect")
    before_a, before_t = tweaks_leaves(active), tweaks_leaves(tweaks)
    after_a, after_t = tweaks_leaves(active2), tweaks_leaves(tweaks2)
    keys = dict((path, {"active": before_a.get(path), "tweaks": before_t.get(path)})
                for path in sorted(set(before_a) | set(after_a) | set(before_t) | set(after_t))
                if before_a.get(path) != after_a.get(path) or before_t.get(path) != after_t.get(path))
    return {"ok": True, "base": new_base, "kept": sorted(kept, key=lambda r: (len(r), r)), "active": active2,
            "tweaks": tweaks2, "keys": keys, "rows": rows, "facts": facts2, "replaced": replaced}


def _tweaks_replaced(cat, rel, base, mine, hand, active, facts, kept):
    """Whether a hand-changed TABLE was REPLACED rather than edited row by row -- a package extracted again, a copy put
    back, then changed: not one row the settings in effect gave it (O = `mine`, built on `base` with the kept rows
    `kept`) is in it (`hand`) as they gave it, and of the rows a setting that reaches many rows gave it -- a quest
    or domain multiplier, the daily commissions, the cost for all domains -- two or more, at least one of them the
    base's again. Read as an edit, each such row would count as changed by hand while that setting applied to it:
    kept and never multiplied again, or given its value for good -- the whole file pinned by a copy put back. Rows
    pair as the merge pairs them (_tweaks_merge_table). Pure."""
    name = rel.rsplit("/", 1)[-1]
    broad = dict((path, value) for path, value in tweaks_leaves(active).items()
                 if path in ("domains.multiplier", "domains.cost") or path.startswith("quests.multiplier."))
    if not broad:
        return False
    try:
        o_lines, b_lines, h_lines = (_tweak_table(data, name)[0] for data in (mine, base, hand))
        wide_out = _tweak_table(_tweaks_output_of(cat, tweaks_from_leaves(broad), facts, base, rel, kept), name)[0]
    except Exception:  # noqa: BLE001 -- what cannot be read here is no evidence of a copy put back
        return False
    if not len(o_lines) == len(b_lines) == len(wide_out):
        return False
    touched = [n for n in range(1, len(o_lines)) if o_lines[n] != b_lines[n]]
    wide = [n for n in touched if wide_out[n] != b_lines[n]]
    if len(wide) < 2:
        return False
    paired, seen = {}, {}
    for n in range(1, len(o_lines)):
        first = o_lines[n].split("\t", 1)[0]
        paired[(first, seen.get(first, 0))] = n
        seen[first] = seen.get(first, 0) + 1
    mate, seen = {}, {}
    for line in h_lines[1:]:
        first = line.split("\t", 1)[0]
        n = paired.get((first, seen.get(first, 0)))
        seen[first] = seen.get(first, 0) + 1
        if n is not None:
            mate[n] = line
    if any(mate.get(n) == o_lines[n] for n in touched):
        return False
    return any(mate.get(n) == b_lines[n] for n in wide)


def tweaks_taken_key(bases):
    """The guard of POST /server/tweaks: sha256 over the lines "<path> <md5 of its base>\\n", sorted, of every file
    whose base is not the vendor's original (`bases`: {path: md5}) -- "" when there is none. A take-over GET
    computed and the same one a job stored give the same key. Pure."""
    if not bases:
        return ""
    lines = "".join("%s %s\n" % (rel, md5) for rel, md5 in sorted(bases.items()))
    return hashlib.sha256(lines.encode("utf-8")).hexdigest()


def tweaks_take_overs(version, cat, record, cached=False):
    """Every hand-changed target file of a stack taken over (tweaks_take_over), COMPUTED -- nothing is written:
    {"taken": {path: {"base": bytes, "kept", "keys", "rows", "hand": md5 of H, "at": its modification time,
    "entry": the record entry a store writes, "replaced": put back outside Relic and changed, "gave": the paths
    whose value in the stored document it changed, "newKept": the rows it kept that were not kept before}},
    "refused": {path: {"code", "reason"}} -- the hand-changed files
    that are not taken over --, "record": the record as a store writes it (its entries, both documents, the
    refusal re-digested when it was about the stored document), "key": tweaks_taken_key of the bases as they are
    then, "states": {path: "original" | "ours" | "changed" | "missing"} before it, by the md5s alone (a file
    whose md5 the entry names is `ours` here even when its base is gone -- tweaks_file and GET name that one
    `changed`; it is never taken over), "facts": the values of the bases after it (tweaks_facts: what the
    documents of "record" are canonical against), "archive": why the shipped
    originals could not be read, when they were needed and could not}. The files are taken over one
    after the other, each on the documents the one before left -- a file put back outside Relic and changed
    (`replaced`) after every other one: it takes the settings that write it out of the document in effect, and
    the others are proven against that document as their output was written. cached: the md5s of the files and
    what their bases hold as GET reads them (per file stamp) -- a job reads everything at this moment. Raises
    AgentError(500) for a file that cannot be read."""
    entries, memo, now = record["files"], {}, time.time()
    states, bases, refused, taken = {}, {}, {}, {}
    hand_files = []
    for rel in sorted(cat["files"]):
        entry, want = entries.get(rel), cat["files"][rel].lower()
        path = tweaks_path(version, rel)
        disk = None
        if cached:
            md5 = _tweaks_md5(path)
        else:
            disk = _tweaks_read(path)
            md5 = None if disk is None else hashlib.md5(disk).hexdigest()
        mine = entry is not None and md5 is not None and md5 in (entry["out"], entry.get("prev"))
        if md5 is None:
            states[rel] = "missing"
        elif md5 == want and not (mine and _tweaks_taken(entry)):
            states[rel] = "original"
        elif mine:
            states[rel] = "ours"
        else:
            states[rel] = "changed"
            hand_files.append((rel, disk))
        if _tweaks_taken(entry) and states[rel] != "original":
            bases[rel] = entry["base"].lower()
    facts = tweaks_record_facts(version, cat, record, memo) if not cached else tweaks_facts(cat, dict(
        (rel, _tweaks_adopted_bytes(version, rel, entries[rel])) for rel in bases))
    candidates = []
    for rel, disk in hand_files:
        entry = entries.get(rel)
        hand = disk if disk is not None else _tweaks_read(tweaks_path(version, rel))
        md5 = None if hand is None else hashlib.md5(hand).hexdigest()
        if md5 is None or md5 == cat["files"][rel].lower() \
                or (entry is not None and md5 in (entry["out"], entry.get("prev"))):
            continue  # (a remembered md5 the file no longer has: it is not hand-changed now)
        if entry is None:
            base = tweaks_vendor_bytes(version, rel, cat["files"][rel], memo=memo)
        else:
            base = _tweaks_entry_base(version, rel, entry, memo)
        candidates.append((rel, entry, base, hand))
    # (a file put back outside Relic and changed is taken over LAST: it takes the settings that write it out of the
    #  document in effect, and every other file is proven against that document as its own output was written)
    active, tweaks, files, later = record["active"], record["tweaks"], dict(entries), []
    for group in (candidates, later):
        for rel, entry, base, hand in group:
            result = tweaks_take_over(cat, rel, entry, base, hand, active, tweaks, facts)
            if not result["ok"]:
                refused[rel] = {"code": result["code"], "reason": result["reason"]}
                continue
            if result["replaced"] and group is candidates:
                later.append((rel, entry, base, hand))
                continue
            active, tweaks, facts = result["active"], result["tweaks"], result["facts"]
            md5_hand, md5_base = hashlib.md5(hand).hexdigest(), hashlib.md5(result["base"]).hexdigest()
            st = _stat_or_none(tweaks_path(version, rel))
            # (what the entry says besides of the file -- `released`, a key this agent does not know -- stays)
            new = dict((k, v) for k, v in (entry or {}).items()
                       if k not in ("base", "out", "ok", "prev", "taken", "kept", "undo", "away"))
            new.update(base=md5_base, out=md5_hand, ok=True)
            if md5_base != cat["files"][rel].lower():
                first = (entry or {}).get("taken") if _tweaks_taken(entry) else None
                new["taken"] = {"at": int(now), "hand": md5_hand,
                                "vendor": first["vendor"] if first else cat["files"][rel].lower()}
                bases[rel] = md5_base
            else:
                bases.pop(rel, None)
            if result["kept"]:
                new["kept"] = result["kept"]
            undo = (entry or {}).get("undo")
            if undo is None:
                undo = {"base": str((entry or {}).get("base") or cat["files"][rel]).lower(),
                        "kept": list((entry or {}).get("kept") or []), "keys": {}}
            else:
                undo = json.loads(json.dumps(undo))
            for path, values in result["keys"].items():
                undo["keys"].setdefault(path, values)
            new["undo"] = undo
            files[rel] = new
            wanted = tweaks_leaves(tweaks)
            taken[rel] = {"base": result["base"], "kept": result["kept"], "keys": result["keys"],
                          "rows": result["rows"], "hand": md5_hand,
                          "at": int(st.st_mtime) if st is not None else int(now), "entry": new,
                          "replaced": result["replaced"],
                          "gave": sorted(path for path, values in result["keys"].items()
                                         if wanted.get(path) != values["tweaks"]),
                          "newKept": [rid for rid in result["kept"] if rid not in (entry or {}).get("kept", [])]}
    after = dict(record, files=files, active=active, tweaks=tweaks)
    refusal = record.get("refused")
    if taken and refusal is not None and refusal.get("digest") == tweaks_digest(record["tweaks"]):
        after["refused"] = dict(refusal, digest=tweaks_digest(tweaks))
    return {"taken": taken, "refused": refused, "record": after, "key": tweaks_taken_key(bases), "states": states,
            "facts": facts, "archive": memo.get(None)}


def _tweaks_adopted_bytes(version, rel, entry):
    """The bytes of the adopted base a taken entry names (_tweaks_adopted_read) -- None when they are not there, or
    cannot be read."""
    try:
        return _tweaks_adopted_read(version, rel, entry["base"].lower())
    except AgentError:
        return None


def tweaks_store_take_overs(version, cat, record, job=None, result=None):
    """The take-overs of a stack (tweaks_take_overs, read at this moment -- or `result`, that computation for
    this very record, made by the caller with nothing written since) STORED -- what every job that plans the
    files does first, after the leftover rule: each adopted base written durably to .relic-tweaks/adopted/ (the
    one an `undo` still names kept beside it as <path>.undo first), then ONE record write: the entries, both
    documents, the refusal re-digested. No data file is written. Nothing taken over: nothing written, the record
    returned as it is. Returns (the record as it is now, the computation -- its "refused" says why a
    hand-changed file stays changed). A job says in one line per file what was taken over. Raises AgentError(507)
    when a base or the record cannot be written -- nothing of a take-over is in effect then."""
    result = tweaks_take_overs(version, cat, record) if result is None else result
    if job is not None and result["archive"]:
        job.log("WARNING: Gameplay settings: %s -- the originals it holds are not available." % result["archive"])
    if not result["taken"]:
        return record, result
    earlier = []  # (path, the adopted base it held -- None: none) of every base written, to put back on a failure

    def put_back():
        for path, data in reversed(earlier):
            try:
                if data is None:
                    _remove_quiet(path)
                else:
                    _write_tweaks_own(version, path, data)
            except OSError:
                pass

    for rel, taken in sorted(result["taken"].items()):
        entry, path = taken["entry"], tweaks_adopted_path(version, rel)
        try:
            undo_base = entry["undo"]["base"]
            current = _tweaks_read(path)
            if current is not None and hashlib.md5(current).hexdigest() == undo_base \
                    and undo_base != entry["base"]:
                _write_tweaks_own(version, tweaks_adopted_path(version, rel, undo=True), current)
            if "taken" in entry:
                earlier.append((path, current))
                _write_tweaks_own(version, path, taken["base"])
        except (OSError, AgentError) as e:
            put_back()
            raise AgentError(507, "Gameplay settings: the base of %s could not be kept (%s) -- the change made outside "
                                  "Relic is not taken over." % (rel, _failure_text(e)))
    try:
        after = write_tweaks_record(version, result["record"])
    except AgentError:
        put_back()
        raise
    if job is not None:
        for rel, taken in sorted(result["taken"].items()):
            gave, kept = len(taken["gave"]), len(taken["newKept"])
            what = ", ".join(([("1 setting gave way" if gave == 1 else "%d settings gave way" % gave)] if gave else [])
                             + ([("1 row kept as it left it" if kept == 1 else "%d rows kept as it left them" % kept)]
                                if kept else []))
            if taken["replaced"]:
                job.log("Gameplay settings: %s was put back outside Relic and changed -- none of what the settings in "
                        "effect gave it is in it any more: the change is taken over%s; the settings that write it "
                        "apply on it again." % (rel, " (%s)" % what if what else ""))
            else:
                job.log("Gameplay settings: %s was changed outside Relic -- the change is taken over%s; the settings "
                        "apply on top of it." % (rel, " (%s)" % what if what else ""))
    return after, result


# -- GET /server/tweaks --

def tweaks_service_states(version):
    """{service: state} of this version's containers as docker reports them ("running", "exited",
    "restarting", ...); None when docker does not answer, from which nothing may be concluded. ONE
    `compose ps`, through the non-logging runner."""
    r = _compose(stack_dir(version), "ps", "-a", "--format", "json", timeout=60)
    return _parse_ps_json(r.stdout) if r.returncode == 0 else None


def tweaks_game_state(version):
    """The state of this version's game server container ("" when it has none), None when docker does not
    answer."""
    states = tweaks_service_states(version)
    return None if states is None else states.get(TWEAKS_GAME_SERVICE, "")


def tweaks_game_runs(version):
    """Whether this version's game server runs -- the service whose loader judges a change of the data
    files: True (its container is "running": one docker restarts, creates or has paused is not), False (the
    stack is not listed, or the container is in another state) or None -- docker did not say, from which
    nothing may be concluded."""
    up, err = stack_up(version)
    if err:
        return None
    if not up:
        return False
    state = tweaks_game_state(version)
    return None if state is None else state == "running"


def tweaks_game_running(version):
    """tweaks_game_runs as a yes or no: False also when docker cannot tell -- without a server to ask,
    nothing but an original may be written."""
    return tweaks_game_runs(version) is True


def tweaks_schedules(text, now):
    """The Abyss calendar of a stack as GET /server/tweaks reports it, from the text of its (date-shifted)
    TowerScheduleData.txt: ([{"id", "floors", "open", "close"}] sorted by open, the id of the period that is
    live at `now` -- 0 when none). floors = the floors every period has, then the ones of this period;
    open / close = the row's earliest and latest time stamp (tower_active_window's reading) as epoch seconds of
    this box's clock; `now` = "YYYY-MM-DD HH:MM:SS". A row without an id, floors or two stamps is skipped."""
    lines = text.split("\n")
    cols = [i for i, title in enumerate(lines[0].rstrip("\r").split("\t"))
            if title == _COL_SCHEDULE_ENTRANCE or _COL_SCHEDULE_FLOORS_RE.fullmatch(title)]
    out, active = [], 0
    for line in lines[1:]:
        cells, stamps = line.rstrip("\r").split("\t"), _STAMP_RE.findall(line)
        floors = [int(x) for c in cols if c < len(cells) for x in cells[c].split(",") if x.strip().isdigit()]
        if not cells[0].strip().isdigit() or len(stamps) < 2 or not floors:
            continue
        try:
            first, last = (int(time.mktime(time.strptime(s, "%Y-%m-%d %H:%M:%S"))) for s in (min(stamps), max(stamps)))
        except (ValueError, OverflowError):
            continue
        out.append({"id": int(cells[0]), "floors": floors, "open": first, "close": last})
        if min(stamps) <= now < max(stamps):
            active = int(cells[0])
    out.sort(key=lambda row: (row["open"], row["id"]))
    return out, active


def _tweaks_sections(cat):
    """{section: (its tables, its monster-group scripts)} -- the files each card of the page rewrites, as
    GET /server/tweaks judges the card by them: a table that cannot be rewritten switches the card off, a
    script only takes out what rests on it -- its own slots and, for a line-up, the enemy level of its
    domains. Scripts: one per monster group of the Abyss, one per line-up of the domains; the other cards
    have none."""
    tables = {"resin": [cat["resin"]["file"]],
              "abyss": [cat["abyss"]["levelFile"]],
              "domains": [cat["domains"]["file"], cat["domains"]["dropFile"]],
              "quests": [cat["quests"]["file"], cat["quests"]["daily"]["file"]]}
    out = {}
    for section, rels in tables.items():
        groups = _tweaks_groups(cat, section) if section in TWEAK_SLOT_SECTIONS else {}
        out[section] = (sorted(set(rels), key=rels.index),
                        sorted(set(group["file"] for group in groups.values()) - set(rels)))
    return out


def _tweaks_card_rows(cat, section, rel):
    """The row ids of a table that belong to a card -- what a row of it kept as a change made outside Relic left it
    (`kept`) counts under: the reward row of every domain on the Domain card, the quest rewards and the daily rows
    on the Quest card (the drop table belongs to both); no other row is ever kept. Pure."""
    rows, daily = set(), cat["quests"]["daily"]
    if section == "domains" and rel == cat["domains"]["dropFile"]:
        rows.update(str(d["root"]) for d in cat["domains"]["list"].values())
    if section == "quests" and rel == cat["quests"]["file"]:
        rows.update(cat["quests"]["rewards"])
    if section == "quests" and rel == daily["file"]:
        rows.update(str(r) for r in daily["drops"])
    return rows


def _tweaks_original_facts(cat, groups, rel, data):
    """What GET /server/tweaks reads out of ONE original file (bytes), and the proof that the file is the one
    the catalogue describes (AgentError otherwise): every row, column and spawn slot the catalogue names is
    there, and the values the catalogue calls original -- the resin row, the enemy levels, the statue costs,
    the monster of each slot, the level a line-up is listed with -- are the file's. So is the enemy-level
    cell of every domain whose level can be set (_tweaks_domain_levels): the level the domain is listed with,
    less one -- of the other domains neither the cell nor its column is asked for. `groups` = the monster
    groups of every card (_tweaks_groups "all"): the script of an Abyss group and the script of a domain
    line-up are proven the same way, slot by slot. {"free": {reward row: free child slots}, "own": {reward
    row: [the items that are children of it, sorted]}} for the drop table, {"rewards": {row: [[item,
    count]]}} for the reward table: the scalar cells first, then the item slots. The file is read as any base is
    (_tweaks_read_facts), then held to the catalogue's values."""
    name = rel.rsplit("/", 1)[-1]
    facts = _tweaks_read_facts(cat, groups, rel, data)

    def same(got, want, what):
        for rid in sorted(want, key=lambda r: (len(r), r)):
            if got[rid] != want[rid]:
                raise AgentError(500, "%s: %s of row %s is not what the catalogue says." % (name, what, rid))

    if "resin" in facts and [facts["resin"][k] for k in ("hardMax", "cap", "minutes")] \
            != [cat["resin"][k] for k in ("hardMax", "cap", "minutes")]:
        raise AgentError(500, "%s: the resin row is not what the catalogue says." % name)
    if "levels" in facts:
        same(facts["levels"], dict((lid, c["level"]) for lid, c in cat["abyss"]["chambers"].items()), "the enemy level")
    lineups = cat["domains"].get("lineups") or {}
    for gid, slots in (facts.get("slots") or {}).items():
        for cfg, monster in groups[gid]["slots"].items():
            if slots[cfg] != monster:
                raise AgentError(500, "%s: spawn slot %s is not what the catalogue says." % (name, cfg))
        # (a line-up is listed with the largest level an entry of its script carries, listed slot or not)
        if gid in lineups and facts["maxLevel"][gid] != lineups[gid]["level"]:
            raise AgentError(500, "%s: the largest level of an entry is not what the catalogue says." % name)
    if "costs" in facts:
        same(facts["costs"], dict((did, d["cost"]) for did, d in cat["domains"]["list"].items()),
             "the cost of the reward statue")
        same(facts["domainLevels"],
             dict((did, cat["domains"]["list"][did]["level"]) for did in _tweaks_domain_levels(cat)), "the enemy level")
    return dict((k, facts[k]) for k in ("free", "own", "rewards") if k in facts)


def _tweaks_md5(path):
    """The md5 of a file as GET /server/tweaks needs it (remembered per mtime + size + inode); None when the
    file is not there or cannot be read."""
    try:
        return _tweaks_cached("md5", path, lambda p: _md5_of(p).hexdigest())
    except OSError:
        return None


def _tweaks_stamp(path):
    """(mtime_ns, size, inode) of a file -- what tells GET /server/tweaks that a job wrote the record while it read
    -- None when the file is not there."""
    st = _stat_or_none(path)
    return None if st is None else (st.st_mtime_ns, st.st_size, st.st_ino)


def tweaks_job_running(version):
    """Whether a job of this version whose work ends in the gameplay settings' waits (TWEAKS_STOP_KINDS) runs: it may
    be writing the data files and the record this very moment."""
    with _jobs_lock:
        return any(JOBS[jid].state == "running" and JOBS[jid].version == version and JOBS[jid].kind in TWEAKS_STOP_KINDS
                   for jid in JOBS_ORDER if jid in JOBS)


def _tweaks_stored_key(version, cat, record):
    """tweaks_taken_key of the bases the record names as adopted, as GET /server/tweaks reads them (md5s per file
    stamp) -- the files a take-over of this moment would add left out: the key of a record read while it was being
    changed."""
    bases = {}
    for rel in sorted(cat["files"]):
        entry = record["files"].get(rel)
        if not _tweaks_taken(entry):
            continue
        md5 = _tweaks_md5(tweaks_path(version, rel))
        mine = md5 is not None and md5 in (entry["out"], entry.get("prev"))
        if md5 == cat["files"][rel].lower() and not mine:
            continue
        bases[rel] = entry["base"].lower()
    return tweaks_taken_key(bases)


_tweaks_facts_memo = {}  # (path, md5 of a base not stored yet) -> what _tweaks_read_facts read off it
_tweaks_facts_memo_lock = threading.Lock()


def _tweaks_base_facts(cat, groups, rel, data):
    """_tweaks_read_facts of the bytes of an adopted base a take-over computed (GET /server/tweaks: nothing stored),
    remembered by their md5 -- None for a base the readers refuse."""
    key = (rel, hashlib.md5(data).hexdigest())
    with _tweaks_facts_memo_lock:
        if key in _tweaks_facts_memo:
            return _tweaks_facts_memo[key]
    try:
        facts = _tweaks_read_facts(cat, groups, rel, data)
    except Exception:  # noqa: BLE001 -- a base the readers refuse is one no setting is built on
        facts = None
    with _tweaks_facts_memo_lock:
        if len(_tweaks_facts_memo) > 64:
            _tweaks_facts_memo.clear()
        _tweaks_facts_memo[key] = facts
    return facts


def _tweaks_vendor_source(version, cat, rel):
    """Where GET /server/tweaks reads the vendor's original of a target file from: (path, None) -- the file itself
    while it is that original, else the base copy -- or (the shipped archive, md5) when only its member holds it;
    (None, None) when no source does. md5s per file stamp."""
    want = cat["files"][rel].lower()
    for path in (tweaks_path(version, rel), tweaks_base_path(version, rel)):
        if _tweaks_md5(path) == want:
            return path, None
    if _tweaks_archive_md5s(version).get(rel) == want:
        return tweaks_originals_path(version), want
    return None, None


def _tweaks_vendor_facts(version, cat, groups, rel, stamp):
    """_tweaks_read_facts of the vendor's original of one target file (_tweaks_vendor_source), remembered per stamp of
    the file it is read from and of the catalogue -- None when no source holds it."""
    path, member = _tweaks_vendor_source(version, cat, rel)
    if path is None:
        return None

    def load(p):
        try:
            data = tweaks_shipped_originals(version, {rel: member})[0].get(rel) if member else _tweaks_read(p)
            return _tweaks_read_facts(cat, groups, rel, data or b"")
        except Exception:  # noqa: BLE001 -- what cannot be read says nothing of the game's values
            return None
    return _tweaks_cached("vendorfacts", path, load, (rel, stamp))


def _tweaks_drop_rows(data, name):
    """({row id: its line} -- the first row of each id --, [(id column, count column, weight column)]) of a drop
    table (bytes)."""
    lines, _ends, cols = _tweak_table(data, name)
    rows = {}
    for line in lines[1:]:
        rows.setdefault(line.split("\t", 1)[0], line)
    return rows, _tweak_drop_children(cols, name)


def _tweaks_tree_rows(rows, children, root):
    """The ids of the rows of a drop table a reward row reaches: the row itself and, through every child in use that
    is a row of the table, the rows below it."""
    seen, todo = set(), [str(root)]
    while todo:
        rid = todo.pop()
        if rid in seen or rid not in rows:
            continue
        seen.add(rid)
        cells = rows[rid].split("\t")
        todo += [cells[c_id] for c_id, _c, _w in children if c_id < len(cells) and cells[c_id] not in ("", "0")]
    return seen


def _tweaks_trees_changed(cat, base, vendor):
    """The domains whose reward tree -- the reward row and every row below it -- differs between the adopted base of
    the drop table and the vendor's original (bytes both): what the catalogue's preview of their reward does not
    describe. Empty when either cannot be read."""
    name = cat["domains"]["dropFile"].rsplit("/", 1)[-1]
    try:
        mine, children = _tweaks_drop_rows(base, name)
        theirs, _children = _tweaks_drop_rows(vendor, name)
    except AgentError:
        return set()
    out = set()
    for did, d in cat["domains"]["list"].items():
        reach = _tweaks_tree_rows(mine, children, d["root"]) | _tweaks_tree_rows(theirs, children, d["root"])
        if any(mine.get(rid) != theirs.get(rid) for rid in reach):
            out.add(did)
    return out


def tweaks_own_refused(version, cat, suspects):
    """Whether the game server REFUSES ITS OWN data files, read from its log alone -- never a signal, never a wait:
    what tweaks_wait_booted(judge=True) would find. The last load of the process that runs failed and no load began
    after it -- or, the game server down (its log renamed when it exited: _tweaks_dated_facts), the last load of
    the process that exited failed: a boot over those files ends the process. {"error": its reasons as a refusal
    quotes them, "files": the target files they name, sorted} or None. The files: a group id the reasons name
    (`group_id:<id>`) -> the script of that monster group; the check or the loader of a table (the resin check and
    ConstValue... -> the constant table, TowerLevel... -> the chamber table, Dungeon... -> the dungeon table,
    DropTree... / drop -> the drop table, Reward... -> the reward table); the name of a target file -> that file;
    nothing found -> `suspects` (the target files changed outside Relic or taken over)."""
    facts = tweaks_service_facts(version, TWEAKS_GAME_SERVICE)
    if facts is None:
        facts = _tweaks_dated_facts(version)
    if facts is None or facts["verdict"] != "refused" or facts["loads"] > facts["judged"]:
        return None
    text = "; ".join(facts["reasons"])
    return {"error": text or "the game server could not load its data files (its log names no reason)",
            "files": sorted(_tweaks_refusal_files(cat, text) or set(suspects))}


def _tweaks_refusal_files(cat, text):
    """The target files the reasons of a refused load name (`text`): the script of a monster group a `group_id:<id>`
    names; a table whose loader or check the server's log names -- the loader by the table's own name
    (`load<Name>ExcelConfig`, `<Name>ExcelConfigMgrBase`, `find<Name>ExcelConfig`: ConstValue, TowerLevel, Dungeon,
    DropTree, Reward), the resin check (`checkResinConfig`) --; a file whose name the text quotes (a path ending in
    it). Every name is taken WHOLE: the loader of another table whose name ends in one of these (DailyDungeon...,
    CoopReward...) or a file whose name ends in one of theirs names none of them. A set of paths, empty when the
    text names none. Pure."""
    groups, files = _tweaks_groups(cat, "all"), set()
    for gid in re.findall(r"group_id:(\d+)", text):
        if gid in groups:
            files.add(groups[gid]["file"])
    for rel, names in ((cat["resin"]["file"], ("ConstValueExcelConfig", "checkResinConfig")),
                       (cat["abyss"]["levelFile"], ("TowerLevelExcelConfig",)),
                       (cat["domains"]["file"], ("DungeonExcelConfig",)),
                       (cat["domains"]["dropFile"], ("DropTreeExcelConfig",)),
                       (cat["quests"]["file"], ("RewardExcelConfig",))):
        if any(re.search(r"(?<![A-Za-z0-9_])(?:load|find|check|get)?" + re.escape(name), text) for name in names):
            files.add(rel)
    files.update(rel for rel in cat["files"]
                 if re.search(r"(?<![A-Za-z0-9_.-])" + re.escape(rel.rsplit("/", 1)[-1]) + r"(?![A-Za-z0-9_])", text))
    return files


def tweaks_info(version, changing=False):
    """GET /server/tweaks: everything the launcher's gameplay settings show for one version -- whether a catalogue
    ships (`available`) and the stack is there (`present`; without either nothing else is answered), whether the
    game server runs (an Apply is judged by it at once), the stored document and the one in effect -- as the next
    job leaves them once it takes over every file changed outside Relic that it can (tweaks_take_overs, COMPUTED:
    nothing is written by an answer) --, what is pending (the files do not hold the EFFECTIVE document: a setting
    that cannot be applied is `blocked`, never pending) / refused / unconfirmed / unread (only while the game server
    runs), the key of the files taken over (`takenKey`, "" for none -- what the next POST sends back), whether the
    files are being changed this moment (`changing`: a job of the version that writes them runs, or the record
    changed while it was read -- no take-over is computed then), whether the game server refuses its own data files
    (`ownRefused`, read from its log alone), per card (`sections`) what can be done with its files, the limits, and
    the values the page starts from -- FROM EACH FILE'S BASE (the vendor's original, or the base a take-over adopted:
    the resin row, the chambers' levels, the monster of every spawn slot, a domain's cost and enemy level, what its
    reward row holds, what each quest reward row hands out) with the game's own value beside it only where it
    differs (`game` of the resin, `gameLevel` of a chamber, `gameSlots` of a half and of a line-up, `gameCost` /
    `gameLevel` / `gamePreview` of a domain, `game` of a reward row the hand changed), the monsters, the Abyss
    floors and the stack's own calendar, the domains (`group`: the monster group of their line-up; `levels`: the
    range a document is held to, only where the enemy level can be set; `kept`: its reward row is kept -- no
    multiplier, no extra item touches it), the line-ups by group id, the items, the quest rewards (`kept`, `tier`
    of a hangout reward) and the items a multiplier leaves at their count (`keep`).
    sections.<card>: `ok` (false while a TABLE of the card cannot carry settings: its controls are off), `why`
    ("changed" | "refused" | "missing": the first of them one of its files is) and `files` -- the card's files
    that cannot carry settings, paths (the Abyss and the Domain card always say `files`); `reasons` {path: {why:
    changed | missing | refused | level, reason}} -- one per such file, a line-up script whose levels are locked
    and a file an editor refuses on an adopted base included; `taken` [{file, at, undo, undoOriginal}] -- the
    files taken over (stored, or computed now: `at` = the file's modification time), `undo` = a Revert puts back
    the base and settings from before, `undoOriginal` = that base is the vendor's original (else an earlier base
    taken over); `kept` {path: rows kept} -- the card's own rows of the file (the drop table: a domain's reward
    row on the Domain card, a daily row on the Quest card); `blocked` -- the card's settings that cannot be
    applied; `dropped` {path: {active, tweaks}} -- what the take-overs of its files took out of the stored
    document and that it does not hold again (a setting set again since, and one a take-over took out of the
    document in effect alone, are not named); `revertFiles` / `resetFiles` -- the files a Revert / a Reset of the
    card acts on (tweaks_op_files; empty: nothing to do), `revertMissing` / `resetMissing` -- the ones of them it
    cannot act on (no vendor's original available; a Revert's adopted base gone); `levelFiles` (Domains) --
    line-up scripts taken over with an entry above the line-up's level: their domains' enemy level is locked,
    their slots are not. Never a 404 (an unknown version is the usual 400), never a write. md5s and what is read
    out of the files are
    remembered per file stamp. changing: answer with no take-over computed (the second look of an answer whose
    record changed, or a job of whose version started, while it read)."""
    check_known(version)
    cat = read_tweaks_catalog(version)
    out = {"version": version, "available": cat is not None, "present": is_present(version)}
    if cat is None or not out["present"]:
        return out
    rec_path = tweaks_record_path(version)
    before = _tweaks_stamp(rec_path)
    try:
        record, record_error = read_tweaks_record(version), None
    except AgentError as e:
        record, record_error = tweaks_blank_record(), e.message
    changing, over = changing or tweaks_job_running(version), None
    if record_error is None and not changing:
        try:
            over = tweaks_take_overs(version, cat, record, cached=True)
        except AgentError:
            over = None  # (a file that cannot be read: the files as they are)
        if _tweaks_stamp(rec_path) != before or tweaks_job_running(version):
            changing, over = True, None
    view = over["record"] if over else record
    computed = over["taken"] if over else {}
    refusals = over["refused"] if over else {}
    memo = dict((("adopted", rel, hashlib.md5(t["base"]).hexdigest()), t["base"]) for rel, t in computed.items())
    refused = view["refused"]
    if refused is not None and refused.get("digest") != tweaks_digest(view["tweaks"]):
        refused = None  # about another document than the one that is wanted
    plan, pending = {}, False
    if record_error is None:
        # What a Start brings into effect (tweaks_after_start): the stored document -- or, while the server's
        # refusal of it stands, the last one it accepted. Pending = the files do not hold its effective form.
        due = view["tweaks"] if refused is None else view["active"]
        try:
            pending = bool(tweaks_plan(version, cat, view, due, dict((rel, why["reason"]) for rel, why in
                                                                     refusals.items()), plan, memo)[0])
        except AgentError:
            pending = True  # the files do not hold it, and as things are they cannot be made to
    running = tweaks_game_running(version)
    # (unread: only while the game server runs -- a service that starts reads the files as they are)
    out.update(running=running, tweaks=view["tweaks"], active=view["active"],
               pending=pending, unconfirmed=tweaks_unconfirmed(view), unread=bool(view.get("unread")) and running,
               refused=None if refused is None else {"at": refused["at"], "error": refused["error"]},
               changing=changing, takenKey=over["key"] if over else _tweaks_stored_key(version, cat, view))
    if record_error is not None:
        out["recordError"] = record_error
    stamp = _stat_or_none(os.path.join(payload_dir(version), "tweaks.json"))
    stamp = None if stamp is None else (stamp.st_mtime_ns, stamp.st_size)
    groups, states, facts = _tweaks_groups(cat, "all"), {}, {}
    lineups = cat["domains"].get("lineups") or {}
    lineup_of = dict((lineup["file"], (gid, lineup["level"])) for gid, lineup in lineups.items())

    def read_facts(src, rel, adopted=False, md5=None):
        try:
            data = tweaks_shipped_originals(version, {rel: md5})[0].get(rel) if md5 else _tweaks_read(src)
            # (an adopted base is read for what it holds; an original is held to what the catalogue says it holds)
            return (_tweaks_read_facts if adopted else _tweaks_original_facts)(cat, groups, rel, data or b"")
        except Exception:  # noqa: BLE001 -- a file the editors cannot read is one they will not rewrite: its card is off
            return None

    def base_of(rel, entry):
        # (the md5 of the base an entry names as found, and where it is read from -- None when it is not there:
        #  the adopted copy of a taken entry, or the copy an undo names beside it; else the base copy, else the
        #  member of the shipped archive)
        want = entry["base"].lower()
        if _tweaks_taken(entry):
            for path in (tweaks_adopted_path(version, rel), tweaks_adopted_path(version, rel, undo=True)):
                if _tweaks_md5(path) == want:
                    return want, path
            return None, None
        if _tweaks_md5(tweaks_base_path(version, rel)) == want:
            return want, tweaks_base_path(version, rel)
        return (want, None) if _tweaks_archive_md5s(version).get(rel) == want else (None, None)

    def state_of(rel):
        # original | ours | changed | missing | refused (a file the readers refuse: what is listed is not in it)
        if rel not in states:
            want, entry = cat["files"][rel].lower(), view["files"].get(rel)
            if rel in computed:
                facts[rel] = _tweaks_base_facts(cat, groups, rel, computed[rel]["base"])
                state = "ours"
            else:
                disk = _tweaks_md5(tweaks_path(version, rel))
                base, src = (None, None) if entry is None or _tweaks_foreign(cat, view, rel) else base_of(rel, entry)
                state = _tweaks_state(want, disk, entry, base)
                if state in ("original", "ours"):
                    taken = state == "ours" and _tweaks_taken(entry)
                    if state == "original":
                        src = tweaks_path(version, rel)
                    if src is None:
                        path = tweaks_originals_path(version)
                        facts[rel] = _tweaks_cached("facts", path, lambda p: read_facts(p, rel, md5=base), (rel, stamp))
                    else:
                        facts[rel] = _tweaks_cached("basefacts" if taken else "facts", src,
                                                    lambda p: read_facts(p, rel, adopted=taken), (rel, stamp))
            if state in ("original", "ours") and facts.get(rel) is None:
                state = "refused"  # a row, a column or a slot the catalogue names is not in the file
            states[rel] = state
        return states[rel]

    def adopted(rel):
        # (a file whose base is not the vendor's original: a take-over stored, or computed now)
        return state_of(rel) == "ours" and (rel in computed or _tweaks_taken(view["files"].get(rel)))

    def level_locked(rel):
        # (a line-up script taken over holds the range of its domains' enemy level only while no entry of it
        #  stands above the level the line-up is listed with -- the range was read off the vendor's scripts)
        if rel not in lineup_of or not adopted(rel):
            return False
        gid, level = lineup_of[rel]
        top = ((facts.get(rel) or {}).get("maxLevel") or {}).get(gid)
        return top is None or top > level

    def reason_of(rel):
        state, entry = states[rel], view["files"].get(rel)
        if state == "missing":
            return {"why": "missing", "reason": TWEAKS_WHY_MISSING}
        if state == "refused":
            return {"why": "refused", "reason": TWEAKS_WHY_UNREAD}
        if entry is not None and _tweaks_foreign(cat, view, rel):
            reason = TWEAKS_WHY_FOREIGN
        elif rel in refusals:
            reason = refusals[rel]["reason"]
        elif changing:
            reason = TWEAKS_WHY_CHANGING
        else:
            reason = _tweaks_changed_why(entry, _tweaks_md5(tweaks_path(version, rel)))
        return {"why": "changed", "reason": reason}

    def vendor_there(rel):
        return _tweaks_vendor_source(version, cat, rel)[0] is not None

    def foreign(rel):
        return _tweaks_foreign_md5(cat, view, rel, _tweaks_md5(tweaks_path(version, rel)))

    def target_there(rel):
        # (the base a Revert builds the file on again: the vendor's original, or an earlier adopted base)
        entry = view["files"].get(rel)
        if entry is None or foreign(rel):
            return True
        md5 = (entry["undo"]["base"] if "undo" in entry else entry["base"]).lower()
        if md5 == cat["files"][rel].lower():
            return True
        return (rel in computed and hashlib.md5(computed[rel]["base"]).hexdigest() == md5) or any(
            _tweaks_md5(tweaks_adopted_path(version, rel, undo=undo)) == md5 for undo in (False, True))

    plan_why = plan.get("unusable") or {}
    blocked_all = plan.get("blocked") or []
    wanted_now = tweaks_leaves(view["tweaks"])
    sections = {}
    for section, (tables, scripts) in _tweaks_sections(cat).items():
        rels = tables + scripts
        bad = [rel for rel in rels if state_of(rel) in ("changed", "missing", "refused")]
        # The Abyss card and the Domain card live on their tables and on one script per monster group: a
        # script that cannot be rewritten takes what rests on it out of the card -- its own slots, and for a
        # line-up the enemy level of its domains (it is named, and settings that need it are blocked) --, not
        # the card: only a table does that. Those two cards always say `files`.
        entry = {"ok": not any(rel in tables for rel in bad)}
        if section in TWEAK_SLOT_SECTIONS:
            entry["files"] = bad
        if bad:
            entry.update(why=next(why for why in ("changed", "refused", "missing")
                                  if any(states[rel] == why for rel in bad)), files=bad)
        reasons = dict((rel, reason_of(rel)) for rel in bad)
        level_files = [rel for rel in scripts if section == "domains" and level_locked(rel)]
        for rel in level_files:
            reasons[rel] = {"why": "level", "reason": _tweaks_level_reason(lineup_of[rel][1])}
        for rel, (why, reason) in sorted(plan_why.items()):
            if why == "refused" and rel in rels and rel not in reasons:
                reasons[rel] = {"why": "refused", "reason": reason}
        taken, kept, dropped = [], {}, {}
        for rel in rels:
            file_entry = view["files"].get(rel)
            if file_entry is None or states[rel] not in ("ours", "original"):
                continue
            if states[rel] == "ours" and (_tweaks_taken(file_entry) or "undo" in file_entry):
                st = _stat_or_none(tweaks_path(version, rel))
                at = computed[rel]["at"] if rel in computed else file_entry["taken"]["at"] \
                    if _tweaks_taken(file_entry) else (int(st.st_mtime) if st is not None else 0)
                undo = file_entry.get("undo")
                taken.append({"file": rel, "at": int(at), "undo": undo is not None,
                              "undoOriginal": undo is not None and undo["base"].lower() == cat["files"][rel].lower()})
            # (the rows of the card's own: the drop table is the Domain card's and the Quest card's)
            own_rows = _tweaks_card_rows(cat, section, rel)
            n_kept = sum(1 for rid in file_entry.get("kept") or [] if rid in own_rows)
            if n_kept:
                kept[rel] = n_kept
            for path, values in ((file_entry.get("undo") or {}).get("keys") or {}).items():
                # (what gave way in the stored document: a key the take-over SET -- null both -- or took out of
                #  it and that it does not hold again)
                if path.split(".", 1)[0] == section and (values == {"active": None, "tweaks": None} or (
                        values.get("tweaks") is not None and wanted_now.get(path) != values["tweaks"])):
                    dropped[path] = values
        op_states = dict((rel, "ours" if states[rel] == "refused" else states[rel]) for rel in rels)
        others = set(rel for rel in rels if foreign(rel))
        revert_files = tweaks_op_files(cat, view, op_states, "revert", [section], others)
        reset_files = tweaks_op_files(cat, view, op_states, "reset", [section], others)
        entry.update(reasons=reasons, taken=taken, kept=kept, dropped=dropped,
                     blocked=[path for path in blocked_all if path.split(".", 1)[0] == section],
                     revertFiles=revert_files,
                     revertMissing=[rel for rel in revert_files if not vendor_there(rel) or not target_there(rel)],
                     resetFiles=reset_files, resetMissing=[rel for rel in reset_files if not vendor_there(rel)])
        if section == "domains":
            entry["levelFiles"] = level_files
        sections[section] = entry
    schedules, active = [], 0
    try:
        with open(tweaks_path(version, cat["abyss"]["scheduleFile"]), "rb") as f:
            schedules, active = tweaks_schedules(f.read().decode("utf-8", "replace"),
                                                 time.strftime("%Y-%m-%d %H:%M:%S"))
    except Exception:  # noqa: BLE001 -- a calendar that cannot be read is an empty one, never a failed GET
        pass
    # the values of the bases: the catalogue's (the vendor's originals), each adopted base read in its place
    base_vals = tweaks_facts(cat)
    for rel in sorted(cat["files"]):
        if adopted(rel):
            _tweaks_put_facts(cat, groups, base_vals, rel, facts[rel])
    drop_file, quest_file = cat["domains"]["dropFile"], cat["quests"]["file"]
    free = (facts.get(drop_file) or {}).get("free") or {}
    own = (facts.get(drop_file) or {}).get("own") or {}
    rewards = (facts.get(quest_file) or {}).get("rewards") or {}
    drop_kept = set((view["files"].get(drop_file) or {}).get("kept") or []) \
        if state_of(drop_file) in ("ours", "original") else set()
    quest_kept = set((view["files"].get(quest_file) or {}).get("kept") or []) \
        if state_of(quest_file) in ("ours", "original") else set()
    vendor_rewards = ((_tweaks_vendor_facts(version, cat, groups, quest_file, stamp) or {}).get("rewards") or {}) \
        if adopted(quest_file) else {}
    trees = set()
    if adopted(drop_file):
        vendor_path, member = _tweaks_vendor_source(version, cat, drop_file)
        try:
            vendor_drop = (tweaks_shipped_originals(version, {drop_file: member})[0].get(drop_file) if member
                           else _tweaks_read(vendor_path)) if vendor_path else None
            base_drop = computed[drop_file]["base"] if drop_file in computed \
                else _tweaks_entry_base(version, drop_file, view["files"][drop_file])
        except AgentError:
            vendor_drop = base_drop = None
        trees = _tweaks_trees_changed(cat, base_drop, vendor_drop) if vendor_drop and base_drop else set(
            cat["domains"]["list"])
    group_of = {str(did): int(gid) for gid, lineup in lineups.items() for did in lineup["dungeons"]}
    levels = _tweaks_domain_levels(cat)

    def value(kind, key, default):
        held = base_vals[kind].get(key)
        return default if held is None else held

    def domain(did, d):
        cost, level = value("costs", did, d["cost"]), value("domainLevels", did, d["level"])
        entry = {"kind": d["kind"], "cost": cost, "max": min(d["max"], TWEAK_LIMITS["multiplierMax"]),
                 "level": level, "free": free.get(str(d["root"]), 0), "own": own.get(str(d["root"]), [])}
        if did in trees:
            entry["gamePreview"] = d.get("preview", [])  # (its reward tree is not the vendor's: no preview of it)
        else:
            entry["preview"] = d.get("preview", [])
        if cost != d["cost"]:
            entry["gameCost"] = d["cost"]
        if level != d["level"]:
            entry["gameLevel"] = d["level"]
        if str(d["root"]) in drop_kept:
            entry["kept"] = True  # (its reward row as the hand left it: no multiplier, no extra item)
        if did in group_of:
            entry["group"] = group_of[did]  # the monster group its fight spawns from; `lineups` is keyed by it
        # (what `level` can be set to; absent = it cannot be set -- also while the line-up's own script, which
        #  the range is held to, is one `sections.domains.files` names, or one taken over with an entry above
        #  the line-up's level (`levelFiles`): a document that sets it is blocked)
        script = lineups[str(group_of[did])]["file"] if did in group_of else None
        if did in levels and state_of(script) in ("original", "ours") and not level_locked(script):
            entry["levels"] = list(levels[did])
        return entry

    def slots_of(gid, listed):
        held = base_vals["slots"].get(str(gid)) or {}
        slots = dict((cfg, monster if held.get(cfg) is None else held[cfg]) for cfg, monster in listed.items())
        return slots, dict((cfg, monster) for cfg, monster in listed.items() if slots[cfg] != monster)

    def chamber(lid, c):
        level = value("levels", lid, c["level"])
        out_c = dict(c, level=level, halves=[])
        if level != c["level"]:
            out_c["gameLevel"] = c["level"]
        for half in c["halves"]:
            h = dict((k, v) for k, v in half.items() if k != "file")
            h["slots"], game = slots_of(half["group"], half["slots"])
            if game:
                h["gameSlots"] = game
            out_c["halves"].append(h)
        return out_c

    def lineup(gid, lu):
        entry = dict((k, lu[k]) for k in ("dungeons", "level", "top", "slots", "waves") if k in lu)
        entry["slots"], game = slots_of(gid, lu["slots"])
        if game:
            entry["gameSlots"] = game
        return entry

    def reward(rid, r):
        entry = {"kind": r["kind"], "quests": r["quests"], "edit": r["edit"], "items": rewards.get(rid, [])}
        if "tier" in r:
            entry["tier"] = r["tier"]  # (a hangout reward: the number of the chapter's endings it asks for)
        if rid in quest_kept:
            entry["kept"] = True  # (the row as the hand left it: no multiplier touches it)
        elif rid in vendor_rewards and vendor_rewards[rid] != entry["items"]:
            entry["game"] = vendor_rewards[rid]
        return entry

    resin = dict((k, value("resin", k, cat["resin"][k])) for k in ("cap", "minutes", "hardMax"))
    game_resin = dict((k, cat["resin"][k]) for k in ("cap", "minutes", "hardMax") if resin[k] != cat["resin"][k])
    if game_resin:
        resin["game"] = game_resin
    suspects = [rel for rel in sorted(cat["files"]) if state_of(rel) == "changed" or adopted(rel)]
    out.update(
        sections=sections,
        ownRefused=None if changing else tweaks_own_refused(version, cat, suspects),
        limits={k: (list(v) if isinstance(v, list) else v) for k, v in TWEAK_LIMITS.items()},
        resin=resin,
        monsters={mid: [m["tier"], m.get("boss", 0)] for mid, m in cat["monsters"].items()},
        abyss={"active": active, "schedules": schedules, "floors": cat["abyss"]["floors"],
               "chambers": dict((lid, chamber(lid, c)) for lid, c in cat["abyss"]["chambers"].items())},
        domains={did: domain(did, d) for did, d in cat["domains"]["list"].items()},
        # (always answered, empty without line-ups: a page reads from the key that this agent knows them)
        lineups=dict((gid, lineup(gid, lu)) for gid, lu in lineups.items()),
        items=cat["items"],
        quests={"keep": list(cat["quests"].get("keep") or []),
                "rewards": dict((rid, reward(rid, r)) for rid, r in cat["quests"]["rewards"].items())})
    if over is not None and (_tweaks_stamp(rec_path) != before or tweaks_job_running(version)):
        # (the record changed, or a job of the version started, while the answer read the files: what looked
        #  changed outside Relic may be that job's own write -- the answer again, with no take-over computed)
        return tweaks_info(version, changing=True)
    return out


# -- the game server's verdict --
# No restart applies a change. Every service that loads the data files (TWEAKS_DATA_SERVICES) rebuilds its
# whole config from disk when it boots and when it receives SIGHUP -- on its main thread, one load at a time,
# minutes each -- and says how each load ended in its log, the DebugFile its rendered config names under
# <stack>/server/<service>/ (tweaks_log_stem): every level in the one file, which the server renames to
# <name>.log.<date>.<number> when it exits and at midnight (a start on the same day renames it back and
# appends). Whether a service also reloads BY ITSELF is a property of its build: one build does it every 300 s
# whatever its config says and states nothing, another states the interval it read when it starts and after
# every signalled reload that ends well and, with the value the vendor ships, never reloads by itself. The
# agent reads that from the service's own log, never from the version, and counts on a timer only where the
# log shows one (tweaks_reload_timer). A load that fails at a RELOAD leaves the config before it in use and
# only says so there; a load that fails at a BOOT ends the process. So the log IS the verdict, and the order of
# its lines the proof: no clock is compared (the lines carry the container's time, the files the box's).
# THE JUDGE IS THE GAME SERVER ALONE, signalled ONCE for the files of a write. NEVER TWO SERVICES ASKED AT A
# TIME: a reload builds a second complete config beside the one in use (a box with little memory has to carry
# it), so a service is asked only while no other one is in a load it was asked for (_tweaks_quiet). The other
# data-loading services run the same loader over the same files: where they reload by themselves they pick a
# change up at their own next reload, neither signalled nor waited for; where the game server does not, they
# are asked after its verdict, one at a time, each awaited through its own log (tweaks_follow). A file that
# changed while such a service ran and that it was not asked to read leaves `unread` on the record.

T_TWEAKS_VERDICT = 1200     # the least a wait for one load may last (tweaks_wait_limit)
T_TWEAKS_BOOT = 3600        # seconds the data-loading services get to finish starting -- nothing is written meanwhile
TWEAKS_LOAD_FACTOR = 4      # a wait for one load: this many times the longest load the service's log shows
T_TWEAKS_JOB = 5400         # every wait of the gameplay settings of ONE job together
# the jobs whose work ends in such waits: POST /server/tweaks {cancel} stops them
TWEAKS_STOP_KINDS = ("tweaks", "start", "provision", "setup", "relocate")
TWEAKS_POLL = 2             # seconds between two looks at a log during a wait
TWEAKS_ALIVE_EVERY = 10     # seconds between two looks at the containers during a wait
TWEAKS_WAIT_NOTE = 60       # seconds between two job lines that say the wait goes on
TWEAKS_LOG_TAIL = 8 << 20   # bytes of a log's end read for what it says of the service as it is
TWEAKS_LOG_CHUNK = 4 << 20  # bytes of a log taken in per read
# They load the data files (the vendor's tothemoonserver is not one: it runs under the donotstart profile without
# the data it needs, and the agent never lifts that profile).
TWEAKS_DATA_SERVICES = (TWEAKS_GAME_SERVICE, "multiserver", "pathfindingserver")
# ...and the ones tweaks_follow asks after the game server's verdict where they do not reload by themselves: all but
# the pathfinding server, which the agent has never signalled. It reads a change at its own next load where it
# reloads by itself, and when it starts where it does not -- a package whose services do not reload by themselves
# ships it switched off (the vendor's donotstart profile, no navmesh to load).
TWEAKS_FOLLOWERS = tuple(s for s in TWEAKS_DATA_SERVICES[1:] if s != PATHFINDING_SERVICE)
# What those services write on their main thread -- matched by function tag and text, never by the source
# position in front of it (it differs from one version to another).
TWEAKS_LOG_BOOT = "[setTimeOffsetFromFile]"             # the first line of every process; no reload writes it
TWEAKS_LOG_UP = ("][init] init app ", " succ")          # ...and its boot is over: the load ended well, the app is up
TWEAKS_LOG_LOAD = "][loadConfig] load log_level_mask="  # a load begins (a boot, a signal, a build's own timer)
TWEAKS_LOG_ACCEPTED = "reload config succ"              # a load ended well (a boot's too): that config is in use
TWEAKS_LOG_REFUSED = "reload config failed"             # a load ended badly (the server writes it twice)
TWEAKS_LOG_REASON = "[CONFIG_ERROR]"                    # a line that says why a load fails
TWEAKS_LOG_SHAPE = "col_num="                           # the warning that names a table row of the wrong width
TWEAKS_LOG_SIGNAL = "][processSignal] catch sig SIGHUP"  # a SIGHUP was caught: the load after it was asked for
# A build that reads <AutoReloadConfig interval> states what it read when a process starts and again after every
# load it was signalled for that ends well (0: it never reloads by itself); a build that does not read it states
# nothing.
TWEAKS_LOG_INTERVAL = "][initServerConfig] AutoReloadConfig interval:"
_TWEAKS_INTERVAL_RE = re.compile(r"\]\[initServerConfig\] AutoReloadConfig interval:(-?\d{1,9})\b")
_TWEAKS_COST_RE = re.compile(r"reload config succ, timecost=(\d{1,12})ms")  # how long a load that ended well took
TWEAKS_TIMER_RANGE = (60, 600)  # a stated reload interval the agent counts on, seconds (tweaks_reload_timer)
# the head of a log line: its level and its thread (1 = the main thread), then the source position
_TWEAKS_LOG_HEAD_RE = re.compile(r"LOG_([A-Z_]+) \d{4}-\d\d-\d\d \d\d:\d\d:\d\d \d+ (\d+) (?:\[[^\[\]]*\])?")


def tweaks_log_lines(data):
    """A piece of a log (bytes) -> ([its whole lines as text], the number of bytes they take). What follows
    the last line break is a line the server is still writing: it stays for the next read. Decoded with
    errors="replace" -- a byte that is not text must not stop the reading. Pure."""
    end = data.rfind(b"\n") + 1
    return [raw.decode("utf-8", "replace").rstrip("\r") for raw in data[:end].split(b"\n")[:-1]], end


def tweaks_log_reason(line):
    """One line of the log as a refusal quotes it: without its level, time, thread and source position, the
    text as the server wrote it, trimmed, at most 300 characters. Pure."""
    text = line.strip()
    head = _TWEAKS_LOG_HEAD_RE.match(text)
    text = text[head.end():].strip() if head else text
    return text if len(text) <= 300 else text[:297] + "..."


def _tweaks_window():
    """The lines of ONE load that may say why it fails, at most three of each kind (the first ones name the
    cause, the later ones only repeat it up the call chain)."""
    return {"shape": [], "tagged": [], "errors": []}


def _tweaks_window_note(window, line):
    """A line of a load, kept when it may be a reason: the warning that names a table row of the wrong width,
    a tagged reason line, an error line of the main thread. A line without a head is the continuation of
    another one (the server dumps a script that does not parse): never a reason."""
    head = _TWEAKS_LOG_HEAD_RE.match(line)
    if head is None:
        return
    kind = "shape" if TWEAKS_LOG_SHAPE in line else "tagged" if TWEAKS_LOG_REASON in line \
        else "errors" if (head.group(1), head.group(2)) == ("ERROR", "1") else None
    if kind and len(window[kind]) < 3:
        window[kind].append(tweaks_log_reason(line))


def _tweaks_reasons(window):
    """The at most three lines a refusal quotes: the row of the wrong width first (the load names it nowhere
    else), then the tagged reason lines -- or, when the load wrote none, the error lines of its thread."""
    return (window["shape"] + (window["tagged"] or window["errors"]))[:3]


def tweaks_log_event(line):
    """What ONE line of a data-loading service's log tells of its loads: "boot" (the first line of a
    process), "up" (its boot is over), "load" (a load begins), "accepted" / "refused" (a load ended),
    "signal" (a SIGHUP was caught: the load after it was asked for), "interval" (the reload interval the
    process states it read), None (anything else). Only a line that starts a record counts: the
    continuation lines of a dump (the server prints a script that does not parse) tell nothing, whatever
    text they hold. Pure."""
    if not line.startswith("LOG_"):
        return None
    if TWEAKS_LOG_REFUSED in line:
        return "refused"
    if TWEAKS_LOG_ACCEPTED in line:
        return "accepted"
    if TWEAKS_LOG_LOAD in line:
        return "load"
    if TWEAKS_LOG_BOOT in line:
        return "boot"
    if TWEAKS_LOG_UP[0] in line and TWEAKS_LOG_UP[1] in line.split(TWEAKS_LOG_UP[0], 1)[1]:
        return "up"
    if TWEAKS_LOG_SIGNAL in line:
        return "signal"
    if TWEAKS_LOG_INTERVAL in line and _TWEAKS_INTERVAL_RE.search(line):
        return "interval"
    return None


def tweaks_verdict_blank():
    """What tweaks_verdict_feed starts from: no load begun, no verdict, no reason."""
    return {"load": False, "verdict": None, "reasons": [], "window": _tweaks_window()}


def tweaks_verdict_feed(state, lines, own=False):
    """The lines the game server appended to its log AFTER the files were written (THE OFFSET), fed in the
    order it wrote them, in one piece or in many -> `state`, whose "verdict" is None (none yet), "accepted",
    "refused" (with "reasons") or "restarted". The order of the lines of the server's main thread decides:
      * a load begins: it began after the write and read every new file -- the next verdict is the answer;
      * a load that ended well: ACCEPTED when a load began before it; one without that began before the
        write was complete and proves nothing -- passed over, the wait goes on;
      * a load that ended badly: REFUSED wherever it stands -- the files were accepted before the write, so
        the write is what changed. Its reasons: what the lines since the last load began say (_tweaks_reasons).
        `own`: the files were NOT known to be accepted before the write (originals read right after a
        refusal, a file broken by hand) -- then only a load that began after the offset answers, as for a
        load that ended well: an earlier load's failure, or the second line the server writes for it seconds
        after the first, is passed over;
      * the first line of a process: the game server restarted under the wait -- no verdict will come from
        the load that was asked for.
    A state that holds a verdict takes no more lines. Pure."""
    for line in lines:
        if state["verdict"] is not None:
            break
        event = tweaks_log_event(line)
        if event == "refused" and own and not state["load"]:
            state["window"] = _tweaks_window()
        elif event == "refused":
            state["verdict"], state["reasons"] = "refused", _tweaks_reasons(state["window"])
        elif event == "boot":
            state["verdict"] = "restarted"
        elif event == "load":
            state["load"], state["window"] = True, _tweaks_window()
        elif event == "accepted" and state["load"]:
            state["verdict"] = "accepted"
        elif event == "accepted":
            state["window"] = _tweaks_window()
        elif event is None:
            _tweaks_window_note(state["window"], line)
    return state


def tweaks_facts_blank():
    """What tweaks_facts_feed starts from: a log that holds no first line of a process tells of a service
    that is up, and one that holds no verdict tells of no refusal."""
    return {"booting": False, "verdict": None, "reasons": [], "window": _tweaks_window(), "loads": 0, "judged": 0,
            "whole": False, "interval": None, "unasked": 0, "cost": 0, "loaded": False, "signalled": False,
            "asked": False}


def tweaks_facts_feed(state, lines):
    """What the log of a data-loading service says of the service AS IT IS, fed in the order written (the end
    of the log first, then what is appended) -> `state`:
      "booting":  the last first-line-of-a-process has no "init app ... succ" after it -- the service is
                  still in the load of its boot, which ENDS the process when it meets a file it refuses;
      "verdict":  how the last load that ended, ended -- "accepted" | "refused" | None (none in these lines);
      "reasons":  of that refusal (the second line the server writes for one refusal keeps them);
      "loads":    how many loads these lines saw BEGIN;
      "judged":   that number at the last verdict. A caller that noted "loads" at some moment knows by it
                  whether a verdict is of a load that began AFTER that moment ("judged" above its note) --
                  one that read the files as they were from then on -- or of a load that was already under
                  way; the second line of one refusal does not move it;
      "whole":    the first line of a process is among these lines -- the boot of the process that runs is
                  in view;
      "interval": the last interval the process that runs stated in these lines (at its start, after a
                  signalled load that ended well), None when it stated none in view;
      "unasked":  loads that began with no `catch sig SIGHUP` line since the load before them began -- loads
                  the service started by itself. A boot's own load is never one, nor the first load of these
                  lines when no boot is in front of it (what stood before it was not read); counted over every
                  process in view: a build's timer is the build's;
      "cost":     the longest load these lines show ending well, ms;
      "loaded" / "signalled": a load of the process that runs is in view / a signal was caught since it
                  began;
      "asked":    the load that began last was asked for -- a signal was caught since the load before it.
    The first line of a process starts the account over -- all but "whole", "unasked" and "cost": what a
    process before it loaded or refused says nothing of the one that runs. Pure."""
    for line in lines:
        event = tweaks_log_event(line)
        if event == "boot":
            state.update(booting=True, verdict=None, reasons=[], window=_tweaks_window(), whole=True, interval=None,
                         loaded=False, signalled=False, asked=False)
        elif event == "up":
            state["booting"] = False
        elif event == "load":
            if state["loaded"] and not state["signalled"]:
                state["unasked"] += 1
            state["loads"] += 1
            state["window"], state["asked"] = _tweaks_window(), state["signalled"]
            state["loaded"], state["signalled"] = True, False
        elif event == "signal":
            state["signalled"] = True
        elif event == "interval":
            state["interval"] = int(_TWEAKS_INTERVAL_RE.search(line).group(1))
        elif event == "refused":
            if state["verdict"] != "refused" or state["loads"] > state["judged"] or any(state["window"].values()):
                state["reasons"] = _tweaks_reasons(state["window"])  # (of ANOTHER load than the last refusal's)
            state["verdict"], state["window"], state["judged"] = "refused", _tweaks_window(), state["loads"]
        elif event == "accepted":
            state["verdict"], state["reasons"], state["window"] = "accepted", [], _tweaks_window()
            state["judged"] = state["loads"]
            took = _TWEAKS_COST_RE.search(line)
            if took:
                state["cost"] = max(state["cost"], int(took.group(1)))
        else:
            _tweaks_window_note(state["window"], line)
    return state


def tweaks_reload_timer(facts):
    """Whether a service's log shows that its build reloads the data files BY ITSELF -- on positive evidence
    only. A stated interval decides (TWEAKS_TIMER_RANGE: under it a build refuses the value or never reloads,
    over it the wait for its next load would not fit the limits). Where the process states none, loads it
    began with no signal since the load before them: one where its boot is in view, two where it is not.
    Everything else -- a stated 0, a log that shows none of it, one of asked loads only -- is no timer: the
    path that is right on every stack, only slower (the agent then asks for every load it needs). Pure."""
    if facts["interval"] is not None:
        return TWEAKS_TIMER_RANGE[0] <= facts["interval"] <= TWEAKS_TIMER_RANGE[1]
    return facts["unasked"] >= (1 if facts["whole"] else 2)


def tweaks_wait_limit(cost_ms):
    """Seconds a wait for ONE load of a service may last: TWEAKS_LOAD_FACTOR times the longest load its log shows
    ending well (tweaks_facts_feed's "cost", ms) -- a wait can span a load already under way and the one asked
    for, and a load can take longer than an earlier one --, rounded up to a whole minute (the job lines say
    minutes), never under T_TWEAKS_VERDICT and never over half of T_TWEAKS_JOB (a whole minute; the floor wins
    over it): one slow load in view must not make a wait that takes a whole job's time, or no write would ever
    find room for its verdict and no follow for its service. Pure."""
    seconds = max(T_TWEAKS_VERDICT, TWEAKS_LOAD_FACTOR * int(cost_ms or 0) // 1000)
    return min(max(T_TWEAKS_VERDICT, T_TWEAKS_JOB // 120 * 60), -(-seconds // 60) * 60)


def _tweaks_minutes(seconds):
    """A limit as the job lines say it: whole minutes, rounded up. Pure."""
    return -(-int(seconds) // 60)


def _tweaks_deadline(job):
    """When the gameplay settings' waits of this job must be over: T_TWEAKS_JOB seconds after the first of them
    began, kept on the job so that every later wait of the same job counts against the same time."""
    until = getattr(job, "tweaks_until", None)
    if until is None:
        until = time.time() + T_TWEAKS_JOB
        job.tweaks_until = until
    return until


def _tweaks_stop_asked(job):
    """Whether POST /server/tweaks {cancel: true} asked this job's waits to end."""
    return getattr(job, "tweaks_stop", False) is True


def tweaks_service_facts(version, service):
    """What the log of a data-loading service says of it as it is (tweaks_log_history + tweaks_facts_feed: is
    it booting, how did its last load end, does it reload by itself, how long its loads take, is a load it was
    asked for under way), or None when its log cannot be read. Reads the log only -- no docker call."""
    try:
        _mark, lines = tweaks_log_history(tweaks_log_dir(version, service), tweaks_log_stem(version, service))
    except (OSError, AgentError):
        return None
    return tweaks_facts_feed(tweaks_facts_blank(), lines)


def _tweaks_dated_facts(version):
    """What the end of the game server's latest dated log says of it (tweaks_facts_feed) -- for when its ACTIVE log
    is not there: the server renames that log when the process exits, so a game server that is down has none.
    The end of the dated log in front of it is read as well while the latest one is shorter than TWEAKS_LOG_TAIL
    (a start on another day began a new file). None when the active log IS there (one that cannot be read says
    nothing), when there is no dated log, or when it cannot be read. Logs only -- no docker call."""
    try:
        folder, stem = tweaks_log_dir(version), tweaks_log_stem(version, TWEAKS_GAME_SERVICE)
        if os.path.lexists(os.path.join(folder, stem + ".log")):
            return None
        dated = _tweaks_dated_logs(folder, stem)
        if not dated:
            return None
        with open(dated[-1], "rb") as f:
            lines, _offset, whole = _tweaks_log_end(f, TWEAKS_LOG_TAIL)
        if whole and len(dated) > 1:
            with open(dated[-2], "rb") as f:
                lines = _tweaks_log_end(f, TWEAKS_LOG_TAIL)[0] + lines
    except (OSError, AgentError):
        return None
    return tweaks_facts_feed(tweaks_facts_blank(), lines)


def _tweaks_dated_timer(version):
    """Whether the game server's build reloads the data files by itself (tweaks_reload_timer), read from the end
    of its latest dated log (_tweaks_dated_facts) -- the build is the stack's, not the process's. None when that
    log says nothing."""
    facts = _tweaks_dated_facts(version)
    return None if facts is None else tweaks_reload_timer(facts)


def tweaks_stack_timer(version):
    """Whether this version's services reload the data files by themselves, as the game server's log shows it:
    its active log (tweaks_service_facts), or -- when there is none, a game server that is down -- the latest
    dated one (_tweaks_dated_timer). True / False, or None when no log of it can be read. Logs only -- no docker
    call."""
    facts = tweaks_service_facts(version, TWEAKS_GAME_SERVICE)
    return tweaks_reload_timer(facts) if facts is not None else _tweaks_dated_timer(version)


def tweaks_none_run(version):
    """Whether no service that loads the data files runs in this version's stack -- every one of them then reads
    the files as they are when it starts: True (the stack is not listed, or docker reports none of
    TWEAKS_DATA_SERVICES as "running"), False (one runs -- a game server that is down does not take the others
    with it: a boot over a file it refuses ends that process alone), None (docker did not say). The `compose
    ps` is asked only of a listed stack; the non-logging runner."""
    up, err = stack_up(version)
    if err:
        return None
    if not up:
        return True
    states = tweaks_service_states(version)
    if states is None:
        return None
    return not any(states.get(service) == "running" for service in TWEAKS_DATA_SERVICES)


def tweaks_log_dir(version, service=TWEAKS_GAME_SERVICE):
    """Where a service of this version writes its logs."""
    return os.path.join(stack_dir(version), "server", service, "log")


_TWEAKS_DEBUGFILE_RE = re.compile(r'<DebugFile\s+path="log/([A-Za-z0-9_][A-Za-z0-9_.\-]{0,63})\.log"')


def tweaks_log_stem(version, service):
    """The name a data-loading service writes its log under in tweaks_log_dir(version, service): the
    <DebugFile path="log/<name>.log"> of its rendered config, <stack>/server/<service>/conf/<service>.xml (a
    vendor template can name another service's: tothemoonserver's writes log/pathfindingserver.log in its own
    folder), else the service's own name. Only a plain name directly under log/ is taken. Remembered per file
    stamp. Never raises."""
    def load(path):
        try:
            with open(path, "rb") as f:
                found = _TWEAKS_DEBUGFILE_RE.search(f.read().decode("utf-8", "replace"))
        except OSError:
            return service
        return found.group(1) if found else service
    try:
        return _tweaks_cached("logstem", os.path.join(stack_dir(version), "server", service, "conf", service + ".xml"),
                              load)
    except Exception:  # noqa: BLE001 -- a version without a folder: the name its service would use
        return service


def _tweaks_log_id(st):
    """What tells one log file from another through a rename -- (device, inode) where the filesystem gives
    them, else None."""
    return (st.st_dev, st.st_ino) if st.st_ino else None


def tweaks_log_open(folder, service, tail=0):
    """The ACTIVE log of a service, <folder>/<service>.log, as it is right now -> (mark, lines): the mark
    tweaks_log_read goes on from -- with tail=0 exactly the end of the file: THE OFFSET of an apply -- and
    the whole lines of its last `tail` bytes (a piece that starts inside a line loses that line; a line that
    is still being written is left for the mark). The end is the end of the OPENED file. Raises OSError: no
    such log, or one that cannot be read."""
    return _tweaks_log_tail(folder, service, tail)[:2]


def _tweaks_log_end(f, tail):
    """An OPENED log -> (the whole lines of its last `tail` bytes, the offset behind them, whether that is
    the whole file)."""
    size = f.seek(0, os.SEEK_END)
    start = max(0, size - tail)
    f.seek(start)
    data = f.read(size - start)
    skip = data.find(b"\n") + 1 if start else 0
    lines, used = tweaks_log_lines(data[skip:])
    return lines, start + skip + used, start == 0


def _tweaks_log_tail(folder, service, tail):
    """tweaks_log_open, plus whether the lines handed out are all the active log holds."""
    with open(os.path.join(folder, service + ".log"), "rb") as f:
        ident = _tweaks_log_id(os.fstat(f.fileno()))
        lines, offset, whole = _tweaks_log_end(f, tail)
    return {"folder": folder, "service": service, "id": ident, "offset": offset}, lines, whole


def _tweaks_dated_logs(folder, service):
    """The logs of a service that the server renamed, <service>.log.<date>.<number>, the latest LAST -- by
    the numbers in the name, never by a file's time (a copy or an extraction rewrites that) -- and never the
    error / warning / cmd logs beside them. A folder that cannot be listed has none."""
    name_re = re.compile(re.escape(service) + r"\.log((?:\.[0-9]+)+)")
    found = []
    try:
        names = os.listdir(folder)
    except OSError:
        return found
    for name in names:
        numbers = name_re.fullmatch(name)
        if numbers:
            found.append((tuple(int(n) for n in numbers.group(1)[1:].split(".")), os.path.join(folder, name)))
    return [path for _numbers, path in sorted(found)]


def tweaks_log_history(folder, service, tail=TWEAKS_LOG_TAIL):
    """What the log of a service says of the service AS IT IS -> (mark, lines): the end of its active log
    (tweaks_log_open: the mark goes on from there) and, while that log is no longer than `tail`, the end of
    the latest dated log in front of it. The server starts a new log at midnight, so a boot or a load can
    begin in one file and end in the next: the two are read as the one log they are. A log from before the
    process that runs changes nothing -- the first line of a process starts the account over. Raises
    OSError: no active log, or a log that cannot be read (the dated one too -- what cannot be read says
    nothing, and the caller takes that for a service that boots)."""
    return _tweaks_log_past(folder, service, tail)[:2]


def _tweaks_log_past(folder, service, tail):
    """tweaks_log_history, plus whether the lines handed out begin where a log file begins: False when
    they are the last `tail` bytes of a longer one -- what the service wrote before them was not read."""
    mark, lines, whole = _tweaks_log_tail(folder, service, tail)
    before = _tweaks_dated_logs(folder, service) if whole else []
    if before:
        with open(before[-1], "rb") as f:
            earlier, _offset, whole = _tweaks_log_end(f, tail)
        lines = earlier + lines
    return mark, lines, whole


def _tweaks_log_rest(f, mark):
    """The whole lines of one OPENED log file from the mark's offset to its end; the offset moves past them,
    never past a line that is still being written. A read that fails hands out what it had."""
    lines = []
    try:
        while True:
            f.seek(mark["offset"])
            data = f.read(TWEAKS_LOG_CHUNK)
            got, used = tweaks_log_lines(data)
            if not used and len(data) >= TWEAKS_LOG_CHUNK:
                used = len(data)  # no line break in a whole chunk: nothing this log writes -- passed over
            lines += got
            mark["offset"] += used
            if len(data) < TWEAKS_LOG_CHUNK:
                break
    except OSError:
        pass
    return lines


def _tweaks_renamed_log(mark):
    """The log a mark was following, once the server renamed it (it exited, or its day ended): the dated
    file that IS that file where the filesystem tells files apart, else the latest dated one that is at least
    as long as the mark's offset. None when there is none."""
    for path in reversed(_tweaks_dated_logs(mark["folder"], mark["service"])):
        try:
            st = os.stat(path)
        except OSError:
            continue
        if _tweaks_log_id(st) == mark["id"] if mark["id"] is not None else st.st_size >= mark["offset"]:
            return path
    return None


def tweaks_log_read(mark):
    """The whole lines a service appended to its log since the mark (tweaks_log_open), in the order written;
    the mark moves past them. A rotation in the middle loses no line: when the active log is not the file
    the mark follows -- another file where the filesystem tells files apart, else one shorter than the
    offset -- or is not there, the renamed file is finished from the offset first, then the new active log is
    read from its beginning. A file renamed back under the active name (a start on the same day) is the same
    file and is simply read on. What a file IS and how long it is are asked of the opened file, never of its
    name. Never raises."""
    try:
        active = open(os.path.join(mark["folder"], mark["service"] + ".log"), "rb")
    except FileNotFoundError:
        active = None
    except OSError:
        return []
    lines = []
    try:
        current = None if active is None else _tweaks_log_id(os.fstat(active.fileno()))
        if active is None or not (current == mark["id"] if current is not None and mark["id"] is not None
                                  else active.seek(0, os.SEEK_END) >= mark["offset"]):
            renamed = _tweaks_renamed_log(mark)
            if renamed is not None:
                with open(renamed, "rb") as old:
                    lines += _tweaks_log_rest(old, mark)
            if active is None:
                return lines
            mark["offset"] = 0
        mark["id"] = current
        lines += _tweaks_log_rest(active, mark)
    except OSError:
        pass
    finally:
        if active is not None:
            active.close()
    return lines


# -- /status: is the game server still loading its data? --
# A game server that docker reports as running turns every client away until the load of its boot is over
# -- minutes after a Start is done. Its log says when (tweaks_facts_feed's "booting": the rule the gameplay
# settings wait by), and /status is asked every few seconds, so the log is FOLLOWED: its end is read once
# per version, every later look takes only what the server appended since. A follower lasts from one answer
# that reports the game server to the next: an answer that does not report it could not see it stop.
_BOOT_WATCH = {}  # version -> {"folder", "stem", "mark", "facts", "told"}: the follower of its game server's log
_boot_watch_lock = threading.Lock()  # one look at a time: a look moves the follower's mark


def _boot_log_cut(mark):
    """A follower that read nothing new: does its log still hold what the mark stands behind? True when the
    active log is the file the mark follows and ends in front of the mark's offset -- it was cut in place
    (emptied by hand, a copy-and-truncate rotation): whatever the server writes into it from then on lies
    in front of the mark and would never be read. Raises OSError when the log is not there to be read at
    all -- the active log cannot be opened, or there is none and its folder is gone as well. No active log
    in a folder that is there is the moment between the server's rename of the log and its next line: False,
    the follower goes on."""
    try:
        with open(os.path.join(mark["folder"], mark["service"] + ".log"), "rb") as f:
            st = os.fstat(f.fileno())
    except FileNotFoundError:
        os.stat(mark["folder"])
        return False
    return _tweaks_log_id(st) == mark["id"] and st.st_size < mark["offset"]


def game_loading(version, states):
    """Is the game server of a stack that is up still in the load of its boot? `states` = docker's state of
    each service (dead_services). True, False, or None when nothing can tell:
      * docker reports it as RESTARTING: True -- it is about to boot whatever its log says (that log still
        ends on the process that died), until its next process says it is up;
      * it does not run: None, and the follower is dropped;
      * it runs: what its log says. The first look reads the end of the log (tweaks_log_history's lines),
        a later one what was appended since (tweaks_log_read); both feed tweaks_facts_feed, whose "booting"
        is the answer. A first look that got only the last TWEAKS_LOG_TAIL bytes of a longer log, with
        neither the first line of a process nor the line that ends a boot among them, cannot tell on which
        side of its boot the process is: None, until the server writes one of the two;
      * a log that cannot be read (none yet, a folder that cannot be opened): None, the follower dropped --
        the next look starts over.
    A follower is built anew -- a first look again -- when its folder or its log's name is not where the
    version's game server logs now (the stack was moved, its rendered config names another DebugFile:
    tweaks_log_stem) and when its log was cut in place under it (_boot_log_cut): what it read is not what
    the file holds. status() calls this with no states for every version whose services it does not report,
    so a follower never outlives an answer that could not see the game server. Never raises."""
    state = (states or {}).get(TWEAKS_GAME_SERVICE)
    with _boot_watch_lock:
        if state not in ("running", "restarting"):
            _BOOT_WATCH.pop(version, None)
            return None
        try:
            folder, stem = tweaks_log_dir(version), tweaks_log_stem(version, TWEAKS_GAME_SERVICE)
            watch = _BOOT_WATCH.get(version)
            if watch is not None and (watch["folder"], watch.get("stem")) != (folder, stem):
                watch = None
            if watch is not None:
                lines = tweaks_log_read(watch["mark"])
                if not lines and _boot_log_cut(watch["mark"]):
                    watch = None
            if watch is None:
                mark, lines, whole = _tweaks_log_past(folder, stem, TWEAKS_LOG_TAIL)
                watch = {"folder": folder, "stem": stem, "mark": mark, "facts": tweaks_facts_blank(), "told": whole}
            tweaks_facts_feed(watch["facts"], lines)
            if not watch["told"]:
                watch["told"] = any(tweaks_log_event(line) in ("boot", "up") for line in lines)
            _BOOT_WATCH[version] = watch
        except (OSError, AgentError):
            _BOOT_WATCH.pop(version, None)
            return True if state == "restarting" else None
        if state == "restarting":
            watch["facts"]["booting"] = watch["told"] = True
        return watch["facts"]["booting"] if watch["told"] else None


TWEAKS_SIGNAL_TRIES = 3  # signals tried, TWEAKS_SIGNAL_GAP seconds apart, where no load comes without one
TWEAKS_SIGNAL_GAP = 5


def tweaks_signal(version, service=TWEAKS_GAME_SERVICE):
    """Ask ONE data-loading service -- the game server unless another is named -- to rebuild its config from
    disk now: SIGHUP, which the process catches (it keeps running, nobody is disconnected). Returns None, or
    why docker could not deliver it. Never two services at a time: every caller awaits one service's load
    before it asks the next (_tweaks_quiet). The non-logging runner."""
    r = _compose(stack_dir(version), "kill", "-s", "HUP", service, timeout=60)
    return None if r.returncode == 0 else _cmd_err(r, 200, "docker did not answer")


def _tweaks_ask(version, service=TWEAKS_GAME_SERVICE, tries=1):
    """tweaks_signal, tried up to `tries` times TWEAKS_SIGNAL_GAP seconds apart while docker does not deliver
    it -> None, or why the last try failed. A service that does not reload by itself is asked with
    TWEAKS_SIGNAL_TRIES: without the signal no load comes. Docker can report a failure for a signal that did
    arrive (a call that timed out after delivering it), and a signal sent again after one an idle service took
    is one more load -- it begins right after the verdict of the first, beside whatever is asked next. So the
    service's own log is marked before the first try and read again before every retry: a `catch sig SIGHUP`
    line since the mark is the signal, arrived (an idle service writes it at once) -- None, and no retry. (A
    service in the middle of a load writes that line only once the load is over; a signal sent again meanwhile
    joins the one that is pending -- one load after it, not two.) A log that cannot be read leaves the retries
    as they are."""
    mark = None
    if tries > 1:
        try:
            mark, _lines = tweaks_log_open(tweaks_log_dir(version, service), tweaks_log_stem(version, service))
        except (OSError, AgentError):
            mark = None
    for n in range(tries):
        if n and mark is not None and any(tweaks_log_event(line) == "signal" for line in tweaks_log_read(mark)):
            return None
        why = tweaks_signal(version, service)
        if why is None or n == tries - 1:
            return why
        time.sleep(TWEAKS_SIGNAL_GAP)


def _tweaks_loading(facts, asked):
    """A load of the process that runs is under way -- begun, no verdict of it yet --, with `asked` only one it
    was asked for (tweaks_facts_feed's "asked"). Pure."""
    return not facts["booting"] and facts["loads"] > facts["judged"] and (facts["asked"] or not asked)


def tweaks_asked_loading(version, service):
    """Whether a data-loading service is in the middle of a load it was ASKED for: its log shows a load of the
    process that runs under way with a `catch sig SIGHUP` line since the load before it began. A load a service
    began by itself is not one -- where the services reload by themselves those come every few minutes,
    whatever the agent does. Reads the log only; False when it cannot be read."""
    facts = tweaks_service_facts(version, service)
    return facts is not None and _tweaks_loading(facts, asked=True)


_TWEAKS_QUIET_STOP = "stopped on request"  # what _tweaks_quiet answers for a stop on request


def _tweaks_quiet(version, job, but, before, also=None):
    """In front of every signal of the gameplay settings: NEVER TWO SERVICES ASKED AT A TIME, across jobs too. A
    reload builds a second complete config beside the one in use, and a service an earlier job asked may still
    be loading when the next job asks another (a follower left silent, a stop on request). So before `but` is
    asked, no OTHER data-loading service that runs may be in a load it was asked for (tweaks_asked_loading) --
    nor, for `also` (the game server, before a follower is asked after its verdict), in any load: one it began
    since its verdict (a signal docker delivered twice, its own timer) is one more config in memory. `but` None
    with `also` the game server: the game server is asked again and awaited while a load of its own may still be
    under way -- that load ends first, so the verdict read is of the load the new signal starts. The logs
    are read first: with nothing under way there is no docker call and no job line -- on a stack whose services
    reload by themselves no load is an asked one, so its jobs ask docker nothing more. Else ONE job line, then
    each such log followed every TWEAKS_POLL seconds and docker asked every TWEAKS_ALIVE_EVERY seconds (one that
    no longer runs is not waited for; a docker that does not answer says nothing), a line every
    TWEAKS_WAIT_NOTE seconds -- up to the load wait of the service waited for (tweaks_wait_limit), never past
    the job's time (_tweaks_deadline); a stop on request ends it, and so does a game server that stops (within
    seconds: nothing is asked of a stack that stops). Returns None once nothing is under way, else why `but`
    must not be asked (_TWEAKS_QUIET_STOP for a stop on request). Never raises: `before` says what waits ("the
    game data is changed")."""
    try:
        follow = {}
        for service in TWEAKS_DATA_SERVICES:
            if service == but:
                continue
            try:
                mark, lines = tweaks_log_history(tweaks_log_dir(version, service), tweaks_log_stem(version, service))
            except (OSError, AgentError):
                continue  # (a log that cannot be read shows no load)
            facts = tweaks_facts_feed(tweaks_facts_blank(), lines)
            if _tweaks_loading(facts, asked=service != also):
                follow[service] = (mark, facts)
        if not follow:
            return None

        def names():
            return _tweaks_and(sorted(follow, key=TWEAKS_DATA_SERVICES.index))

        started, until = time.time(), _tweaks_deadline(job)
        own = max(tweaks_wait_limit(facts["cost"]) for _mark, facts in follow.values())
        limit = max(0, min(own, until - started))
        job.log("Waiting for %s to finish reading the data files before %s (up to %d minutes)..."
                % (names(), before, _tweaks_minutes(limit)))
        note_at, ps_at = started + TWEAKS_WAIT_NOTE, started
        while True:
            now = time.time()
            if now >= ps_at:
                ps_at = now + TWEAKS_ALIVE_EVERY
                states = tweaks_service_states(version)
                if states is not None and states.get(TWEAKS_GAME_SERVICE) not in ("running", "restarting"):
                    return "the game server stopped"  # (nothing is asked of a stack that stops; within seconds)
                for service in list(follow) if states is not None else []:
                    if states.get(service) != "running":
                        del follow[service]  # (it no longer runs: no config of it is in memory)
            for service in list(follow):
                mark, facts = follow[service]
                tweaks_facts_feed(facts, tweaks_log_read(mark))
                if not _tweaks_loading(facts, asked=service != also):
                    del follow[service]
            if not follow:
                return None
            if _tweaks_stop_asked(job):
                return _TWEAKS_QUIET_STOP
            if now - started >= limit:
                if limit < own:
                    return "%s had not finished reading the data files when this job's time was up" % names()
                return "%s did not finish reading the data files within %d minutes" % (names(), _tweaks_minutes(limit))
            if now >= note_at:
                note_at = now + TWEAKS_WAIT_NOTE
                job.log("Still reading: %s (%d s)..." % (", ".join(sorted(follow, key=TWEAKS_DATA_SERVICES.index)),
                                                          now - started))
            time.sleep(TWEAKS_POLL)
    except Exception as e:  # noqa: BLE001 -- what cannot be looked at is not taken for quiet
        return "the other services could not be looked at (%s)" % _failure_text(e)


def _tweaks_and(names):
    """Names as a sentence lists them: "a", "a and b", "a, b and c"."""
    names = list(names)
    return names[0] if len(names) == 1 else "%s and %s" % (", ".join(names[:-1]), names[-1])


def tweaks_wait_booted(version, job, judge=False):
    """Before a file that is not an original is written: no service that loads the data files may still be
    BOOTING. The load of a boot reads the files like any load, and a boot that meets a file the server then
    refuses ends the process -- while a Start is done long before the slowest of them is up. So: the
    services of TWEAKS_DATA_SERVICES that run now or that docker is restarting (docker is asked at once and
    every TWEAKS_ALIVE_EVERY seconds), the end of each one's log (tweaks_log_history: a boot can begin before
    midnight and end after it), then what it appends (tweaks_facts_feed); a log that cannot be read says
    nothing, and its service counts as booting. One docker reports as RESTARTING is about to boot whatever
    its log says -- that log still ends on the process that died: it counts as booting from that look on,
    until its log tells of a process that is up.
    judge=True (tweaks_judge_ready) holds the game server to one thing more, in the same wait: it must not
    be refusing the files it has. A log that ends on a failed load does not say that yet -- after a refusal
    the previous bytes are put back; a game server that reloads by itself reads them at its own next load,
    one that does not is asked ONCE, at the first look that finds no load begun since the refusal (three
    undelivered signals: the 409; nor while another service is in a load it was asked for: _tweaks_quiet).
    So the wait goes on: a load that ends well ends it, and only a load that BEGAN during the wait and fails
    says the server refuses its own files (tweaks_facts_feed's "judged" above the "loads" noted at the first
    look -- a load that was under way then may have read the files as they were before).
    While it waits: ONE job line naming what for, one every TWEAKS_WAIT_NOTE seconds. Returns what the game
    server's log says of it (tweaks_facts_feed's state). Raises AgentError(409), no file written by it: a
    service still starting after T_TWEAKS_BOOT (the boot wait: nothing is written meanwhile), one that keeps
    restarting -- two new processes of it in this wait: the first line of a process its log appends, or
    docker reporting it restarting after it was up in this wait (one restart, whichever of the two tells of
    it first) --, a game server that stopped meanwhile, a docker that does not answer, a stop on request
    (POST /server/tweaks {cancel}) and -- judge -- a game server that refuses its own files, or that did not
    read them again within the load wait of tweaks_wait_limit. Each of the two waits is bounded by what is
    left of the job's T_TWEAKS_JOB as well."""
    started, until = time.time(), _tweaks_deadline(job)
    note_at, ps_at, states, follow, since, noted = started + TWEAKS_WAIT_NOTE, started, None, {}, {}, 0
    asked = False  # (the game server was asked to read its files again in this wait)
    # the restarts of each service seen in this wait: a docker look that saw one before its log did leaves a
    # credit, which the first line of that process takes
    restarts, credit, up_seen = {}, set(), set()
    while True:
        now, looked = time.time(), None
        if _tweaks_stop_asked(job):
            raise AgentError(409, "Stopped on request -- no new settings were written.")
        if now >= ps_at:
            ps_at = now + TWEAKS_ALIVE_EVERY
            looked = tweaks_service_states(version)
            if looked is not None:
                states = looked
            if states is None:
                raise AgentError(409, "docker did not say which services run, so no new settings were written -- "
                                      "try again.")
            if states.get(TWEAKS_GAME_SERVICE) not in ("running", "restarting"):
                raise AgentError(409, "The game server stopped -- no new settings were written.")
        booting, blind = [], {}
        for service in TWEAKS_DATA_SERVICES:
            if states.get(service) not in ("running", "restarting"):
                continue
            try:
                if service in follow:
                    lines = tweaks_log_read(follow[service][0])
                    for line in lines:
                        if tweaks_log_event(line) == "boot":  # a new process of it, in this wait
                            up_seen.discard(service)
                            if service in credit:
                                credit.discard(service)
                            else:
                                restarts[service] = restarts.get(service, 0) + 1
                    tweaks_facts_feed(follow[service][1], lines)
                else:
                    mark, lines = tweaks_log_history(tweaks_log_dir(version, service),
                                                     tweaks_log_stem(version, service))
                    follow[service] = (mark, tweaks_facts_feed(tweaks_facts_blank(), lines))
                    if service == TWEAKS_GAME_SERVICE:
                        noted = follow[service][1]["loads"]
                if looked is not None and looked.get(service) == "restarting":
                    if service in up_seen and service not in credit:
                        restarts[service] = restarts.get(service, 0) + 1
                        credit.add(service)
                    up_seen.discard(service)
                    follow[service][1]["booting"] = True  # (only its next process's "up" line takes that back)
                if follow[service][1]["booting"]:
                    booting.append(service)
                elif states.get(service) == "running":
                    up_seen.add(service)
            except OSError as e:
                booting.append(service)
                blind[service] = e
        looping = [s for s in TWEAKS_DATA_SERVICES if restarts.get(s, 0) >= 2]
        if looping:
            raise AgentError(409, "%s keeps restarting, so no new settings were written -- repair it or switch it off "
                                  "first." % looping[0])
        if not booting:
            facts = follow[TWEAKS_GAME_SERVICE][1]
            if not judge or facts["verdict"] != "refused":
                return facts
            said = "Its log says: %s" % "; ".join(facts["reasons"]) if facts["reasons"] else "Its log names no reason."
            if facts["judged"] > noted:
                raise AgentError(409, "The game server refuses its own data files (a load it began while this job "
                                      "waited failed), so no new settings were written -- a data file of the "
                                      "server is damaged. " + said)
        kind = "boot" if booting else "load"
        first = kind not in since
        waited = now - since.setdefault(kind, now)
        own = T_TWEAKS_BOOT if booting else tweaks_wait_limit(facts["cost"])
        limit = max(0, min(own, until - since[kind]))
        minutes = _tweaks_minutes(limit)
        if waited >= limit and booting:
            names = _tweaks_and("%s (its log cannot be read: %s)" % (s, blind[s]) if s in blind else s
                                for s in booting)
            raise AgentError(409, "%s still starting after %d minutes, so no new settings were written -- a "
                                  "service that boots must not meet files the server has not accepted. Try again "
                                  "once it is up; one that never finishes starting has to be repaired or switched "
                                  "off first." % (names + (" is" if len(booting) == 1 else " are"), minutes))
        if waited >= limit:
            raise AgentError(409, "The game server refused its own data files at its last load and did not read "
                                  "them again within %d minutes, so no new settings were written -- try again "
                                  "later. %s" % (minutes, said))
        # A game server that does not reload by itself reads the files that were put back only when it is asked:
        # ONCE per wait, at the first look that finds its last load refused and no load begun since
        ask = not booting and not asked and not tweaks_reload_timer(facts) and facts["loads"] == facts["judged"]
        if ask:
            why = _tweaks_quiet(version, job, TWEAKS_GAME_SERVICE, "the game server is asked to read its own again")
            if why == _TWEAKS_QUIET_STOP:
                raise AgentError(409, "Stopped on request -- no new settings were written.")
            if why is None:
                why = _tweaks_ask(version, TWEAKS_GAME_SERVICE, TWEAKS_SIGNAL_TRIES)
            if why is not None:
                raise AgentError(409, "The game server refused its data files at its last load and could not be asked "
                                      "to read them again (%s), so no new settings were written -- try again later. "
                                      "%s" % (why, said))
            asked = True
        if first and booting:
            job.log("Waiting for %s to finish starting before the game data is changed (up to %d minutes)..."
                    % (_tweaks_and(booting), minutes))
        elif first and ask:
            job.log("The game server refused its data files at its last load -- it was asked to read them again; "
                    "waiting for that before the game data is changed (up to %d minutes)..." % minutes)
        elif first:
            job.log("The game server refused its data files at its last load -- waiting for it to read them again "
                    "before the game data is changed (up to %d minutes)..." % minutes)
        elif ask:
            job.log("The game server was asked to read its data files again.")
        elif now >= note_at:
            note_at = now + TWEAKS_WAIT_NOTE
            job.log("Still starting: %s (%d s)..." % (", ".join(booting), waited) if booting else
                    "The game server has not read its data files again yet (%d s)..." % waited)
        time.sleep(TWEAKS_POLL)


def tweaks_judge_ready(version, job):
    """Before a file is written: can the game server judge? No data-loading service may be booting, and the
    game server must not be refusing the files it has -- a server that does is not asked to judge new ones
    (tweaks_wait_booted with judge=True: after a refusal it is waited for to read the files that were put
    back -- at its own next load, or the load it is asked for). The same wait as a yes or no; a caller that
    needs the facts (_tweaks_apply_live) calls tweaks_wait_booted itself. Raises AgentError(409); no file was
    written by it."""
    tweaks_wait_booted(version, job, judge=True)


# What tweaks_reload_verdict answers when no verdict came -- a refusal all the same, each named for the caller
_TWEAKS_RESTARTED = "the game server restarted while it read the new settings"
_TWEAKS_STOPPED = "the game server stopped while it read the new settings"
_TWEAKS_STOP_ASKED = "the wait for its verdict was stopped on request"
_TWEAKS_UNASKED = "the game server could not be asked to read the new settings"  # + " (<why>)"


def tweaks_reload_verdict(version, job, own=False):
    """What the game server says about the data files that were JUST written -> None when it accepted them,
    else the reason it did not (as a refusal quotes it). `own`: the files were not known to be accepted before
    (tweaks_verdict_feed) -- only a load that began after THE OFFSET answers.
    1. THE OFFSET: the end of its active log, taken now -- right after the last file was renamed into place,
       before the signal. Only what it appends from here on is read: a load whose first line stands after
       the offset read every new file.
    2. ONE signal, never a second one for the same apply (the caller made sure no other service is in a load
       it was asked for: _tweaks_quiet). Where the game server reloads by itself (tweaks_reload_timer) one
       docker could not deliver is not fatal: its own next load is the answer; where it does not, the signal
       is tried TWEAKS_SIGNAL_TRIES times and one that never arrives is the answer at once: no load will come.
    3. Every TWEAKS_POLL seconds the appended lines go through tweaks_verdict_feed: accepted, refused (the
       reasons its log names), or restarted; every TWEAKS_ALIVE_EVERY seconds docker is asked whether its
       container still runs -- one that does not is a refusal too, a docker that does not answer says nothing.
    4. No verdict within the load wait of tweaks_wait_limit (the longest load its log shows, bounded by what
       is left of the job's T_TWEAKS_JOB) is a refusal, and so is a stop on request (POST /server/tweaks
       {cancel}): the caller cannot tell what the server will make of the files.
    Job lines: one when the wait starts, one every TWEAKS_WAIT_NOTE seconds while it lasts, one for the
    verdict. The caller puts the previous bytes back on anything but None. Raises OSError when the log is
    not there to take the offset from."""
    mark, _lines = tweaks_log_open(tweaks_log_dir(version), tweaks_log_stem(version, TWEAKS_GAME_SERVICE))
    facts = tweaks_service_facts(version, TWEAKS_GAME_SERVICE)
    timer = facts is not None and tweaks_reload_timer(facts)
    undelivered = _tweaks_ask(version, TWEAKS_GAME_SERVICE, 1 if timer else TWEAKS_SIGNAL_TRIES)
    state, started = tweaks_verdict_blank(), time.time()
    limit = max(0, min(tweaks_wait_limit(facts["cost"] if facts else 0), _tweaks_deadline(job) - started))
    minutes = _tweaks_minutes(limit)
    if undelivered is None:
        job.log("The game server was asked to read the new files -- waiting for its verdict (up to %d minutes)..."
                % minutes)
    elif timer:
        job.log("The game server could not be asked to read the new files (%s) -- it reads them by itself within "
                "minutes; waiting for its verdict (up to %d minutes)..." % (undelivered, minutes))
    else:
        job.log("The game server could not be asked to read the new files (%s)." % undelivered)
        return _TWEAKS_UNASKED + " (%s)" % undelivered
    note_at, alive_at = started + TWEAKS_WAIT_NOTE, started + TWEAKS_ALIVE_EVERY
    while True:
        tweaks_verdict_feed(state, tweaks_log_read(mark), own=own)
        now = time.time()
        if state["verdict"] == "accepted":
            job.log("The game server accepted the new files (after %d s)." % (now - started))
            return None
        if state["verdict"] == "refused":
            reason = "; ".join(state["reasons"]) or "the game server could not load them (its log names no reason)"
            job.log("The game server refused the new files: %s" % reason)
            return reason
        if state["verdict"] == "restarted":
            job.log("The game server restarted while it read the new files.")
            return _TWEAKS_RESTARTED
        if _tweaks_stop_asked(job):
            job.log("The wait for the game server's verdict was stopped on request.")
            return _TWEAKS_STOP_ASKED
        if now - started >= limit:
            job.log("The game server did not confirm the new files within %d minutes." % minutes)
            return "the game server did not confirm within %d minutes" % minutes
        if now >= alive_at:
            alive_at = now + TWEAKS_ALIVE_EVERY
            container = tweaks_game_state(version)
            if container is not None and container != "running":
                job.log("The game server stopped while it read the new files.")
                return _TWEAKS_STOPPED
        if now >= note_at:
            note_at = now + TWEAKS_WAIT_NOTE
            job.log("The game server is still reading the new files (%d s)..." % (now - started))
        time.sleep(TWEAKS_POLL)


def tweaks_follow(version, job):
    """After the game server accepted the files of a write, on a stack whose game server does not reload by
    itself: each service of TWEAKS_FOLLOWERS that runs (multiserver; never the pathfinding server) is asked to
    read them too -- one at a time, in that order, each awaited through its own log before the next is
    signalled, none while the game server is in a load it began since its verdict (a reload builds a second
    config beside the one in use: never two services asked at a time). One whose own log shows it reloads by
    itself is not asked; one still starting is left to the next Apply. Returns the services that were not
    brought in line (empty: all were); never raises -- a WARNING says what was not done, none of it is an
    undo."""
    after = list(TWEAKS_FOLLOWERS)
    try:
        states = tweaks_service_states(version)
        if states is None:
            job.log("WARNING: docker did not say which services run -- the other services were not asked to read the "
                    "new files; the next Apply asks them.")
            return after
        if states.get(TWEAKS_GAME_SERVICE) != "running":
            job.log("WARNING: the game server stopped -- the follow ends here; the next Apply asks the other services "
                    "that run.")
            return [s for s in after if states.get(s) == "running"]
        left = []
        for n, service in enumerate(after):
            if states.get(service) != "running":
                continue  # it reads the files when it starts
            facts = tweaks_service_facts(version, service)
            if facts is None:
                job.log("WARNING: the log of %s cannot be read -- it was not asked to read the new files; the next "
                        "Apply asks it." % service)
                left.append(service)
                continue
            if tweaks_reload_timer(facts):
                job.log("%s reads the new files at its own next load." % service)
                continue
            if facts["booting"]:
                job.log("%s is still starting -- the next Apply asks it to read the new files." % service)
                left.append(service)
                continue
            outcome = _tweaks_follow_one(version, job, service, facts)
            if outcome == "unasked":
                left.append(service)
            elif outcome in ("silent", "gone", "stop"):
                return left + [s for s in after[n:] if states.get(s) == "running"]
        return left
    except Exception as e:  # noqa: BLE001 -- the follow is never an undo, and never a failed job
        job.log("WARNING: the other services were not asked to read the new files (%s) -- the next Apply asks them."
                % _failure_text(e))
        return after


def _tweaks_follow_one(version, job, service, facts):
    """tweaks_follow for ONE service (`facts`: what its log said a moment ago) -> "read" | "refused" | "restarted" |
    "stopped" | "unasked" | "silent" | "gone" | "stop". It is not asked once the job was asked to stop, while the
    game server or another service is still in a load (_tweaks_quiet, TWEAKS_SIGNAL_GAP seconds after the verdict
    before it: a load begun right after that verdict shows by then), nor when what is left of the job's time
    would not cover its wait: a signal nobody awaits could leave it loading while the next job asks another.
    Else THE OFFSET of its own log, the signal (TWEAKS_SIGNAL_TRIES) and the wait for its verdict through that
    log (tweaks_verdict_feed), every TWEAKS_POLL seconds, docker asked every TWEAKS_ALIVE_EVERY seconds -- up to
    its own load wait (tweaks_wait_limit), never past the job's time. A refusal is a WARNING and no undo: the
    game server judged the files, and this service keeps the config it had while it runs."""
    stopped = "WARNING: stopped on request -- %s and the services after it were not asked; the next Apply asks them."
    if _tweaks_stop_asked(job):
        job.log(stopped % service)
        return "stop"
    # (a load the game server begins right after its verdict -- a signal that was pending while it loaded is served
    #  about a second after that verdict -- shows in its log only then: looked for a moment later)
    time.sleep(TWEAKS_SIGNAL_GAP)
    why = _tweaks_quiet(version, job, service, "%s is asked to read them" % service, also=TWEAKS_GAME_SERVICE)
    if why == _TWEAKS_QUIET_STOP:
        job.log(stopped % service)
        return "stop"
    if why is not None:
        job.log("WARNING: %s was not asked to read the new files (%s) -- the next Apply asks it." % (service, why))
        return "silent"
    if _tweaks_deadline(job) - time.time() < tweaks_wait_limit(facts["cost"]):
        job.log("WARNING: %s was not asked to read the new files: the job's time is up -- the next Apply asks it."
                % service)
        return "silent"
    try:
        mark, _lines = tweaks_log_open(tweaks_log_dir(version, service), tweaks_log_stem(version, service))
    except OSError as e:
        job.log("WARNING: the log of %s cannot be read (%s) -- it was not asked to read the new files; the next "
                "Apply asks it." % (service, e))
        return "unasked"
    why = _tweaks_ask(version, service, TWEAKS_SIGNAL_TRIES)
    if why is not None:
        job.log("WARNING: %s could not be asked to read the new files (%s) -- the next Apply asks it." % (service, why))
        return "unasked"
    state, started = tweaks_verdict_blank(), time.time()
    limit = max(0, min(tweaks_wait_limit(facts["cost"]), _tweaks_deadline(job) - started))
    job.log("%s was asked to read the new files -- waiting for it (up to %d minutes)..."
            % (service, _tweaks_minutes(limit)))
    note_at, alive_at = started + TWEAKS_WAIT_NOTE, started + TWEAKS_ALIVE_EVERY
    while True:
        tweaks_verdict_feed(state, tweaks_log_read(mark))
        now = time.time()
        if state["verdict"] == "accepted":
            job.log("%s read the new files (after %d s)." % (service, now - started))
            return "read"
        if state["verdict"] == "refused":
            job.log("WARNING: %s refused the files the game server accepted: %s -- it keeps the settings it had while "
                    "it runs, and it would not start with these files: change the settings or restore the original "
                    "game before the version is started again."
                    % (service, "; ".join(state["reasons"]) or "its log names no reason"))
            return "refused"
        if state["verdict"] == "restarted":
            job.log("%s restarted while it read the new files -- it reads them as it starts." % service)
            return "restarted"
        if _tweaks_stop_asked(job):
            job.log("WARNING: stopped on request -- %s and the services after it were not waited for; the next "
                    "Apply asks them." % service)
            return "stop"
        if now - started >= limit:
            job.log("WARNING: %s did not read the new files within %d minutes -- no service after it was asked; the "
                    "next Apply asks again." % (service, _tweaks_minutes(limit)))
            return "silent"
        if now >= alive_at:
            alive_at = now + TWEAKS_ALIVE_EVERY
            states = tweaks_service_states(version)
            if states is not None and states.get(TWEAKS_GAME_SERVICE) != "running":
                job.log("WARNING: the game server stopped -- the follow ends here; the next Apply asks the other "
                        "services that run.")
                return "gone"
            if states is not None and states.get(service) != "running":
                job.log("WARNING: %s stopped while it read the new files -- it reads them when it starts again."
                        % service)
                return "stopped"
        if now >= note_at:
            note_at = now + TWEAKS_WAIT_NOTE
            job.log("%s is still reading the new files (%d s)..." % (service, now - started))
        time.sleep(TWEAKS_POLL)


# -- POST /server/tweaks, the leftover rule of every boot and the last step of a Start --

def _tweaks_no_catalogue(version):
    return AgentError(409, "Version %s has no gameplay settings on this server: the agent ships no catalogue for "
                           "it (payloads/%s/tweaks.json)." % (version, version))


def tweaks_preflight(body):
    """The synchronous half of POST /server/tweaks (a body without `cancel`: that one is a stop request) ->
    (version, the document checked -- None for a Revert / a Reset --, the takenKey the page read, {"revert" |
    "reset": [cards]} -- {} for a document), or the AgentError to answer: 400 for a request that cannot be right
    -- an unknown version; none, or more than one, of `tweaks` (the whole settings document), `revert` and
    `reset` (the cards whose files are put back); a `tweaks` that is not an object (never read as {}: {} is no
    setting, every file back on its base); cards that are not a list of cards of TWEAK_SECTIONS, at least one,
    none twice; a takenKey that is not a string; whatever normalise_tweaks refuses against the catalogue
    (tweaks_unknown_facts, unread: the stack is not read here, so nothing whose "no change" depends on its bases
    is dropped, and a domain's own cost -- which a document built on a base taken over may state at that base's
    value outside the range -- is held to its type alone; the job normalises against the bases) -- and 409 for a
    version this agent ships no catalogue for.
    Never a 404 (the launcher reads one as "this agent lacks the route"): the stack's folder is not looked at
    here, a version that is not installed is the job's own error. An absent takenKey is "" -- no file taken over
    seen."""
    version = body["version"]
    if not isinstance(version, str):
        raise AgentError(400, "version must be a string")
    check_known(version)
    named = [key for key in ("tweaks",) + TWEAKS_FILE_OPS if key in body]
    if not named:
        raise AgentError(400, "tweaks is required: the whole settings document ({} = no setting: every file holds its "
                              "base) -- or revert / reset: the cards whose files are put back")
    if len(named) > 1:
        raise AgentError(400, "only one of tweaks, revert and reset: %s were sent" % _tweaks_and(named))
    op = {}
    if named[0] == "tweaks" and not isinstance(body["tweaks"], dict):
        raise AgentError(400, "tweaks: must be an object")
    if named[0] in TWEAKS_FILE_OPS:
        cards = body[named[0]]
        if not isinstance(cards, list) or not cards:
            raise AgentError(400, "%s: must be a list of at least one card (%s)"
                             % (named[0], ", ".join(TWEAK_SECTIONS)))
        for card in cards:
            if not isinstance(card, str) or card not in TWEAK_SECTIONS:
                raise AgentError(400, "%s: %s is not a card (%s)" % (named[0], json.dumps(card)[:40],
                                                                    ", ".join(TWEAK_SECTIONS)))
        if len(set(cards)) != len(cards):
            raise AgentError(400, "%s: a card is named twice" % named[0])
        op = {named[0]: list(cards)}
    taken_key = body.get("takenKey", "")
    if not isinstance(taken_key, str):
        raise AgentError(400, "takenKey must be a string")
    cat = read_tweaks_catalog(version)
    if cat is None:
        raise _tweaks_no_catalogue(version)
    doc = None if op else normalise_tweaks(cat, body["tweaks"], tweaks_unknown_facts(cat), unread=True)
    return version, doc, taken_key, op


def tweaks_guard(version, cat, record, taken_key):
    """THE GUARD of a job that applies a document: the files taken over now -- stored, or that a take-over of
    this moment would store (tweaks_take_overs) -- must be the ones the page read (`taken_key`, its answer's
    takenKey; "" = none): a document built before a hand change must not be written over it. AgentError(409)
    otherwise -- nothing written. Returns the computation (what tweaks_store_take_overs stores while nothing was
    written since)."""
    result = tweaks_take_overs(version, cat, record)
    if result["key"] != (taken_key or ""):
        raise AgentError(409, "A data file was changed outside Relic since the page read the settings -- read them "
                              "again.")
    return result


# -- Revert and Reset: a card's files put back, at once, in two phases --
# A Revert ("back to the settings Relic had in effect before the changes made outside Relic") and a Reset ("the
# original game for these cards") act on WHOLE FILES of the cards they name -- the drop table belongs to the
# Domain card and to the Quest card: a file of one is put back for the other too, and the other card's settings
# follow on it again. PHASE 1, whether the game server runs or not: a copy of the bytes the hand changed (the
# file, or the agent's output on a base it adopted) in .relic-tweaks/hand/, the vendor's original into every file
# of the operation (a missing one comes back), then ONE record write: each entry set to the base its settings
# are built on from then on (Revert: the base before the first take-over -- `undo`; Reset: the original) with
# `released` = the hand's bytes, never taken over again; the keys a take-over took out of the documents back in
# `tweaks` (and, for a Reset, the cards' settings out of it); `active` without the settings of the files that are
# originals now. Every file of the operation is the vendor's original after it: the game server can boot and
# load. PHASE 2 is an Apply of what is left on those originals -- judged when the game server runs, the Start's
# last step when it does not; a refusal or a stop leaves the originals.

def tweaks_op_files(cat, record, states, kind, cards, foreign=()):
    """The files a Revert (kind "revert") or a Reset ("reset") of `cards` acts on -- whole files, sorted. Of every
    file of those cards (_tweaks_sections: their tables and monster-group scripts) a Revert takes the one whose
    entry holds an `undo` (a take-over since the agent's last accepted write of it), one `changed` outside Relic
    and not taken over, one that is `missing`, and one whose entry was built on another original than the
    catalogue's (`foreign`: their paths -- _tweaks_foreign_md5; put back as a Reset would); a Reset takes every
    one that is not the vendor's original as it stands (not `original`, an entry on an adopted base, a foreign
    one) and every one a setting of those cards writes (in `tweaks` or in `active`). states: {path: state}
    (tweaks_file's). Pure."""
    sections, rels = _tweaks_sections(cat), []
    for card in cards:
        tables, scripts = sections[card]
        rels += [rel for rel in tables + scripts if rel not in rels]
    written = set()
    if kind == "reset":
        paths = [path for path in set(tweaks_leaves(record["tweaks"])) | set(tweaks_leaves(record["active"]))
                 if path.split(".", 1)[0] in cards]
        written = set(rel for writes, _needs in tweaks_setting_files(cat, paths).values() for rel in writes)
    out = []
    for rel in rels:
        entry, state = record["files"].get(rel), states.get(rel)
        if kind == "revert":
            take = (entry is not None and "undo" in entry) or state in ("changed", "missing") or rel in foreign
        else:
            take = state != "original" or _tweaks_taken(entry) or rel in written or rel in foreign
        if take:
            out.append(rel)
    return sorted(out)


def _tweaks_originals_of(version, wanted, disks, memo=None):
    """{path: the vendor's original} of the files `wanted` names ({path: md5}) -- the file itself while it is that
    original (`disks`: {path: its bytes | None}), the base copy, else the member of the shipped archive, read in
    ONE pass for every file that needs it; a file whose original is nowhere is left out. memo[None] (when given)
    says why the archive could not be read."""
    found, rest = {}, {}
    for rel, md5 in sorted(wanted.items()):
        disk = disks.get(rel)
        if disk is not None and hashlib.md5(disk).hexdigest() == md5:
            found[rel] = disk
            continue
        data = _tweaks_read(tweaks_base_path(version, rel))
        if data is not None and hashlib.md5(data).hexdigest() == md5:
            found[rel] = data
            continue
        rest[rel] = md5
    if rest:
        got, why = tweaks_shipped_originals(version, rest)
        found.update(got)
        if why and memo is not None and None not in memo:
            memo[None] = why
    return found


def _tweaks_files_named(rels):
    """Paths as a job line names them: three at most, then how many more."""
    rels = list(rels)
    return ", ".join(rels[:3]) + (" and %d more" % (len(rels) - 3) if len(rels) > 3 else "")


def _tweaks_phase_one(version, job, cat, record, kind, cards, said=False):
    """PHASE 1 of a Revert (kind "revert") or a Reset ("reset") of `cards`, under _op_lock, after the take-overs
    were stored: (the record as written, the document of phase 2, in_effect, [the paths written]). said: the job
    already said that the shipped archive cannot be read (ONE warning a job).
    Refused before anything is written (409): a file of the operation whose vendor's original is not available
    -- not on disk, not in the base copy, not in the shipped archive --, one whose Revert needs an adopted base
    that is not there, documents that cannot be put back. Then:
    1. every file the originals go into proven replaceable (_probe_tweaks_plan: a file held open, a read-only one
       -- a 500, nothing written, no copy replaced);
    2. a copy of every file of the operation whose bytes are not the agent's plain output on the vendor's
       original -- changed by hand, or the agent's output on an adopted base -- into .relic-tweaks/hand/<path>
       (ONE copy, durable), named in a job line;
    3. the vendor's original into every file of the operation that does not hold it (a missing one comes back);
    4. ONE record write. Per file the entry is set to {base: the base the settings are built on from then on --
       Revert: `undo.base` (the vendor's original or an earlier adopted base, read from adopted/<path>.undo),
       or the entry's base for a file without `undo`; Reset and a file built on another original than the
       catalogue's: the vendor's original --, out: the original, ok: true, kept: the rows kept on that base,
       taken on an adopted base, released: the md5s of what it lets go -- the bytes the file held and, of a
       base adopted from a change made outside Relic that it lets go too, that change as found and that base --
       added to the ones the entry named} -- dropped when it says nothing more than "the original". `tweaks`:
       every key the take-overs of those files took out back at its value (`undo` keys, whichever card they
       belong to) while the document holds what the take-over left there -- nothing, or the base's value; one
       set since stays as set (ONE job line) --, then for a Reset the cards' settings out of it; canonical
       against the new bases. `active`: without every setting that writes a file of the operation
       (tweaks_prune_active) -- while a refusal of `tweaks` stands, the settings in effect with the `undo` keys
       back instead (a Reset: without the cards' settings): the document a Start brings back. A refusal that
       stands follows the new `tweaks` (its digest).
    The document of phase 2: `tweaks` -- `active` while a refusal stands (in_effect). A failure to write puts
    the previous bytes back (507); nothing is on record then."""
    names = _tweaks_and(TWEAKS_CARD_NAMES[c] for c in cards) + (" card" if len(cards) == 1 else " cards")
    sections, rels, memo = _tweaks_sections(cat), [], {}
    for card in cards:
        tables, scripts = sections[card]
        rels += [rel for rel in tables + scripts if rel not in rels]
    looked = dict((rel, tweaks_file(version, cat, record, rel, memo)) for rel in rels)
    foreign = set(rel for rel, (_s, disk, _b) in looked.items() if _tweaks_foreign_md5(
        cat, record, rel, None if disk is None else hashlib.md5(disk).hexdigest()))
    op = tweaks_op_files(cat, record, dict((rel, s) for rel, (s, _d, _b) in looked.items()), kind, cards, foreign)
    standing = record["refused"] is not None and record["refused"].get("digest") == tweaks_digest(record["tweaks"])
    if not op:
        job.log("Gameplay settings: no file of the %s needs to be put back." % names)
        return record, (record["active"] if standing else record["tweaks"]), standing, []
    vmd5 = dict((rel, cat["files"][rel].lower()) for rel in op)
    vendor = _tweaks_originals_of(version, vmd5, dict((rel, looked[rel][1]) for rel in op), memo)
    if memo.get(None) and not said:
        job.log("WARNING: Gameplay settings: %s -- the originals it holds are not available." % memo[None])
    lost = [rel for rel in op if rel not in vendor]
    if lost:
        raise AgentError(409, "Gameplay settings: the original of %s is not available -- not on the server, not in the "
                              "originals this agent ships -- so nothing was put back." % _tweaks_files_named(lost))
    targets, gone = {}, []
    for rel in op:
        entry = record["files"].get(rel)
        if kind == "reset" or entry is None or rel in foreign:
            targets[rel] = (vmd5[rel], vendor[rel], [], None)
            continue
        md5, kept = ((entry["undo"]["base"].lower(), list(entry["undo"]["kept"])) if "undo" in entry
                     else (entry["base"].lower(), list(entry.get("kept") or [])))
        if md5 == vmd5[rel]:
            targets[rel] = (md5, vendor[rel], kept, None)
            continue
        data = _tweaks_adopted_read(version, rel, md5)
        if data is None:
            gone.append(rel)
            continue
        taken = dict(entry["taken"]) if _tweaks_taken(entry) else {"at": int(time.time()), "hand": md5,
                                                                   "vendor": vmd5[rel]}
        targets[rel] = (md5, data, kept, taken)
    if gone:
        raise AgentError(409, "Gameplay settings: the base Relic built %s on before the change made outside Relic is "
                              "not there any more -- put back the original files instead; nothing was put back."
                         % _tweaks_files_named(gone))
    # the documents, checked against the bases they are built on from then on -- before anything is written. A key
    # a take-over took out goes back only while the document holds what that take-over left there: nothing, or the
    # value of the base (a domain's own cost under the cost for all domains) -- one set again since is the admin's
    # later choice and stays
    wanted, held = tweaks_leaves(record["tweaks"]), tweaks_leaves(record["active"])
    now_facts, later = tweaks_record_facts(version, cat, record, memo), set()
    for rel in op:
        for path, values in ((record["files"].get(rel) or {}).get("undo") or {}).get("keys", {}).items():
            left_there = _tweaks_base_value(now_facts, path)
            for leaves, value, mine in ((wanted, values.get("tweaks"), True), (held, values.get("active"), False)):
                if leaves.get(path) == value:
                    continue
                if leaves.get(path) is not None and leaves[path] != left_there:
                    if mine:
                        later.add(path)
                    continue
                if value is None:
                    leaves.pop(path, None)
                else:
                    leaves[path] = value
    if kind == "reset":
        wanted = dict((path, value) for path, value in wanted.items() if path.split(".", 1)[0] not in cards)
        held = dict((path, value) for path, value in held.items() if path.split(".", 1)[0] not in cards)
        later = set(path for path in later if path.split(".", 1)[0] not in cards)
    bases = tweaks_record_bases(version, cat, record, memo)
    for rel in op:
        if targets[rel][0] == vmd5[rel]:
            bases.pop(rel, None)
        else:
            bases[rel] = targets[rel][1]
    facts = tweaks_facts(cat, bases)
    try:
        tweaks_new = normalise_tweaks(cat, tweaks_from_leaves(wanted), facts)
        active_new = normalise_tweaks(cat, tweaks_from_leaves(held), facts) if standing \
            else tweaks_prune_active(cat, record["active"], op)
    except AgentError as e:
        raise AgentError(409, "Gameplay settings: the settings of the %s cannot be put back (%s) -- nothing was put "
                              "back." % (names, e.message))
    # 1. every file the originals go into proven replaceable -- nothing written yet, the copies kept before either
    items = [(rel, vendor[rel]) for rel in op if looked[rel][1] != vendor[rel]]
    there = [(rel, data, "restore") for rel, data in items if looked[rel][1] is not None]
    _probe_tweaks_plan(version, there)
    previous = [(rel, looked[rel][1]) for rel, _data, _kind in there][::-1]
    # 2. the hand's bytes, kept
    hands = {}
    for rel in op:
        state, disk, _base = looked[rel]
        if disk is not None and disk != vendor[rel] and (
                state == "changed" or (state == "ours" and _tweaks_taken(record["files"].get(rel)))):
            hands[rel] = disk
    for rel, data in sorted(hands.items()):
        try:
            _write_tweaks_own(version, tweaks_hand_path(version, rel), data)
        except OSError as e:
            raise AgentError(507, "Gameplay settings: a copy of %s could not be kept (%s) -- nothing was put back."
                             % (rel, e))
    if hands:
        job.log("Gameplay settings: what %s held is kept in %s."
                % (_tweaks_files_named(sorted(hands)), os.path.join(stack_dir(version), TWEAKS_DIR, "hand")))
    if later:
        paths = sorted(later)
        job.log("Gameplay settings: %s %s set after the change made outside Relic -- kept as set."
                % (_tweaks_and(paths), "was" if len(paths) == 1 else "were"))
    # 3. the originals into the files
    try:
        for rel, _data in items:
            if looked[rel][1] is None:
                os.makedirs(os.path.dirname(tweaks_path(version, rel)), exist_ok=True)
        _write_tweak_files(version, items)
    except OSError as e:
        stuck = _put_back_tweak_files(version, previous)
        raise AgentError(507, "Gameplay settings: the original files could not be written (%s) -- %s." % (
            e, "the previous files are back in place" if not stuck else "the previous files could NOT all be put back "
            "(%s)" % _tweaks_stuck_text(stuck)))
    # 4. ONE record write
    files = dict(record["files"])
    for rel in op:
        md5, _data, kept, taken = targets[rel]
        old = record["files"].get(rel) or {}
        # (released: every md5 that stands for the change outside Relic this lets go -- the bytes the file held, and
        #  of a base adopted from such a change that is let go too, the change as it was found and that base -- so
        #  that none of them is taken over again; never the base the settings follow on, nor the original)
        let_go = [hashlib.md5(hands[rel]).hexdigest()] if rel in hands else []
        if _tweaks_taken(old) and old["base"].lower() != md5:
            let_go += [old["taken"]["hand"].lower(), old["base"].lower()]
        released = [m for m in _tweaks_released(old) + let_go if m not in (md5, vmd5[rel])]
        released = [m for n, m in enumerate(released) if m not in released[:n]][-TWEAKS_RELEASED_MAX:]
        entry = {"base": md5, "out": vmd5[rel], "ok": True}
        if kept:
            entry["kept"] = sorted(set(kept), key=lambda r: (len(r), r))
        if taken:
            entry["taken"] = taken
        if released:
            entry["released"] = released
        if md5 == vmd5[rel] and not kept and not released:
            files.pop(rel, None)
        else:
            files[rel] = entry
    refused = record["refused"]
    if standing:
        refused = dict(refused, digest=tweaks_digest(tweaks_new))
    after = _tweaks_unread(dict(record, files=files, tweaks=tweaks_new, active=active_new, refused=refused),
                           bool(record.get("unread")) or (bool(items) and tweaks_stack_timer(version) is not True))
    try:
        after = write_tweaks_record(version, after)
    except AgentError:
        _put_back_tweak_files(version, previous)
        raise
    job.log("Gameplay settings: %s of the %s -- %s." % (
        "Revert" if kind == "revert" else "Reset", names,
        "1 file is the original again" if len(op) == 1 else "%d files are the originals again" % len(op)))
    return after, (active_new if standing else tweaks_new), standing, [rel for rel, _data in items]


def _tweaks_leftovers(version, job, record):
    """The leftover rule with its ONE job line (tweaks_restore_originals) -> (the record as written, the paths
    put back). Where the game server's log shows no timer (or cannot be read), the originals it puts back
    reach a running service only when it is asked: the record then says `unread`. The class is the build's,
    so a game server that is down -- its log renamed when it exited -- is judged by its latest dated log
    (tweaks_stack_timer). A log read, no docker call -- the hooks in front of every boot stay docker-free. A file
    taken over (tweaks_take_over) gets the bytes it held before the change that was cut off, not an original:
    the line says how many."""
    record, back, left = tweaks_restore_originals(version, record, unread=tweaks_stack_timer(version) is not True,
                                                  job=job)
    before = [rel for rel in back if _tweaks_taken(record["files"].get(rel))]
    job.log("Gameplay settings: an earlier change was never confirmed by the game server -- %d files are the "
            "originals again%s%s." % (len(back) - len(before),
                                      ", %d hold what they held before it" % len(before) if before else "",
                                      " (%d changed outside Relic: left alone)" % len(left) if left else ""))
    return record, back


def _tweaks_read_now(version, job):
    """An up game server that does not reload by itself is asked to read the data files as they are now and
    awaited (tweaks_reload_verdict), then the other services that run in turn (tweaks_follow). Not asked once
    the job was asked to stop, while another service is still in a load it was asked for, nor while the game
    server ITSELF is in a load (_tweaks_quiet with `also`: a signal an earlier job sent and did not wait for --
    the put-back after a refusal -- leaves a load under way), nor when what is left of the job's time would not
    cover the wait for its verdict. The files it is asked to read were not known to be accepted before (they may
    be the originals put back right after a refusal), so its verdict is that of a load that BEGAN after the
    offset (tweaks_reload_verdict `own`): the failure of an earlier load -- and the second line the server
    writes for one seconds after the first -- is not this load's. True when all of them read the files; anything
    else is a WARNING and False. Never raises."""
    if _tweaks_stop_asked(job):
        job.log("WARNING: the game server was not asked to read its data files: stopped on request -- the next Apply "
                "asks it.")
        return False
    why = _tweaks_quiet(version, job, None, "the game server is asked to read its data files",
                        also=TWEAKS_GAME_SERVICE)
    if why is not None:
        job.log("WARNING: the game server was not asked to read its data files (%s) -- the next Apply asks it." % why)
        return False
    facts = tweaks_service_facts(version, TWEAKS_GAME_SERVICE)
    if _tweaks_deadline(job) - time.time() < tweaks_wait_limit(facts["cost"] if facts else 0):
        job.log("WARNING: the game server was not asked to read its data files: the job's time is up -- the next "
                "Apply asks it.")
        return False
    try:
        reason = tweaks_reload_verdict(version, job, own=True)
    except Exception as e:  # noqa: BLE001 -- what cannot be read is not done
        reason = "its verdict could not be read (%s)" % _failure_text(e)
    if reason is not None:
        job.log("WARNING: the game server did not take the data files as they are now (%s) -- the next Apply asks it "
                "again." % reason)
        return False
    return not tweaks_follow(version, job)


def _tweaks_reread(version, job, record):
    """A record that says `unread`: the data files changed after a running service that does not reload by
    itself last read them. Every such service that runs is asked to read them, the game server first
    (_tweaks_read_now), once nothing boots. Dropped without a signal where the services reload by themselves
    (tweaks_stack_timer) or none of them runs (tweaks_none_run); a game server that does not run while another
    one does keeps it -- the game server judges first, so the others are asked once it runs again. Returns the
    record as it is now; never raises (a WARNING or a line says why the mark stays)."""
    try:
        facts = tweaks_service_facts(version, TWEAKS_GAME_SERVICE)
        if (tweaks_reload_timer(facts) if facts is not None else _tweaks_dated_timer(version)) is True:
            return _tweaks_mark_read(version, record, job)
        runs = tweaks_game_runs(version)
        if runs is False:
            if tweaks_none_run(version) is True:
                return _tweaks_mark_read(version, record, job)
            job.log("Gameplay settings: the game server does not run, and another service that reads the data files "
                    "may -- it is asked to read them once the game server runs again (the next Apply, or a Start).")
            return record
        if facts is None:
            job.log("WARNING: the game server's log cannot be read -- it was not asked to read its data files; the "
                    "next Apply asks again.")
            return record
        if runs is None:
            job.log("Gameplay settings: docker did not say whether the game server runs -- the next Apply asks a "
                    "running one to read its data files.")
            return record
        if _tweaks_stop_asked(job):
            job.log("WARNING: the game server was not asked to read its data files: stopped on request -- the next "
                    "Apply asks it.")
            return record
        try:
            facts = tweaks_wait_booted(version, job)
        except AgentError as e:
            job.log("WARNING: the game server was not asked to read its data files (%s) -- the next Apply asks again."
                    % e.message)
            return record
        if tweaks_reload_timer(facts):
            return _tweaks_mark_read(version, record, job)
        job.log("Gameplay settings: the data files changed while the game server ran -- it is asked to read them.")
        return _tweaks_mark_read(version, record, job) if _tweaks_read_now(version, job) else record
    except Exception as e:  # noqa: BLE001 -- the mark stays: the next Apply asks again
        job.log("WARNING: the services were not asked to read the data files (%s) -- the next Apply asks again."
                % _failure_text(e))
        return record


def _tweaks_put_originals(version, job, cat, record, doc, changes, runs, in_effect=False, effective=None):
    """A plan that only puts originals back. Originals need no judge, so it is carried out whether the game
    server runs or not (`runs`: True / False / None as tweaks_game_runs answers): the probe, the files, the
    record -- `doc` in effect and nothing refused or, with in_effect (`doc` is the document in effect, the
    stored one stands refused), `tweaks` and `refused` as they are. A game server that reloads by itself, is
    still starting or whose log cannot be read gets one signal, not waited for; one that does not reload by
    itself and is up is awaited and followed (_tweaks_read_now), `unread` on record until all of them read
    the files -- and so it stays where nothing was asked (docker did not say whether it runs, a signal that
    never arrived, a game server still starting, and a game server that does not run while another service
    that reads the files does or may: tweaks_none_run). Returns (outcome, why, timer): "down" | "unknown"
    (docker did not say) | "asked" | "unasked" (why: what docker answered, or why the services could not be
    asked) | "read" | "partly" (not every service read them), and whether the game server's log -- its latest
    dated one while it is down (tweaks_stack_timer) -- shows a timer. effective: the EFFECTIVE document
    (tweaks_plan's info) -- what `active` becomes. `changes` may be empty: originals a Revert or a Reset already
    put back are read the same way."""
    _probe_tweaks_plan(version, changes)
    after = _apply_tweaks_plan(version, cat, record, None if in_effect else doc, changes)
    facts = tweaks_service_facts(version, TWEAKS_GAME_SERVICE)
    timer = (tweaks_reload_timer(facts) if facts is not None else _tweaks_dated_timer(version)) is True

    def confirm(unread):
        if in_effect:
            return write_tweaks_record(version, _tweaks_unread(dict(after, files=_tweaks_held_files(version, cat, after)),
                                                               unread))
        return tweaks_mark_confirmed(version, cat, _tweaks_unread(after, unread), effective)

    if runs is not True:
        confirm(not timer and (runs is None or tweaks_none_run(version) is not True))
        return ("down" if runs is False else "unknown"), None, timer
    if timer or facts is None or facts["booting"]:
        confirm(not timer)
        why = _tweaks_quiet(version, job, TWEAKS_GAME_SERVICE, "the game server is asked to read them")
        if why is None:
            why = tweaks_signal(version)  # one signal, not waited for: the record first, as before
        return ("asked" if why is None else "unasked"), why, timer
    done = confirm(True)
    if _tweaks_read_now(version, job):
        _tweaks_mark_read(version, done, job)
        return "read", None, False
    return "partly", None, False


def _tweaks_apply_live(version, job, cat, record, doc, changes, in_effect=False, effective=None):
    """A plan carried out on a RUNNING game server -- the one place a data file that is not an original is
    written:
    0. no other service is in a load it was asked for (_tweaks_quiet), THEN no data-loading service boots and
       the game server does not refuse the files it has (tweaks_wait_booted with judge=True: its last look is
       the last one before the write -- a service that starts over while another one's load is waited out is
       waited for in turn), and the job has time left for the verdict's wait -- else nothing is touched;
    1. the probe, then the base copies, the record (every file about to be written `ok: false`) and the
       files, back to back;
    2. the offset of the game server's log, ONE signal and the wait for its verdict (tweaks_reload_verdict);
    3. accepted: the record says so -- and where the game server does not reload by itself the other services
       are asked in turn (tweaks_follow), `unread` on record until all of them read the files. Refused, or no
       verdict: the previous bytes back at once (last file first), the record's `files` as they were plus
       `refused`. A game server that reloads by itself is not signalled again (it never left the config before,
       and reads the files that were put back at its own next load); one that does not is asked ONCE, not
       waited for (it may have taken the new files late -- after a stop on request too: the load under way may
       read them), except after the game server stopped, after a signal that never arrived (docker delivered
       none of three tries) and after a restart -- then `unread` goes on record instead: the boot of the
       process that started over may have read the new files.
    in_effect: `doc` is the document in effect (`active`), handed to the server AGAIN because the files do
    not hold it while the stored one stands refused. `tweaks` and `refused` stay as they are: accepted, only
    `files` changes; refused, `active` loses every setting that writes a file that was written
    (tweaks_prune_active) -- the files written hold what they held before, which is not it.
    effective: the EFFECTIVE document (tweaks_plan's info) -- what `active` becomes once the server accepts.
    Returns None when the server accepted the files, else the reason of the refusal. Raises AgentError for
    what stops it before a file is written and for previous bytes that could not all be put back (507): the
    refusal is on record then too, with every written file kept as unconfirmed -- the leftover rule puts
    the originals back before a game service boots, and no Start hands the server that document again."""
    why = _tweaks_quiet(version, job, TWEAKS_GAME_SERVICE, "the game data is changed")
    if why == _TWEAKS_QUIET_STOP:
        raise AgentError(409, "Stopped on request -- no new settings were written.")
    if why is not None:
        raise AgentError(409, "%s, so no new settings were written -- try again later." % why)
    # (the boots last: a service that starts over while another one's load is waited out must not boot over files
    #  the server has not accepted -- the judge wait's look is the last one before the write; the only signal it
    #  may send is the game server's own, after a quiet wait of its own)
    facts = tweaks_wait_booted(version, job, judge=True)
    timer = tweaks_reload_timer(facts)
    need, until = tweaks_wait_limit(facts["cost"]), _tweaks_deadline(job)
    if until - time.time() < need:
        raise AgentError(409, "The services took %d minutes to be ready, and the game server's verdict can take up "
                              "to %d more -- longer than the %d minutes one job may wait, so no new settings were "
                              "written. Apply them again." % (int(time.time() - (until - T_TWEAKS_JOB)) // 60,
                                                              need // 60, T_TWEAKS_JOB // 60))
    restores = sum(1 for _rel, _new, kind in changes if kind == "restore")
    job.log("Writing %d files of the game data%s..."
            % (len(changes), " (%d back to the original)" % restores if restores else ""))
    files_before = record["files"]
    previous = _probe_tweaks_plan(version, changes)
    after = _apply_tweaks_plan(version, cat, record, None if in_effect else doc, changes)
    try:
        reason = tweaks_reload_verdict(version, job)
    except Exception as e:  # noqa: BLE001 -- without a verdict the files must not stay, whatever went wrong
        reason = "the game server's verdict could not be read (%s)" % _failure_text(e)
    if reason is None:
        # (`unread` is on record from the confirmation until the follow ends well: a job that dies in the follow
        #  leaves a record that says so)
        if in_effect:
            done = write_tweaks_record(version, _tweaks_unread(
                dict(after, files=_tweaks_held_files(version, cat, after)), not timer))
        else:
            done = tweaks_mark_confirmed(version, cat, _tweaks_unread(after, not timer), effective)
        if not timer and not tweaks_follow(version, job):
            _tweaks_mark_read(version, done, job)
        return None
    stuck = None
    try:
        _undo_tweaks_plan(version, previous)
    except AgentError as e:
        stuck = e
    unread = not timer and bool(record.get("unread"))
    if not timer and reason == _TWEAKS_RESTARTED:
        unread = True  # (the boot of the process that started over may have read the new files)
    elif stuck is None and not timer and reason != _TWEAKS_STOPPED and not reason.startswith(_TWEAKS_UNASKED):
        why = _tweaks_quiet(version, job, TWEAKS_GAME_SERVICE, "the game server is asked to read the previous files")
        if why is None:
            why = _tweaks_ask(version, TWEAKS_GAME_SERVICE, TWEAKS_SIGNAL_TRIES)
        if why is None:
            job.log("The game server was asked to read the previous files again.")
        else:
            job.log("WARNING: the game server could not be asked to read the previous files again (%s) -- the next "
                    "Apply asks it." % why)
            unread = True
    # The refusal goes on record either way: with `files` as they were once the previous bytes are back,
    # with every written file still unconfirmed while they are not.
    files = files_before if stuck is None else after["files"]
    try:
        if in_effect:
            write_tweaks_record(version, _tweaks_unread(dict(after, files=files, active=tweaks_prune_active(
                cat, after["active"], set(rel for rel, _new, _kind in changes))), unread))
        else:
            tweaks_mark_refused(version, _tweaks_unread(after, unread), files, reason)
    except AgentError:
        if stuck is None:
            raise
    if stuck is not None:
        raise AgentError(507, "The server refused the %s: %s. %s"
                         % ("settings it had accepted before" if in_effect else "new settings", reason.rstrip("."),
                            stuck.message))
    return reason


def do_tweaks(version, job, doc, taken_key="", revert=None, reset=None):
    """POST /server/tweaks {version, tweaks | revert | reset, takenKey}: make the stack's data files hold `tweaks`
    (the whole document; {} = no setting: every file back on its base) -- or, for a Revert (`revert`: the cards)
    or a Reset (`reset`), put the files of those cards back first and apply what is left on them.
    1. The catalogue (409 without one), the stack (the 404 of a version that is not there), the document against
       the catalogue, the record (500 naming a record that cannot be read), THE GUARD (tweaks_guard: the files
       taken over must be the ones the page read -- `taken_key` -- else 409 and nothing is stored or written),
       the data layout (the guard asked again when files were hoisted).
    2. Leftovers first: a record that names a file no server confirmed gets every original back (the guard is
       asked again when it ran: what it put back may be what a take-over finds now). Then every hand-changed
       file that can be is taken over and stored (tweaks_store_take_overs), and the document is normalised
       against the stack's bases.
    3. A Revert / a Reset: its PHASE 1 (_tweaks_phase_one) -- the vendor's originals into the files of its cards
       at once, whether the game server runs or not, the hand's bytes kept, ONE record write; the document of
       phase 2 is `tweaks` as it left it (`active` while a refusal of `tweaks` stands: in_effect).
    4. The plan, ONE SETTING AT A TIME (tweaks_plan): the settings that rest on a file that cannot carry them
       are blocked -- ONE job line names their cards and the files why (tweaks_blocked_line), the result lists
       them (`blocked`) -- and the rest is applied: the files are brought in line with the EFFECTIVE document.
       Nothing to write: the document is stored -- the effective one as the one in effect -> effect "none" (a
       record that says `unread` asks the services that run to read the files as they are: _tweaks_reread).
    5. A plan that only puts originals back needs no judge -- nor do the originals phase 1 put back: carried out
       -> "next-start" on a stack whose game server does not run (or docker cannot tell), "live" on one that runs
       -- it is asked to read them (_tweaks_put_originals: a game server that reloads by itself, or one still
       starting: one signal, not waited for; one that does not and is up: awaited, then the other services in
       turn).
    6. Any other plan: the game server does not run (or docker cannot tell) -> only stored, and the Start
       applies it (tweaks_after_start) -> "next-start"; it runs -> _tweaks_apply_live -> "live", or the 409
       of a refusal (the previous files are back -- after a phase 1 the originals --, the document stays stored
       as refused).
    Returns {version, changed, effect, clamped, blocked}. The job lines say which of the three docker answered:
    the game server runs, it does not, or docker did not say. No game service is started, stopped or restarted,
    and the agent's state file is not involved."""
    cat = read_tweaks_catalog(version)
    if cat is None:
        raise _tweaks_no_catalogue(version)
    if not is_present(version):
        raise AgentError(404, "Version %s does not exist on this server (%s is missing)."
                         % (version, stack_dir(version)))
    kind, cards = ("revert", revert) if revert else ("reset", reset) if reset else (None, None)
    if kind is None:
        doc = normalise_tweaks(cat, doc, tweaks_unknown_facts(cat), unread=True)
    record = read_tweaks_record(version)
    overs = tweaks_guard(version, cat, record, taken_key)
    if ensure_data_layout(version, job):
        overs = tweaks_guard(version, cat, record, taken_key)  # (files were hoisted: asked again)
    touched = set()
    if tweaks_unconfirmed(record):
        record, back = _tweaks_leftovers(version, job, record)
        touched.update(back)
        overs = tweaks_guard(version, cat, record, taken_key)
    record, overs = tweaks_store_take_overs(version, cat, record, job, overs)
    reasons = dict((rel, why["reason"]) for rel, why in overs["refused"].items())
    in_effect, first = False, []
    if kind is not None:
        record, doc, in_effect, first = _tweaks_phase_one(version, job, cat, record, kind, cards,
                                                          bool(overs.get("archive")))
        touched.update(first)
    on_record = os.path.isfile(tweaks_record_path(version))
    info = {}
    changes, clamped = tweaks_plan(version, cat, record, doc, reasons, info)
    doc, effective = info["doc"], info["effective"]
    if clamped:
        job.log("%d reward amounts are limited to the largest value the server accepts." % clamped)
    line = tweaks_blocked_line(cat, info)
    if line:
        job.log(line)
    result = {"version": version, "changed": 0, "effect": "none", "clamped": clamped, "blocked": info["blocked"]}
    if not changes and not first:
        # (the original game asked of a stack that never had settings leaves no record)
        if not in_effect and (on_record or doc):
            record = tweaks_mark_confirmed(version, cat, dict(record, tweaks=doc), effective)
        job.log("The server's files already hold %s -- nothing to write."
                % ("every setting that can be applied" if info["blocked"] else "these settings"))
        if record.get("unread"):
            _tweaks_reread(version, job, record)
        return dict(result, changed=len(touched))
    restores = sum(1 for _rel, _new, kind_ in changes if kind_ == "restore")
    runs = tweaks_game_runs(version)  # True | False | None: docker did not say
    if restores == len(changes):
        outcome, why, timer = _tweaks_put_originals(version, job, cat, record, doc, changes, runs, in_effect,
                                                    effective)
        touched.update(rel for rel, _new, _kind in changes)
        n = len(set(rel for rel, _new, _kind in changes) | set(first))
        if outcome == "down":
            job.log("The game server is not running -- %d files are the originals again." % n)
        elif outcome == "unknown" and timer:
            job.log("%d files are the originals again -- docker did not say whether the game server runs; one "
                    "that does reads them by itself within minutes." % n)
        elif outcome == "unknown":
            job.log("%d files are the originals again -- docker did not say whether the game server runs; the next "
                    "Apply asks a running one to read them." % n)
        elif outcome == "asked":
            job.log("%d files are the originals again -- the game server was asked to read them." % n)
        elif outcome == "unasked" and timer:
            job.log("%d files are the originals again -- the game server could not be asked to read them (%s): "
                    "it reads them by itself within minutes." % (n, why))
        elif outcome == "unasked":
            job.log("%d files are the originals again -- the game server could not be asked to read them (%s): the "
                    "next Apply asks again." % (n, why))
        elif outcome == "read":
            job.log("%d files are the originals again -- the game server read them." % n)
        else:
            job.log("%d files are the originals again -- not every service read them yet: the next Apply asks "
                    "again." % n)
        return dict(result, changed=len(touched), effect="live" if runs else "next-start")
    if not runs:
        # (an `unread` mark is dropped where no service that loads the data files runs -- every one of them reads
        #  the files when it starts --, never while one does: the game server judges first, the others follow)
        drop = runs is False and record.get("unread") and tweaks_none_run(version) is True
        if in_effect:
            if drop:
                _tweaks_mark_read(version, record, job)
            job.log("%s -- the settings that were in effect are put back by the next Start (%d files)."
                    % ("docker did not say whether the game server runs" if runs is None
                       else "The game server is not running", len(changes)))
        else:
            tweaks_mark_wanted(version, _tweaks_unread(record, False) if drop else record, doc)
            if runs is None:
                job.log("docker did not say whether the game server runs -- the settings are stored and not written "
                        "yet (%d files); apply them again once docker answers, or the next Start applies them."
                        % len(changes))
            else:
                job.log("The game server is not running -- the settings are stored; the next Start applies them "
                        "(%d files)." % len(changes))
        return dict(result, changed=len(touched), effect="next-start")
    reason = _tweaks_apply_live(version, job, cat, record, doc, changes, in_effect, effective)
    if reason == _TWEAKS_STOP_ASKED:
        raise AgentError(409, "Stopped on request before the game server's verdict -- %s."
                         % ("the original files stay in place" if first else "the previous settings are back in place"))
    if reason is not None:
        if first:
            raise AgentError(409, "The server refused the settings that follow the original files: %s. The original "
                                  "files stay in place." % reason.rstrip("."))
        raise AgentError(409, "The server refused the new settings: %s. The previous settings are back in place."
                         % reason.rstrip("."))
    touched.update(rel for rel, _new, _kind in changes)
    return dict(result, changed=len(touched), effect="live")


def tweaks_before_boot(version, job):
    """In front of every docker call of the agent that boots or restarts a service that loads the data files
    -- a Start, a provision, the vendor bootstrap, the watchdogs' revive and towerfix, events, txt fixes, the
    restarts of netfix, of the advertise follow and of the hotpatch, a secrets rotation, the pathfinding
    enable -- and once when the agent starts (tweaks_at_agent_start): a data file written without a verdict
    of the server (an apply that was cut off: the agent stopped, the box lost power; a refusal whose files
    could not all be put back) goes back to what no verdict is missing for (its original, or the bytes a file
    taken over held before) -- the leftover rule, nothing else --, so no service boots from a file the server's
    loader has not accepted. On a running stack too: originals may be written at any time; a service that does
    not reload by itself reads them only when asked, so the record then carries `unread`, which the next tweaks
    job -- or a Start that did not boot every service -- clears by asking it. The settings stay stored;
    tweaks_after_start hands them to the running server at the next Start. Never raises: gameplay settings must
    not block what the caller is about to do. A stack without a record gets nothing at all -- no job line, no
    file, no docker call; one whose record cannot be read gets ONE warning."""
    try:
        if not os.path.isfile(tweaks_record_path(version)):
            return
        record = read_tweaks_record(version)
        if tweaks_unconfirmed(record):
            _tweaks_leftovers(version, job, record)
    except AgentError as e:
        job.log("WARNING: %s Going on with the data files as they are." % e.message)
    except Exception as e:  # noqa: BLE001 -- gameplay settings must never block a server start
        job.log("WARNING: gameplay settings could not be checked (%s) -- going on with the data files as they are."
                % e)


class _AgentLog:
    """What a hook that reports through a job writes to when the agent runs it by itself, outside any job:
    the agent's own log, each line naming the version it is about."""

    def __init__(self, version):
        self.version = version

    def log(self, msg):
        log_line("gio-agent: version %s: %s" % (self.version, str(msg).rstrip()))


def tweaks_at_agent_start():
    """When the agent starts, before its watchdogs and its HTTP server: the leftover rule (tweaks_before_boot)
    for every version that has a folder. No apply can be under way at this moment, so a record that names an
    unconfirmed file is what an agent that stopped in the middle of one left behind -- the originals go
    back at once, whatever boots a game service next. Said in the agent's own log; never raises; nothing at
    all for a stack without a record."""
    for version in configured_versions():
        tweaks_before_boot(version, _AgentLog(version))


def tweaks_after_start(version, job, booted=False):
    """The last step of a Start and of a provision, once the stack is verified and on record as running: the
    stored gameplay settings are brought into effect when the files do not hold them -- a document saved
    while the stack was down, files a re-extracted archive returned to the originals, a change
    tweaks_before_boot took back. The steps are the job's (leftovers, the plan, the live apply with the game
    server's verdict), with two differences. A document the server already refused is not handed to it
    again (ONE line): in its place the files are brought back in line with the last document the server
    ACCEPTED (`active`) -- through the same branches, `tweaks` and `refused` left as they are --, so a
    re-extracted archive does not silently end settings that were in effect. The settings are applied one at a
    time (tweaks_plan): those that rest on a file that cannot carry them are named in ONE line -- their cards
    and the files why -- and the rest is applied. And nothing here fails the
    job: a refusal is a WARNING plus the record of it, the start itself succeeded. booted: the Start /
    provision booted every data-loading service after the leftover rule ran, so none holds a config older
    than the files (`unread` dropped without a signal -- before this hook's own leftover rule, which may put
    files back again); a Start that did not asks the services that run to read them where the record says
    `unread`. Never raises. Silent -- no job line, no file, no docker call -- on a stack without a record,
    and without a line whenever the files already hold what they should (a record that cannot be read:
    tweaks_before_boot gave this job its warning)."""
    failed = "the stored gameplay settings were not applied"
    try:
        if not os.path.isfile(tweaks_record_path(version)):
            return
        try:
            record = read_tweaks_record(version)
        except AgentError:
            return
        stored, refused = record["tweaks"], record["refused"]
        cat = read_tweaks_catalog(version)
        if cat is None:
            if stored or record["files"]:
                job.log("WARNING: gameplay settings are stored for version %s, but the agent ships no catalogue for "
                        "it -- they are not applied." % version)
            return
        held = refused is not None and refused.get("digest") == tweaks_digest(stored)
        if held:
            failed = "the gameplay settings that were in effect were not put back"
            job.log("Gameplay settings: the stored settings are not handed to the game server again -- change them "
                    "in the Gameplay settings (Server -> Game rules). It refused them: %s" % refused["error"])
        if booted:
            record = _tweaks_mark_read(version, record, job)
        if tweaks_unconfirmed(record):
            record, _back = _tweaks_leftovers(version, job, record)
        # (a file changed by hand is taken over before the plan -- a refusal that stood stays standing: its
        #  digest follows the document the take-over left)
        record, overs = tweaks_store_take_overs(version, cat, record, job)
        doc = record["active"] if held else record["tweaks"]
        info = {}
        changes, _clamped = tweaks_plan(version, cat, record, doc,
                                        dict((rel, why["reason"]) for rel, why in overs["refused"].items()), info)
        effective = info["effective"]
        line = tweaks_blocked_line(cat, info)
        if line:
            job.log(line)  # (the settings that rest on a file that cannot carry them -- the rest is applied)
        if not changes:
            if record.get("unread"):
                record = _tweaks_reread(version, job, record)
            if not held and record["active"] != effective:
                tweaks_mark_confirmed(version, cat, record, effective)
            return
        runs = tweaks_game_runs(version)
        if all(kind == "restore" for _rel, _new, kind in changes):
            _tweaks_put_originals(version, job, cat, record, doc, changes, runs, in_effect=held, effective=effective)
            job.log("Gameplay settings: %d files are the originals again." % len(changes))
            return
        which = "the last settings it accepted" if held else "the stored settings"
        if not runs:
            if runs is False and record.get("unread") and tweaks_none_run(version) is True:
                _tweaks_mark_read(version, record, job)
            job.log("Gameplay settings: %s -- %s stay pending (%d files)."
                    % ("docker did not say whether the game server runs" if runs is None
                       else "the game server does not run", which, len(changes)))
            return
        job.log("Gameplay settings: handing %s to the game server%s (%d files)..."
                % (which, " again" if held else "", len(changes)))
        reason = _tweaks_apply_live(version, job, cat, record, doc, changes, in_effect=held, effective=effective)
        if reason == _TWEAKS_STOP_ASKED:
            job.log("WARNING: the wait for the game server's verdict was stopped on request -- the previous files are "
                    "back in place; apply the settings again in the Gameplay settings (Server -> Game rules).")
        elif reason is not None and held:
            job.log("WARNING: the game server refused the gameplay settings it had accepted before -- the previous "
                    "files are back in place, and the settings that write them are no longer in effect; set them "
                    "again in the Gameplay settings (Server -> Game rules). Its reason: %s" % reason)
        elif reason is not None:
            job.log("WARNING: the game server refused the stored gameplay settings -- the previous files are back "
                    "in place; change the settings in the Gameplay settings (Server -> Game rules). Its reason: %s"
                    % reason)
    except AgentError as e:
        job.log("WARNING: %s: %s" % (failed, e.message))
    except Exception as e:  # noqa: BLE001 -- gameplay settings must never fail a start that succeeded
        job.log("WARNING: %s (%s)." % (failed, e))


# -- HTTP --

class Handler(BaseHTTPRequestHandler):
    server_version = "gio-agent/" + AGENT_VERSION
    timeout = 20  # socket timeout: a client that stalls mid-request must not park a thread forever

    def _authed(self):
        return self._auth_kind() is not None

    def _auth_kind(self):
        """Who the bearer is: "token" (the agent's own), "key" (the open-administration key) or None. A folder as the
        source of a move needs the token (migrate_preflight); every other admin route takes either."""
        # compare_digest: no timing side-channel -- the agent may listen on the LAN.
        # Compare BYTES, not str: http.server decodes headers as latin-1, so a non-ASCII byte in the
        # Authorization header would make compare_digest(str, str) raise TypeError and crash the
        # handler thread. Encoding both sides to bytes accepts any client input and just returns False.
        if not TOKEN:
            return None
        got = self.headers.get("Authorization", "").encode("latin-1", "replace")
        if hmac.compare_digest(got, f"Bearer {TOKEN}".encode("utf-8")):
            return "token"
        # Open administration: while the option is on, the key handed out on /public/admin/key opens
        # every admin endpoint as the token does. The key is the one in memory (open_admin_key: no
        # I/O, cannot raise) -- a wrong bearer costs a compare, never a file read.
        key = open_admin_key()
        return "key" if bool(key) and hmac.compare_digest(got, f"Bearer {key}".encode("utf-8")) else None

    def _send(self, code, obj, retry_after=None):
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        if retry_after is not None:
            self.send_header("Retry-After", str(int(retry_after)))
        self.end_headers()
        self.wfile.write(body)

    def _send_error(self, e):
        obj = {"error": e.message}
        if e.code:
            obj["code"] = e.code
        if e.retry_after is not None:
            obj["retryAfter"] = int(e.retry_after)
        return self._send(e.status, obj, retry_after=e.retry_after)

    def _read_json(self, max_body=MAX_BODY):
        raw = read_http_body(self.rfile, self.headers, max_body=max_body)
        try:
            parsed = json.loads(raw or b"{}")
        except ValueError:
            raise AgentError(400, "invalid request body (not JSON)", code="bad_request")
        return parsed if isinstance(parsed, dict) else {}

    def _client_ip(self):
        ip = self.client_address[0]
        if TRUST_PROXY:
            xff = self.headers.get("X-Forwarded-For", "")
            if xff:
                ip = xff.split(",")[0].strip() or ip
        return ip

    def _job_reply(self, kind, version, fn, lock=True):
        check_known(version)
        job = start_job(kind, version, fn, lock=lock)
        return self._send(202, {"ok": True, "async": True, "job": job.id,
                                "kind": kind, "version": version})

    # -- public (token-less) --

    def _public_get(self, path, query):
        ip = self._client_ip()
        try:
            if path == "/public/status":
                enforce_limits([("status:" + ip, 30, 60, "rate_limited")])
                return self._send(200, public_status())
            if path == "/public/admin/key":
                # Open administration: the key that opens every admin endpoint while policy.openAdmin
                # is on. The option is the state file's word, read here and never from the cached
                # snapshot (fail closed: an unreadable file reads as off, and so does a flag without a
                # usable key); the key is the one in memory, which whoever holds it keeps meanwhile.
                # The address is logged, never the key.
                enforce_limits([("openadmin:" + ip, 10, 60, "rate_limited")])
                on = get_policy().get("openAdmin")
                key = open_admin_key()
                if not on or not key:
                    raise AgentError(403, "this server does not let everyone administer it",
                                     code="open_admin_disabled")
                log_line("gio-agent: open admin key handed to %s" % ip)
                return self._send(200, {"ok": True, "token": key})
            if path.startswith("/public/jobs/"):
                enforce_limits([("jobs:" + ip, 60, 60, "rate_limited")])
                job = public_job(path[len("/public/jobs/"):])
                if job is None:
                    return self._send(404, {"error": "unknown job", "code": "not_found"})
                return self._send(200, job.public_snapshot())
        except AgentError as e:
            return self._send_error(e)
        except Exception as e:  # noqa: BLE001
            log_line("gio-agent: public GET %s from %s failed: %s" % (path, ip, e))
            return self._send(500, {"error": "server error, try later", "code": "server_error"})
        return self._send(404, {"error": "not found", "code": "not_found"})

    def _public_post(self, path):
        ip = self._client_ip()
        try:
            # Body BEFORE anything else and capped small: a token-less caller gets 4 KB, period.
            b = self._read_json(max_body=PUBLIC_MAX_BODY)
            if path == "/public/account/create":
                return self._public_create(b, ip)
            if path == "/public/command":
                return self._public_command(b, ip)
        except AgentError as e:
            return self._send_error(e)
        except KeyError as e:
            return self._send(400, {"error": f"missing/invalid field: {e}", "code": "bad_request"})
        except Exception as e:  # noqa: BLE001
            log_line("gio-agent: public POST %s from %s failed: %s" % (path, ip, e))
            return self._send(500, {"error": "server error, try later", "code": "server_error"})
        return self._send(404, {"error": "not found", "code": "not_found"})

    def _public_create(self, b, ip):
        policy = get_policy()
        if not policy["signup"]["enabled"]:
            raise AgentError(403, "account creation is disabled on this server", code="signup_disabled")
        version = str(b.get("version", "")).strip()
        check_known(version)
        vp = (policy["signup"]["versions"] or {}).get(version)
        if vp is None:
            raise AgentError(403, "account creation is disabled for this version", code="signup_disabled_version")
        name = str(b.get("name", "")).strip()
        template = str(b.get("template", "fresh")).strip() or "fresh"
        password = b.get("password")
        why = validate_account_name(name, reserved_names(version))
        if why:
            raise AgentError(400, why[1], code=why[0])
        if template not in (vp.get("templates") or []):
            raise AgentError(400, "that template is not available on this server", code="template_unavailable")
        if template != "fresh" and (not template_ready(version, template) or progress_copy_refusal(version)):
            raise AgentError(503, "that progress template is not ready on this server", code="template_not_ready")
        if version_state(version).get("passwordVerify"):
            if not (isinstance(password, str) and PASSWORD_RE.match(password)):
                raise AgentError(400, "a password of 8-64 printable characters is required", code="password_required")
        elif password is not None and password != "" and \
                not (isinstance(password, str) and PASSWORD_RE.match(password)):
            raise AgentError(400, "the password must be 8-64 printable characters", code="password_invalid")
        # This launcher's accounts on the version, before anything is spent (the job checks
        # again under the job slot, and counts the account it creates).
        client = signup_client_key(b.get("client"), ip)
        check_player_limit(version, client, vp)
        # The cached snapshot is free -- a version that is down must not burn the caller's quota.
        snap = public_status()
        vs = (snap.get("versions") or {}).get(version) or {}
        if not vs.get("up"):
            raise AgentError(503, "this server version is not running right now", code="version_down")
        # Quota fairness: a refusal that did no work must not cost the caller a signup token.
        # (a) The job slot first. server_busy is the one 429 a launcher retries on its own, and each
        #     of those retries would otherwise spend a create token.
        if current_job(skip_yielding=True) is not None:
            raise public_busy_error()
        # (b) "Name taken" BEFORE the quota, under its own small budget (namecheck_rules): the budget
        #     bounds how fast this endpoint can enumerate names (the vendor register page on :21000
        #     answers "already exists" anyway). A spent budget never refuses a signup: it falls back
        #     to the reverse order -- quota first, lookup after -- and a name taken on that path is NOT
        #     refunded, or take + refund would be an unlimited name oracle.
        quota = signup_quota_rules(ip, version, vp)

        def lookup():
            # A missing, relocated or unreadable sdk.db raises a code-less 500: log it, answer the player
            # a coded server_error (still refunded below on the fallback path).
            try:
                return _sdk_db_lookup(version, name)
            except AgentError as e:
                if e.status < 500 or e.code:
                    raise
                log_line("gio-agent: public signup lookup failed: %s" % e.message)
                raise AgentError(500, "server error, try later", code="server_error")

        prechecked = LIMITER.take_all(namecheck_rules(ip))[0]
        if prechecked and lookup() is not None:
            raise AgentError(409, "name taken", code="name_taken")
        # (c) All four create buckets or none.
        enforce_limits(quota)
        try:
            # (d) The fallback lookup.
            if not prechecked and lookup() is not None:
                raise AgentError(409, "name taken", code="name_taken")
            # (e) A job can have taken the slot since (a): that race is refunded below. The job hands
            #     the quota back itself when it fails before registering -- only for a request the
            #     namecheck budget admitted, and never for version_down (its docker exec probe holds
            #     the slot for up to 30 s, see do_signup).
            job = start_public_job("signup", version,
                                   lambda j: do_signup(version, j, name, password, template, ip,
                                                       refund=quota if prechecked else None,
                                                       client=client))
        except Exception as e:
            if not (isinstance(e, AgentError) and e.code == "name_taken"):
                LIMITER.give(quota)  # nothing ran: a busy race, or an unreadable account database
            raise
        log_line("gio-agent: public signup from %s -> job %s (name=%s version=%s template=%s)"
                 % (ip, job.id, name, version, template))
        return self._send(202, {"ok": True, "job": job.id})

    def _public_command(self, b, ip):
        if not get_policy().get("playerCommands"):
            raise AgentError(403, "player commands are disabled on this server", code="commands_disabled")
        enforce_limits([("cmd:" + ip, 30, 60, "rate_limited"), ("cmd:*", 300, 60, "rate_limited_server")])
        version = str(b.get("version", "")).strip()
        check_known(version)
        snap = public_status()
        if not ((snap.get("versions") or {}).get(version) or {}).get("up"):
            raise AgentError(503, "this server version is not running right now", code="version_down")
        uid, msg = str(b["uid"]).strip(), str(b["msg"])
        if not uid.isdigit() or len(msg) > 512:
            raise AgentError(400, "uid must be numeric and msg at most 512 characters", code="command_invalid")
        log_line("gio-agent: public command from %s: version=%s uid=%s msg=%s" % (ip, version, uid, msg[:120]))
        res = gm_command(version, uid, msg)
        return self._send(200, {"ok": True, "response": res})

    # -- the hotpatch mirror (token-less static files in the CDN layout) --

    def _hotpatch_miss(self, rel, local, ip):
        """A cached file is missing: fetch it once from the manifest's upstreams when allowed
        (hotpatch_miss_policy: a listed file, or an unlisted one under an ADVERTISED output only --
        never under a `listedOnly` manifest --, of a version whose hotpatch is enabled),
        within the per-address + global miss quotas, at most HOTPATCH_ONDEMAND_PARALLEL transfers
        at once (503 + Retry-After when busy) and, for unlisted files, the HOTPATCH_ONDEMAND_MAX byte
        budget. Anything else is a plain 404, its ONE line written by _note_route_refused's rule (a token-less
        caller could otherwise write lines at the rate the route answers). Returns True when served. Waits are
        bounded and sized for the game's downloader (2.8: no HEAD, 30 s per GET, 6 tries 3 s apart): a request
        for a file that is ALREADY being fetched waits for that fetch without taking a transfer slot, and
        a voice pack waits up to 20 s for a slot -- an instant 503 would burn the six tries in 15 s.
        The anonymous caller only ever sees "not found" / "upstream unavailable": the upstream
        detail (resolver, proxy, upstream hosts) goes to the log."""
        pol = hotpatch_miss_policy(rel)  # first: it also counts the voice packs players ask for in vain
        if pol is None:
            voice_hit = hotpatch_voice_path(rel)
            if voice_hit is None:
                _note_route_refused("unlisted", rel, ip, "not a file of an enabled hotpatch (one its manifest lists, "
                                                         "or under one of its advertised outputs) -- not fetched",
                                    head="miss")
            elif not any(e["name"] == voice_hit[3] for e in hotpatch_voice_index(voice_hit[1]).get(voice_hit[2], ())):
                _note_route_refused("unindexed", rel, ip, "a voice pack the mirrored, verified release index does not "
                                                          "name (or that index is not mirrored yet) -- not fetched",
                                    head="miss")
            # (a pack the index names, of a language nobody selected, has its own hourly line: _note_voice_refused)
            return False
        if not hotpatch_route_upstream():  # the policy as the route's copy of the state file holds it
            _note_route_refused("upstream", rel, ip, "fetching on demand is switched off on this server "
                                                     "(GIO_HOTPATCH_UPSTREAM, the policy's hotpatchUpstream) -- not "
                                                     "fetched", head="miss")
            return False
        man, expect, cap = pol
        if expect is not None and expect.get("voice"):
            free = _mirror_free_bytes()
            if free is not None and free < int(expect["size"]) + HOTPATCH_DISK_RESERVE:
                _note_route_refused("disk", rel, ip, "only %d MiB free on the mirror's volume (GIO_HOTPATCH_DISK_RESERVE "
                                                     "keeps %d) -- not fetched"
                                    % (free >> 20, HOTPATCH_DISK_RESERVE >> 20), head="miss")
                return False
        enforce_limits([("hotpatch-miss:" + ip, 120, 60), ("hotpatch-miss:*", 60, 60)], limiter=HOTPATCH_LIMITER)
        if expect is None:
            used = ondemand_bytes()
            if used >= HOTPATCH_ONDEMAND_MAX:
                _note_route_refused("budget", rel, ip, "the on-demand budget is used up (%d of %d MiB, "
                                                       "GIO_HOTPATCH_ONDEMAND_MAX) -- not fetched"
                                    % (used >> 20, HOTPATCH_ONDEMAND_MAX >> 20), head="miss")
                return False
            cap = min(cap, HOTPATCH_ONDEMAND_MAX - used)
        voice = bool(expect and expect.get("voice"))
        lk = _path_lock(rel)
        if lk.locked():  # this very file is being fetched (the same player's retry, a second player)
            if lk.acquire(timeout=HOTPATCH_WAIT):
                lk.release()
            if os.path.isfile(local):
                return True
            raise AgentError(503, "mirror busy, try again later", retry_after=3)
        if not (_hotpatch_ondemand_sem.acquire(timeout=20) if voice
                else _hotpatch_ondemand_sem.acquire(blocking=False)):
            raise AgentError(503, "mirror busy, try again later", retry_after=5)
        try:
            if voice and hotpatch_voice_expect(rel) is None:
                return False  # deselected (and maybe purged) while this request waited for its slot
            log_line("gio-agent: hotpatch miss %s from %s -- fetching from the upstream%s"
                     % (_log_rel(rel), ip, "" if expect else " (unlisted, %d MiB cap)" % (cap >> 20)))
            try:
                n = hotpatch_fetch(man.get("upstreams") or [], rel, expect=expect, cap=cap, resume=voice)
            except AgentError as e:
                if e.status == 507:
                    log_line("gio-agent: hotpatch miss %s: %s" % (_log_rel(rel), e.message))
                    raise AgentError(503, "mirror busy, try again later", retry_after=60)
                if "HTTP 404" in e.message:
                    log_line("gio-agent: hotpatch miss %s: not on the upstream either" % _log_rel(rel))
                    return False  # the upstream has no such file: a plain 404, not an error
                log_line("gio-agent: hotpatch miss %s: upstream failed: %s" % (_log_rel(rel), e.message))
                raise AgentError(502, "upstream unavailable")
            if expect is None:
                ondemand_bytes(add=n)
        finally:
            _hotpatch_ondemand_sem.release()
        return os.path.isfile(local)

    def _serve_hotpatch(self, raw, head_only):
        ip = self._client_ip()
        local = None
        sent_headers = False  # once the status line is out, no error may be written into the body
        try:
            enforce_limits([("hotpatch:" + ip, 600, 60)], limiter=HOTPATCH_LIMITER)
            fenced = []
            safe = safe_hotpatch_path(raw, fenced)
            if safe is None:
                if fenced:  # a listed-only branch was asked for a file its manifest does not prove
                    _note_fence_refused(fenced[0], ip)
                return self._send(404, {"error": "not found"})
            rel, local = safe
            closed = hotpatch_route_closed(rel)
            if closed:  # a version's files are served only while its hotpatch is enabled -- from disk too
                _note_route_refused(closed[0], rel, ip, closed[1])
                return self._send(404, {"error": "not found"})
            if not os.path.isfile(local):
                if not self._hotpatch_miss(rel, local, ip):
                    return self._send(404, {"error": "not found"})
            elif hotpatch_base_refuses(rel, ip):
                # of a base output only a voice pack its verified index names, of a language the admin selected for
                # the version -- from disk as on a miss
                return self._send(404, {"error": "not found"})
            st = os.stat(local)
            size = st.st_size
            rng = parse_range(self.headers.get("Range"), size)
            start, end = rng if rng else (0, size - 1)
            length = max(0, end - start + 1)
            sent_headers = True
            self.send_response(206 if rng else 200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("Content-Length", str(length))
            self.send_header("Last-Modified", email.utils.formatdate(st.st_mtime, usegmt=True))
            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Cache-Control", "public, max-age=86400")
            if rng:
                self.send_header("Content-Range", "bytes %d-%d/%d" % (start, end, size))
            self.end_headers()
            if head_only or length == 0:
                return None
            with open(local, "rb") as f:
                f.seek(start)
                left = length
                while left > 0:
                    chunk = f.read(min(HOTPATCH_SEND_CHUNK, left))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    left -= len(chunk)
            return None
        except AgentError as e:
            if sent_headers:
                return None
            if e.status == 416 and local is not None:
                self.send_response(416)
                self.send_header("Content-Range", "bytes */%d" % os.path.getsize(local))
                self.send_header("Content-Length", "0")
                self.end_headers()
                return None
            return self._send_error(e)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError, socket.timeout):
            return None  # the client went away / stalled mid-transfer -- nothing to report
        except Exception as e:  # noqa: BLE001
            log_line("gio-agent: hotpatch GET %s from %s failed: %s" % (_log_rel(raw or ""), ip, e))
            if sent_headers:
                return None  # the body is already declared: a JSON error would corrupt the file
            try:
                return self._send(500, {"error": "server error, try later"})
            except OSError:
                return None

    def do_HEAD(self):
        path = self.path.partition("?")[0]
        if path.startswith("/hotpatch/"):
            return self._serve_hotpatch(path[len("/hotpatch/"):], head_only=True)
        self._send(404, {"error": "not found"})

    # -- admin --

    def do_GET(self):
        path, _, query = self.path.partition("?")
        if path == "/health":
            return self._send(200, {"ok": True, "service": "gio-agent", "version": AGENT_VERSION})
        if path.startswith("/public/"):
            return self._public_get(path, query)
        if path.startswith("/hotpatch/"):
            return self._serve_hotpatch(path[len("/hotpatch/"):], head_only=False)
        if not self._authed():
            return self._send(401, {"error": "unauthorized"})
        qs = urllib.parse.parse_qs(query)
        try:
            if path == "/status":
                return self._send(200, status())
            if path == "/server/hotpatch":
                return self._send(200, hotpatch_info(qs.get("version", [""])[0]))
            if path == "/jobs":
                with _jobs_lock:
                    jobs = [JOBS[j].snapshot(10 ** 9) for j in JOBS_ORDER]
                return self._send(200, {"jobs": jobs})
            if path.startswith("/jobs/"):
                job = JOBS.get(path[len("/jobs/"):])
                if job is None:
                    return self._send(404, {"error": "no such job (was the agent restarted?)"})
                since = qs.get("since", ["0"])[0]
                return self._send(200, job.snapshot(since))
            if path == "/server/account/policy":
                return self._send(200, get_policy())
            if path == "/server/accounts":
                # One page of a version's accounts: read-only and never a job -- the logins from a copy of
                # sdk.db, the characters and who is online through one query each while the version runs. A
                # malformed query is a 400; never a 404 for a known version (that means "an agent without this
                # route" to the launcher).
                return self._send(200, accounts_list(*accounts_preflight(query)))
            if path == "/server/templates":
                return self._send(200, templates_report(qs.get("version", [""])[0]))
            if path == "/server/secrets":
                return self._send(200, secrets_info(qs.get("version", [""])[0]))
            if path == "/server/tweaks":
                # never a 404 (the launcher reads one as "this agent lacks the route"): a version without a
                # catalogue or without a stack answers 200 with available / present false
                return self._send(200, tweaks_info(qs.get("version", [""])[0]))
            if path == "/agent/config":
                return self._send(200, agent_config_info())
        except AgentError as e:
            return self._send_error(e)
        except Exception as e:  # noqa: BLE001
            return self._send(500, {"error": str(e)})
        self._send(404, {"error": "not found"})

    def do_PUT(self):
        path = self.path.partition("?")[0]
        if path == "/server/account/policy":
            return self.do_POST()
        self._send(404, {"error": "not found"})

    def do_POST(self):
        path = self.path.partition("?")[0]
        if path.startswith("/public/"):
            return self._public_post(path)
        if not self._authed():
            return self._send(401, {"error": "unauthorized"})
        try:
            # Inside the try: a malformed body is an AgentError with a real status, not a traceback
            # on the handler thread.
            b = self._read_json()
            if path == "/server/start":
                v, mode = b["version"], str(b.get("provision", "auto")).lower()
                return self._job_reply("start", v, lambda j: do_start(v, j, provision=mode))
            if path == "/server/stop":
                v = b["version"]
                return self._job_reply("stop", v, lambda j: do_stop(v, j))
            if path == "/server/setup":
                v, txt, force = b["version"], b.get("txtFixes"), bool(b.get("force"))
                prog = parse_progress(b.get("progress"))  # 400 here, before a job exists
                pf = b.get("pathfinding")  # bool | null (omitted = the stored decision, else the default)
                if pf is not None and not isinstance(pf, bool):
                    raise AgentError(400, "pathfinding must be true or false")
                # bool | null: the admin's choice for a stack with no hotpatch decision yet (null = the manifest's default)
                hp = hotpatch_choice_of(b.get("hotpatch"))  # 400 here, before a job exists
                return self._job_reply("setup", v, lambda j: do_setup(v, j, txt_fixes=txt, force=force,
                                                                      progress=prog, pathfinding=pf,
                                                                      hotpatch=hp))
            if path == "/server/provision":
                v, txt = b["version"], b.get("txtFixes")
                prog = parse_progress(b.get("progress"))
                return self._job_reply("provision", v, lambda j: do_provision(v, j, txt_fixes=txt, progress=prog))
            if path == "/server/pathfinding":
                v, on = b["version"], b["enabled"]
                if not isinstance(on, bool):
                    raise AgentError(400, "enabled must be true or false")
                return self._job_reply("pathfinding", v, lambda j: do_pathfinding(v, j, on))
            if path == "/server/txtfixes":
                v, action = b["version"], str(b.get("action", "apply")).lower()
                return self._job_reply("txtfixes", v, lambda j: do_txt_fixes(v, j, action=action))
            if path == "/server/events":
                v = b["version"]
                return self._job_reply("events", v, lambda j: do_events(v, j))
            if path == "/server/tweaks" and "cancel" in b:
                # Not a job: the gameplay-settings waits of the running job of that version end at their next
                # look (TWEAKS_STOP_KINDS) -- before a write nothing is written, while the game server reads new
                # files they go back as after a refusal, after its verdict the other services are not asked. A
                # body that carries `cancel` is a stop request whatever its value, and never starts a job.
                v, stop = b.get("version"), b["cancel"]
                if not isinstance(v, str):
                    raise AgentError(400, "version must be a string")
                if not isinstance(stop, bool):
                    raise AgentError(400, "cancel must be true or false")
                check_known(v)
                with _jobs_lock:
                    running = next((JOBS[jid] for jid in reversed(JOBS_ORDER) if JOBS[jid].state == "running"
                                    and JOBS[jid].version == v and JOBS[jid].kind in TWEAKS_STOP_KINDS), None)
                stopping = stop and running is not None
                if stopping:
                    running.tweaks_stop = True
                return self._send(200, {"ok": True, "stopping": stopping})
            if path == "/server/tweaks":
                # {version, tweaks, takenKey}: the whole gameplay-settings document, {} = no setting --
                # or {version, revert | reset: [cards], takenKey}: the files of those cards put back at once, what
                # is left applied on them -- and the takenKey of the answer the page built it on (absent = "").
                # Exactly one of tweaks / revert / reset. What cannot be right is a 400 and a version without a
                # catalogue a 409 here, before a job exists -- never a 404 (that means "an agent without this
                # route" to the launcher): a version that is not installed, or has no folder, is the job's own
                # error.
                v, doc, key, op = tweaks_preflight(b)
                return self._job_reply("tweaks", v, lambda j: do_tweaks(v, j, doc, key, **op))
            if path == "/server/netfix":
                v = b["version"]
                return self._job_reply("netfix", v, lambda j: do_netfix(v, j))
            if path == "/server/account/copy":
                # {version, from | fromUid | fromTemplate, to | toUid, dryRun?}: the malformed request is a 400
                # here, before a job exists (never a 404 -- that means "an agent without this route" to the
                # launcher).
                v, src_kw, dst_kw, dry = account_copy_preflight(b)
                return self._job_reply("accountcopy", v,
                                       lambda j: do_account_copy(v, j, dry_run=dry, **src_kw, **dst_kw))
            if path == "/server/account/create":
                # The malformed request is a 400 here, before a job exists (never a 404 --
                # that means "an agent without this route" to the launcher). An admin-started job:
                # it waits (409) while a yielding job runs, like every other one.
                v, name, pw, tpl = admin_create_preflight(b)
                return self._job_reply("accountcreate", v, lambda j: do_account_create(v, j, name, pw, tpl))
            if path == "/server/account/policy":
                return self._send(200, set_policy(b))
            if path == "/agent/state/reset":
                return self._send(200, reset_state(b.get("confirm"), force=b.get("force") is True))
            if path == "/agent/config":
                return self._send(200, set_agent_config(b))
            if path == "/agent/restart":
                how = request_restart()  # the 409s, then no job may start any more
                try:
                    self._send(202, {"ok": True, "restarting": True, "how": how})
                finally:
                    _launch_restart(how)  # even when the reply could not be written: the flag is set
                return
            if path == "/server/templates/ensure":
                v = b["version"]
                return self._job_reply("templates", v, lambda j: do_templates_ensure(v, j))
            if path == "/server/secrets":
                v = b["version"]
                vals = {k: b.get(k) for k in SECRET_KNOBS}
                return self._job_reply("secrets", v, lambda j: do_secrets(v, j, vals))
            if path == "/server/auth":
                v, verify = b["version"], b["verifyPassword"]
                if not isinstance(verify, bool):
                    raise AgentError(400, "verifyPassword must be true or false")
                dp = b.get("defaultPassword")
                return self._job_reply("auth", v, lambda j: do_auth(v, j, verify, default_password=dp))
            if path == "/server/account/password":
                v, name, pw = b["version"], str(b["name"]), b["password"]
                return self._job_reply("password", v, lambda j: do_account_password(v, j, name, pw))
            if path == "/server/hotpatch":
                v, on, purge = b["version"], b["enabled"], bool(b.get("purge"))
                if not isinstance(on, bool):
                    raise AgentError(400, "enabled must be true or false")
                return self._job_reply("hotpatch", v, lambda j: do_hotpatch(v, j, on, purge=purge))
            if path == "/server/hotpatch/voice" and b.get("cancel") is True:
                # Not a job: asks the running voice job of this version to stop after the chunk it
                # is writing (its .part stays, a later run resumes it).
                v = b["version"]
                check_known(v)
                running = running_job_of_kind("hotpatch-voice")
                stopping = running is not None and running.version == v
                if stopping:
                    _voice_cancel.set()
                return self._send(200, {"ok": True, "stopping": stopping})
            if path == "/server/fetch" and b.get("cancel") is True:
                # Same shape for the server package download: the .part stays, the archive too.
                v = b["version"]
                check_known(v)
                running = running_job_of_kind("fetch")
                stopping = running is not None and running.version == v
                if stopping:
                    _fetch_cancel.set()
                return self._send(200, {"ok": True, "stopping": stopping})
            if path == "/server/fetch":
                v, force = b["version"], bool(b.get("force"))
                fetch_preflight(v, force)  # the synchronous refusals (404/409/500) before a job exists
                return self._job_reply("fetch", v, lambda j: do_fetch(v, j, force=force),
                                       lock=False)  # it holds _op_lock for its prepare + finish phases only
            if path == "/server/navmesh" and b.get("cancel") is True:
                # Same shape for the navmesh archive download: the .part stays, the next run resumes it.
                v = b["version"]
                check_known(v)
                running = running_job_of_kind("navmesh")
                stopping = running is not None and running.version == v
                if stopping:
                    _navmesh_cancel.set()
                return self._send(200, {"ok": True, "stopping": stopping})
            if path == "/server/navmesh":
                # {version, url, sha256, size}: what cannot be right is a 400 here, before a job exists -- never
                # a 404 (that means "an agent without this route" to the launcher); a stack folder is not
                # needed, the archive lands in the agent's own payloads folder.
                v, url, sha, size = navmesh_download_preflight(b)
                return self._job_reply("navmesh", v, lambda j: do_navmesh_download(v, j, url, sha, size),
                                       lock=False)  # it holds _op_lock for its finish phase only (the download yields)
            if path == "/server/navdata" and "cancel" in b:
                # Same shape for the pathfinding data download: the .part stays, the next run resumes it. A body
                # that carries `cancel` is a stop request whatever its value, and never starts a download.
                v, stop = b.get("version"), b["cancel"]
                if not isinstance(v, str):
                    raise AgentError(400, "version must be a string")
                if not isinstance(stop, bool):
                    raise AgentError(400, "cancel must be true or false")
                check_known(v)
                running = running_job_of_kind("navdata")
                stopping = stop and running is not None and running.version == v
                if stopping:
                    _navdata_cancel.set()
                return self._send(200, {"ok": True, "stopping": stopping})
            if path == "/server/navdata":
                # {version}: every refusal before a job exists -- 400 / 500 / 409, never a 404 (that means "an
                # agent without this route" to the launcher)
                v, _cat, _missing = navdata_preflight(b)
                return self._job_reply("navdata", v, lambda j: do_navdata(v, j),
                                       lock=False)  # it holds _op_lock for its prepare and finish phases only
            if path == "/server/migrate" and "cancel" in b:
                # Not a job: the running move of that version stops at its next look -- a look between two steps of
                # the source phase, once a second during the copy and the reader's start, before each account's
                # write. A body that carries `cancel` is a stop request whatever else it holds.
                v, stop = b.get("version"), b["cancel"]
                if not isinstance(stop, bool):
                    raise AgentError(400, "cancel must be true or false")
                if not isinstance(v, str):
                    raise AgentError(400, "version must be a string")
                check_known(v)
                running = running_job_of_kind("migrate")
                stopping = stop and running is not None and running.version == v
                if stopping:
                    _migrate_cancel.set()
                return self._send(200, {"ok": True, "stopping": stopping})
            if path == "/server/migrate":
                # {version, source: {version} | {dir}, accounts?, dryRun?, keepPassword?, keepUid?}: every refusal of
                # the request itself before a job exists -- 400, a 403 for a folder with the open-administration
                # key, never a 404 (that means "an agent without this route" to the launcher): a version or a folder
                # that is not on this box is the job's own 409.
                v, req = migrate_preflight(b, self._auth_kind())
                return self._job_reply("migrate", v, lambda j: do_migrate(v, j, req),
                                       lock=False)  # it reads the source without _op_lock and takes it per account
            if path == "/server/relocate" and b.get("cancel") is True:
                # Same shape as the fetch's: a cross-volume copy stops between two files (cp -a is killed),
                # the temp copy goes, the server stays where it was (and is started again if it ran).
                v = b["version"]
                check_known(v)
                running = running_job_of_kind("relocate")
                stopping = running is not None and running.version == v
                if stopping:
                    _relocate_cancel.set()
                return self._send(200, {"ok": True, "stopping": stopping})
            if path == "/server/relocate":
                # {version, dir, mode: move|repoint[, check: true]}. `dir` is required -- an
                # omitted one must never read as "" (= take the version off this agent).
                v, raw_dir, mode = b["version"], b["dir"], b.get("mode")
                if not isinstance(v, str):
                    raise AgentError(400, "version must be a string")
                mode = mode.strip().lower() if isinstance(mode, str) else ""
                rep, refusal = relocate_check(v, raw_dir, mode)  # 400 unknown version / mode
                if b.get("check") is True:
                    return self._send(200, rep)  # the dry run: every refusal is the report's `problem`
                if refusal is not None:
                    raise refusal
                return self._job_reply("relocate", v, lambda j: do_relocate(v, j, raw_dir, mode))
            if path == "/server/hotpatch/voice":
                v, langs, purge = b["version"], b["languages"], bool(b.get("purge"))
                # Names only ever select entries of the verified index -- never a path component.
                if not isinstance(langs, list) or len(langs) > VOICE_LANGUAGES_MAX or not all(
                        isinstance(x, str) and VOICE_PACK_RE.match(x + "/x.pck") for x in langs):
                    raise AgentError(400, "languages must be a list of voice language names")
                check_known(v)
                return self._job_reply("hotpatch-voice", v, lambda j: do_hotpatch_voice(v, j, langs, purge=purge),
                                       lock=False)  # it holds _op_lock for its prepare phase only
            if path == "/command":
                res = gm_command(b["version"], b["uid"], b["msg"])
                return self._send(200, {"ok": True, "response": res})
        except AgentError as e:
            return self._send_error(e)
        except KeyError as e:
            return self._send(400, {"error": f"missing/invalid field: {e}"})
        except Exception as e:  # noqa: BLE001 -- report any failure as 500 JSON
            return self._send(500, {"error": str(e)})
        self._send(404, {"error": "not found"})

    def log_message(self, *_):  # keep the journal quiet
        pass


def selftest():
    import io
    import tempfile
    global BIND_IP, ADVERTISED_IP, ADVERTISED_HOST, IS_WINDOWS, CONFIG_FILE
    global HOTPATCH_DIR, HOTPATCH_URL, PAYLOAD_DIR, STATE_PATH, LISTEN_HOST, LISTEN_PORT
    global HOTPATCH_BUNDLE_DIR, HOTPATCH_BUNDLES, HOTPATCH_DISK_RESERVE, REGION, SERVER_NAME
    global MYSQL_ROOT_PASSWORD, FLASK_SECRET_KEY, KEEP_ENV, HOTPATCH_RETRY_WAIT
    global running_projects, _fetch_to_file, mysql_exec, run_sql, _compose_stream, verify_stack, mysql_reachable
    checks = 0
    # What the closing check compares with (the end of this function): every block below swaps module
    # functions -- and a few library ones -- for fakes and must put each of them back.
    _callables_before = {k: v for k, v in globals().items() if callable(v)}
    _lib_before = (time.sleep, time.time, urllib.request.urlopen, os.fsync)
    _versions_before = {v: dict(meta) for v, meta in VERSIONS.items()}
    # The selftest runs on every box before its upgrade, beside the box's real stacks, and no check may ask that box's
    # docker: every start of a docker program is noted here and answered as "not installed", and the end of this
    # function fails on the first one noted.
    _docker_starts = []
    _real_popen = subprocess.Popen

    class _NoDockerPopen(_real_popen):
        def __init__(self, args, *a, **k):
            word = str(args).split()[0] if isinstance(args, str) and args.strip() else str(args[0]) if args else ""
            if os.path.basename(word.replace("\\", "/")).lower() in ("docker", "docker.exe"):
                _docker_starts.append(_cmd_words(args if isinstance(args, (list, tuple)) else args.split(), 6))
                raise FileNotFoundError(2, "no docker in a selftest", "docker")
            _real_popen.__init__(self, args, *a, **k)

    subprocess.Popen = _NoDockerPopen
    # install_agent.sh runs the selftest with the box's stored GIO_* exported, every version's folder among
    # them. The checks build their stacks in temp dirs under the two versions named here, and each block
    # parks the one of them it does not use; a version that is no fixture has no block that parks it, so a
    # real stack of it would stay in reach of every loop over VERSIONS (the status, the stop of the other
    # stacks, the policy). It gets no folder and no project for the whole run, and both are put back right
    # before the closing comparison.
    SELFTEST_FIXTURES = ("1.6", "2.8")
    for v, meta in VERSIONS.items():
        if v not in SELFTEST_FIXTURES:
            meta["dir"], meta["project"] = "", ""
    # What the payload of each version is expected to hold -- data, compared with the manifests and the
    # package catalogues that came with this agent: whether the manifest ships a save, the events its events
    # block keeps open (`events`: the schedule ids of `gaa`, sorted; None = no events block), the stack files
    # those events cannot be held open without (`needsFiles`, as the block lists them; None = it names none)
    # and the rows of those events whose day gates the payload's condition table keeps as they are
    # (`dayGateKept`), the top folder + stray entries its package catalogue names (`stack`; None = no
    # expectation about that archive, a catalogue is then held to the rules every catalogue obeys), how many
    # files its pathfinding-data catalogue names, of them the vendor's (`navdata`; None = the version ships no
    # such catalogue -- one that comes with it anyway fails) and its manifest's saves block (`saves`: the
    # versions whose saves its server reads, each with the fields a save of that version holds and this one's
    # have not -- `acceptFrom`, each source with its drop list --, the client prefixes as the block lists them and
    # the sha256 of the save schema it names; None = no saves block and no save schema), and the sha256 of its
    # hotpatch manifest's bytes (`hotpatchSha256`; None = the version ships none). A schema changes only
    # together with its row: build/save_compat.py --check proves a schema against its stack and needs the stacks
    # to do so, which leaves this row the check of the shipped file -- and so does a hotpatch manifest, whose
    # entries were proven against the official index lines (and the per-file source's own metadata) when it was
    # made: it changes only together with that proof and this row. A manifest's top-level flags (the 3.2 manifest's
    # `defaultEnabled` and its note) are part of these bytes and so of this pin; the file table is pinned apart
    # (HOTPATCH_TABLES) and covers the files only. A version whose folder holds a manifest or a catalogue has a row
    # here: a payload nobody described fails instead of passing unseen.
    PAYLOAD_EXPECT = {
        "1.6": {"save": True, "events": ["2005001", "5030001", "5032001", "5033001"], "needsFiles": None,
                "stack": {"topDir": "1.6_live", "strays": []}, "navdata": None,
                "hotpatchSha256": "422051a385a2922d0619c4c8efb315e7992529017443b9ae5fe84c09a4e74ca2",
                "saves": {"acceptFrom": {"1.6": []},
                          "clientPrefixes": ["CNRELAndroid1.6.0_", "CNRELAndroid1.6.1_", "CNRELWin1.6.0_",
                                             "CNRELWin1.6.1_", "CNRELiOS1.6.0_", "CNRELiOS1.6.1_",
                                             "OSRELAndroid1.6.0_", "OSRELAndroid1.6.1_", "OSRELWin1.6.0_",
                                             "OSRELWin1.6.1_", "OSRELiOS1.6.0_", "OSRELiOS1.6.1_"],
                          "schemaSha256": "8cc484cef6b243aca850389c8ff5e4e93175a283eff2d5ca7840d10a9381eaf8"}},
        "2.8": {"save": True, "events": ["2014001", "5083001", "5084001"], "needsFiles": None,
                "stack": {"topDir": "2.8_live", "strays": ["data.txt"]}, "navdata": {"files": 828, "vendor": 773},
                "hotpatchSha256": "190da8e2780de41e92782a7b2a70f3df5cfe71066e40ba26327e21aa504f25e8",
                "saves": {"acceptFrom": {"1.6": ["PlayerDataBin.6.5.1.2.2"], "2.8": []},
                          "clientPrefixes": ["CNRELAndroid2.8.0_", "CNRELWin2.8.0_", "CNRELiOS2.8.0_",
                                             "OSRELAndroid2.8.0_", "OSRELWin2.8.0_", "OSRELiOS2.8.0_"],
                          "schemaSha256": "630af6837d4e4e59088f35e0d9627a8b30973d789bf10a132bed8e48c81f9190"}},
        # the package's own condition table ends Fabulous Fungus Frenzy's content on its event day 19; 5108017
        # ('day < 5') hands its NPCs over to 5108018 from day 5: held open it would place them twice
        "3.2": {"save": False, "events": ["2017001", "5099001", "5107001", "5108001"],
                "needsFiles": ["server/data/txt/NewActivityCondData.txt"], "dayGateKept": ["5108017"],
                "stack": {"topDir": "3.2_dev", "strays": []}, "navdata": None,
                "hotpatchSha256": "a7c428e1732762639faa7cd08a19b76f2c9b84886359a4e3bfea0ece716a3cad",
                "saves": {"acceptFrom": {"1.6": ["PlayerDataBin.6.5.1.2.2"], "2.8": [], "3.2": []},
                          "clientPrefixes": ["CNRELAndroid3.2.0_", "CNRELWin3.2.0_", "CNRELiOS3.2.0_",
                                             "OSRELAndroid3.2.0_", "OSRELWin3.2.0_", "OSRELiOS3.2.0_"],
                          "schemaSha256": "ad2c90e60c440811e3aa8a8984d47295e29e72aa4d8fcbe11364b13c402f64c7"}},
    }
    # Same for a configured DDNS host: it would make every "no advertised address" case below
    # reachable. The checks set it themselves.
    ADVERTISED_HOST = ""
    # Same for a configured mirror URL (the Agent settings card can set it): with one, every
    # "no reachable mirror URL" case below would answer that URL. The checks that want one set it.
    HOTPATCH_URL = ""
    # And the box's free-disk reserve: the hotpatch blocks below run the REAL guard against the REAL
    # free space of the volume that holds the temp mirror, so a reserve the admin raised from the
    # Agent settings card -- or a box with less than 2 GiB free under TMPDIR -- would refuse a 1600-byte
    # voice job and abort the whole upgrade. The fetch block already does this with its own twin.
    HOTPATCH_DISK_RESERVE = 1 << 20
    # The pause a job's per-file fetch takes before it asks an upstream again: the hotpatch blocks below run
    # simulated outages file by file, each of which would wait it out for real. The check of the pause itself
    # sets it, and back.
    HOTPATCH_RETRY_WAIT = 0
    # Same for the box's MUIP region (free text in install_agent.sh's prompt): a value holding "&"
    # would add split points to the signed query the signing check below takes apart.
    REGION = "selftest_region"
    # Same for the box's server name (its GIO_SERVER_NAME, else its host name): every public projection
    # carries it, and a check that a word is not in one would fail on a box named with that word.
    SERVER_NAME = "selftest-name"
    # Same for the box's stored MySQL root password / Flask secret key: a check that drives
    # a prepare path over a vendor value expects a RANDOM replacement unless it configures one itself --
    # and the box's own secrets have no business in a check's temp stacks, job lines or assertions.
    # ...but first the import-time rule itself: whatever the box stored, what reaches this point is empty or a
    # valid, non-vendor value (the messages never quote it).
    assert not MYSQL_ROOT_PASSWORD or (MYSQL_ROOT_RE.match(MYSQL_ROOT_PASSWORD)
                                       and MYSQL_ROOT_PASSWORD not in VENDOR_MYSQL_ROOT_PASSWORDS), \
        "GIO_MYSQL_ROOT_PASSWORD survived the import although it is invalid or a vendor default"
    assert not FLASK_SECRET_KEY or (SECRET_VALUE_RE.match(FLASK_SECRET_KEY)
                                    and FLASK_SECRET_KEY not in VENDOR_FLASK_KEYS), \
        "GIO_FLASK_SECRET_KEY survived the import although it is invalid or a vendor default"
    MYSQL_ROOT_PASSWORD = ""
    FLASK_SECRET_KEY = ""
    # Same for the box's "Keep .env settings" switch (GIO_KEEP_ENV): with it on, no prepare path replaces
    # a vendor value or repairs OUTER_IP -- and every check below that drives one over a vendor stack
    # expects exactly that replacement. The checks of the switch itself turn it on, and off again.
    KEEP_ENV = False
    # For the same reason the box's STATE FILE is not an input: GIO_STATE_PATH is exported too, so
    # every check that reads a record would read the RUNNING agent's history -- and abort the
    # upgrade of a real box: `secrets_info` would report the stack's vendor key
    # together with `muipSource: "random"` out of the live state, the check that expects a fresh
    # record would fail, and install_agent.sh (which runs --selftest before it touches anything)
    # would abort -- on every box that has ever prepared a stack. A scratch file is the
    # default from here on, so the selftest can neither read nor write the box's state; the blocks
    # that need a state file still point STATE_PATH at their own temp copy and restore it to this.
    def _box_state_bytes(path):
        """The box's state file as it is right now, for the before/after proof below. Never
        raises: an unreadable file is a state this must tolerate, not judge."""
        try:
            with open(path, "rb") as f:
                return f.read()
        except OSError as e:
            return "unreadable: %s" % e.__class__.__name__

    _state_scratch = tempfile.mkdtemp(prefix="gio-selftest-state-")
    _box_state = STATE_PATH  # what the box configured -- kept only to prove it stays untouched
    _box_state_before = _box_state_bytes(_box_state)
    STATE_PATH = os.path.join(_state_scratch, "state.json")
    # ...and the settings: a block that leaves a non-callable global swapped (a mode, a key, an address,
    # IS_WINDOWS) hands every later check the stand-in just the same. Taken AFTER the neutralisations above.
    _scalars_before = {k: v for k, v in globals().items() if not k.startswith("__")
                       and isinstance(v, (str, int, float, bool, type(None), tuple, frozenset))}

    def ok(msg):
        nonlocal checks
        checks += 1
        print("selftest: " + msg)

    payload = {"uid": "10001", "msg": "item add 202 555"}
    secret, host = "TESTKEY", "http://10.0.0.1:21051"
    url, qstr, sign = sign_query(payload, secret, host)
    assert "cmd=1116" in qstr, qstr
    assert f"region={REGION}" in qstr
    assert "uid=10001" in qstr and "msg=item add 202 555" in qstr
    parts = qstr.split("&")
    assert parts == sorted(parts), "kvs must be sorted"
    assert sign == hashlib.sha256((qstr + secret).encode()).hexdigest()
    assert url.startswith(host + "/api?") and f"sign={sign}" in url
    assert "msg=item+add+202+555" in url, "spaces must urlencode to '+'"
    ok("MUIP signing OK")

    # Config-file loader: KEY=VALUE, comments, BOM, quotes; the environment keeps precedence.
    pairs = parse_config_text("\ufeff# comment\n\nGIO_A=1\n GIO_B = \"two\" \nbad line\n9X=no\nGIO_C='3'\r\n")
    assert pairs == [("GIO_A", "1"), ("GIO_B", "two"), ("GIO_C", "3")], pairs
    with tempfile.TemporaryDirectory() as td:
        cfg = os.path.join(td, "config")
        with open(cfg, "w", encoding="utf-8-sig") as f:
            f.write("GIO_X=file\nGIO_Y=file\n")
        env = {"GIO_X": "env"}
        applied = apply_config_file(cfg, env)
        assert applied == ["GIO_Y"] and env == {"GIO_X": "env", "GIO_Y": "file"}, (applied, env)
        # --config / --log option parsing, both spellings
        assert _cli_option("--config", ["--config", cfg]) == cfg
        assert _cli_option("--log", ["--log=" + cfg, "x"]) == cfg
        assert _cli_option("--config", ["--selftest"]) is None
        # the rotating log: writes append, rotation keeps one .1
        lp = os.path.join(td, "agent.log")
        lg = _RotatingLog(lp, max_bytes=64)
        try:
            for i in range(10):
                lg.write("line %d is long enough to matter\n" % i)
            lg.flush()
            assert os.path.isfile(lp) and os.path.isfile(lp + ".1"), os.listdir(td)
            assert os.path.getsize(lp) <= 64 + 40 and os.path.getsize(lp + ".1") > 64
        finally:
            lg.close()
    ok("config file loader + CLI options + log rotation OK")

    # Platform defaults: Windows has no stack dirs unless told, and state lives beside --config.
    saved_plat = (IS_WINDOWS, CONFIG_FILE)
    try:
        IS_WINDOWS, CONFIG_FILE = True, None
        os.environ.pop("GIO_DIR_16_SELFTEST", None)
        assert _dir_setting("GIO_DIR_16_SELFTEST", "/home/1.6_live") == ""
        assert _default_state_path().endswith(os.path.join("Relic", "agent", "state.json")), _default_state_path()
        CONFIG_FILE = os.path.join("C:" + os.sep, "relic", "agent", "config")
        assert _default_state_path() == os.path.join(os.path.dirname(os.path.abspath(CONFIG_FILE)), "state.json")
        IS_WINDOWS, CONFIG_FILE = False, None
        assert _dir_setting("GIO_DIR_16_SELFTEST", "/home/1.6_live") == "/home/1.6_live"
        # a version without an assumed folder is not configured until its key names one
        assert _dir_setting("GIO_DIR_16_SELFTEST", "") == ""
        assert dir_setting_key("16_SELFTEST") == "GIO_DIR_16_SELFTEST" and _version_row("16_SELFTEST") == {"dir": ""} \
            and _version_row("16_SELFTEST", "/home/x_live") == {"dir": "/home/x_live"}
        assert _default_state_path() == "/var/lib/gio-agent/state.json"
        assert _popen_kwargs() == {}
        IS_WINDOWS = True
        assert "creationflags" in _popen_kwargs()
    finally:
        IS_WINDOWS, CONFIG_FILE = saved_plat
    # an unconfigured version is never a path: stack_dir refuses, is_present/is_bootstrapped say no
    saved_dir = VERSIONS["2.8"]["dir"]
    try:
        VERSIONS["2.8"]["dir"] = ""
        assert not is_present("2.8") and not is_bootstrapped("2.8") and not is_configured("2.8")
        try:
            stack_dir("2.8")
            raise AssertionError("an unconfigured version must not resolve to a directory")
        except AgentError as e:
            assert e.status == 404
    finally:
        VERSIONS["2.8"]["dir"] = saved_dir
    ok("platform defaults OK (Windows: empty dirs, state beside --config, CREATE_NO_WINDOW)")

    # The version table as the source writes it: one row per line, `"<id>": _version_row("<id>")` with the
    # id written twice -- a row that reads another version's key would hand that version's folder to this
    # one -- and, where a Linux box is assumed to hold the stack, the conventional folder of that id. The
    # rows are the versions the table holds, in its order.
    with open(os.path.abspath(__file__), encoding="utf-8") as f:
        table_src = f.read()
    table_src = table_src[table_src.index("\nVERSIONS = {\n") + len("\nVERSIONS = {\n"):]
    table_rows = [re.fullmatch(r'    "([^"]+)": _version_row\("([^"]+)"(?:, "([^"]+)")?\),', line)
                  for line in table_src[:table_src.index("\n}\n")].split("\n")]
    assert all(table_rows), "a row of VERSIONS is not written as \"<id>\": _version_row(\"<id>\"[, \"<folder>\"]),"
    assert [m.group(1) for m in table_rows] == list(VERSIONS), [m.group(1) for m in table_rows]
    for m in table_rows:
        assert m.group(2) == m.group(1) and m.group(3) in (None, "/home/%s_live" % m.group(1)), m.group(0)
        assert dir_setting_key(m.group(1)) in _SETTING_REFUSED, m.group(1)
    # ...and of those versions only the two these checks build their stacks under keep a folder for the run
    assert set(SELFTEST_FIXTURES) <= set(VERSIONS) and all(
        VERSIONS[v] == {"dir": "", "project": ""} for v in VERSIONS if v not in SELFTEST_FIXTURES)
    ok("version table OK (%d rows, one per line, each reading the folder key of its own id; an assumed Linux "
       "folder only as /home/<id>_live, none = not configured until the key names one; every folder key refused "
       "by the Agent settings; the versions that are no fixture of these checks parked for the whole run)"
       % len(table_rows))

    # TSV repair: the real NewActivityCondData line-217 shape (a tab that became two spaces).
    with tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False, encoding="utf-8") as f:
        f.write("a\tb\tc\n1\t2\t3\n4  5\t6\n")
        tmp = f.name
    text, repaired, bad = validate_tsv(tmp)
    assert repaired == 1 and not bad, (repaired, bad)
    assert "4\t5\t6" in text, text
    with open(tmp, "w", encoding="utf-8") as f:
        f.write("a\tb\tc\n1\t2\n")
    _, _, bad = validate_tsv(tmp)
    assert bad == [2], bad
    os.remove(tmp)
    ok("TSV repair OK")

    # Spiral Abyss calendar shift: whole years forward, byte-identical everywhere else. The
    # synthetic file mirrors the real one: CRLF, header without dates, half-month windows.
    hdr = "id\tentr\tfloors\topen1\tf2\to2\tf3\to3\tf4\to4\tend\treward\r"
    tower = "\n".join([
        hdr,
        "1\t1001,1002\t1009,1010\t2020-07-01 00:00:00\t\t\t\t\t\t\t2020-07-16 03:59:59\t40\r",
        "2\t1001,1002\t1011,1012\t2020-07-16 04:00:00\t\t\t\t\t\t\t2021-08-01 03:59:59\t60\r",
    ]) + "\n"
    now = "2026-08-14 12:00:00"
    new, info = shift_tower_calendar(tower, now)
    assert info["shift"] == 6 and info["start"] == "2026-07-01 00:00:00" \
        and info["end"] == "2027-08-01 03:59:59", info
    assert "2026-07-16 04:00:00" in new and "2027-08-01 03:59:59" in new, new
    assert _STAMP_RE.sub("@", new) == _STAMP_RE.sub("@", tower), "only timestamps may change"
    assert new.count("\r\n") == tower.count("\r\n") == 3, "CRLF endings must survive"
    assert tower_active_window(new, now) == ("2", "2027-08-01 03:59:59")
    again, info2 = shift_tower_calendar(new, now)
    assert info2["shift"] == 0 and again == new, "a calendar that already covers today is left alone"
    # under 12 months no whole-year shift can cover `now`: the earliest open stretches back instead
    short = "id\topen\tend\r\n7\t2020-07-01 04:00:00\t2020-10-01 03:59:59\r\n"
    new2, info3 = shift_tower_calendar(short, "2026-02-10 09:00:00")
    assert info3["start"] == "2026-02-10 00:00:00" and info3["end"] == "2026-10-01 03:59:59", info3
    assert tower_active_window(new2, "2026-02-10 09:00:00") == ("7", "2026-10-01 03:59:59")
    # a shifted Feb 29 must never be emitted into a non-leap year
    assert _plus_years("2020-02-29 04:00:00", 1) == "2021-02-28 04:00:00"
    assert _plus_years("2020-02-29 04:00:00", 4) == "2024-02-29 04:00:00"
    # a file shifted under a future-skewed clock must come BACK once the clock is right
    ahead, _ = shift_tower_calendar(tower, "2044-08-14 12:00:00")
    back, info4 = shift_tower_calendar(ahead, now)
    assert info4["shift"] == -18 and back == new, "negative re-shift must undo the skewed one"
    try:
        shift_tower_calendar("id\topen\tend\nno dates here\n", now)
        raise AssertionError("a dateless file must be refused, not rewritten")
    except AgentError as e:
        assert e.status == 500, e.status
    ok("Abyss/tower calendar OK (+years shift, CRLF and TSV intact, active window)")

    # Request framing. The chunked case is byte-for-byte what .NET's HttpClient sends; reading only
    # Content-Length would answer "400 missing/invalid field: 'version'" to every command.
    CHUNKED = {"Transfer-Encoding": "chunked"}

    def body(raw, hdrs=None, **kw):
        return read_http_body(io.BytesIO(raw), hdrs or {}, **kw)

    assert body(b'11\r\n{"version":"1.6"}\r\n0\r\n\r\n', CHUNKED) == b'{"version":"1.6"}'
    # split across chunks, with a chunk extension and a trailer -- all legal HTTP/1.1
    assert body(b'5;x=y\r\n{"ver\r\n5\r\nsion"\r\n0\r\nX-T: 1\r\n\r\n', CHUNKED) == b'{"version"'
    assert body(b'{"a":1}', {"Content-Length": "7"}) == b'{"a":1}'
    assert body(b"ignored") == b""  # no framing headers at all -> no body
    for raw, hdrs in ((b"zz\r\n", CHUNKED), (b"", {"Content-Length": "x"})):
        try:
            body(raw, hdrs)
            raise AssertionError("malformed framing must be rejected: %r" % raw)
        except AgentError as e:
            assert e.status == 400, e.status
    # the public body cap: 4 KB + 1 is refused with 413 in both framings
    big = b"x" * (PUBLIC_MAX_BODY + 1)
    for raw, hdrs in ((big, {"Content-Length": str(len(big))}),
                      (b"%x\r\n" % len(big) + big + b"\r\n0\r\n\r\n", CHUNKED)):
        try:
            body(raw, hdrs, max_body=PUBLIC_MAX_BODY)
            raise AssertionError("a public body over the cap must be refused")
        except AgentError as e:
            assert e.status == 413, e.status
    ok("HTTP body framing OK (chunked + counted + malformed + public 4 KB cap)")

    # compose ps parsing -- the eyes of the stability check and the service watchdog. NDJSON is
    # modern compose, the array is older compose; garbage must read as "docker is mute" (None),
    # never as an empty-but-valid answer that would count every service as dead.
    nd = _parse_ps_json('{"Service":"mysql","State":"running"}\n{"Service":"gameserver","State":"exited"}')
    assert nd == {"mysql": "running", "gameserver": "exited"}, nd
    arr = _parse_ps_json('[{"Service":"mysql","State":"running"},{"Service":"nodeserver","State":"Exited"}]')
    assert arr == {"mysql": "running", "nodeserver": "exited"}, arr
    assert _parse_ps_json("") == {} and _parse_ps_json(None) == {}
    assert _parse_ps_json("plain text, not json") is None
    # exited AND never-created both count as dead; a healthy stack reports nothing
    dead = _dead_from(["gameserver", "mysql", "nodeserver"], {"mysql": "running", "gameserver": "exited"})
    assert dead == ["gameserver", "nodeserver"], dead
    assert _dead_from(["mysql"], {"mysql": "running"}) == []
    ok("compose ps parsing OK (NDJSON + array + garbage -> mute)")

    # compose ls parsing -- same defensive shape as ps: array today, NDJSON-proof for tomorrow.
    assert _parse_ls_json('[{"Name":"16_live","Status":"running(13)"}]') == ["16_live"]
    assert _parse_ls_json('{"Name":"16_live"}\n{"Name":"28_live"}') == ["16_live", "28_live"]
    assert _parse_ls_json("") == [] and _parse_ls_json(None) == []
    assert _parse_ls_json("not json") is None and _parse_ls_json('["only","strings"]') is None
    # the compose project name is derived from the dir basename exactly like compose derives it --
    # the agent's up-checks compare it against `ls` output, so the derivation must match compose's.
    assert _project_name("/home/1.6_live") == "16_live"
    assert _project_name("/root/2.8_live/") == "28_live"
    assert _project_name("/srv/My.Stack-X") == "mystack-x"
    assert _project_name("D:\\servers\\1.6_live") == "16_live" or os.name != "nt"
    ok("compose ls parsing + derived project name OK")

    # IP rewrite must not maul the docker subnet (172.10.3.8 shares no boundary with 172.10.3.80).
    text = 'outer_ip="192.0.2.57" peer="172.10.3.8" other="192.0.2.570"'
    out = re.sub(IP_RE % re.escape("192.0.2.57"), "198.51.100.171", text)
    assert 'outer_ip="198.51.100.171"' in out and '172.10.3.8' in out and '192.0.2.570' in out, out

    # Bind-IP guard: a re-extracted archive ships OUTER_IP=127.0.0.1 and every render (compose port
    # bindings, server XMLs, data.sql) inherits it -- the "server busy (502)" reinstall trap.
    saved = (BIND_IP, ADVERTISED_IP, VERSIONS["1.6"]["dir"])

    class _Job:
        def __init__(self):
            self.lines = []

        def log(self, msg):
            self.lines.append(str(msg))

    with tempfile.TemporaryDirectory() as td:
        VERSIONS["1.6"]["dir"] = td
        with open(os.path.join(td, ".env"), "w", encoding="utf-8") as f:
            f.write("# keep this comment\nMYSQL_ROOT_PASSWORD=pw\nOUTER_IP=10.99.99.99\n"
                    "RELOAD_CONFIG_INTERVAL=-1\n")
        try:
            # 192.0.2.x is TEST-NET-1 -- unbindable, unless the box allows nonlocal binds
            # (net.ipv4.ip_nonlocal_bind=1), in which case the sub-check proves nothing: skip it.
            BIND_IP, ADVERTISED_IP = "192.0.2.123", "198.51.100.171"
            if _bindable("192.0.2.123"):
                print("selftest: skipping the foreign-IP refusal (ip_nonlocal_bind=1 on this machine)")
            else:
                try:
                    ensure_bind_ip("1.6", _Job())
                    raise AssertionError("a GIO_BIND_IP that is not this machine's must be refused")
                except AgentError as e:
                    assert e.status == 500 and "GIO_ADVERTISED_IP" in e.message

            # loopback GIO_BIND_IP on a server clients must reach is a config error, not a repair
            BIND_IP = "127.0.0.1"
            try:
                ensure_bind_ip("1.6", _Job())
                raise AssertionError("loopback GIO_BIND_IP + GIO_ADVERTISED_IP set must be refused")
            except AgentError as e:
                assert e.status == 500 and "loopback" in e.message

            # ...but explicit localhost play (no advertised IP) is fine -- and exercises the rewrite
            ADVERTISED_IP = ""
            assert ensure_bind_ip("1.6", _Job()) == "127.0.0.1"
            env = read_env("1.6")
            assert env["OUTER_IP"] == "127.0.0.1" and env["MYSQL_ROOT_PASSWORD"] == "pw"
            with open(os.path.join(td, ".env"), encoding="utf-8") as f:
                assert "# keep this comment" in f.read(), ".env comments must survive"

            # localhost-only play (no advertised IP, no bind IP) must be left alone
            BIND_IP = ""
            assert ensure_bind_ip("1.6", _Job()) == "127.0.0.1"
            assert read_env("1.6")["OUTER_IP"] == "127.0.0.1"

            # reachable server left with the vendor loopback: auto-detect (or the explicit error
            # pointing at GIO_BIND_IP on a box where detection has no route to work with)
            ADVERTISED_IP = "198.51.100.171"
            try:
                got = ensure_bind_ip("1.6", _Job())
                assert got and not got.startswith("127."), got
                assert read_env("1.6")["OUTER_IP"] == got
            except AgentError as e:
                assert e.status == 500 and "GIO_BIND_IP" in e.message

            # a BOM'd .env (Windows editor round trip) must still edit in place, not append a twin,
            # and CRLF endings must come out as CRLF
            with open(os.path.join(td, ".env"), "w", encoding="utf-8-sig", newline="") as f:
                f.write("OUTER_IP=127.0.0.1\r\nMYSQL_ROOT_PASSWORD=pw\r\n")
            write_env_value("1.6", "OUTER_IP", "192.0.2.7")
            write_env_value("1.6", "NEW_KEY", "v")
            with open(os.path.join(td, ".env"), "rb") as f:
                raw = f.read()
            assert raw.count(b"OUTER_IP=") == 1 and b"192.0.2.7" in raw, raw
            assert raw == b"OUTER_IP=192.0.2.7\r\nMYSQL_ROOT_PASSWORD=pw\r\nNEW_KEY=v\r\n", raw

            # the loopback-render detector + the generic template renderer (CRLF preserved)
            with open(os.path.join(td, "docker-compose.yml.tmpl"), "w", encoding="utf-8", newline="") as f:
                f.write('ports:\r\n  - "%OUTER_IP%:21000:80"\r\npass: "%MYSQL_ROOT_PASSWORD%"\r\n')
            n = render_stack_configs("1.6", _Job())
            assert n == 1, n
            with open(os.path.join(td, "docker-compose.yml"), "rb") as f:
                rendered = f.read()
            assert b'"192.0.2.7:21000:80"\r\n' in rendered and b'pass: "pw"' in rendered, rendered
            assert not compose_binds_loopback("1.6")
            write_env_value("1.6", "OUTER_IP", "127.0.0.1")
            render_stack_configs("1.6", _Job())
            assert compose_binds_loopback("1.6")
            # a LAN-only box (advertised empty, bind IP set) walks into the same trap -- stay armed
            ADVERTISED_IP, BIND_IP = "", "10.99.99.99"
            assert compose_binds_loopback("1.6")
            BIND_IP = ""  # localhost play proper: loopback bindings are the point, not a bug
            assert not compose_binds_loopback("1.6")

            # secrets: the shared literal is replaced in every syntax and nowhere else; the MUIP key
            # by anchor; the password-verify flag by regex; all with endings intact
            old = "HsjnaKGabKebabSarmale"
            sql = ("CREATE USER IF NOT EXISTS 'hk4e_work'@'172.10.%%' IDENTIFIED BY '%s';\r\n"
                   "CREATE USER IF NOT EXISTS 'hk4e_readonly'@'172.10.%%' IDENTIFIED BY '%s';\r\n"
                   "-- %s appears in a comment too\r\n" % (old, old, old))
            new_sql, n = replace_sql_identified_by(sql, old, "NewPass_123")
            assert n == 2 and new_sql.count("NewPass_123") == 2 and "-- %s appears" % old in new_sql, new_sql
            comp = "    command: redis-server --save 60 1 --loglevel warning --requirepass %s\n  x: %sX\n" % (old, old)
            new_comp, n = replace_requirepass(comp, old, "NewPass_123")
            assert n == 1 and "--requirepass NewPass_123\n" in new_comp and "%sX" % old in new_comp, new_comp
            sh = "mysql -h172.10.3.100 -u hk4e_work -p%s < data.sql\nmysql -u hk4e_work -p%s < adjust.sql\necho -p%sx\n" % (old, old, old)
            new_sh, n = replace_sh_password(sh, old, "NewPass_123")
            assert n == 2 and new_sh.count("-pNewPass_123 <") == 2 and "-p%sx" % old in new_sh, new_sh
            xml = ('<Db index="1" user="hk4e_work" pwd="%s" dbname="hk4e_db_user" />\r\n'
                   '<Db index="14" host="172.10.3.101" pwd="%s" db="7"/>\r\n'
                   '<ApiConf sign_key="8JTdsghuAythdHFtjkasiuHbxdjjayYfsvaJ" />\r\n'
                   '<Other notpwd="%s" />\r\n' % (old, old, old))
            new_xml, n = replace_xml_pwd(xml, old, "NewPass_123")
            assert n == 2 and new_xml.count('pwd="NewPass_123"') == 2 and 'notpwd="%s"' % old in new_xml, new_xml
            assert new_xml.count("\r\n") == 4
            keyed, n = replace_sign_key(new_xml, "MuipKey_0123456789")
            assert n == 1 and 'sign_key="MuipKey_0123456789"' in keyed and 'pwd="NewPass_123"' in keyed
            assert "sign_key" not in replace_sign_key("no key here", "x")[0] or True
            assert replace_sign_key("no key here", "x")[1] == 0
            cfg = '{\r\n  "auth": {\r\n    "enable_password_verify": false,\r\n    "enable_server_guest": true\r\n  }\r\n}\r\n'
            on, n = set_password_verify_text(cfg, True)
            assert n == 1 and '"enable_password_verify": true,' in on and on.count("\r\n") == cfg.count("\r\n"), on
            off, n = set_password_verify_text(on, False)
            assert n == 1 and off == cfg, off
            assert set_password_verify_text("{}", True)[1] == 0
            # the same, applied to files through _rewrite (atomic, endings preserved)
            sdk_dir = os.path.join(td, "sdk", "data")
            os.makedirs(sdk_dir)
            with open(os.path.join(sdk_dir, "config.json.tmpl"), "w", newline="") as f:
                f.write(cfg)
            VERSIONS["1.6"]["dir"] = td
            n = _rewrite(os.path.join(sdk_dir, "config.json.tmpl"), lambda t: set_password_verify_text(t, True))
            with open(os.path.join(sdk_dir, "config.json.tmpl"), "rb") as f:
                assert n == 1 and b'"enable_password_verify": true,\r\n' in f.read()
            assert _rewrite(os.path.join(td, "nope.json"), lambda t: (t, 1)) == 0
            # secrets_info: values come from the sources, the MUIP key only as a fingerprint
            os.makedirs(os.path.join(td, "server", "muipserver", "conf"))
            with open(os.path.join(td, "server", "muipserver", "conf", "muipserver.xml.tmpl"), "w") as f:
                f.write('<ApiConf sign_key="8JTdsghuAythdHFtjkasiuHbxdjjayYfsvaJ" />\n')
            with open(os.path.join(td, "docker-compose.yml.tmpl"), "a") as f:
                f.write("cmd: redis-server --requirepass %s\n" % old)
            write_env_value("1.6", "FLASK_SECRET_KEY", "fl")
            info = secrets_info("1.6")
            assert info["mysqlRoot"] == "pw" and info["flask"] == "fl" and info["internal"] == old, info
            assert info["muip"]["set"] and len(info["muip"]["fingerprint"]) == 8
            assert "8JTdsghu" not in json.dumps(info), "the MUIP key must never be returned"
            assert info["muip"]["vendorDefault"] is True and info["muip"]["source"] is None, info["muip"]
            assert internal_literal("1.6") == old
            write_creds_file("1.6", {"mysqlRoot": "a", "flask": "b", "muip": "c", "internal": "d"})
            with open(os.path.join(td, "creds.txt")) as f:
                creds = f.read()
            assert "mysql/root: a" in creds and "h4ke pass: d" in creds and "Managed by" in creds
        finally:
            BIND_IP, ADVERTISED_IP, VERSIONS["1.6"]["dir"] = saved
    ok("bind-IP guard OK (.env repair, CRLF kept, loopback render detection)")
    ok("secrets helpers OK (SQL/compose/sh/XML anchors, sign_key, creds.txt, fingerprint only)")
    ok("password-verify flag edit OK (regex, endings kept, atomic rewrite)")

    # Exec-bit repair + owner/mode preservation -- POSIX only (Windows has no Unix exec bit; the
    # authoritative run is the one install_agent.sh does on the box).
    if os.name == "posix":
        saved_dir = VERSIONS["1.6"]["dir"]
        with tempfile.TemporaryDirectory() as td:
            VERSIONS["1.6"]["dir"] = td
            try:
                os.makedirs(os.path.join(td, "dockerfiles", "prepare-vars"))
                os.makedirs(os.path.join(td, "server", "gameserver"))
                os.makedirs(os.path.join(td, "server", "data"))
                for rel in (("bootstrap.sh",), ("dockerfiles", "prepare-vars", "prepare-vars.sh"),
                            ("server", "gameserver", "gameserver"), ("server", "data", "notes.txt")):
                    p = os.path.join(td, *rel)
                    with open(p, "w") as f:
                        f.write("x")
                    os.chmod(p, 0o644)
                assert ensure_exec_bits("1.6", _Job()) == 3
                assert os.stat(os.path.join(td, "bootstrap.sh")).st_mode & 0o111 == 0o111
                assert os.stat(os.path.join(td, "server", "gameserver", "gameserver")).st_mode & 0o111
                assert not os.stat(os.path.join(td, "server", "data", "notes.txt")).st_mode & 0o111, \
                    "data files must not get an exec bit"
                assert ensure_exec_bits("1.6", _Job()) == 0, "idempotent"
                # an overwritten file gets its previous mode back...
                secret_f = os.path.join(td, "sec.bin")
                with open(secret_f, "w") as f:
                    f.write("old")
                os.chmod(secret_f, 0o600)
                prev = _stat_or_none(secret_f)
                with open(secret_f, "w") as f:
                    f.write("new")
                os.chmod(secret_f, 0o644)  # what copy2 would have stamped from the payload
                _restore_owner_mode(secret_f, prev)
                assert os.stat(secret_f).st_mode & 0o7777 == 0o600
                # ...and a NEW file gets 0644 + its directory's owner (the container-uid case)
                fresh = os.path.join(td, "server", "data", "fresh.bin")
                open(fresh, "w").close()
                os.chmod(fresh, 0o750)
                _restore_owner_mode(fresh, None)
                assert os.stat(fresh).st_mode & 0o7777 == 0o644
                if hasattr(os, "chown") and os.geteuid() == 0:
                    os.chown(os.path.join(td, "server", "data"), 12345, 12345)
                    _restore_owner_mode(fresh, None)
                    st = os.stat(fresh)
                    assert (st.st_uid, st.st_gid) == (12345, 12345), \
                        "a new file must inherit the directory's owner"
            finally:
                VERSIONS["1.6"]["dir"] = saved_dir
        ok("exec-bit repair + owner/mode preservation OK")
    else:
        j = _Job()
        saved_dir = VERSIONS["1.6"]["dir"]
        VERSIONS["1.6"]["dir"] = os.getcwd()
        try:
            assert ensure_exec_bits("1.6", j) == 0 and j.lines and "skipped" in j.lines[0]
        finally:
            VERSIONS["1.6"]["dir"] = saved_dir
        print("selftest: skipping the exec-bit test (POSIX only; the no-op path logs one line)")

    # The day gates of the events an events block keeps open, read from the payload's condition table
    # (NewActivityCondData.txt: column 0 the CondId, 3 how its conditions combine -- 1 (or empty: the vendor
    # writes 'day >= 1 & quest & day < 18' so) all of them, 2 any one of them --, 4..13 five (type, value)
    # conditions, 14..23 five ON actions as (type, parameter)). A row of a kept-open event -- its CondId starts
    # with the event's activity id, the schedule id without its last three digits -- (a) holds no 'day < N'
    # (condition 13) below 7777, the day the tables use for "never", and no 'time < T' (condition 2): either ends
    # the row on a date of its own; and (b) runs no ON action that closes something where the date alone fires
    # it: a row that needs all its conditions, all of them the event day (12, 13), the time (1, 2) or the
    # player's level (3, 14), with a largest 'day >= N' of 2 or more below 7777 or a 'time > T' (1); a row that
    # needs any one of them, with such a 'day >= N' or a 'time > T' among them. Such a row ends the event's
    # content on a day of its own, whatever the schedule in the database says. Day 0 and day 1 hold from the
    # event's start; a row that needs all its conditions and also waits for a quest or for progress closes as
    # part of the play, while the player's level is no progress of the event -- the date fires such a row for
    # every player who has that level. The closing actions are one numbering in the 1.6, 2.8 and 3.2
    # gameservers (the NEW_ACTIVITY_ACTION enum their debug information carries): every action whose name holds
    # CLOSE, LOCK (never UNLOCK), CANCEL, UNLOAD, FORBID, DEL_, DEACTIV, HIDE_SCENE_POINT, UNREGISTER, DISABLE or
    # INTERRUPT, and 59 MODIFY_ACTIVITY_COND_DEFAULT.
    day_gate_closers = frozenset((2, 4, 5, 8, 12, 13, 14, 16, 18, 20, 22, 26, 29, 31, 33, 36, 39, 42, 43, 45, 49, 52,
                                  54, 56, 58, 59, 60, 63, 64, 66, 70, 71, 73, 77, 79, 84, 85, 86, 87, 90, 96, 97, 104,
                                  108, 116, 117, 119, 122, 123, 129, 137, 144, 147, 149, 158, 162))
    assert len(day_gate_closers) == 56

    def day_gate_problems(data, open_ids, kept):
        """[text] -- one per row of the condition table `data` (its bytes) that ends an event of `open_ids`
        on a date of its own; the CondIds in `kept` are left as they are."""
        prefixes = tuple(str(int(s) // 1000) for s in open_ids)
        found = []
        for line in data.decode("utf-8").split("\n")[1:]:
            r = line.rstrip("\r").split("\t")
            if not line.strip() or not r[0].startswith(prefixes) or r[0] in kept:
                continue
            if len(r) < 24:
                found.append("%s: %d columns" % (r[0], len(r)))
                continue
            terms = [(r[4 + 2 * k].strip(), r[5 + 2 * k].strip()) for k in range(5) if r[4 + 2 * k].strip()]
            acts = [r[14 + 2 * k].strip() for k in range(5) if r[14 + 2 * k].strip()]
            if not all(t.isdigit() and (t not in ("12", "13") or p.isdigit()) for t, p in terms) \
                    or not all(a.isdigit() for a in acts):
                found.append("%s: a condition or an action that is not a number" % r[0])
                continue
            combine = r[3].strip()
            if combine not in ("", "1", "2"):
                found.append("%s: conditions combined as %r -- neither all (1) nor any (2) of them" % (r[0], combine))
                continue
            found += ["%s: day < %s" % (r[0], p) for t, p in terms if t == "13" and int(p) < 7777]
            found += ["%s: time < %s" % (r[0], p) for t, p in terms if t == "2"]
            closing = [int(a) for a in acts if int(a) in day_gate_closers]
            days = [int(p) for t, p in terms if t == "12"]
            later = [n for n in days if 2 <= n < 7777]
            times = [p for t, p in terms if t == "1"]
            if not closing or not (later or times):
                continue
            if combine == "2":
                found.append("%s: %s OR ... closes %s" % (
                    r[0], "day >= %d" % min(later) if later else "time > %s" % times[0], closing))
            elif all(t in ("1", "2", "3", "12", "13", "14") for t, _p in terms) and max(days or [0]) < 7777:
                found.append("%s: %s closes %s" % (
                    r[0], "day >= %d" % max(later) if later else "time > %s" % times[0], closing))
        return found

    def _cond_row(cid, terms=(), on=(), combine="1"):
        cells = [cid, "1", "", combine] + [""] * 31
        for k, (t, p) in enumerate(terms):
            cells[4 + 2 * k], cells[5 + 2 * k] = str(t), str(p)
        for k, (t, p) in enumerate(on):
            cells[14 + 2 * k], cells[15 + 2 * k] = str(t), str(p)
        return "\t".join(cells)
    _cond_head = "\t".join(["CondId"] + ["c%d" % n for n in range(1, 35)])
    for row, kept, want in (
            # the vendor's own closers of a kept-open event: a 'day < N' window, a day-only close of the content
            (_cond_row("2017001", [(12, 1), (13, 19)], [(3, "4008101")]), [], ["2017001: day < 19"]),
            (_cond_row("2017501", [(12, 19)], [(162, ""), (2, "704")]), [], ["2017501: day >= 19 closes [162, 2]"]),
            (_cond_row("5099777", [(12, 11)], [(56, "")]), [], ["5099777: day >= 11 closes [56]"]),
            # the same rows with the day that never comes, and the rows the rule leaves alone
            (_cond_row("2017001", [(12, 1), (13, 7777)], [(3, "4008101")]), [], []),
            (_cond_row("2017501", [(12, 7777)], [(162, ""), (2, "704")]), [], []),
            (_cond_row("5099778", [(12, 1)], [(162, "")]), [], []),
            (_cond_row("5099779", [(12, 5), (4, 4008506)], [(2, "682")]), [], []),
            (_cond_row("5099780", [(12, 14)], [(47, "83")]), [], []),
            (_cond_row("2003402", [(12, 18)], [(33, "")]), [], []),
            (_cond_row("5108017", [(12, 2), (13, 5)], [(17, "133220643")]), [], ["5108017: day < 5"]),
            (_cond_row("5108017", [(12, 2), (13, 5)], [(17, "133220643")]), ["5108017"], []),
            (_cond_row("5099781", [(12, "x")]), [], ["5099781: a condition or an action that is not a number"]),
            ("5099782\t1", [], ["5099782: 2 columns"]),
            # a row any one of whose conditions is enough fires on its date alone, whatever else it waits for
            (_cond_row("5099783", [(12, 21), (4, 4001103)], [(57, "4,109"), (59, "5099001")], "2"), [],
             ["5099783: day >= 21 OR ... closes [59]"]),
            (_cond_row("5099784", [(12, 5), (13, 7777), (4, 4008506)], [(2, "682")], "2"), [],
             ["5099784: day >= 5 OR ... closes [2]"]),
            (_cond_row("5099785", [(1, "4"), (4, 4001103)], [(60, "4,7")], "2"), [],
             ["5099785: time > 4 OR ... closes [60]"]),
            (_cond_row("5099783", [(12, 7777), (4, 4001103)], [(57, "4,109"), (59, "5099001")], "2"), [], []),
            (_cond_row("5099786", [(12, 1), (4, 4001103)], [(59, "5099001")], "2"), [], []),
            # a row that needs all its conditions: its largest day decides, and the level is no progress of the event
            (_cond_row("2017503", [(12, 1), (12, 19)], [(162, "")]), [], ["2017503: day >= 19 closes [162]"]),
            (_cond_row("2017504", [(12, 19), (13, 7777)], [(162, "")]), [], ["2017504: day >= 19 closes [162]"]),
            (_cond_row("2017505", [(12, 19), (14, 30)], [(162, "")]), [], ["2017505: day >= 19 closes [162]"]),
            (_cond_row("2017506", [(12, 19)], [(162, "")], ""), [], ["2017506: day >= 19 closes [162]"]),
            (_cond_row("2017507", [(1, "4")], [(162, "")]), [], ["2017507: time > 4 closes [162]"]),
            (_cond_row("2017508", [(12, 19), (11, 1210)], [(162, "")]), [], []),
            (_cond_row("2017509", [(12, 19), (12, 7777)], [(162, "")]), [], []),
            (_cond_row("2017510", [(12, 1), (2, "5")], [(3, "4008101")]), [], ["2017510: time < 5"]),
            (_cond_row("2017511", [(12, 19)], [(162, "")], "3"), [],
             ["2017511: conditions combined as '3' -- neither all (1) nor any (2) of them"])):
        table = (_cond_head + "\r\n" + row + "\r\n").encode("utf-8")
        got = day_gate_problems(table, ["2017001", "5099001", "5108001"], kept)
        assert got == want, (row[:40], got, want)
        assert day_gate_problems(table.replace(b"\r\n", b"\n"), ["2017001", "5099001", "5108001"], kept) == want, \
            "the same with LF line ends"
    ok("day gates: a kept-open event's 'day < N' below 7777, its 'time < T' and the closers the date alone fires "
       "(all or any of a row's conditions) are found (the closing actions of the gameservers' enum, the rows a "
       "version keeps named in PAYLOAD_EXPECT)")

    def saves_payload_problem(v, man_, expect):
        """Why the saves block of the manifest `man_` of version v is not the one PAYLOAD_EXPECT describes
        (`expect`: its acceptFrom, each source with its drop list, its clientPrefixes in their order and the sha256
        of the schema file it names; None = no saves block and no save_schema.json in the version's payload
        folder); None when it is. The version's server reads its own saves dropping nothing, and the schema the
        block names is one copy_save can follow (save_plan)."""
        saves = man_.get("saves")
        if expect is None:
            if saves is not None or os.path.exists(os.path.join(payload_dir(v), "save_schema.json")):
                return "a saves block or a save_schema.json that PAYLOAD_EXPECT does not name"
            return None
        why = saves_block_problem(saves)
        if why:
            return "the saves block: %s" % why
        if sorted(saves) != ["acceptFrom", "clientPrefixes", "schema"]:
            return "the saves block holds %s" % sorted(saves)
        accepted = dict((src, rule["drop"]) for src, rule in saves["acceptFrom"].items())
        if accepted != expect["acceptFrom"]:
            return "acceptFrom says %s, PAYLOAD_EXPECT says %s" % (accepted, expect["acceptFrom"])
        if accepted.get(v) != []:
            return "its server does not read its own saves, dropping nothing"
        if saves["clientPrefixes"] != expect["clientPrefixes"]:
            return "clientPrefixes says %s, PAYLOAD_EXPECT says %s" % (saves["clientPrefixes"], expect["clientPrefixes"])
        plan_, why_ = save_plan(v, man_)
        if plan_ is None:
            return why_ or "no save schema"
        with open(os.path.join(payload_dir(v), saves["schema"]), "rb") as f:
            sha = hashlib.sha256(f.read()).hexdigest()
        if sha != expect["schemaSha256"]:
            return "%s has the sha256 %s, PAYLOAD_EXPECT says %s" % (saves["schema"], sha, expect["schemaSha256"])
        return None

    # Every shipped manifest must be loadable and point at files that exist.
    shipped_saves = {}  # version -> (its manifest, its compiled save schema)
    for v in VERSIONS:
        man = read_manifest(v)
        if not man:
            print("selftest: no payload for", v, "(skipped)")
            continue
        # what this version is expected to ship is written down (PAYLOAD_EXPECT) and the manifest agrees
        assert v in PAYLOAD_EXPECT, \
            "payloads/%s/manifest.json: no row for version %s in PAYLOAD_EXPECT -- a payload nobody described" % (v, v)
        assert manifest_ships_save(man) is PAYLOAD_EXPECT[v]["save"], \
            "payloads/%s: %s a save, PAYLOAD_EXPECT says otherwise" % (v, "ships" if manifest_ships_save(man) else "ships no")
        kept_open = sorted(str(k) for k in ((man.get("events") or {}).get("gaa") or {})) \
            if manifest_has_events(man) else None
        assert kept_open == PAYLOAD_EXPECT[v]["events"], \
            "payloads/%s: the events block keeps %s open, PAYLOAD_EXPECT says %s" \
            % (v, kept_open, PAYLOAD_EXPECT[v]["events"])
        for item in man.get("files", []) + man.get("mysql", []):
            p = os.path.join(payload_dir(v), item["src"])
            assert os.path.isfile(p), "payload missing: " + p
        for item in man.get("files", []):
            p = os.path.join(payload_dir(v), item["src"])
            # an entry is installed by exactly one stage, into the stack and nowhere else: a stage nothing
            # installs, or a dst that leaves the stack folder, is a manifest written wrongly
            assert effective_stage(item) in MANIFEST_STAGES, \
                "payloads/%s: %s names the stage %r, which nothing installs" % (v, item["src"], item.get("stage"))
            assert manifest_dst_problem(item.get("dst")) is None, \
                "payloads/%s: the entry of %s: %s" % (v, item["src"], manifest_dst_problem(item.get("dst")))
            if item.get("md5") is not None:
                # the bytes the entry pins are the bytes that came with this agent
                assert isinstance(item["md5"], str) and _HEX32_RE.match(item["md5"].lower()), \
                    "payloads/%s: the md5 of %s is not 32 hex digits" % (v, item["src"])
                assert _file_md5(p) == item["md5"].lower(), \
                    "payloads/%s: %s does not match the md5 its manifest entry pins" % (v, item["src"])
            if effective_stage(item) == BOOTSTRAP_STAGE:
                assert bootstrap_entry_problem(item) is None, \
                    "payloads/%s: the bootstrap entry of %s: %s" % (v, item.get("dst"), bootstrap_entry_problem(item))
            if item.get("tsv"):
                # a table goes into the stack exactly as it was shipped: no row the server would refuse,
                # none the installer would have to repair on the way, and no byte that is not UTF-8 --
                # install_files writes the decoded text back, which gives such a byte back as another one
                _text, repaired, bad = validate_tsv(p)
                assert not bad and not repaired, \
                    "payloads/%s: %s has rows of the wrong width (bad: %s, repairable: %d)" % (v, item["src"], bad[:5], repaired)
                with open(p, "rb") as f:
                    assert _text.encode("utf-8") == f.read(), \
                        "payloads/%s: %s would not be installed byte for byte (it holds bytes that are not UTF-8)" \
                        % (v, item["src"])
        for stmt in man.get("sql_events", []):
            # One statement per entry -- run_sql reports per-statement failures, and a stray ';'
            # would hide the second half of a line inside a single "ok"/"ignored" log entry.
            # (A ';' inside a quoted string, as in a `desc` column, is fine.)
            assert ";" not in re.sub(r"'[^']*'", "''", stmt), \
                "sql_events must be one statement per entry: " + stmt[:60]
        ev = man.get("events") or {}
        gaa, others = ev.get("gaa") or {}, ev.get("others") or {}
        # the events block is optional (without one the stack keeps its own schedule); one that is there
        # names at least one event to keep open -- apply_events refuses it otherwise
        assert gaa or not manifest_has_events(man), "no open events listed for " + v
        assert not (set(gaa) & set(others)), \
            "an event cannot be both open and closed: %s" % (set(gaa) & set(others))
        for k in list(gaa) + list(others):
            assert str(k).isdigit(), "schedule ids must be numeric (SQL is built from them): " + str(k)
        # A file the events block needs (needsFiles) is the one PAYLOAD_EXPECT names, and one this payload
        # installs whenever a progress choice is applied and never takes back, pinned by md5 -- the bytes apply_events
        # compares the stack's copy with (events_files_missing) before it opens anything. A `config` entry: a
        # `txt_fix` one is left out while txt fixes wait for later, and "Revert txt fixes" puts the stack's own
        # table back and boots the game services under the events already held open.
        needs = ev.get("needsFiles")
        assert needs is None or (isinstance(needs, list) and needs and all(isinstance(d, str) for d in needs)), \
            "payloads/%s: events.needsFiles must be a non-empty list of stack files" % v
        assert (needs if manifest_has_events(man) else None) == PAYLOAD_EXPECT[v]["needsFiles"], \
            "payloads/%s: the events block needs %s, PAYLOAD_EXPECT says %s" \
            % (v, needs, PAYLOAD_EXPECT[v]["needsFiles"])
        for dst in needs or []:
            entries = [item for item in man.get("files", []) if item.get("dst") == dst]
            assert len(entries) == 1 and effective_stage(entries[0]) == "config" \
                and entries[0].get("md5") is not None, \
                "payloads/%s: events.needsFiles names %s, which no config entry of files[] installs with an md5 (a " \
                "txt_fix one can be reverted under events already held open)" % (v, dst)
        # ...and the condition table this payload installs ends none of the events it keeps open on a date of its
        # own (day_gate_problems)
        gates_checked = 0
        for item in man.get("files", []) if manifest_has_events(man) else []:
            if item.get("dst") == "server/data/txt/NewActivityCondData.txt":
                with open(os.path.join(payload_dir(v), item["src"]), "rb") as f:
                    gates = day_gate_problems(f.read(), gaa, PAYLOAD_EXPECT[v].get("dayGateKept") or [])
                assert not gates, "payloads/%s: %s ends an event the events block keeps open on a date of its own: " \
                                  "%s" % (v, item["src"], "; ".join(gates[:6]))
                gates_checked += 1
        assert gates_checked == 1 or "server/data/txt/NewActivityCondData.txt" not in (needs or []), \
            "payloads/%s: the condition table the events block needs was checked %d times" % (v, gates_checked)
        tpls = manifest_templates(v, man)
        validate_templates(tpls, payload_dir(v))
        # The saves block: its acceptFrom (each source with the fields a copy from it drops) is the one
        # PAYLOAD_EXPECT names, the version's server reads its own saves dropping nothing, and the schema it names
        # is one copy_save can follow (save_plan); a save_schema.json no saves block names is a payload nobody
        # described.
        saves = man.get("saves")
        problem = saves_payload_problem(v, man, PAYLOAD_EXPECT[v]["saves"])
        assert problem is None, "payloads/%s: %s" % (v, problem)
        if saves is not None:
            shipped_saves[v] = (man, save_plan(v, man)[0])
        if manifest_has_events(man):
            ok("events %s OK (%d open, %d closed; day gates of %d condition table(s) checked; needs %s)"
               % (v, len(gaa), len(others), gates_checked, ", ".join(needs or []) or "-"))
        else:
            print("selftest: no events block for", v, "(the stack keeps its own schedule)")
        ok("payload %s OK (%d files, %d dumps, %d sql, %d templates: %s; navmesh files bundled: %d; save schema: %s)"
           % (v, len(man.get("files", [])), len(man.get("mysql", [])), len(man.get("sql_events", [])),
              len(tpls), ", ".join(t["id"] for t in tpls) or "-", len(navmesh_bundle(v)),
              "reads the saves of %s" % ", ".join(sorted(saves["acceptFrom"])) if v in shipped_saves else "none"))
    # Every source a saves block names has a save schema of its own, each field a copy from it drops is one of
    # that source's saves and not of this version's, and each 64-bit field both schemas hold has one class in both
    # (a server that reads the other version's saves reads such a value as what it was written as); no client
    # string is claimed by two versions. Every shipped schema names the five stored messages (and
    # compile_save_schema holds each of its guid paths to the main save), each field that names another player and
    # that a copy drops (_GUID_DROP_PATHS) is a uid path of it or a map keyed by one, and the avatars' equip lists,
    # the team lists and the temporary avatar list are guid lists of it.
    def saves_cross_problems(shipped, plan_of):
        """What is wrong with the saves blocks of `shipped` ({version: (manifest, compiled schema)}) taken
        together: a source this agent does not know, or one without a save schema of its own (plan_of(source)
        -> save_plan's answer), a drop that is no field of the source's saves or one the target's still have, a
        64-bit field the two schemas class differently, a client prefix that names the client strings of another
        version's."""
        problems = []
        for v, (man_, plan_) in sorted(shipped.items()):
            for src, rule in sorted(man_["saves"]["acceptFrom"].items()):
                if src not in VERSIONS:
                    problems.append("%s: acceptFrom names %s, a version this agent does not know" % (v, src))
                    continue
                src_plan, src_why = plan_of(src)
                if src_plan is None:
                    problems.append("%s: acceptFrom names %s, which ships no save schema of its own (%s)"
                                    % (v, src, src_why or "no saves block"))
                    continue
                for path in rule["drop"]:
                    if src_plan.field_at(path) is None or plan_.field_at(path) is not None:
                        problems.append("%s: the drop %s of %s is no field of %s's saves that %s's lack"
                                        % (v, path, src, src, v))
                for key in sorted(set(src_plan.class64) & set(plan_.class64)):
                    if src_plan.class64[key] != plan_.class64[key]:
                        problems.append("%s: %s is a %s in the save schema of %s and a %s in this one"
                                        % (v, _schema_path_text(*key), src_plan.class64[key], src,
                                           plan_.class64[key]))
        prefixes = [(v, x) for v, (man_, _p) in sorted(shipped.items()) for x in man_["saves"]["clientPrefixes"]]
        for i, (v, x) in enumerate(prefixes):
            for w, y in prefixes[i + 1:]:
                if v != w and (x.startswith(y) or y.startswith(x)):
                    problems.append("the client prefix %s of %s and %s of %s name the same client strings"
                                    % (x, v, y, w))
        return problems

    assert saves_cross_problems(shipped_saves, save_plan) == [], saves_cross_problems(shipped_saves, save_plan)
    for v, (man_, plan_) in sorted(shipped_saves.items()):
        assert set(SAVE_SCHEMA_ROOTS) <= set(plan_.roots), (v, sorted(plan_.roots))
        with open(os.path.join(payload_dir(v), man_["saves"]["schema"]), "rb") as f:
            schema_ = json.loads(f.read().decode("utf-8"))
        uid_paths = set(e.get("path") for e in schema_["uidBound"] if e.get("class") == "uid")
        for p in sorted(_GUID_DROP_PATHS):
            dotted = _schema_path_text(SAVE_MAIN_ROOT, p)
            assert dotted in uid_paths or dotted + ".1" in uid_paths, \
                "payloads/%s: %s, a field a copy drops, is no uid path of the save schema nor a map keyed by one" \
                % (v, dotted)
        assert {(2, 1, 101, 2), (2, 5, 2, 1), (2, 17)} <= plan_.guid_list.get(SAVE_MAIN_ROOT, frozenset()), v
    # The shipped saves -- every template dump; the default save is the pre-gaa one -- through the schema walk of
    # their version: none holds a field its schema does not know or a field a copy drops; copied from uid 1 to
    # uid 2, the schema walk writes the bytes the generic walk writes (no value of another class carries the high
    # word 1); and copied as if they belonged to a uid that is also the high word of millisecond times they hold
    # (SHIPPED_TIME_UIDS: per shipped save, such a uid and how many of its times carry it -- the 64-bit values off
    # the guid paths that build/save_compat.py --saves lists), they come out as the uid-1 copy: every such time
    # kept and logged, where the generic walk rewrites each of them too. A version whose server reads them as they
    # are (its acceptFrom names theirs with nothing to drop) walks them the same way: its schema decodes them
    # whole and writes the bytes their own schema writes, every such time kept -- the real saves its schema is
    # held to, where its own payload ships none.
    SHIPPED_TIME_UIDS = {("1.6", "pre-gaa"): {392: 3}, ("1.6", "post-gaa"): {392: 4},
                         ("2.8", "pre-gaa"): {400: 6}, ("2.8", "post-gaa"): {400: 3, 416: 3}}
    walked, read_by = [], set()
    for v, (man_, plan_) in sorted(shipped_saves.items()):
        readers = [(w, plan_w) for w, (man_w, plan_w) in sorted(shipped_saves.items())
                   if w != v and (man_w["saves"]["acceptFrom"].get(v) or {}).get("drop") == []]
        for t in manifest_templates(v, man_):
            with open(os.path.join(payload_dir(v), t["sql"]), encoding="utf-8") as f:
                m = re.search(r"INSERT INTO `t_player_data_1`.*?VALUES\s*\(1,\s*'.*?(0x[0-9A-Fa-f]+)", f.read(), re.S)
            assert m, "no uid 1 save in %s %s" % (v, t["sql"])
            blob = bytes.fromhex(m.group(1)[2:])
            save_ = zlib.decompress(blob[4:]) if blob[:4] == b"ZLIB" else blob
            log_ = []
            assert _rewrite_save(plan_, save_, _NO_GUID_OWNER, _NO_GUID_OWNER, log_) == (save_, False) and not log_, \
                "the shipped %s %s save decodes on its schema with nothing to drop: %s" % (v, t["id"], log_[:3])
            ls_, lg_ = [], []
            s2 = _rewrite_save(plan_, save_, 1, 2, ls_)[0]
            n_ = sum(n for k, _p, n in ls_ if k in _GUID_REWRITE_KINDS)
            assert s2 == _guid_rewrite(save_, 1, 2, (), lg_)[0] and n_ > 0 \
                and n_ == sum(n for k, _p, n in lg_ if k in _GUID_REWRITE_KINDS), (v, t["id"], n_)
            assert not [e for e in ls_ if e[0] != "kept" and e[0] not in _GUID_REWRITE_KINDS] \
                and not [e for e in ls_ if e[0] == "kept"], (v, t["id"], "no value of another class has the high word 1")
            assert _rewrite_save(plan_, s2, 2, 1, [])[0] == save_, (v, t["id"], "the roundtrip")
            assert (v, t["id"]) in SHIPPED_TIME_UIDS, \
                "the shipped %s %s save has no row in SHIPPED_TIME_UIDS -- a save nobody described" % (v, t["id"])
            for uid_, times_ in sorted(SHIPPED_TIME_UIDS[(v, t["id"])].items()):
                owned = _rewrite_save(plan_, save_, 1, uid_, [])[0]
                lk_, lg2 = [], []
                assert _rewrite_save(plan_, owned, uid_, 2, lk_)[0] == s2, (v, t["id"], uid_, "every time kept")
                kept_ = [(p, n) for k, p, n in lk_ if k == "kept"]
                assert sum(n for _p, n in kept_) == times_ and all(
                    plan_.class64.get((SAVE_MAIN_ROOT, p)) == "time" for p, _n in kept_), (v, t["id"], uid_, kept_)
                assert _guid_rewrite(owned, uid_, 2, (), lg2)[0] != s2 and \
                    sum(n for k, _p, n in lg2 if k in _GUID_REWRITE_KINDS) == n_ + times_, \
                    (v, t["id"], uid_, "the generic walk rewrites the times as well")
            for w, plan_w in readers:
                read_by.add((v, w))
                log_ = []
                assert _rewrite_save(plan_w, save_, _NO_GUID_OWNER, _NO_GUID_OWNER, log_) == (save_, False) \
                    and not log_, "the shipped %s %s save decodes on the schema of %s: %s" % (v, t["id"], w, log_[:3])
                assert _rewrite_save(plan_w, save_, 1, 2, [])[0] == s2, (v, t["id"], w, "the uid-1 copy")
                for uid_, times_ in sorted(SHIPPED_TIME_UIDS[(v, t["id"])].items()):
                    lk_ = []
                    assert _rewrite_save(plan_w, _rewrite_save(plan_, save_, 1, uid_, [])[0], uid_, 2, lk_)[0] == s2 \
                        and sum(n for k, _p, n in lk_ if k == "kept") == times_, (v, t["id"], w, uid_, lk_[:3])
            walked.append("%s %s: %d guids%s%s" % (v, t["id"], n_, "".join(
                ", as uid %d %d times kept" % kv for kv in sorted(SHIPPED_TIME_UIDS[(v, t["id"])].items())),
                "".join(", the same on %s" % w for w, _p in readers)))
    shipped_ids = set((v, t["id"]) for v, (man_, _p) in shipped_saves.items() for t in manifest_templates(v, man_))
    assert all(key in shipped_ids for key in SHIPPED_TIME_UIDS if key[0] in shipped_saves), \
        "SHIPPED_TIME_UIDS names a save its version's payload does not ship"
    # every version that reads another's saves as they are walked each of them (PAYLOAD_EXPECT names the pairs)
    assert read_by == set((v, w) for w in shipped_saves for v, drop in PAYLOAD_EXPECT[w]["saves"]["acceptFrom"].items()
                          if v != w and v in shipped_saves and drop == [] and manifest_templates(v, shipped_saves[v][0])), \
        sorted(read_by)
    ok("save schemas of the payloads OK (%s: the saves block and the schema's sha256 as PAYLOAD_EXPECT says, every "
       "source with a schema of its own, each drop a field of the source's saves the target's lack, each 64-bit field "
       "of two schemas of one class, no client string claimed twice; the five stored messages, the co-op fields uid "
       "paths; the shipped saves: %s -- the schema walk writes the generic walk's bytes from uid 1, and keeps every "
       "time of the source uid's high word)"
       % (", ".join(sorted(shipped_saves)) or "none", "; ".join(walked) or "none"))
    # the build identity: one sha256 over the script and the payload files that came with it -- the same
    # for every copy of one agent, whatever a box added to its payloads folder since
    for rel, skipped in (("1.6/manifest.json", False), ("2.8/txt/a.txt", False), ("2.8/txt/x.zip", False),
                         ("stray.txt", False), ("1.6/sub/navmesh.json", False),
                         ("1.6/navmesh/navmesh.json", True), ("1.6/navmesh/NavMesh/scene_3.navmesh", True),
                         ("1.6/navmesh.zip", True), ("1.6/navmesh.zip.part", True), ("1.6/NAVMESH.ZIP", True),
                         ("1.6/navmesh.relic-old-12-34/navmesh.json", True), ("1.6/navmeshes.txt", True),
                         ("1.6/other.zip", True), ("1.6/Other.Zip.PART", True), ("archive.zip", True),
                         ("archive.part", True), ("1.6/.relic-navmesh-zip-refused", True),
                         ("1.6/.relic-navmesh-unpack/1.6/navmesh/navmesh.json", True), (".hidden", True),
                         ("2.8/__pycache__/x.pyc", True), ("2.8/txt/.keep", True), ("", True)):
        assert identity_skips(rel) is skipped, rel
    with tempfile.TemporaryDirectory() as td:
        script, pay = os.path.join(td, "gio_agent.py"), os.path.join(td, "payloads")
        script_bytes = b"print('agent')\n"

        def put(rel, data):
            p = os.path.join(pay, *rel.split("/"))
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "wb") as f:
                f.write(data)

        with open(script, "wb") as f:
            f.write(script_bytes)
        alone = build_identity(script, pay)
        assert alone == identity_digest(hashlib.sha256(script_bytes).hexdigest(), []), \
            "no payloads folder: the script alone"
        put("1.6/manifest.json", b"{}\n")
        put("2.8/txt/a.txt", b"a\tb\r\n")
        base = build_identity(script, pay)
        # the launcher's twin (AgentBuild.Identity) is held to the same two values by the `server` spike
        assert base == "05171038f1733a8dc16e8c26930e54c98ba6fb9e8493a529cc19204a81899149" != alone, base
        v2 = [("\ue000.txt", "11" * 32), ("\U0001f600.txt", "22" * 32), ("a/b.txt", "33" * 32)]
        assert identity_digest("00" * 32, v2) == identity_digest("00" * 32, v2[::-1]) \
            == "95eb3dec39190c3b824d39465af96c41fd0af87226cf28356c32dc8eefb25cb4", \
            "the lines are sorted by the path's UTF-8 bytes"
        # what a box adds beside the shipped files changes nothing ...
        for rel in ("1.6/navmesh/navmesh.json", "1.6/navmesh/NavMesh/scene_3.navmesh", "1.6/navmesh.zip",
                    "1.6/navmesh.zip.part", "1.6/.relic-navmesh-zip-refused",
                    "1.6/.relic-navmesh-unpack/1.6/navmesh/navmesh.json",
                    "1.6/navmesh.relic-old-12-34/navmesh.json", "archive.zip", "2.8/Other.ZIP",
                    "2.8/__pycache__/x.pyc"):
            put(rel, b"box")
            assert build_identity(script, pay) == base, rel
        # ... every byte, name and file that came with the agent does
        put("2.8/txt/a.txt", b"a\tb\n")
        assert build_identity(script, pay) != base, "a payload byte"
        put("2.8/txt/a.txt", b"a\tb\r\n")
        assert build_identity(script, pay) == base
        os.rename(os.path.join(pay, "2.8", "txt", "a.txt"), os.path.join(pay, "2.8", "txt", "b.txt"))
        assert build_identity(script, pay) != base, "a payload name"
        os.rename(os.path.join(pay, "2.8", "txt", "b.txt"), os.path.join(pay, "2.8", "txt", "a.txt"))
        put("2.8/txt/x.zip", b"shipped")
        assert build_identity(script, pay) != base, "below a version folder's own entries every name counts"
        os.remove(os.path.join(pay, "2.8", "txt", "x.zip"))
        with open(script, "ab") as f:
            f.write(b"#\n")
        assert build_identity(script, pay) not in (base, alone), "a script byte"
        # the agent that answers: the script as it was when the process started, the payload files as they are
        saved_build, saved_payload_dir = dict(_BUILD), PAYLOAD_DIR
        try:
            PAYLOAD_DIR = pay
            _BUILD.update(script=hashlib.sha256(script_bytes).hexdigest(), stamp=None, id="")
            assert agent_build() == base == agent_build(), "the started script counts, not the file's bytes since"
            put("2.8/txt/a.txt", b"another payload")
            assert agent_build() not in (base, alone, ""), "a payload file replaced under the running agent"
            PAYLOAD_DIR = os.path.join(td, "absent")
            assert agent_build() == alone
            PAYLOAD_DIR = None
            assert agent_build() == "", "a payloads folder that cannot be read: no identity, never an exception"
            PAYLOAD_DIR = pay
            _BUILD["script"] = ""
            assert agent_build() == "", "a script that could not be read at the start: no identity"
        finally:
            PAYLOAD_DIR = saved_payload_dir
            _BUILD.clear()
            _BUILD.update(saved_build)
    assert re.fullmatch(r"[0-9a-f]{64}", _BUILD["script"]), "this script's own sha256 is taken when it starts"
    ok("build identity OK (script + payload files; navmesh bundle, archives, dot-entries left out; "
       "the started script, the payloads as they are)")
    # template manifest validation refuses bad ids, duplicates and missing dumps
    with tempfile.TemporaryDirectory() as td:
        open(os.path.join(td, "a.sql"), "w").close()
        validate_templates([{"id": "pre-gaa", "label": "x", "sql": "a.sql", "md5": None}], td)
        for bad_list, why in (
                ([{"id": "Pre GAA", "label": "", "sql": "a.sql", "md5": None}], "id"),
                ([{"id": "fresh", "label": "", "sql": "a.sql", "md5": None}], "reserved"),
                ([{"id": "x", "label": "", "sql": "a.sql", "md5": None}] * 2, "duplicate"),
                ([{"id": "x", "label": "", "sql": "missing.sql", "md5": None}], "missing"),
                ([{"id": "x", "label": "", "sql": "a.sql", "md5": "00"}], "md5")):
            try:
                validate_templates(bad_list, td)
                raise AssertionError("validate_templates must refuse: " + why)
            except ValueError as e:
                assert why in str(e), (why, e)
    assert template_db_name("post-gaa") == "relic_tpl_post-gaa"
    ok("template manifest validation OK")

    # Navmesh payload (the pathfinding server's data files): the name grammar, the md5 list merge, the bundle
    # validation and the installer end to end -- over temp folders with a synthetic payload root, never the
    # real payload folder (which may or may not ship a bundle).
    import stat as _stat
    import struct
    for good in ("scene_9.navmesh", "scene_9_1001.navmesh", "scene_9_0_0.navmesh", "scene_9_-1_-1.navmesh",
                 "scene_3_1001_-1_0.navmesh", "scenepolygon_9_1_12345.navmesh"):
        assert NAVMESH_NAME_RE.match(good), good
    for bad in ("../scene_9.navmesh", "scene_9.navmesh.bak", "Scene_9.navmesh", "scene_9_a.navmesh", "scene_-9.navmesh",
                "scene_9_-1.navmesh", "scene_9_1_2_3_4.navmesh", "scenepolygon_9_1.navmesh", "scene_9.navmesh\n",
                "NavMesh/scene_9.navmesh", "scene_9 .navmesh", "scene_9.NavMesh", "",
                "scene_\u0669.navmesh"):  # an Arabic-Indic digit: `\d` is ASCII only, like the loader's integers
        assert not NAVMESH_NAME_RE.match(bad), bad
    ok("navmesh file names: the loader's five forms accepted, everything else refused (other scripts' digits too)")

    m1, m2, m3 = "a" * 32, "b" * 32, "c" * 32
    vendor = ("%s  ./NavMesh/scene_3_0_0.navmesh\n%s  ./NavMesh/scene_4_0_0.navmesh\n%s  ./server_res_version.txt\n"
              % (m1, m1, m3))
    # from nothing: our lines alone, LF, one newline at the end
    assert navmesh_md5_list_merge(None, [(m2, "scene_9_0_0.navmesh")]) == "%s  ./NavMesh/scene_9_0_0.navmesh\n" % m2
    assert navmesh_md5_list_merge("", [(m2, "scene_9_0_0.navmesh"), (m1, "scene_9_0_-1.navmesh")]) == \
        "%s  ./NavMesh/scene_9_0_0.navmesh\n%s  ./NavMesh/scene_9_0_-1.navmesh\n" % (m2, m1)
    assert navmesh_md5_list_merge(vendor, []) == vendor, "no entries: the text as it is"
    # appended when no line names anything outside NavMesh/ (no ./server_res_version.txt line) -- a missing
    # final newline is added first
    only_nav = "%s  ./NavMesh/scene_3_0_0.navmesh" % m1
    assert navmesh_md5_list_merge(only_nav, [(m2, "scene_9_0_0.navmesh")]) == \
        only_nav + "\n%s  ./NavMesh/scene_9_0_0.navmesh\n" % m2
    # inserted before ./server_res_version.txt, which stays last; the other lines keep their bytes and order
    merged = navmesh_md5_list_merge(vendor, [(m2, "scene_9_0_0.navmesh")])
    assert merged == ("%s  ./NavMesh/scene_3_0_0.navmesh\n%s  ./NavMesh/scene_4_0_0.navmesh\n"
                      "%s  ./NavMesh/scene_9_0_0.navmesh\n%s  ./server_res_version.txt\n" % (m1, m1, m2, m3)), merged
    # an existing line gets its md5 replaced in place -- whatever its spacing
    merged = navmesh_md5_list_merge(vendor, [(m2, "scene_4_0_0.navmesh")])
    assert merged == vendor.replace("%s  ./NavMesh/scene_4_0_0" % m1, "%s  ./NavMesh/scene_4_0_0" % m2), merged
    assert navmesh_md5_list_merge("%s\t./NavMesh/scene_4_0_0.navmesh\n" % m1, [(m2, "scene_4_0_0.navmesh")]) == \
        "%s\t./NavMesh/scene_4_0_0.navmesh\n" % m2
    # CRLF kept on the old lines and taken by the new one
    crlf = vendor.replace("\n", "\r\n")
    merged = navmesh_md5_list_merge(crlf, [(m2, "scene_9_0_0.navmesh")])
    assert merged == crlf.replace("%s  ./server_res_version.txt" % m3,
                                  "%s  ./NavMesh/scene_9_0_0.navmesh\r\n%s  ./server_res_version.txt" % (m2, m3)), merged
    # idempotent, LF and CRLF alike
    assert navmesh_md5_list_merge(merged, [(m2, "scene_9_0_0.navmesh")]) == merged
    lf_merged = navmesh_md5_list_merge(vendor, [(m2, "scene_9_0_0.navmesh"), (m3, "scene_3_0_0.navmesh")])
    assert navmesh_md5_list_merge(lf_merged, [(m2, "scene_9_0_0.navmesh"), (m3, "scene_3_0_0.navmesh")]) == lf_merged
    # unrelated lines (a comment, a blank line, a file under another folder) are kept where they are, the new
    # lines go before the first line that names something outside NavMesh/, trailing empty lines go
    odd = "# a note\n\n%s  ./other/x.bin\n%s  ./NavMesh/scene_3_0_0.navmesh\n%s  ./server_res_version.txt\n\n\n" % (m1, m1, m3)
    merged = navmesh_md5_list_merge(odd, [(m2, "scene_9_0_0.navmesh"), (m3, "scene_3_0_0.navmesh")])
    assert merged == ("# a note\n\n%s  ./NavMesh/scene_9_0_0.navmesh\n%s  ./other/x.bin\n%s  ./NavMesh/scene_3_0_0.navmesh\n"
                      "%s  ./server_res_version.txt\n" % (m2, m1, m3, m3)), merged
    ok("navmesh md5 list merge OK (from nothing, appended, before server_res_version.txt, replaced in place, "
       "CRLF kept, idempotent, unrelated lines kept, one final newline)")

    with tempfile.TemporaryDirectory() as td:
        proot = os.path.join(td, "payloads")
        nav = os.path.join(proot, "2.8", "navmesh")
        os.makedirs(os.path.join(nav, "NavMesh"))

        def blob(scene, tail=b""):
            return struct.pack("<ii", scene, 0) + bytes(120) + tail

        def entry(name, data, scene, **over):
            with open(os.path.join(nav, "NavMesh", name), "wb") as f:
                f.write(data)
            e = {"name": name, "size": len(data), "md5": hashlib.md5(data).hexdigest(),
                 "sha256": hashlib.sha256(data).hexdigest(), "scene": scene, "tiles": 1, "block": [0, 0]}
            e.update(over)
            return e

        def write_manifest(files, **top):
            doc = {"format": 1, "version": "2.8", "files": files, "note": "selftest"}
            doc.update(top)
            with open(os.path.join(nav, NAVMESH_MANIFEST), "w", encoding="utf-8") as f:
                json.dump(doc, f)

        good1 = entry("scene_9_0_0.navmesh", blob(9), 9)
        good2 = entry("scene_9_0_-1.navmesh", blob(9, b"\x01"), 9)
        corrupt = entry("scene_1071.navmesh", blob(1071), 1071, sha256="0" * 64)  # the file is fine, its entry is not
        wrong = entry("scene_20127.navmesh", blob(20128), 20127)                    # the header names another scene
        write_manifest([good1, good2, corrupt, wrong])
        # validation: the wrong header is left out (one problem); the wrong sha256 is NOT -- the installer's
        entries, problems = _navmesh_read_bundle("2.8", proot)
        assert [e["name"] for e in entries] == [good1["name"], good2["name"], corrupt["name"]], entries
        assert entries[0]["src"] == os.path.join(nav, "NavMesh", good1["name"]) and entries[2]["scene"] == 1071
        assert len(problems) == 1 and "scene_20127.navmesh" in problems[0] and "20128" in problems[0], problems
        # a size that is off, a file the manifest names but the payload lacks: that entry only
        write_manifest([good1, dict(good2, size=good2["size"] + 1), dict(good1, name="scene_5.navmesh")])
        entries, problems = _navmesh_read_bundle("2.8", proot)
        assert [e["name"] for e in entries] == [good1["name"]] and len(problems) == 2, (entries, problems)
        assert "bytes" in problems[0] and "not in the payload" in problems[1], problems
        # the once-only WARNING: a status poll reads the bundle again and again
        write_manifest([good1, good2, corrupt, wrong])
        real_log, logged = globals()["log_line"], []
        globals()["log_line"] = logged.append
        try:
            assert len(navmesh_bundle("2.8", proot)) == 3 and len(navmesh_bundle("2.8", proot)) == 3
            assert len(logged) == 1 and "WARNING" in logged[0] and "scene_20127.navmesh" in logged[0], logged
            # a malformed manifest: [] and ONE WARNING, however often it is read
            write_manifest("not a list")
            assert navmesh_bundle("2.8", proot) == [] and navmesh_bundle("2.8", proot) == []
            assert len(logged) == 2 and "`files` is not a list" in logged[1], logged
            # another game version's manifest in this folder, a name the server would not load, a name twice,
            # an entry without its hashes, not even JSON: refused whole, one WARNING each
            write_manifest([good1], version="1.6")
            assert navmesh_bundle("2.8", proot) == [] and len(logged) == 3 and "version 1.6" in logged[2], logged
            write_manifest([dict(good1, name="../scene_9.navmesh")])
            assert navmesh_bundle("2.8", proot) == [] and len(logged) == 4 and "would not load" in logged[3], logged
            write_manifest([good1, good1])
            assert navmesh_bundle("2.8", proot) == [] and len(logged) == 5 and "twice" in logged[4], logged
            write_manifest([dict(good1, md5="zz")])
            assert navmesh_bundle("2.8", proot) == [] and len(logged) == 6 and "valid size, md5" in logged[5], logged
            with open(os.path.join(nav, NAVMESH_MANIFEST), "w", encoding="utf-8") as f:
                f.write("{not json")
            assert navmesh_bundle("2.8", proot) == [] and len(logged) == 7 and "cannot be read" in logged[6], logged
            # another format, or no folder at all: no bundle, silently
            write_manifest([good1], format=2)
            assert navmesh_bundle("2.8", proot) == [] and navmesh_bundle("1.6", proot) == [] and len(logged) == 7, logged
            # the problem gone and back: logged again
            write_manifest([good1, good2, corrupt, wrong])
            assert len(navmesh_bundle("2.8", proot)) == 3 and len(logged) == 8 and "scene_20127" in logged[7], logged
            # a scene-less entry is checked for nothing but its bytes; a bool is not a scene id
            write_manifest([dict(good1, scene=None), dict(good2, scene=True)])
            assert navmesh_bundle("2.8", proot) == [] and len(logged) == 9, logged
            write_manifest([dict(good1, scene=None)])
            assert [e["scene"] for e in navmesh_bundle("2.8", proot)] == [None] and len(logged) == 9, logged
        finally:
            globals()["log_line"] = real_log
        ok("navmesh bundle validation OK (names, sizes, scene header, hashes well-formed; sha256 left to the "
           "installer; another version / format / no folder; every problem one WARNING, logged again once gone)")

        # the installer, over a stack that has the vendor's list (server_res_version.txt last) and -- where
        # one bundled file goes -- a file of its own
        write_manifest([good1, good2, corrupt, wrong])
        stack = os.path.join(td, "stack")
        res = os.path.join(stack, "server", "res")
        os.makedirs(os.path.join(res, "NavMesh"))
        list_path = os.path.join(res, NAVMESH_LIST)
        with open(list_path, "w", encoding="utf-8", newline="") as f:
            f.write(vendor)
        foreign = os.path.join(res, "NavMesh", good2["name"])
        with open(foreign, "wb") as f:
            f.write(b"vendor bytes")
        if os.name == "posix":
            os.chmod(foreign, 0o664)
        saved_dir = VERSIONS["2.8"]["dir"]
        VERSIONS["2.8"]["dir"] = stack
        try:
            j = _Job()
            r = install_navmesh("2.8", j, payload_root=proot)
            assert r == {"installed": 2, "kept": 0, "skipped": 1, "listUpdated": True}, r
            for e in (good1, good2):
                with open(os.path.join(res, "NavMesh", e["name"]), "rb") as f:
                    assert hashlib.sha256(f.read()).hexdigest() == e["sha256"], e["name"]
            with open(foreign + ".orig", "rb") as f:
                assert f.read() == b"vendor bytes", "the stack's own file is kept as .orig"
            # the marker: the name the agent CREATED (good1), one per line, LF -- never a replaced file's (good2)
            marker = os.path.join(res, "NavMesh", NAVMESH_MARKER)
            with open(marker, "r", encoding="utf-8", newline="") as f:
                assert f.read() == good1["name"] + "\n", "the marker holds the created name alone"
            assert not os.path.exists(os.path.join(res, "NavMesh", good1["name"] + ".orig")), "a created file: no .orig"
            if os.name == "posix":
                assert _stat.S_IMODE(os.stat(marker).st_mode) == 0o644, "the marker is a new stack file: 0644"
                assert _stat.S_IMODE(os.stat(foreign + ".orig").st_mode) == 0o664, "the .orig keeps the replaced file's mode"
            assert any(l.endswith("; the stack's own copy kept as .orig)") and good2["name"] in l for l in j.lines), j.lines
            assert any(l.endswith(" MB)") and good1["name"] in l for l in j.lines), j.lines
            assert not os.path.exists(os.path.join(res, "NavMesh", corrupt["name"])), "a skipped file is not copied"
            assert not os.path.exists(os.path.join(res, "NavMesh", wrong["name"])), "a refused entry is not copied"
            assert not any(n.endswith(".tmp") for n in os.listdir(os.path.join(res, "NavMesh"))), "no temp file left"
            if os.name == "posix":
                assert _stat.S_IMODE(os.stat(foreign).st_mode) == 0o664, "a replaced file keeps its mode"
                assert _stat.S_IMODE(os.stat(os.path.join(res, "NavMesh", good1["name"])).st_mode) == 0o644, \
                    "a new file is 0644"
            with open(list_path, "r", encoding="utf-8", newline="") as f:
                text = f.read()
            lines = text.split("\n")
            assert text.endswith("./server_res_version.txt\n") and text.count("\n") == 5, text
            assert lines[0:2] == vendor.split("\n")[0:2], "the vendor's lines are kept"
            assert "%s  ./NavMesh/%s" % (good1["md5"], good1["name"]) in lines, text
            assert "%s  ./NavMesh/%s" % (good2["md5"], good2["name"]) in lines, text
            assert not any(corrupt["name"] in l for l in lines), "a skipped file is never registered"
            assert any(l.startswith("WARNING: Navmesh: scene_1071.navmesh does not match the sha256") for l in j.lines), j.lines
            assert any(l.startswith("WARNING: Navmesh: scene_20127.navmesh starts with scene id 20128") for l in j.lines), j.lines
            assert j.lines[-1].startswith("Navmesh: 3 bundled files for 2.8 -- installed 2, already in place 0, skipped 1; "
                                          "md5 list updated"), j.lines[-1]
            # the status: by size, no hashing, the corrupt entry counted as bundled but not installed; stackFiles =
            # the navmesh names in the stack's own folder, whoever put them there (the .orig and the marker are none)
            st = navmesh_status("2.8", proot)
            assert st == {"vendorList": True, "bundled": 3, "installed": 2, "scenes": [9, 1071], "stackFiles": 2,
                          "archive": None, "data": None}, st
            assert stack_navmesh_files("2.8") == 2 and stack_navmesh_files("0.0") == 0, \
                "one listing of the stack's folder; a version nobody knows: 0, never an error"
            # a second run: nothing to do, the list not rewritten (same inode, same mtime)
            before = os.stat(list_path)
            j2 = _Job()
            r = install_navmesh("2.8", j2, payload_root=proot)
            assert r == {"installed": 0, "kept": 2, "skipped": 1, "listUpdated": False}, r
            after = os.stat(list_path)
            assert (before.st_mtime_ns, before.st_ino) == (after.st_mtime_ns, after.st_ino), "an unchanged list is not rewritten"
            assert j2.lines[-1].startswith("Navmesh: 3 bundled files for 2.8 -- installed 0, already in place 2, skipped 1; "
                                           "md5 list unchanged"), j2.lines[-1]
            # nothing to register (every bundled file skipped): the list is not touched -- not even to give it
            # the final newline a merge would
            write_manifest([corrupt])
            with open(list_path, "r", encoding="utf-8", newline="") as f:
                kept_text = f.read()
            with open(list_path, "w", encoding="utf-8", newline="") as f:
                f.write(kept_text.rstrip("\n"))
            r = install_navmesh("2.8", _Job(), payload_root=proot)
            assert r == {"installed": 0, "kept": 0, "skipped": 1, "listUpdated": False}, r
            with open(list_path, "r", encoding="utf-8", newline="") as f:
                assert f.read() == kept_text.rstrip("\n"), "a list with nothing to register is left as it is"
            with open(list_path, "w", encoding="utf-8", newline="") as f:
                f.write(kept_text)
            # newer builds replace ours and their lines follow. good1 was CREATED by the agent (in the marker):
            # its newer build gets no .orig; good2 replaced the stack's own file (not in the marker): the FIRST
            # .orig stays
            good1b = entry(good1["name"], blob(9, b"\x03"), 9)
            good2b = entry(good2["name"], blob(9, b"\x02"), 9)
            write_manifest([good1b, good2b, corrupt, wrong])
            jb = _Job()
            r = install_navmesh("2.8", jb, payload_root=proot)
            assert r == {"installed": 2, "kept": 0, "skipped": 1, "listUpdated": True}, r
            with open(foreign + ".orig", "rb") as f:
                assert f.read() == b"vendor bytes", ".orig is written once"
            assert not os.path.exists(os.path.join(res, "NavMesh", good1["name"] + ".orig")), "our own earlier build: no .orig"
            with open(marker, "r", encoding="utf-8", newline="") as f:
                assert f.read() == good1["name"] + "\n", "a replacement changes the marker in no way"
            assert any(l.endswith("; an earlier build of ours replaced)") and good1["name"] in l for l in jb.lines), jb.lines
            assert any(l.endswith("; replaced, the earlier .orig kept)") and good2["name"] in l for l in jb.lines), jb.lines
            with open(list_path, "r", encoding="utf-8", newline="") as f:
                text2 = f.read()
            assert "%s  ./NavMesh/%s" % (good2b["md5"], good2b["name"]) in text2 and good2["md5"] not in text2, text2
            assert "%s  ./NavMesh/%s" % (good1b["md5"], good1b["name"]) in text2 and good1["md5"] not in text2, text2
            assert text2.endswith("./server_res_version.txt\n") and text2.count("\n") == 5, text2
            # the stack's own file back at good2's name (a re-extracted archive): replaced again, the first .orig
            # kept, the name still not in the marker
            with open(foreign, "wb") as f:
                f.write(b"vendor bytes again")
            r = install_navmesh("2.8", _Job(), payload_root=proot)
            assert r == {"installed": 1, "kept": 1, "skipped": 1, "listUpdated": False}, r
            with open(foreign + ".orig", "rb") as f:
                assert f.read() == b"vendor bytes", "an existing .orig is never overwritten"
            with open(marker, "r", encoding="utf-8", newline="") as f:
                assert f.read() == good1["name"] + "\n", "a replaced file of the stack's own is never recorded"
            # the manifest's md5 is a claim: a bundled file whose real md5 is another is skipped like a sha256
            # mismatch -- the list may only ever name an md5 that is true for the file -- while the good entries
            # are installed; a file already in place with the right sha256 but a wrong md5 in its entry is
            # skipped too (not kept, not re-registered) and its line keeps the md5 that is true
            good3 = entry("scene_1073.navmesh", blob(1073), 1073)
            badmd5 = entry("scene_1072.navmesh", blob(1072), 1072, md5="0" * 32)
            write_manifest([good1b, good2b, good3, badmd5])
            jm = _Job()
            r = install_navmesh("2.8", jm, payload_root=proot)
            assert r == {"installed": 1, "kept": 2, "skipped": 1, "listUpdated": True}, r
            assert not os.path.exists(os.path.join(res, "NavMesh", badmd5["name"])), "a wrong md5: not copied"
            assert any(l.startswith("WARNING: Navmesh: scene_1072.navmesh does not match the md5 of its entry in navmesh.json")
                       for l in jm.lines), jm.lines
            with open(list_path, "r", encoding="utf-8", newline="") as f:
                text_m = f.read()
            assert "%s  ./NavMesh/%s" % (good3["md5"], good3["name"]) in text_m, text_m
            assert "0" * 32 not in text_m and badmd5["name"] not in text_m, text_m
            with open(marker, "r", encoding="utf-8", newline="") as f:
                assert f.read() == "%s\n%s\n" % (good3["name"], good1["name"]), "the created names, sorted"
            write_manifest([dict(good3, md5="f" * 32), good1b])
            jm2 = _Job()
            r = install_navmesh("2.8", jm2, payload_root=proot)
            assert r == {"installed": 0, "kept": 1, "skipped": 1, "listUpdated": False}, r
            assert any(l.startswith("WARNING: Navmesh: scene_1073.navmesh does not match the md5 of its entry") for l in jm2.lines), \
                jm2.lines
            with open(list_path, "r", encoding="utf-8", newline="") as f:
                assert f.read() == text_m, "a kept file with a wrong md5 in its entry: its line keeps the md5 that is true"
            # the marker is read tolerant: bytes that are no UTF-8, CRLF, blanks and lines that are no navmesh
            # name are ignored, a missing marker or a folder in its place is no name at all; a rewrite drops them
            with open(marker, "wb") as f:
                f.write(b"\xff\xfe\r\n\r\n  scene_9_0_0.navmesh \r\nnot a name\n../scene_1.navmesh\nscene_1073.navmesh")
            assert _navmesh_marker_read(os.path.join(res, "NavMesh")) == {good1["name"], good3["name"]}
            assert _navmesh_marker_read(os.path.join(td, "nowhere")) == set()
            os.makedirs(os.path.join(td, "mdir", NAVMESH_MARKER))
            assert _navmesh_marker_read(os.path.join(td, "mdir")) == set()
            _navmesh_marker_write(os.path.join(res, "NavMesh"), _navmesh_marker_read(os.path.join(res, "NavMesh")))
            with open(marker, "r", encoding="utf-8", newline="") as f:
                assert f.read() == "%s\n%s\n" % (good3["name"], good1["name"]), "rewritten clean"
            write_manifest([good1b, good2b, corrupt, wrong])
            # no list at all (seen on a 2.8 stack that was extracted without one): created with our lines alone,
            # 0644
            os.remove(list_path)
            st = navmesh_status("2.8", proot)
            assert st == {"vendorList": False, "bundled": 3, "installed": 2, "scenes": [9, 1071], "stackFiles": 3,
                          "archive": None, "data": None}, st
            j3 = _Job()
            r = install_navmesh("2.8", j3, payload_root=proot)
            assert r == {"installed": 0, "kept": 2, "skipped": 1, "listUpdated": True}, r
            with open(list_path, "r", encoding="utf-8", newline="") as f:
                text3 = f.read()
            assert text3 == "%s  ./NavMesh/%s\n%s  ./NavMesh/%s\n" % (good1b["md5"], good1b["name"],
                                                                      good2b["md5"], good2b["name"]), text3
            assert j3.lines[-1].endswith("md5 list created (the pathfinding server reads it when it boots)"), j3.lines[-1]
            if os.name == "posix":
                assert _stat.S_IMODE(os.stat(list_path).st_mode) == 0o644
            # no bundle: one line at a provision, silence at a start, nothing touched
            shutil.rmtree(nav)
            before_names = sorted(os.listdir(os.path.join(res, "NavMesh")))
            j4 = _Job()
            assert install_navmesh("2.8", j4, payload_root=proot) == {"installed": 0, "kept": 0, "skipped": 0,
                                                                    "listUpdated": False}
            assert j4.lines == ["Navmesh: no bundled files for 2.8"], j4.lines
            j5 = _Job()
            install_navmesh("2.8", j5, payload_root=proot, report_empty=False)
            assert j5.lines == [], j5.lines
            assert sorted(os.listdir(os.path.join(res, "NavMesh"))) == before_names
            assert navmesh_status("2.8", proot) == {"vendorList": True, "bundled": 0, "installed": 0, "scenes": [],
                                                    "stackFiles": 3, "archive": None, "data": None}
            # a failure inside is one WARNING line and a result, never an exception: NavMesh is a FILE here
            os.makedirs(os.path.join(nav, "NavMesh"))
            good1 = entry(good1["name"], blob(9), 9)
            write_manifest([good1])
            shutil.rmtree(os.path.join(res, "NavMesh"))
            with open(os.path.join(res, "NavMesh"), "w", encoding="utf-8") as f:
                f.write("in the way")
            j6 = _Job()
            r = install_navmesh("2.8", j6, payload_root=proot)
            assert r == {"installed": 0, "kept": 0, "skipped": 0, "listUpdated": False}, r
            assert len(j6.lines) == 1 and j6.lines[0].startswith("WARNING: Navmesh: the bundled files could not be installed"), \
                j6.lines
            assert navmesh_status("2.8", proot) == {"vendorList": True, "bundled": 1, "installed": 0, "scenes": [9],
                                                    "stackFiles": 0, "archive": None, "data": None}
        finally:
            VERSIONS["2.8"]["dir"] = saved_dir
        # the three hooks are in the source: a provision installs in every mode and says so without a bundle, a
        # start installs before the staged up and is silent without one, and so does the pathfinding enable on a
        # running stack right before it boots the service
        with open(os.path.abspath(__file__), encoding="utf-8") as f:
            agent_src = f.read()
        prov_src = agent_src[agent_src.index("\ndef do_provision("):agent_src.index("\ndef needs_provision(")]
        start_src = agent_src[agent_src.index("\ndef do_start("):agent_src.index("\ndef do_stop(")]
        pf_src = agent_src[agent_src.index("\ndef reconcile_pathfinding("):agent_src.index("\ndef do_pathfinding(")]
        assert prov_src.count("install_navmesh(version, job)") == 1 and \
            prov_src.index("install_files(version, job, stages)") < prov_src.index("install_navmesh(version, job)") < \
            prov_src.index('"up", "-d", "mysql", "redis"'), "do_provision installs the navmesh files after the payload files, before mysql"
        assert start_src.count("install_navmesh(version, job, report_empty=False)") == 1 and \
            start_src.index("ensure_exec_bits(version, job)") < start_src.index("install_navmesh(") < \
            start_src.index('"up", "-d", "mysql", "redis"'), "do_start installs the navmesh files before the staged up"
        assert pf_src.count("install_navmesh(version, job, report_empty=False)") == 1 and \
            pf_src.index("tweaks_before_boot(version, job)") < pf_src.index("install_navmesh(") < \
            pf_src.index('"up", "-d", "--no-deps", PATHFINDING_SERVICE'), \
            "reconcile_pathfinding installs the navmesh files right before it boots the pathfinding server"
    ok("navmesh install OK (durable copies, .orig once and only for a file the agent did not create, the created "
       "names in .relic-navmesh (read tolerant), an entry whose md5 is not the file's skipped, modes kept / 0644, the "
       "md5 list merged with server_res_version.txt last, created when absent, not rewritten when unchanged, a skipped "
       "file never registered, status by size, no bundle = one line at a provision only, a failure = one WARNING, the "
       "three hooks)")

    # Navmesh archives: a zip in the payloads folder (or payloads/<v>/) adopted as payloads/<v>/navmesh/ --
    # once per sha256 (the marker), a newer one replaces the folder, what does not validate is refused once
    # and recorded; the route's 400s; the download job on a faked _fetch_to_file.
    import zipfile  # a later block imports it locally too, which makes the name local to this function
    g = globals()
    faked_z = ("PAYLOAD_DIR", "log_line", "_fetch_to_file", "running_projects", "start_job", "TOKEN", "NAVMESH_ZIP_MAX",
               "_navmesh_zip_unpack", "adopt_navmesh_archives", "is_bootstrapped", "pathfinding_enabled", "stack_up",
               "dead_services", "internal_change_pending", "reconcile_pathfinding")
    saved_z = {k: g[k] for k in faked_z}
    saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
    saved_sleep = time.sleep
    with tempfile.TemporaryDirectory() as td:
        try:
            proot = os.path.join(td, "payloads")
            os.makedirs(os.path.join(proot, "2.8"))
            logged = []
            g.update({"PAYLOAD_DIR": proot, "log_line": lambda m: logged.append(str(m)),
                      "running_projects": lambda: ([], None), "TOKEN": "selftest-token"})
            for v_ in VERSIONS:
                VERSIONS[v_]["dir"], VERSIONS[v_]["project"] = "", ""
            nav28 = os.path.join(proot, "2.8", "navmesh")

            def nav_blob(scene, tail=b""):
                return struct.pack("<ii", scene, 0) + bytes(120) + tail

            def make_zip(path, version="2.8", files=None, extra=None, manifest=True, version_in=None, bad_sha=False,
                         mtime=None, corrupt=False, stored=None):
                """files = [(name, data, scene)]; extra = [(member name, bytes)] written as they are; corrupt = the
                stored bytes of the first file flipped on disk, so the member's CRC does not match its bytes;
                stored = (member name, the name the archive stores instead): the name's bytes patched in the file
                itself -- in the member's local header and in the central directory -- so what the zip stores is
                exactly that, whatever the writer of this system would make of the name."""
                files = files if files is not None else [("scene_9_0_0.navmesh", nav_blob(9), 9)]
                doc = {"format": 1, "version": version_in or version, "files": [], "note": "selftest"}
                for name, data, scene in files:
                    doc["files"].append({"name": name, "size": len(data), "md5": hashlib.md5(data).hexdigest(),
                                         "sha256": ("0" * 64) if bad_sha else hashlib.sha256(data).hexdigest(),
                                         "scene": scene})
                with zipfile.ZipFile(path, "w", zipfile.ZIP_STORED if corrupt else zipfile.ZIP_DEFLATED) as zf:
                    if manifest:
                        zf.writestr(version + "/" + NAVMESH_MANIFEST, json.dumps(doc))
                    for name, data, scene in files:
                        zf.writestr(version + "/NavMesh/" + name, data)
                    for mname, data in (extra or []):
                        # the name as given: ZipInfo's constructor would strip a leading `/` and turn the
                        # platform's separator into `/`, and these members are here to carry exactly that
                        zi = zipfile.ZipInfo("placeholder", date_time=(2020, 1, 1, 0, 0, 0))
                        zi.filename = mname
                        zf.writestr(zi, data)
                if corrupt:
                    with open(path, "rb") as f:
                        raw = bytearray(f.read())
                    at = raw.find(files[0][1])  # stored, so the member's bytes are in the file as they are
                    assert at > 0, "the stored member must be findable"
                    raw[at + 8] ^= 0xFF
                    with open(path, "wb") as f:
                        f.write(raw)
                if stored is not None:
                    was, now = (n.encode("ascii") for n in stored)
                    assert len(was) == len(now), "a stored name is patched in place: the same length"
                    with open(path, "rb") as f:
                        raw = f.read()
                    assert raw.count(was) == 2, "the name in the local header and in the central directory"
                    with open(path, "wb") as f:
                        f.write(raw.replace(was, now))
                if mtime is not None:
                    os.utime(path, (mtime, mtime))
                return path

            def folder_names():
                try:
                    return sorted(os.listdir(os.path.join(nav28, "NavMesh")))
                except OSError:
                    return None

            t0 = time.time() - 100
            # (a) adoption from the payloads folder itself: the folder, the marker, one line
            z1 = make_zip(os.path.join(proot, "relic-navmesh-2.8.zip"), mtime=t0)
            r = adopt_navmesh_archives("2.8")
            assert r and r["adopted"] is True and r["files"] == 1 and r["archive"] == "relic-navmesh-2.8.zip" and \
                r["sha256"] == _file_sha256(z1), r
            assert folder_names() == ["scene_9_0_0.navmesh"] and os.path.isfile(os.path.join(nav28, NAVMESH_MANIFEST))
            rec = _navmesh_zip_marker_read(os.path.join(nav28, NAVMESH_ZIP_MARKER))
            assert rec and rec["sha256"] == _file_sha256(z1) and rec["name"] == "relic-navmesh-2.8.zip" and \
                re.match(r"^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d$", rec["adoptedAt"]) and rec["refused"] is False, rec
            assert len(logged) == 1 and "adopted relic-navmesh-2.8.zip (1 file" in logged[0] and "WARNING" not in logged[0], logged
            assert os.path.isfile(z1), "the zip stays where it was put"
            assert not os.path.exists(os.path.join(proot, "2.8", ".relic-navmesh-unpack")) and \
                not os.path.exists(nav28 + ".relic-old")
            assert len(navmesh_bundle("2.8")) == 1 and adopt_navmesh_archives("1.6") is None, "not 1.6's archive"
            # (b) idempotent through the marker: nothing done, nothing said
            r = adopt_navmesh_archives("2.8")
            assert r["adopted"] is False and r["known"] is True and r["files"] == 1 and len(logged) == 1, (r, logged)
            # /status: the marker, nothing raised without a stack folder either
            VERSIONS["2.8"]["dir"] = os.path.join(td, "stack28")
            st_ = navmesh_status("2.8")
            assert st_["archive"] == {"name": "relic-navmesh-2.8.zip", "sha256": rec["sha256"], "adoptedAt": rec["adoptedAt"]} \
                and st_["bundled"] == 1 and st_["vendorList"] is False, st_
            VERSIONS["2.8"]["dir"] = ""
            assert navmesh_status("2.8")["archive"] == st_["archive"]
            # (c) a NEWER zip in payloads/2.8/ replaces the folder (two files; the old one's file is gone)
            z2 = make_zip(os.path.join(proot, "2.8", "newer.zip"), mtime=t0 + 10,
                          files=[("scene_9_0_-1.navmesh", nav_blob(9, b"\x01"), 9), ("scene_20133.navmesh", nav_blob(20133), 20133)],
                          extra=[("2.8/NavMesh/notes.txt", b"ignored"), ("README.md", b"ignored too"),
                                 ("2.8/NavMesh/scene_9_7_7.navmesh", nav_blob(9))])  # unlisted: dropped
            with open(os.path.join(nav28, "stray.txt"), "w") as f:
                f.write("goes with the old folder")
            r = adopt_navmesh_archives("2.8")
            assert r["adopted"] is True and r["files"] == 2 and r["archive"] == "newer.zip", r
            assert folder_names() == ["scene_20133.navmesh", "scene_9_0_-1.navmesh"], folder_names()
            assert not os.path.exists(os.path.join(nav28, "stray.txt")) and not os.path.exists(nav28 + ".relic-old")
            assert _navmesh_zip_marker_read(os.path.join(nav28, NAVMESH_ZIP_MARKER))["sha256"] == _file_sha256(z2)
            # the older archive beside it is named once per process (the modification time decides), then the adoption
            assert len(logged) == 3 and "in place of the earlier payload" in logged[2] and \
                "newer.zip is the newest archive of 2.8" in logged[1] and "relic-navmesh-2.8.zip not looked at" in logged[1] \
                and "WARNING" not in logged[1], logged
            assert adopt_navmesh_archives("2.8")["known"] is True and len(logged) == 3, "said once per process"
            assert os.path.isfile(z1) and os.path.isfile(z2)
            marker_before = read_text(os.path.join(nav28, NAVMESH_ZIP_MARKER))
            # a swap a crash cut in two: the folder renamed aside, nothing in its place -> put back first, one line;
            # a stale aside beside a folder that is in place is removed
            aside = os.path.join(proot, "2.8", _NAVMESH_ASIDE_PREFIX + "-1-1")
            os.rename(nav28, aside)
            r = adopt_navmesh_archives("2.8")
            assert r["known"] is True and r["files"] == 2 and folder_names() == ["scene_20133.navmesh", "scene_9_0_-1.navmesh"] \
                and not os.path.exists(aside) and len(logged) == 4 and "put back as payloads/2.8/navmesh/" in logged[3], (r, logged[-1])
            assert read_text(os.path.join(nav28, NAVMESH_ZIP_MARKER)) == marker_before
            os.makedirs(os.path.join(aside, "NavMesh"))
            assert adopt_navmesh_archives("2.8")["known"] is True and not os.path.exists(aside) and len(logged) == 4
            # a failure of THIS box while unpacking (disk, permissions): one WARNING, NO refusal record, the folder as
            # it was, and the same archive is looked at again next time
            z3 = make_zip(os.path.join(proot, "2.8", "later.zip"), mtime=t0 + 15,
                          files=[("scene_9_1_1.navmesh", nav_blob(9, b"\x03"), 9)])
            refused_path = os.path.join(proot, "2.8", NAVMESH_ZIP_REFUSED)

            def unpack_fails(path, version, tmp_root):
                os.makedirs(os.path.join(tmp_root, version, "navmesh", "NavMesh"))
                raise OSError(28, "No space left on device")

            g["_navmesh_zip_unpack"] = unpack_fails
            n_log = len(logged)
            r = adopt_navmesh_archives("2.8")
            assert r["adopted"] is False and r["known"] is False and r["local"] is True and \
                r["problem"] == "could not be looked at ([Errno 28] No space left on device)", r
            assert len(logged) == n_log + 2 and "WARNING: Navmesh: later.zip could not be looked at (" in logged[-1] \
                and "looked at again next time" in logged[-1] and "refused" not in logged[-1] \
                and "later.zip is the newest archive of 2.8" in logged[-2], logged[-2:]
            assert not os.path.exists(refused_path) and folder_names() == ["scene_20133.navmesh", "scene_9_0_-1.navmesh"] \
                and not os.path.exists(os.path.join(proot, "2.8", ".relic-navmesh-unpack")), "no record, nothing changed"
            g["_navmesh_zip_unpack"] = saved_z["_navmesh_zip_unpack"]
            with open(os.path.join(proot, "2.8", ".relic-navmesh-unpack"), "w") as f:
                f.write("a stray file at the temp folder's name")
            r = adopt_navmesh_archives("2.8")
            assert r["adopted"] is True and r["files"] == 1 and folder_names() == ["scene_9_1_1.navmesh"], r
            assert len(logged) == n_log + 3 and "adopted later.zip" in logged[-1], logged[-1]
            # ...and a manifest that is not JSON is the ARCHIVE's problem: refused and recorded
            with zipfile.ZipFile(os.path.join(proot, "2.8", "nojson.zip"), "w") as zf:
                zf.writestr("2.8/" + NAVMESH_MANIFEST, "{not json")
            os.utime(os.path.join(proot, "2.8", "nojson.zip"), (t0 + 16, t0 + 16))
            n_log = len(logged)
            r = adopt_navmesh_archives("2.8")
            assert r["adopted"] is False and r["local"] is False and r["problem"].startswith("navmesh.json is not valid JSON (") \
                and os.path.isfile(refused_path) and len(logged) == n_log + 2 and "refused -- navmesh.json is not valid JSON" in logged[-1], (r, logged[-2:])
            os.remove(os.path.join(proot, "2.8", "nojson.zip"))
            os.remove(z3)
            _remove_quiet(refused_path)
            # the record of the folder is newer.zip's again
            r = adopt_navmesh_archives("2.8")
            assert r["adopted"] is True and r["archive"] == "newer.zip" and folder_names() == ["scene_20133.navmesh", "scene_9_0_-1.navmesh"], r
            marker_before = read_text(os.path.join(nav28, NAVMESH_ZIP_MARKER))
            # (d) refusals: the folder stays, ONE warning, the sha256 recorded, silent afterwards
            refused_path = os.path.join(proot, "2.8", NAVMESH_ZIP_REFUSED)
            cases = [
                ("escaping member", dict(extra=[("../escape.txt", b"x")]), "a member named '../escape.txt'"),
                ("absolute member", dict(extra=[("/etc/passwd", b"x")]), "a member named '/etc/passwd'"),
                ("sha256 mismatch", dict(bad_sha=True), "scene_9_0_0.navmesh does not match the sha256 of its entry"),
                ("another version", dict(version="1.6"), "no 2.8/navmesh.json in it"),  # 1.6/navmesh.json in payloads/2.8/
                ("manifest of another version", dict(version_in="1.6"), "says version 1.6, but it sits in the 2.8 payload"),
                ("no manifest", dict(manifest=False), "no 2.8/navmesh.json in it"),
                ("corrupt member", dict(corrupt=True), "cannot be unpacked (Bad CRC-32")]
            # A backslash in a name as the archive STORES it, refused on every system: Windows' zipfile hands the
            # name out with `/` in its place -- there the second zip below would otherwise be a valid bundle (its
            # one file under 2.8/NavMesh/) and be adopted, on Linux it would be refused for the same bytes
            cases.insert(1, ("backslash member", dict(extra=[("2.8\\NavMesh\\scene_9.navmesh", b"x")]),
                             "a member named '2.8\\\\NavMesh\\\\scene_9.navmesh'"))
            cases.insert(2, ("backslash in the stored name of a listed file",
                             dict(stored=("2.8/NavMesh/scene_9_0_0.navmesh", "2.8\\NavMesh\\scene_9_0_0.navmesh")),
                             "a member named '2.8\\\\NavMesh\\\\scene_9_0_0.navmesh'"))
            for i, (label, kw, text) in enumerate(cases):
                zr = make_zip(os.path.join(proot, "2.8", "bad%d.zip" % i), mtime=t0 + 20 + i, **kw)
                n_log = len(logged)
                r = adopt_navmesh_archives("2.8")
                assert r["adopted"] is False and r["known"] is False and r["problem"], (label, r)
                assert len(logged) == n_log + 1 and logged[-1].startswith("gio-agent: navmesh: WARNING: Navmesh: bad%d.zip refused -- " % i) \
                    and "not looked at again" in logged[-1] and text in logged[-1], (label, logged[-1])
                assert folder_names() == ["scene_20133.navmesh", "scene_9_0_-1.navmesh"], (label, folder_names())
                assert read_text(os.path.join(nav28, NAVMESH_ZIP_MARKER)) == marker_before, label
                ref = _navmesh_zip_marker_read(refused_path)
                assert ref and ref["refused"] is True and ref["sha256"] == _file_sha256(zr) and ref["name"] == "bad%d.zip" % i, (label, ref)
                r = adopt_navmesh_archives("2.8")
                assert r["known"] is True and r["problem"] == "refused earlier" and len(logged) == n_log + 1, (label, r)
                assert not os.path.exists(os.path.join(proot, "2.8", ".relic-navmesh-unpack")), label
                os.remove(zr)
            # ...and a manifest stored under such a name is no manifest: a zip of the payloads folder itself that
            # holds only that is no candidate of the version on any system (the listing is read as stored)
            zb = make_zip(os.path.join(td, "stored-backslash.zip"), stored=("2.8/navmesh.json", "2.8\\navmesh.json"))
            assert _navmesh_zip_holds(zb, "2.8") is False and _navmesh_zip_holds(z2, "2.8") is True
            with zipfile.ZipFile(zb) as zf:
                assert _navmesh_zip_members(zf, "2.8")[2] == "a member named '2.8\\\\navmesh.json'", \
                    _navmesh_zip_members(zf, "2.8")
            # a zip over the size cap: refused without a hash, one warning per process (the cap lowered here:
            # a file of two real GB has no place in a selftest)
            big = os.path.join(proot, "2.8", "big.zip")
            with open(big, "wb") as f:
                f.write(b"PK" * 600)
            os.utime(big, (t0 + 50, t0 + 50))
            g["NAVMESH_ZIP_MAX"] = 1000
            n_log = len(logged)
            r = adopt_navmesh_archives("2.8")
            assert r["adopted"] is False and r["problem"] == "1200 bytes, over the 0 GiB cap" and len(logged) == n_log + 1, (r, logged[-1:])
            assert adopt_navmesh_archives("2.8")["known"] is True and len(logged) == n_log + 1
            g["NAVMESH_ZIP_MAX"] = saved_z["NAVMESH_ZIP_MAX"]
            os.remove(big)
            # the other version's archive in the payloads folder is 1.6's alone: adopted there, ignored for 2.8
            make_zip(os.path.join(proot, "relic-navmesh-1.6.zip"), version="1.6", mtime=t0 + 60,
                     files=[("scene_4_0_0.navmesh", nav_blob(4), 4)])
            r = adopt_navmesh_archives("1.6")
            assert r["adopted"] is True and r["files"] == 1 and sorted(os.listdir(os.path.join(proot, "1.6", "navmesh", "NavMesh"))) == ["scene_4_0_0.navmesh"], r
            assert adopt_navmesh_archives("2.8")["known"] is True, "2.8 keeps newer.zip on record"
            # a refusal is cleared once a good zip is adopted after it
            make_zip(os.path.join(proot, "2.8", "bad9.zip"), mtime=t0 + 70, bad_sha=True)
            assert adopt_navmesh_archives("2.8")["adopted"] is False and os.path.isfile(refused_path)
            make_zip(os.path.join(proot, "2.8", "good9.zip"), mtime=t0 + 80)
            assert adopt_navmesh_archives("2.8")["adopted"] is True and not os.path.exists(refused_path)
            for n_ in ("bad9.zip", "good9.zip"):
                os.remove(os.path.join(proot, "2.8", n_))
            # install_navmesh adopts at its top (the source), navmesh_status / /status never raise over it
            inst_src = agent_src[agent_src.index("\ndef install_navmesh("):agent_src.index("\ndef navmesh_status(")]
            assert inst_src.index("adopt_navmesh_archives(version, job, payload_root)") < inst_src.index("_navmesh_read_bundle(version, payload_root)")
            main_src = agent_src[agent_src.index('\nif __name__ == "__main__":'):]
            assert main_src.index("tweaks_at_agent_start()") < main_src.index("navmesh_at_agent_start()") < \
                main_src.index("target=tower_watchdog"), "the archives are adopted at the agent's start, before the watchdogs"
            # (e) the route: 400 for whatever cannot be right, a good body reaches start_job as kind `navmesh`
            started = []

            def fake_start_z(kind, version, fn, lock=True, beside_yielding=False):
                started.append((kind, version, lock))
                return Job(kind, version, job_id="nav-route")

            def post_z(body, path="/server/navmesh"):
                reply = []
                raw = json.dumps(body).encode()
                hh = Handler.__new__(Handler)
                hh.path, hh.rfile = path, io.BytesIO(raw)
                hh.headers = {"Authorization": "Bearer selftest-token", "Content-Length": str(len(raw))}
                hh._send = lambda status_, obj, retry_after=None: reply.append((status_, obj))
                hh.do_POST()
                assert len(reply) == 1, reply
                return reply[0]

            g["start_job"] = fake_start_z
            good = {"version": "2.8", "url": "https://github.com/x/relic/releases/download/v1/relic-navmesh-2.8.zip",
                    "sha256": "c8f3c607d6406758bb19df61b13e5636abbde5efa793c6699bc6037941661a8c", "size": 127650863}
            for body, text in (
                    (dict(good, version="0.0"), "Unknown version: 0.0."),
                    (dict(good, version=28), "version must be a string"),
                    ({k: v for k, v in good.items() if k != "version"}, "version must be a string"),
                    ({k: v for k, v in good.items() if k != "url"}, "url is required"),
                    (dict(good, url=""), "url is required"),
                    (dict(good, url="http://github.com/x.zip"), "url must be an https URL with a host"),
                    (dict(good, url="https:///x.zip"), "url must be an https URL with a host"),
                    (dict(good, url="https://github.com/a b.zip"), "url must not contain spaces"),
                    (dict(good, url="https://h/" + "x" * NAVMESH_URL_MAX), "url must be at most 2048 characters"),
                    ({k: v for k, v in good.items() if k != "sha256"}, "sha256 must be 64 hex characters"),
                    (dict(good, sha256="c8f3"), "sha256 must be 64 hex characters"),
                    (dict(good, sha256="g" * 64), "sha256 must be 64 hex characters"),
                    ({k: v for k, v in good.items() if k != "size"}, "size must be an integer between 1 and"),
                    (dict(good, size=0), "size must be an integer between 1 and"),
                    (dict(good, size=True), "size must be an integer between 1 and"),
                    (dict(good, size="127650863"), "size must be an integer between 1 and"),
                    (dict(good, size=NAVMESH_ZIP_MAX + 1), "size must be an integer between 1 and")):
                status_, obj = post_z(body)
                assert status_ == 400 and text in obj["error"], (body, status_, obj)
            assert not started
            status_, obj = post_z(dict(good, sha256=good["sha256"].upper()))
            assert status_ == 202 and obj["kind"] == "navmesh" and obj["version"] == "2.8" and started == [("navmesh", "2.8", False)], \
                (status_, obj, started)  # lock=False: the job takes _op_lock for its finish phase only
            status_, obj = post_z({"version": "2.8", "cancel": True})
            assert status_ == 200 and obj == {"ok": True, "stopping": False} and len(started) == 1, (status_, obj)
            status_, obj = post_z({"version": "0.0", "cancel": True})
            assert status_ == 400, (status_, obj)
            g["start_job"] = saved_z["start_job"]
            # (f) the job on a faked downloader that writes a synthetic zip: adopted, installed 0 without a stack
            zbytes = io.BytesIO()
            with zipfile.ZipFile(zbytes, "w", zipfile.ZIP_DEFLATED) as zf:
                data = nav_blob(9, b"\x02")
                zf.writestr("2.8/" + NAVMESH_MANIFEST, json.dumps({"format": 1, "version": "2.8", "files": [
                    {"name": "scene_9_0_0.navmesh", "size": len(data), "md5": hashlib.md5(data).hexdigest(),
                     "sha256": hashlib.sha256(data).hexdigest(), "scene": 9}]}))
                zf.writestr("2.8/NavMesh/scene_9_0_0.navmesh", data)
            zbytes = zbytes.getvalue()
            zsha = hashlib.sha256(zbytes).hexdigest()
            fetched = []
            cur_job = [None]  # the job of the running download: it must YIELD while the bytes come in

            def fake_fetch_z(url, dst, timeout=60, cap=None, expect_md5=None, expect_size=None, resume=False,
                             should_stop=None, progress=None):
                fetched.append(url)
                assert expect_md5 is None and expect_size == len(zbytes) and resume and cap == NAVMESH_ZIP_MAX \
                    and should_stop is not None, (expect_md5, expect_size, resume, cap)
                assert cur_job[0] is None or cur_job[0].yielding is True, "the download phase must let watchdog jobs and signups start"
                assert not _op_lock.locked(), "the download must not hold _op_lock"
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with open(dst + ".part", "wb") as f:
                    f.write(zbytes)
                if progress is not None:
                    progress(len(zbytes))
                replace_file(dst + ".part", dst)
                return len(zbytes)

            g["_fetch_to_file"] = fake_fetch_z
            jz = _Job()
            cur_job[0] = jz
            res = do_navmesh_download("2.8", jz, good["url"], zsha, len(zbytes))
            cur_job[0] = None
            assert res == {"adopted": True, "archive": "navmesh.zip", "files": 1, "installed": 0, "restarted": False,
                           "downloaded": True, "note": "adopted as payloads/2.8/navmesh/; no server stack of 2.8 on this box "
                                                       "-- the files reach a stack at its first Prepare / Start"}, res
            assert jz.yielding is False and not _op_lock.locked(), "the finish phase runs under _op_lock, not yielding"
            assert any("admin operations on this server wait until this finishes" in l for l in jz.lines), jz.lines
            assert fetched == [good["url"]] and os.path.isfile(_navmesh_zip_path("2.8")) and folder_names() == ["scene_9_0_0.navmesh"]
            with open(os.path.join(nav28, "NavMesh", "scene_9_0_0.navmesh"), "rb") as f:
                assert f.read() == data
            assert any("Archive verified (size + sha256)" in l for l in jz.lines) and any("adopted navmesh.zip" in l for l in jz.lines), jz.lines
            # run again: the archive is already here and on record -- no download, not a failure
            jz2 = _Job()
            res = do_navmesh_download("2.8", jz2, good["url"], zsha, len(zbytes))
            assert res["adopted"] is False and res["downloaded"] is False and res["files"] == 1 and len(fetched) == 1 \
                and res["note"].startswith("already the payload of 2.8"), res
            assert any("skipped the download" in l for l in jz2.lines), jz2.lines
            # the sha256 mismatch: 502, the file deleted, the payload folder as it was
            os.remove(_navmesh_zip_path("2.8"))
            try:
                do_navmesh_download("2.8", _Job(), good["url"], "0" * 64, len(zbytes))
                raise AssertionError("a sha256 mismatch must end in 502")
            except AgentError as e:
                assert e.status == 502 and "Checksum mismatch" in e.message and "discarded" in e.message, e.message
            assert not os.path.exists(_navmesh_zip_path("2.8")) and folder_names() == ["scene_9_0_0.navmesh"]
            # a downloaded archive that does not validate: 500, the folder as it was, the archive kept
            badbytes = io.BytesIO()
            with zipfile.ZipFile(badbytes, "w") as zf:
                zf.writestr("2.8/" + NAVMESH_MANIFEST, json.dumps({"format": 1, "version": "2.8", "files": [
                    {"name": "scene_9_0_0.navmesh", "size": 1, "md5": "0" * 32, "sha256": "0" * 64, "scene": 9}]}))
            badbytes = badbytes.getvalue()

            def fake_fetch_bad(url, dst, **kw):
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with open(dst, "wb") as f:
                    f.write(badbytes)
                return len(badbytes)

            g["_fetch_to_file"] = fake_fetch_bad
            try:
                do_navmesh_download("2.8", _Job(), good["url"], hashlib.sha256(badbytes).hexdigest(), len(badbytes))
                raise AssertionError("an archive that does not validate must end in 500")
            except AgentError as e:
                assert e.status == 500 and "was refused" in e.message and "not in the payload" in e.message \
                    and refused_path in e.message, e.message
            assert os.path.isfile(_navmesh_zip_path("2.8")) and folder_names() == ["scene_9_0_0.navmesh"]
            # asked again for the same archive: the refusal on record is cleared first (the request is a retry),
            # the archive looked at again -- and refused again, the folder still as it was
            assert os.path.isfile(refused_path)
            jr = _Job()
            try:
                do_navmesh_download("2.8", jr, good["url"], hashlib.sha256(badbytes).hexdigest(), len(badbytes))
                raise AssertionError("the retry of an archive that does not validate must end in 500")
            except AgentError as e:
                assert e.status == 500 and "was refused" in e.message, e.message
            assert any("looked at again, as asked" in l for l in jr.lines) and any("refused -- " in l for l in jr.lines), jr.lines
            assert os.path.isfile(refused_path) and folder_names() == ["scene_9_0_0.navmesh"]
            # a failure of the box after the download: 500 that says so, not "another file is newer"
            g["adopt_navmesh_archives"] = lambda version, job=None, payload_root=None: None
            try:
                do_navmesh_download("2.8", _Job(), good["url"], hashlib.sha256(badbytes).hexdigest(), len(badbytes))
                raise AssertionError("a payloads folder that cannot be looked at must end in 500")
            except AgentError as e:
                assert e.status == 500 and "could not be looked at" in e.message and "newest archive" not in e.message, e.message
            g["adopt_navmesh_archives"] = saved_z["adopt_navmesh_archives"]
            os.remove(_navmesh_zip_path("2.8"))
            _remove_quiet(refused_path)
            # Stop mid-download: 409, the .part stays
            def stopping_fetch_z(url, dst, **kw):
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with open(dst + ".part", "wb") as f:
                    f.write(zbytes[:50])
                _navmesh_cancel.set()
                raise FetchStopped("stopped on request")

            g["_fetch_to_file"] = stopping_fetch_z
            try:
                do_navmesh_download("2.8", _Job(), good["url"], zsha, len(zbytes))
                raise AssertionError("a cancelled download must end in 409")
            except AgentError as e:
                assert e.status == 409 and e.message.startswith("Stopped on request"), e.message
            assert os.path.getsize(_navmesh_zip_path("2.8") + ".part") == 50
            _navmesh_cancel.clear()
            # a network cut: retried with the backoff, then the transfer completes
            cuts = [1]

            def cutting_fetch_z(url, dst, **kw):
                if cuts[0]:
                    cuts[0] -= 1
                    raise FetchCut("connection lost mid-transfer (timed out)")
                return fake_fetch_z(url, dst, **kw)

            g["_fetch_to_file"] = cutting_fetch_z
            time.sleep = lambda _s: None
            jc = _Job()
            res = do_navmesh_download("2.8", jc, good["url"], zsha, len(zbytes))
            assert res["downloaded"] is True and any("retrying in 10 s (0 of 0 MB kept)" in l for l in jc.lines), (res, jc.lines)
            # a stack present but not bootstrapped: the files are installed, nothing restarted
            stack28 = os.path.join(td, "stack28")
            os.makedirs(os.path.join(stack28, "server", "res"))
            with open(os.path.join(stack28, "docker-compose.yml.tmpl"), "w") as f:
                f.write("services: {}\n")
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = stack28, _project_name(stack28)
            os.remove(_navmesh_zip_path("2.8"))
            g["_fetch_to_file"] = fake_fetch_z
            jp = _Job()
            res = do_navmesh_download("2.8", jp, good["url"], zsha, len(zbytes))
            assert res["installed"] == 1 and res["restarted"] is False and "switched off" in res["note"], res
            assert os.path.isfile(os.path.join(stack28, "server", "res", "NavMesh", "scene_9_0_0.navmesh"))
            assert os.path.isfile(os.path.join(stack28, "server", "res", NAVMESH_LIST))
            # the restart of a RUNNING pathfinding server = the toggle's two paths (off, then on with the 75 s check);
            # none over an unfinished change of the stack internal password or a record that cannot be read -- the
            # files are installed by then, so the job ends with its result and a note, never a 409
            calls = []
            g["is_bootstrapped"] = lambda v: True
            g["pathfinding_enabled"] = lambda v: True
            g["stack_up"] = lambda v: (True, None)
            g["dead_services"] = lambda v: ([], {PATHFINDING_SERVICE: "running"})
            g["reconcile_pathfinding"] = lambda v, j, enabled: calls.append((v, enabled))
            g["internal_change_pending"] = lambda v: ("yes", None)
            jr_ = _Job()
            r = _navmesh_restart_pathfinding("2.8", jr_)
            assert r[0] is False and "has not finished" in r[1] and "next Start" in r[1] and calls == [] and not jr_.lines, r
            g["internal_change_pending"] = lambda v: ("unknown", OSError("unreadable"))
            assert _navmesh_restart_pathfinding("2.8", jr_)[0] is False and calls == []
            g["internal_change_pending"] = lambda v: ("no", None)
            assert _navmesh_restart_pathfinding("2.8", jr_) == (True, "the pathfinding server was restarted and reads the files now") \
                and calls == [("2.8", False), ("2.8", True)] and any("Restarting the pathfinding server" in l for l in jr_.lines)
            g["dead_services"] = lambda v: ([], {PATHFINDING_SERVICE: "exited"})
            assert _navmesh_restart_pathfinding("2.8", jr_) == (False, "the pathfinding server is not running (exited) -- the files load when it boots") \
                and len(calls) == 2
            # _fetch_to_file itself: resume with a size but no md5 adopts a complete .part by its size (no
            # request), the caller proving the bytes afterwards
            dstf = os.path.join(td, "dl", "a.zip")
            os.makedirs(os.path.dirname(dstf))
            with open(dstf + ".part", "wb") as f:
                f.write(b"123456")
            assert saved_z["_fetch_to_file"]("https://h.invalid/a.zip", dstf, expect_size=6, resume=True) == 6
            assert os.path.isfile(dstf) and not os.path.exists(dstf + ".part")
        finally:
            time.sleep = saved_sleep
            g.update(saved_z)
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_
            _navmesh_cancel.clear()
            _NAVMESH_ZIP_WARNED.clear()
            _NAVMESH_ZIP_NOTED.clear()
    ok("navmesh archives OK (adopted from the payloads folder and payloads/<v>/, once per sha256, a newer zip "
       "replaces the folder, every refusal once + recorded -- a backslash in a name as the zip stores it on every "
       "system --, the size cap, the other version's zip, /status "
       "archive, the route's 400s + cancel, the job: adopted / already here / sha256 502 / refused 500 / stop 409 / "
       "cut retried / installed into a present stack, a size-pinned resume)")

    # THE PATHFINDING DATA DOWNLOAD: the shipped catalogues against PAYLOAD_EXPECT, the validator, the md5 list rule,
    # the status numbers, the refusals -- never a 404 -- and the job on a faked downloader + extractor over a temp
    # stack of a fixture version: only what the stack lacks goes in, a file it has is left alone, the md5 list names
    # what holds the catalogue's bytes, and every way out that changes nothing leaves the stack as it was.
    for v in VERSIONS:
        cat = read_navdata_catalog(v)
        if cat is None:
            continue
        expect = (PAYLOAD_EXPECT.get(v) or {}).get("navdata")
        assert expect is not None, \
            "payloads/%s/%s: PAYLOAD_EXPECT names no pathfinding data for %s -- a catalogue nobody described" \
            % (v, NAVDATA_CATALOG, v)
        assert validate_navdata_catalog(cat, v) and usable_navdata_catalog(v) == cat, v
        assert cat["version"] == v and cat["label"] == "Internet Archive" \
            and urllib.parse.urlsplit(cat["url"]).hostname == "archive.org", (v, cat["url"])
        files = cat["files"]
        assert (len(files), sum(1 for f_ in files if f_["vendor"])) == (expect["files"], expect["vendor"]), \
            (v, len(files), sum(1 for f_ in files if f_["vendor"]))
        assert [f_["path"] for f_ in files] == sorted((f_["path"] for f_ in files), key=lambda p_: p_.encode("utf-8")), \
            "payloads/%s/%s: the files sorted by the path's UTF-8 bytes" % (v, NAVDATA_CATALOG)
        assert cat["size"] < cat["extractedSize"] and sum(f_["size"] for f_ in files) <= cat["extractedSize"], v
        ok("pathfinding data catalogue %s OK (%d files, %d of them the vendor's, a %.1f MB archive on %s)"
           % (v, len(files), expect["vendor"], cat["size"] / 1e6, urllib.parse.urlsplit(cat["url"]).hostname))
    f0 = {"path": "NavMesh/scene_9_0_0.navmesh", "size": 3, "md5": "b" * 32, "vendor": False}
