            g["_mysql_q"] = saved["_mysql_q"]
            assert sdk_exact_lookup("2.8", "bob") == (1, "bob") and sdk_exact_lookup("2.8", "BOB") is None and \
                sdk_exact_lookup("2.8", "guestname") is None and sdk_exact_lookup("2.8", "nobody") is None
            g["_mysql_q"] = mg_q
            # a real run: phase T begins only after the whole source phase, the reader gone, the rows spooled as read with
            # the entry, private and without a hash; the hashes in memory alone; the spool gone with the job
            at_t = {}

            def fake_phase_t(target_, job_, req_, st_):
                at_t.update(order=list(order), st=st_, spool=sorted(os.listdir(migrate_spool_dir(job_.id))))
                at_t["kept"] = [migrate_spool_get(job_.id, n_) for n_ in st_["spooled"]]
                at_t["modes"] = [os.stat(os.path.join(migrate_spool_dir(job_.id), n_)).st_mode & 0o777 for n_ in at_t["spool"]]
                with open(os.path.join(migrate_spool_dir(job_.id), "%d.json" % st_["spooled"][0]), "rb") as f:
                    at_t["text"] = f.read()
