            assert IS_WINDOWS or at_t["modes"] == [0o600] * 3, at_t["modes"]
            assert at_t["order"][-2:] == ["rm-f", "volume-rm"], at_t["order"]
            st_ = at_t["st"]
            assert st_["spooled"] == [0, 1, 3] and at_t["spool"] == ["0.json", "1.json", "3.json"], at_t["spool"]
            assert [e_["verdict"] for e_ in st_["entries"]] == ["create", "create", "skip", "overwrite", "skip"], st_["entries"]
            assert st_["hashes"] and all(isinstance(h_, bytes) for h_ in st_["hashes"].values()), "kept for the tail"
            assert sorted(st_["hashes"]) == [1, 2, 3, 10], "of the accounts named, type 1 alone: %s" % sorted(st_["hashes"])
            assert st_["ctx"]["mail"] is False, "no mail moves"
            assert st_["build"] == "1.6" and st_["src"] == s16 and st_["man"]["version"] == "2.8" and st_["ctx"]["facts"] is F28
            assert b"$2b$" not in at_t["text"] and PW_HASH not in at_t["text"]
            entry0, rows0 = at_t["kept"][0]
