    ps_src_hp = agent_src_hp[ps_start_hp:agent_src_hp.index("\ndef ", ps_start_hp + 5)]
    assert "defaultEnabled" not in ps_src_hp and "hotpatch_brief" not in ps_src_hp \
        and "hotpatch_info" not in ps_src_hp, "the public snapshot carries a hotpatch answer (S4)"
    ok("hotpatch default OK (the shipped 3.2 flag, the reader's rule and its one warning, the route's choice, the "
       "Prepare's decision table, a decided record untouched, 1.6 and 2.8 without a default, the status answers, the "
       "pinned bytes; a 3.2 Prepare with no URL refuses with one line and leaves the stack and the record alone, the "
       "route closed; with a URL on a stopped stack it is enabled and pending, applied by the SQL half later; an explicit "
       "False is kept over an advertising restart; the enable runs before the bootstrap, no version id, the public "
       "snapshot names none of it)")
    ok("hotpatch enable/disable job OK (fake stack, no network, no docker: mirror + configs + "
       "pending state + failure + refusals + purge)")
    ok("hotpatch job with the stack up OK (simulated MySQL/compose: state persisted before the SQL, "
       "restart only when something changed or is owed, failed restart/SQL stay pending, "
       "double disable owes nothing, empty row read as empty)")
    ok("hotpatch path confinement + miss policy + on-demand budget OK (a version's files served -- from disk too -- "
       "and fetched on demand only while its hotpatch is enabled, an unreadable state a no, the files a Disable "
       "keeps served again once enabled, the state file read again only once it changed or another read found it "
       "unreadable -- for the enabled flags, the voice selections and the policy's on-demand switch alike --, a stat "
       "that fails a no; a reset or a restore enables again the hotpatch a stack still advertises, and so does the "
       "agent's start where the state holds no decision about it, a missing state file included, a record that says "
       "disabled kept; a restore disables again an enabled record of a stack that certainly no longer advertises it "
       "(its revert owed) or of a version without a stack, never one whose stack cannot be read; a listedOnly "
       "manifest's subtrees: only "
       "the files it lists and the voice packs its verified index names are served or fetched; another spelling of a "
       "stored file never served; every refusal of the route -- the fence, a version not enabled, an unreadable "
       "state, a miss not fetched, a file of a base output that is no voice pack its index names -- logged once per "
       "path and reason an hour, the lines a minute capped for all of them)")
    ok("hotpatch voice packs OK (index allowlist, admin selection -- from disk as on a miss: a language not selected "
       "keeps its packs on disk, unserved, and of a base output only the packs its verified index names --, job + "
       "purge, on-demand only while enabled, tampered index -- hashed once at its stat, like the official one --, disk "
       "guard, refused-request counter)")

    # _fetch_to_file touches the disk only after the upstream answered: a 404 / dead CDN creates
    # no directory, a transfer that dies half-way (or over the cap) takes its directories away again.
    saved_open = urllib.request.urlopen
    with tempfile.TemporaryDirectory() as td:
        try:
            deep = os.path.join(td, "a", "b", "c", "file.bin")

            def dead(req, timeout=0):
                raise urllib.error.HTTPError(req.full_url, 404, "NoSuchKey", {}, None)

            class Resp:
                def __init__(self, chunks, status=200, headers=None):
                    self.chunks = list(chunks)
                    self.status = status
                    self.headers = headers or {}

                def __enter__(self):
                    return self

                def __exit__(self, *a):
                    return False

                def read(self, n):
                    if not self.chunks:
                        return b""
                    c = self.chunks.pop(0)
                    if isinstance(c, Exception):
                        raise c
                    return c

            urllib.request.urlopen = dead
            try:
                _fetch_to_file("https://hk.invalid/x", deep)
                raise AssertionError("a 404 must raise")
            except urllib.error.HTTPError:
                pass
            assert not os.path.exists(os.path.join(td, "a")), "a 404 must not create directories"
            urllib.request.urlopen = lambda req, timeout=0: Resp([b"ab", socket.timeout("stalled")])
            try:
                _fetch_to_file("https://hk.invalid/x", deep)
                raise AssertionError("a stalled transfer must raise")
            except FetchCut as e:
                assert isinstance(e, OSError), "callers retry it like any network error"
            assert not os.path.exists(os.path.join(td, "a")), "a failed transfer must remove what it created"
            urllib.request.urlopen = lambda req, timeout=0: Resp([b"ab", b"cd"])
            try:
                _fetch_to_file("https://hk.invalid/x", deep, cap=3)
                raise AssertionError("over the cap must raise")
            except ValueError as e:
                assert "cap" in str(e)
            assert not os.path.exists(os.path.join(td, "a"))
            assert _fetch_to_file("https://hk.invalid/x", deep, expect_md5=hashlib.md5(b"abcd").hexdigest(),
                                  expect_size=4) == 4
            with open(deep, "rb") as f:
                assert f.read() == b"abcd"
            assert not os.path.exists(deep + ".part")
            # a DECLARED length that can never pass is refused before a byte is streamed or a
            # directory made (an unlisted 300 MB pack must not be pulled four times up to the cap)
            big = Resp([b"x" * 10], headers={"Content-Length": "10"})
            urllib.request.urlopen = lambda req, timeout=0: big
            for kw in ({"cap": 9}, {"expect_size": 11, "expect_md5": "0" * 32}):
                try:
                    _fetch_to_file("https://hk.invalid/x", os.path.join(td, "r", "f.bin"), **kw)
                    raise AssertionError("must be refused: %r" % kw)
                except FetchRefused:
                    pass
                assert len(big.chunks) == 1 and not os.path.exists(os.path.join(td, "r")), kw
            # resume (voice packs): what the NETWORK cut keeps its .part and continues by Range; the
            # md5 covers the whole file; an upstream that ignores the Range restarts cleanly; a bad
            # splice is thrown away like any other corruption
            want = {"expect_md5": hashlib.md5(b"abcdef").hexdigest(), "expect_size": 6, "resume": True}
            vo = os.path.join(td, "v", "VO.pck")
            asked = []

            def ranged(*bodies):
                todo = list(bodies)

                def opener(req, timeout=0):
                    asked.append(req.get_header("Range"))
                    return todo.pop(0)
                return opener

            urllib.request.urlopen = ranged(Resp([b"abc", socket.timeout("stalled")]), Resp([b"def"], status=206))
            try:
                _fetch_to_file("https://hk.invalid/v", vo, **want)
                raise AssertionError("the cut transfer must raise")
            except FetchCut:
                pass
            with open(vo + ".part", "rb") as f:
                assert f.read() == b"abc", "a transfer the network cut keeps its .part"

            def cdn_down(req, timeout=0):
                raise urllib.error.URLError("unreachable")

            resume_opener = urllib.request.urlopen
            urllib.request.urlopen = cdn_down  # a dead CDN costs nothing (no hashing) and keeps the .part
            try:
                _fetch_to_file("https://hk.invalid/v", vo, **want)
                raise AssertionError("must raise")
            except urllib.error.URLError:
                pass
            assert os.path.getsize(vo + ".part") == 3
            urllib.request.urlopen = resume_opener
            assert _fetch_to_file("https://hk.invalid/v", vo, **want) == 6 and asked == [None, "bytes=3-"], asked
            with open(vo, "rb") as f:
                assert f.read() == b"abcdef"
            assert not os.path.exists(vo + ".part")
            os.remove(vo)
            with open(vo + ".part", "wb") as f:
                f.write(b"abc")
            urllib.request.urlopen = ranged(Resp([b"abcdef"], status=200))  # the Range was ignored
            assert _fetch_to_file("https://hk.invalid/v", vo, **want) == 6
            with open(vo, "rb") as f:
                assert f.read() == b"abcdef"
            os.remove(vo)
            with open(vo + ".part", "wb") as f:
                f.write(b"XYZ")
            urllib.request.urlopen = ranged(Resp([b"def"], status=206))
            try:
                _fetch_to_file("https://hk.invalid/v", vo, **want)
                raise AssertionError("a wrong splice must fail the md5")
            except ValueError as e:
                assert "md5" in str(e)
            assert not os.path.exists(vo + ".part") and not os.path.exists(vo)
            # without resume nothing is kept, as before
            urllib.request.urlopen = lambda req, timeout=0: Resp([b"abc", socket.timeout("stalled")])
            try:
                _fetch_to_file("https://hk.invalid/v", vo, expect_md5=want["expect_md5"], expect_size=6)
                raise AssertionError("must raise")
            except FetchCut:
                pass
            assert not os.path.exists(vo + ".part")
            # a COMPLETE .part (only the rename never happened) is verified and adopted, no request
            with open(vo + ".part", "wb") as f:
                f.write(b"abcdef")
            urllib.request.urlopen = cdn_down
            assert _fetch_to_file("https://hk.invalid/v", vo, **want) == 6 and not os.path.exists(vo + ".part")
            os.remove(vo)
            # should_stop (a cancelled voice job): FetchStopped, the .part stays for the next run
            calls = []
            urllib.request.urlopen = lambda req, timeout=0: Resp([b"abc", b"def"])
            try:
                _fetch_to_file("https://hk.invalid/v", vo, should_stop=lambda: bool(calls) or calls.append(1), **want)
                raise AssertionError("must stop")
            except FetchStopped:
                pass
            with open(vo + ".part", "rb") as f:
                assert f.read() == b"abc"
            os.remove(vo + ".part")
            # a rename refused because dst is open elsewhere: accepted only when dst IS the file
            # (size AND md5); a same-size corrupt dst is "in use", and the complete .part waits
            real_replace = globals()["replace_file"]

            def refused(src, dst_, attempts=5, delay=0.2):
                raise PermissionError(13, "in use (selftest)")

            globals()["replace_file"] = refused
            try:
                with open(vo, "wb") as f:
                    f.write(b"abcdef")
                urllib.request.urlopen = lambda req, timeout=0: Resp([b"abcdef"])
                assert _fetch_to_file("https://hk.invalid/v", vo, **want) == 6 and not os.path.exists(vo + ".part")
                with open(vo, "wb") as f:
                    f.write(b"ABCDEF")  # same size, wrong bytes: what a force re-fetch is there to repair
                urllib.request.urlopen = lambda req, timeout=0: Resp([b"abcdef"])
                try:
                    _fetch_to_file("https://hk.invalid/v", vo, **want)
                    raise AssertionError("a corrupt dst that cannot be replaced must not pass as verified")
                except MirrorBusyError:
                    pass
                with open(vo + ".part", "rb") as f:
                    assert f.read() == b"abcdef", "the complete, verified .part waits for the next run"
            finally:
                globals()["replace_file"] = real_replace
            os.remove(vo)
            os.remove(vo + ".part")
            # the LOCAL side failing is no network error: MirrorWriteError, no .part left behind
            blocker = os.path.join(td, "blocker")
            open(blocker, "w").close()
            urllib.request.urlopen = lambda req, timeout=0: Resp([b"abcdef"])
            try:
                _fetch_to_file("https://hk.invalid/v", os.path.join(blocker, "x", "VO.pck"), **want)
                raise AssertionError("a folder that cannot be made must raise")
            except MirrorWriteError:
                pass
            HOTPATCH_DIR_saved, HOTPATCH_DIR = HOTPATCH_DIR, blocker
            try:
                hotpatch_fetch(["https://hk.invalid"], "x/VO.pck", expect={"md5": want["expect_md5"], "size": 6}, resume=True)
                raise AssertionError("must raise")
            except AgentError as e:
                assert e.status == 507, (e.status, e.message)
            finally:
                HOTPATCH_DIR = HOTPATCH_DIR_saved
        finally:
            urllib.request.urlopen = saved_open
    ok("_fetch_to_file touches the disk only after the upstream answered (404 / outage / cap leave no directory)")
    ok("_fetch_to_file refuses a declared length that cannot pass; resume keeps a cut .part and continues by Range")
    ok("_fetch_to_file: only a NETWORK cut keeps the .part (a dead CDN costs no hashing, a complete .part is "
       "adopted, should_stop keeps it); a local write failure is MirrorWriteError -> 507, no retry")

    # The agent state file: a broken state.json is never silently reset and never turns a routine
    # Start into a re-import; recovery markers are saved strictly. Temp dir + fakes, no docker.
    g = globals()
    faked_st = ("STATE_PATH", "PROVISION_MODE", "TOKEN", "read_manifest", "running_projects", "mysql_exec",
                "_compose_stream", "wait_for_mysql", "_write_state_atomic", "log_line", "current_job",
                "_read_state_bytes")
    saved_st = {k: g[k] for k in faked_st}
    saved_rec = dict(_STATE_RECOVERY)
    saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
    with tempfile.TemporaryDirectory() as td:
        try:
            sp = os.path.join(td, "state.json")
            stack = os.path.join(td, "1.6_live")
            os.makedirs(stack)
            for name in ("docker-compose.yml", ".bootstrap.lock"):
                open(os.path.join(stack, name), "w").close()
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = stack, _project_name(stack)
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = "", ""
            g.update({"STATE_PATH": sp, "PROVISION_MODE": "once", "log_line": lambda *_a: None,
                      # (a payload that ships a save: only such a version is ever provisioned on its own)
                      "read_manifest": lambda _v: {"files": [], "mysql": [{"src": "x.sql", "db": "hk4e_db_user"}]},
                      "running_projects": lambda: (None, "docker unavailable (selftest)"),
                      "current_job": lambda **_k: None})
            _STATE_RECOVERY.update(degraded=None, corruptCopy=None)

            def state_bytes():
                with open(sp, "rb") as f:
                    return f.read()

            def put(data):
                with open(sp, "wb") as f:
                    f.write(data)

            def refused(fn, status, code):
                try:
                    fn()
                except AgentError as e:
                    assert e.status == status and e.code == code, (status, code, e.status, e.code, e.message)
                    return
                raise AssertionError("must be refused with %d %s" % (status, code))

            def disk_full(_data):
                raise OSError(28, "No space left on device")

            # a missing file is a fresh agent (and a fresh stack still provisions); a BOM is tolerated
            assert load_state() == {} and needs_provision("1.6") is True
            put(b'\xef\xbb\xbf{"lastStarted": "1.6"}')
            assert load_state() == {"lastStarted": "1.6"}

            # a torn write: every writer refuses with 503 and the bytes stay exactly as they were
            torn = b'{"versions": {"1.6": {"provisionedAt": "2026-08-14 21:03:11", "runni'
            put(torn)
            try:
                load_state()
                raise AssertionError("a torn state file must not read as {}")
            except StateUnreadable as e:
                assert "JSON" in e.reason, e.reason
            refused(lambda: state_set(lastStarted="1.6"), 503, "state_unreadable")
            refused(lambda: version_state_set("1.6", runningOk=False), 503, "state_unreadable")
            refused(lambda: version_state_set("1.6", strict=True, runningOk=False), 503, "state_unreadable")
            refused(lambda: set_policy({"playerCommands": True}), 503, "state_unreadable")
            refused(lambda: set_policy({"openAdmin": True}), 503, "state_unreadable")
            refused(lambda: version_state("1.6"), 503, "state_unreadable")
            refused(lambda: needs_provision("1.6"), 503, "state_unreadable")
            refused(lambda: do_start("1.6", _Job()), 503, "state_unreadable")
            refused(lambda: do_setup("1.6", _Job()), 503, "state_unreadable")
            assert version_state_set("1.6", best_effort=True, runningOk=False) is False, "the stop path logs and skips"
            assert state_bytes() == torn, "a writer must never save over a file it could not read"
            assert _STATE_RECOVERY["degraded"] and state_readable_for("selftest loop") is False
            # readers degrade: policy fail-closed (signup + commands + upstream forced off, whatever the
            # defaults say), facts unknown, no generation and no signup for players
            pol = get_policy()
            assert not pol["signup"]["enabled"] and not pol["playerCommands"] and not pol["hotpatchUpstream"], pol
            assert pol["openAdmin"] is False and load_open_admin_key() == "", \
                "open administration reads as off too, and an agent started over the file loads no key"
            full = g["status"]()  # `status` is a local loop name earlier in selftest()
            assert full["state"]["ok"] is False and full["state"]["degraded"] and "JSON" in full["state"]["error"], full["state"]
            assert full["versions"]["1.6"]["provisioned"] is None and full["versions"]["1.6"]["passwordVerify"] is None
            pub = build_public_status(full, dict(p1, openAdmin=True))  # p1: signup + player commands ON (policy check above)
            assert pub["signup"]["enabled"] is False and pub["playerCommands"] is False, pub
            assert pub["openAdmin"] is False, pub
            assert pub["versions"]["1.6"]["generation"] is None, pub
            assert secrets_info("1.6")["changedAt"] is None, "the secrets stay readable for a manual repair"
            # non-dict JSON and a malformed "versions" are unreadable too, never {}
            for bad in (b"[1, 2]", b'"x"', b'{"versions": []}', b'{"versions": {"1.6": 3}}'):
                put(bad)
                try:
                    load_state()
                    raise AssertionError("must be unreadable: %r" % bad)
                except StateUnreadable:
                    pass
            ok("state file: unreadable -> writers refuse (503, bytes untouched), stop path skips, readers degrade")

            # save: the current parsable file becomes .bak, no .tmp is left, the file reads again
            put(b'{"lastStarted": "2.8"}')
            assert state_set(lastStarted="1.6") is True and not _STATE_RECOVERY["degraded"]
            assert load_state() == {"lastStarted": "1.6"} and not os.path.exists(sp + ".tmp")
            with open(sp + ".bak", "rb") as f:
                assert json.loads(f.read()) == {"lastStarted": "2.8"}
            # a failed write: a convenience fact logs and goes on, a strict one is a 507 with a code
            g["_write_state_atomic"] = disk_full
            assert state_set(lastStarted="2.8") is False
            refused(lambda: version_state_set("1.6", strict=True, runningOk=False), 507, "state_write_failed")
            # ...and it stops the secrets job and a start before anything touches docker or MySQL
            calls = []
            g.update({"mysql_exec": lambda *a, **k: calls.append("mysql") or subprocess.CompletedProcess([], 0, stdout="1\n", stderr=""),
                      "_compose_stream": lambda *a, **k: calls.append("compose") or 0,
                      "wait_for_mysql": lambda *a, **k: calls.append("wait"),
                      "running_projects": lambda: ([VERSIONS["1.6"]["project"]], None)})
            with open(os.path.join(stack, ".env"), "w") as f:
                f.write("MYSQL_ROOT_PASSWORD=OldRoot_1234\nOUTER_IP=192.0.2.10\n")
            with open(os.path.join(stack, "docker-compose.yml.tmpl"), "w") as f:
                f.write("cmd: redis-server --requirepass Internal_1234\n")
            env_before = read_text(os.path.join(stack, ".env"))
            refused(lambda: do_secrets("1.6", _Job(), {"mysqlRoot": "NewRoot_1234"}), 507, "state_write_failed")
            assert calls == [] and read_text(os.path.join(stack, ".env")) == env_before, calls
            refused(lambda: do_start("1.6", _Job(), provision="none"), 507, "state_write_failed")
            assert calls == [], "no down, no compose before runningOk=False is on record"
            g["_write_state_atomic"] = saved_st["_write_state_atomic"]
            g["running_projects"] = lambda: (None, "docker unavailable (selftest)")
            assert load_state() == {"lastStarted": "1.6"}
            ok("state file: save keeps a .bak; strict marker failure aborts secrets/start before docker or MySQL (507)")

            # the provisioned marker survives a lost state file and re-seeds the same generation
            put(b"{}")
            write_provisioned_marker("1.6", "2026-08-14 21:03:11")
            j = _Job()
            assert needs_provision("1.6", j) is False and any(PROVISIONED_MARKER in l for l in j.lines), j.lines
            assert version_state("1.6")["provisionedAt"] == "2026-08-14 21:03:11"
            os.remove(provisioned_marker_path("1.6"))
            put(b"{}")
            assert needs_provision("1.6") is True, "no marker, no record, no guard: the first provision still runs"
            # migration: a record without a marker gets one, once (v2: progress back-filled as default)
            put(json.dumps({"versions": {"1.6": {"provisionedAt": "2026-08-01 10:00:00"}}}).encode())
            assert migrate_provisioned_markers() == 1 and read_provisioned_marker("1.6") == \
                {"at": "2026-08-01 10:00:00", "progress": "default", "defaultAccount": True}
            assert migrate_provisioned_markers() == 0
            # a fresh bootstrap (it wipes mysql/) forgets both (and the progress record with them)
            forget_provisioned("1.6", _Job())
            vs16 = version_state("1.6")
            assert read_provisioned_marker("1.6") is None and not vs16.get("provisionedAt")
            assert vs16.get("progress") is None and vs16["defaultAccount"] is False, vs16
            ok("provisioned marker: re-seeds a lost provisionedAt, migrated at start, forgotten by a fresh bootstrap")

            # startup: a read failure that clears before the second read leaves a HEALTHY file alone
            healthy = json.dumps({"policy": {"playerCommands": True}, "lastStarted": "1.6",
                                  "versions": {"1.6": {"runningOk": True, "passwordVerify": True}}}).encode()
            put(healthy)
            with open(sp + ".bak", "w") as f:
                json.dump({"lastStarted": "2.8"}, f)
            flaky = []

            def flaky_read(path, attempts=5, delay=0.2):
                if path == sp and not flaky:
                    flaky.append(path)
                    raise StateUnreadable(path, "permission denied (selftest)")
                return saved_st["_read_state_bytes"](path, attempts, delay)
            g["_read_state_bytes"] = flaky_read
            assert recover_state_at_startup(now=1757929900) == "ok" and flaky
            g["_read_state_bytes"] = saved_st["_read_state_bytes"]
            assert state_bytes() == healthy and not _STATE_RECOVERY["degraded"]
            assert not [n for n in os.listdir(td) if n.startswith("state.json.corrupt-")], "a healthy file is never a corrupt copy"
            ok("startup recovery: a transient read failure never rolls a healthy state file back to .bak")

            # startup: unreadable + a good .bak -> corrupt copy kept, .bak restored, runningOk cleared, guard set
            # ...the backup names open administration ON with its key: the restore drops the key and switches
            # the option off (launchers may still hold that key), and says so without the key
            good = {"policy": {"playerCommands": True, "openAdmin": True}, "openAdminToken": "ab" * 24,
                    "lastStarted": "1.6", "versions": {"1.6": {"runningOk": True, "txtFixes": "applied"}}}
            with open(sp + ".bak", "w") as f:
                json.dump(good, f)
            # the sdk still enforces a verification the .bak does not know about
            os.makedirs(os.path.join(stack, "sdk", "data"))
            with open(os.path.join(stack, "sdk", "data", "config.json.tmpl"), "w") as f:
                f.write('{\n  "auth": {\n    "enable_password_verify": true\n  }\n}\n')
            put(torn)
            restore_log = []
            g["log_line"] = lambda *a: restore_log.append(" ".join(str(x) for x in a))
            assert recover_state_at_startup(now=1757930000) == "restored"
            g["log_line"] = lambda *_a: None
            st = load_state()
            assert st["versions"]["1.6"]["runningOk"] is False, st
            assert st["policy"] == {"playerCommands": True, "openAdmin": False} and "openAdminToken" not in st, st
            assert any("open administration switched off" in l for l in restore_log) \
                and not any("ab" * 24 in l for l in restore_log), restore_log
            assert st["versions"]["1.6"]["passwordVerify"] is True, st
            copy = st["restoredFromBackup"]["corruptCopy"]
            assert copy.startswith("state.json.corrupt-") and os.sep not in copy, copy
            with open(os.path.join(td, copy), "rb") as f:
                assert f.read() == torn
            assert g["status"]()["state"]["restoredFromBackup"]["corruptCopy"] == copy
            j = _Job()
            assert needs_provision("1.6", j) is False and any("restored from a backup" in l for l in j.lines), j.lines
            release_provision_guard(_Job())
            assert load_state().get("restoredFromBackup"), "a version without a record keeps the guard"
            write_provisioned_marker("1.6", "2026-08-14 21:03:11")
            release_provision_guard(_Job())
            assert "restoredFromBackup" not in load_state()
            os.remove(provisioned_marker_path("1.6"))
            # switch mode: a rolled-back lastStarted must not re-import a provisioned stack while guarded
            g["PROVISION_MODE"] = "switch"
            prov16 = {"1.6": {"provisionedAt": "2026-08-14 21:03:11"}}
            put(json.dumps({"lastStarted": "2.8", "versions": prov16,
                            "restoredFromBackup": {"at": "2026-09-15 12:00:00", "corruptCopy": copy,
                                                   "reason": "selftest"}}).encode())
            j = _Job()
            assert needs_provision("1.6", j) is False and any("restored from a backup" in l for l in j.lines), j.lines
            put(json.dumps({"lastStarted": "2.8", "versions": prov16}).encode())
            assert needs_provision("1.6") is True, "unguarded, switch mode still re-imports on a version switch"
            g["PROVISION_MODE"] = "once"
            # startup: unreadable and no usable .bak -> left in place (never missing), degraded
            with open(sp + ".bak", "wb") as f:
                f.write(b"{nope")
            put(torn)
            assert recover_state_at_startup(now=1757930100) == "degraded"
            assert state_bytes() == torn and _STATE_RECOVERY["degraded"] and g["status"]()["state"]["degraded"]
            assert len([n for n in os.listdir(td) if n.startswith("state.json.corrupt-")]) == 1, \
                "the same broken bytes reuse their earlier copy"
            ok("startup recovery: .bak restored (corrupt copy, runningOk cleared, guard, open administration closed "
               "and its key dropped) or left in place degraded")

            # POST /agent/state/reset {"confirm": true}: token-only, refused while a job runs
            refused(lambda: reset_state(False), 400, None)
            g["current_job"] = lambda **_k: Job("start", "1.6", job_id="busy-selftest")
            refused(lambda: reset_state(True), 409, None)
            g["current_job"] = lambda **_k: None
            g["TOKEN"] = "selftest-token"
            reply = []
            hh = Handler.__new__(Handler)
            hh.path, hh.rfile = "/agent/state/reset", io.BytesIO(b'{"confirm": true}')
            hh.headers = {"Authorization": "Bearer selftest-token", "Content-Length": "17"}
            hh._send = lambda status_, obj, retry_after=None: reply.append((status_, obj))
            hh.do_POST()
            assert reply and reply[0][0] == 200 and reply[0][1]["ok"], reply
            rst = reply[0][1]["state"]
            assert rst["ok"] and not rst["degraded"] and rst["reset"]["corruptCopy"] == reply[0][1]["corruptCopy"], rst
            assert not _STATE_RECOVERY["degraded"] and state_set(lastStarted="1.6") is True
            assert needs_provision("1.6") is False, "after a reset a version with no record is not imported automatically"
            assert version_state("1.6").get("passwordVerify") is True, "a reset keeps the verification the sdk enforces"
            # a marked stack reads as provisioned right after the reset, with the value the next Start re-seeds
            assert g["status"]()["versions"]["1.6"]["provisioned"] is False
            write_provisioned_marker("1.6", "2026-08-14 21:03:11")
            s16 = g["status"]()["versions"]["1.6"]
            assert s16["provisioned"] is True and s16["provisionedAt"] == "2026-08-14 21:03:11", s16
            assert build_public_status(g["status"](), p1)["versions"]["1.6"]["generation"] == "2026-08-14 21:03:11"
            os.remove(provisioned_marker_path("1.6"))
            # a file that reads again is never reset from a stale screen (409, degraded note cleared); force can
            before = state_bytes()
            _STATE_RECOVERY["degraded"] = "stale screen (selftest)"
            refused(lambda: reset_state(True), 409, "state_readable")
            assert state_bytes() == before and not _STATE_RECOVERY["degraded"]
            reply.clear()
            hh.rfile = io.BytesIO(b'{"confirm": true, "force": true}')
            hh.headers = {"Authorization": "Bearer selftest-token", "Content-Length": "32"}
            hh.do_POST()
            assert reply and reply[0][0] == 200 and reply[0][1]["corruptCopy"], reply
            # ...and a stack that still advertises this agent's hotpatch gets it enabled again, by a reset as by a
            # restore (reconcile_hotpatch_enabled): its dispatch keeps sending the players' clients to the mirror
            hman_ = read_hotpatch_manifest("1.6")
            if hman_ is not None:
                pc_ = os.path.join(stack, PC_VERSION_TXT)
                os.makedirs(os.path.dirname(pc_), exist_ok=True)
                write_text(pc_, render_pc_version(hman_))
                hp_log = []
                try:
                    g["log_line"] = hp_log.append
                    put(torn)
                    assert reset_state(True)["ok"] and version_state("1.6")["hotpatch"] == {"enabled": True}, \
                        load_state()
                    assert [l_ for l_ in hp_log if "hotpatch of 1.6 is enabled again after the reset" in l_], hp_log
                    with open(sp + ".bak", "w") as f:
                        json.dump({"versions": {"1.6": {"passwordVerify": True}}}, f)
                    put(torn)
                    assert recover_state_at_startup(now=1757930200) == "restored"
                    assert load_state()["versions"]["1.6"]["hotpatch"] == {"enabled": True}, load_state()
                    assert [l_ for l_ in hp_log if "hotpatch of 1.6 is enabled again after the restore" in l_], hp_log
                    # ...and the other way: a Disable of the stopped stack (its PC_version.txt removed, the record
                    # disabled, the URL columns deferred to the next start) that a .bak restore rolled back to the
                    # enabled record is disabled again -- the stack is the truth both ways --, its revert owed as the
                    # Disable left it, and the route stays closed for that version's files
                    _remove_quiet(pc_)
                    with open(sp + ".bak", "w") as f:
                        json.dump({"versions": {"1.6": {"hotpatch": {"enabled": True, "pending": False,
                                                                     "voice": ["Japanese"]}}}}, f)
                    put(torn)
                    n_log_ = len(hp_log)
                    assert recover_state_at_startup(now=1757930300) == "restored"
                    assert load_state()["versions"]["1.6"]["hotpatch"] == {"enabled": False, "pending": True,
                                                                           "voice": ["Japanese"]}, load_state()
                    assert [l_ for l_ in hp_log[n_log_:] if "disabled again" in l_] == [
                        "gio-agent: the hotpatch of 1.6 is disabled again after the restore: its stack no longer "
                        "advertises the mirror (its revert is owed: the next start of 1.6 clears the URL columns its "
                        "database may still hold)."], hp_log[n_log_:]
                    rel_ = hotpatch_res_root(hman_) + "res_versions_external"
                    assert hotpatch_route_closed(rel_) == (
                        "closed", "the hotpatch of 1.6 is not enabled on this server -- not served"), \
                        hotpatch_route_closed(rel_)
                    # ...which the next boot pays (apply_hotpatch, before the services start): never while the
                    # version's hotpatch manifest is gone (one WARNING, the revert still owed), then the URL columns
                    # cleared once, nothing owed after it -- a second boot changes nothing
                    vt_ = os.path.join(stack, DATA_VERSION_TXT)
                    os.makedirs(os.path.dirname(vt_), exist_ok=True)
                    write_text(vt_, "{}")  # the vendor's: the dispatch files already hold no hotpatch
                    sql_ = []
                    real_sql_, real_man_ = g["hotpatch_sql"], g["read_hotpatch_manifest"]
                    try:
                        g["hotpatch_sql"] = lambda v_, j_, url_, m_: sql_.append((v_, url_)) or True
                        g["read_hotpatch_manifest"] = lambda v_: None
                        j_ = _Job()
                        assert apply_hotpatch("1.6", j_) == 0 and sql_ == [] and j_.lines == [
                            "WARNING: the hotpatch is disabled in state with its revert owed but "
                            "payloads/1.6/hotpatch.json is gone -- leaving the stack alone."], j_.lines
                        assert version_state("1.6")["hotpatch"]["pending"] is True, version_state("1.6")
                        g["read_hotpatch_manifest"] = real_man_
                        assert apply_hotpatch("1.6", _Job()) == 1 and sql_ == [("1.6", None)], sql_
                        assert version_state("1.6")["hotpatch"] == {"enabled": False, "pending": False,
                                                                    "voice": ["Japanese"]}, version_state("1.6")
                        assert apply_hotpatch("1.6", _Job()) == 0 and len(sql_) == 1, sql_
                    finally:
                        g["hotpatch_sql"], g["read_hotpatch_manifest"] = real_sql_, real_man_
                        _remove_quiet(vt_)
                    assert hotpatch_route_closed(rel_)[0] == "closed"
                    # ...but only where that is certain: a PC_version.txt the restore cannot read keeps the enabled
                    # record it brought back (the route keeps serving what the dispatch may still advertise), while a
                    # version without a stack (2.8 here) advertises nothing -- its enabled record is disabled again too
                    hman28_ = read_hotpatch_manifest("2.8")
                    write_text(pc_, render_pc_version(hman_))
                    real_rt_ = g["read_text"]

                    def rt_refused_(p_, *a_, **k_):
                        if os.path.normcase(os.path.abspath(p_)) == os.path.normcase(os.path.abspath(pc_)):
                            raise PermissionError(13, "selftest")
                        return real_rt_(p_, *a_, **k_)

                    with open(sp + ".bak", "w") as f:
                        json.dump({"versions": {"1.6": {"hotpatch": {"enabled": True, "pending": False}},
                                                "2.8": {"hotpatch": {"enabled": True, "pending": False}}}}, f)
                    put(torn)
                    n_log_ = len(hp_log)
                    try:
                        g["read_text"] = rt_refused_
                        assert recover_state_at_startup(now=1757930400) == "restored"
                    finally:
                        g["read_text"] = real_rt_
                    hp_ = dict((v_, r_.get("hotpatch")) for v_, r_ in load_state()["versions"].items())
                    assert hp_["1.6"] == {"enabled": True, "pending": False} and \
                        hp_["2.8"] == {"enabled": False, "pending": False}, hp_
                    assert [l_ for l_ in hp_log[n_log_:] if "disabled again" in l_] == [
                        "gio-agent: the hotpatch of 2.8 is disabled again after the restore: its stack no longer "
                        "advertises the mirror."], hp_log[n_log_:]
                    assert hotpatch_route_closed(rel_) is None
                    if hman28_ is not None:
                        rel28_ = hotpatch_res_root(hman28_) + "res_versions_external"
                        assert hotpatch_route_closed(rel28_) == (
                            "closed", "the hotpatch of 2.8 is not enabled on this server -- not served"), \
                            hotpatch_route_closed(rel28_)
                finally:
                    g["log_line"] = lambda *_a: None
                    _remove_quiet(pc_)
            ok("state reset route OK (confirm, 409 while busy or readable, force, corrupt copy, guard, "
               "passwordVerify kept, the hotpatch a stack still advertises enabled again and one it certainly no "
               "longer advertises -- or a version without a stack -- disabled again, its revert owed where there is a "
               "stack and paid once by the next boot, never one whose stack cannot be read, marker in /status)")
        finally:
            g.update(saved_st)
            _STATE_RECOVERY.clear()
            _STATE_RECOVERY.update(saved_rec)
            _state_skip_logged.clear()
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_

    # The advertised address. The database half is recorded apart from the XML half, so an
    # XML-only pass never strands the old WAN IP in dispatch_url / the gacha URLs, and a half-failed
    # pass re-run over rows that already hold the new IP never corrupts them. Then the DDNS follower:
    # address filter, boot fallback, two-check confirmation, never a netfix for a stopped version. Last,
    # "Keep .env settings" over a stack rendered from a loopback OUTER_IP: the address applied in full.
    # Temp dir + a fake MySQL that evaluates the REPLACE chains + fake compose/start_job; no DNS, no docker.
    faked_adv = ("STATE_PATH", "ADVERTISED_IP", "ADVERTISED_HOST", "ADVERTISED_ALLOW_PRIVATE", "BIND_IP",
                 "mysql_exec", "running_projects", "_compose_stream", "verify_stack", "start_job",
                 "log_line", "_is_global_ip", "read_hotpatch_manifest", "KEEP_ENV")
    saved_adv = {k: g[k] for k in faked_adv}
    saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
    saved_follow = (dict(_ADVERTISE), dict(_next_follow), dict(_follow_refused), dict(_follow_failures))
    with tempfile.TemporaryDirectory() as td:
        try:
            stack = os.path.join(td, "1.6_live")
            conf = os.path.join(stack, "server", "dispatch", "conf")
            os.makedirs(conf)
            open(os.path.join(stack, ".bootstrap.lock"), "w").close()
            compose_path = os.path.join(stack, "docker-compose.yml")
            write_text(compose_path, 'ports:\n  - "192.0.2.57:21000:80"\n')
            write_text(os.path.join(stack, ".env"), "OUTER_IP=192.0.2.57\n")
            xml_path = os.path.join(conf, "dispatch.xml")
            write_text(xml_path, '<dispatch outer_ip="192.0.2.57" peer="172.10.3.8" />\n')
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = stack, _project_name(stack)
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = "", ""
            logs = []
            g.update({"STATE_PATH": os.path.join(td, "state.json"), "ADVERTISED_HOST": "", "BIND_IP": "",
                      "ADVERTISED_ALLOW_PRIVATE": False, "log_line": logs.append,
                      "read_hotpatch_manifest": lambda _v: None})
            _ADVERTISE.update(checkedAt=None, error=None, pending=None, loggedError=None)
            _next_follow.clear()
            _follow_refused.clear()
            _follow_failures.clear()

            # a fake MySQL holding the seven client-facing URL columns; an UPDATE is evaluated (the
            # REPLACE chain, innermost first) or fails as a whole, like the real statement
            cols = {"t_region_config": ["dispatch_url"],
                    "t_gacha_newbie_url_config": ["gacha_prob_url", "gacha_record_url"],
                    "t_gacha_schedule_config": ["gacha_prob_url", "gacha_record_url",
                                                "gacha_prob_url_oversea", "gacha_record_url_oversea"]}
            dbv = {t: {c: "http://127.0.0.1:21000/%s/%s" % (t, c) for c in cs} for t, cs in cols.items()}
            fail = {}  # table -> the stderr its UPDATE answers
            innermost = re.compile(r"REPLACE\('([^']*)', '([^']*)', '([^']*)'\)")

            def fake_mysql(version, sql, db=None, timeout=300, password=None):
                m = re.match(r"UPDATE \w+\.(\w+) SET (.*)$", sql, re.S)
                if not m:
                    return subprocess.CompletedProcess([], 0, stdout="", stderr="")
                table = m.group(1)
                if table in fail:
                    return subprocess.CompletedProcess([], 1, stdout="", stderr=fail[table])
                new_vals = {}
                for part in re.split(r", (?=\w+ = REPLACE\()", m.group(2)):
                    col, expr = part.split(" = ", 1)
                    expr = expr.replace("(%s, " % col, "('%s', " % dbv[table][col], 1)
                    n = 1
                    while n:
                        expr, n = innermost.subn(lambda r: "'%s'" % r.group(1).replace(r.group(2), r.group(3)), expr)
                    new_vals[col] = expr.strip("'")
                dbv[table].update(new_vals)
                return subprocess.CompletedProcess([], 0, stdout="", stderr="")

            def all_db():
                return [u for t in dbv.values() for u in t.values()]

            def db_is(ip):
                return all(u.startswith("http://%s:21000/" % ip) for u in all_db())

            mysql_exec = fake_mysql
            # (1) a full pass: XML + database rewritten (the vendor 127.0.0.1 too), both halves recorded
            ADVERTISED_IP = "198.51.100.171"
            apply_advertised_ip("1.6", _Job(), with_sql=True)
            vs = version_state("1.6")
            assert vs["advertisedIp"] == vs["advertisedIpSql"] == "198.51.100.171" and vs["advertisedIpSqlOwed"] == [], vs
            assert db_is("198.51.100.171"), dbv
            assert 'outer_ip="198.51.100.171"' in read_text(xml_path) and "172.10.3.8" in read_text(xml_path)
            assert not advertised_lags("1.6") and advertised_sql_current("1.6")
            # (2) the address changes while the stack is stopped: XML only (netfix on a stopped stack) --
            #     the old WAN IP stays owed, and the next database pass still replaces it
            ADVERTISED_IP = "203.0.113.17"
            apply_advertised_ip("1.6", _Job(), with_sql=False)
            vs = version_state("1.6")
            assert vs["advertisedIp"] == "203.0.113.17" and vs["advertisedIpSql"] == "198.51.100.171", vs
            assert vs["advertisedIpSqlOwed"] == ["198.51.100.171"] and db_is("198.51.100.171"), (vs, dbv)
            assert advertised_lags("1.6") and not advertised_sql_current("1.6")
            apply_advertised_ip("1.6", _Job(), with_sql=True)
            assert db_is("203.0.113.17"), "the old WAN IP must not be stranded in the database: %r" % dbv
            assert version_state("1.6")["advertisedIpSql"] == "203.0.113.17" and not advertised_lags("1.6")
            # (3) a failed UPDATE does not advance advertisedIpSql; the new IP is a prefix of the old one
            ADVERTISED_IP = "203.0.113.1"
            fail["t_gacha_schedule_config"] = "ERROR 2013 (HY000): Lost connection to server during query"
            j3 = _Job()
            apply_advertised_ip("1.6", j3, with_sql=True)
            vs = version_state("1.6")
            assert vs["advertisedIpSql"] == "203.0.113.17" and vs["advertisedIpSqlOwed"] == ["203.0.113.17"], vs
            assert dbv["t_region_config"]["dispatch_url"].startswith("http://203.0.113.1:")
            assert dbv["t_gacha_schedule_config"]["gacha_prob_url"].startswith("http://203.0.113.17:"), dbv
            assert any("did not complete" in l for l in j3.lines) and any("(ignored)" in l for l in j3.lines), j3.lines
            del fail["t_gacha_schedule_config"]
            apply_advertised_ip("1.6", _Job(), with_sql=True)
            assert db_is("203.0.113.1") and advertised_sql_current("1.6"), dbv
            # (4) the other way round: an owed old IP that is a PREFIX of the new one, re-run over rows the
            #     failed pass already moved -- a bare REPLACE would turn 203.0.113.17 into 203.0.113.177
            ADVERTISED_IP = "203.0.113.17"
            fail["t_gacha_newbie_url_config"] = "ERROR 2002 (HY000): Can't connect to local server through socket"
            apply_advertised_ip("1.6", _Job(), with_sql=True)
            assert dbv["t_region_config"]["dispatch_url"].startswith("http://203.0.113.17:") and not advertised_sql_current("1.6")
            del fail["t_gacha_newbie_url_config"]
            apply_advertised_ip("1.6", _Job(), with_sql=True)
            assert db_is("203.0.113.17") and not any("203.0.113.177" in u for u in all_db()), dbv
            chain = _sql_ip_rewrite("c", ["192.0.2.57", "203.0.113.17"], "203.0.113.1")
            assert chain.index("'203.0.113.17'") < chain.index("'203.0.113.1', '{relic-advertised}'"), \
                "an old IP containing the new one is rewritten before the new one is parked: " + chain
            # (5) a table this version does not have counts as done -- there is nothing in it to rewrite
            ADVERTISED_IP = "198.51.100.171"
            fail["t_gacha_newbie_url_config"] = ("ERROR 1146 (42S02) at line 1: Table "
                                                 "'hk4e_db_config.t_gacha_newbie_url_config' doesn't exist")
            j5 = _Job()
            apply_advertised_ip("1.6", j5, with_sql=True)
            assert advertised_sql_current("1.6") and any("not in this version" in l for l in j5.lines), j5.lines
            del fail["t_gacha_newbie_url_config"]
            # (the fake kept rows a version without that table would not have: align them)
            dbv["t_gacha_newbie_url_config"] = {c: "http://198.51.100.171:21000/n/" + c for c in cols["t_gacha_newbie_url_config"]}
            fail["t_region_config"] = "ERROR 1146 (42S02) at line 1: Table 'x' doesn't exist"
            try:
                run_sql("1.6", _Job(), ["UPDATE hk4e_db_deploy_config.t_region_config SET dispatch_url = 'x'"])
                raise AssertionError("missing_ok is opt-in: a plain run_sql must still fail loudly")
            except AgentError as e:
                assert "SQL failed" in e.message
            del fail["t_region_config"]
            # (6) the record is lost (a state reset): the address dispatch.xml holds is still an old IP, so a
            #     pass to a new address rewrites the XMLs AND the database rows the lost record knew about
            assert DISPATCH_OUTER_IP_RE.search("<outer_ip> 203.0.113.5</outer_ip>").group(1) == "203.0.113.5"
            assert dispatch_outer_ip("1.6") == "198.51.100.171"
            saved_rec6 = dict(_STATE_RECOVERY)
            try:
                with open(STATE_PATH, "wb") as f:
                    f.write(b"{torn")
                assert reset_state(True)["ok"] and not version_state("1.6"), load_state()
                ADVERTISED_IP = "203.0.113.50"
                apply_advertised_ip("1.6", _Job(), with_sql=True)
                assert 'outer_ip="203.0.113.50"' in read_text(xml_path) and db_is("203.0.113.50"), (read_text(xml_path), dbv)
            finally:
                _STATE_RECOVERY.clear()
                _STATE_RECOVERY.update(saved_rec6)
            ADVERTISED_IP = "198.51.100.171"  # back to what the steps below expect the stack to hold
            apply_advertised_ip("1.6", _Job(), with_sql=True)
            assert db_is("198.51.100.171") and not advertised_lags("1.6"), dbv
            ok("advertised IP: the database half is recorded apart (XML-only pass, failed UPDATE, missing "
               "table), the REPLACE chain is prefix-safe over rows already moved, a lost record falls back to "
               "the address dispatch.xml holds")

            # -- the DDNS follower --
            assert _advertised_config({"GIO_ADVERTISED_HOST": " game.example.com. ",
                                       "GIO_ADVERTISED_IP": "198.51.100.171"}) == ("game.example.com", "", True)
            assert _advertised_config({"GIO_ADVERTISED_IP": " 198.51.100.171 "}) == ("", "198.51.100.171", False)
            assert _advertised_config({"GIO_ADVERTISED_HOST": " "}) == ("", "", False)
            assert (_parse_check_every("5"), _parse_check_every(""), _parse_check_every("x"),
                    _parse_check_every("300")) == (30, 120, 120, 300)
            # the filter with ipaddress' real verdicts -- documentation ranges are not public either
            for bad in ("10.0.0.5", "192.168.0.10", "172.16.4.4", "100.64.0.1", "127.0.0.1", "169.254.1.1",
                        "0.0.0.0", "0.1.2.3", "224.0.0.1", "240.0.0.1", "198.51.100.171", "2001:db8::1", "x", ""):
                assert not advertisable_ip(bad, False), bad
            for priv in ("10.0.0.5", "192.168.0.10", "172.16.4.4"):
                assert advertisable_ip(priv, True), priv
            for never in ("100.64.0.1", "127.0.0.1", "169.254.1.1", "224.0.0.1", "0.0.0.0", "198.18.0.1"):
                assert not advertisable_ip(never, True), never
            doc_nets = (ipaddress.ip_network("198.51.100.0/24"), ipaddress.ip_network("203.0.113.0/24"))
            g["_is_global_ip"] = lambda ip: ip.is_global or any(ip in n for n in doc_nets)

            def answers(*addrs):
                return lambda _host: list(addrs)

            def gaierror(_host):
                raise socket.gaierror(-2, "Name or service not known")

            r = _resolve_advertised("game.example.com", answers("10.0.0.5", "100.64.1.1", "127.0.0.1"), allow_private=False)
            assert r[0] is None and "ALLOW_PRIVATE" in r[1], r
            assert _resolve_advertised("game.example.com", answers("10.0.0.5", "100.64.1.1", "127.0.0.1"),
                                       allow_private=True) == ("10.0.0.5", None)
            multi = answers("203.0.113.9", "198.51.100.171", "203.0.113.9")
            assert _resolve_advertised("game.example.com", multi, current="203.0.113.9") == ("203.0.113.9", None), \
                "the current A record is kept (no flapping between records)"
            assert _resolve_advertised("game.example.com", multi, current="203.0.113.50") == ("198.51.100.171", None)
            assert "cannot resolve" in _resolve_advertised("game.example.com", gaierror)[1]
            assert "no IPv4" in _resolve_advertised("game.example.com", answers())[1]
            gate = threading.Event()
            assert "no DNS answer" in _resolve_advertised("game.example.com", lambda _h: gate.wait(5) and [], timeout=0.2)[1]
            assert "not returned yet" in _resolve_advertised("game.example.com", answers("203.0.113.9"))[1], \
                "never a second lookup thread while one hangs"
            gate.set()
            _advertise_lookup["thread"].join(5)
            assert _resolve_advertised("game.example.com", answers("203.0.113.9")) == ("203.0.113.9", None)
            ok("advertised host: config precedence (host wins), address filter (private/CGNAT/loopback/reserved, "
               "ALLOW_PRIVATE), keep-current among A records, lookup timeout without piling threads")

            # boot: never confirmed + DNS down -> nothing advertised, yet the box stays "reachable"
            ADVERTISED_HOST, ADVERTISED_IP = "game.example.com", ""
            fake_t = [0.0]

            def fake_sleep(s):
                fake_t[0] += s

            assert resolve_advertised_at_boot(gaierror, budget=6, sleep=fake_sleep, clock=lambda: fake_t[0]) == "unresolved"
            assert fake_t[0] >= 4, "a fast-failing lookup is retried inside the budget"
            assert ADVERTISED_IP == "" and advertise_intent() and reachable_intent()
            write_text(compose_path, 'ports:\n  - "127.0.0.1:21000:80"\n')
            assert compose_binds_loopback("1.6"), "an unresolved host keeps the loopback-render guard armed"
            write_text(compose_path, 'ports:\n  - "192.0.2.57:21000:80"\n')
            BIND_IP = "127.0.0.1"
            try:
                ensure_bind_ip("1.6", _Job())
                raise AssertionError("a loopback bind IP with an (unresolved) advertised host must be refused")
            except AgentError as e:
                assert "loopback" in e.message, e.message
            BIND_IP = ""
            assert hotpatch_public_url("1.6", {"branch": "1.6_live"}, strict=False)[0] is None, \
                "an unresolved host never falls back to a LAN mirror URL"
            assert apply_advertised_ip("1.6", _Job()) == 0
            assert resolve_advertised_at_boot(answers("203.0.113.9"), sleep=fake_sleep, clock=lambda: fake_t[0]) == "resolved"
            assert ADVERTISED_IP == "203.0.113.9" and load_state()["advertisedResolvedIp"] == "203.0.113.9"
            ADVERTISED_IP = ""
            assert resolve_advertised_at_boot(gaierror, budget=3, sleep=fake_sleep, clock=lambda: fake_t[0]) == "fallback"
            assert ADVERTISED_IP == "203.0.113.9", "DNS down at boot: the last confirmed address"
            ok("advertised host at boot: resolved + remembered, fallback to advertisedResolvedIp, an unresolved "
               "host keeps reachable intent (bind guard, loopback-render guard, no LAN mirror URL)")

            # the watchdog -- nothing running: two identical answers, then only the address is swapped
            started, busy = [], [False]

            def fake_start_job(kind, version, fn, **_kw):
                if busy[0]:
                    raise AgentError(409, "busy (selftest)")
                started.append((kind, version, fn))
                return Job(kind, version, job_id="follow-%d" % len(started))

            g["start_job"] = fake_start_job
            running_projects = lambda: ([], None)  # noqa: E731
            _ADVERTISE.update(pending=None, error=None, loggedError=None)
            new = answers("203.0.113.50")
            assert advertise_tick(new) == "pending" and ADVERTISED_IP == "203.0.113.9"
            assert advertise_tick(gaierror) == "error" and _ADVERTISE["pending"] is None and _ADVERTISE["error"], \
                "a failed lookup breaks the run of identical answers"
            assert advertise_tick(new) == "pending" and _ADVERTISE["pending"] == "203.0.113.50"
            assert advertise_tick(new) == "swapped" and ADVERTISED_IP == "203.0.113.50" and not started
            assert load_state()["advertisedResolvedIp"] == "203.0.113.50" and _ADVERTISE["error"] is None
            # listed by compose but not vouched for by runningOk: a stopped stack for the follower
            running_projects = lambda: ([VERSIONS["1.6"]["project"]], None)  # noqa: E731
            version_state_set("1.6", runningOk=False)
            assert advertise_tick(new) == "idle" and not started, "never a netfix for a version that is not up"
            # a running stack: a 409 keeps the confirmation, the next sweep starts the netfix job
            ADVERTISED_IP = "198.51.100.171"  # what the stack holds (step 5): nothing lags
            version_state_set("1.6", runningOk=True)
            nxt = answers("203.0.113.60")
            busy[0] = True
            assert advertise_tick(nxt) == "pending"
            assert advertise_tick(nxt) == "busy" and _ADVERTISE["pending"] == "203.0.113.60"
            busy[0] = False
            assert advertise_tick(nxt) == "job" and [(k, v) for k, v, _f in started] == [("netfix", "1.6")]
            assert ADVERTISED_IP == "198.51.100.171", "the address changes inside the job, under _op_lock"
            assert _next_follow["1.6"] > time.time() + 800 and _ADVERTISE["pending"] is None
            verified, restarted = [], []
            verify_stack = lambda v, j, rounds=0: verified.append(v)  # noqa: E731
            _compose_stream = lambda d, j, *a, **k: restarted.append(a) or 0  # noqa: E731
            jf = _Job()
            with _op_lock:
                res = started[0][2](jf)
            assert res == {"advertisedIp": "203.0.113.60", "netfix": True, "restarted": True}, (res, jf.lines)
            assert ADVERTISED_IP == "203.0.113.60" and db_is("203.0.113.60"), dbv
            assert 'outer_ip="203.0.113.60"' in read_text(xml_path) and verified == ["1.6"]
            assert restarted and restarted[0][0] == "restart" and not advertised_lags("1.6"), restarted
            # a follow whose database half fails: the job fails, the backoff holds, the catch-up retries
            started.clear()
            _next_follow.clear()
            fail["t_region_config"] = "ERROR 2013 (HY000): Lost connection to server during query"
            nxt2 = answers("203.0.113.70")
            assert advertise_tick(nxt2) == "pending" and advertise_tick(nxt2) == "job"
            n_restarts, n_verified = len(restarted), len(verified)
            try:
                with _op_lock:
                    started[0][2](_Job())
                raise AssertionError("a follow whose database half failed must fail its job")
            except AgentError as e:
                assert e.status == 500 and "database half" in e.message and "15 minutes" in e.message, e.message
            assert ADVERTISED_IP == "203.0.113.70" and advertised_lags("1.6")
            assert len(restarted) == n_restarts + 1, "the first follow is the full netfix: it restarts"
            assert _follow_failures["1.6"]["count"] == 1 and "database half" in (follow_error() or ""), _follow_failures
            assert advertise_tick(nxt2) == "idle" and len(started) == 1, "no retry inside the backoff"
            # the database half keeps failing: every catch-up retries only the database -- no restart, no
            # kicked players -- and waits twice as long as the one before
            for n, wait in ((2, 1800), (3, 3600)):
                _next_follow["1.6"] = 0
                assert advertise_tick(nxt2) == "idle", "the failure backoff outlasts the plain one"
                _follow_failures["1.6"]["retryAt"] = 0
                assert advertise_tick(nxt2) == "job" and len(started) == n
                jr = _Job()
                try:
                    with _op_lock:
                        started[-1][2](jr)
                    raise AssertionError("the database half still fails")
                except AgentError as e:
                    assert "%d minutes" % (wait // 60) in e.message, e.message
                assert len(restarted) == n_restarts + 1 and any("not restarting" in l for l in jr.lines), jr.lines
                assert _follow_failures["1.6"]["count"] == n and _follow_failures["1.6"]["retryAt"] > time.time() + wait - 60
            _next_follow["1.6"] = 0
            assert not _follow_blocked("1.6") and _follow_blocked("1.6", retry=True), \
                "a confirmed address change is not held back by the failure backoff"
            _follow_failures["0.0"] = {"count": 30}
            assert _follow_failed("0.0", "selftest") == ADVERTISE_RETRY_MAX
            del _follow_failures["0.0"]
            # the database answers again: the retry completes it and restarts the services once
            del fail["t_region_config"]
            _follow_failures["1.6"]["retryAt"] = 0
            assert advertise_tick(nxt2) == "job" and len(started) == 4, "the catch-up retries after the backoff"
            with _op_lock:
                assert started[-1][2](_Job()) == {"advertisedIp": "203.0.113.70", "netfix": True, "restarted": True}
            assert len(restarted) == n_restarts + 2 and len(verified) == n_verified + 2, (restarted, verified)
            assert db_is("203.0.113.70") and not advertised_lags("1.6") and follow_error() is None, dbv
            # healed by something else (a start, a manual netfix): the next sweep forgets the failures
            _follow_failures["1.6"] = {"count": 2, "retryAt": time.time() + 900, "error": "selftest"}
            _next_follow["1.6"] = 0
            assert advertise_tick(nxt2) == "idle" and "1.6" not in _follow_failures
            # a stack never advertised before whose first database half fails (the address arrived while it
            # ran, or its start raced MySQL): no old IP is owed, yet the failure must stay visible and the
            # catch-up must retry it -- the half is recorded as never done
            vrec = load_state()
            for k in ("advertisedIp", "advertisedIpSql", "advertisedIpSqlOwed"):
                vrec["versions"]["1.6"].pop(k, None)
            save_state(vrec, strict=True)
            fail["t_region_config"] = "ERROR 2013 (HY000): Lost connection to server during query"
            apply_advertised_ip("1.6", _Job(), with_sql=True)
            vs = version_state("1.6")
            assert "advertisedIpSql" in vs and vs["advertisedIpSql"] is None and advertised_lags("1.6"), vs
            started.clear()
            _next_follow.clear()
            _follow_failures["1.6"] = {"count": 1, "retryAt": 0, "error": "selftest"}
            assert advertise_tick(nxt2) == "job" and len(started) == 1 and follow_error() == "selftest", \
                "a failed first database half is retried, and its failure is not wiped as healed"
            del fail["t_region_config"]
            n_restarts = len(restarted)
            with _op_lock:
                assert started[-1][2](_Job()) == {"advertisedIp": "203.0.113.70", "netfix": True, "restarted": True}
            assert len(restarted) == n_restarts + 1 and not advertised_lags("1.6") and follow_error() is None
            # a skipped database half over a record without advertisedIpSql that vouches for the address: no change
            vrec = load_state()
            vrec["versions"]["1.6"].pop("advertisedIpSql")
            save_state(vrec, strict=True)
            apply_advertised_ip("1.6", _Job(), with_sql=False)
            assert "advertisedIpSql" not in version_state("1.6") and not advertised_lags("1.6"), version_state("1.6")
            version_state_set("1.6", advertisedIpSql="203.0.113.70")
            # a change confirmed inside the plain backoff is only swapped; the config files are then behind
            # the address, so the first sweep after the plain backoff starts the job -- never held by the
            # failure backoff meant for database-only retries
            started.clear()
            _next_follow["1.6"] = time.time() + 600
            _follow_failures["1.6"] = {"count": 3, "retryAt": time.time() + 3600, "error": "selftest"}
            nxt4 = answers("203.0.113.85")
            assert advertise_tick(nxt4) == "pending" and advertise_tick(nxt4) == "swapped" and not started
            assert ADVERTISED_IP == "203.0.113.85" and advertise_tick(nxt4) == "idle" and not started
            _next_follow["1.6"] = 0
            assert advertise_tick(nxt4) == "job" and len(started) == 1, "stale config files wait only the plain backoff"
            started.clear()
            _next_follow.clear()
            _follow_failures.clear()
            ADVERTISED_IP = "203.0.113.70"
            # a stack gone by the time its job runs is not netfixed; the address is swapped all the same
            running_projects = lambda: ([], None)  # noqa: E731
            n_restarts = len(restarted)
            with _op_lock:
                assert do_advertise_follow("1.6", _Job(), "203.0.113.75") == {"advertisedIp": "203.0.113.75", "netfix": False}
            assert ADVERTISED_IP == "203.0.113.75" and len(restarted) == n_restarts
            ADVERTISED_IP = "203.0.113.70"
            running_projects = lambda: ([VERSIONS["1.6"]["project"]], None)  # noqa: E731
            # a loopback-rendered stack: no netfix job (it would 409 every sweep), refusal logged once
            write_text(compose_path, 'ports:\n  - "127.0.0.1:21000:80"\n')
            started.clear()
            _next_follow.clear()
            del logs[:]
            nxt3 = answers("203.0.113.80")
            assert advertise_tick(nxt3) == "pending" and advertise_tick(nxt3) == "swapped" and not started
            assert advertise_tick(nxt3) == "idle" and advertise_tick(nxt3) == "idle" and not started
            assert sum("127.0.0.1" in l for l in logs) == 1, logs
            write_text(compose_path, 'ports:\n  - "192.0.2.57:21000:80"\n')
            # admin /status carries the follower; /public/status carries no address at all
            running_projects = lambda: ([], None)  # noqa: E731
            full = g["status"]()
            assert full["advertisedHost"] == "game.example.com" and full["advertisedIp"] == "203.0.113.80", full
            assert full["advertisedCheckedAt"] and full["advertisedError"] is None and full["advertisedPending"] is None
            assert full["versions"]["1.6"]["advertisedIpSql"] == "203.0.113.70", full["versions"]["1.6"]
            pub = json.dumps(build_public_status(full, get_policy()))
            assert "203.0.113" not in pub and "game.example.com" not in pub and "advertised" not in pub, pub
            ADVERTISED_HOST = ""
            assert advertise_tick(nxt3) == "off"
            ok("advertise watchdog: two-check confirmation, 409 keeps it, swap only for stopped / unvouched / "
               "loopback-rendered stacks, follow job re-applies both halves + verify, a failed follow backs off "
               "then catches up; /public/status carries no address")

            # -- "Keep .env settings" over a stack rendered from a loopback OUTER_IP --
            # The package's .env (OUTER_IP=127.0.0.1) kept as it is: no render guard stands in front of the
            # pass there, and the advertised address is applied in FULL -- the outer_ip that holds a loopback
            # address is rewritten too (attribute and element form, CRLF / LF kept) and nothing else that points
            # at 127.0.0.1 -- so the XMLs, the database and the record name ONE address. First the pattern alone:
            for text, want in (('outer_ip="127.0.0.1"', 'outer_ip="A"'),
                               ("outer_ip = '127.0.0.53' x", "outer_ip = 'A' x"),
                               ("<outer_ip>\r\n  127.0.0.1</outer_ip>", "<outer_ip>\r\n  A</outer_ip>"),
                               ('router_ip="127.0.0.1"', None), ('outer_ip2="127.0.0.1"', None),
                               ('addr="127.0.0.1"', None), ('my-outer_ip="127.0.0.1"', None),
                               ('outer_ip="127.0.0.1.9"', None), ('outer_ip="192.0.2.127"', None),
                               ("<outer_ip>192.0.2.5</outer_ip> 127.0.0.1", None)):
                assert LOOPBACK_OUTER_IP_RE.sub(lambda m: m.group(1) + "A", text) == (want or text), text
            keep = os.path.join(td, "keep", "1.6_live")
            # two conf files: the outer_ip the clients are handed (attribute form in a CRLF file, element form
            # in an LF one) beside entries that point at the box itself and must keep doing so
            kept_tmpl = {
                "dispatch": '<Root>\r\n  <Server id="1" host="172.10.3.1" inner_ip="172.10.3.1" '
                            'outer_ip="%(outer)s" />\r\n'
                            '  <Redis addr="%(lan)s" router_ip="%(lan)s" outer_ip2="%(lan)s" />\r\n</Root>\r\n',
                "gateserver": "<Root>\n  <outer_ip> %(outer)s </outer_ip>\n  <local>%(lan)s</local>\n</Root>\n"}

            def kept_path(name):
                return os.path.join(keep, "server", name, "conf", name + ".xml")

            def kept_on(ip, lan="127.0.0.1"):
                """What the conf files hold while their outer_ip names `ip` -- every other byte as rendered."""
                return {name: text % {"outer": ip, "lan": lan} for name, text in kept_tmpl.items()}

            def kept_render(lan="127.0.0.1", database=True):
                """The stack as its own .env renders it: every conf file -- and URL column -- on `lan`."""
                write_text(os.path.join(keep, ".env"), "OUTER_IP=%s\n" % lan)
                for name, text in kept_on(lan, lan).items():
                    write_text(kept_path(name), text)
                for t, cs in cols.items() if database else ():
                    dbv[t] = {c: "http://%s:21000/%s/%s" % (lan, t, c) for c in cs}

            def kept_now():
                return {name: read_text(kept_path(name)) for name in kept_tmpl}

            def kept_holds(ip):
                """The XMLs, the record (both halves, nothing owed) and the database all name `ip`."""
                rec_ = version_state("1.6")
                return (kept_now() == kept_on(ip) and db_is(ip) and dispatch_outer_ip("1.6") == ip
                        and (rec_.get("advertisedIp"), rec_.get("advertisedIpSql"), rec_.get("advertisedIpSqlOwed"))
                        == (ip, ip, []) and not advertised_lags("1.6"))

            for name in kept_tmpl:
                os.makedirs(os.path.dirname(kept_path(name)))
            open(os.path.join(keep, ".bootstrap.lock"), "w").close()
            write_text(os.path.join(keep, "docker-compose.yml"), 'ports:\n  - "127.0.0.1:21000:80"\n')
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = keep, _project_name(keep)
            STATE_PATH = os.path.join(td, "keep-state.json")
            ADVERTISED_HOST, ADVERTISED_IP = "", "198.51.100.171"
            running_projects = lambda: ([VERSIONS["1.6"]["project"]], None)  # noqa: E731
            # the switch off: the render guards are armed, and a pass that reaches such a stack all the same
            # leaves its XMLs alone (only the URL columns and the record take the address)
            kept_render()
            assert compose_binds_loopback("1.6") and _follow_blocked("1.6")
            assert apply_advertised_ip("1.6", _Job(), with_sql=True) == 0 and kept_now() == kept_on("127.0.0.1"), \
                kept_now()
            assert db_is("198.51.100.171") and version_state("1.6")["advertisedIp"] == "198.51.100.171", dbv
            os.remove(STATE_PATH)
            _follow_refused.clear()
            # the switch on: all three move together
            KEEP_ENV = True
            kept_render()
            assert not compose_binds_loopback("1.6") and not _follow_blocked("1.6")
            jk = _Job()
            assert apply_advertised_ip("1.6", jk, with_sql=True) == 2 and kept_holds("198.51.100.171"), \
                (kept_now(), version_state("1.6"), dbv)
            assert jk.lines[0] == "Setting the advertised IP: 127.0.0.1 -> 198.51.100.171", jk.lines
            # a second pass changes nothing
            rec_before = version_state("1.6")
            assert apply_advertised_ip("1.6", _Job(), with_sql=True) == 0 and kept_holds("198.51.100.171") \
                and version_state("1.6") == rec_before, (kept_now(), version_state("1.6"))
            # a changed advertised address moves all three, through the ordinary old -> new chain
            ADVERTISED_IP = "203.0.113.17"
            assert advertised_lags("1.6")
            assert apply_advertised_ip("1.6", _Job(), with_sql=True) == 2 and kept_holds("203.0.113.17"), \
                (kept_now(), version_state("1.6"), dbv)
            # a re-render (a secrets rotation) puts the loopback address back into the XMLs while the record
            # keeps naming the advertised one: the XML-only pass that follows it is never "already there"
            rec_before = version_state("1.6")
            kept_render(database=False)
            assert kept_now() == kept_on("127.0.0.1") and not advertised_lags("1.6")
            assert apply_advertised_ip("1.6", _Job(), with_sql=False) == 2 and kept_holds("203.0.113.17") \
                and version_state("1.6") == rec_before, (kept_now(), version_state("1.6"))
            # ...and through the real netfix and the follower: such a stack is not held back as "rendered on
            # loopback", a confirmed change is ONE full netfix (XML + database + one restart) whose result says
            # so, and then nothing lags -- no second job, no further restart
            assert do_netfix("1.6", _Job()) == {"xml": True, "sql": True} and kept_holds("203.0.113.17")
            ADVERTISED_HOST = "game.example.com"
            version_state_set("1.6", runningOk=True)
            _ADVERTISE.update(pending=None, error=None, loggedError=None)
            for box in (started, _next_follow, _follow_failures, _follow_refused):
                box.clear()
            nxt5 = answers("203.0.113.90")
            assert advertise_tick(nxt5) == "pending" and advertise_tick(nxt5) == "job" and len(started) == 1
            n_restarts, n_verified = len(restarted), len(verified)
            with _op_lock:
                assert started[-1][2](_Job()) == {"advertisedIp": "203.0.113.90", "netfix": True, "restarted": True}
            assert kept_holds("203.0.113.90") and (len(restarted), len(verified)) == (n_restarts + 1, n_verified + 1)
            _next_follow.clear()
            assert advertise_tick(nxt5) == "idle" and len(started) == 1 and follow_error() is None
            # a database half that fails there is retried alone: the XMLs already name the address, so nothing
            # the services read at boot changed and nothing is restarted
            fail["t_region_config"] = "ERROR 2013 (HY000): Lost connection to server during query"
            nxt6 = answers("203.0.113.95")
            assert advertise_tick(nxt6) == "pending" and advertise_tick(nxt6) == "job" and len(started) == 2
            for retry in (False, True):
                if retry:
                    _next_follow.clear()
                    _follow_failures["1.6"]["retryAt"] = 0
                    assert advertise_tick(nxt6) == "job" and len(started) == 3
                n_restarts = len(restarted)
                jr = _Job()
                try:
                    with _op_lock:
                        started[-1][2](jr)
                    raise AssertionError("a follow whose database half failed must fail its job")
                except AgentError as e:
                    assert e.status == 500 and "database half" in e.message, e.message
                assert kept_now() == kept_on("203.0.113.95") and advertised_lags("1.6"), kept_now()
                assert len(restarted) == n_restarts + (not retry) \
                    and any("not restarting" in l for l in jr.lines) is retry, (retry, jr.lines)
            del fail["t_region_config"]
            # a stack kept on ANOTHER loopback address: that address is what its own render put into the URL
            # columns, so the database half replaces it as well
            ADVERTISED_HOST, ADVERTISED_IP = "", "198.51.100.171"
            os.remove(STATE_PATH)
            kept_render("127.0.0.5")
            assert apply_advertised_ip("1.6", _Job(), with_sql=True) == 2 and db_is("198.51.100.171") \
                and kept_now() == kept_on("198.51.100.171", lan="127.0.0.5") and not advertised_lags("1.6"), \
                (kept_now(), dbv)
            # ...and an advertised address that IS the stack's own loopback address leaves nothing to rewrite
            ADVERTISED_IP = "127.0.0.5"
            os.remove(STATE_PATH)
            kept_render("127.0.0.5")
            jk = _Job()
            assert apply_advertised_ip("1.6", jk, with_sql=False) == 0 \
                and jk.lines == ["The advertised IP is already 127.0.0.5."] \
                and kept_now() == kept_on("127.0.0.5", lan="127.0.0.5"), (jk.lines, kept_now())
            KEEP_ENV = False
            ok("\"Keep .env settings\" + advertised address OK (a stack rendered from a loopback OUTER_IP: the "
               "outer_ip attribute / element rewritten and nothing else on 127.0.0.1, line endings kept; XML, "
               "record and database on ONE address; a second pass changes nothing; a changed address moves all "
               "three; an XML-only pass after a re-render; netfix + the follower: not blocked, one restart, then "
               "idle, a failing database half retried without a restart; another loopback address; with the "
               "switch off the XMLs are left alone)")
        finally:
            g.update(saved_adv)
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_
            _ADVERTISE.clear()
            _ADVERTISE.update(saved_follow[0])
            _next_follow.clear()
            _next_follow.update(saved_follow[1])
            _follow_refused.clear()
            _follow_refused.update(saved_follow[2])
            _follow_failures.clear()
            _follow_failures.update(saved_follow[3])

    # SERVER PACKAGE DOWNLOAD: the shipped catalogues, the validator, the extractor
    # command lines, the probe rule, the bundle-dir guard, the nested 2.8 layout heal, the status
    # brief (never public) and a dry run of the fetch job with a fake downloader + extractor.
    # A catalogue is OPTIONAL by contract (no stack.json = this version cannot be downloaded, the
    # admin brings the package) -- an installed box whose GIO_PAYLOAD_DIR holds none must not have
    # its upgrade aborted here; what IS shipped is validated.
    for v in VERSIONS:
        cat = read_stack_catalog(v)
        if cat is None:
            log_line("selftest: no stack catalogue for %s (a version that cannot be downloaded) -- skipped" % v)
            continue
        assert validate_stack_catalog(cat), "payloads/%s/stack.json invalid" % v
        assert cat["version"] == v and cat["label"] == "Internet Archive", cat
        for arc in stack_archives(cat):  # its own archive and every alternate: one host, one tree
            assert urllib.parse.urlsplit(arc["url"]).hostname == "archive.org" and cat["extractedSize"] > arc["size"], \
                (v, arc)
        # ...and what its archive unpacks to is the version's row of PAYLOAD_EXPECT: a row without a `stack`
        # holds the catalogue to the rules above alone, a version without a row has no business shipping one
        assert v in PAYLOAD_EXPECT, \
            "payloads/%s/stack.json: no row for version %s in PAYLOAD_EXPECT -- a catalogue nobody described" % (v, v)
        expect = PAYLOAD_EXPECT[v]["stack"]
        assert expect is None or (cat["topDir"] == expect["topDir"] and cat["strays"] == expect["strays"]), (v, cat)
    good = {"url": "https://archive.org/download/x/y.7z", "size": 10, "md5": "a" * 32, "extractedSize": 30,
            "topDir": "1.6_live", "strays": ["data.txt"]}
    for bad in (dict(good, url="http://archive.org/x.7z"), dict(good, url="file:///x.7z"), dict(good, url="https://a b/x"),
                dict(good, topDir="../x"), dict(good, topDir="a/b"), dict(good, topDir="a\\b"), dict(good, topDir=".hidden"),
                dict(good, topDir=""), dict(good, md5="a" * 31), dict(good, md5="g" * 32), dict(good, size=0),
                dict(good, size=True), dict(good, size="10"), dict(good, strays=["a/b"]), dict(good, strays="data.txt"),
                dict(good, extractedSize=-1), "nope", None):
        try:
            validate_stack_catalog(bad)
            raise AssertionError("must refuse %r" % (bad,))
        except ValueError:
            pass
    assert validate_stack_catalog(dict(good, strays=[])) and validate_stack_catalog({k: x for k, x in good.items() if k != "strays"})
    # the format of an archive is the extension of its address -- .7z or .zip, nothing else --, and a
    # catalogue may name the same tree in the other format under `alt`: each entry held to the rules of
    # the catalogue's own archive, no two archives of one format
    zipped = {"url": "https://archive.org/download/x/y.zip", "size": 20, "md5": "B" * 32}
    both = dict(good, alt=[zipped])
    for bad, why in ((dict(good, url="https://archive.org/download/x/y.rar"), "url must name a .7z or .zip file"),
                     (dict(good, url="https://archive.org/download/x/y"), "url must name a .7z or .zip file"),
                     (dict(good, url="https://archive.org/download/x.7z/y"), "url must name a .7z or .zip file"),
                     (dict(good, url="https://archive.org/download/x/.zip"), "url must name a .7z or .zip file"),
                     (dict(good, alt=zipped), "alt must be a list"), (dict(good, alt=[zipped["url"]]), "alt must be a list"),
                     (dict(good, alt="none"), "alt must be a list"), (dict(good, alt=None), "alt must be a list"),
                     (dict(good, alt=[{"url": zipped["url"], "size": 20}]), "alt[0].md5 must be 32 hex digits"),
                     (dict(good, alt=[dict(zipped, size=0)]), "alt[0].size must be a positive integer"),
                     (dict(good, alt=[dict(zipped, url="http://archive.org/download/x/y.zip")]), "alt[0].url must be an https"),
                     (dict(good, alt=[dict(zipped, url="https://archive.org/download/x/y.tar")]), "alt[0].url must name"),
                     (dict(good, alt=[dict(zipped, url=good["url"])]), "two archives of one format"),
                     (dict(good, url=zipped["url"], alt=[dict(zipped, url="https://archive.org/download/x/z.ZIP")]),
                      "two archives of one format"),
                     (dict(good, alt=[zipped, dict(zipped, url="https://archive.org/download/x/z.zip")]),
                      "two archives of one format")):
        try:
            validate_stack_catalog(bad)
            raise AssertionError("must refuse %r" % (bad,))
        except ValueError as e:
            assert why in str(e), (bad, str(e))
    assert validate_stack_catalog(both) and validate_stack_catalog(dict(good, alt=[])) \
        and validate_stack_catalog(dict(zipped, extractedSize=30, topDir="x", alt=[{k: good[k] for k in ("url", "size", "md5")}]))
    assert STACK_ARCHIVE_EXTS == (".7z", ".zip")
    for url_, ext_ in (("https://archive.org/download/x/y.7z", ".7z"), ("https://archive.org/download/x/Y.ZIP", ".zip"),
                       ("https://archive.org/download/x/y.tar.7z", ".7z"), ("https://archive.org/download/x/y.rar", ".rar"),
                       ("https://archive.org/download/x/y", ""), ("https://archive.org/download/x.zip/y", ""),
                       ("https://archive.org/download/x/.zip", ""), ("https://archive.org/download/x/y.zip/", ""),
                       ("https://archive.org/download/x/y.7z?download=1#top", ".7z"), ("", ""), (None, "")):
        assert stack_archive_ext(url_) == ext_, (url_, stack_archive_ext(url_))
    assert stack_archives(good) == [{"url": good["url"], "size": 10, "md5": "a" * 32, "ext": ".7z"}]
    assert stack_archives(both) == [{"url": good["url"], "size": 10, "md5": "a" * 32, "ext": ".7z"},
                                    {"url": zipped["url"], "size": 20, "md5": "b" * 32, "ext": ".zip"}], stack_archives(both)
    # which of them a box takes: the first it can unpack -- a .zip always, a .7z only with an extractor
    zip_first = dict(zipped, extractedSize=30, topDir="x", alt=[{k: good[k] for k in ("url", "size", "md5")}])
    for cat_, found_, want in ((good, ("/usr/bin/7zz", "7z"), ".7z"), (good, None, None), (both, ("/usr/bin/7zz", "7z"), ".7z"),
                               (both, None, ".zip"), (zip_first, ("/usr/bin/7zz", "7z"), ".zip"), (zip_first, None, ".zip"),
                               (dict(zipped, extractedSize=30, topDir="x"), None, ".zip")):
        arc = choose_stack_archive(cat_, found_)
        assert (arc["ext"] if arc else None) == want, (cat_, found_, arc)
    assert extract_argv("/usr/bin/7zz", "/a.7z", "/out") == ["/usr/bin/7zz", "x", "-y", "-bd", "-o/out", "/a.7z"]
    for t in ("7z", "7za", "7zr"):
        assert extract_argv("/usr/bin/" + t, "/a.7z", "/out") == ["/usr/bin/" + t, "x", "-y", "-bd", "-o/out", "/a.7z"], t
    assert extract_argv("/usr/bin/bsdtar", "/a.7z", "/out") == ["/usr/bin/bsdtar", "-xf", "/a.7z", "-C", "/out"]
    assert extract_argv(r"C:\Windows\System32\tar.exe", r"C:\a.7z", r"C:\out") == \
        [r"C:\Windows\System32\tar.exe", "-xf", r"C:\a.7z", "-C", r"C:\out"]
    assert extract_argv(r"C:\Program Files\7-Zip\7z.exe", r"C:\a.7z", r"C:\out") == \
        [r"C:\Program Files\7-Zip\7z.exe", "x", "-y", "-bd", r"-oC:\out", r"C:\a.7z"]
    assert extract_argv(r"C:\Program Files\Bandizip\bz.exe", r"C:\a.7z", r"C:\out") == \
        [r"C:\Program Files\Bandizip\bz.exe", "x", "-y", r"-o:C:\out", r"C:\a.7z"]
    assert _extractor_kind("tar") == "bsdtar" and _extractor_kind("7ZZ") == "7z" and _extractor_kind("BZ.EXE") == "bz"
    assert probe_authority("0.0.0.0:18080") == "127.0.0.1:18080" and probe_authority("[::]:18080") == "127.0.0.1:18080"
    assert probe_authority("192.0.2.10:18081") == "192.0.2.10:18081"
    assert probe_authority("[2001:db8::1]:18080") == "[2001:db8::1]:18080"
    assert probe_authority("") == "127.0.0.1:18080" and probe_authority("18081") == "127.0.0.1:18081"
    assert _cli_list("--fetch", ["--config", "c", "--fetch", "1.6", "2.8", "--log", "x"]) == ["1.6", "2.8"]
    assert _cli_list("--fetch", ["--fetch"]) == [] and _cli_list("--fetch", ["--fetch", "2.8", "--config", "c"]) == ["2.8"]
    # The CLI clients of the RUNNING agent (--fetch, --relocate) over a canned HTTP call: what they ask, in which
    # order, with which body, what they print and the exit code. No agent is asked anything; the token and the
    # address are the check's own (an empty token stops both before any call, and a box's listen address would be
    # in their lines).
    saved_token_cli, saved_sleep_cli = TOKEN, time.sleep
    try:
        globals()["TOKEN"] = "selftest-token"
        time.sleep = lambda _s: None  # --fetch waits 2 s between two polls of its job
        cli_base = "http://selftest:1"
        cli_health = ("GET", "/health", (200, {"ok": True, "service": "gio-agent", "version": AGENT_VERSION}))
        cli_agent = "agent %s at %s" % (AGENT_VERSION, cli_base)
        cli_next = "Next: Prepare the server (launcher -> Server page) or POST /server/setup."
        cli_busy = "Another operation is already running on the server (x, version 2.8). Wait for it to finish."
        cli_token = "The agent refused the token (401) -- is GIO_AGENT_TOKEN in the config the one it runs with?"
        cli_mute = ("The agent does not answer at %s (connection refused) -- start the service first (systemctl start "
                    "gio-agent)." % cli_base)

        def canned(*pairs):
            """A CLI client's call(method, path, body, timeout) answering from (method, path, answer) in that order:
            answer = (status, body), or an exception to raise. Anything else asked fails the check; .todo holds what
            was not asked, .asked every (method, path, body) that was."""
            todo, asked = list(pairs), []

            def call_(method, path, body=None, timeout=30):
                asked.append((method, path, body))
                assert todo, "nothing more was to be asked: %s %s" % (method, path)
                m_, p_, answer = todo.pop(0)
                assert (m_, p_) == (method, path), ((m_, p_), (method, path))
                if isinstance(answer, BaseException):
                    raise answer
                return answer

            call_.todo, call_.asked = todo, asked
            return call_

        def never(*_a, **_k):
            raise AssertionError("nothing may be asked of the agent here")

        relocate_argv = ["--config", "c", "--relocate", "3.2", "/srv/3.2_live", "--mode", "move"]
        assert _cli_list("--relocate", relocate_argv) == ["3.2", "/srv/3.2_live"] and _cli_option("--mode", relocate_argv) == "move"
        assert _cli_list("--relocate", ["--relocate", "1.6", ""]) == ["1.6", ""], "an empty folder takes the version off"
        # An option this build does not know ends the run before anything starts (a command meant for another build
        # never starts a second agent); the value after an option that takes one is never judged.
        for argv_, unknown_ in ((relocate_argv, None), (["--config", "c", "--log", "l"], None), (["--selftest"], None),
                                (["--build-id"], None), (["--config=c", "--log=-", "--fetch", "1.6", "2.8"], None),
                                (["--log", "-", "--relocate", "1.6", "", "--mode=move"], None), ([], None),
                                (["--config", "c", "--unpack", "1.6"], "--unpack"), (["-h"], "-h"),
                                (["--fetch=1.6"], "--fetch=1.6"), (["--selftest=1"], "--selftest=1"),
                                (["--relocate", "1.6", "/x", "--mode", "move", "--force"], "--force")):
            assert _cli_unknown(argv_) == unknown_, (argv_, _cli_unknown(argv_))
        assert set(CLI_VALUE_OPTIONS) < set(CLI_OPTIONS) and all(o in CLI_USAGE for o in CLI_OPTIONS)
        # --relocate's --mode: absent = repoint; given without a value = a usage error, never a repoint
        for argv_, mode_ in ((["--relocate", "1.6", "/x"], None), (relocate_argv, "move"),
                             (["--relocate", "1.6", "/x", "--mode=Move"], "Move"), (["--relocate", "1.6", "/x", "--mode"], ""),
                             (["--relocate", "1.6", "/x", "--mode="], "")):
            assert _relocate_mode_option(argv_) == mode_, (argv_, _relocate_mode_option(argv_))
        # --fetch: a version already there is skipped; a refusal, a busy agent, a job followed to its end, a mute agent
        cli_absent = ("GET", "/status", (200, {"versions": {"1.6": {"present": False, "dir": "/x"}}}))
        cli_out = []
        cli_call = canned(cli_health, ("GET", "/status", (200, {"versions": {"1.6": {"present": True, "dir": "/x"}}})))
        assert fetch_cli(["1.6"], call=cli_call, emit=cli_out.append, base=cli_base) == 0 and not cli_call.todo
        assert cli_out == [cli_agent, "1.6: already on this box (/x) -- skipped.", cli_next], cli_out
        cli_out = []
        cli_call = canned(cli_health, cli_absent, ("POST", "/server/fetch", (404, {"error": "not found"})))
        assert fetch_cli(["1.6"], call=cli_call, emit=cli_out.append, base=cli_base) == 1 and not cli_call.todo
        assert cli_out[-1] == "1.6: the agent refused the download (HTTP 404): not found", cli_out
        assert cli_call.asked[-1] == ("POST", "/server/fetch", {"version": "1.6"}), cli_call.asked
        cli_out = []
        cli_call = canned(cli_health, cli_absent, ("POST", "/server/fetch", (409, {"error": cli_busy})))
        assert fetch_cli(["1.6"], call=cli_call, emit=cli_out.append, base=cli_base) == 3 and cli_out[-1] == "1.6: " + cli_busy
        cli_out = []
        cli_call = canned(cli_health, cli_absent, ("POST", "/server/fetch", (202, {"job": "j1"})),
                          ("GET", "/jobs/j1?since=0", (200, {"lines": ["a"], "next": 1, "state": "running"})),
                          ("GET", "/jobs/j1?since=1", (200, {"lines": ["b"], "next": 2, "state": "done"})))
        assert fetch_cli(["1.6"], call=cli_call, emit=cli_out.append, base=cli_base) == 0 and not cli_call.todo
        assert cli_out == [cli_agent, "1.6: job j1 started -- following it (Ctrl+C stops following, not the job; rerun this "
                           "command or GET %s/jobs/j1?since=0 to watch again)" % cli_base, "  a", "  b", cli_next], cli_out
        cli_out = []
        cli_call = canned(cli_health, cli_absent, ("POST", "/server/fetch", (202, {"job": "j2"})),
                          ("GET", "/jobs/j2?since=0", (200, {"lines": ["c"], "next": 1, "state": "error", "error": "boom"})))
        assert fetch_cli(["1.6"], call=cli_call, emit=cli_out.append, base=cli_base) == 1 and cli_out[-2:] == [
            "  c", "1.6: FAILED -- boom"], cli_out
        cli_out = []
        assert fetch_cli(["1.6"], call=canned(("GET", "/health", OSError("connection refused"))), emit=cli_out.append,
                         base=cli_base) == 4 and cli_out == [cli_mute], cli_out
        cli_out = []
        assert fetch_cli(["9.9"], call=never, emit=cli_out.append, base=cli_base) == 2 \
            and cli_out == ["usage: gio_agent.py [--config FILE] --fetch %s" % " | ".join(VERSIONS)], cli_out
        globals()["TOKEN"] = ""
        cli_out = []
        assert fetch_cli(["1.6"], call=never, emit=cli_out.append, base=cli_base) == 2 and cli_out == [
            "GIO_AGENT_TOKEN is empty -- pass --config /etc/gio-agent/config (or export it)."], cli_out
        cli_out = []
        assert relocate_cli(["1.6", "/x"], call=never, emit=cli_out.append, base=cli_base) == 2 and cli_out == [
            "GIO_AGENT_TOKEN is empty -- pass --config /etc/gio-agent/config (or export it)."], cli_out
        globals()["TOKEN"] = "selftest-token"
        # --relocate: usage before anything is asked; a mute agent, a refused token, an agent without the route, a
        # busy one, a refused check, a check that goes on with what it says, the real request refused, a job done
        cli_usage = ("usage: gio_agent.py [--config FILE] --relocate %s <folder> [--mode repoint|move]"
                     % " | ".join(VERSIONS))
        for values_, mode_ in (([], None), (["1.6"], None), (["9.9", "/x"], None), (["1.6", "/x", "/y"], None),
                               (["1.6", "/x"], "copy"), (["1.6", "/x"], ""), (["1.6", "/x"], "  ")):
            cli_out = []
            assert relocate_cli(values_, mode_, call=never, emit=cli_out.append, base=cli_base) == 2 \
                and cli_out == [cli_usage], (values_, mode_, cli_out)
        cli_out = []
        assert relocate_cli(["1.6", "/x"], call=canned(("GET", "/health", OSError("connection refused"))),
                            emit=cli_out.append, base=cli_base) == 4 and cli_out == [cli_mute], cli_out

        def cli_check(answer):
            return ("POST", "/server/relocate", answer)

        for answer, rc, last in (((401, {"error": "unauthorized"}), 4, cli_token),
                                 ((404, {"error": "not found"}), 1,
                                  "1.6: this agent cannot change a stack folder (HTTP 404) -- update it first."),
                                 ((400, {"error": "mode must be move or repoint"}), 1,
                                  "1.6: the agent refused the check (HTTP 400): mode must be move or repoint"),
                                 ((200, {"ok": False, "problem": cli_busy}), 3, "1.6: " + cli_busy),
                                 ((200, {"ok": False, "problem": "The folder is not empty and holds no server: /x"}), 1,
                                  "1.6: The folder is not empty and holds no server: /x")):
            cli_out = []
            cli_call = canned(cli_health, cli_check(answer))
            assert relocate_cli(["1.6", "/x"], call=cli_call, emit=cli_out.append, base=cli_base) == rc \
                and not cli_call.todo and cli_out == [cli_agent, last], (answer, cli_out)
            assert cli_call.asked[-1] == ("POST", "/server/relocate",
                                          {"version": "1.6", "dir": "/x", "mode": "repoint", "check": True}), cli_call.asked
        cli_disk = "Not enough free disk space: 5.0 GB needed (selftest)"
        cli_out = []
        cli_call = canned(cli_health, cli_check((200, {
            "ok": True, "from": "", "to": "/x", "running": True,
            "carry": [{"name": "1.6_live.7z.part", "size": 2 * 10 ** 9, "fits": True},
                      {"name": "1.6_live.7z", "size": 3 * 10 ** 9, "fits": False}],
            "download": {"need": 5 * 10 ** 9, "free": 4 * 10 ** 9, "problem": cli_disk}})),
            cli_check((400, {"error": "e"})))
        assert relocate_cli(["1.6", "/x"], call=cli_call, emit=cli_out.append, base=cli_base) == 1 and not cli_call.todo
        assert cli_out == [cli_agent, "1.6: (not configured) -> /x (repoint)",
                           "  version 1.6 is running: it is stopped first.",
                           "  1.6_live.7z.part (2.0 GB) follows the version.",
                           "  1.6_live.7z (3.0 GB) stays beside the old folder -- it does not fit on the new drive.",
                           "  a download into that folder needs 5.0 GB there, 4.0 GB are free.",
                           "  WARNING: a download into that folder would be refused now: " + cli_disk,
                           "1.6: the agent refused the relocation (HTTP 400): e"], cli_out
        assert [b for _m, _p, b in cli_call.asked[1:]] == [{"version": "1.6", "dir": "/x", "mode": "repoint", "check": True},
                                                           {"version": "1.6", "dir": "/x", "mode": "repoint"}], cli_call.asked
        cli_out = []
        cli_call = canned(cli_health, cli_check((200, {"ok": True, "from": "/old", "to": "/x", "running": False})),
                          cli_check((409, {"error": cli_busy})))
        assert relocate_cli(["1.6", "/x"], call=cli_call, emit=cli_out.append, base=cli_base) == 3 \
            and cli_out == [cli_agent, "1.6: /old -> /x (repoint)", "1.6: " + cli_busy], cli_out
        cli_out = []
        cli_call = canned(cli_health, cli_check((200, {"ok": True, "from": "/old", "to": "/srv/1.6_live", "running": False})),
                          cli_check((202, {"job": "r1"})),
                          ("GET", "/jobs/r1?since=0", (200, {"lines": ["x"], "next": 1, "state": "running"})),
                          ("GET", "/jobs/r1?since=1", (200, {"lines": [], "next": 1, "state": "done",
                                                             "result": {"to": "/srv/1.6_live", "restartError": "boom"}})))
        waits = []
        assert relocate_cli(["1.6", "/srv/1.6_live"], "Move", call=cli_call, emit=cli_out.append, sleep=waits.append,
                            base=cli_base) == 0 and not cli_call.todo and waits == [2], (cli_out, waits)
        assert cli_out == [cli_agent, "1.6: /old -> /srv/1.6_live (move)",
                           "1.6: job r1 started -- following it (Ctrl+C stops following, not the job; GET %s/jobs/r1?since=0 "
                           "to watch again)" % cli_base, "  x", "1.6: done -- GIO_DIR_16=/srv/1.6_live",
                           "1.6: WARNING -- it did not start again (boom); start it from the launcher's Server page."], cli_out
        assert cli_call.asked[2] == ("POST", "/server/relocate", {"version": "1.6", "dir": "/srv/1.6_live", "mode": "move"})
        ok("CLI clients of the running agent OK (--fetch: skipped / refused / busy / followed to done and to an error / "
           "mute / usage / no token, its lines as they were; --relocate: argv, usage before any call -- a --mode given "
           "without a value included --, mute, the token, an agent without the route, a refused or busy check, what "
           "the dry run says -- running, what follows, a download refused there --, the real request refused or busy, "
           "a job followed to done with its restart warning; an option this build does not know ends the run)")
    finally:
        globals()["TOKEN"] = saved_token_cli
        time.sleep = saved_sleep_cli
    assert _bundle_dir_inside_mirror("/var/lib/gio-agent/hotpatch/bundles", "/var/lib/gio-agent/hotpatch")
    assert _bundle_dir_inside_mirror("/var/lib/gio-agent/hotpatch", "/var/lib/gio-agent/hotpatch/")
    assert not _bundle_dir_inside_mirror("/var/lib/gio-agent/hotpatch-bundles", "/var/lib/gio-agent/hotpatch")
    ok("stack catalogues + validator, extractor argv, probe authority, --fetch argv, bundle-dir guard OK")

    with tempfile.TemporaryDirectory() as td:
        stack = os.path.join(td, "2.8_live")
        nested = os.path.join(stack, "server", "data", "2.8_live-output_9464149-server-data")
        fixture = ((nested, ("txt", "ConstValueData.txt"), "nested const"),
                   (nested, ("txt", "MaterialDeleteData.txt"), "vendor's copy"),
                   (nested, ("json", "a", "b.json"), "nested json"),
                   (nested, ("lua", "common", "x.lua"), "nested lua"),
                   (nested, ("server_data_version.txt",), "9464149"),
                   (nested, ("notes.md",), "not hoisted"),
                   (os.path.join(stack, "server", "data"), ("json", "a", "b.json"), "older json"),
                   (os.path.join(stack, "server", "data"), ("json", "only_top.json"), "top only"),
                   (os.path.join(stack, "server", "data"), ("txt", "MaterialDeleteData.txt"), "agent's copy"))
        for base, rel, body in fixture:
            p = os.path.join(base, *rel)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "w") as f:
                f.write(body)
        owned = {"server/data/txt/MaterialDeleteData.txt"}
        logs = []
        n = heal_nested_server_data(stack, owned, logs.append)
        assert n == 4, (n, logs)
        data = os.path.join(stack, "server", "data")
        for rel, body in ((("txt", "ConstValueData.txt"), "nested const"), (("json", "a", "b.json"), "nested json"),
                          (("lua", "common", "x.lua"), "nested lua"), (("server_data_version.txt",), "9464149"),
                          (("txt", "MaterialDeleteData.txt"), "agent's copy"), (("json", "only_top.json"), "top only")):
            with open(os.path.join(data, *rel)) as f:
                assert f.read() == body, (rel, f.read())
        assert os.path.isdir(nested) and os.listdir(nested) == ["notes.md"], "a leftover the server never reads stays"
        assert any("not empty after the hoist" in l for l in logs), logs
        assert heal_nested_server_data(stack, owned, logs.append) == 0, "idempotent"
        os.remove(os.path.join(nested, "notes.md"))
        assert heal_nested_server_data(stack, owned, logs.append) == 0 and not os.path.exists(nested), "emptied -> removed"
        flat = os.path.join(td, "1.6_live", "server", "data", "txt")
        os.makedirs(flat)
        open(os.path.join(flat, "ConstValueData.txt"), "w").close()
        n_logs = len(logs)
        assert heal_nested_server_data(os.path.join(td, "1.6_live"), set(), logs.append) == 0
        assert os.path.isfile(os.path.join(flat, "ConstValueData.txt")) and len(logs) == n_logs, "a flat tree: silent no-op"
        assert heal_nested_server_data(os.path.join(td, "nothing"), set(), logs.append) == 0 and len(logs) == n_logs
    ok("nested server/data layout heal OK (hoist, owned keeps the top copy, nested wins, leftover logged, "
       "idempotent, flat tree + missing data no-op)")

    g = globals()
    faked_f = ("PAYLOAD_DIR", "STATE_PATH", "find_extractor", "extract_archive", "_fetch_to_file", "log_line",
               "running_projects", "read_manifest", "FETCH_DISK_RESERVE", "_free_bytes_at", "_extract_external",
               "EXTRACT_PROGRESS_STEP", "IS_WINDOWS")
    saved_f = {k: g[k] for k in faked_f}
    saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
    saved_sleep = time.sleep
    saved_urlopen_f = urllib.request.urlopen
    with tempfile.TemporaryDirectory() as td:
        try:
            stack = os.path.join(td, "srv", "1.6_live")
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = stack, _project_name(stack)
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = "", ""
            # the free space of the volume a download lands on is the check's own, never the box's
            free_default = lambda _p: 10 ** 12  # noqa: E731
            g.update({"PAYLOAD_DIR": os.path.join(td, "payloads"), "STATE_PATH": os.path.join(td, "state.json"),
                      "log_line": lambda *_a: None, "running_projects": lambda: ([], None),
                      "read_manifest": lambda _v: None, "FETCH_DISK_RESERVE": 1 << 20,
                      "find_extractor": lambda: ("/fake/7zz", "7z"), "_free_bytes_at": free_default})
            body = b"7z\xbc\xaf\x27\x1c fake archive bytes " * 100
            cat = {"version": "1.6", "url": "https://archive.org/download/test/1.6_live_gio.7z", "size": len(body),
                   "md5": hashlib.md5(body).hexdigest(), "extractedSize": 2 * len(body), "topDir": "1.6_live",
                   "label": "Internet Archive", "strays": ["data.txt"]}
            os.makedirs(os.path.join(PAYLOAD_DIR, "1.6"))
            with open(os.path.join(PAYLOAD_DIR, "1.6", "stack.json"), "w") as f:
                json.dump(cat, f)
            assert fetch_brief("1.6") == {"available": True, "size": len(body), "host": "archive.org", "topDir": "1.6_live",
                                          "part": 0, "archive": False, "kind": "7z", "tool": "7zz", "formats": ["7z"],
                                          "fetchedAt": None, "extractedSize": 2 * len(body), "reserve": 1 << 20,
                                          "need": len(body) + 2 * len(body) + (1 << 20), "free": 10 ** 12,
                                          "problem": None}, fetch_brief("1.6")
            assert fetch_brief("2.8") == {"available": False, "size": 0, "host": None, "topDir": None, "part": 0,
                                          "archive": False, "kind": None, "tool": None, "formats": [],
                                          "fetchedAt": None, "extractedSize": None, "reserve": 1 << 20, "need": None,
                                          "free": None, "problem": None}, fetch_brief("2.8")
            os.makedirs(os.path.dirname(stack))
            with open(archive_path("1.6") + ".part", "wb") as f:
                f.write(b"abc")
            assert fetch_brief("1.6")["part"] == 3
            assert fetch_brief("1.6")["need"] == len(body) - 3 + 2 * len(body) + (1 << 20), "what the .part holds is there"
            # never in the public projection -- not from a hand-made status, not from status() itself; the version
            # entries carry none of the download's keys (looked at as keys: the texts around them are not the check's)
            new_fetch_keys = ("fetch", "extractedSize", "reserve", "need", "free", "problem")
            full = {"versions": {"1.6": {"present": False, "fetch": fetch_brief("1.6")},
                                 "2.8": {"present": True, "up": False, "fetch": {"available": True, "host": "archive.org"}}},
                    "state": {"ok": True}, "platform": "linux"}
            pub = build_public_status(full, default_policy())
            assert "fetch" not in pub["versions"]["1.6"] and "fetch" not in pub["versions"]["2.8"], pub
            assert "archive.org" not in json.dumps(pub) and pub["versions"]["1.6"] == {"present": False}
            assert not any(k in e_ for e_ in pub["versions"].values() for k in new_fetch_keys), pub
            g["running_projects"] = lambda: (None, "docker unavailable (selftest)")
            full = g["status"]()  # (a local `status` shadows the function inside selftest)
            assert full["versions"]["1.6"]["fetch"]["available"] and full["versions"]["1.6"]["fetch"]["part"] == 3, full
            assert full["versions"]["2.8"]["fetch"]["available"] is False
            assert full["versions"]["1.6"]["fetch"]["need"] == len(body) - 3 + 2 * len(body) + (1 << 20), full
            assert "fetch" not in json.dumps(build_public_status(full, default_policy()))
            pub = build_public_status(full, default_policy())
            assert not any(k in e_ for e_ in pub["versions"].values() for k in new_fetch_keys), pub
            os.remove(archive_path("1.6") + ".part")
            # a complete archive of the catalogue's size beside the folder is no download left to make: the need is
            # the unpacked tree and the reserve
            with open(archive_path("1.6"), "wb") as f:
                f.write(body)
            fb = fetch_brief("1.6")
            assert fb["archive"] is True and fb["need"] == 2 * len(body) + (1 << 20) and fb["problem"] is None, fb
            os.remove(archive_path("1.6"))
            # a catalogue that names no unpacked size: 0 reported, three times the archive reckoned with
            with open(os.path.join(PAYLOAD_DIR, "1.6", "stack.json"), "w") as f:
                json.dump(dict(cat, extractedSize=0), f)
            fb = fetch_brief("1.6")
            assert fb["extractedSize"] == 0 and fb["need"] == len(body) + 3 * len(body) + (1 << 20), fb
            with open(os.path.join(PAYLOAD_DIR, "1.6", "stack.json"), "w") as f:
                json.dump(cat, f)
            # the synchronous refusals
            g["find_extractor"] = lambda: None
            try:
                fetch_preflight("1.6")
                raise AssertionError("no extractor must be refused")
            except AgentError as e:
                assert e.status == 409 and "extractor" in e.message, e.message
                assert e.message.startswith("No 7z extractor on this box (") \
                    and "the server package of version 1.6 is published as .7z only" in e.message, e.message
                no_tool = e.message
            # ...and the status says so: no archive of this catalogue can be unpacked here -- no kind, no tool,
            # the size of the first one; what lies beside the folder is still told, and so is the refusal the
            # download would get, word for word; no need without an archive to take, the free space all the same
            fb = fetch_brief("1.6")
            assert (fb["available"], fb["kind"], fb["tool"], fb["formats"], fb["size"]) == \
                (True, None, None, ["7z"], len(body)), fb
            assert fb["problem"] == no_tool and fb["need"] is None and fb["free"] == 10 ** 12, fb
            assert archive_path("1.6") == stack + ".7z", "without a choice the path is the .7z's"
            g["find_extractor"] = lambda: ("/fake/7zz", "7z")
            for v_, want in (("2.8", 404), ("3.0", 400)):
                try:
                    fetch_preflight(v_)
                    raise AssertionError("must refuse %s" % v_)
                except AgentError as e:
                    assert e.status == want, (v_, e.status, e.message)
            os.makedirs(stack)
            with open(os.path.join(stack, "junk.txt"), "w") as f:
                f.write("x")
            try:
                fetch_preflight("1.6")
                raise AssertionError("a non-empty non-stack dir must be refused")
            except AgentError as e:
                assert e.status == 409 and "not a server stack" in e.message, e.message
                assert fetch_brief("1.6")["problem"] == e.message, fetch_brief("1.6")
            os.remove(os.path.join(stack, "junk.txt"))
            # a file where the download would put its archive that is not the catalogue's: the same 409 in the status
            with open(stack + ".7z", "wb") as f:
                f.write(b"a backup of the stack folder")
            try:
                fetch_preflight("1.6")
                raise AssertionError("a file in the way must be refused")
            except AgentError as e:
                assert e.status == 409 and e.message == (
                    "%s is in the way: it is not the catalogue's archive (its size differs). Move it away, then run "
                    "this again -- nothing was deleted." % (stack + ".7z")), e.message
                assert fetch_brief("1.6")["problem"] == e.message, fetch_brief("1.6")
            os.remove(stack + ".7z")
            g["_free_bytes_at"] = lambda _p: 10
            try:
                fetch_preflight("1.6")
                raise AssertionError("a full disk must be refused")
            except AgentError as e:
                assert e.status == 409 and "Not enough free disk space" in e.message, e.message
                fb = fetch_brief("1.6")
                assert fb["problem"] == e.message and fb["problem"].startswith("Not enough free disk space") \
                    and fb["free"] == 10, fb
                # one read of the free space per poll: the figure in the refusal is the `free` beside it
                free_reads = []
                g["_free_bytes_at"] = lambda p_: free_reads.append(p_) or 10
                fb = fetch_brief("1.6")
                assert len(free_reads) == 1 and fb["problem"] == e.message and fb["free"] == 10, (free_reads, fb)
            # while a download of this version runs its own archive and tree are on that volume already: no need, no
            # refusal -- the free space is still told (a job of another kind beside it is not that download)
            fake_fetch_job = Job("fetch", "1.6", job_id="fetch-selftest-brief")
            with _jobs_lock:
                JOBS[fake_fetch_job.id] = fake_fetch_job
                JOBS_ORDER.append(fake_fetch_job.id)
            try:
                fb = fetch_brief("1.6")
                assert fb["need"] is None and fb["problem"] is None and fb["free"] == 10, fb
                fake_fetch_job.version = "2.8"
                fb = fetch_brief("1.6")
                assert fb["need"] is not None and fb["problem"] is not None, "a download of another version"
            finally:
                with _jobs_lock:
                    JOBS.pop(fake_fetch_job.id, None)
                    if fake_fetch_job.id in JOBS_ORDER:
                        JOBS_ORDER.remove(fake_fetch_job.id)

            def unreadable_free(_p):
                raise OSError("selftest: no volume")

            g["_free_bytes_at"] = unreadable_free
            fb = fetch_brief("1.6")
            assert fb["available"] is True and (fb["need"], fb["free"], fb["problem"]) == (None, None, None), fb
            g["_free_bytes_at"] = free_default
            with open(os.path.join(PAYLOAD_DIR, "1.6", "stack.json"), "w") as f:
                json.dump(dict(cat, topDir="../x"), f)
            try:
                fetch_preflight("1.6")
                raise AssertionError("an invalid catalogue must be refused")
            except AgentError as e:
                assert e.status == 500 and "invalid" in e.message, e.message
            with open(os.path.join(PAYLOAD_DIR, "1.6", "stack.json"), "w") as f:
                json.dump(cat, f)
            assert fetch_preflight("1.6")[1] == "/fake/7zz", "an EMPTY target dir is fine"
            # the job, with a fake downloader (writes the catalogue's bytes) and a fake extractor
            fetched, extracted, fail_extract = [], [], []

            def fake_fetch2(url, dst, timeout=60, cap=None, expect_md5=None, expect_size=None, resume=False,
                            should_stop=None, progress=None):
                fetched.append(url)
                assert expect_md5 == cat["md5"] and expect_size == len(body) and resume and should_stop is not None
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with open(dst + ".part", "wb") as f:
                    f.write(body)
                if progress is not None:
                    progress(len(body))
                replace_file(dst + ".part", dst)
                return len(body)

            def fake_extract2(archive, dest, job, should_stop=None, timeout=None):
                extracted.append(archive)
                assert os.path.isfile(archive) and os.path.basename(dest) == ".relic-extract-1.6_live", dest
                if fail_extract:
                    raise ExtractError("7zz exited with code 1: simulated")
                top = os.path.join(dest, "1.6_live")
                deep = os.path.join(top, "server", "data", "1.6_live-output_1-server-data", "txt")
                os.makedirs(deep)
                for p_, text in ((os.path.join(top, "docker-compose.yml.tmpl"), "services: {}"),
                                 (os.path.join(top, "bootstrap.sh"), "#!/bin/sh"),
                                 (os.path.join(deep, "ConstValueData.txt"), "k\tv"),
                                 (os.path.join(dest, "data.txt"), "stray")):
                    with open(p_, "w") as f:
                        f.write(text)
                return 0.5

            g["_fetch_to_file"], g["extract_archive"] = fake_fetch2, fake_extract2
            # (1) the extractor fails: 500, the verified archive is KEPT, present stays False, no temp folder
            fail_extract.append(1)
            jf = _Job()
            try:
                do_fetch("1.6", jf)
                raise AssertionError("a failed extraction must fail the job")
            except AgentError as e:
                assert e.status == 500 and "kept" in e.message and "simulated" in e.message, e.message
            assert os.path.isfile(archive_path("1.6")) and not is_present("1.6") and not os.path.exists(extract_tmp("1.6"))
            assert fetched == [cat["url"]] and fetch_brief("1.6")["archive"] is True
            fail_extract.clear()
            # (2) the retry adopts the verified archive (no download), unpacks, renames, heals the nested
            #     layout, repairs the exec bits, drops the stray + temp + archive, records the fetch
            jd = _Job()
            res = do_fetch("1.6", jd)
            assert res == {"fetched": True, "downloaded": False, "bytes": len(body), "healed": 1,
                           "execBits": 1 if os.name == "posix" else 0, "dir": stack}, res
            assert is_present("1.6") and jd.yielding is True and fetched == [cat["url"]], "adopted: no second download"
            assert not os.path.exists(archive_path("1.6")) and not os.path.exists(extract_tmp("1.6"))
            assert os.path.isfile(os.path.join(stack, "server", "data", "txt", "ConstValueData.txt"))
            assert not os.path.exists(os.path.join(os.path.dirname(stack), "data.txt")), "the stray went with the temp folder"
            vs = version_state("1.6")
            assert vs.get("fetchedAt") and vs.get("fetchedFrom") == "archive.org", vs
            assert fetch_brief("1.6")["fetchedAt"] == vs["fetchedAt"] and fetch_brief("1.6")["archive"] is False
            assert any("pre-seeded" in l for l in jd.lines) and any("Installed into" in l for l in jd.lines), jd.lines
            assert any("Healed the nested server/data layout (1 files hoisted)" in l for l in jd.lines), jd.lines
            # a folder that holds the stack asks nothing of the disk -- and the status passes what it found
            fb = fetch_brief("1.6")
            assert (fb["need"], fb["free"], fb["problem"]) == (None, None, None) and fb["reserve"] == 1 << 20, fb
            fb = fetch_brief("1.6", present=False)
            assert fb["problem"] == "Version 1.6 is already on this server (%s) -- nothing to download." % stack, fb
            # (3) a second call is refused: already present -- force too (a present stack is never overwritten)
            for force in (False, True):
                try:
                    fetch_preflight("1.6", force)
                    raise AssertionError("a present stack must be refused")
                except AgentError as e:
                    assert e.status == 409 and "already on this server" in e.message, e.message
            # (4) a full run on a fresh target: downloaded, and present flips only AFTER the rename
            shutil.rmtree(stack)
            seen = []

            def spying_extract(archive, dest, job, should_stop=None, timeout=None):
                seen.append(is_present("1.6"))
                return fake_extract2(archive, dest, job, should_stop, timeout)

            g["extract_archive"] = spying_extract
            del fetched[:]
            res = do_fetch("1.6", _Job())
            assert res["downloaded"] is True and seen == [False] and is_present("1.6") and fetched == [cat["url"]], (res, seen)
            # (5) Stop mid-download: 409 "Stopped on request", the .part stays, nothing present
            shutil.rmtree(stack)

            def stopping_fetch(url, dst, timeout=60, cap=None, expect_md5=None, expect_size=None, resume=False,
                               should_stop=None, progress=None):
                fetched.append(url)
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with open(dst + ".part", "wb") as f:
                    f.write(body[:100])
                _fetch_cancel.set()
                raise FetchStopped("stopped on request")

            g["_fetch_to_file"] = stopping_fetch
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a cancelled download must end in 409")
            except AgentError as e:
                assert e.status == 409 and e.message.startswith("Stopped on request") and "run it again" in e.message, e.message
            assert os.path.getsize(archive_path("1.6") + ".part") == 100 and not is_present("1.6")
            assert fetch_brief("1.6")["part"] == 100
            # (6) a checksum mismatch: 502 and nothing kept (as _fetch_to_file left it)
            os.remove(archive_path("1.6") + ".part")

            def bad_fetch(url, dst, **kw):
                fetched.append(url)
                raise ValueError("md5 x, expected y")

            g["_fetch_to_file"] = bad_fetch
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a checksum mismatch must end in 502")
            except AgentError as e:
                assert e.status == 502 and "Checksum mismatch" in e.message, e.message
            assert not os.path.exists(archive_path("1.6")) and not is_present("1.6")
            # (7) network cuts: retried with a doubling wait (5, 10 s ...), then the transfer completes
            cuts = [2]

            def cutting_fetch(url, dst, timeout=60, cap=None, expect_md5=None, expect_size=None, resume=False,
                              should_stop=None, progress=None):
                fetched.append(url)
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                if cuts[0]:
                    cuts[0] -= 1
                    with open(dst + ".part", "ab") as f:
                        f.write(b"x" * 10)
                    raise FetchCut("connection lost mid-transfer (timed out)")
                with open(dst + ".part", "wb") as f:
                    f.write(body)
                replace_file(dst + ".part", dst)
                return len(body)

            g["_fetch_to_file"], g["extract_archive"] = cutting_fetch, fake_extract2
            time.sleep = lambda _s: None  # the backoff waits are not worth real seconds here
            del fetched[:]
            jc = _Job()
            res = do_fetch("1.6", jc)
            assert res["downloaded"] is True and is_present("1.6") and len(fetched) == 3, (res, fetched)
            assert any("retrying in 5 s" in l for l in jc.lines) and any("retrying in 5 s (10 of" in l or "retrying in 5 s" in l for l in jc.lines), jc.lines
            assert sum("connection lost" in l for l in jc.lines) == 2, jc.lines
            # (8) a bundle-style HTTP 404 from the archive host: 502 at once, no retry loop
            shutil.rmtree(stack)
            del fetched[:]

            def gone_fetch(url, dst, **kw):
                fetched.append(url)
                raise urllib.error.HTTPError(url, 404, "NoSuchKey", {}, None)

            g["_fetch_to_file"] = gone_fetch
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a 404 must end in 502")
            except AgentError as e:
                assert e.status == 502 and "HTTP 404" in e.message and len(fetched) == 1, (e.message, fetched)
            ok("server package download OK (brief never public, preflight refusals, failed extractor keeps the archive, "
               "pre-seeded archive adopted, present flips after the rename, stop keeps the .part, checksum 502, "
               "cut retries with backoff, 404 no retry)")

            # (9) A .zip is unpacked by the agent itself: REAL small zips through the real extract_archive (the
            #     stand-in of the cases above is lifted), with no extractor on the box and no look at the box's
            #     free disk. A job line per MiB written here, so the progress lines are seen.
            g.update({"extract_archive": saved_f["extract_archive"], "find_extractor": lambda: None,
                      "_free_bytes_at": lambda _p: None, "EXTRACT_PROGRESS_STEP": 1 << 20})
            zdir = os.path.join(td, "zips")
            os.makedirs(zdir)
            STAMP = (2021, 6, 9, 12, 34, 56)

            def zip_of(name, entries):
                """A zip in the fixture folder. entries = [(member name, bytes -- None for a directory entry --,
                {method, zip64, mode, raw})]: Deflate unless `method` says otherwise; `zip64` writes the member with
                the ZIP64 fields although it is small; `mode` = the Unix mode an archive made there carries; `raw`
                keeps the name as given (the constructor would tidy it for the system this runs on)."""
                path = os.path.join(zdir, name)
                with zipfile.ZipFile(path, "w") as zf:
                    for member, data, opt in entries:
                        zi = zipfile.ZipInfo("placeholder" if opt.get("raw") else member, date_time=STAMP)
                        if opt.get("raw"):
                            zi.filename = member
                        zi.compress_type = opt.get("method", zipfile.ZIP_DEFLATED)
                        if "mode" in opt:
                            zi.create_system, zi.external_attr = 3, opt["mode"] << 16
                        if opt.get("zip64"):
                            with zf.open(zi, "w", force_zip64=True) as member_out:
                                member_out.write(data)
                        else:
                            zf.writestr(zi, data or b"")
                return path

            def patch_central(path, member, offset, fmt, value):
                """One field of a member's record in the zip's central directory, changed in place."""
                with zipfile.ZipFile(path) as zf:
                    at = zf.start_dir
                with open(path, "rb") as f:
                    raw = bytearray(f.read())
                while raw[at:at + 4] == b"PK\x01\x02":
                    n_len, e_len, c_len = struct.unpack_from("<HHH", raw, at + 28)
                    if bytes(raw[at + 46:at + 46 + n_len]) == member.encode():
                        struct.pack_into(fmt, raw, at + offset, value)
                        with open(path, "wb") as f:
                            f.write(raw)
                        return path
                    at += 46 + n_len + e_len + c_len
                raise AssertionError("no central directory record for %s" % member)

            def tree_of(root):
                files, folders = {}, set()
                for cur, dnames, fnames in os.walk(root):
                    rel = os.path.relpath(cur, root).replace(os.sep, "/")
                    rel = "" if rel == "." else rel + "/"
                    folders.update(rel + d_ for d_ in dnames)
                    for n_ in fnames:
                        with open(os.path.join(cur, n_), "rb") as f:
                            files[rel + n_] = f.read()
                return files, folders

            def refused_whole(path, text, **kw):
                """The archive is refused before a byte is written: an ExtractError that holds `text`, no folder."""
                out_ = path + ".out"
                try:
                    extract_archive(path, out_, _Job(), **kw)
                    raise AssertionError("must be refused: %s" % text)
                except ExtractStopped:
                    raise AssertionError("refused, not stopped: %s" % text)
                except ExtractError as e:
                    assert text in str(e), (text, str(e))
                assert not os.path.exists(out_), "refused as a whole, nothing written: %s" % text

            big = bytes(range(256)) * 12000  # 3 MB: more than two read pieces, two progress lines
            entries = [("top/", None, {}), ("top/docker-compose.yml.tmpl", b"services: {}\n", {}),
                       ("top/stored.bin", bytes(range(256)) * 40, {"method": zipfile.ZIP_STORED}),
                       ("top/empty/", None, {}), ("top/deep/a/b/c.txt", b"no directory entry leads here\n", {}),
                       ("top/big.bin", big, {}), ("top/zip64.bin", b"written with the ZIP64 fields\n" * 8, {"zip64": True}),
                       ("top/none.txt", b"", {}), ("top/run.sh", b"#!/bin/sh\n", {"mode": 0o100755}),
                       ("stray.txt", b"beside the top folder\n", {})]
            z_ok = zip_of("ok.zip", entries)
            with zipfile.ZipFile(z_ok) as zf, open(z_ok, "rb") as f:
                # (a member is written with the ZIP64 fields when its local header carries the ZIP64 extra block,
                #  id 1; whether its plain size fields then read 0xFFFFFFFF depends on the Python that wrote it)
                f.seek(zf.getinfo("top/zip64.bin").header_offset + 26)
                name_len_, extra_len_ = struct.unpack("<HH", f.read(4))
                f.seek(name_len_, 1)
                extra_, ids_, at_ = f.read(extra_len_), [], 0
                while at_ + 4 <= len(extra_):
                    ident_, size_ = struct.unpack_from("<HH", extra_, at_)
                    ids_.append(ident_)
                    at_ += 4 + size_
                assert 0x0001 in ids_, "the fixture's ZIP64 member is one"
                assert {i.compress_type for i in zf.infolist()} == {zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED}
            out = os.path.join(zdir, "out")
            jz = _Job()
            secs = extract_archive(z_ok, out, jz)
            files_, folders_ = tree_of(out)
            assert files_ == {member: data for member, data, _o in entries if data is not None}, sorted(files_)
            assert folders_ == {"top", "top/empty", "top/deep", "top/deep/a", "top/deep/a/b"}, sorted(folders_)
            assert os.listdir(os.path.join(out, "top", "empty")) == [], "a folder nothing lies in survives"
            total_ = sum(len(data) for _m, data, _o in entries if data is not None)
            assert secs >= 0 and jz.lines[0] == "Unpacking %s -> %s (8 files, %d MB)" % (z_ok, out, total_ // 1000000), jz.lines
            assert len(jz.lines) == 1 + total_ // (1 << 20) == 3 and all(
                re.match(r"^  \d+ / 3 MB \(\d+%\), \d+ of 8 files\Z", l) for l in jz.lines[1:]), jz.lines
            for rel_ in ("top/stored.bin", "top/empty", "top"):
                assert time.localtime(os.stat(os.path.join(out, *rel_.split("/"))).st_mtime)[:6] == STAMP, \
                    "%s carries its entry's time" % rel_
            if os.name == "posix":
                assert _stat.S_IMODE(os.stat(os.path.join(out, "top", "run.sh")).st_mode) == 0o755, "its entry's mode"
            # refused as a whole, before anything is written -- the member in question comes AFTER a good one:
            # a name that reaches outside the folder (one written with backslashes, which is refused on every
            # system: the name the archive stores is judged, not the one zipfile tidied), a member behind a
            # password, a symbolic link, a file that is no zip, a volume too small for the tree
            good_e = ("top/ok.txt", b"fine\n", {})
            for i, (member, text) in enumerate((("../escape.txt", "a member named '../escape.txt'"),
                                                ("/abs.txt", "a member named '/abs.txt'"),
                                                ("top/../../x.txt", "a member named 'top/../../x.txt'"),
                                                ("C:/x.txt", "a member named 'C:/x.txt'"),
                                                ("top/a\x01b.txt", "a member named 'top/a\\x01b.txt'"),
                                                ("top\\evil.txt", "a member named 'top\\\\evil.txt'"))):
                refused_whole(zip_of("name%d.zip" % i, [good_e, (member, b"x", {"raw": True})]), text)
            refused_whole(patch_central(zip_of("enc.zip", [good_e, ("top/secret.txt", b"x", {})]), "top/secret.txt", 8, "<H", 0x1),
                          "an encrypted member (top/secret.txt)")
            # (the two other flags zipfile opens no member for, each on the SECOND member of its method: named
            # by the listing -- never met after the first file is written, never taken for a method to hand over)
            for flag, text in ((0x40, "an encrypted member (top/secret.txt)"),
                               (0x20, "a member of compressed patched data (top/secret.txt)")):
                flagged = patch_central(zip_of("flag%02x.zip" % flag, [good_e, ("top/secret.txt", b"x", {})]),
                                        "top/secret.txt", 8, "<H", flag)
                refused_whole(flagged, text)
            refused_whole(zip_of("link.zip", [good_e, ("top/link", b"docker-compose.yml.tmpl", {"mode": 0o120777})]),
                          "a symbolic link (top/link)")
            with open(os.path.join(zdir, "garbage.zip"), "wb") as f:
                f.write(b"not a zip at all\n" * 40)
            refused_whole(os.path.join(zdir, "garbage.zip"), "cannot be read as a zip")
            g["_free_bytes_at"] = lambda _p: 10
            refused_whole(z_ok, "not enough free disk space to unpack it")
            g["_free_bytes_at"] = lambda _p: None
            # ...and where the tree is written on Windows: a name the system cannot hold, a path it refuses
            assert all(windows_name_problem(n_) is None for n_ in (
                "top/a/b.txt", "top/./x", "top/.hidden", "top/console", "top/nul_file", "top/com10", "top/a.b.c", "top/"))
            assert all(windows_name_problem(n_) for n_ in (
                "top/d:evil.txt", "top/con", "top/NUL.txt", "top/com1", "top/lpt9.log", "top/x./y", "top/x /y",
                "top/trailing.", 'top/a"b', "top/a?b", "top/a*b", "top/a<b", "top/a>b", "top/a|b"))
            win_zip = zip_of("win.zip", [good_e, ("top/d:evil.txt", b"x", {"raw": True})])
            long_zip = zip_of("long.zip", [good_e, ("top/" + "/".join(["d" * 50] * 6) + "/f.txt", b"x", {})])
            g["IS_WINDOWS"] = True
            refused_whole(win_zip, "a member Windows cannot hold under its name (top/d:evil.txt)")
            refused_whole(long_zip, "a member whose path on this box would be 260 characters or longer")
            g["IS_WINDOWS"] = False
            for path_ in (win_zip, long_zip):
                with zipfile.ZipFile(path_) as zf:
                    assert zip_refusal(zf.infolist(), path_ + ".out") is None, "those two rules are Windows' own"
            # (the two lengths Windows' own file calls refuse, each at its edge -- nothing is unpacked, one
            #  member's name is judged against a folder: WINDOWS_PATH_MAX for any member, twelve less for a
            #  folder, be it a directory entry or the folder a file lies in; counted as Windows counts, a
            #  character outside the Basic Multilingual Plane being two)
            short = os.sep + "e"
            base_ = len(os.path.abspath(short))

            def lies_at(length, tail=""):
                """The refusal of ONE member whose path in `short` has `length` characters and ends in `tail` --
                in folders of a hundred characters, so that no part is longer than a name may be."""
                info = zipfile.ZipInfo("placeholder")
                body = length - base_ - 1 - len(tail.rstrip("/"))
                info.orig_filename = info.filename = "".join("/" if n % 100 == 99 else "d" for n in range(body)) + tail
                return zip_refusal([info], short)

            TOO_LONG, TOO_DEEP = ("a member whose path on this box would be 260 characters or longer (",
                                  "a member whose folder on this box would lie at a path of 248 characters or longer (")
            assert (WINDOWS_PATH_MAX, WINDOWS_FOLDER_MAX) == (260, 248) and _counted_twice("plain") == 0 \
                and _counted_twice(chr(0xFC) + chr(0x6587) + chr(0xFFFF)) == 0 \
                and _counted_twice("a\U0001F600b\U00010000") == 2
            edges = (((259, ".txt"), None), ((260, ".txt"), TOO_LONG), ((247, "/"), None), ((248, "/"), TOO_DEEP),
                     ((253, "/f.txt"), None), ((254, "/f.txt"), TOO_DEEP),
                     ((258, "\U0001F600.txt"), None), ((259, "\U0001F600.txt"), TOO_LONG),
                     ((246, "\U0001F600/"), None), ((247, "\U0001F600/"), TOO_DEEP))
            for (length, tail), _text in edges:
                assert lies_at(length, tail) is None, "no length is refused where the tree is not written on Windows"
            g["IS_WINDOWS"] = True
            for (length, tail), text in edges:
                got = lies_at(length, tail)
                assert got is None if text is None else (got or "").startswith(text), (length, tail, got)
            # members that cannot lie in ONE tree, on every system: a path that is a file for one member and a
            # folder for another (either first; the folder a directory entry, or only where another file lies),
            # a file named `.` -- and on Windows two paths that differ in case alone, which would become one
            # file or one folder there. Each is named by the listing, before a byte is written
            for i, (pair, text) in enumerate((
                    ((("top/a", b"one"), ("top/a/b.txt", b"two")),
                     "a path that is a file in one member and a folder in another (top/a and top/a/b.txt)"),
                    ((("top/a/", None), ("top/a", b"one")),
                     "a path that is a file in one member and a folder in another (top/a/ and top/a)"),
                    ((("top/x/.", b"x"),), "a file named `.` (top/x/.)"))):
                clash = zip_of("tree%d.zip" % i, [good_e] + [(member, data, {"raw": True}) for member, data in pair])
                for windows in (False, True):
                    g["IS_WINDOWS"] = windows
                    refused_whole(clash, text)
            # (a file without a name of its own -- the empty name, one of `.` alone -- names the folder it would
            #  lie in, and a component of more than PART_BYTES_MAX bytes is one a Linux file system cannot hold:
            #  both refused on every system, before a byte is written)
            for i, (member, text) in enumerate((("./.", "a file without a name of its own ('./.')"),
                                                ("top/" + "\u00e9" * 128,
                                                 "a member name with a part of more than 255 bytes (top/"))):
                odd = zip_of("odd%d.zip" % i, [good_e, (member, b"x", {"raw": True})])
                for windows in (False, True):
                    g["IS_WINDOWS"] = windows
                    refused_whole(odd, text)
            assert zip_tree_problem({}, "", False) == "a file without a name of its own ('')" \
                and zip_tree_problem({}, "top/" + "\u00e9" * 127 + "a", False) is None \
                and zip_tree_problem({}, "top/" + "a" * 255, True) is None, "255 bytes in one part are one name"
            for i, (pair, text) in enumerate((
                    (("top/Same.txt", "top/same.txt"), "two paths that differ in case only (top/Same.txt and top/same.txt)"),
                    (("top/Data/a.txt", "top/data/b.txt"),
                     "two paths that differ in case only (top/Data/a.txt and top/data/b.txt)"),
                    (("top/Thing", "top/thing/b.txt"),
                     "a path that is a file in one member and a folder in another (top/Thing and top/thing/b.txt)"))):
                cased = zip_of("case%d.zip" % i, [good_e] + [(member, b"x", {}) for member in pair])
                g["IS_WINDOWS"] = True
                refused_whole(cased, text)
                g["IS_WINDOWS"] = False
                with zipfile.ZipFile(cased) as zf:
                    assert zip_refusal(zf.infolist(), cased + ".out") is None, "names told apart by their case are two names"
            # (a component `.` and an empty one are no folder of their own, and the same file stored twice is no
            #  clash: the tree is told by the paths the members are written at)
            grown = {}
            assert all(zip_tree_problem(grown, n_, False) is None for n_ in (
                "top/", "top/a.txt", "top/./b.txt", "top//c.txt", "top/a.txt", "top/d/./", "top/d/e.txt")) \
                and sorted(grown) == ["top", "top/a.txt", "top/b.txt", "top/c.txt", "top/d", "top/d/e.txt"], grown
            g["IS_WINDOWS"] = saved_f["IS_WINDOWS"]
            # a member that asks for a newer zip version than zipfile reads is no zip the agent can read
            newer = patch_central(zip_of("newer.zip", [good_e, ("top/new.bin", b"x", {})]), "top/new.bin", 6, "<H", 99)
            refused_whole(newer, "cannot be read as a zip (zip file version 9.9)")
            # a compression method this Python cannot read (Deflate64 is what Windows' own packer writes for a
            # large file): found by opening a member, not by a list -- without a tool the archive is refused
            # with the method named; with one the WHOLE archive goes to it, and one job line says why
            m9 = patch_central(zip_of("m9.zip", [good_e, ("top/packed.bin", b"y" * 100, {})]), "top/packed.bin", 10, "<H", 9)
            with zipfile.ZipFile(m9) as zf:
                assert zip_unreadable_methods(zf, zf.infolist()) == {9: "compression method 9 (deflate64)"}
            with zipfile.ZipFile(z_ok) as zf:
                assert zip_unreadable_methods(zf, zf.infolist()) == {}
            refused_whole(m9, "the archive uses compression method 9 (deflate64), which this Python cannot read, and the "
                              "box has no 7z extractor to hand it to")
            handed = []
            g["find_extractor"] = lambda: ("/fake/7zz", "7z")
            g["_extract_external"] = lambda found, archive, dest, job, should_stop=None, timeout=None: \
                handed.append((found, archive, dest, should_stop, timeout)) or 1.5
            jh, stop_h = _Job(), lambda: False
            assert extract_archive(m9, m9 + ".out", jh, should_stop=stop_h, timeout=77) == 1.5
            assert handed == [(("/fake/7zz", "7z"), m9, m9 + ".out", stop_h, 77)] and not os.path.exists(m9 + ".out"), handed
            assert jh.lines == ["The archive uses compression method 9 (deflate64), which the agent's own zip reader "
                                "cannot read -- unpacking it with 7zz."], jh.lines
            # (a readable zip never asks for a tool, whatever the box has)
            assert extract_archive(z_ok, os.path.join(zdir, "out-with-tool"), _Job()) >= 0 and len(handed) == 1
            g["_extract_external"] = saved_f["_extract_external"]
            g["find_extractor"] = lambda: None
            # a byte that changed inside a member: zipfile's CRC check ends the run at that member, named;
            # what was unpacked before it is the caller's to remove
            stored = bytes(range(256)) * 16
            crc = zip_of("crc.zip", [good_e, ("top/stored.bin", stored, {"method": zipfile.ZIP_STORED}),
                                     ("top/after.txt", b"never reached\n", {})])
            with open(crc, "rb") as f:
                raw = bytearray(f.read())
            raw[raw.find(stored) + 100] ^= 0xFF
            with open(crc, "wb") as f:
                f.write(raw)
            try:
                extract_archive(crc, crc + ".out", _Job())
                raise AssertionError("a member whose bytes changed must fail the extraction")
            except ExtractError as e:
                assert str(e).startswith("top/stored.bin cannot be read (Bad CRC-32"), str(e)
            assert tree_of(crc + ".out")[0].get("top/ok.txt") == b"fine\n" \
                and not os.path.exists(os.path.join(crc + ".out", "top", "after.txt"))
            # a stop request and the timeout are looked at between two pieces of a member
            asked_stop = []
            try:
                extract_archive(z_ok, os.path.join(zdir, "stopped"), _Job(),
                                should_stop=lambda: asked_stop.append(1) or len(asked_stop) > 4)
                raise AssertionError("a stop request must end the extraction")
            except ExtractStopped as e:
                assert str(e) == "stopped on request" and len(asked_stop) == 5, (str(e), asked_stop)
            part_files = tree_of(os.path.join(zdir, "stopped"))[0]
            assert "top/docker-compose.yml.tmpl" in part_files and "stray.txt" not in part_files, sorted(part_files)
            try:
                extract_archive(z_ok, os.path.join(zdir, "late"), _Job(), timeout=-1)
                raise AssertionError("the timeout must end the extraction")
            except ExtractStopped:
                raise AssertionError("out of time is not a stop request")
            except ExtractError as e:
                assert str(e) == "timed out after -1 s", str(e)
            ok("zip extraction OK (the agent's own reader on real zips: Deflate + Store + ZIP64 + an empty folder = the "
               "same tree, each entry's time and -- POSIX -- mode, a job line per step; refused whole with nothing "
               "written: six unsafe names -- one written with backslashes --, an encrypted member by either flag, "
               "compressed patched data, a symbolic link, members that cannot lie in one tree -- a file that is a "
               "folder elsewhere, a file named `.`, a file without a name of its own, a part of more than 255 "
               "bytes --, no zip at all, a zip version zipfile does not read, a volume "
               "too small, on Windows a name it cannot hold, two paths that differ in case only, a path of 260 "
               "characters and a folder at 248, both as Windows counts them; a method this Python cannot read: "
               "refused by name without a tool, the whole archive handed to the tool with one; a changed byte = "
               "the CRC refusal at that member; a stop request; the timeout)")

            # (10) The whole job on a catalogue that names a .zip, on a box with NO extractor: downloaded by the
            #      real _fetch_to_file from a stand-in upstream, unpacked by the agent, the .zip beside the folder
            #      gone afterwards -- and a .7z somebody put there neither used nor deleted, with its one line.
            nested_txt = "1.6_live/server/data/1.6_live-output_1-server-data/txt/ConstValueData.txt"
            zpath = zip_of("stack.zip", [("1.6_live/", None, {}),
                                         ("1.6_live/docker-compose.yml.tmpl", b"services: {}", {"method": zipfile.ZIP_STORED}),
                                         ("1.6_live/bootstrap.sh", b"#!/bin/sh", {}), (nested_txt, b"k\tv", {}),
                                         ("1.6_live/server/res/NavMesh/", None, {}), ("data.txt", b"stray", {})])
            with open(zpath, "rb") as f:
                zbody = f.read()
            zurl = "https://archive.org/download/test/1.6_live_gio.zip"
            zarc = {"url": zurl, "size": len(zbody), "md5": hashlib.md5(zbody).hexdigest()}
            zcat = dict(cat, **zarc)

            def ship_catalogue(doc):
                with open(os.path.join(PAYLOAD_DIR, "1.6", "stack.json"), "w") as f:
                    json.dump(doc, f)

            class Upstream:
                """What urlopen answers: the bytes of the address asked for, in pieces."""
                def __init__(self, data):
                    self.left, self.status, self.headers = data, 200, {"Content-Length": str(len(data))}

                def __enter__(self):
                    return self

                def __exit__(self, *a):
                    return False

                def read(self, n):
                    piece, self.left = self.left[:n], self.left[n:]
                    return piece

            served = {zurl: zbody, cat["url"]: body}

            def upstream(req, timeout=0):
                fetched.append(req.full_url)
                return Upstream(served[req.full_url])

            def never_fetch(url, dst, **kw):
                raise AssertionError("nothing is downloaded here: %s" % url)

            def brief():
                fb_ = fetch_brief("1.6")
                return fb_["kind"], fb_["tool"], fb_["size"], fb_["part"], fb_["archive"]

            urllib.request.urlopen = upstream
            g["_fetch_to_file"] = saved_f["_fetch_to_file"]
            ship_catalogue(zcat)
            del fetched[:]
            assert fetch_brief("1.6")["formats"] == ["zip"] and brief() == ("zip", "zipfile", len(zbody), 0, False), fetch_brief("1.6")
            assert fetch_preflight("1.6") == (zcat, None), "a .zip asks for no extractor"
            assert archive_path("1.6") == stack + ".zip" and archive_path("1.6", ".7z") == stack + ".7z"
            with open(stack + ".7z", "wb") as f:
                f.write(b"somebody's own archive")
            with open(stack + ".7z.part", "wb") as f:
                f.write(b"a partial download of that format")
            jz = _Job()
            res = do_fetch("1.6", jz)
            assert res == {"fetched": True, "downloaded": True, "bytes": len(zbody), "healed": 1,
                           "execBits": 1 if os.name == "posix" else 0, "dir": stack}, res
            assert is_present("1.6") and jz.yielding is True and fetched == [zurl], fetched
            assert not os.path.exists(stack + ".zip") and not os.path.exists(stack + ".zip.part") \
                and not os.path.exists(extract_tmp("1.6")), "the archive that was unpacked is deleted"
            assert os.listdir(os.path.join(stack, "server", "res", "NavMesh")) == [], "the empty folder of the package"
            assert os.path.isfile(os.path.join(stack, "server", "data", "txt", "ConstValueData.txt"))
            assert not os.path.exists(os.path.join(os.path.dirname(stack), "data.txt")), "the stray went with the temp folder"
            with open(stack + ".7z", "rb") as f:
                assert f.read() == b"somebody's own archive"
            with open(stack + ".7z.part", "rb") as f:
                assert f.read() == b"a partial download of that format", "the .part of a format the catalogue does not name stays"
            BESIDE = "%s is beside the folder as well -- not used and not deleted (%s)."
            PART = "%s (a partial download) is beside the folder as well -- not continued%s (%s)."
            GONE = "Removed %s -- a partial download nothing continues once the server is installed."
            assert [l for l in jz.lines if "beside the folder" in l] == [
                BESIDE % (stack + ".7z", "the catalogue of version 1.6 names no .7z package"),
                PART % (stack + ".7z.part", " and not deleted", "the catalogue of version 1.6 names no .7z package")], jz.lines
            assert not any(l.startswith("Removed ") for l in jz.lines), jz.lines
            os.remove(stack + ".7z.part")
            assert jz.lines[0].startswith("Downloading the 1.6 server package (") \
                and jz.lines[0].endswith(" GB) from archive.org into %s ..." % (stack + ".zip")), jz.lines[0]
            assert "Extracting with the agent's own zip reader ..." in jz.lines and "Archive verified (size + md5)." in jz.lines
            assert any(l.startswith("Unpacking %s -> %s (" % (stack + ".zip", extract_tmp("1.6"))) for l in jz.lines), \
                "the archive was at <dir>.zip and was unpacked into the temp folder beside the target"
            assert version_state("1.6")["fetchedFrom"] == "archive.org"
            # a pre-seed: the complete .zip beside the folder is adopted once its md5 is proven -- no download
            shutil.rmtree(stack)
            with open(stack + ".zip", "wb") as f:
                f.write(zbody)
            assert brief() == ("zip", "zipfile", len(zbody), 0, True), fetch_brief("1.6")
            g["_fetch_to_file"] = never_fetch
            jp = _Job()
            res = do_fetch("1.6", jp)
            assert res["downloaded"] is False and is_present("1.6") and not os.path.exists(stack + ".zip"), res
            assert any("pre-seeded" in l for l in jp.lines) and os.path.isfile(stack + ".7z"), jp.lines
            # an md5 that is not the catalogue's: 502, and nothing of that download stays beside the folder
            shutil.rmtree(stack)
            g["_fetch_to_file"] = saved_f["_fetch_to_file"]
            served[zurl] = bytes(reversed(zbody))
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a checksum mismatch must end in 502")
            except AgentError as e:
                assert e.status == 502 and "Checksum mismatch" in e.message, e.message
            assert not os.path.exists(stack + ".zip") and not os.path.exists(stack + ".zip.part") and not is_present("1.6")
            served[zurl] = zbody
            # an extraction that fails keeps the VERIFIED .zip (500) for the retry -- the archive the catalogue
            # names here holds a member whose bytes do not match its CRC
            zbad = bytearray(zbody)
            zbad[zbad.find(b"services: {}") + 3] ^= 0xFF
            zbad = bytes(zbad)
            ship_catalogue(dict(zcat, md5=hashlib.md5(zbad).hexdigest()))
            with open(stack + ".zip", "wb") as f:
                f.write(zbad)
            g["_fetch_to_file"] = never_fetch
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a failed extraction must fail the job")
            except AgentError as e:
                assert e.status == 500 and e.message.startswith(
                    "Unpacking the .zip failed (1.6_live/docker-compose.yml.tmpl cannot be read (Bad CRC-32") \
                    and e.message.endswith("-- the verified archive is kept at %s for a retry." % (stack + ".zip")), e.message
            with open(stack + ".zip", "rb") as f:
                assert f.read() == zbad and not is_present("1.6") and not os.path.exists(extract_tmp("1.6"))
            # ...and a stop request during the agent's own extraction: 409, the verified .zip kept, no temp folder
            ship_catalogue(zcat)
            with open(stack + ".zip", "wb") as f:
                f.write(zbody)
            g["_free_bytes_at"] = lambda _p: _fetch_cancel.set()  # asked by the extraction right before it writes
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a stop during the extraction must end in 409")
            except AgentError as e:
                assert e.status == 409 and e.message.startswith("Stopped on request during the extraction"), e.message
            g["_free_bytes_at"] = lambda _p: None
            _fetch_cancel.clear()
            assert os.path.getsize(stack + ".zip") == len(zbody) and not is_present("1.6") \
                and not os.path.exists(extract_tmp("1.6"))
            # A file at <dir>.zip that is NOT the catalogue's archive is somebody's own -- a zip made of the
            # stack folder lands beside it under exactly this name -- and never makes way for the download:
            # 409 naming it, from its size before a job exists and from its md5 inside the job; the upstream is
            # asked nothing, the file is as it was, no .part appears. What is no file at all likewise.
            IN_THE_WAY = ("%s is in the way: it is not the catalogue's archive (%s). Move it away, then run this "
                          "again -- nothing was deleted.")

            def in_the_way(call, path, why):
                try:
                    call()
                    raise AssertionError("must be refused: %s (%s)" % (path, why))
                except AgentError as e:
                    assert e.status == 409 and e.message == IN_THE_WAY % (path, why), e.message

            g["_fetch_to_file"] = saved_f["_fetch_to_file"]
            del fetched[:]
            for own, why in ((b"a backup of the stack folder", "its size differs"), (bytes(len(zbody)), "its md5 differs")):
                with open(stack + ".zip", "wb") as f:
                    f.write(own)
                if len(own) == len(zbody):
                    assert fetch_preflight("1.6") == (zcat, None), "a file of the archive's size: its md5 is the job's to read"
                else:
                    in_the_way(lambda: fetch_preflight("1.6"), stack + ".zip", why)
                in_the_way(lambda: do_fetch("1.6", _Job()), stack + ".zip", why)
                with open(stack + ".zip", "rb") as f:
                    assert f.read() == own, "nothing was deleted"
                assert fetched == [] and not os.path.exists(stack + ".zip.part") and not is_present("1.6"), fetched
            os.remove(stack + ".zip")
            os.makedirs(stack + ".zip")
            in_the_way(lambda: fetch_preflight("1.6"), stack + ".zip", "it is not a file")
            in_the_way(lambda: do_fetch("1.6", _Job()), stack + ".zip", "it is not a file")
            os.rmdir(stack + ".zip")
            assert stack_archive_misfit(zarc, stack + ".zip") is None and fetch_preflight("1.6") == (zcat, None)
            os.remove(stack + ".7z")

            # (11) A catalogue that names BOTH formats: the first archive the box can unpack -- the .7z with an
            #      extractor, the .zip without one --, and before that choice a verified archive of either usable
            #      format that already lies beside the folder, the catalogue's order deciding between two.
            both_cat = dict(cat, alt=[zarc])
            ship_catalogue(both_cat)
            real_extract = saved_f["extract_archive"]

            def either_extract(archive, dest, job, should_stop=None, timeout=EXTRACT_TIMEOUT):
                """The block's stand-in for a .7z (no tool is run here), the agent's own reader for a .zip."""
                if archive.endswith(".7z"):
                    return fake_extract2(archive, dest, job, should_stop, timeout)
                return real_extract(archive, dest, job, should_stop=should_stop, timeout=timeout)

            def beside_both(found, seeds=(), parts=()):
                """The two-format catalogue's box before a job: `found` as its extractor, no stack folder, the
                named archives pre-seeded (a dict gives each its own bytes) and the .part files of `parts`."""
                if os.path.isdir(stack):
                    shutil.rmtree(stack)
                for ext_, data in ((".7z", body), (".zip", zbody)):
                    _remove_quiet(stack + ext_)
                    _remove_quiet(stack + ext_ + ".part")
                    if ext_ in seeds:
                        with open(stack + ext_, "wb") as f:
                            f.write(dict(seeds)[ext_] if isinstance(seeds, dict) else data)
                    if ext_ in parts:
                        with open(stack + ext_ + ".part", "wb") as f:
                            f.write(data[:10])
                g.update({"find_extractor": lambda: found, "extract_archive": either_extract,
                          "_fetch_to_file": saved_f["_fetch_to_file"]})
                del fetched[:], extracted[:]

            def run_both(found, seeds=(), parts=()):
                """One job over the two-format catalogue on that box; -> (result, job, what was asked of the
                upstream, what the status said of the download beforehand)."""
                beside_both(found, seeds, parts)
                job_ = _Job()
                seen_brief = brief()
                res_ = do_fetch("1.6", job_)
                assert is_present("1.6") and not os.path.exists(extract_tmp("1.6")), res_
                return res_, job_, list(fetched), seen_brief

            tool7 = ("/fake/7zz", "7z")
            g["find_extractor"] = lambda: tool7
            assert fetch_brief("1.6")["formats"] == ["7z", "zip"] and fetch_preflight("1.6") == (both_cat, "/fake/7zz")
            res, jb, asked_, seen_ = run_both(tool7)
            assert seen_ == ("7z", "7zz", len(body), 0, False) and asked_ == [cat["url"]] and extracted == [stack + ".7z"] \
                and res["bytes"] == len(body) and res["downloaded"] is True, (seen_, asked_, extracted, res)
            res, jb, asked_, seen_ = run_both(None)
            assert seen_ == ("zip", "zipfile", len(zbody), 0, False) and asked_ == [zurl] and extracted == [] \
                and res["bytes"] == len(zbody) and res["downloaded"] is True, (seen_, asked_, extracted, res)
            assert "Extracting with the agent's own zip reader ..." in jb.lines
            # a pre-seeded .zip wins over the download of the .7z this box would otherwise take ...
            res, jb, asked_, seen_ = run_both(tool7, seeds=(".zip",))
            assert seen_ == ("zip", "zipfile", len(zbody), 0, True) and asked_ == [] and extracted == [] \
                and res == dict(res, downloaded=False, bytes=len(zbody)) and not os.path.exists(stack + ".zip"), (seen_, res)
            # ... both pre-seeded: the catalogue's order decides, and the other one stays where it is, named
            res, jb, asked_, seen_ = run_both(tool7, seeds=(".7z", ".zip"))
            assert seen_ == ("7z", "7zz", len(body), 0, True) and asked_ == [] and extracted == [stack + ".7z"] \
                and res["downloaded"] is False and not os.path.exists(stack + ".7z"), (seen_, res)
            with open(stack + ".zip", "rb") as f:
                assert f.read() == zbody
            assert [l for l in jb.lines if "beside the folder" in l] == [BESIDE % (stack + ".zip", "the .7z is the one in use")], jb.lines
            # ... a .7z the box cannot unpack is no pre-seed: the .zip is downloaded, the .7z named and left
            res, jb, asked_, seen_ = run_both(None, seeds=(".7z",))
            assert seen_ == ("zip", "zipfile", len(zbody), 0, False) and asked_ == [zurl] and os.path.getsize(stack + ".7z") == len(body)
            assert [l for l in jb.lines if "beside the folder" in l] == [
                BESIDE % (stack + ".7z", "this box has no 7z extractor to unpack it")], jb.lines
            # ... and a file of the right size that is NOT the catalogue's archive is no pre-seed either: beside
            # the format in use it is named and left ...
            res, jb, asked_, seen_ = run_both(tool7, seeds={".zip": bytes(len(zbody))})
            assert asked_ == [cat["url"]] and extracted == [stack + ".7z"] and res["downloaded"] is True, (asked_, res)
            with open(stack + ".zip", "rb") as f:
                assert f.read() == bytes(len(zbody)), "not the catalogue's file: not used, not deleted"
            assert [l for l in jb.lines if "beside the folder" in l] == [BESIDE % (stack + ".zip", "its md5 is not the catalogue's")]
            assert any(l.startswith("Downloading the .7z package instead (") for l in jb.lines), jb.lines
            # ... and where the download would put its own archive it is in the way, in either format: the job
            # ends 409 with that file named, every file beside the folder as it was and the upstream asked nothing
            for found_, seeds_, ext_, why, other in (
                    (tool7, {".7z": bytes(len(body)), ".zip": b"short"}, ".7z", "its md5 differs",
                     "its size is not the catalogue's"),
                    (tool7, {".7z": b"short", ".zip": bytes(len(zbody))}, ".7z", "its size differs",
                     "its md5 is not the catalogue's"),
                    (None, {".7z": bytes(len(body)), ".zip": bytes(len(zbody))}, ".zip", "its md5 differs",
                     "this box has no 7z extractor to unpack it")):
                beside_both(found_, seeds_)
                jb = _Job()
                in_the_way(lambda: do_fetch("1.6", jb), stack + ext_, why)
                for kept_ext, kept_bytes in seeds_.items():
                    with open(stack + kept_ext, "rb") as f:
                        assert f.read() == kept_bytes, "%s: nothing was deleted" % kept_ext
                assert fetched == [] and extracted == [] and not is_present("1.6") \
                    and not any(os.path.exists(stack + e_ + ".part") for e_ in STACK_ARCHIVE_EXTS), (ext_, why, fetched)
                the_other = next(e_ for e_ in STACK_ARCHIVE_EXTS if e_ != ext_)
                assert [l for l in jb.lines if "beside the folder" in l] == [BESIDE % (stack + the_other, other)], jb.lines
            # A partial download of the format a run does not take is the agent's own, left by a run that took
            # the other one: named in one line, not continued, and removed once the server is installed -- as is
            # the .part a pre-seed made needless. A run that fails removes none.
            res, jb, asked_, seen_ = run_both(tool7, parts=(".zip",))
            assert asked_ == [cat["url"]] and extracted == [stack + ".7z"] and not os.path.exists(stack + ".zip.part")
            assert [l for l in jb.lines if ".part" in l] == [
                PART % (stack + ".zip.part", "", "the .7z is the one in use"), GONE % (stack + ".zip.part")], jb.lines
            res, jb, asked_, seen_ = run_both(None, parts=(".7z",))
            assert asked_ == [zurl] and extracted == [] and not os.path.exists(stack + ".7z.part")
            assert [l for l in jb.lines if ".part" in l] == [
                PART % (stack + ".7z.part", "", "this box has no 7z extractor to unpack it"), GONE % (stack + ".7z.part")], jb.lines
            res, jb, asked_, seen_ = run_both(tool7, seeds=(".7z",), parts=(".7z", ".zip"))
            assert asked_ == [] and res["downloaded"] is False \
                and not any(os.path.exists(stack + e_ + ".part") for e_ in STACK_ARCHIVE_EXTS)
            assert [l for l in jb.lines if ".part" in l] == [
                PART % (stack + ".zip.part", "", "the .7z is the one in use"), GONE % (stack + ".7z.part"),
                GONE % (stack + ".zip.part")], jb.lines
            beside_both(tool7, seeds=(".7z",), parts=(".zip",))
            fail_extract.append(1)
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a failed extraction must fail the job")
            except AgentError as e:
                assert e.status == 500 and "kept" in e.message, e.message
            finally:
                fail_extract.clear()
            assert os.path.getsize(stack + ".7z") == len(body) and os.path.getsize(stack + ".zip.part") == 10, \
                "the job did not finish: the verified archive and the other format's .part are both still there"
            # A complete file of ANOTHER format that turns out not to be the catalogue's is no reason to refuse:
            # the download of the first archive takes its place in the plan, and its room on the disk is asked
            # for before its first byte -- the preflight had reckoned with the file that was there
            beside_both(tool7, seeds={".zip": bytes(len(zbody))})
            disk_asked = []
            g["_free_bytes_at"] = lambda _p: disk_asked.append(1) or (None if len(disk_asked) == 1 else 10)
            try:
                do_fetch("1.6", _Job())
                raise AssertionError("a download there is no room for must be refused before it starts")
            except AgentError as e:
                assert e.status == 409 and "Not enough free disk space" in e.message, e.message
            assert fetched == [] and len(disk_asked) == 2 and not is_present("1.6") \
                and os.path.getsize(stack + ".zip") == len(zbody) and not os.path.exists(stack + ".7z.part"), disk_asked
            g["_free_bytes_at"] = lambda _p: None
            _remove_quiet(stack + ".zip")

            # (12) What a download left beside a folder follows a move of it -- the formats that version's
            #      catalogue names; every known one only for a version without a usable catalogue.
            def moved_with(exts):
                old_d, new_d = os.path.join(td, "mv", "old"), os.path.join(td, "mv", "new")
                shutil.rmtree(os.path.join(td, "mv"), ignore_errors=True)
                os.makedirs(old_d)
                for suffix in (".7z", ".7z.part", ".zip", ".zip.part", ".rar"):
                    write_text(old_d + suffix, suffix)
                _relocate_siblings(old_d, new_d, _Job(), exts)
                return sorted(n_[3:] for n_ in os.listdir(os.path.join(td, "mv")) if n_.startswith("new"))

            ship_catalogue(cat)
            assert stack_archive_exts("1.6") == (".7z",) and moved_with(stack_archive_exts("1.6")) == [".7z", ".7z.part"]
            ship_catalogue(zcat)
            assert stack_archive_exts("1.6") == (".zip",) and moved_with(stack_archive_exts("1.6")) == [".zip", ".zip.part"]
            ship_catalogue(both_cat)
            assert moved_with(stack_archive_exts("1.6")) == [".7z", ".7z.part", ".zip", ".zip.part"]
            ship_catalogue(dict(cat, topDir="../x"))
            assert stack_archive_exts("1.6") == STACK_ARCHIVE_EXTS and stack_archive_exts("2.8") == STACK_ARCHIVE_EXTS, \
                "no usable catalogue: an archive brought by hand may be either"
            assert moved_with(stack_archive_exts("2.8")) == [".7z", ".7z.part", ".zip", ".zip.part"]
            ok("server package formats OK (a .zip catalogue with no extractor: real download + the agent's own "
               "extraction, the .zip gone after it, a pre-seed adopted, a wrong md5 = 502 with nothing kept, a failed "
               "extraction and a stop keep the verified .zip, a .7z beside it named and left; both formats: the .7z "
               "with an extractor, the .zip without, a verified pre-seed of either usable format first -- the "
               "catalogue's order between two --; a file that is not the catalogue's archive named and left beside "
               "the format in use and, where the download would put its own, a 409 with nothing deleted -- by its "
               "size before a job exists, by its md5 inside it, a folder too; the room for a download that takes "
               "another format's place asked for first; a partial download of the other format named, not "
               "continued and removed with the finish, one of a format the catalogue does not name left; kind / "
               "tool / size / formats in the status; the archives that follow a moved folder are the catalogue's "
               "formats)")
        finally:
            time.sleep = saved_sleep
            urllib.request.urlopen = saved_urlopen_f
            g.update(saved_f)
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_
            _fetch_cancel.clear()

    # Prepare-the-server progress choice on fakes (no docker, no MySQL): default | keep |
    # fixes stages + record, the v2 marker (re-seed, migration, forget), needs_provision's keep/fixes
    # rule, do_setup's decisions, do_start's pathfinding re-assert, the pending-password gate, the
    # routes' 400s and /status + the public projection of a server without the default save.
    g = globals()
    faked_p = ("STATE_PATH", "PAYLOAD_DIR", "PROVISION_MODE", "TXT_FIXES_MODE", "TOKEN", "log_line", "read_manifest",
               "running_projects", "current_job", "down_all", "install_files", "mysql_exec", "mysql_import",
               "ensure_templates", "run_sql", "apply_events", "apply_tower_schedule", "tower_mark_applied",
               "apply_advertised_ip", "apply_hotpatch", "verify_stack", "ensure_exec_bits", "ensure_data_layout",
               "compose_binds_loopback", "_compose_stream", "wait_for_mysql", "ensure_muip_key",
               "set_account_password", "do_bootstrap", "do_provision", "apply_pathfinding", "reconcile_pathfinding",
               "drop_pathfinding_leftover",
               "game_services_up", "ensure_bind_ip", "ensure_env_secrets", "ensure_internal_sources", "_stream",
               "_bootstrap_windows", "KEEP_ENV")
    saved_p = {k: g[k] for k in faked_p}
    saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
    with tempfile.TemporaryDirectory() as td:
        try:
            stack = os.path.join(td, "1.6_live")
            os.makedirs(stack)
            for name in ("docker-compose.yml", ".bootstrap.lock"):
                open(os.path.join(stack, name), "w").close()
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = stack, _project_name(stack)
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = "", ""
            os.makedirs(os.path.join(td, "payloads", "1.6", "mysql"))
            with open(os.path.join(td, "payloads", "1.6", "mysql", "hk4e_db_user.sql"), "w") as f:
                f.write("-- dump\n")
            man = {"account": "aether", "password": "123123123",
                   "files": [{"src": "sdk/data/sdk.db", "dst": "sdk/data/sdk.db", "stage": "save"},
                             {"src": "redis/dump.rdb", "dst": "redis/dump.rdb", "stage": "save"},
                             {"src": "txt/MaterialDeleteData.txt", "dst": "server/data/txt/MaterialDeleteData.txt",
                              "stage": "save", "tsv": True},
                             {"src": "txt/NewActivityCondData.txt", "dst": "server/data/txt/NewActivityCondData.txt",
                              "stage": "txt_fix", "tsv": True}],
                   "mysql": [{"src": "mysql/hk4e_db_user.sql", "db": "hk4e_db_user", "recreate": True}],
                   "templates": []}
            # (the files it names are in the payload folder: a provision proves its sources before it stops
            # anything, whatever installs them afterwards)
            for item in man["files"]:
                src_ = os.path.join(td, "payloads", "1.6", *item["src"].split("/"))
                os.makedirs(os.path.dirname(src_), exist_ok=True)
                with open(src_, "wb") as f:
                    f.write(b"id\tname\n1\ta\n" if item.get("tsv") else b"payload\n")
            calls = {"stages": [], "imports": [], "templates": 0, "pw": []}
            done = subprocess.CompletedProcess([], 0, stdout="", stderr="")
            sp = os.path.join(td, "state.json")

            def put(data):
                with open(sp, "wb") as f:
                    f.write(data)

            g.update({"STATE_PATH": sp, "PAYLOAD_DIR": os.path.join(td, "payloads"), "PROVISION_MODE": "once",
                      "TXT_FIXES_MODE": "now", "log_line": lambda *_a: None,
                      "read_manifest": lambda _v: man if _v == "1.6" else None,
                      "running_projects": lambda: ([], None), "current_job": lambda **_k: None,
                      "down_all": lambda *a, **k: None,
                      "install_files": lambda _v, _j, stages: calls["stages"].append(set(stages)) or len(stages),
                      "mysql_exec": lambda *a, **k: done,
                      "mysql_import": lambda _v, _src, db: calls["imports"].append(db) or done,
                      "ensure_templates": lambda _v, _j: calls.__setitem__("templates", calls["templates"] + 1) or {},
                      "run_sql": lambda *a, **k: None, "apply_events": lambda *a, **k: None,
                      "apply_tower_schedule": lambda *a, **k: None, "tower_mark_applied": lambda *a, **k: None,
                      "apply_advertised_ip": lambda *a, **k: False, "apply_hotpatch": lambda *a, **k: False,
                      "verify_stack": lambda *a, **k: None, "ensure_exec_bits": lambda *a, **k: 0,
                      "ensure_data_layout": lambda *a, **k: 0, "compose_binds_loopback": lambda _v: False,
                      "_compose_stream": lambda *a, **k: 0, "wait_for_mysql": lambda *a, **k: None,
                      "ensure_muip_key": lambda *a, **k: None,
                      "set_account_password": lambda _v, _j, name, _pw: calls["pw"].append(name),
                      "apply_pathfinding": lambda *a, **k: False, "reconcile_pathfinding": lambda *a, **k: False,
                      "drop_pathfinding_leftover": lambda *a, **k: None,
                      # (a start of a listed stack asks docker whether its game services run)
                      "game_services_up": lambda _v: None})
            assert parse_progress(None) == "default" and parse_progress("") == "default" and parse_progress(" Keep ") == "keep"
            for bad in ("nope", 1, True, ["keep"]):
                try:
                    parse_progress(bad)
                    raise AssertionError("parse_progress must refuse %r" % (bad,))
                except AgentError as e:
                    assert e.status == 400 and "progress must be one of default, keep, fixes" == e.message
            assert [effective_stage(i) for i in man["files"]] == ["save", "save", "config", "txt_fix"], \
                "a save+tsv entry counts as config"

            # (A) keep on a fresh stack: no save, no import, templates yes, no pre-made account anywhere
            put(b"{}")
            j = _Job()
            res = do_provision("1.6", j, progress="keep")
            assert res["provisioned"] and res["progress"] == "keep" and res["defaultAccount"] is False \
                and res["txtFixes"] == "applied", res
            assert calls["stages"][-1] == {"config", "txt_fix"} and calls["imports"] == [] and calls["templates"] == 1, calls
            vs = version_state("1.6")
            gen_keep = vs["provisionedAt"]
            assert gen_keep and vs["progress"] == "keep" and vs["defaultAccount"] is False, vs
            assert read_provisioned_marker("1.6") == {"at": gen_keep, "progress": "keep", "defaultAccount": False}
            assert any("No pre-made account" in l for l in j.lines) and not any("Game account" in l for l in j.lines), j.lines
            assert any("progress: keep" in l for l in j.lines), j.lines
            st16 = g["status"]()["versions"]["1.6"]
            assert st16["account"] is None and st16["progress"] == "keep" and st16["defaultAccount"] is False, st16
            assert build_public_status(g["status"](), default_policy())["versions"]["1.6"]["defaultAccount"] == ""
            assert needs_provision("1.6") is False, "a keep stack is never auto-imported"
            g["PROVISION_MODE"] = "switch"
            state_set(lastStarted="2.8")
            assert needs_provision("1.6") is False, "...not even by switch on a version switch"
            g["PROVISION_MODE"] = "once"
            g["do_provision"] = lambda *a, **k: (_ for _ in ()).throw(AssertionError("do_provision must not run"))
            res = do_start("1.6", _Job(), provision="auto")
            assert res["started"] and res["provisioned"] is False, res
            g["do_provision"] = saved_p["do_provision"]

            # (B) fixes over the keep stack: config + txt fixes only (txtFixes=later ignored), no templates,
            # the generation is kept
            version_state_set("1.6", provisionedAt="2026-08-01 10:00:00")
            calls["templates"] = 0
            res = do_provision("1.6", _Job(), progress="fixes", txt_fixes="later")
            assert res["progress"] == "fixes" and res["txtFixes"] == "applied" and res["defaultAccount"] is False, res
            assert calls["stages"][-1] == {"config", "txt_fix"} and calls["imports"] == [] and calls["templates"] == 0, calls
            assert version_state("1.6")["provisionedAt"] == "2026-08-01 10:00:00", "fixes keeps the generation"
            assert read_provisioned_marker("1.6")["progress"] == "fixes"

            # (C) default over the keep/fixes stack: the save + the import, a new generation, the account is back
            j = _Job()
            res = do_provision("1.6", j, progress="default")
            assert res == {"provisioned": True, "progress": "default", "defaultAccount": True, "txtFixes": "applied"}, res
            assert calls["stages"][-1] == {"save", "config", "txt_fix"} and calls["imports"] == ["hk4e_db_user"] \
                and calls["templates"] == 1, calls
            vs = version_state("1.6")
            assert vs["provisionedAt"] != "2026-08-01 10:00:00" and vs["progress"] == "default" and vs["defaultAccount"] is True, vs
            with open(provisioned_marker_path("1.6")) as f:
                assert f.read() == "%s\nprogress=default\ndefaultAccount=1\n" % vs["provisionedAt"]
            assert any("Game account: aether" in l for l in j.lines), j.lines
            st16 = g["status"]()["versions"]["1.6"]
            assert st16["account"] == "aether" and st16["progress"] == "default" and st16["defaultAccount"] is True, st16
            assert build_public_status(g["status"](), default_policy())["versions"]["1.6"]["defaultAccount"] == "aether"

            # (D) keep over a default stack: no import, generation + defaultAccount kept (the save is still there)
            version_state_set("1.6", provisionedAt="2026-08-01 10:00:00")
            del calls["imports"][:]
            res = do_provision("1.6", _Job(), progress="keep")
            assert res["defaultAccount"] is True and calls["imports"] == [], res
            assert version_state("1.6")["provisionedAt"] == "2026-08-01 10:00:00", "keep keeps the generation"
            assert read_provisioned_marker("1.6") == {"at": "2026-08-01 10:00:00", "progress": "keep", "defaultAccount": True}
            assert g["status"]()["versions"]["1.6"]["account"] == "aether", "the default save is still in the database"

            # (D2) the accounts a stack came with. Only the save replaces sdk.db, so a keep / fixes run over a
            # database the bootstrap has just created leaves the file as the package brought it -- and says
            # ONCE how many accounts it holds. Nothing for an empty file, for one that is missing or is no
            # account database, for a run over a database that was already there, for the default save.
            sdk_db = os.path.join(stack, "sdk", "data", "sdk.db")
            os.makedirs(os.path.dirname(sdk_db))

            def sdk_accounts(*names, **kw):
                _remove_quiet(sdk_db)
                con = sqlite3.connect(sdk_db)
                try:
                    con.execute("CREATE TABLE %s (uid INTEGER PRIMARY KEY, name TEXT)" % kw.get("table", "accounts"))
                    con.executemany("INSERT INTO %s (name) VALUES (?)" % kw.get("table", "accounts"),
                                    [(name,) for name in names])
                    con.commit()
                finally:
                    con.close()

            def came_with(**kw):
                j = _Job()
                assert do_provision("1.6", j, **kw)["provisioned"]
                return [l for l in j.lines if l.startswith("WARNING") and "sdk.db" in l]

            sdk_accounts("packager", "guest")
            with open(sdk_db, "rb") as f:
                sdk_before = f.read()
            assert sdk_account_count("1.6") == 2
            said = came_with(progress="keep", fresh=True)
            assert said == ["WARNING: sdk/data/sdk.db already holds 2 account(s) although this server's database was "
                            "just created -- they came with the package or stayed from an earlier install; their "
                            "names log in here and start from a new character."], said
            assert len(came_with(progress="fixes", fresh=True)) == 1
            assert came_with(progress="keep") == [] and came_with(progress="fixes") == [], \
                "a database that was already there: its accounts are the server's own"
            assert came_with(progress="default", fresh=True) == [] and came_with(progress="default") == [], \
                "the default save replaces the file"
            with open(sdk_db, "rb") as f:
                assert f.read() == sdk_before, "the count is taken from a copy: the sdk's own file is as it was"
            # ...through the account list's guarded reader (read_sqlite_copy): a hot journal beside the file -- the sdk
            # in the middle of a write, the journal growing at every try -- is no count while it lasts, and the count
            # is there again once the write is over
            journal_, pauses_ = sdk_db + "-journal", []

            def sdk_writing(_seconds):
                pauses_.append(_seconds)
                with open(journal_, "wb") as f_:
                    f_.write(_SQLITE_JOURNAL_MAGIC + b"\0" * (16 * len(pauses_)))

            saved_pause = g["_sdk_db_pause"]
            g["_sdk_db_pause"] = sdk_writing
            try:
                sdk_writing(0)
                assert sdk_account_count("1.6") is None and len(pauses_) == SDK_DB_READ_TRIES, pauses_
            finally:
                g["_sdk_db_pause"] = saved_pause
                _remove_quiet(journal_)
            assert sdk_account_count("1.6") == 2 and not os.path.exists(journal_)
            sdk_accounts()
            assert sdk_account_count("1.6") == 0 and came_with(progress="keep", fresh=True) == []
            sdk_accounts("packager", table="accounts_guests")
            assert sdk_account_count("1.6") is None and came_with(progress="keep", fresh=True) == []
            with open(sdk_db, "wb") as f:
                f.write(b"not a database\n" * 64)
            assert sdk_account_count("1.6") is None and came_with(progress="keep", fresh=True) == []
            os.remove(sdk_db)
            assert sdk_account_count("1.6") is None and came_with(progress="keep", fresh=True) == []
            assert sdk_account_count("2.8") is None and sdk_account_count("0.0") is None, "no stack: no count, no error"
            shutil.rmtree(os.path.join(stack, "sdk"))

            # (E) the config stage is never reverted (the real revert_files over .orig files)
            txt_dir = os.path.join(stack, "server", "data", "txt")
            os.makedirs(txt_dir)
            for name in ("MaterialDeleteData.txt", "NewActivityCondData.txt"):
                write_text(os.path.join(txt_dir, name), "agent\n")
                write_text(os.path.join(txt_dir, name + ".orig"), "vendor\n")
            assert revert_files("1.6", _Job(), {"txt_fix"}) == 1
            assert read_text(os.path.join(txt_dir, "MaterialDeleteData.txt")) == "agent\n", "config is never reverted"
            assert read_text(os.path.join(txt_dir, "NewActivityCondData.txt")) == "vendor\n"

            # (F) the marker re-seeds the WHOLE record: a v2 keep marker keeps the stack out of auto-import
            put(b"{}")
            _write_stack_text(provisioned_marker_path("1.6"), "2026-08-14 21:03:11\nprogress=keep\ndefaultAccount=0\n")
            j = _Job()
            assert needs_provision("1.6", j) is False and any("progress keep" in l for l in j.lines), j.lines
            vs = version_state("1.6")
            assert vs["provisionedAt"] == "2026-08-14 21:03:11" and vs["progress"] == "keep" and vs["defaultAccount"] is False, vs
            assert g["status"]()["versions"]["1.6"]["account"] is None
            put(b"{}")
            _write_stack_text(provisioned_marker_path("1.6"), "2026-08-14 21:03:11\n")
            assert read_provisioned_marker("1.6") == {"at": "2026-08-14 21:03:11", "progress": "default", "defaultAccount": True}, \
                "a one-line marker of an older agent reads as the default save"
            assert needs_provision("1.6") is False and version_state("1.6")["progress"] == "default" \
                and version_state("1.6")["defaultAccount"] is True
            put(b'{"versions": {"1.6": {"provisionedAt": "2026-08-14 21:03:11"}}}')
            _write_stack_text(provisioned_marker_path("1.6"), "2026-08-14 21:03:11\nprogress=fixes\ndefaultAccount=0\n")
            st16 = g["status"]()["versions"]["1.6"]
            assert st16["progress"] == "fixes" and st16["defaultAccount"] is False and st16["account"] is None, \
                "status reads the marker's record when the state lacks it"

            # (G) migration at start: a record without progress is back-filled, a one-line marker rewritten, once
            os.remove(provisioned_marker_path("1.6"))
            put(b'{"versions": {"1.6": {"provisionedAt": "2026-08-01 10:00:00"}}}')
            assert migrate_provisioned_markers() == 1
            vs = version_state("1.6")
            assert vs["progress"] == "default" and vs["defaultAccount"] is True, vs
            with open(provisioned_marker_path("1.6")) as f:
                assert f.read() == "2026-08-01 10:00:00\nprogress=default\ndefaultAccount=1\n"
            assert migrate_provisioned_markers() == 0
            _write_stack_text(provisioned_marker_path("1.6"), "2026-08-01 10:00:00\n")
            version_state_set("1.6", progress="keep", defaultAccount=False)
            assert migrate_provisioned_markers() == 1
            assert read_provisioned_marker("1.6") == {"at": "2026-08-01 10:00:00", "progress": "keep", "defaultAccount": False}
            assert migrate_provisioned_markers() == 0

            # (H) a fresh bootstrap forgets the record: progress gone, defaultAccount False
            forget_provisioned("1.6", _Job())
            vs = version_state("1.6")
            assert not vs.get("provisionedAt") and vs.get("progress") is None and vs["defaultAccount"] is False, vs
            assert read_provisioned_marker("1.6") is None

            # (I) the pending password is dropped, not retried forever, on a stack without the account
            version_state_set("1.6", passwordPending=True, defaultAccount=False)
            j = _Job()
            apply_pending_password("1.6", j)
            assert version_state("1.6")["passwordPending"] is False and calls["pw"] == [] \
                and any("No pre-made account" in l for l in j.lines), (j.lines, calls["pw"])
            version_state_set("1.6", passwordPending=True, defaultAccount=True)
            apply_pending_password("1.6", _Job())
            assert calls["pw"] == ["aether"] and version_state("1.6")["passwordPending"] is False

            # (J) do_setup: the bootstrap outcome + the record decide what do_provision is asked for
            prov_calls = []
            g["do_provision"] = lambda _v, _j, **kw: prov_calls.append(kw) or dict(kw, provisioned=True)
            put(b"{}")
            g["do_bootstrap"] = lambda _v, _j, force=False: "fresh"
            do_setup("1.6", _Job(), progress="keep")
            assert prov_calls[-1] == {"txt_fixes": None, "fresh": True, "progress": "keep"}, prov_calls
            g["do_bootstrap"] = lambda _v, _j, force=False: None
            version_state_set("1.6", provisionedAt="2026-08-01 10:00:00", progress="default", defaultAccount=True)
            assert do_setup("1.6", _Job()) == {"provisioned": False, "alreadyReady": True}, "default on a ready stack: nothing redone"
            do_setup("1.6", _Job(), progress="fixes")
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "fixes"}, "keep/fixes on a ready stack: a non-destructive re-run"
            g["do_bootstrap"] = lambda _v, _j, force=False: "healed"
            do_setup("1.6", _Job(), progress="default")
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "default", "keep_db": True}, "healed default over default keeps the database"
            version_state_set("1.6", progress="keep", defaultAccount=False)
            do_setup("1.6", _Job(), progress="default")
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "default", "keep_db": False}, "healed default over keep imports"
            do_setup("1.6", _Job(), progress="keep")
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "keep", "keep_db": False}
            # (J2) THE data-loss case: the state record is gone (a restored .bak, a reset, a wipe)
            # but the stack's own marker still says default/1. A heal must read the MARKER-merged
            # record -- reading state alone would make "Prepare the server" re-import the save over a live
            # player database. needs_provision re-seeds the state from the marker first, so the
            # decision must be taken after that, never from a value captured before it.
            put(b"{}")
            write_provisioned_marker("1.6", "2026-08-01 10:00:00", "default", True)
            do_setup("1.6", _Job(), progress="default")
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "default", "keep_db": True}, \
                "healed default with the record only in the marker MUST keep the database: %s" % prov_calls[-1]
            # the same for a keep marker: the admin's "default" then really does import
            put(b"{}")
            write_provisioned_marker("1.6", "2026-08-01 10:00:00", "keep", False)
            do_setup("1.6", _Job(), progress="default")
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "default", "keep_db": False}, prov_calls[-1]
            # and provision_record itself: state wins where it has a value, the marker fills the rest
            put(b"{}")
            write_provisioned_marker("1.6", "2026-08-01 10:00:00", "default", True)
            rec = provision_record("1.6")
            assert rec["provisionedAt"] == "2026-08-01 10:00:00" and rec["progress"] == "default" \
                and rec["defaultAccount"] is True, rec
            version_state_set("1.6", progress="keep", defaultAccount=False)
            rec = provision_record("1.6")
            assert rec["progress"] == "keep" and rec["defaultAccount"] is False, rec
            os.remove(provisioned_marker_path("1.6"))
            g["do_provision"] = saved_p["do_provision"]

            # (K) do_start re-asserts the stored pathfinding decision before the staged up; an already-up
            # stack being disabled is reconciled, a down one is covered by the up -d that follows
            pf_calls = []
            g["apply_pathfinding"] = lambda _v, _j, on: pf_calls.append(("apply", on)) or True
            g["reconcile_pathfinding"] = lambda _v, _j, on: pf_calls.append(("reconcile", on)) or True
            version_state_set("1.6", pathfinding=False, provisionedAt="2026-08-01 10:00:00", progress="keep")
            g["running_projects"] = lambda: ([VERSIONS["1.6"]["project"]], None)
            do_start("1.6", _Job(), provision="none")
            assert pf_calls == [("apply", False), ("reconcile", False)], pf_calls
            del pf_calls[:]
            g["running_projects"] = lambda: ([], None)
            do_start("1.6", _Job(), provision="none")
            assert pf_calls == [("apply", False)], pf_calls
            del pf_calls[:]
            version_state_set("1.6", pathfinding=True)
            g["running_projects"] = lambda: ([VERSIONS["1.6"]["project"]], None)
            do_start("1.6", _Job(), provision="none")
            assert pf_calls == [("apply", True)], "enable on an up stack: the up -d below starts it"

            # (L) the routes: a bad progress / pathfinding / enabled is a 400 before any job exists
            g["TOKEN"] = "selftest-token"
            reply = []
            hh = Handler.__new__(Handler)
            hh._send = lambda status_, obj, retry_after=None: reply.append((status_, obj))
            for path, body, text in (("/server/setup", b'{"version": "1.6", "progress": "nope"}', "progress must be one of"),
                                     ("/server/provision", b'{"version": "1.6", "progress": "all"}', "progress must be one of"),
                                     ("/server/setup", b'{"version": "1.6", "pathfinding": "yes"}', "pathfinding must be"),
                                     ("/server/pathfinding", b'{"version": "1.6", "enabled": 1}', "enabled must be")):
                del reply[:]
                hh.path, hh.rfile = path, io.BytesIO(body)
                hh.headers = {"Authorization": "Bearer selftest-token", "Content-Length": str(len(body))}
                hh.do_POST()
                assert reply and reply[0][0] == 400 and text in reply[0][1]["error"], (path, reply)

            # (M) A version whose payload ships no save -- here one table of the config stage and nothing else.
            # `default` has nothing to import there: it runs, and is recorded, as `keep`; no account is ever
            # reported, no txt fix is owed, nothing is provisioned on its own, and the txt-fixes job does not
            # stop a server it has no file for. A version WITHOUT a manifest is none of this: nothing tells
            # what it ships, and every mode runs as it is asked.
            saveless = {"files": [{"src": "txt/QuestData.txt", "dst": "server/data/txt/QuestData.txt",
                                   "stage": "config", "tsv": True}]}
            with open(os.path.join(td, "payloads", "1.6", "txt", "QuestData.txt"), "wb") as f:
                f.write(b"id\tname\n1\ta\n")
            full = dict(man, events={"gaa": {"2005001": "kept open"}})
            NO_SAVE = "Version 1.6 ships no save -- nothing to import; this run keeps the database as it is."
            READY_LINE = "The 1.6 stack is already installed and provisioned -- nothing redone, the progress stays."

            def ships(manifest):
                g["read_manifest"] = lambda _v: manifest if _v == "1.6" else None

            assert manifest_ships_save(man) and manifest_has_stage(man, "txt_fix") and manifest_has_stage(man, "config") \
                and not manifest_has_events(man) and manifest_has_events(full)
            assert not manifest_ships_save(saveless) and manifest_has_stage(saveless, "config") \
                and not manifest_has_stage(saveless, "txt_fix") and not manifest_has_events(saveless)
            for nothing in (None, {}, {"files": None}, {"files": "x", "mysql": []}, {"files": [3, None]}, {"events": {}}):
                assert not manifest_ships_save(nothing) and not manifest_has_stage(nothing, "config") \
                    and not manifest_has_events(nothing), nothing
            assert manifest_ships_save({"mysql": [{"src": "x.sql", "db": "hk4e_db_user"}]}), "a dump alone is a save"
            assert not manifest_ships_save({"files": [
                {"src": "a.txt", "dst": "a.txt", "stage": "save", "tsv": True},
                {"src": "b", "dst": "b", "stage": "bootstrap", "overMd5": ["0" * 32]}]}), \
                "a save entry flagged tsv is a data file, and a bootstrap entry is no progress"
            ships(saveless)
            j = _Job()
            assert effective_progress("1.6", "default", j) == "keep" and j.lines == [NO_SAVE], j.lines
            j = _Job()
            assert effective_progress("1.6", "keep", j) == "keep" and effective_progress("1.6", "fixes", j) == "fixes" \
                and effective_progress("2.8", "default", j) == "default" and j.lines == [], \
                "keep and fixes as they are asked; a version without a manifest keeps default"
            ships(man)
            assert effective_progress("1.6", "default", j) == "default" and j.lines == []
            # do_provision: default answers keep -- no save stage, no import, no account, no txt fix owed, a generation
            ships(saveless)
            put(b"{}")
            g.update({"running_projects": lambda: ([], None), "apply_pathfinding": lambda *a, **k: False,
                      "reconcile_pathfinding": lambda *a, **k: False})
            del calls["imports"][:]
            j = _Job()
            res = do_provision("1.6", j, progress="default")
            assert res == {"provisioned": True, "progress": "keep", "defaultAccount": False, "txtFixes": "none"}, res
            assert "save" not in calls["stages"][-1] and "config" in calls["stages"][-1] and calls["imports"] == [], calls
            assert j.lines.count(NO_SAVE) == 1 and any("progress: keep" in l for l in j.lines) \
                and any("No pre-made account" in l for l in j.lines) \
                and not any("Apply txt fixes" in l for l in j.lines), j.lines
            vs = version_state("1.6")
            assert vs["provisionedAt"] and vs["progress"] == "keep" and vs["defaultAccount"] is False \
                and vs["txtFixes"] == "none", vs
            assert read_provisioned_marker("1.6") == {"at": vs["provisionedAt"], "progress": "keep", "defaultAccount": False}
            # ...a second run keeps the generation; and a record that says the shipped save is in the database
            # (another payload's, a hand edit) is never carried over, whatever mode is asked
            for mode, recorded in (("default", "keep"), ("keep", "keep"), ("fixes", "fixes")):
                version_state_set("1.6", provisionedAt="2026-08-01 10:00:00", progress="default", defaultAccount=True)
                res = do_provision("1.6", _Job(), progress=mode)
                assert res == {"provisioned": True, "progress": recorded, "defaultAccount": False, "txtFixes": "none"}, \
                    (mode, res)
                assert read_provisioned_marker("1.6") == {"at": "2026-08-01 10:00:00", "progress": recorded,
                                                          "defaultAccount": False}, mode
                assert version_state("1.6")["defaultAccount"] is False and calls["imports"] == [], mode
            st16 = g["status"]()["versions"]["1.6"]
            assert st16["account"] is None and st16["defaultAccount"] is False and st16["txtFixes"] == "none", st16
            # never provisioned on its own: not by once, not by switch, and the state-recovery guard does not
            # wait for it -- while the same stack under a payload that ships a save is, and holds the guard
            put(b"{}")
            os.remove(provisioned_marker_path("1.6"))
            assert needs_provision("1.6") is False and _without_provision_record("1.6", {}) is False
            g["PROVISION_MODE"] = "switch"
            state_set(lastStarted="2.8")
            assert needs_provision("1.6") is False, "...nor by switch on a version switch"
            g["PROVISION_MODE"] = "once"
            ships(man)
            assert needs_provision("1.6") is True and _without_provision_record("1.6", {}) is True
            g["read_manifest"] = lambda _v: None
            assert needs_provision("1.6") is False and _without_provision_record("1.6", {}) is True, \
                "no payload manifest at all: nothing to import while it is missing -- and the guard waits for it"
            ships(saveless)
            g["do_provision"] = lambda *a, **k: (_ for _ in ()).throw(AssertionError("do_provision must not run"))
            res = do_start("1.6", _Job(), provision="auto")
            assert res["started"] and res["provisioned"] is False, res
            # THE case the guard is for: the state was reset, the stack has no record, and at a Start the
            # payload folder is not there. That Start imports nothing -- and leaves the guard in place: lifted,
            # it would let the Start after the payload is back import the save over the database
            put(b'{"stateReset": {"at": "2026-08-01 10:00:00"}}')
            g["read_manifest"] = lambda _v: None
            j = _Job()
            res = do_start("1.6", j, provision="auto")
            assert res["started"] and res["provisioned"] is False and load_state().get("stateReset"), res
            assert any(l.startswith("Automatic provisioning stays off for 1.6 ") for l in j.lines), j.lines
            ships(man)
            j = _Job()
            res = do_start("1.6", j, provision="auto")
            assert res["started"] and res["provisioned"] is False and load_state().get("stateReset"), \
                "the payload is back and ships a save: still no import, the guard still waits"
            assert any("automatic provisioning is disabled" in l for l in j.lines), j.lines
            # ...while a manifest that ships no save holds nothing back: the same Start lifts the guard
            ships(saveless)
            j = _Job()
            do_start("1.6", j, provision="auto")
            assert not load_state().get("stateReset") and any("the state-recovery guard is lifted" in l for l in j.lines), \
                j.lines
            # A record lost with the state file comes back from the stack's marker for such a version as for
            # every other -- the per-launcher signup book is keyed on it -- and without a payload manifest too
            for shipped in (saveless, None):
                ships(shipped)
                put(b"{}")
                write_provisioned_marker("1.6", "2026-08-01 10:00:00", "keep", False)
                j = _Job()
                assert needs_provision("1.6", j) is False and sum("record restored" in l for l in j.lines) == 1, j.lines
                vs = version_state("1.6")
                assert vs["provisionedAt"] == "2026-08-01 10:00:00" and vs["progress"] == "keep" \
                    and vs["defaultAccount"] is False, (shipped is None, vs)
                assert _signup_gen(load_state(), "1.6") == "2026-08-01 10:00:00" \
                    == g["status"]()["versions"]["1.6"]["provisionedAt"], "the state and the status name one generation"
                j = _Job()
                assert needs_provision("1.6", j) is False and j.lines == [], "re-seeded once"
            os.remove(provisioned_marker_path("1.6"))
            ships(saveless)
            # do_setup: default on an installed stack WITHOUT a record runs the non-destructive provision, with
            # ONE line for the job; WITH a record -- in the state or in the marker alone -- nothing is redone
            prov_calls = []
            g["do_provision"] = lambda _v, _j, **kw: prov_calls.append(kw) or dict(kw, provisioned=True)
            g["do_bootstrap"] = lambda _v, _j, force=False: None
            put(b"{}")
            j = _Job()
            do_setup("1.6", j)
            assert prov_calls == [{"txt_fixes": None, "progress": "keep"}] and j.lines == [NO_SAVE], (prov_calls, j.lines)
            version_state_set("1.6", provisionedAt="2026-08-01 10:00:00", progress="keep", defaultAccount=False)
            j = _Job()
            assert do_setup("1.6", j) == {"provisioned": False, "alreadyReady": True} and len(prov_calls) == 1
            assert j.lines == [NO_SAVE, READY_LINE], j.lines
            put(b"{}")
            write_provisioned_marker("1.6", "2026-08-01 10:00:00", "keep", False)
            assert do_setup("1.6", _Job()) == {"provisioned": False, "alreadyReady": True} and len(prov_calls) == 1, \
                "a record that lives in the marker alone is a record"
            do_setup("1.6", _Job(), progress="keep")
            assert prov_calls[1:] == [{"txt_fixes": None, "progress": "keep"}], "an explicit keep on the ready stack re-runs"
            do_setup("1.6", _Job(), progress="fixes")
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "fixes"}
            g["do_bootstrap"] = lambda _v, _j, force=False: "fresh"
            do_setup("1.6", _Job())
            assert prov_calls[-1] == {"txt_fixes": None, "fresh": True, "progress": "keep"}, prov_calls[-1]
            g["do_bootstrap"] = lambda _v, _j, force=False: "healed"
            do_setup("1.6", _Job())
            assert prov_calls[-1] == {"txt_fixes": None, "progress": "keep", "keep_db": False}, prov_calls[-1]
            os.remove(provisioned_marker_path("1.6"))
            # (a version that ships a save: the same answer on a ready stack names the way to import it again)
            ships(man)
            g["do_bootstrap"] = lambda _v, _j, force=False: None
            version_state_set("1.6", provisionedAt="2026-08-01 10:00:00", progress="default", defaultAccount=True)
            j = _Job()
            assert do_setup("1.6", j) == {"provisioned": False, "alreadyReady": True}
            assert j.lines == [READY_LINE + " To deliberately re-import the save use Re-apply the progress."], j.lines
            g["do_provision"] = saved_p["do_provision"]
            # the status says what the payload holds -- to the admin only; a save schema only where the payload
            # names one this agent can follow (save_plan)
            for shipped, has in ((full, True), (saveless, False), (None, False)):
                ships(shipped)
                st_all = g["status"]()
                for v_, want in (("1.6", has), ("2.8", False)):
                    e_ = st_all["versions"][v_]
                    assert (e_["hasSave"], e_["hasTxtFixes"], e_["hasEvents"]) == (want, want, want), (v_, e_)
                    assert e_["saveSchema"] is False and e_["migrateFrom"] == [], (v_, e_)
                assert st_all["versions"]["1.6"]["hasPayload"] is (shipped is not None)
                pub = json.dumps(build_public_status(st_all, default_policy()))
                assert not any(k in pub for k in ("hasSave", "hasTxtFixes", "hasEvents", "hasPayload",
                                                  "saveSchema", "migrateFrom")), pub
            real_16 = os.path.join(saved_p["PAYLOAD_DIR"], "1.6")
            real_man = os.path.join(real_16, "manifest.json")
            if os.path.isfile(real_man):
                with open(real_man, "rb") as f:
                    real_block = json.loads(f.read().decode("utf-8")).get("saves")
                if real_block:
                    shutil.copyfile(os.path.join(real_16, real_block["schema"]),
                                    os.path.join(td, "payloads", "1.6", real_block["schema"]))
                    for block_, want in ((real_block, True), (dict(real_block, schema="none.json"), False)):
                        ships(dict(full, saves=block_))
                        st_all = g["status"]()
                        assert st_all["versions"]["1.6"]["saveSchema"] is want, (block_, st_all["versions"]["1.6"])
                        assert st_all["versions"]["1.6"]["migrateFrom"] == (["1.6"] if want else []), block_
                        assert "saveSchema" not in json.dumps(build_public_status(st_all, default_policy()))
                        assert "migrateFrom" not in json.dumps(build_public_status(st_all, default_policy()))
                    os.remove(os.path.join(td, "payloads", "1.6", real_block["schema"]))
            # the txt-fixes job on a version that has none: docker is asked nothing, nothing is recorded, nothing
            # stops -- while a version that has some is stopped, changed and booted, and one without a manifest
            # is treated as it always is
            ships(saveless)
            asked = []
            g["running_projects"] = lambda: asked.append("ls") or ([VERSIONS["1.6"]["project"]], None)
            g["_compose_stream"] = lambda _d, _j, *a, **k: asked.append(a) or 0
            state_before = _box_state_bytes(sp)
            for action, word in (("apply", "install"), ("revert", "restore")):
                j = _Job()
                assert do_txt_fixes("1.6", j, action=action) == {"files": 0, "action": action}
                assert j.lines == ["Version 1.6 ships no txt fixes -- nothing to %s; the server was not stopped." % word], \
                    j.lines
            assert asked == [] and _box_state_bytes(sp) == state_before, asked
            for shipped in (man, None):
                ships(shipped)
                del asked[:]
                version_state_set("1.6", txtFixes="pending")
                do_txt_fixes("1.6", _Job())
                assert asked == ["ls", ("down",), ("up", "-d", "mysql", "redis"), ("up", "-d")] \
                    and version_state("1.6")["txtFixes"] == "applied", (shipped is None, asked)
            g.update({"running_projects": lambda: ([], None), "_compose_stream": lambda *a, **k: 0})

            # (N) The manifest stage `bootstrap`: a file the server package is published with, replaced right
            # before the vendor bootstrap -- only while it is byte for byte a content the entry names.
            pay16 = os.path.join(td, "payloads", "1.6")
            published, ours = b"the copy the package is published with\n", b"the payload's copy\n"

            def put_file(path, data):
                os.makedirs(os.path.dirname(path), exist_ok=True)
                with open(path, "wb") as f:
                    f.write(data)

            def get_file(path):
                with open(path, "rb") as f:
                    return f.read()

            put_file(os.path.join(pay16, "sdk", "Dockerfile"), ours)
            put_file(os.path.join(pay16, "txt", "QuestData.txt"), b"id\tname\n1\ta\n")
            docker_file = os.path.join(stack, "sdk", "Dockerfile")
            boot = {"src": "sdk/Dockerfile", "dst": "sdk/Dockerfile", "stage": "bootstrap",
                    "overMd5": ["0" * 32, hashlib.md5(published).hexdigest().upper()]}
            ships(dict(saveless, files=saveless["files"] + [boot]))
            assert effective_stage(boot) == "bootstrap" == BOOTSTRAP_STAGE and bootstrap_entry_problem(boot) is None
            # the four destinations: missing (nothing is created), the payload's bytes already, a named content,
            # anything else -- only the third is touched, with ONE line, no .orig and no temp file left
            j = _Job()
            assert install_bootstrap_files("1.6", j) == 0 and j.lines == [] and not os.path.exists(os.path.dirname(docker_file))
            for held in (ours, b"the admin's own Dockerfile\n", b""):
                put_file(docker_file, held)
                assert install_bootstrap_files("1.6", j) == 0 and j.lines == [] and get_file(docker_file) == held, held
            put_file(docker_file, published)
            if os.name == "posix":
                os.chmod(docker_file, 0o640)
            assert install_bootstrap_files("1.6", j) == 1 and get_file(docker_file) == ours
            assert j.lines == ["Before the bootstrap: sdk/Dockerfile was the copy this server package is published "
                               "with -- replaced with the payload's."], j.lines
            assert os.listdir(os.path.dirname(docker_file)) == ["Dockerfile"], "no .orig copy, no temp file"
            if os.name == "posix":
                assert _stat.S_IMODE(os.stat(docker_file).st_mode) == 0o640, "the replaced file's mode is kept"
            assert install_bootstrap_files("1.6", j) == 0 and len(j.lines) == 1, "a second run finds the payload's bytes"
            # a read-only file (Windows refuses a rename over one, and the removal of one) is replaced like any
            # other and stays read-only; and a rename that fails -- on every system -- is ONE WARNING that
            # leaves no temp file beside the file and the file as it was, so the next run is not locked out
            read_only = os.name == "nt"

            def published_again():
                if os.path.exists(docker_file):
                    os.chmod(docker_file, 0o600)
                put_file(docker_file, published)
                if read_only:
                    os.chmod(docker_file, 0o400)

            def as_it_was_kept(what):
                assert os.listdir(os.path.dirname(docker_file)) == ["Dockerfile"], what
                assert not read_only or not os.stat(docker_file).st_mode & 0o200, what + ": still read-only"

            published_again()
            j = _Job()
            assert install_bootstrap_files("1.6", j) == 1 and get_file(docker_file) == ours and len(j.lines) == 1, j.lines
            as_it_was_kept("replaced")
            published_again()
            saved_replace = g["replace_file"]
            g["replace_file"] = lambda *_a, **_k: (_ for _ in ()).throw(PermissionError(13, "held by another program"))
            try:
                for run_n in (1, 2):  # (never `_run`: a local of that name would hide the runner from every block)
                    j = _Job()
                    assert install_bootstrap_files("1.6", j) == 0 and get_file(docker_file) == published
                    assert len(j.lines) == 1 and j.lines[0].startswith(
                        "WARNING: sdk/Dockerfile could not be replaced with the payload's copy before the bootstrap "
                        "([Errno 13] held by another program) -- left as it is."), j.lines
                    as_it_was_kept("a rename that failed, run %d" % run_n)
            finally:
                g["replace_file"] = saved_replace
            assert install_bootstrap_files("1.6", _Job()) == 1 and get_file(docker_file) == ours, \
                "nothing of the failed runs stands in the way of the next one"
            os.chmod(docker_file, 0o600)
            # an entry the manifest wrote wrongly: ONE WARNING, the file left as it is, never a failed job
            put_file(docker_file, published)
            for broken, why in (({"overMd5": None}, "overMd5"), ({"overMd5": []}, "overMd5"), ({"overMd5": "0" * 32}, "overMd5"),
                                ({"overMd5": ["zz"]}, "overMd5"), ({"overMd5": [3]}, "overMd5"),
                                ({"overMd5": ["0" * 32, "1" * 31]}, "overMd5"), ({"tsv": True}, "tsv"), ({"dst": ""}, "dst"),
                                ({"dst": "../%s/sdk/Dockerfile" % os.path.basename(stack)}, "below the stack folder"),
                                ({"dst": "sdk/../sdk/Dockerfile"}, "below the stack folder"),
                                ({"dst": "sdk\\Dockerfile"}, "below the stack folder"),
                                ({"dst": docker_file.replace(os.sep, "/")}, "below the stack folder")):
                bad = dict(boot, **broken)
                assert why in bootstrap_entry_problem(bad), (broken, bootstrap_entry_problem(bad))
                ships({"files": [bad]})
                j = _Job()
                assert install_bootstrap_files("1.6", j) == 0 and get_file(docker_file) == published, broken
                assert len(j.lines) == 1 and j.lines[0].startswith("WARNING: the payload manifest's bootstrap entry for ") \
                    and j.lines[0].endswith(" -- skipped."), j.lines
            # (the rule those four dst broke, and the stages there are: an entry of another one is installed by nothing)
            for dst_ in ("sdk/Dockerfile", "a", ".env", "server/data/txt/x.txt", "a/..b/c..", "a/.../b"):
                assert manifest_dst_problem(dst_) is None, dst_
            for dst_ in (None, "", 3, ["a"], "/abs", "..", "../x", "a/../b", "a/..", "a\\b", "C:/x", "c:x", "\\\\host\\x"):
                assert manifest_dst_problem(dst_), dst_
            assert MANIFEST_STAGES == ("save", "config", "txt_fix", "bootstrap") and effective_stage({}) == "save" \
                and all(effective_stage({"stage": stage_}) == stage_ for stage_ in MANIFEST_STAGES) \
                and effective_stage({"stage": "Bootstrap"}) not in MANIFEST_STAGES
            # only the payload itself fails the job: a source that is missing, or is not the bytes its md5 pins
            for bad, text in ((dict(boot, src="sdk/Missing"), "Payload file missing: "),
                              (dict(boot, md5="f" * 32), "Payload file sdk/Dockerfile does not match its manifest "
                                                         "(damaged in transit) -- install the agent again.")):
                ships({"files": [bad]})
                try:
                    install_bootstrap_files("1.6", _Job())
                    raise AssertionError("a broken payload must fail the stage: %r" % (bad,))
                except AgentError as e:
                    assert e.status == 500 and e.message.startswith(text), e.message
                assert get_file(docker_file) == published
            ships({"files": [dict(boot, md5=hashlib.md5(ours).hexdigest())]})
            assert install_bootstrap_files("1.6", _Job()) == 1 and get_file(docker_file) == ours
            # install_files and revert_files pass a bootstrap entry over, whatever stages they are handed
            g["install_files"] = saved_p["install_files"]
            ships(dict(saveless, files=saveless["files"] + [boot]))
            put_file(docker_file, published)
            put_file(docker_file + ".orig", b"an .orig somebody left\n")
            every = {"save", "config", "txt_fix", "bootstrap"}
            quest = os.path.join(stack, "server", "data", "txt", "QuestData.txt")
            put_file(quest, b"the stack's own table\n")
            assert install_files("1.6", _Job(), every) == 1 and get_file(quest) == b"id\tname\n1\ta\n" \
                and get_file(quest + ".orig") == b"the stack's own table\n", "the config table alone went in"
            assert get_file(docker_file) == published
            assert revert_files("1.6", _Job(), {"txt_fix", "bootstrap"}) == 0 and revert_files("1.6", _Job(), every) == 1, \
                "the table's .orig is all a revert of every stage puts back"
            assert get_file(docker_file) == published and get_file(docker_file + ".orig") == b"an .orig somebody left\n" \
                and get_file(quest) == b"the stack's own table\n"
            os.remove(docker_file + ".orig")
            # files[].md5 in every stage: a source that is not the bytes its entry pins is refused before the
            # .orig copy exists and before a byte of the stack changes; the right bytes go in
            put_file(quest, b"the stack's own table\n")
            os.remove(quest + ".orig")
            pinned = dict(saveless["files"][0], md5="0" * 32)
            ships({"files": [pinned]})
            try:
                install_files("1.6", _Job(), {"config"})
                raise AssertionError("a payload file that is not the bytes its md5 pins must be refused")
            except AgentError as e:
                assert e.status == 500 and e.message == ("Payload file txt/QuestData.txt does not match its manifest "
                                                         "(damaged in transit) -- install the agent again."), e.message
            assert get_file(quest) == b"the stack's own table\n" and not os.path.exists(quest + ".orig")
            ships({"files": [dict(pinned, md5=hashlib.md5(b"id\tname\n1\ta\n").hexdigest().upper())]})
            assert install_files("1.6", _Job(), {"config"}) == 1 and get_file(quest) == b"id\tname\n1\ta\n" \
                and get_file(quest + ".orig") == b"the stack's own table\n"
            # ...and a JOB proves the payload files it is about to install BEFORE it stops a server, forgets a
            # record or writes a file for them -- a provision its stages, the txt-fixes job its fixes, a fresh
            # bootstrap its bootstrap entries: with one of them missing or not the bytes its entry pins, docker is
            # asked nothing, nothing is recorded and no file of the stack changes (not the one listed before it either)
            good = dict(pinned, md5=hashlib.md5(b"id\tname\n1\ta\n").hexdigest())
            second = {"src": "txt/Second.txt", "dst": "server/data/txt/Second.txt", "stage": "config", "tsv": True,
                      "md5": "0" * 32}
            put_file(os.path.join(pay16, "txt", "Second.txt"), b"id\tname\n2\tb\n")
            DAMAGED = "Payload file %s does not match its manifest (damaged in transit) -- install the agent again."
            put_file(quest, b"the stack's own table\n")
            os.remove(quest + ".orig")
            open(os.path.join(stack, "bootstrap.sh"), "w").close()
            put(b"{}")
            version_state_set("1.6", provisionedAt="2026-08-01 10:00:00", progress="keep", defaultAccount=False,
                              runningOk=True)
            write_provisioned_marker("1.6", "2026-08-01 10:00:00", "keep", False)
            touched = []
            g.update({"do_bootstrap": saved_p["do_bootstrap"], "down_all": lambda *a, **k: touched.append("down"),
                      "_compose_stream": lambda _d, _j, *a, **k: touched.append(a) or 0,
                      "running_projects": lambda: touched.append("ls") or ([VERSIONS["1.6"]["project"]], None)})

            def stack_files():
                return {os.path.relpath(os.path.join(cur, name), stack): get_file(os.path.join(cur, name))
                        for cur, _dirs, names in os.walk(stack) for name in names}

            state_before, files_before = _box_state_bytes(sp), stack_files()
            fixes = [dict(good, stage="txt_fix"), dict(second, stage="txt_fix")]
            for shipped, text, fn, kw in (
                    ({"files": [good, second]}, DAMAGED % "txt/Second.txt", do_provision, {"progress": "keep"}),
                    ({"files": [good, dict(second, src="txt/Missing.txt")]}, "Payload file missing: ", do_provision,
                     {"progress": "fixes"}),
                    ({"files": fixes}, DAMAGED % "txt/Second.txt", do_txt_fixes, {}),
                    ({"files": [good, dict(boot, md5="f" * 32)]}, DAMAGED % "sdk/Dockerfile", do_setup,
                     {"progress": "keep", "force": True}),
                    ({"files": [good, dict(boot, src="sdk/Missing")]}, "Payload file missing: ", do_bootstrap,
                     {"force": True})):
                ships(shipped)
                try:
                    fn("1.6", _Job(), **kw)
                    raise AssertionError("a payload file that cannot be installed must fail the job first: " + text)
                except AgentError as e:
                    assert e.status == 500 and e.message.startswith(text), (text, e.message)
                assert touched == [] and _box_state_bytes(sp) == state_before and stack_files() == files_before, \
                    (text, touched)
            # (only the stages a job installs are proven; a bootstrap entry the manifest wrote wrongly is passed
            # over, as its stage passes it over; without a manifest there is nothing to prove)
            ships({"files": [good, dict(second, stage="txt_fix"), dict(boot, src="sdk/Missing", overMd5=[])]})
            assert prove_payload_files("1.6", {"save", "config", "bootstrap"}) is None
            try:
                prove_payload_files("1.6", {"txt_fix"})
                raise AssertionError("a stage that is asked for is proven")
            except AgentError as e:
                assert e.status == 500 and e.message == DAMAGED % "txt/Second.txt", e.message
            g["read_manifest"] = lambda _v: None
            assert prove_payload_files("1.6", set(MANIFEST_STAGES)) is None
            # (...and a revert reads no payload file: the same damaged fix does not hold it back)
            ships({"files": fixes})
            assert do_txt_fixes("1.6", _Job(), action="revert") == {"files": 0, "action": "revert"} \
                and touched == ["ls", ("down",), ("up", "-d", "mysql", "redis"), ("up", "-d")], touched
            os.remove(provisioned_marker_path("1.6"))
            g.update({"do_bootstrap": lambda _v, _j, force=False: None, "down_all": lambda *a, **k: None,
                      "_compose_stream": lambda *a, **k: 0, "running_projects": lambda: ([], None)})
            g["install_files"] = lambda _v, _j, stages: calls["stages"].append(set(stages)) or len(stages)
            # WHERE it runs, first: on do_bootstrap's fresh path, after the other stacks are down and before the
            # vendor's step -- in every progress mode, and with "Keep .env settings" on (it is payload, no .env
            # setting). The vendor's step is a stand-in that notes what it finds.
            boot_src = agent_src[agent_src.index("\ndef do_bootstrap("):agent_src.index("\nPROGRESS_LOG = {")]
            assert boot_src.count("install_bootstrap_files(version, job)") == 1 and boot_src.index('return "healed"') \
                < boot_src.index("down_all(job, keep=None)") < boot_src.index("install_bootstrap_files(version, job)") \
                < min(boot_src.index("_bootstrap_windows(version, job)"), boot_src.index('["bash", "bootstrap.sh"]')), \
                "do_bootstrap installs the bootstrap files on its fresh path, after the down and before the vendor bootstrap"
            order = []

            def vendor_step(*_a, **_k):
                order.append(("vendor", get_file(docker_file)))
                open(os.path.join(stack, ".bootstrap.lock"), "w").close()
                return 0

            open(os.path.join(stack, "bootstrap.sh"), "w").close()
            g.update({"do_bootstrap": saved_p["do_bootstrap"], "_stream": vendor_step, "_bootstrap_windows": vendor_step,
                      "down_all": lambda *a, **k: order.append(("down", get_file(docker_file))),
                      "ensure_bind_ip": lambda *a, **k: None, "ensure_env_secrets": lambda *a, **k: None,
                      "ensure_internal_sources": lambda *a, **k: None,
                      "do_provision": lambda _v, _j, **kw: prov_calls.append(kw) or dict(kw, provisioned=True)})
            ships(dict(man, files=man["files"] + [boot]))
            for mode, keep_env in (("default", False), ("keep", False), ("fixes", False), ("keep", True)):
                put_file(docker_file, published)
                put(b"{}")
                del order[:]
                g["KEEP_ENV"] = keep_env
                j = _Job()
                do_setup("1.6", j, progress=mode, force=True)
                assert order == [("down", published), ("vendor", ours)], (mode, order)
                assert len([l for l in j.lines if l.startswith("Before the bootstrap: sdk/Dockerfile ")]) == 1, j.lines
                assert prov_calls[-1] == {"txt_fixes": None, "fresh": True, "progress": mode}, (mode, prov_calls[-1])
            g["KEEP_ENV"] = False
            # ...while do_bootstrap leaves a stack that is installed already as it is -- nothing is bootstrapped
            # there: the provision is what follows a Prepare without a reinstall (a stand-in here, so the file
            # is still the published one after it)
            put_file(docker_file, published)
            del order[:]
            do_setup("1.6", _Job(), progress="keep")
            assert order == [] and get_file(docker_file) == published, "an installed stack is not a fresh bootstrap"
            # ...and a Prepare that redoes NOTHING -- the default choice on a stack that is installed and has its
            # record -- replaces nothing either: it names what is still the published copy, with the way to have
            # it replaced, in ONE WARNING before its answer. Nothing published, no line.
            STILL = ("WARNING: %s still the cop%s this server package is published with, and nothing is redone here "
                     "to replace %s. Applying a progress choice does: Re-apply the progress -- \"keep\" and \"fixes\" "
                     "touch nobody's progress.%s")
            REAPPLY = READY_LINE + " To deliberately re-import the save use Re-apply the progress."
            version_state_set("1.6", provisionedAt="2026-08-01 10:00:00", progress="default", defaultAccount=True)
            assert published_bootstrap_files("1.6") == ["sdk/Dockerfile"] and published_bootstrap_files("2.8") == []
            n_prov = len(prov_calls)
            j = _Job()
            assert do_setup("1.6", j) == {"provisioned": False, "alreadyReady": True} and len(prov_calls) == n_prov
            assert j.lines[-2:] == [STILL % ("sdk/Dockerfile is", "y", "it", ""), REAPPLY] \
                and sum("published with" in l for l in j.lines) == 1, j.lines
            assert order == [] and get_file(docker_file) == published, "named, not replaced: the server is not stopped here"
            for held in (ours, b"the admin's own Dockerfile\n"):
                put_file(docker_file, held)
                j = _Job()
                assert do_setup("1.6", j) == {"provisioned": False, "alreadyReady": True} and j.lines[-1] == REAPPLY \
                    and not any("published with" in l for l in j.lines) and published_bootstrap_files("1.6") == [], j.lines
            put(b"{}")
            g.update({"do_provision": saved_p["do_provision"], "down_all": lambda *a, **k: None})
            # ...and the PROVISION's file stage runs the same entries, by the same rule, in every progress mode
            # and with "Keep .env settings" on: once the stack is down, before the other payload files -- a stack
            # bootstrapped by hand, or one whose package was extracted over it again, loses the published copy
            # at its next Prepare, with ONE line; the payload's bytes and the admin's own file are left, silently
            prov_src = agent_src[agent_src.index("\ndef do_provision("):agent_src.index("\ndef needs_provision(")]
            in_prov = "install_bootstrap_files(version, job, before_bootstrap=False)"
            assert prov_src.count("install_bootstrap_files(") == 1 and prov_src.index("down_all(job, grace=") \
                < prov_src.index(in_prov) < prov_src.index("n = install_files(version, job, stages)") \
                < prov_src.index('"up", "-d", "mysql", "redis"'), \
                "do_provision installs the bootstrap files while the stack is down, before the other payload files"
            assert "prove_payload_files(version, stages | {BOOTSTRAP_STAGE})" in prov_src, \
                "a provision proves the bootstrap sources too before it stops anything"
            REPLACED = "  sdk/Dockerfile was the copy this server package is published with -- replaced with the payload's."
            for mode, keep_env in (("default", False), ("keep", False), ("fixes", False), ("keep", True)):
                put_file(docker_file, published)
                g["KEEP_ENV"] = keep_env
                j = _Job()
                assert do_provision("1.6", j, progress=mode)["provisioned"] and get_file(docker_file) == ours, mode
                assert [l for l in j.lines if "sdk/Dockerfile" in l] == [REPLACED], (mode, j.lines)
                assert j.lines.index("Copying the payload files into the stack...") < j.lines.index(REPLACED) \
                    < next(i for i, l in enumerate(j.lines) if l.endswith(" files installed.")), (mode, j.lines)
                assert os.listdir(os.path.dirname(docker_file)) == ["Dockerfile"], "no .orig copy, no temp file"
                j = _Job()
                assert do_provision("1.6", j, progress=mode)["provisioned"] \
                    and not [l for l in j.lines if "sdk/Dockerfile" in l], "a second Prepare finds the payload's bytes"
            g["KEEP_ENV"] = False
            put_file(docker_file, b"the admin's own Dockerfile\n")
            j = _Job()
            assert do_provision("1.6", j, progress="keep")["provisioned"] and not [l for l in j.lines if "sdk/Dockerfile" in l] \
                and get_file(docker_file) == b"the admin's own Dockerfile\n", "anything else is the admin's: left, silently"
            # ...which is how the accounts a package came with go: its sdk.db is replaced with an empty account
            # database before the bootstrap, so the provision that follows counts none and says nothing -- while
            # a file the stage left alone (other accounts in it: somebody's own) is still named
            os.makedirs(os.path.dirname(sdk_db))
            sdk_accounts()
            put_file(os.path.join(pay16, "sdk", "data", "sdk.db"), get_file(sdk_db))
            sdk_accounts("packager", "guest")
            package_db = get_file(sdk_db)
            with_package_db = dict(saveless, files=saveless["files"] + [
                {"src": "sdk/data/sdk.db", "dst": "sdk/data/sdk.db", "stage": "bootstrap", "overMd5": [_file_md5(sdk_db)]}])
            ships(with_package_db)
            assert sdk_account_count("1.6") == 2 and sdk_db_published("1.6") is True \
                and install_bootstrap_files("1.6", _Job()) == 1 and sdk_account_count("1.6") == 0 \
                and sdk_db_published("1.6") is False
            assert came_with(progress="default", fresh=True) == [], "the package's accounts went with its file"
            sdk_accounts("packager", "guest", "somebody")
            assert install_bootstrap_files("1.6", _Job()) == 0 and sdk_account_count("1.6") == 3
            said = came_with(progress="default", fresh=True)
            assert len(said) == 1 and "already holds 3 account(s)" in said[0], said
            # ...and on a stack this run did not bootstrap -- the package extracted again over an installed
            # stack, a stack bootstrapped by hand -- the provision's own file stage replaces the account file the
            # package is published with, in every mode, and nothing is left to warn about. Only a file that
            # could NOT be replaced is still named, after the line that says why. Somebody's own accounts and a
            # manifest that names no such file are left as they are.
            assert sdk_db_published("1.6") is False and came_with(progress="keep") == [], "other accounts: somebody's own"
            for mode in ("default", "keep", "fixes"):
                put_file(sdk_db, package_db)
                assert sdk_db_published("1.6") is True and came_with(progress=mode) == [], mode
                assert sdk_account_count("1.6") == 0 and sdk_db_published("1.6") is False, \
                    "%s: the published account file went at the Prepare" % mode
            put_file(sdk_db, package_db)
            saved_replace = g["replace_file"]

            def held_sdk_db(src_, dst_, *a, **k):
                # (the state file is replaced through the same function: only the account file is held)
                if os.path.normpath(dst_) == os.path.normpath(sdk_db):
                    raise PermissionError(13, "held by another program")
                return saved_replace(src_, dst_, *a, **k)

            g["replace_file"] = held_sdk_db
            try:
                for mode in ("default", "keep", "fixes"):
                    said = came_with(progress=mode)
                    assert len(said) == 2 and said[0].startswith(
                        "WARNING: sdk/data/sdk.db could not be replaced with the payload's copy ([Errno 13] held by "
                        "another program) -- left as it is.") and said[1] == (
                        "WARNING: sdk/data/sdk.db is still the account file this server package is published with -- "
                        "its 2 account(s) were created by nobody on this server, and their names log in here. "
                        "Re-apply the progress tries again to replace that file with the payload's."), (mode, said)
            finally:
                g["replace_file"] = saved_replace
            assert get_file(sdk_db) == package_db, "a file that could not be replaced is named and left as it was"
            # ...and the Prepare that redoes nothing on this stack -- installed, with its record -- names that
            # account file with the accounts in it, and two such files in one line; the file stays as it was
            j = _Job()
            assert do_setup("1.6", j) == {"provisioned": False, "alreadyReady": True} and get_file(sdk_db) == package_db
            assert j.lines[-2:] == [STILL % ("sdk/data/sdk.db is", "y", "it", " Until then the 2 account(s) in "
                                             "sdk/data/sdk.db, created by nobody on this server, log in here."),
                                    READY_LINE], j.lines
            put_file(docker_file, published)
            ships(dict(with_package_db, files=with_package_db["files"] + [boot]))
            j = _Job()
            assert do_setup("1.6", j) == {"provisioned": False, "alreadyReady": True}
            assert j.lines[-2].startswith("WARNING: sdk/data/sdk.db, sdk/Dockerfile are still the copies this server "
                                          "package is published with, and nothing is redone here to replace them. "), j.lines
            put_file(docker_file, b"the admin's own Dockerfile\n")
            ships(with_package_db)
            ships(saveless)
            assert sdk_db_published("1.6") is False and came_with(progress="keep") == [] \
                and get_file(sdk_db) == package_db, "no entry names the file"
            ships(dict(man, files=man["files"] + with_package_db["files"][1:]))
            assert sdk_db_published("1.6") is True and came_with(progress="default") == [] \
                and sdk_account_count("1.6") == 0, "with a save as well: replaced before the save's files go in"
            g["read_manifest"] = lambda _v: None
            assert sdk_db_published("1.6") is False and sdk_db_published("2.8") is False, "no manifest, no stack: no"
        finally:
            g.update(saved_p)
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_
    ok("provisioning progress OK (default/keep/fixes stages + record, marker v2 re-seed/migration/forget, "
       "never auto-imported, setup decisions incl. the marker-merged heal, pending-password gate, "
       "route 400s, account hidden without the save)")
    ok("a version whose payload ships no save OK (default runs and is recorded as keep with ONE job line, keep and "
       "fixes as asked, a version without a manifest untouched; no default account whatever an earlier record said, "
       "txtFixes none and no hint, the generation set once; never provisioned on its own, not by once nor switch, "
       "and the recovery guard does not wait for it -- it does wait for a version whose manifest is missing, so a "
       "save that comes back with the payload is not imported; a lost record re-seeded from the marker; Prepare on "
       "a ready stack: nothing redone with a record, the non-destructive run without one; hasSave / hasTxtFixes / "
       "hasEvents in the status, never public; the txt-fixes job asks docker nothing and records nothing)")
    ok("payload bootstrap stage + md5 pin OK (a file replaced only while it is a content its entry names: missing, "
       "the payload's own or anything else left alone silently; ONE line, no .orig, mode kept, a read-only file "
       "replaced and still read-only; a rename that fails leaves no temp file and the file as it was; a wrongly "
       "written entry -- a dst outside the stack among them -- = ONE WARNING; only a missing source or one that is "
       "not its pinned bytes fails; never touched by install_files / revert_files; on the fresh bootstrap, after "
       "the down and before the vendor's step, and in the file stage of every provision, once the stack is down "
       "and before the other payload files -- each in every progress mode and with Keep .env settings on; a Prepare "
       "that redoes nothing replaces none and names each in ONE WARNING, with its accounts for the account file; the "
       "package's accounts gone with its sdk.db; a pinned source that differs is refused before the .orig copy, and "
       "by a provision, the txt-fixes job and a fresh bootstrap before anything is stopped, recorded or written)")
    ok("accounts a stack came with OK (sdk.db counted from a copy; ONE WARNING after a keep / fixes run over a "
       "database the bootstrap just created; the account file a package is published with replaced by the Prepare "
       "of a stack the run did not bootstrap, and named only where it could not be; none for an empty file, a "
       "missing one, a file that is no account database, a database that was already there, the default save; "
       "never a failed job)")

    # Pathfinding server on/off: the profile edit in the vendor's syntax (CRLF and LF,
    # idempotent, round-trip byte-exact, oaserver untouched, the inline form read), then the job on
    # fakes: both files + state, the compose argv on a running stack, a failing compose, the
    # dead_services filter and the Prepare-time decision applied before the bootstrap renders.
    tmpl_crlf = ("version: '3'\r\nservices:\r\n  mysql:\r\n    image: mariadb\r\n    ports:\r\n"
                 "      - \"%OUTER_IP%:3306:3306\"\r\n"
                 "  oaserver:\r\n    profiles:\r\n      - donotstart\r\n    image: debian:11\r\n"
                 "  pathfindingserver:\r\n    image: debian:11\r\n    restart: on-failure\r\n    expose:\r\n"
                 "      - \"21101/udp\"\r\n    networks:\r\n      default:\r\n        ipv4_address: 172.10.3.8\r\n"
                 "    command: ./pathfindingserver\r\n"
                 "  sdk:\r\n    image: sdk\r\nnetworks:\r\n  default:\r\n    driver: bridge\r\n")
    off, n = set_pathfinding_text(tmpl_crlf, False)
    assert n == 1 and "  pathfindingserver:\r\n    profiles:\r\n      - donotstart\r\n    image: debian:11\r\n" in off, off
    assert off.count("\r\n") == tmpl_crlf.count("\r\n") + 2 and "\n" not in off.replace("\r\n", ""), "CRLF kept"
    assert off.count("- donotstart") == 2 and off.replace("  pathfindingserver:\r\n    profiles:\r\n      - donotstart\r\n",
                                                          "  pathfindingserver:\r\n") == tmpl_crlf, "only that block changed"
    assert set_pathfinding_text(off, False) == (off, 0), "idempotent"
    on, n = set_pathfinding_text(off, True)
    assert n == 1 and on == tmpl_crlf, "disable -> enable round-trips byte-exact"
    assert set_pathfinding_text(tmpl_crlf, True) == (tmpl_crlf, 0)
    assert compose_service_profiled(tmpl_crlf, "pathfindingserver") is False and compose_service_profiled(off, "pathfindingserver") is True
    assert compose_service_profiled(tmpl_crlf, "oaserver") is True and compose_service_profiled(tmpl_crlf, "mysql") is False
    assert compose_service_profiled(tmpl_crlf, "gameserver") is None
    assert compose_disabled_services(tmpl_crlf) == {"oaserver"} and compose_disabled_services(off) == {"oaserver", "pathfindingserver"}
    tmpl_lf = tmpl_crlf.replace("\r\n", "\n")
    off_lf, n = set_pathfinding_text(tmpl_lf, False)
    assert n == 1 and "\r" not in off_lf and "    profiles:\n      - donotstart\n" in off_lf
    assert set_pathfinding_text(off_lf, True) == (tmpl_lf, 1)
    assert set_pathfinding_text("services:\n  mysql:\n    image: x\n", False) == ("services:\n  mysql:\n    image: x\n", 0)
    assert compose_service_profiled("services:\n  mysql:\n    image: x\n", "pathfindingserver") is None
    inline = "services:\n  pathfindingserver:\n    profiles: [donotstart]\n    image: x\n"
    assert compose_service_profiled(inline, "pathfindingserver") is True and compose_disabled_services(inline) == {"pathfindingserver"}
    assert set_pathfinding_text(inline, True) == ("services:\n  pathfindingserver:\n    image: x\n", 1)
    assert set_pathfinding_text("services:\n  pathfindingserver:\n    profiles: [debug]\n", False)[0] == \
        "services:\n  pathfindingserver:\n    profiles: [debug, donotstart]\n"
    # a same-named key nested in another service (depends_on long form) never passes for the service
    nested = ("services:\n  gameserver:\n    depends_on:\n      pathfindingserver:\n        condition: service_started\n"
              "  pathfindingserver:\n    image: x\n")
    off_n, n = set_pathfinding_text(nested, False)
    assert n == 1 and off_n == nested.replace("  pathfindingserver:\n    image: x\n",
                                              "  pathfindingserver:\n    profiles:\n      - donotstart\n    image: x\n"), off_n
    faked_pf = ("STATE_PATH", "PAYLOAD_DIR", "running_projects", "_compose_stream", "_compose", "verify_stack", "log_line",
                "current_job", "PATHFINDING_DEFAULT", "do_bootstrap", "do_provision", "ensure_data_layout",
                "stack_has_navmesh")
    saved_pf = {k: g[k] for k in faked_pf}
    saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
    with tempfile.TemporaryDirectory() as td:
        try:
            stack = os.path.join(td, "1.6_live")
            os.makedirs(stack)
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = stack, _project_name(stack)
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = "", ""
            tmpl_path, rendered = _compose_paths("1.6")
            write_text(os.path.join(stack, ".env"), "OUTER_IP=192.0.2.10\n")
            write_text(tmpl_path, tmpl_crlf)
            argv = []
            # The payload folder is a temp one from the first line on: the folder this run was handed may
            # ship a manifest or a navmesh bundle for 1.6, and neither may decide anything here -- not what
            # Prepare does with the progress, not what the pathfinding enable installs, not the default below.
            pf_payloads = os.path.join(td, "payloads")
            os.makedirs(pf_payloads)
            # the quiet runner (_compose) answers only drop_pathfinding_leftover's call here: `rm -f` of the service
            # through the profile; what it said comes from `answers` (none queued = there was no such container)
            pf_rm = ("--profile", "donotstart", "rm", "-f", "pathfindingserver")
            quiet, answers = [], []

            def quiet_compose(_d, *a, **k):
                assert a == pf_rm, a
                quiet.append(a)
                return answers.pop(0) if answers else \
                    subprocess.CompletedProcess([], 0, stdout="", stderr="No stopped containers\n")

            g.update({"STATE_PATH": os.path.join(td, "state.json"), "PAYLOAD_DIR": pf_payloads,
                      "running_projects": lambda: ([], None),
                      "_compose_stream": lambda _d, _j, *a, **k: argv.append(a) or 0, "_compose": quiet_compose,
                      "verify_stack": lambda *a, **k: argv.append(("verify",)),
                      "log_line": lambda *_a: None, "current_job": lambda **_k: None})
            assert pathfinding_enabled("1.6") is True, "the template alone, before the bootstrap"
            render_stack_configs("1.6", _Job())
            rendered_vendor = tmpl_crlf.replace("%OUTER_IP%", "192.0.2.10")
            assert read_text(rendered) == rendered_vendor and pathfinding_enabled("1.6") is True
            # (a) stack not running: both files edited, state persisted, no compose call
            res = do_pathfinding("1.6", _Job(), False)
            assert res == {"enabled": False, "changed": True, "applied": False} and argv == [] and quiet == [], \
                (res, argv, quiet)
            assert pathfinding_enabled("1.6") is False and version_state("1.6")["pathfinding"] is False
            assert compose_service_profiled(read_text(tmpl_path), "pathfindingserver") is True
            assert read_text(rendered) == set_pathfinding_text(rendered_vendor, False)[0], "rendered: same edit, CRLF kept"
            # the rendered file is the truth for status when the two disagree (a hand edit on the box)
            write_text(tmpl_path, tmpl_crlf)
            assert pathfinding_enabled("1.6") is False
            assert do_pathfinding("1.6", _Job(), False)["changed"] is True, "the template is brought back in line"
            assert do_pathfinding("1.6", _Job(), False)["changed"] is False
            # (b) running + bootstrapped: enable = up --no-deps + the stability check; disable = rm through the profile
            open(os.path.join(stack, ".bootstrap.lock"), "w").close()
            g["running_projects"] = lambda: ([VERSIONS["1.6"]["project"]], None)
            seen = []
            g["_compose_stream"] = lambda _d, _j, *a, **k: argv.append(a) or seen.append(("stream", a)) or 0
            g["_compose"] = lambda _d, *a, **k: seen.append(("quiet", a)) or quiet_compose(_d, *a, **k)
            res = do_pathfinding("1.6", _Job(), True)
            assert res == {"enabled": True, "changed": True, "applied": True}, res
            assert argv == [("up", "-d", "--no-deps", "pathfindingserver"), ("verify",)], argv
            assert seen == [("quiet", pf_rm), ("stream", ("up", "-d", "--no-deps", "pathfindingserver"))], \
                "a stopped container of the service a stop left behind goes before the `up` that starts it: %r" % seen
            assert read_text(rendered) == rendered_vendor and read_text(tmpl_path) == tmpl_crlf, "round-trip on disk"
            g["_compose_stream"] = lambda _d, _j, *a, **k: argv.append(a) or 0
            g["_compose"] = quiet_compose
            del argv[:], quiet[:]
            res = do_pathfinding("1.6", _Job(), False)
            assert res["applied"] is True and argv == [("--profile", "donotstart", "rm", "-s", "-f", "pathfindingserver")], argv
            assert quiet == [], "switched off on a running stack: the profile's own rm -s takes the container"
            # (b2) bootstrapped but not up: a stopped container of the service that no stop removed (`down` passes over
            #      a service its profile switches off) goes, through the quiet runner, whichever way the switch goes --
            #      one line when one was removed, one WARNING when that failed or docker could not be asked, silent
            #      when there was none; the docker half of the switch waits for the next start either way
            g["running_projects"] = lambda: ([], None)
            removed_line = ("Removed the container of pathfindingserver that a stop had left behind -- it is created "
                            "afresh with the stack's network.")
            for want_on, answer_, said in (
                    (True, subprocess.CompletedProcess([], 0, stdout="", stderr="No stopped containers\n"), []),
                    (False, subprocess.CompletedProcess(
                        [], 0, stdout="Going to remove 1_6_live-pathfindingserver-1\n",
                        stderr=" Container 1_6_live-pathfindingserver-1  Removing\n"
                               " Container 1_6_live-pathfindingserver-1  Removed\n"), [removed_line]),
                    (True, subprocess.CompletedProcess([], 1, stdout="", stderr="Cannot connect to the Docker daemon\n"),
                     ["WARNING: a container of pathfindingserver that a stop left behind could not be removed (Cannot "
                      "connect to the Docker daemon) -- if the start fails on a network that is not found, remove it "
                      "by hand (docker rm)."])):
                del argv[:], quiet[:]
                answers.append(answer_)
                j = _Job()
                res = do_pathfinding("1.6", j, want_on)
                assert res["applied"] is False and argv == [] and quiet == [pf_rm], (res, argv, quiet)
                assert [l for l in j.lines if "left behind" in l] == said, j.lines
            del quiet[:]
            g["_compose"] = lambda *_a, **_k: (_ for _ in ()).throw(OSError("selftest: docker is gone"))
            j = _Job()
            assert reconcile_pathfinding("1.6", j, True) is False and [l for l in j.lines if "left behind" in l] == [
                "WARNING: could not look for a container of pathfindingserver left behind (selftest: docker is gone)."], \
                j.lines
            g["_compose"] = quiet_compose
            g["running_projects"] = lambda: ([VERSIONS["1.6"]["project"]], None)
            del argv[:], quiet[:]
            # (c) a failing compose: 500, the files stay edited and the decision is on record
            g["_compose_stream"] = lambda *a, **k: 1
            try:
                do_pathfinding("1.6", _Job(), True)
                raise AssertionError("a failed up must be a 500")
            except AgentError as e:
                assert e.status == 500 and "pathfindingserver" in e.message, e.message
            assert pathfinding_enabled("1.6") is True and version_state("1.6")["pathfinding"] is True
            # docker mute: the files change, the docker half waits for the next start
            g["_compose_stream"] = lambda _d, _j, *a, **k: argv.append(a) or 0
            g["running_projects"] = lambda: (None, "docker unavailable (selftest)")
            del argv[:]
            j = _Job()
            assert do_pathfinding("1.6", j, False) == {"enabled": False, "changed": True, "applied": False} and argv == []
            assert any("next start" in l for l in j.lines), j.lines
            g["running_projects"] = lambda: ([VERSIONS["1.6"]["project"]], None)
            # (d) dead_services subtracts the profiled services even when `config --services` lists them,
            # and a stale container of a switched-off service (the ps fallback) is not "dead" either
            ps_json = "\n".join(json.dumps({"Service": s, "State": "running"}) for s in ("mysql", "sdk"))
            g["_compose"] = lambda _d, *a, **k: subprocess.CompletedProcess(
                [], 0, stdout=(ps_json if a[0] == "ps" else "mysql\noaserver\npathfindingserver\nsdk\n"), stderr="")
            dead, states = dead_services("1.6")
            assert dead == [] and states == {"mysql": "running", "sdk": "running"}, (dead, states)
            stale = ps_json + "\n" + json.dumps({"Service": "pathfindingserver", "State": "exited"})
            g["_compose"] = lambda _d, *a, **k: subprocess.CompletedProcess(
                [], 0 if a[0] == "ps" else 1, stdout=(stale if a[0] == "ps" else ""), stderr="")
            assert dead_services("1.6")[0] == [], "a leftover container of a profiled service is never revived"
            # (e) Prepare server: the request's choice, else the stored one, else GIO_PATHFINDING only for a
            # stack never bootstrapped -- applied to the template BEFORE the bootstrap renders it
            g["PATHFINDING_DEFAULT"] = False
            asked_default = []

            def default_is(answer):
                return lambda: asked_default.append(answer) or answer

            assert _pathfinding_decision(None, None, False, default_is(False)) is False \
                and _pathfinding_decision(None, None, False, default_is(True)) is True
            assert asked_default == [False, True], "no choice, none stored, never bootstrapped: the default decides"
            del asked_default[:]
            assert _pathfinding_decision(True, None, False, default_is(False)) is True \
                and _pathfinding_decision(False, None, False, default_is(True)) is False
            assert _pathfinding_decision(None, True, False, default_is(False)) is True \
                and _pathfinding_decision(None, False, False, default_is(True)) is False
            assert _pathfinding_decision(None, None, True, default_is(True)) is None \
                and _pathfinding_decision(False, True, True, default_is(True)) is False
            assert asked_default == [], "a choice, a stored decision or an installed stack decides: the default is not asked"
            seen = {}

            def fake_bootstrap(v, jb, force=False):
                seen["tmpl_profiled"] = compose_service_profiled(read_text(tmpl_path), "pathfindingserver")
                render_stack_configs(v, jb)
                open(os.path.join(stack, ".bootstrap.lock"), "w").close()
                return "fresh"

            def fresh_files():
                for p in (os.path.join(stack, ".bootstrap.lock"), rendered):
                    if os.path.exists(p):
                        os.remove(p)
                write_text(tmpl_path, tmpl_crlf)
                with open(g["STATE_PATH"], "wb") as f:
                    f.write(b"{}")

            g.update({"do_bootstrap": fake_bootstrap, "do_provision": lambda _v, _j, **kw: {"provisioned": True},
                      "ensure_data_layout": lambda *a, **k: 0})
            fresh_files()
            do_setup("1.6", _Job())
            assert seen["tmpl_profiled"] is True and pathfinding_enabled("1.6") is False \
                and version_state("1.6")["pathfinding"] is False, "the default (off) reached the template before the render"
            fresh_files()
            do_setup("1.6", _Job(), pathfinding=True)
            assert seen["tmpl_profiled"] is False and pathfinding_enabled("1.6") is True \
                and version_state("1.6")["pathfinding"] is True, "an explicit true wins over the default"
            os.remove(os.path.join(stack, ".bootstrap.lock"))
            os.remove(rendered)
            write_text(tmpl_path, tmpl_crlf)
            do_setup("1.6", _Job())
            assert seen["tmpl_profiled"] is False and version_state("1.6")["pathfinding"] is True, \
                "no choice: the stored decision, never the default, on a stack that decided before"
            # (f) the default itself: GIO_PATHFINDING on applies only where the pathfinding server would have a
            # navmesh to load -- a file of the stack's own NavMesh folder under a name the server loads, else a
            # bundle in the payload. Each look at the stack is counted: a Prepare takes one only when the default
            # decides (the status takes its own, for the answer it reports).
            g.update({"PATHFINDING_DEFAULT": True, "running_projects": lambda: ([], None)})
            looked = []
            g["stack_has_navmesh"] = lambda v_: looked.append(v_) or saved_pf["stack_has_navmesh"](v_)
            nav_dir = os.path.join(stack, "server", "res", "NavMesh")

            def prepared(**kw):
                fresh_files()
                do_setup("1.6", _Job(), **kw)
                st_ = g["status"]()
                assert st_["pathfindingDefault"] is True and st_["versions"]["2.8"]["pathfindingDefault"] is None \
                    and "navmesh" not in st_["versions"]["2.8"], "GIO_PATHFINDING as configured; no stack: no answer"
                pub_ = json.dumps(build_public_status(st_, default_policy()))
                assert not any(k in pub_ for k in ("pathfindingDefault", "stackFiles", "navmesh")), pub_
                return (not seen["tmpl_profiled"], version_state("1.6")["pathfinding"],
                        st_["versions"]["1.6"]["pathfindingDefault"], st_["versions"]["1.6"]["navmesh"]["stackFiles"])

            assert stack_has_navmesh("1.6") is False and stack_navmesh_files("1.6") == 0, "no NavMesh folder at all"
            del looked[:]
            assert prepared() == (False, False, False, 0) and looked[0] == "1.6", "no navmesh file anywhere: off"
            os.makedirs(nav_dir)
            assert prepared() == (False, False, False, 0), "an empty NavMesh folder: off"
            # names the server would not load, and a folder under a name it would, are no navmesh file
            for name in ("readme.txt", "scene_3.navmesh.orig", NAVMESH_MARKER):
                write_text(os.path.join(nav_dir, name), "x")
            os.makedirs(os.path.join(nav_dir, "scene_4.navmesh"))
            assert prepared() == (False, False, False, 1), "stackFiles counts names in one listing; the default wants a file"
            os.rmdir(os.path.join(nav_dir, "scene_4.navmesh"))
            write_text(os.path.join(nav_dir, "scene_3.navmesh"), "x")
            assert prepared() == (True, True, True, 1), "one navmesh file of the stack's own: on"
            # ...and a choice, a stored decision or an installed stack still decide without a look at the folder
            del looked[:]
            fresh_files()
            do_setup("1.6", _Job(), pathfinding=False)
            assert seen["tmpl_profiled"] is True and version_state("1.6")["pathfinding"] is False, "an explicit false wins"
            os.remove(os.path.join(stack, ".bootstrap.lock"))
            os.remove(rendered)
            write_text(tmpl_path, tmpl_crlf)
            do_setup("1.6", _Job())
            assert seen["tmpl_profiled"] is True and version_state("1.6")["pathfinding"] is False, "the stored decision"
            with open(g["STATE_PATH"], "wb") as f:
                f.write(b"{}")
            do_setup("1.6", _Job())
            assert "pathfinding" not in version_state("1.6"), "an installed stack nobody decided about keeps its files"
            assert looked == [], "none of the three asked the default"
            # a bundle in the payload alone -- the stack's own folder empty again -- is a navmesh too: the install
            # puts it into the stack before the pathfinding server boots
            os.remove(os.path.join(nav_dir, "scene_3.navmesh"))
            assert prepared() == (False, False, False, 0)
            nav_blob_ = struct.pack("<ii", 3, 0) + bytes(120)
            bundle_dir = os.path.join(pf_payloads, "1.6", "navmesh")
            os.makedirs(os.path.join(bundle_dir, "NavMesh"))
            with open(os.path.join(bundle_dir, "NavMesh", "scene_3.navmesh"), "wb") as f:
                f.write(nav_blob_)
            write_text(os.path.join(bundle_dir, NAVMESH_MANIFEST), json.dumps({"format": 1, "version": "1.6", "files": [
                {"name": "scene_3.navmesh", "size": len(nav_blob_), "md5": hashlib.md5(nav_blob_).hexdigest(),
                 "sha256": hashlib.sha256(nav_blob_).hexdigest(), "scene": 3}]}))
            assert len(navmesh_bundle("1.6")) == 1 and stack_navmesh_files("1.6") == 0
            assert prepared() == (True, True, True, 0), "a bundled navmesh alone: on"
            g["PATHFINDING_DEFAULT"] = False
            del looked[:]
            fresh_files()
            do_setup("1.6", _Job())
            assert seen["tmpl_profiled"] is True and g["status"]()["versions"]["1.6"]["pathfindingDefault"] is False \
                and looked == [], "GIO_PATHFINDING off: off, whatever the stack holds -- and nothing is looked at"
        finally:
            g.update(saved_pf)
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_
    ok("pathfinding profile edit OK (vendor syntax, CRLF/LF, idempotent, round-trip, oaserver untouched, "
       "dead_services filter, job argv, setup decision before the render; a stopped container of the service that "
       "no stop removed goes before the `up` that would start it, and while the stack is down)")
    ok("pathfinding default OK (asked only when it decides -- never with a choice, a stored decision or an installed "
       "stack; GIO_PATHFINDING on applies only with a navmesh file in the stack's own folder or a bundle in the "
       "payload: none, an empty folder, other names and a folder of that name = off; per version in the status with "
       "the stack's file count, null without a stack, never public; the payload folder of the run decides nothing)")

    # The MUIP sign key: a stack still on the archive's published key gets GIO_MUIP_KEY or a
    # random one (template + rendered xml + creds.txt + state), a private key is never touched, only a
    # fingerprint is ever logged or returned, and a template without sign_key cannot be prepared.
    faked_m = ("STATE_PATH", "MUIP_KEY", "log_line", "running_projects", "current_job")
    saved_m = {k: g[k] for k in faked_m}
    saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
    with tempfile.TemporaryDirectory() as td:
        try:
            stack = os.path.join(td, "1.6_live")
            conf = os.path.join(stack, "server", "muipserver", "conf")
            os.makedirs(conf)
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = stack, _project_name(stack)
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = "", ""
            tmpl_x, rendered_x = os.path.join(conf, "muipserver.xml.tmpl"), os.path.join(conf, "muipserver.xml")
            vendor = '<Root>\r\n  <ApiConf sign_key="8JTdsghuAythdHFtjkasiuHbxdjjayYfsvaJ" />\r\n</Root>\r\n'
            write_text(tmpl_x, vendor)
            write_text(rendered_x, vendor)
            write_text(os.path.join(stack, ".env"), "MYSQL_ROOT_PASSWORD=RootPw_1234\nFLASK_SECRET_KEY=fl\nOUTER_IP=192.0.2.10\n")
            write_text(os.path.join(stack, "docker-compose.yml.tmpl"), "cmd: redis-server --requirepass Internal_1234\n")
            write_text(os.path.join(stack, "creds.txt"), "MUIP_KEY: 8JTdsghuAythdHFtjkasiuHbxdjjayYfsvaJ\n")
            g.update({"STATE_PATH": os.path.join(td, "state.json"), "MUIP_KEY": "", "log_line": lambda *_a: None,
                      "running_projects": lambda: ([], None), "current_job": lambda **_k: None})
            assert is_vendor_muip_key("") and all(is_vendor_muip_key(k) for k in VENDOR_MUIP_KEYS) \
                and not is_vendor_muip_key("Chosen_Key_12345")
            assert random_muip_key() != random_muip_key() and SECRET_VALUE_RE.match(random_muip_key())
            assert muip_fingerprint("") is None and muip_fingerprint("abc") == hashlib.sha256(b"abc").hexdigest()[:8]
            j = _Job()
            assert ensure_muip_key("1.6", j) == "random"
            new = _read_sign_key_file(tmpl_x)
            assert len(new) == 36 and SECRET_VALUE_RE.match(new) and new not in VENDOR_MUIP_KEYS, new
            assert _read_sign_key_file(rendered_x) == new, "the rendered xml follows the template"
            assert read_text(tmpl_x) == vendor.replace("8JTdsghuAythdHFtjkasiuHbxdjjayYfsvaJ", new), "only the key, CRLF kept"
            creds = read_text(os.path.join(stack, "creds.txt"))
            assert "MUIP_KEY: %s" % new in creds and "mysql/root: RootPw_1234" in creds and "h4ke pass: Internal_1234" in creds, creds
            sec = version_state("1.6")["secrets"]
            assert sec["muipSource"] == "random" and sec["muipChangedAt"], sec
            assert len(j.lines) == 1 and new not in j.lines[0] and muip_fingerprint(new) in j.lines[0], "fingerprint only"
            assert ensure_muip_key("1.6", _Job()) is None and _read_sign_key_file(tmpl_x) == new, "a private key is never touched"
            write_text(tmpl_x, vendor)
            g["MUIP_KEY"] = "Chosen_Key_12345"
            j = _Job()
            assert ensure_muip_key("1.6", j) == "config"
            assert _read_sign_key_file(tmpl_x) == "Chosen_Key_12345" and _read_sign_key_file(rendered_x) == "Chosen_Key_12345"
            assert version_state("1.6")["secrets"]["muipSource"] == "config" and "Chosen_Key_12345" not in j.lines[0]
            write_text(tmpl_x, '<ApiConf sign_key="AdminRotated_0001" />\n')
            assert ensure_muip_key("1.6", _Job()) is None, "a key the admin rotated to is not replaced by the configured one"
            info = secrets_info("1.6")
            assert info["muip"]["vendorDefault"] is False and info["muip"]["source"] == "config" \
                and info["muip"]["fingerprint"] == hashlib.sha256(b"AdminRotated_0001").hexdigest()[:8], info["muip"]
            assert "AdminRotated_0001" not in json.dumps(info) and "Chosen_Key" not in json.dumps(info)
            write_text(tmpl_x, vendor)
            assert secrets_info("1.6")["muip"]["vendorDefault"] is True
            open(os.path.join(stack, "docker-compose.yml"), "w").close()  # present
            st16 = g["status"]()["versions"]["1.6"]
            assert st16["muipKey"] == "vendor" and st16["muipChangedAt"] == version_state("1.6")["secrets"]["muipChangedAt"], st16
            write_text(tmpl_x, '<ApiConf sign_key="AdminRotated_0001" />\n')
            full = g["status"]()
            assert full["versions"]["1.6"]["muipKey"] == "custom" and full["versions"]["2.8"]["muipKey"] is None
            assert "AdminRotated_0001" not in json.dumps(full) and "8JTdsghu" not in json.dumps(full)
            assert "muipKey" not in json.dumps(build_public_status(full, default_policy()))
            assert isinstance(full["pathfindingDefault"], bool) and "pathfinding" in full["versions"]["1.6"]
            write_text(tmpl_x, "<ApiConf />\n")
            try:
                ensure_muip_key("1.6", _Job())
                raise AssertionError("a template without sign_key must be a 500")
            except AgentError as e:
                assert e.status == 500 and "muipserver.xml.tmpl" in e.message, e.message
            # the import-time rule for GIO_MUIP_KEY is SECRET_VALUE_RE itself
            assert not SECRET_VALUE_RE.match("short1") and not SECRET_VALUE_RE.match("has space 12345") \
                and SECRET_VALUE_RE.match("x" * 128) and not SECRET_VALUE_RE.match("x" * 129)
        finally:
            g.update(saved_m)
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_
    ok("MUIP sign key OK (vendor key replaced with random/config, private key untouched, creds.txt + state, "
       "fingerprint only, 500 without sign_key, never public)")

    # The two .env secrets -- the MySQL root password and the Flask secret key -- on fake stacks in a
    # temp dir: no docker, no MySQL. The server is a MODEL of how the agent reaches the real one: every mysql_exec
    # is its own LOGIN as 'root'@'localhost' (`docker compose exec mysql mysql -uroot` = the socket), checked
    # against the password that account holds at that moment -- so a statement sent with the old password after
    # 'root'@'localhost' was altered is refused, whatever 'root'@'%' holds -- and an `up` over an absent / empty
    # mysql/ creates the database with what the RENDERED compose file names. Every wait_for_mysql runs on a
    # virtual clock. A nested function: selftest() has ~700 locals, one of which (`status`) already shadows a
    # module function; every fake goes in through g[...] and comes back out in the finally.
    def _env_secrets_block():
        g = globals()
        faked = ("STATE_PATH", "PAYLOAD_DIR", "PROVISION_MODE", "TXT_FIXES_MODE", "MYSQL_ROOT_PASSWORD",
                 "FLASK_SECRET_KEY", "MUIP_KEY", "ADVERTISED_IP", "ADVERTISED_HOST", "BIND_IP", "PATHFINDING_DEFAULT",
                 "IS_WINDOWS", "log_line", "protect_path", "replace_file", "_run", "_stream", "_compose_stream",
                 "running_projects", "current_job", "dead_services", "mysql_exec", "mysql_import", "install_files",
                 "ensure_templates", "heal_templates", "migrate_drop_scratch", "run_sql", "apply_events",
                 "repair_settled_activities", "apply_tower_schedule", "tower_mark_applied", "apply_advertised_ip",
                 "apply_hotpatch", "verify_stack", "ensure_exec_bits", "ensure_data_layout", "ensure_bind_ip",
                 "read_manifest", "find_extractor", "SERVER_NAME", "ensure_internal_password", "ensure_internal_sources",
                 "game_services_up", "game_account_login", "render_stack_configs", "start_job", "read_text",
                 "_backup_state", "write_text_durable", "write_text_atomic", "_write_state_atomic",
                 "KEEP_ENV", "_bindable", "detect_local_ip")
        saved = {k: g[k] for k in faked}
        saved_vdirs = {v: (VERSIONS[v]["dir"], VERSIONS[v]["project"]) for v in VERSIONS}
        saved_rec = dict(_STATE_RECOVERY)
        saved_clock, saved_fsync = (time.time, time.sleep), os.fsync
        VROOT, VFLASK = "UUshgAUgtGenMihOybO", "GuaHanbGfasCXCCClol"              # the 1.6 archive's .env
        VROOT28, VFLASK28 = "MyVeryLowPasswordHere", "FlaskVeryLowPasswordHere"  # the 2.8 archive's
        VMUIP, VINT = "8JTdsghuAythdHFtjkasiuHbxdjjayYfsvaJ", "HsjnaKGabKebabSarmale"
        public = (VROOT, VFLASK, VROOT28, VFLASK28, VMUIP, VINT)  # published with the archives: not secrets
        assert VENDOR_MYSQL_ROOT_PASSWORDS == {VROOT, VROOT28} and VENDOR_FLASK_KEYS == {VFLASK, VFLASK28}
        # the 1.6 archive's .env, verbatim: LF, a comment above each key, NO trailing newline
        vendor_env = (
            "# Mysql password for root. You can access the database using phpmyadmin or adminer in your browser.\n"
            "# (see open ports in docker-compose.yml)\n"
            "# You must change the default password if you want to make a public server, otherwise you will be hacked.\n"
            "MYSQL_ROOT_PASSWORD=UUshgAUgtGenMihOybO\n\nFLASK_SECRET_KEY=GuaHanbGfasCXCCClol\n\n"
            "# Server external IP. Keep 127.0.0.1 if you want to play localhost only\nOUTER_IP=127.0.0.1\n\n"
            "# Reload all configurations in seconds, set -1 for never reload (very expensive operation for the processor)\n"
            "RELOAD_CONFIG_INTERVAL=-1\n\n# Minimum 0.25, Maximum 1.00 as state (for 6 cores)\nCPU_USAGE_LIMIT=0.50")
        vendor_creds = "mysql/root: %s\r\nFlask: %s\r\nMUIP_KEY: %s\r\nh4ke pass: %s" % (VROOT, VFLASK, VMUIP, VINT)
        compose_tmpl = ("version: '3.9'\n\nservices:\n  mysql:\n    image: mariadb:10.9\n    restart: always\n"
                        "    environment:\n      MYSQL_ROOT_PASSWORD: %MYSQL_ROOT_PASSWORD%\n      MYSQL_ROOT_HOST: \"%\"\n"
                        "    volumes:\n      - ./mysql:/var/lib/mysql\n\n  redis:\n    image: redis:6.2\n"
                        "    command: redis-server --save 60 1 --loglevel warning --requirepass " + VINT + "\n\n"
                        "  adminer:\n    ports:\n      - \"%OUTER_IP%:8085:80\"\n")
        sdk_tmpl = ('{\n  "app": {\n    "listen": "0.0.0.0",\n    "port": 80,\n    "debug": false,\n'
                    '    "secret_key": "%FLASK_SECRET_KEY%"\n  },\n'
                    '  "auth": {\n    "enable_password_verify": false\n  }\n}\n')
        muip_tmpl = '<Root>\n  <ApiConf sign_key="%s" />\n  <Db user="hk4e_work" pwd="%s" />\n</Root>\n' % (VMUIP, VINT)
        bootstrap_sql = ("CREATE USER IF NOT EXISTS 'hk4e_work'@'172.10.%%' IDENTIFIED BY '%s';\n"
                         "CREATE USER IF NOT EXISTS 'hk4e_readonly'@'172.10.%%' IDENTIFIED BY '%s';\n" % (VINT, VINT))
        # every `docker compose` call on the vendor file carries this notice on stderr, next to the real answer
        NOTICE = ('time="2026-10-01T10:00:00+03:00" level=warning msg="docker-compose.yml: the attribute `version` is '
                  'obsolete, it will be ignored, please remove it to avoid potential confusion"\n')
        DENIED = "ERROR 1045 (28000): Access denied for user 'root'@'localhost' (using password: YES)"
        ALTER_ROOT = "ALTER USER IF EXISTS 'root'@'%' IDENTIFIED BY '?', 'root'@'localhost' IDENTIFIED BY '?'"
        ALTER_GAME = "'hk4e_work'@'172.10.%' IDENTIFIED BY '?', 'hk4e_readonly'@'172.10.%' IDENTIFIED BY '?'"
        READY = {"started": True, "provisioned": False, "eventsApplied": True}
        UP_DB, UP_ALL, DOWN = ("up", "-d", "mysql", "redis"), ("up", "-d"), ("down", "--remove-orphans")
        GAME_SERVICES = ("dbgate", "dispatch", "gameserver", "gateserver", "muipserver", "multiserver", "nodeserver")
        SERVICES = ("mysql", "redis", "sdk", "adminer", "phpmyadmin") + GAME_SERVICES
        # the places of the stack internal password, as the MODEL reads them (section J)
        MODEL_PLACES = re.compile(r"^CREATE USER IF NOT EXISTS '(?:hk4e_work|hk4e_readonly)'@'172\.10\.%' "
                                  r"IDENTIFIED BY '([^']*)'"
                                  r"|--requirepass (\S+)|-u hk4e_work -p(\S+)|\bpwd=\"([^\"]*)\"", re.M)
        INT_SOURCES = ("bootstrap.sql", "docker-compose.yml.tmpl",
                       os.path.join("dockerfiles", "prepare-db", "prepare-db.sh"))

        td = tempfile.mkdtemp(prefix="gio-selftest-secrets-")
        here = []         # [the stack folder mk() made last]
        srv = {}          # the model server: see mk() and fake_server()
        sent = []         # (outcome, head of the statement) of every login, in order -- never a password
        explicit = []     # the index in `sent` of every probe made with another password than .env's (a candidate)
        alters = []       # every ALTER USER that reached the server, its passwords cut out
        seen = {}         # what was ON DISK when the first ALTER arrived
        composes = []     # the argv of every docker compose call a job made
        compose_rc = {}   # argv -> the exit code it answers instead of 0
        protected = []    # (basename, mode) of every protect_path call
        events = []       # "fsync" / "replace <basename>", in order: what makes a write durable
        tmp_modes = []    # POSIX: the mode of the record's temp file at the moment it is renamed into place
        failing = set()   # basenames replace_file refuses with "disk full"
        held = set()      # basenames replace_file refuses with PermissionError: another program holds the file open
        spawned = []      # a process this block would have started for real -- must stay empty
        # ...and the stack internal password's half of the model (section J)
        logins = []       # (user, password, verdict, ALTERs so far) of every login as a game account (stack network)
        pings = []        # (password, answer) of every `redis-cli ping`
        ps_calls = []     # one entry per `docker compose ps` -- what game_up is read from
        boots = []        # per boot of game services: did their rendered files, both accounts and redis name ONE value?
        at_alter = []     # per ALTER USER: the record's internal pending line, the state's chooser, every place's value
        writes = []       # per file replaced that can hold a place: (basename, bytes changed?, places changed?, pending
        #                   line, ALTERs so far)
        record_writes = []  # per record replaced: (the internal pending line it puts there, the state's chooser then)
        written = {}      # section J: temp file -> the bytes its writer is putting there (write_text_durable / _atomic)
        at_down = []      # the record's internal pending line at every `down`
        verified = []     # ...and at every verify_stack
        bootstraps = []   # (pending line, the sources' values, chooser, fresh) when the vendor bootstrap read them
        renders = []      # every render_stack_configs the AGENT made (the vendor bootstrap's own render is not one)
        timeline = []     # non-empty from section J on: `writes` + `record_writes` are kept (more reads per write)
        # the files that can hold a place of the internal password (by name): only their writes go into `writes` (the
        # state file, .env, creds.txt and the record never hold one -- nothing to read back for them)
        PLACE_FILE_ENDINGS = (".sql", ".tmpl", ".yml", ".sh", ".xml")
        values = set()    # every secret that came up (generated, configured, chosen): the leak sweep's needles...
        jobs, journal, states, dumps, errors = [], [], [], [], []  # ...and its haystacks
        streamed = []     # ...and the command line a LOGGING runner (_stream / _compose_stream) writes into the job log

        class _Killed(BaseException):
            """The agent process dies here (no `except Exception` of the code under test may swallow it)."""

        def answer(rc, out="", err=""):
            return subprocess.CompletedProcess([], rc, stdout=out, stderr=NOTICE + (err + "\n" if err else ""))

        def fake_server(version, sql, db=None, timeout=300, password=None):
            """ONE login as 'root'@'localhost' with `password` -- else .env's value, exactly as _mysql_cmd takes
            it -- then the statement(s). An ALTER USER changes each account it names, in order, at once."""
            pw = password if password is not None else mysql_password(version)
            what = sql.split(" IDENTIFIED")[0][:60]
            if password is not None and sql == "SELECT 1":
                explicit.append(len(sent))
                if srv["hiccup"]:  # the server restarts under this one probe: no answer, not a refusal
                    srv["hiccup"] = 0
                    sent.append(("failed", what))
                    return answer(1, err="ERROR 2002 (HY000): Can't connect to local server through socket "
                                         "'/run/mysqld/mysqld.sock' (2)")
            if not srv["up"]:
                sent.append(("down", what))
                return answer(1, err="ERROR 2002 (HY000): Can't connect to local server through socket "
                                     "'/run/mysqld/mysqld.sock' (2)")
            if srv["broken"]:  # an answer that is NOT "root's password is wrong"
                sent.append(("failed", what))
                return answer(1, err=srv["broken"])
            if srv["deny_first"] > 0 or pw != srv["local"]:
                srv["deny_first"] = max(0, srv["deny_first"] - 1)
                sent.append(("denied", what))
                return answer(1, err=DENIED)
            if sql.startswith("SELECT User, Host FROM mysql.user"):  # (the layout check: which game accounts exist)
                if srv["accounts"] is None:  # (the server goes away under this one query: no answer)
                    sent.append(("failed", what))
                    return answer(1, err="ERROR 2013 (HY000): Lost connection to MySQL server during query")
                sent.append(("ok", what))
                return answer(0, out="User\tHost\n" + "".join("%s\t%s\n" % a_ for a_ in srv["accounts"]))
            specs = [s_ for stmt in sql.split(";") if stmt.strip().upper().startswith("ALTER USER")
                     for s_ in re.findall(r"'([^']+)'@'([^']+)' IDENTIFIED BY '([^']*)'", stmt)]
            if specs:
                alters.append(re.sub(r"IDENTIFIED BY '[^']*'", "IDENTIFIED BY '?'", sql))
                if not seen:
                    on_disk = read_creds_record(version)
                    seen.update(new=specs[0][2], login=pw, env=read_env(version).get("MYSQL_ROOT_PASSWORD", ""),
                                pending=on_disk["pending"], root=on_disk["root"])
                try:
                    chooser_ = (version_state(version).get("secrets") or {}).get("internalPendingSource")
                except AgentError:
                    chooser_ = None
                at_alter.append({"internal": pending_now(), "source": chooser_, "held": placed()})
                # a sequence ("half refused"): one mode per statement, in order
                how, _sp, srv["alter"] = srv["alter"].partition(" ")
                if srv["env_dies"]:   # .env was writable when the agent asked -- and stops being so at this moment
                    failing.add(".env")
                if any(user != "root" for user, _h, _p in specs):  # ...and what dies with the game accounts' ALTER
                    if srv["file_dies"]:
                        failing.add(srv["file_dies"])
                    if srv["record_dies"]:  # the record turns into something nothing can read
                        os.remove(creds_record_path(version))
                        os.makedirs(creds_record_path(version))
                    if srv["unknown_after_alter"]:
                        srv["login_unknown"] = True
                if how == "refused":  # nothing applied; the error quotes the statement and the login, as a client may
                    sent.append(("refused", what))
                    return answer(1, err="ERROR 1396 (HY000): Operation ALTER USER failed for %s (login: %s)" % (sql, pw))
                if how == "partial":  # not atomic: the root accounts are altered, then the statement fails
                    for user, host, new_pw in specs:
                        if user == "root":
                            srv["any" if host == "%" else "local"] = new_pw
                    sent.append(("partial", what))
                    return answer(1, err="ERROR 1396 (HY000) at line 1: Operation ALTER USER failed for "
                                         "'hk4e_work'@'172.10.%'")
                if how == "half":     # not atomic either: the first game account is altered, then the statement fails
                    user, _h, new_pw = next(s_ for s_ in specs if s_[0] != "root")
                    srv["game"][user] = new_pw
                    sent.append(("partial", what))
                    return answer(1, err="ERROR 1396 (HY000) at line 1: Operation ALTER USER failed for "
                                         "'hk4e_readonly'@'172.10.%'")
                if how == "work-only":  # (no error either -- and only hk4e_work changed)
                    srv["game"].update((user, new_pw) for user, _h, new_pw in specs if user == "hk4e_work")
                elif how != "noop":   # ("noop": the statement reports no error and changes nothing)
                    for user, host, new_pw in specs:
                        if user == "root":
                            srv["any" if host == "%" else "local"] = new_pw
                        else:
                            srv["game"][user] = new_pw
                if how == "kill":     # the server applied it; the agent never gets to see the answer
                    raise _Killed()
                if how == "lost":     # applied -- and the client reports a failure of its own
                    sent.append(("lost", what))
                    return answer(1, err="error during connect: open //./pipe/docker_engine: Access is denied.")
                if how == "crash":    # applied -- and the server is gone before anybody can ask it
                    srv["up"] = False
                    sent.append(("lost", what))
                    return answer(1, err="ERROR 2013 (HY000) at line 1: Lost connection to MySQL server during query")
                if how == "dead":     # afterwards the server accepts neither the old nor the new password
                    srv["local"] = srv["any"] = "Nobody_Knows_0000"
            sent.append(("ok", what))
            return answer(0, out="hk4e_db_user\n" if "hk4e_db_user" in sql else "1\n")

        def sql_step(label, result=None):
            """A later step of a job that talks to MySQL: one login with .env's password, like its statements."""
            def step(version, *_a, **k):
                if k.get("with_sql", True):
                    fake_server(version, "-- " + label)
                return result
            return step

        def place_values(text):
            """Every value the stack internal password's places name in one file's text, read with the MODEL's own
            pattern (never the agent's): the CREATE USER of the two game accounts, redis' --requirepass, prepare-db.sh's
            imports as hk4e_work, every pwd="..." of a server XML."""
            return [next(v_ for v_ in m.groups() if v_ is not None) for m in MODEL_PLACES.finditer(text)]

        def placed(sources=True, rendered=True, directory=None):
            """{the values every internal-password place of the stack names now}: the sources (bootstrap.sql, the
            compose template, prepare-db.sh, every server XML template), the rendered files (docker-compose.yml, every
            server XML) -- what a bootstrap reads, what redis and the game services run on."""
            d_, out = directory or here[0], set()
            for base, _dirs, names in os.walk(d_):
                for n_ in names:
                    rel = os.path.relpath(os.path.join(base, n_), d_)
                    if (sources and (rel in INT_SOURCES or (rel.startswith("server") and n_.endswith(".xml.tmpl")))) \
                            or (rendered and (rel == "docker-compose.yml"
                                              or (rel.startswith("server") and n_.endswith(".xml")))):
                        out.update(place_values(read_text(os.path.join(base, n_))))
            return out

        def rendered_requirepass(directory):
            try:
                m = re.search(r"--requirepass (\S+)", read_text(os.path.join(directory, "docker-compose.yml")))
            except OSError:
                return ""
            return m.group(1) if m else ""

        def pending_now():
            """The record's internal pending line right now ("" none, None = the record cannot be read)."""
            try:
                return read_creds_record("1.6")["internalPending"]
            except (OSError, AgentError):
                return None

        def handoff():
            """What the vendor bootstrap finds when it reads the sources: (the internal pending line, the sources'
            values, the state's chooser, the fresh-bootstrap mark)."""
            try:
                sec_ = version_state("1.6").get("secrets") or {}
            except AgentError:
                sec_ = {}
            return (pending_now(), placed(rendered=False), sec_.get("internalPendingSource"),
                    sec_.get("internalPendingFresh"))

        def create_accounts(directory):
            """bootstrap.sql: CREATE USER IF NOT EXISTS of the two game accounts -- an account that survived in a data
            dir nobody wiped keeps its password --, then prepare-db.sh's imports AS hk4e_work with its own -p value:
            srv["imports"] = whether the database took each of them."""
            sql_ = read_text(os.path.join(directory, "bootstrap.sql"))
            for user, pw_ in re.findall(r"(?m)^CREATE USER IF NOT EXISTS '(hk4e_work|hk4e_readonly)'@'172\.10\.%' "
                                        r"IDENTIFIED BY '([^']*)'", sql_):
                srv["game"].setdefault(user, pw_)
            try:
                sh_ = read_text(os.path.join(directory, "dockerfiles", "prepare-db", "prepare-db.sh"))
            except OSError:
                return
            srv["imports"] = [pw_ == srv["game"].get("hk4e_work") for pw_ in re.findall(r"-u hk4e_work -p(\S+)", sh_)]

        def consistent(directory):
            """A boot of the game services meets ONE value: every rendered place, both game accounts and redis."""
            vals = placed(sources=False, directory=directory)
            return len(vals) == 1 \
                and {srv["game"].get("hk4e_work"), srv["game"].get("hk4e_readonly"), srv["redis"]} == vals

        def docker(directory, argv):
            """What a compose call does to the model: `up` (re)creates the containers it names, every one when it names
            none -- MariaDB initialises an absent / empty mysql/ with the password the RENDERED compose file names
            (a database without the game accounts yet: the bootstrap creates them) and refuses every login while it
            does (`init_window` of them); redis is (re)created whenever its rendered command line names another
            password than the one it runs with; game services that were not running BOOT, each boot judged
            (`boots`) --, `down` stops everything."""
            if argv[:2] == UP_ALL:
                wanted_ = [a_ for a_ in argv[2:] if not a_.startswith("-")] or list(SERVICES)
                if "mysql" in wanted_:
                    data = os.path.join(directory, "mysql")
                    if not os.path.isdir(data) or not os.listdir(data):
                        os.makedirs(data, exist_ok=True)
                        write_text(os.path.join(data, "ibdata1"), "x")
                        named = re.search(r"(?m)^[ \t]+MYSQL_ROOT_PASSWORD:[ \t]*(\S+)",
                                          read_text(os.path.join(directory, "docker-compose.yml"))).group(1)
                        srv.update(local=named, any=named, inits=srv["inits"] + 1, deny_first=srv["init_window"],
                                   game={})
                    srv["up"] = True
                if "redis" in wanted_:
                    want = rendered_requirepass(directory)
                    if srv["redis"] not in (None, want):
                        srv["redis_recreated"] += 1
                    srv["redis"] = want
                booted = [s_ for s_ in wanted_ if s_ in GAME_SERVICES and srv["services"].get(s_) != "running"]
                srv["services"].update(dict.fromkeys(wanted_, "running"))
                if booted:
                    boots.append(consistent(directory))
            elif argv[:1] == ("down",):
                srv.update(up=False, services={}, redis=None)

        def fake_compose(directory, job_, *argv, **kw):
            composes.append(argv)
            streamed.append("$ " + " ".join(["docker", "compose", "--project-directory", directory] + list(argv)))
            if argv[:1] == ("down",):
                at_down.append(pending_now())
            if compose_rc.get(argv, 0) == 0:
                docker(directory, argv)
            return compose_rc.get(argv, 0)

        def counted_render(version, job_):
            """render_stack_configs, counted: a render the AGENT makes (the vendor bootstrap's own goes around this)."""
            renders.append(version)
            return saved["render_stack_configs"](version, job_)

        def fake_stream(argv, job_, cwd=None, timeout=0, prefix=""):
            """The vendor bootstrap. Linux: bootstrap.sh in one go -- `sudo rm -rf mysql redis` (silently skipped
            without sudo: the script has no `set -e`), render, mysql up, the accounts + the import, the lock, the full
            stack. Windows: the same steps as _bootstrap_windows sends them, one docker call each."""
            streamed.append("$ " + " ".join(argv))
            if argv == ["bash", "bootstrap.sh"]:
                bootstraps.append(handoff())
                for _ in range(40 if srv["sudo"] else 0):  # (on Windows a scanner may hold a file for a moment)
                    shutil.rmtree(os.path.join(cwd, "mysql"), ignore_errors=True)
                    if not os.path.exists(os.path.join(cwd, "mysql")):
                        break
                    saved_clock[1](0.05)
                saved["render_stack_configs"]("1.6", _Job())
                docker(cwd, UP_DB)
                create_accounts(cwd)
                write_text(os.path.join(cwd, ".bootstrap.lock"), "\n")
                docker(cwd, UP_ALL)
                return 0
            if argv[:2] == ["docker", "compose"]:
                step = tuple(a for a in argv[2:] if a not in ("-f", "docker-preinstall.yml"))
                if step == ("up", "preparevars"):
                    bootstraps.append(handoff())
                    saved["render_stack_configs"]("1.6", _Job())  # what prepare-vars.sh does with the templates
                elif step == ("up", "preparedb"):
                    create_accounts(cwd)
                elif step[:2] == UP_ALL or step[:1] == ("down",):
                    docker(cwd, step)
                return 0
            if argv[:2] == ["docker", "network"]:
                return 0
            spawned.append(list(argv[:4]))
            return 127

        def game_login(user, pw_):
            """A login as a game account over the stack network, as the services make it: what the account holds
            decides -- while MySQL runs and docker answers at all ("unknown" otherwise)."""
            if srv["login_unknown"] or not srv["up"]:
                verdict = "unknown"
                r_ = answer(1, err="error during connect: open //./pipe/docker_engine: Access is denied." if srv["up"]
                            else 'service "mysql" is not running')
            elif srv["game"].get(user) == pw_:
                verdict, r_ = "ok", answer(0, out="1\n")
            else:
                verdict, r_ = "refused", answer(1, err="ERROR 1045 (28000): Access denied for user '%s'@'172.10.3.100' "
                                                       "(using password: YES)" % user)
            logins.append((user, pw_, verdict, len(alters)))
            return r_

        def redis_ping(pw_):
            if srv["redis"] is None:
                r_ = answer(1, err='service "redis" is not running')
            elif srv["redis_loading"] > 0 or srv["redis_mute"]:
                srv["redis_loading"] = max(0, srv["redis_loading"] - 1)
                r_ = answer(0, out="LOADING Redis is loading the dataset in memory\n")
            elif pw_ == srv["redis"]:
                r_ = answer(0, out="PONG\n")
            else:
                r_ = answer(0, out="NOAUTH Authentication required.\n",
                            err="AUTH failed: WRONGPASS invalid username-password pair or user is disabled.")
            pings.append((pw_, r_.stdout.strip()))
            return r_

        def fake_run(args, **_kw):
            """The docker calls the agent makes through the NON-logging runner (_run / _compose), answered by the model
            -- in exactly the shape they must have: `ps` of the project, a login as a game account to the mysql
            container's own address (no shell inside the container), redis-cli with the password in REDISCLI_AUTH
            (never on its own argv) -- and every password named by a bare `-e NAME`, its value in the environment of
            the docker CLI process (_exec_args): never on docker's argv either. Anything else would be a real
            process: recorded, never started."""
            a_ = list(args)
            if a_[:3] == ["docker", "compose", "--project-directory"] and len(a_) > 5:
                rest = a_[4:]
                if rest == ["ps", "-a", "--format", "json"]:
                    ps_calls.append(a_[3])
                    if srv["ps_fail"]:
                        return answer(1, err="Cannot connect to the Docker daemon at unix:///var/run/docker.sock.")
                    return answer(0, out="".join(json.dumps({"Service": s_, "State": st_}) + "\n"
                                                 for s_, st_ in srv["services"].items()))
                if rest[:3] == ["exec", "-T", "-e"] and len(rest) > 5:
                    name_, svc, cmd = rest[3], rest[4], rest[5:]
                    pw_ = (_kw.get("env") or {}).get(name_) if "=" not in name_ else None
                    if svc == "mysql" and name_ == "MYSQL_PWD" and pw_ is not None and len(cmd) == 6 \
                            and cmd[:2] == ["mysql", "-h172.10.3.100"] and cmd[2][:2] == "-u" \
                            and cmd[3:] == ["-N", "-e", "SELECT 1"]:
                        return game_login(cmd[2][2:], pw_)
                    if svc == "redis" and name_ == "REDISCLI_AUTH" and pw_ is not None and cmd[:1] == ["redis-cli"] \
                            and "-a" not in cmd:
                        if cmd[1:] == ["ping"]:
                            return redis_ping(pw_)
                        if cmd[1:4] == ["-n", "7", "EXISTS"] and len(cmd) == 5:  # (_uid_online)
                            if pw_ == srv["redis"]:
                                return answer(0, out="0\n")
                            return answer(0, out="NOAUTH Authentication required.\n",
                                          err="AUTH failed: WRONGPASS invalid username-password pair or user is "
                                              "disabled.")
                if rest == ["--profile", "donotstart", "rm", "-f", "pathfindingserver"]:  # (drop_pathfinding_leftover)
                    return answer(0, err="No stopped containers\n")
            spawned.append(list(args[:4]))
            return _Failed("the selftest starts no process here")

        def fake_protect(path_, mode_):
            protected.append((os.path.basename(path_), mode_))
            if os.name != "nt":  # the chmod itself: the real one branches on IS_WINDOWS, which this block fakes
                try:
                    os.chmod(path_, mode_)
                except OSError:
                    pass

        def new_bytes(src):
            """What a temp file about to be renamed into place holds: as its writer handed it over (section J), else
            read back."""
            b_ = written.get(src)
            if b_ is None:
                with open(src, "rb") as f:
                    b_ = f.read()
            return b_

        def fake_replace(src, dst, attempts=5, delay=0.2):
            if os.path.basename(dst) in failing:
                raise OSError(errno.ENOSPC, "No space left on device (selftest)")
            if os.path.basename(dst) in held:  # what Windows answers for a destination somebody keeps open
                raise PermissionError(errno.EACCES, "Access is denied (selftest)")
            if os.path.basename(dst) == CREDS_RECORD and os.name != "nt":
                tmp_modes.append(os.stat(src).st_mode & 0o777)
            if timeline and os.path.basename(dst) == CREDS_RECORD:  # (section J: who had chosen a value it records)
                line_ = _parse_creds_record(new_bytes(src).decode("utf-8", "replace"))[0]["internalPending"]
                try:
                    chooser_ = (version_state("1.6").get("secrets") or {}).get("internalPendingSource")
                except AgentError:
                    chooser_ = None
                record_writes.append((line_, chooser_))
            if timeline and os.path.basename(dst).endswith(PLACE_FILE_ENDINGS):  # (section J: what each write
                # changed, and what was on record meanwhile)
                new_ = new_bytes(src)
                try:
                    with open(dst, "rb") as f:
                        old_ = f.read()
                except OSError:
                    old_ = None
                if os.path.basename(dst) == srv["write_lost"] and new_ != old_:
                    os.remove(src)  # the disk lost this write: nothing changes, nobody is told
                    return None
                moved = place_values((old_ or b"").decode("utf-8", "replace")) \
                    != place_values(new_.decode("utf-8", "replace"))
                writes.append((os.path.basename(dst), new_ != old_, moved, pending_now(), len(alters)))
            events.append("replace " + os.path.basename(dst))
            return saved["replace_file"](src, dst, attempts, delay)

        def virtual(fn, nap=1):
            """fn() on a virtual clock: time.time() reads it and time.sleep() advances it (a pause of up to `nap`
            seconds -- replace_file's or an rmtree's retry while a scanner holds a file -- is really slept too).
            Returns (fn's result, the seconds the pauses longer than one second -- wait_for_mysql's 3 s -- added up
            to)."""
            now, waited = [1000000.0], [0]

            def vsleep(s):
                now[0] += s
                if s > 1:
                    waited[0] += s
                elif s <= nap:
                    saved_clock[1](s)

            time.time, time.sleep = (lambda: now[0]), vsleep
            try:
                out = fn()
            finally:
                time.time, time.sleep = saved_clock
            return out, waited[0]

        def keep_state():
            try:
                with open(g["STATE_PATH"], "rb") as f:
                    states.append(f.read().decode("utf-8", "replace"))
            except OSError:
                pass

        def mk(name, env=vendor_env, data=True, bootstrapped=True, server_root=None, up=False, creds=vendor_creds):
            """A new fake 1.6 stack and an empty agent state. `env` = its .env, `creds` = its creds.txt (None =
            no such file), `bootstrapped` = rendered from that .env + the lock, `data` = an initialised mysql/.
            The model server holds `server_root` (default: what that .env says) and is `up` or down."""
            learn()
            keep_state()
            stack = os.path.join(td, name, "1.6_live")
            os.makedirs(os.path.join(stack, "server", "muipserver", "conf"))
            os.makedirs(os.path.join(stack, "sdk", "data"))
            for rel, text in ((".env", env), ("creds.txt", creds), ("bootstrap.sh", "#!/bin/bash\n"),
                              ("bootstrap.sql", bootstrap_sql), ("docker-preinstall.yml", "services: {}\n"),
                              ("docker-compose.yml.tmpl", compose_tmpl),
                              (os.path.join("sdk", "data", "config.json.tmpl"), sdk_tmpl),
                              (os.path.join("server", "muipserver", "conf", "muipserver.xml.tmpl"), muip_tmpl)):
                if text is not None:
                    write_text(os.path.join(stack, rel), text)
            VERSIONS["1.6"]["dir"], VERSIONS["1.6"]["project"] = stack, _project_name(stack)
            with open(g["STATE_PATH"], "wb") as f:
                f.write(b"{}")
            if bootstrapped:
                render_stack_configs("1.6", _Job())
                write_text(os.path.join(stack, ".bootstrap.lock"), "\n")
            if data:
                os.makedirs(os.path.join(stack, "mysql"))
                write_text(os.path.join(stack, "mysql", "ibdata1"), "x")
            if server_root is None:
                server_root = read_env("1.6").get("MYSQL_ROOT_PASSWORD", "") if env is not None else ""
            values.add(server_root)
            srv.clear()
            srv.update(local=server_root, any=server_root, game={"hk4e_work": VINT, "hk4e_readonly": VINT}, up=up,
                       deny_first=0, broken="", alter="", sudo=True, inits=0, init_window=0, hiccup=0,
                       env_dies=False)
            # ...the stack internal password's half (section J): the accounts the server lists (None: that query gets
            # no answer), the services that run (every one, on a stack that is up), the password redis runs with, and
            # what can go wrong
            srv.update(accounts=[("hk4e_work", "172.10.%"), ("hk4e_readonly", "172.10.%")],
                       services=dict.fromkeys(SERVICES, "running") if up else {},
                       redis=rendered_requirepass(stack) if up else None, redis_recreated=0, redis_loading=0,
                       redis_mute=False, ps_fail=False, login_unknown=False, unknown_after_alter=False, file_dies="",
                       record_dies=False, write_lost="", imports=[])
            for box in (sent, explicit, alters, composes, protected, events, tmp_modes, logins, pings, ps_calls, boots,
                        at_alter, writes, record_writes, at_down, verified, bootstraps, renders):
                del box[:]
            seen.clear()
            failing.clear()
            held.clear()
            compose_rc.clear()
            here[:] = [stack]
            return stack

        def job():
            keep_state()
            jobs.append(_Job())
            return jobs[-1]

        def rd(*rel):
            with open(os.path.join(here[0], *rel), "rb") as f:
                return f.read().decode("utf-8")

        def tree():
            """{relative path: bytes} of every file of the current stack: "nothing was written" is an equality."""
            out = {}
            for base, _dirs, names in os.walk(here[0]):
                for n_ in names:
                    with open(os.path.join(base, n_), "rb") as f:
                        out[os.path.relpath(os.path.join(base, n_), here[0])] = f.read()
            return out

        def rec():
            """The record's two root lines (the internal password's line has cases of its own)."""
            r_ = read_creds_record("1.6")
            return {"root": r_["root"], "pending": r_["pending"]}

        def note(value):
            values.add(value)
            return value

        def env16(key="MYSQL_ROOT_PASSWORD"):
            return note(read_env("1.6").get(key, ""))

        def muip16():
            return note(_read_sign_key_file(muip_key_file("1.6")))

        def learn():
            """Whatever the current stack's files and the model hold right now is a secret of this block."""
            values.update(v_ for v_ in (srv.get("local"), srv.get("any"), srv.get("redis")) + tuple(seen.values())
                          + tuple((srv.get("game") or {}).values()) + tuple(p_ for _u, p_, _v, _n in logins)
                          + tuple(p_ for p_, _a in pings) + tuple(a_["internal"] for a_ in at_alter)
                          if isinstance(v_, str))
            if here:
                try:
                    values.update(read_creds_record("1.6").values())
                except OSError:
                    pass  # (a record made unreadable on purpose)
                try:
                    env16(), env16("FLASK_SECRET_KEY"), muip16()
                    values.update(placed())
                except OSError:
                    pass

        def shown(*what):
            """repr() for an assertion message, every value of this block cut out of it: a message never carries
            a password, not even a temp stack's."""
            learn()
            text = repr(what[0] if len(what) == 1 else what)
            for v_ in sorted(values.union(public), key=len, reverse=True):
                text = text.replace(v_, "<value>") if v_ else text
            return text

        def clean(lines, *secrets_):
            """None of the given values in any line; the message names the line by number, never by text."""
            values.update(s_ for s_ in secrets_ if s_)
            bad = [i for i, l in enumerate(lines) if any(s_ and s_ in l for s_ in secrets_)]
            assert not bad, "a secret value reached line(s) %s of %d" % (bad, len(lines))

        def warned(job_):
            return len([l for l in job_.lines if l.startswith("WARNING")])

        def raises(status_, fn):
            try:
                fn()
            except AgentError as e:
                errors.append(e.message)
                keep_state()
                assert e.status == status_, (e.status, shown(e.message))
                return e.message
            raise AssertionError("must be refused with %d" % status_)

        def status16():
            """/status of the 1.6 stack (`status` is a local loop name of selftest(), hence g[...])."""
            full = g["status"]()
            dumps.extend((json.dumps(full), json.dumps(build_public_status(full, default_policy()))))
            return full["versions"]["1.6"]

        def kinds():
            st_ = status16()
            return st_["mysqlPassword"], st_["flaskKey"], st_["muipKey"]

        def compose_of(root, ip="127.0.0.1", internal=VINT):
            return compose_tmpl.replace("%MYSQL_ROOT_PASSWORD%", root).replace("%OUTER_IP%", ip).replace(VINT, internal)

        def sdk_of(flask):
            return sdk_tmpl.replace("%FLASK_SECRET_KEY%", flask)

        def creds_of(root, flask, muip, internal=VINT):
            """creds.txt byte for byte as it is written over the vendor's file (CRLF kept, a final line break)."""
            return ("# Managed by the Relic GIO agent -- rewritten whenever a secret changes.\r\nmysql/root: %s\r\n"
                    "Flask: %s\r\nMUIP_KEY: %s\r\nh4ke pass: %s\r\n" % (root, flask, muip, internal))

        def env_of(root, flask=VFLASK):
            return vendor_env.replace(VROOT, root).replace(VFLASK, flask)

        def reextract():
            """The archive extracted over the stack again: .env, creds.txt and the templates are the vendor's
            once more; nothing rendered, no .relic-* file and not mysql/ is touched."""
            for rel, text in ((".env", vendor_env), ("creds.txt", vendor_creds),
                              (os.path.join("server", "muipserver", "conf", "muipserver.xml.tmpl"), muip_tmpl)):
                write_text(os.path.join(here[0], rel), text)

        def no_tmp():
            return not [n_ for n_ in os.listdir(here[0]) if n_.endswith(".tmp")]

        try:
            os.makedirs(os.path.join(td, "payloads", "1.6"))  # no manifest in it: this "box" ships no payload
            VERSIONS["2.8"]["dir"], VERSIONS["2.8"]["project"] = "", ""
            g.update({"STATE_PATH": os.path.join(td, "state.json"), "PAYLOAD_DIR": os.path.join(td, "payloads"),
                      "PROVISION_MODE": "once", "TXT_FIXES_MODE": "now", "MYSQL_ROOT_PASSWORD": "",
                      "FLASK_SECRET_KEY": "", "MUIP_KEY": "", "ADVERTISED_IP": "", "ADVERTISED_HOST": "", "BIND_IP": "",
                      "PATHFINDING_DEFAULT": True, "SERVER_NAME": "selftest",
                      "log_line": lambda *a: journal.append(" ".join(str(x) for x in a)),
                      "protect_path": fake_protect, "replace_file": fake_replace, "_run": fake_run,
                      "_stream": fake_stream, "_compose_stream": fake_compose, "current_job": lambda **_k: None,
                      # (listed while any of its containers runs -- MySQL, or only redis and the sdk after a reboot)
                      "running_projects": lambda: ([VERSIONS["1.6"]["project"]] if srv["up"]
                                                   or "running" in srv["services"].values() else [], None),
                      "render_stack_configs": counted_render,
                      "dead_services": lambda _v: (None, None), "find_extractor": lambda: None,
                      "mysql_exec": fake_server,
                      "mysql_import": lambda version, _path, db, timeout=1800: fake_server(version, "-- import " + db),
                      "install_files": lambda _v, _j, _stages: 0, "ensure_templates": sql_step("templates", {}),
                      "heal_templates": sql_step("templates"), "migrate_drop_scratch": sql_step("move leftovers"),
                      "run_sql": sql_step("sql"),
                      "apply_events": sql_step("events"), "repair_settled_activities": sql_step("settled", 0),
                      "apply_tower_schedule": lambda *a, **k: None, "tower_mark_applied": lambda *a, **k: None,
                      "apply_advertised_ip": sql_step("advertised ip", False),
                      "apply_hotpatch": sql_step("hotpatch", False),
                      "verify_stack": lambda *a, **k: verified.append(pending_now()),
                      "ensure_exec_bits": lambda *a, **k: 0, "ensure_data_layout": lambda *a, **k: 0,
                      # The stack internal password is not this block's subject: its db stage and file
                      # level stand still here (its own cases replace them), docker is never asked whether game
                      # services run, and a login as a game account answers from the model's two accounts.
                      "ensure_internal_password": lambda *a, **k: False,
                      "ensure_internal_sources": lambda *a, **k: None, "game_services_up": lambda _v: None,
                      "game_account_login": lambda _v, user, password: (
                          "unknown" if not srv["up"] else "ok" if srv["game"].get(user) == password else "refused")})
            _STATE_RECOVERY.update(degraded=None, corruptCopy=None)
            # Recorded, not performed: WHEN a write is synced is the fact to check; the temp dir's own durability
            # is nobody's (and the block's ~600 real fsyncs would cost more than everything else in it).
            os.fsync = lambda _fd: events.append("fsync")

            # (A) the pure parts: the generator, the two rules (\Z: a trailing line break is refused), the editors
            a_, b_ = random_secret_value(), random_secret_value()
            assert a_ != b_ and len(a_) == 32 and a_.isalnum() and len(random_secret_value(12)) == 12
            assert all(random_secret_value()[0] in string.ascii_letters for _ in range(300)), "never a digit first"
            assert MYSQL_ROOT_RE.match(a_) and SECRET_VALUE_RE.match(a_)
            for rx in (SECRET_VALUE_RE, MYSQL_ROOT_RE):
                assert rx.match("Abcdefgh") and rx.match("a" * 128) and rx.match("Root_Pw-12345"), rx.pattern
                for bad in ("Abcdefg", "a" * 129, "Abc defgh", "Abcdefgh\n", "Abcdefgh\r\n", "Abcdefg'", ""):
                    assert not rx.match(bad), "%s must refuse %r" % (rx.pattern, bad)
            for bad in ("01234567", "-abcdefg", "_abcdefg"):  # a Flask / MUIP key may; the unquoted YAML scalar not
                assert SECRET_VALUE_RE.match(bad) and not MYSQL_ROOT_RE.match(bad), bad
            for nl_ in ("\n", "\r\n"):
                text = compose_of(VROOT).replace("\n", nl_)
                new, n = set_compose_env_value(text, "MYSQL_ROOT_PASSWORD", "NewRoot_0001")
                assert n == 1 and new == compose_of("NewRoot_0001").replace("\n", nl_), "only the value changes"
                assert set_compose_env_value(new, "MYSQL_ROOT_PASSWORD", "NewRoot_0001") == (new, 0), "n = CHANGED lines"
                assert compose_env_value(new, "MYSQL_ROOT_PASSWORD") == "NewRoot_0001"
                assert compose_env_value(new, "MYSQL_ROOT_HOST") == "%" and compose_env_value(new, "MYSQL_PWD") is None
                text = sdk_of(VFLASK).replace("\n", nl_)
                new, n = set_sdk_secret_key_text(text, "NewFlask_001")
                assert n == 1 and new == sdk_of("NewFlask_001").replace("\n", nl_) and sdk_secret_key(new) == "NewFlask_001"
                assert set_sdk_secret_key_text(new, "NewFlask_001") == (new, 0)
            for text, want in (
                    ("  x:\r\n    MYSQL_ROOT_PASSWORD: old   # note\r\n", "  x:\r\n    MYSQL_ROOT_PASSWORD: N   # note\r\n"),
                    ('  x:\n    MYSQL_ROOT_PASSWORD: "an old one"\n', "  x:\n    MYSQL_ROOT_PASSWORD: N\n"),
                    ("  x:\n    MYSQL_ROOT_PASSWORD:\n    y: 1\n", "  x:\n    MYSQL_ROOT_PASSWORD: N\n    y: 1\n")):
                assert set_compose_env_value(text, "MYSQL_ROOT_PASSWORD", "N") == (want, 1), want
            for text in ("services: {}\n", "    # MYSQL_ROOT_PASSWORD: commented out\n"):
                assert set_compose_env_value(text, "MYSQL_ROOT_PASSWORD", "N") == (text, 0)
                assert compose_env_value(text, "MYSQL_ROOT_PASSWORD") is None
            assert compose_env_value("  x:\n    MYSQL_ROOT_PASSWORD:\n", "MYSQL_ROOT_PASSWORD") == ""
            assert set_sdk_secret_key_text("{}", "x") == ("{}", 0) and sdk_secret_key("{}") is None

            # (B) creds.txt is written byte for byte in its fixed layout and NEVER touches the record; the record has
            #     its own two lines (None keeps one, "" removes it), is private and is replaced atomically
            stack = mk("b")
            assert rec() == {"root": "", "pending": ""}
            write_creds_file("1.6", {"mysqlRoot": "a1", "flask": "b1", "muip": "c1", "internal": "d1"})
            assert rd("creds.txt") == creds_of("a1", "b1", "c1", "d1") and protected == [("creds.txt", 0o600)], protected
            assert not os.path.exists(os.path.join(stack, CREDS_RECORD)), "write_creds_file must leave the record alone"
            del events[:]
            write_creds_record("1.6", pending="Pend_00000001")
            assert rec() == {"root": "", "pending": "Pend_00000001"}
            assert events == ["fsync", "replace " + CREDS_RECORD] + ["fsync"] * (os.name != "nt"), \
                "synced BEFORE the rename (then the folder): %r" % (events,)
            write_creds_record("1.6", root="Root_00000001")
            assert rec() == {"root": "Root_00000001", "pending": "Pend_00000001"}, "None keeps a line"
            lines = rd(CREDS_RECORD).split("\n")
            assert len(lines) > 3 and all(l.startswith("# ") for l in lines[:-3]) and "\r" not in rd(CREDS_RECORD)
            assert lines[-3:] == ["mysql/root: Root_00000001", "mysql/root (pending): Pend_00000001", ""], len(lines)
            assert protected[-1] == (CREDS_RECORD, 0o600) and no_tmp()
            if os.name != "nt":
                assert os.stat(os.path.join(stack, CREDS_RECORD)).st_mode & 0o777 == 0o600
                assert tmp_modes == [0o600, 0o600], "the temp file is CREATED private, not made so afterwards"
            write_creds_file("1.6", {"mysqlRoot": VROOT, "flask": "b2", "muip": "c2", "internal": "d1"})
            assert ensure_muip_key("1.6", job()) == "random" and not is_vendor_muip_key(muip16())
            assert rec() == {"root": "Root_00000001", "pending": "Pend_00000001"}, \
                "a creds.txt rewrite (write_creds_file, the MUIP key's) must never copy .env's value into the record"
            write_creds_record("1.6", pending="")
            assert rec() == {"root": "Root_00000001", "pending": ""} and "pending" not in rd(CREDS_RECORD), '"" removes'
            write_creds_record("1.6", root="", pending="Pend_00000002")
            assert rec() == {"root": "", "pending": "Pend_00000002"}
            failing.add(CREDS_RECORD)
            try:
                write_creds_record("1.6", root="Root_00000003")
                raise AssertionError("a record that cannot be written is the caller's OSError")
            except OSError:
                pass
            failing.clear()
            assert rec() == {"root": "", "pending": "Pend_00000002"} and no_tmp(), "the old record stays, no temp file"
            # a temp file left behind by a write that was KILLED (the create is exclusive) is no obstacle
            write_text(os.path.join(stack, CREDS_RECORD + ".tmp"), "left by a killed write")
            write_creds_record("1.6", root="Root_00000004")
            assert rec() == {"root": "Root_00000004", "pending": "Pend_00000002"} and no_tmp()
            # ...a creds.txt of the agent's own making is LF, a record that exists but cannot be read RAISES
            # (read as empty, the next write would rebuild it without the lines it could not see) -- and .env
            # itself is replaced the same way: the same bytes, the same mode, never torn
            stack = mk("b-env", data=False, bootstrapped=False, creds=None)
            write_creds_file("1.6", {"mysqlRoot": "a1", "flask": "b1", "muip": "c1", "internal": "d1"})
            assert rd("creds.txt") == creds_of("a1", "b1", "c1", "d1").replace("\r\n", "\n")
            os.makedirs(os.path.join(stack, CREDS_RECORD))
            try:
                read_creds_record("1.6")
                raise AssertionError("a record that exists but cannot be read must be the caller's OSError")
            except OSError:
                pass
            del events[:]
            if os.name != "nt":
                os.chmod(os.path.join(stack, ".env"), 0o640)
            write_text(os.path.join(stack, ".env.tmp"), "MYSQL_ROOT_PASSW")  # (a killed write's leftover)
            write_env_value("1.6", "OUTER_IP", "192.0.2.77")
            assert rd(".env") == vendor_env.replace("OUTER_IP=127.0.0.1", "OUTER_IP=192.0.2.77") and no_tmp()
            assert events == ["fsync", "replace .env"] + ["fsync"] * (os.name != "nt"), events
            if os.name != "nt":
                assert os.stat(os.path.join(stack, ".env")).st_mode & 0o777 == 0o640
            failing.add(".env")
            before = tree()
            try:
                write_env_value("1.6", "OUTER_IP", "192.0.2.78")
                raise AssertionError("an .env that cannot be replaced is the caller's OSError")
            except OSError:
                pass
            assert tree() == before, "a failed write leaves .env as it was and no temp file"
            failing.clear()
            write_env_value("1.6", "ODD", "a\\1b\\g<0>c")  # (a recovered hand-made password may hold a backslash)
            assert read_env("1.6")["ODD"] == "a\\1b\\g<0>c", "a value is written as it is, never as a regex template"
            # Windows alone: an .env another program HOLDS OPEN cannot be replaced (the rename is refused) but can
            # still be written in place -- the durable way is tried first, then the value gets
            # there all the same. Elsewhere that refusal is the caller's OSError, as a full disk is on every platform
            for win in (False, True):
                g["IS_WINDOWS"] = win
                for refusal, ip in ((failing, "192.0.2.78"), (held, "192.0.2.79")):
                    refusal.add(".env")
                    before = tree()
                    del events[:]
                    try:
                        write_env_value("1.6", "OUTER_IP", ip)
                        wrote = True
                    except OSError:
                        wrote = False
                    refusal.clear()
                    assert wrote is (win and refusal is held), (win, ip)
                    assert events == ["fsync"] and no_tmp(), "the temp file was written and synced, the rename refused"
                    if wrote:
                        assert rd(".env") == before[".env"].decode().replace("OUTER_IP=192.0.2.77", "OUTER_IP=" + ip)
                    else:
                        assert tree() == before, (win, ip)
            g["IS_WINDOWS"] = saved["IS_WINDOWS"]

            # (C) the file level. The vendor's .env verbatim -- LF with the 1.6 archive's literals, CRLF with the
            #     2.8 archive's -- on a stack nothing was rendered or created for yet: only the two values change
            for nl_, vroot, vflask in (("\n", VROOT, VFLASK), ("\r\n", VROOT28, VFLASK28)):
                env0 = vendor_env.replace(VROOT, vroot).replace(VFLASK, vflask).replace("\n", nl_)
                stack = mk("c-fresh%d" % len(nl_), env=env0, data=False, bootstrapped=False)
                j = job()
                out = ensure_env_secrets("1.6", j, cold=True)
                assert out == {"flask": "random", "mysqlRoot": "random"}, out
                root, flask = env16(), env16("FLASK_SECRET_KEY")
                assert MYSQL_ROOT_RE.match(root) and SECRET_VALUE_RE.match(flask) and root != flask
                assert root not in VENDOR_MYSQL_ROOT_PASSWORDS and flask not in VENDOR_FLASK_KEYS
                assert rd(".env") == env0.replace(vroot, root).replace(vflask, flask), "only the two values change"
                assert not rd(".env").endswith("\n"), "still no trailing newline"
                assert rd("docker-compose.yml.tmpl") == compose_tmpl and rd("sdk", "data", "config.json.tmpl") == sdk_tmpl
                assert rec() == {"root": "", "pending": root}, "no server has accepted it yet: pending, never root"
                assert rd("creds.txt") == creds_of(root, flask, VMUIP)
                assert set(version_state("1.6")) == {"secrets"}, sorted(version_state("1.6"))
                sec = version_state("1.6")["secrets"]
                assert sec["mysqlRootSource"] == sec["flaskSource"] == "random" and sec["mysqlRootChangedAt"] \
                    and sec["flaskChangedAt"], sorted(sec)
                assert len(j.lines) == 2, shown(j.lines)
                clean(j.lines, root, flask)
                before = tree()
                for cold in (True, False):
                    j = job()
                    assert ensure_env_secrets("1.6", j, cold=cold) == {} and j.lines == [], shown(j.lines)
                assert tree() == before and sent == [] and composes == [], "a private value is never touched"
            # the configured values
            g.update({"MYSQL_ROOT_PASSWORD": "CfgRoot_12345", "FLASK_SECRET_KEY": "CfgFlask_12345"})
            stack = mk("c-config", data=False, bootstrapped=False)
            j = job()
            assert ensure_env_secrets("1.6", j, cold=True) == {"flask": "config", "mysqlRoot": "config"}
            assert rd(".env") == env_of("CfgRoot_12345", "CfgFlask_12345") and rec()["pending"] == "CfgRoot_12345"
            sec = version_state("1.6")["secrets"]
            assert sec["mysqlRootSource"] == sec["flaskSource"] == "config", sorted(sec)
            clean(j.lines, "CfgRoot_12345", "CfgFlask_12345")
            # ...and a configured value never replaces one that is already private: before a database exists, on
            # an installed stack, and when a re-extracted archive brings the vendor's .env back (the key the sdk
            # runs on is restored -- the configured one is for a stack that has no private key yet)
            for n_, (data_, boot_) in enumerate(((False, False), (True, True))):
                stack = mk("c-config-private%d" % n_, env=env_of("Private_Root_06", "Private_Flask_06"),
                           data=data_, bootstrapped=boot_)
                before = tree()
                assert ensure_env_secrets("1.6", job(), cold=True) == {} and tree() == before, n_
            stack = mk("c-config-restore", env=env_of("Private_Root_07", "Private_Flask_07"))
            write_text(os.path.join(stack, ".env"), vendor_env)
            write_creds_record("1.6", root="Private_Root_07", pending="")
            assert ensure_env_secrets("1.6", job(), cold=True) == {"flask": "restored"}
            assert rd(".env") == env_of(VROOT, "Private_Flask_07")
            g.update({"MYSQL_ROOT_PASSWORD": "", "FLASK_SECRET_KEY": ""})
            # an INITIALISED data dir holds its own password: the root value is left to the db stage, the Flask
            # key is replaced and -- at a cold site -- the rendered config.json (what the sdk loads) follows
            stack = mk("c-data")
            j = job()
            out = ensure_env_secrets("1.6", j, cold=True)
            assert out == {"flask": "random", "sdkConfig": True}, out
            flask = env16("FLASK_SECRET_KEY")
            assert rd(".env") == env_of(VROOT, flask) and rd("docker-compose.yml") == compose_of(VROOT)
            assert rd("sdk", "data", "config.json") == sdk_of(flask) and rd("creds.txt") == creds_of(VROOT, flask, VMUIP)
            assert not os.path.exists(os.path.join(stack, CREDS_RECORD)), "nothing to note: .env names what the server has"
            assert "mysqlRootSource" not in version_state("1.6")["secrets"]
            clean(j.lines, flask)
            # cold=False (the loopback heal: the stack may be running, a full re-render follows): .env only -- no
            # rendered file is written, and the root value is not replaced there even without a database
            stack = mk("c-warm", data=False)
            assert ensure_env_secrets("1.6", job(), cold=False) == {"flask": "random"}
            assert rd(".env") == env_of(VROOT, env16("FLASK_SECRET_KEY")), "the root value is not for a warm site"
            assert rd("docker-compose.yml") == compose_of(VROOT) and rd("sdk", "data", "config.json") == sdk_of(VFLASK)
            assert not os.path.exists(os.path.join(stack, CREDS_RECORD))
            # an EMPTY mysql/ is no database either; the rendered compose file follows, so the staged `up` that
            # comes next creates MariaDB with the private password
            stack = mk("c-emptydir", data=False)
            os.makedirs(os.path.join(stack, "mysql"))
            j = job()
            out = ensure_env_secrets("1.6", j, cold=True)
            assert out == {"flask": "random", "sdkConfig": True, "mysqlRoot": "random", "compose": True}, out
            assert rd("docker-compose.yml") == compose_of(env16()) and rec() == {"root": "", "pending": env16()}
            clean(j.lines, env16(), env16("FLASK_SECRET_KEY"))
            # capture + restore: the archive is extracted over a stack whose secrets are private -- .env is the
            # vendor's again, the rendered files still name the real values. The root password of the rendered
            # compose file goes on record as PENDING (the heal's re-render is about to overwrite that line), the
            # Flask key the sdk runs on is put back into .env; nothing is "replaced", no source is recorded
            stack = mk("c-capture", env=env_of("Private_Root_02", "Private_Flask_02"))
            for cold in (False, True):
                write_text(os.path.join(stack, ".env"), vendor_env)
                write_creds_record("1.6", root="", pending="")  # (a record without a line is no record)
                j = job()
                out = ensure_env_secrets("1.6", j, cold=cold)
                assert out == {"captured": True, "flask": "restored"}, out
                assert rec() == {"root": "", "pending": "Private_Root_02"}, "captured as pending: not proven yet"
                assert rd(".env") == env_of(VROOT, "Private_Flask_02"), "the Flask key back, the root value untouched"
                assert rd("docker-compose.yml") == compose_of("Private_Root_02"), "never pushed back to the vendor value"
                assert rd("sdk", "data", "config.json") == sdk_of("Private_Flask_02")
                assert len(j.lines) == 1 and "secrets" not in version_state("1.6"), shown(j.lines)
                clean(j.lines, "Private_Root_02", "Private_Flask_02")
            write_text(os.path.join(stack, ".env"), vendor_env)
            write_creds_record("1.6", root=note("Known_Root_0001"), pending="")
            assert ensure_env_secrets("1.6", job(), cold=True) == {"flask": "restored"}
            assert rec() == {"root": "Known_Root_0001", "pending": ""}, "a record that names a password is not captured over"
            # a key to put back that .env refuses is one WARNING -- never a reason to invent another key instead
            write_text(os.path.join(stack, ".env"), vendor_env)
            failing.add(".env")
            j = job()
            assert ensure_env_secrets("1.6", j, cold=True) == {} and len(j.lines) == 1 and warned(j) == 1, shown(j.lines)
            failing.clear()
            assert rd(".env") == vendor_env and rd("sdk", "data", "config.json") == sdk_of("Private_Flask_02")
            # what the capture notes, in one place: the rendered line whenever it names ANOTHER non-vendor password
            # than .env -- the vendor's again, or a private value nobody proved (an .env edited by hand, without an
            # ALTER USER) -- and the record holds no line; nothing for the same value in both files, and nothing
            # for a stack whose .env names no root value
            write_creds_record("1.6", root="", pending="")
            assert [rendered_root_to_note("1.6", v_) for v_ in (VROOT, "Edited_Root_0002", "Private_Root_02", "")] \
                == ["Private_Root_02", "Private_Root_02", "", ""]
            # a private .env whose rendered files are behind (a kill between two writes, a root password the db
            # stage changed under a running stack): both follow at a cold site, only there, once
            stack = mk("c-follow")
            write_text(os.path.join(stack, ".env"), env_of("Private_Root_03", "Private_Flask_03"))
            before = tree()
            j = job()
            assert ensure_env_secrets("1.6", j, cold=False) == {} and j.lines == [] and tree() == before
            out = ensure_env_secrets("1.6", j, cold=True)
            assert out == {"sdkConfig": True, "compose": True}, out
            assert rd("docker-compose.yml") == compose_of("Private_Root_03")
            assert rd("sdk", "data", "config.json") == sdk_of("Private_Flask_03")
            assert rd("creds.txt") == vendor_creds and rd(".env") == before[".env"].decode(), ".env did not change"
            assert not os.path.exists(os.path.join(stack, CREDS_RECORD)), "only the SERVER's answer feeds the record"
            clean(j.lines, "Private_Root_03", "Private_Flask_03")
            before = tree()
            assert ensure_env_secrets("1.6", job(), cold=True) == {} and tree() == before
            # ...but never a hand-made root password YAML would not read back as the same string (the line is
            # unquoted: 01234567 is a number there)
            stack = mk("c-digits")
            write_text(os.path.join(stack, ".env"), env_of("01234567", "Private_Flask_04"))
            assert ensure_env_secrets("1.6", job(), cold=True) == {"sdkConfig": True}
            assert rd("docker-compose.yml") == compose_of(VROOT)
            # nothing to judge = nothing done, at both stages: no key, an empty value, no .env at all, an
            # unreadable one (even on an installed stack: no line, no SQL, no compose call, no file, no state)
            for n_, env0 in enumerate(("OUTER_IP=127.0.0.1\n",
                                       "MYSQL_ROOT_PASSWORD=\nFLASK_SECRET_KEY=\nOUTER_IP=127.0.0.1\n", None, "a folder")):
                stack = mk("c-none%d" % n_, env=None if env0 == "a folder" else env0, data=False, up=True)
                if env0 == "a folder":
                    os.makedirs(os.path.join(stack, ".env"))  # open() fails with something else than "not found"
                # (rendered without a value, the compose line keeps its %PLACEHOLDER% -- no password to capture)
                assert rendered_root_password("1.6") == ("" if n_ == 1 else "%MYSQL_ROOT_PASSWORD%"), n_
                assert rendered_root_to_note("1.6", "") == "", n_
                before = tree()
                j = job()
                for cold in (True, False):
                    assert ensure_env_secrets("1.6", j, cold=cold) == {}, (n_, cold)
                assert ensure_db_root_password("1.6", j) is False, n_
                assert j.lines == [] and sent == [] and composes == [] and tree() == before, (n_, shown(j.lines))
                assert version_state("1.6") == {} and current_secrets("1.6")["mysqlRoot"] == ""
            # a write that fails is one WARNING line and the job goes on: the record (the root step is then
            # skipped -- a random password is never put where no file remembers it), .env, the agent state
            stack = mk("c-norecord", data=False)
            failing.add(CREDS_RECORD)
            j = job()
            out = ensure_env_secrets("1.6", j, cold=True)
            assert out == {"flask": "random", "sdkConfig": True} and env16() == VROOT, out
            assert warned(j) == 1 and CREDS_RECORD in "".join(j.lines), shown(j.lines)
            assert rd("docker-compose.yml") == compose_of(VROOT) and not os.path.exists(os.path.join(stack, CREDS_RECORD))
            env16("FLASK_SECRET_KEY")
            stack = mk("c-noenv", data=False)
            failing.add(".env")
            j = job()
            assert ensure_env_secrets("1.6", j, cold=True) == {} and rd(".env") == vendor_env
            assert warned(j) == 2 and rd("creds.txt") == vendor_creds, shown(j.lines)
            assert rd("docker-compose.yml") == compose_of(VROOT), "the compose file never runs ahead of .env"
            clean(j.lines, note(rec()["pending"]))
            stack = mk("c-nostate", data=False)
            with open(g["STATE_PATH"], "wb") as f:
                f.write(b'{"versions": {"1.6": {"runni')  # torn in the middle of the job
            j = job()
            out = ensure_env_secrets("1.6", j, cold=True)
            assert out == {"flask": "random", "sdkConfig": True, "mysqlRoot": "random", "compose": True}, out
            assert warned(j) == 2 and rd(".env") == env_of(env16(), env16("FLASK_SECRET_KEY")), shown(j.lines)
            assert rec() == {"root": "", "pending": env16()}

            # (D) the db stage: MySQL is up and has just accepted .env's password -- the vendor's
            stack = mk("d-rotate", up=True)
            before = tree()
            j = job()
            assert ensure_db_root_password("1.6", j) is True
            new = env16()
            assert MYSQL_ROOT_RE.match(new) and new not in VENDOR_MYSQL_ROOT_PASSWORDS
            assert srv["local"] == srv["any"] == new, "what .env names is what both root accounts have: %s" % shown(sent)
            assert alters == [ALTER_ROOT], "ONE statement naming both accounts, sent once: %s" % shown(alters)
            assert seen == {"new": new, "login": VROOT, "env": VROOT, "pending": new, "root": ""}, \
                "WHEN the ALTER arrives the new value is on record as pending and .env still names the old one"
            assert [s_ for s_, _w in sent] == ["ok", "ok"], shown(sent)
            assert rec() == {"root": new, "pending": ""} and rd("creds.txt") == creds_of(new, VFLASK, VMUIP)
            assert rd(".env") == env_of(new) and composes == [], composes
            assert rd("docker-compose.yml") == before["docker-compose.yml"].decode(), "no rendered file is the db stage's"
            sec = version_state("1.6")["secrets"]
            assert sec["mysqlRootSource"] == "random" and sec["mysqlRootChangedAt"] and "flaskSource" not in sec, sorted(sec)
            assert len(j.lines) == 1, shown(j.lines)
            clean(j.lines, new, VROOT)
            del sent[:]
            j = job()
            assert ensure_db_root_password("1.6", j) is False and sent == [] and j.lines == [], "a private one: no SQL"
            # the ALTER is refused / changes nothing: the old password still works -> a WARNING, nothing changed
            for how in ("refused", "noop"):
                stack = mk("d-" + how, up=True)
                srv["alter"] = how
                j = job()
                assert ensure_db_root_password("1.6", j) is False
                assert rd(".env") == vendor_env and srv["local"] == srv["any"] == VROOT and composes == [], how
                assert rec() == {"root": "", "pending": note(seen["new"])}, "never `root` unproven; the target stays pending"
                assert kinds()[0] == "vendor"  # (and /status is swept WITH a pending line on record)
                assert len(j.lines) == 1 and warned(j) == 1, shown(j.lines)
                clean(j.lines, seen["new"], VROOT)
                assert rd("creds.txt") == vendor_creds and "secrets" not in version_state("1.6")
            # ...the verdict is the LOGIN, never the statement's exit code: applied, but the client reported an error
            stack = mk("d-lost", up=True)
            srv["alter"] = "lost"
            assert ensure_db_root_password("1.6", job()) is True and env16() == srv["local"] != VROOT
            assert rec() == {"root": env16(), "pending": ""}
            # neither password works: 500 -- the rest of the job must not run on a dead password
            stack = mk("d-dead", up=True)
            srv["alter"] = "dead"
            j = job()
            msg = raises(500, lambda: ensure_db_root_password("1.6", j))
            assert CREDS_RECORD in msg and "pending" in msg and rd(".env") == vendor_env, shown(msg)
            assert rec() == {"root": "", "pending": note(seen["new"])}
            clean([msg] + j.lines, seen["new"])
            # the server dies under the statement: neither probe is ANSWERED -- which proves nothing about either
            # password: 500, nothing written, and when the server is back the next wait settles it by the record
            stack = mk("d-crash", up=True)
            srv["alter"] = "crash"
            j = job()
            msg = raises(500, lambda: ensure_db_root_password("1.6", j))
            pend = note(rec()["pending"])
            assert CREDS_RECORD in msg and rd(".env") == vendor_env and pend == seen["new"] and not rec()["root"], \
                shown(msg)
            assert [s_ for s_, _w in sent] == ["lost", "down", "down"], shown(sent)
            clean([msg] + j.lines, pend)
            srv["up"] = True
            _none, waited = virtual(lambda: wait_for_mysql("1.6", job()))
            assert waited == 3 and env16() == pend == srv["local"] and rec() == {"root": pend, "pending": ""}
            # the record cannot be written: no ALTER is sent (the new value would live in memory only)
            stack = mk("d-norecord", up=True)
            failing.add(CREDS_RECORD)
            j = job()
            assert ensure_db_root_password("1.6", j) is False and sent == [] and rd(".env") == vendor_env, shown(sent)
            assert len(j.lines) == 1 and warned(j) == 1, shown(j.lines)
            # .env cannot be written: found out BEFORE anything is recorded or sent (the new password would have
            # to go there right after the ALTER) -- the vendor's simply stays: one WARNING, no pending line, no SQL
            stack = mk("d-noenv-first", up=True)
            failing.add(".env")
            j = job()
            assert ensure_db_root_password("1.6", j) is False and sent == [] and rd(".env") == vendor_env, shown(sent)
            assert len(j.lines) == 1 and warned(j) == 1 and ".env cannot be written" in j.lines[0], shown(j.lines)
            assert not os.path.exists(os.path.join(stack, CREDS_RECORD)) and no_tmp(), "nothing on record either"
            # (that proof is a rewrite of the file's own BYTES -- a BOM, quotes, CRLF and all: a stage that ends
            # right after it, here over a record that cannot be written, has changed nothing)
            stack = mk("d-probe", env="\ufeff" + vendor_env.replace("=" + VROOT, '="%s"' % VROOT).replace("\n", "\r\n"),
                       up=True)
            failing.add(CREDS_RECORD)
            before = tree()
            assert ensure_db_root_password("1.6", job()) is False and sent == [] and tree() == before, shown(sent)
            assert events[:2] == ["fsync", "replace .env"] and "replace " + CREDS_RECORD not in events, events
            # ...and an .env that stops being writable only once the ALTER has arrived: the database has the new
            # password, 500 -- and the next wait repairs .env from the pending line
            stack = mk("d-noenv", up=True)
            srv["env_dies"] = True
            msg = raises(500, lambda: ensure_db_root_password("1.6", job()))
            pend = note(rec()["pending"])
            assert pend == srv["local"] != VROOT and rd(".env") == vendor_env and "pending" in msg, shown(msg)
            clean([msg], pend)
            failing.clear()
            _none, waited = virtual(lambda: wait_for_mysql("1.6", job()))
            assert waited == 3 and env16() == pend and rec() == {"root": pend, "pending": ""}
            # the configured value; the stage is as silent as the file level on a private password
            g["MYSQL_ROOT_PASSWORD"] = "CfgRoot_12345"
            stack = mk("d-config", up=True)
            j = job()
            assert ensure_db_root_password("1.6", j) is True and env16() == "CfgRoot_12345" == srv["local"] == srv["any"]
            assert version_state("1.6")["secrets"]["mysqlRootSource"] == "config"
            assert (seen["pending"], seen["env"]) == ("CfgRoot_12345", VROOT), "on record BEFORE the statement -- a configured value too"
            clean(j.lines, "CfgRoot_12345")
            stack = mk("d-private", env=env_of("Private_Root_05"), up=True)
            before = tree()
            assert ensure_db_root_password("1.6", job()) is False and sent == [] and tree() == before
            g["MYSQL_ROOT_PASSWORD"] = ""

            # (E) recovery + learning, through the REAL wait_for_mysql on the virtual clock. The server refuses
            #     .env's password; the first candidate the SERVER accepts is written back -- asked in the order
            #     pending, record, rendered compose file, configured, vendor -- and never on the first refusal
            for name, env_root, server_root, record, compose_root, config, needle, tried in (
                    ("record", VROOT, "Private_Root_10", ("Private_Root_10", ""), None, "", "on record", 0),
                    ("pending", VROOT, "Pending_Root_11", ("", "Pending_Root_11"), None, "", "pending", 0),
                    ("stale", VROOT, "Private_Root_12", ("Private_Root_12", "Stale_Pend_0012"), None, "", "on record", 1),
                    ("compose", VROOT, "Compose_Root_13", None, "Compose_Root_13", "", "docker-compose.yml", 0),
                    ("config", VROOT, "CfgRoot_12345", None, None, "CfgRoot_12345", "GIO_MYSQL_ROOT_PASSWORD", 0),
                    ("vendor", "Private_Root_14", VROOT, ("Private_Root_14", "Stale_Pend_0014"), None, "", "vendor", None)):
                stack = mk("e-" + name, env=env_of(env_root), server_root=server_root, up=True)
                if record is not None:
                    write_creds_record("1.6", root=record[0], pending=record[1])
                if compose_root is not None:
                    write_text(os.path.join(stack, "docker-compose.yml"), compose_of(compose_root))
                g["MYSQL_ROOT_PASSWORD"] = config
                j = job()
                _none, waited = virtual(lambda: wait_for_mysql("1.6", j))
                g["MYSQL_ROOT_PASSWORD"] = ""
                assert waited == 3, "%s: acted on the 2nd refusal, never the 1st (waited %s s)" % (name, waited)
                assert rd(".env") == env_of(server_root), "%s: .env repaired, nothing else changed" % name
                assert [s_ for s_, _w in sent[:2]] == ["denied", "denied"] and sent[-2:] == [("ok", "SELECT 1")] * 2 \
                    and set(s_ for s_, _w in sent[2:-2]) <= {"denied"}, (name, shown(sent))
                assert explicit == list(range(2, len(sent) - 1)) and tried in (None, len(sent) - 4), (name, explicit)
                assert rec() == {"root": server_root, "pending": ""}, "%s: the record names what the server accepted" % name
                assert rd("creds.txt") == creds_of(server_root, VFLASK, VMUIP), name
                assert len(j.lines) == 3 and j.lines[0] == "Waiting for MySQL..." and j.lines[2] == "MySQL is ready." \
                    and needle in j.lines[1], (name, shown(j.lines))
                clean(j.lines, *(v_ for v_ in (server_root, env_root) + (record or ()) if v_ not in public))
            # ...after which the db stage runs as usual: a recovered vendor password is replaced
            assert ensure_db_root_password("1.6", job()) is True and env16() == srv["local"] not in public
            # a candidate probe that gets NO answer (the server restarting under it) is not an acceptance: nothing
            # is written for it, the next candidate is asked
            stack = mk("e-hiccup", server_root="Private_Root_17", up=True)
            write_creds_record("1.6", root="Private_Root_17", pending="Stale_Pend_0017")
            srv["hiccup"] = 1
            j = job()
            _none, waited = virtual(lambda: wait_for_mysql("1.6", j))
            assert waited == 3 and rd(".env") == env_of("Private_Root_17"), waited
            assert [s_ for s_, _w in sent] == ["denied", "denied", "failed", "ok", "ok"] and explicit == [2, 3], \
                shown(sent)
            assert rec() == {"root": "Private_Root_17", "pending": ""} and "on record" in j.lines[1], shown(j.lines)
            # one refusal alone (the image's first-run initialisation refuses everything) asks nobody anything;
            # the plain success is LEARNED: the record names the private password the server has just accepted
            stack = mk("e-transient", env=env_of("Private_Root_15"), up=True)
            write_creds_record("1.6", root="Other_Root_0015", pending="Other_Pend_0015")
            srv["deny_first"] = 1
            j = job()
            _none, waited = virtual(lambda: wait_for_mysql("1.6", j))
            assert sent == [("denied", "SELECT 1"), ("ok", "SELECT 1")] and explicit == [] and waited == 3, shown(sent)
            assert j.lines == ["Waiting for MySQL...", "MySQL is ready."], shown(j.lines)
            assert rec() == {"root": "Private_Root_15", "pending": ""}, "learned: the root replaced, the stale pending gone"
            n = len(protected)
            virtual(lambda: wait_for_mysql("1.6", job()))
            assert len(protected) == n, "nothing to learn: the record is not written again"
            stack = mk("e-vendor-ok", up=True)
            virtual(lambda: wait_for_mysql("1.6", job()))
            assert not os.path.exists(os.path.join(stack, CREDS_RECORD)), "a vendor password is never learned"
            stack = mk("e-nolearn", env=env_of("Private_Root_16"), up=True)
            failing.add(CREDS_RECORD)
            j = job()
            virtual(lambda: wait_for_mysql("1.6", j))  # a record that cannot be written never fails the wait
            assert j.lines[:2] == ["Waiting for MySQL...", "MySQL is ready."] and len(j.lines) == 3 and warned(j) == 1, \
                shown(j.lines)
            # no candidate works: the unchanged timeout error after the unchanged 300 s (100 probes), one round of
            # candidates right after the 2nd, the 6th and the 20th refusal; nothing is written
            stack = mk("e-lost", server_root="Lost_Root_000017", up=True)
            before = tree()
            j = job()
            msg = raises(500, lambda: virtual(lambda: wait_for_mysql("1.6", j)))
            assert msg == "MySQL did not come up within 300s. Last error: " + DENIED, shown(msg)
            assert len(sent) == 100 + 3 and set(sent) == {("denied", "SELECT 1")} and explicit == [2, 7, 22], explicit
            assert tree() == before and j.lines == ["Waiting for MySQL..."], shown(j.lines)
            # a server that is not up, or an error that is not "root's password is wrong" (docker's own "Access is
            # denied.", 1044, 1698, another account's 1045): no candidate is asked although the record offers one
            stack = mk("e-other", server_root="Private_Root_18")
            write_creds_record("1.6", root="Private_Root_18", pending="")
            for broken in ("", "error during connect: open //./pipe/docker_engine: Access is denied.",
                           "ERROR 1044 (42000): Access denied for user 'root'@'localhost' to database 'hk4e_db_user'",
                           "ERROR 1698 (28000): Access denied for user 'root'@'localhost'",
                           "ERROR 1045 (28000): Access denied for user 'hk4e_work'@'172.10.3.1' (using password: YES)"):
                srv.update(up=bool(broken), broken=broken)
                del sent[:]
                msg = raises(500, lambda: virtual(lambda: wait_for_mysql("1.6", job(), timeout=30)))
                assert msg.startswith("MySQL did not come up within 30s. Last error: ") \
                    and msg.endswith(broken or "(2)"), shown(msg)
                assert len(sent) == 10 and explicit == [] and rd(".env") == vendor_env, shown(sent[:3])
            # the server accepts a candidate but .env cannot be written: a WARNING per round, still only the timeout
            stack = mk("e-noenv", server_root="Private_Root_19", up=True)
            write_creds_record("1.6", root="Private_Root_19", pending="")
            failing.add(".env")
            j = job()
            msg = raises(500, lambda: virtual(lambda: wait_for_mysql("1.6", j, timeout=30)))
            assert "within 30s" in msg and rd(".env") == vendor_env and rec() == {"root": "Private_Root_19", "pending": ""}
            assert warned(j) == 2 and len(j.lines) == 3, shown(j.lines)
            clean(j.lines, "Private_Root_19")

            # (F) end to end, through the real do_start / do_provision / do_setup / do_bootstrap.
            # A prepared, stopped stack -- the vendor's values in every place -- is started:
            stack = mk("f-cold")
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and waited == 0, (res, waited, shown(j.lines))
            root, flask, muip = env16(), env16("FLASK_SECRET_KEY"), muip16()
            assert composes == [UP_DB, UP_ALL], "exactly the staged start, no `up` of the stage's own: %r" % (composes,)
            assert alters == [ALTER_ROOT] and (seen["login"], seen["env"], seen["pending"]) == (VROOT, VROOT, root)
            assert set(s_ for s_, _w in sent) == {"ok"}, "no login of the whole start was refused: %s" % shown(sent)
            assert root not in public and flask not in public and not is_vendor_muip_key(muip)
            assert srv["local"] == srv["any"] == root and rec() == {"root": root, "pending": ""}
            assert rd(".env") == env_of(root, flask) and rd("creds.txt") == creds_of(root, flask, muip)
            assert rd("sdk", "data", "config.json") == sdk_of(flask)
            assert rd("docker-compose.yml") == compose_of(VROOT), "the rendered compose file waits for the next cold start"
            assert kinds() == ("custom", "custom", "custom")
            info = secrets_info("1.6")
            assert [info[k] for k in ("mysqlRootVendorDefault", "mysqlRootSource", "flaskVendorDefault", "flaskSource")] \
                == [False, "random", False, "random"] and (info["mysqlRoot"], info["flask"]) == (root, flask)
            clean(j.lines, root, flask, muip)
            # ...stopped and started again: the compose file follows .env, still exactly the two calls, no SQL
            # but the logins of an ordinary start; a third start finds nothing left to do
            for again in (1, 2):
                docker(stack, ("down",))
                del composes[:], sent[:], alters[:]
                before = tree()
                res, waited = virtual(lambda: do_start("1.6", job(), provision="none"))
                assert res == READY and waited == 0 and composes == [UP_DB, UP_ALL] and alters == [], (again, composes)
                assert set(s_ for s_, _w in sent) == {"ok"} and rd("docker-compose.yml") == compose_of(root), shown(sent)
                assert again == 1 or tree() == before, "a third start changes no file"
            # a RUNNING stack on the vendor's values (the agent was installed under it): the root password is
            # replaced all the same -- no service logs in as root -- and no file a running service reads changes
            stack = mk("f-running", up=True)
            before = tree()
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            root = env16()
            assert res == READY and waited == 0 and composes == [UP_DB, UP_ALL], (res, composes)
            assert root not in VENDOR_MYSQL_ROOT_PASSWORDS and srv["local"] == srv["any"] == root, \
                "the db stage runs on a stack that was already up"
            assert alters == [ALTER_ROOT] and (seen["env"], seen["pending"]) == (VROOT, root)
            assert rd(".env") == env_of(root) and rec() == {"root": root, "pending": ""}
            assert all(tree()[k] == before[k] for k in before if k not in (".env", "creds.txt")), "only .env + creds.txt"
            assert kinds() == ("custom", "vendor", "vendor")
            info = secrets_info("1.6")
            assert (info["mysqlRootVendorDefault"], info["flaskVendorDefault"], info["flaskSource"]) == (False, True, None)
            clean(j.lines, root)
            # THE scenario the record exists for: Prepare server, stop, the archive extracted over the stack again
            # (.env, creds.txt and the MUIP template are the vendor's; mysql/ and the rendered files keep the
            # private values), Start. Nothing may be lost: the database's password is found again -- the creds.txt
            # rewrites that run BEFORE MySQL is up must not have replaced it on record -- and the sdk keeps its key
            stack = mk("f-reextract")
            virtual(lambda: do_provision("1.6", job(), progress="keep"))
            private, pflask = env16(), env16("FLASK_SECRET_KEY")
            muip16()
            assert private not in VENDOR_MYSQL_ROOT_PASSWORDS and srv["local"] == private and rec()["root"] == private
            assert rd("docker-compose.yml") == compose_of(VROOT), "(the rendered compose file cannot help: not synced yet)"
            docker(stack, ("down",))
            reextract()
            del composes[:], sent[:], alters[:], explicit[:]
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and waited == 3, "the password was found at the 2nd refusal: %r" % ((res, waited),)
            assert rd(".env") == env_of(private, pflask) and srv["local"] == srv["any"] == private
            assert rec() == {"root": private, "pending": ""} and rd("creds.txt") == creds_of(private, pflask, muip16())
            assert not is_vendor_muip_key(muip16()) and composes == [UP_DB, UP_ALL] and alters == [], (composes, alters)
            assert [s_ for s_, _w in sent[:4]] == ["denied", "denied", "ok", "ok"] and explicit == [2] \
                and set(s_ for s_, _w in sent[4:]) == {"ok"}, shown(sent)
            assert kinds() == ("custom", "custom", "custom")
            clean(j.lines, private, pflask)
            # the same over a stack that keeps RUNNING: the root password is found again at once, the Flask key --
            # the sdk runs on its own -- comes back into .env at the next start of the stopped stack
            stack = mk("f-reextract-up")
            virtual(lambda: do_provision("1.6", job(), progress="fixes"))
            private, pflask = env16(), env16("FLASK_SECRET_KEY")
            muip16()
            reextract()
            del alters[:]
            res, waited = virtual(lambda: do_start("1.6", job(), provision="none"))
            assert res == READY and waited == 3 and rd(".env") == env_of(private) and alters == [], (res, waited)
            assert kinds() == ("custom", "custom", "vendor"), "the Flask key is judged where the sdk loads it"
            docker(stack, ("down",))
            virtual(lambda: do_start("1.6", job(), provision="none"))
            assert rd(".env") == env_of(private, pflask) and kinds() == ("custom", "custom", "custom")
            muip16()
            # ...and through Prepare server's loopback heal on a stack that has NO record:
            # the root password is captured from the rendered compose file before the heal's
            # re-render replaces that line with .env's vendor value
            stack = mk("f-heal", env=env_of("Private_Root_20", "Private_Flask_20"), up=True)
            reextract()
            g.update({"ADVERTISED_IP": "198.51.100.9",
                      "ensure_bind_ip": lambda v_, _j: write_env_value(v_, "OUTER_IP", "192.0.2.10")})
            j = job()
            try:
                res, waited = virtual(lambda: do_setup("1.6", j))
            finally:
                g.update({"ADVERTISED_IP": "", "ensure_bind_ip": saved["ensure_bind_ip"]})
            assert res["provisioned"] and waited == 3 and alters == [], (res, waited)
            assert rd(".env") == env_of("Private_Root_20", "Private_Flask_20").replace("OUTER_IP=127.0.0.1",
                                                                                       "OUTER_IP=192.0.2.10")
            assert srv["local"] == srv["any"] == "Private_Root_20"
            assert rec() == {"root": "Private_Root_20", "pending": ""}
            assert rd("docker-compose.yml") == compose_of(VROOT, "192.0.2.10"), "(re-rendered; it follows at a cold start)"
            muip16()
            clean(j.lines, "Private_Root_20", "Private_Flask_20")
            # ...and at a cold start, for an .env somebody edited by hand (a private value, no ALTER USER; on a
            # stack that has no record nothing proves either value): the rendered compose file is the LAST place
            # that names the database's password, and this very start makes that line follow .env. It goes on
            # record first, the wait finds it there at the 2nd refusal -- and the line follows at the next cold start
            stack = mk("f-handedit", env=env_of("Private_Root_21", "Private_Flask_21"))
            write_text(os.path.join(stack, ".env"), env_of("Edited_Root_0021", "Private_Flask_21"))
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and waited == 3, "the password was found at the 2nd refusal: %r" % ((res, waited),)
            assert rd(".env") == env_of("Private_Root_21", "Private_Flask_21") and srv["local"] == "Private_Root_21"
            assert rec() == {"root": "Private_Root_21", "pending": ""} and alters == [] and explicit == [2], explicit
            assert composes == [UP_DB, UP_ALL] and rd("docker-compose.yml") == compose_of("Edited_Root_0021"), composes
            assert rd("creds.txt") == creds_of("Private_Root_21", "Private_Flask_21", muip16())
            assert len([l for l in j.lines if "recorded as pending in " + CREDS_RECORD in l]) == 1, shown(j.lines)
            clean(j.lines, "Private_Root_21", "Edited_Root_0021", "Private_Flask_21")
            docker(stack, ("down",))
            res, waited = virtual(lambda: do_start("1.6", job(), provision="none"))
            assert res == READY and waited == 0 and rd("docker-compose.yml") == compose_of("Private_Root_21"), (res, waited)
            # Prepare server with the default save: the password is replaced BEFORE the import (it logs in with
            # .env's value) and no login of the job is refused
            write_text(os.path.join(td, "payloads", "1.6", "save.sql"), "-- dump\n")
            g["read_manifest"] = lambda _v: {"files": [],
                                             "mysql": [{"src": "save.sql", "db": "hk4e_db_user", "recreate": True}]}
            stack = mk("f-provision")
            j = job()
            res, waited = virtual(lambda: do_provision("1.6", j, progress="default"))
            heads = [w for _s, w in sent]
            assert res["provisioned"] and waited == 0 and env16() == srv["local"] == srv["any"] not in public, res
            assert composes == [DOWN, UP_DB, UP_ALL] and alters == [ALTER_ROOT], (composes, alters)
            assert heads.index("-- import hk4e_db_user") > heads.index(ALTER_ROOT.split(" IDENTIFIED")[0]), heads
            assert set(s_ for s_, _w in sent) == {"ok"}, shown(sent)
            clean(j.lines, env16(), env16("FLASK_SECRET_KEY"), muip16())
            g["read_manifest"] = saved["read_manifest"]
            # a FRESH install (Prepare server on a just-extracted stack), the Windows steps and the Linux script:
            # both values are private before anything is rendered, MariaDB is CREATED with the private password
            # (no ALTER), and the first wait proves it -- the record's pending line becomes its root line. On
            # Windows the agent itself waits through the image's first-run initialisation, which refuses EVERY
            # password for a while: the candidates asked meanwhile (a record left by an earlier life of the
            # folder, the vendor literals) are refused too, nothing is written, .env's own value works a moment later
            for win in (True, False):
                g["IS_WINDOWS"] = win
                stack = mk("f-fresh%d" % win, data=False, bootstrapped=False)
                if win:
                    srv["init_window"] = 7
                    write_creds_record("1.6", root="Earlier_Life_001", pending="")
                j = job()
                res, waited = virtual(lambda: do_setup("1.6", j))
                root, flask, muip = env16(), env16("FLASK_SECRET_KEY"), muip16()
                assert res["provisioned"] and srv["inits"] == 1 and alters == [], (win, res, alters)
                assert srv["local"] == srv["any"] == root and root not in public and flask not in public, win
                assert waited == (12 if win else 0) and explicit == ([2, 3, 4] if win else []), (win, waited, explicit)
                assert set(s_ for s_, _w in sent[7 if win else 0:]) == {"ok"}, (win, shown(sent))
                assert rd(".env") == env_of(root, flask) and rd("docker-compose.yml") == compose_of(root), win
                assert rd("sdk", "data", "config.json") == sdk_of(flask), win
                assert rec() == {"root": root, "pending": ""} and rd("creds.txt") == creds_of(root, flask, muip), win
                sec = version_state("1.6")["secrets"]
                assert sec["mysqlRootSource"] == sec["flaskSource"] == sec["muipSource"] == "random", (win, sorted(sec))
                clean(j.lines, root, flask, muip)
            # a FORCED reinstall over an existing database: the root password is NOT replaced at file level
            # (nothing guarantees the vendor script wipes mysql/ -- `sudo rm -rf`, no `set -e`), the db stage
            # replaces it once MySQL answers -- whether the folder was wiped (Windows) or not (Linux, no sudo)
            for win, sudo in ((True, True), (False, False)):
                g["IS_WINDOWS"] = win
                stack = mk("f-force%d" % win)
                srv["sudo"] = sudo
                mode, waited = virtual(lambda: do_bootstrap("1.6", job(), force=True))
                assert mode == "fresh" and waited == 0 and srv["inits"] == (1 if sudo else 0), (win, srv["inits"])
                assert env16() == VROOT == srv["local"] and env16("FLASK_SECRET_KEY") not in VENDOR_FLASK_KEYS, \
                    "a vendor root password over an existing database is the db stage's (windows: %s)" % win
                res, waited = virtual(lambda: do_provision("1.6", job(), fresh=True))
                assert waited == 0 and alters == [ALTER_ROOT] and env16() == srv["local"] == srv["any"] not in public, win
                assert rec() == {"root": env16(), "pending": ""}
                muip16()
            g["IS_WINDOWS"] = saved["IS_WINDOWS"]
            # the agent dies right after the server applied the ALTER: .env still names the old password, the
            # record's pending line is the only place that names the new one -- and the next Start (mysql + redis
            # were left running) finds it there
            stack = mk("f-killed")
            srv["alter"] = "kill"
            try:
                virtual(lambda: do_start("1.6", job(), provision="none"))
                raise AssertionError("the kill did not happen")
            except _Killed:
                pass
            pend = note(rec()["pending"])
            assert pend and pend == srv["local"] and rd(".env") == env_of(VROOT, env16("FLASK_SECRET_KEY")) \
                and rec()["root"] == "", "the new password is pending on disk, .env still names the old one"
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and waited == 3 and env16() == pend == srv["local"] and len(alters) == 1, (res, waited)
            assert rec() == {"root": pend, "pending": ""} \
                and rd("creds.txt") == creds_of(pend, env16("FLASK_SECRET_KEY"), muip16())
            clean(j.lines, pend)
            # MySQL never answers .env's password and no candidate works: the start goes on all the same (the
            # remaining services anyway, eventsApplied False) -- the db stage needs a server that ANSWERED: no
            # pending line, no statement
            stack = mk("f-unverified", server_root="Unknown_Root_0099")
            res, waited = virtual(lambda: do_start("1.6", job(), provision="none"))
            assert res == dict(READY, eventsApplied=False) and waited == 300, (res, waited)
            assert alters == [] and composes == [UP_DB, UP_ALL] and rec() == {"root": "", "pending": ""}, composes
            assert env16() == VROOT and version_state("1.6")["runningOk"] is True
            env16("FLASK_SECRET_KEY"), muip16()
            # the db stage's 500 ends a start before the full `up`
            stack = mk("f-dead")
            srv["alter"] = "dead"
            raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
            assert composes == [UP_DB] and version_state("1.6")["runningOk"] is False, composes
            env16("FLASK_SECRET_KEY"), muip16()

            # (G) the admin rotation (POST /server/secrets). Root + Flask + internal in ONE run, on a stopped and
            #     on a running stack: one statement for the four accounts (sent one login per statement, the old
            #     root password is refused right after 'root'@'localhost' changed), the new root on record as
            #     pending when it arrives, the sources `admin`
            for up in (False, True):
                stack = mk("g-all%d" % up, env=env_of("Private_Root_30", "Private_Flask_30"), up=up)
                version_state_set("1.6", runningOk=up)
                j = job()
                res, waited = virtual(lambda: do_secrets("1.6", j, {
                    "mysqlRoot": "AdminRoot_12345", "flask": "AdminFlask_1234", "internal": "AdminInternal_12"}))
                assert sorted(res["changed"]) == ["flask", "internal", "mysqlRoot"] and waited == 0, (up, res)
                assert alters == [ALTER_ROOT + ", " + ALTER_GAME], "ONE statement, sent once: %s" % shown(alters)
                assert set(s_ for s_, _w in sent) == {"ok"}, (up, shown(sent))
                assert srv["local"] == srv["any"] == "AdminRoot_12345" \
                    and srv["game"] == {"hk4e_work": "AdminInternal_12", "hk4e_readonly": "AdminInternal_12"}, up
                assert seen == {"new": "AdminRoot_12345", "login": "Private_Root_30", "env": "Private_Root_30",
                                "pending": "AdminRoot_12345", "root": "Private_Root_30"}, "pending BEFORE the ALTER"
                assert rec() == {"root": "AdminRoot_12345", "pending": ""}
                assert rd(".env") == env_of("AdminRoot_12345", "AdminFlask_1234")
                assert rd("creds.txt") == creds_of("AdminRoot_12345", "AdminFlask_1234", VMUIP, "AdminInternal_12")
                assert rd("docker-compose.yml") == compose_of("AdminRoot_12345", internal="AdminInternal_12")
                assert rd("sdk", "data", "config.json") == sdk_of("AdminFlask_1234")
                vs = version_state("1.6")
                sec = vs["secrets"]
                assert sec["mysqlRootSource"] == sec["flaskSource"] == "admin" and "muipSource" not in sec \
                    and sec["mysqlRootChangedAt"] == sec["flaskChangedAt"] == sec["changedAt"], (up, sorted(sec))
                assert vs.get("secretsPending") is None and vs["runningOk"] is up and srv["up"] is up, (up, sorted(vs))
                assert composes == ([DOWN, UP_DB, UP_ALL] if up else [UP_DB, DOWN]), (up, composes)
                assert [l for l in j.lines if l.startswith("  ok: ")] == [
                    "  ok: ALTER USER 'root'@'%'", "  ok: ALTER USER 'root'@'localhost'",
                    "  ok: ALTER USER 'hk4e_work'@'172.10.%'", "  ok: ALTER USER 'hk4e_readonly'@'172.10.%'"], shown(j.lines)
                clean(j.lines, "AdminRoot_12345", "AdminFlask_1234", "AdminInternal_12", "Private_Root_30",
                      "Private_Flask_30")
            # the rule of mysqlRoot (the compose line is unquoted YAML): a letter first -- 400 before anything is
            # touched, never quoting the value; the Flask key keeps the general rule
            stack = mk("g-rule", env=env_of("Private_Root_31"), up=True)
            msg = raises(400, lambda: do_secrets("1.6", job(), {"mysqlRoot": "9DigitFirst_123"}))
            assert "starting with a letter" in msg and "9DigitFirst" not in msg, shown(msg)
            raises(400, lambda: do_secrets("1.6", job(), {"mysqlRoot": "Trailing_Newline1\n"}))
            assert "starting with" not in raises(400, lambda: do_secrets("1.6", job(), {"flask": "short"}))
            assert sent == [] and composes == [] and version_state("1.6") == {}
            res, _w = virtual(lambda: do_secrets("1.6", job(), {"flask": "9DigitFirst_123"}))
            assert res == {"changed": ["flask"]} and alters == [] and env16("FLASK_SECRET_KEY") == "9DigitFirst_123"
            # the statement is refused and the old password still works: 500 "nothing was changed", the markers
            # taken back (a running stack stays tended, a stopped one is stopped again) -- no value in the error
            for up in (True, False):
                stack = mk("g-refused%d" % up, env=env_of("Private_Root_32"), up=up)
                version_state_set("1.6", runningOk=up)
                srv["alter"] = "refused"
                j = job()
                msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", j, {"mysqlRoot": "AdminRoot_32222",
                                                                               "internal": "AdminInternal_32"})))
                assert "nothing was changed" in msg and rd(".env") == env_of("Private_Root_32"), shown(msg)
                assert srv["local"] == srv["any"] == "Private_Root_32" and srv["game"]["hk4e_work"] == VINT
                vs = version_state("1.6")
                assert vs.get("secretsPending") is None and vs["runningOk"] is up and srv["up"] is up, (up, sorted(vs))
                assert rec()["root"] in ("", "Private_Root_32"), "never the unproven target as `root`"
                clean([msg] + j.lines, "AdminRoot_32222", "AdminInternal_32", "Private_Root_32")
            # the pending line cannot be written: 500 before anything is altered, the markers taken back
            stack = mk("g-norecord", env=env_of("Private_Root_33"), up=True)
            version_state_set("1.6", runningOk=True)
            virtual(lambda: wait_for_mysql("1.6", job()))  # (the record learns the current password first)
            failing.add(CREDS_RECORD)
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"mysqlRoot": note("AdminRoot_33333")})))
            failing.clear()
            assert alters == [] and rd(".env") == env_of("Private_Root_33") and srv["local"] == "Private_Root_33"
            assert version_state("1.6").get("secretsPending") is None and version_state("1.6")["runningOk"] is True
            assert rec() == {"root": "Private_Root_33", "pending": ""} and CREDS_RECORD in msg, shown(msg)
            # ...nor can .env take the new password (asked first, before the pending line): 500 "nothing was
            # changed" -- nothing altered, nothing on record for the target, the markers taken back
            stack = mk("g-noenv", env=env_of("Private_Root_45"), up=True)
            version_state_set("1.6", runningOk=True)
            failing.add(".env")
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"mysqlRoot": note("AdminRoot_45555")})))
            failing.clear()
            assert msg.startswith(".env cannot be written") and "nothing was changed" in msg and alters == [], shown(msg)
            assert rd(".env") == env_of("Private_Root_45") and srv["local"] == srv["any"] == "Private_Root_45"
            assert version_state("1.6").get("secretsPending") is None and version_state("1.6")["runningOk"] is True
            assert rec() == {"root": "Private_Root_45", "pending": ""} and composes == [] and no_tmp(), composes
            # neither password works afterwards: 500 naming the record; .env keeps the old value, the target stays
            # on record as pending -- what the next Start tries
            stack = mk("g-dead", env=env_of("Private_Root_34"), up=True)
            srv["alter"] = "dead"
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"mysqlRoot": "AdminRoot_34444"})))
            assert CREDS_RECORD in msg and "pending" in msg and rd(".env") == env_of("Private_Root_34"), shown(msg)
            assert rec()["pending"] == "AdminRoot_34444" and rec()["root"] != "AdminRoot_34444"
            vs = version_state("1.6")
            assert vs["secretsPending"]["stage"] == "start" and vs["runningOk"] is False, sorted(vs)
            clean([msg], "AdminRoot_34444", "Private_Root_34")
            assert kinds()[0] == "custom"
            # ...and the statement was applied although its client reported an error: here too the login decides
            stack = mk("g-lost", env=env_of("Private_Root_29"), up=True)
            srv["alter"] = "lost"
            res, _w = virtual(lambda: do_secrets("1.6", job(), {"mysqlRoot": "AdminRoot_29999",
                                                                "internal": "AdminInternal_29"}))
            assert sorted(res["changed"]) == ["internal", "mysqlRoot"] and alters[0] == ALTER_ROOT + ", " + ALTER_GAME, res
            assert srv["local"] == srv["any"] == "AdminRoot_29999" and set(srv["game"].values()) == {"AdminInternal_29"}
            assert rd(".env") == env_of("AdminRoot_29999") and rec() == {"root": "AdminRoot_29999", "pending": ""}
            assert "denied" not in [s_ for s_, _w in sent] and version_state("1.6").get("secretsPending") is None, \
                shown(sent)
            # ...or failed HALF WAY (the root accounts altered, the game accounts not): the game accounts are sent
            # again, logged in with the NEW root password -- else the files would name an internal password the
            # database never got and no game service could log in after the restart
            stack = mk("g-partial", env=env_of("Private_Root_28"), up=True)
            srv["alter"] = "partial"
            res, _w = virtual(lambda: do_secrets("1.6", job(), {"mysqlRoot": "AdminRoot_28888",
                                                                "internal": "AdminInternal_28"}))
            assert sorted(res["changed"]) == ["internal", "mysqlRoot"], res
            assert alters == [ALTER_ROOT + ", " + ALTER_GAME, "ALTER USER IF EXISTS " + ALTER_GAME], shown(alters)
            assert srv["local"] == srv["any"] == "AdminRoot_28888" and set(srv["game"].values()) == {"AdminInternal_28"}
            # (the wait, the layout check of the game accounts -- before anything is sent --, the statement, ...)
            assert [s_ for s_, _w in sent[:5]] == ["ok", "ok", "partial", "ok", "ok"] \
                and sent[1][1].startswith("SELECT User, Host FROM mysql.user"), shown(sent)
            # only the internal password: no root account in the statement, its exit code decides, no pending line
            stack = mk("g-internal", env=env_of("Private_Root_35"), up=True)
            res, _w = virtual(lambda: do_secrets("1.6", job(), {"internal": "AdminInternal_35"}))
            assert res == {"changed": ["internal"]} and alters[:1] == ["ALTER USER IF EXISTS " + ALTER_GAME], shown(alters)
            assert srv["game"] == {"hk4e_work": "AdminInternal_35", "hk4e_readonly": "AdminInternal_35"}
            assert srv["local"] == "Private_Root_35" and rec() == {"root": "Private_Root_35", "pending": ""}
            stack = mk("g-internal-refused", env=env_of("Private_Root_36"), up=True)
            srv["alter"] = "refused"
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"internal": "AdminInternal_36"})))
            assert msg.startswith("ALTER USER failed") and srv["game"]["hk4e_work"] == VINT, shown(msg)
            clean([msg], "AdminInternal_36", "Private_Root_36")
            # a recovery INSIDE its wait (the archive was extracted over a running stack: .env names the vendor's
            # password, the database a private one): the statement goes out with the password the wait put back --
            # never the stale one read before it --, creds.txt gets it, and a request for that very value is
            # "nothing to do" with the markers taken back
            stack = mk("g-recover", server_root="Private_Root_37", up=True)
            write_creds_record("1.6", root="Private_Root_37", pending="")
            res, waited = virtual(lambda: do_secrets("1.6", job(), {"internal": "AdminInternal_37"}))
            assert res == {"changed": ["internal"]} and waited == 3 and seen["login"] == "Private_Root_37", (res, waited)
            assert rd(".env") == env_of("Private_Root_37") \
                and rd("creds.txt") == creds_of("Private_Root_37", VFLASK, VMUIP, "AdminInternal_37")
            stack = mk("g-recover-same", server_root="Private_Root_38", up=True)
            write_creds_record("1.6", root="Private_Root_38", pending="")
            version_state_set("1.6", runningOk=True)
            res, waited = virtual(lambda: do_secrets("1.6", job(), {"mysqlRoot": "Private_Root_38"}))
            assert res == {"changed": []} and waited == 3 and alters == [] and rd(".env") == env_of("Private_Root_38")
            assert composes == [], "nothing to do is no reason to restart a running server: %r" % (composes,)
            assert version_state("1.6").get("secretsPending") is None and version_state("1.6")["runningOk"] is True
            # ...a run that ends before anything could be altered (MySQL accepts no password this agent knows; mysql
            # cannot even be started) takes its markers back too, and leaves no pending line: nothing was sent
            stack = mk("g-timeout", env=env_of("Private_Root_39"), server_root="Unknown_Root_0039", up=True)
            version_state_set("1.6", runningOk=True)
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"mysqlRoot": note("AdminRoot_39999")})))
            assert msg.startswith("MySQL did not come up within 300s") and alters == [] and composes == [], shown(msg)
            assert version_state("1.6").get("secretsPending") is None and version_state("1.6")["runningOk"] is True
            assert rec() == {"root": "", "pending": ""} and rd(".env") == env_of("Private_Root_39")
            stack = mk("g-nostart", env=env_of("Private_Root_40"))
            compose_rc[UP_DB] = 1
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"internal": note("AdminInternal_40")})))
            assert msg.startswith("Could not start mysql") and composes == [UP_DB] and sent == [], (shown(msg), composes)
            assert version_state("1.6").get("secretsPending") is None and rd(".env") == env_of("Private_Root_40")
            # a Flask-only rotation waits for no MySQL before it re-renders the configs. Over a re-extracted
            # archive on a stack that has no record yet, the compose file's line is the LAST place that names the
            # database's root password: it goes on record before the re-render replaces it (as at the loopback
            # heal), and the restart's wait -- or the next Start of a stopped stack -- finds it there
            for up in (True, False):
                stack = mk("g-rerender%d" % up, env=env_of("Private_Root_42", "Private_Flask_42"), up=up)
                version_state_set("1.6", runningOk=up)
                reextract()
                res, waited = virtual(lambda: do_secrets("1.6", job(), {"flask": "AdminFlask_4200"}))
                assert res == {"changed": ["flask"]} and waited == (3 if up else 0) and alters == [], (up, res, waited)
                assert rd("docker-compose.yml") == compose_of(VROOT), "(re-rendered from .env: the line is gone)"
                if not up:
                    assert rec() == {"root": "", "pending": "Private_Root_42"} and env16() == VROOT, "noted first"
                    res, waited = virtual(lambda: do_start("1.6", job(), provision="none"))
                    assert res == READY and waited == 3, (res, waited)
                assert rd(".env") == env_of("Private_Root_42", "AdminFlask_4200") and srv["local"] == "Private_Root_42", up
                assert rec() == {"root": "Private_Root_42", "pending": ""} and srv["up"], up
                muip16()
            # a rotation that does NOT name the Flask key must not hand the sdk the vendor's either: Prepare server,
            # the archive extracted over the running stack (.env carries the published key again, the rendered sdk
            # config still the stack's own), then the internal password is rotated -- the stack's key is put back
            # into .env BEFORE the re-render, exactly as the loopback heal does (a restore: a vendor key the sdk
            # really runs on is never replaced by a rotation -- g-lost, g-recover). With `flask` in the run the
            # requested key wins and nothing is put back.
            # The MUIP sign key the same way: muipserver.xml.tmpl carries the published key again while the
            # rendered muipserver.xml still names the stack's own -- back into the template BEFORE the re-render,
            # or muipserver would come back up on a key anyone can sign GM commands with. A restore too: one line
            # without the key, no new chooser, no new date
            MUIP_FILES = [os.path.join("server", "muipserver", "conf", n_) for n_ in ("muipserver.xml.tmpl",
                                                                                      "muipserver.xml")]
            LINE_FLASK_BACK = ("Flask secret key: .env carried the vendor's published key again (a re-extracted "
                               "archive) -- the key this stack's sdk/data/config.json names was put back.")
            LINE_MUIP_BACK = ("MUIP sign key: muipserver.xml.tmpl carried the vendor's published key again (a "
                              "re-extracted archive) -- the key this stack's muipserver.xml names was put back.")

            def muip_keys():
                """(the sign key muipserver.xml.tmpl names, the one the rendered muipserver.xml names)."""
                return tuple(note(_read_sign_key_file(os.path.join(here[0], rel))) for rel in MUIP_FILES)

            def muip_sec():
                """Who chose the sign key, and when, as the state records it."""
                sec_ = version_state("1.6").get("secrets") or {}
                return {k_: v_ for k_, v_ in sec_.items() if k_.startswith("muip")}

            for knobs in ({"internal": "AdminInternal_46"}, {"internal": "AdminInternal_47", "flask": "AdminFlask_4700"}):
                stack = mk("g-reextract%d" % len(knobs))
                virtual(lambda: do_provision("1.6", job(), progress="keep"))
                private, pflask, pmuip = env16(), env16("FLASK_SECRET_KEY"), muip16()
                chosen = muip_sec()
                assert pflask not in VENDOR_FLASK_KEYS and rd("sdk", "data", "config.json") == sdk_of(pflask)
                assert not is_vendor_muip_key(pmuip) and muip_keys() == (pmuip, pmuip) \
                    and chosen["muipSource"] == "random", sorted(chosen)
                reextract()
                assert muip_keys() == (VMUIP, pmuip)
                j = job()
                res, waited = virtual(lambda: do_secrets("1.6", j, knobs))
                want = knobs.get("flask", pflask)
                assert sorted(res["changed"]) == sorted(knobs) and waited == 3, (res, waited)
                assert rd(".env") == env_of(private, want) and rd("sdk", "data", "config.json") == sdk_of(want), \
                    "the sdk keeps a private key: its own, or the one the admin asked for"
                assert muip_keys() == (pmuip, pmuip), "muipserver keeps the stack's own sign key through the re-render"
                assert rd("creds.txt") == creds_of(private, want, pmuip, knobs["internal"])
                assert [l for l in j.lines if "was put back" in l] \
                    == ([] if "flask" in knobs else [LINE_FLASK_BACK]) + [LINE_MUIP_BACK], shown(j.lines)
                assert muip_sec() == chosen, "a restore names no new chooser: %s" % sorted(muip_sec())
                assert kinds() == ("custom", "custom", "custom") and srv["up"] \
                    and version_state("1.6")["runningOk"] is True
                clean(j.lines, private, pflask, pmuip, *knobs.values())
            # ...with `muip` in the run the requested key wins and nothing is put back; and a key that really is
            # the vendor's -- in the template AND where muipserver loads it -- is not replaced by a rotation
            # nobody asked that of
            stack = mk("g-reextract-muip")
            virtual(lambda: do_provision("1.6", job(), progress="keep"))
            pmuip = muip16()
            reextract()
            j = job()
            res, waited = virtual(lambda: do_secrets("1.6", j, {"muip": "AdminMuip_480000"}))
            assert res == {"changed": ["muip"]} and muip_keys() == ("AdminMuip_480000", "AdminMuip_480000"), res
            assert LINE_MUIP_BACK not in j.lines and muip_sec()["muipSource"] == "admin", shown(j.lines)
            clean(j.lines, pmuip, "AdminMuip_480000")
            stack = mk("g-muip-vendor")
            j = job()
            res, waited = virtual(lambda: do_secrets("1.6", j, {"flask": "AdminFlask_4900"}))
            assert res == {"changed": ["flask"]} and muip_keys() == (VMUIP, VMUIP) and muip_sec() == {} \
                and not [l for l in j.lines if "MUIP" in l], shown(j.lines)
            # the restore alone. Nothing to put back = nothing done, silently: no template (nothing renders
            # muipserver.xml), a private key in the template, a rendered file that names the vendor's key, none,
            # or one outside the rule
            stack = mk("g-muip-restore")
            tmpl_m, xml_m = (os.path.join(stack, rel) for rel in MUIP_FILES)
            for tmpl_key, xml_key in ((VMUIP, VMUIP), (VMUIP, ""), (VMUIP, "has space 12345"),
                                      ("Private_Muip_Tmpl001", "Private_Muip_Xml0001"), (None, "Private_Muip_Xml0002")):
                if tmpl_key is None:
                    os.remove(tmpl_m)
                else:
                    write_text(tmpl_m, muip_tmpl.replace(VMUIP, note(tmpl_key)))
                write_text(xml_m, muip_tmpl.replace(VMUIP, note(xml_key)))
                before = tree()
                j = job()
                assert restore_muip_key("1.6", j) == "" and j.lines == [] and tree() == before, \
                    shown(tmpl_key, xml_key, j.lines)
            # ...a template that names NO key takes the stack's own as well; one that cannot take it -- no
            # sign_key to set, a write that fails -- is ONE WARNING (never the key), the file as it was
            write_text(tmpl_m, muip_tmpl.replace(VMUIP, ""))
            j = job()
            assert restore_muip_key("1.6", j) == "Private_Muip_Xml0002" \
                and muip_keys() == ("Private_Muip_Xml0002", "Private_Muip_Xml0002") \
                and j.lines == ["MUIP sign key: muipserver.xml.tmpl named no key -- the key this stack's "
                                "muipserver.xml names was put back."], shown(j.lines)
            for tmpl_text, holds, why in (
                    ("<Root>\n  <ApiConf />\n</Root>\n", "no key", "it holds no sign_key this agent can set"),
                    (muip_tmpl, "the vendor's published key", "it could not be rewritten (")):
                write_text(tmpl_m, tmpl_text)
                if holds != "no key":
                    failing.add("muipserver.xml.tmpl")
                j = job()
                assert restore_muip_key("1.6", j) is None and rd(MUIP_FILES[0]) == tmpl_text, shown(j.lines)
                failing.clear()
                assert len(j.lines) == 1 and j.lines[0].startswith(
                    "WARNING: the MUIP sign key this stack runs on was NOT put back into muipserver.xml.tmpl -- "
                    + why) and j.lines[0].endswith(
                    " The re-render replaces it with what the template holds (%s)." % holds), shown(j.lines)
                clean(j.lines, "Private_Muip_Xml0002")
                _remove_quiet(tmpl_m + ".tmp")  # (what the refused replace left behind)
            # a Flask-only rotation of a STOPPED stack asks no server anything: it must not put .env's root
            # password on record either
            stack = mk("g-flask-stopped", env=env_of("Private_Root_44", "Private_Flask_44"))
            res, waited = virtual(lambda: do_secrets("1.6", job(), {"flask": "AdminFlask_4400"}))
            assert res == {"changed": ["flask"]} and sent == [] and composes == [], (res, composes)
            assert not os.path.exists(os.path.join(stack, CREDS_RECORD)) and env16("FLASK_SECRET_KEY") == "AdminFlask_4400"
            # a stack that is not bootstrapped yet: files only -- and the new root password is PENDING on record
            stack = mk("g-nobootstrap", data=False, bootstrapped=False)
            res = do_secrets("1.6", job(), {"mysqlRoot": "AdminRoot_40000", "flask": "AdminFlask_40000"})
            assert sorted(res["changed"]) == ["flask", "mysqlRoot"] and sent == [] and composes == []
            assert rec() == {"root": "", "pending": "AdminRoot_40000"} \
                and rd(".env") == env_of("AdminRoot_40000", "AdminFlask_40000")
            sec = version_state("1.6")["secrets"]
            assert sec["mysqlRootSource"] == sec["flaskSource"] == "admin", sorted(sec)

            # (H) reporting: "vendor" | "custom" | null in /status (never public, never a value), the four fields of
            #     GET /server/secrets, an unreadable .env = unknown -- not a 500 of /status
            stack = mk("h-report")
            assert kinds() == ("vendor", "vendor", "vendor")
            info = secrets_info("1.6")
            assert [info[k] for k in ("mysqlRootVendorDefault", "mysqlRootSource", "flaskVendorDefault", "flaskSource")] \
                == [True, None, True, None]
            full = g["status"]()
            assert (full["versions"]["2.8"]["mysqlPassword"], full["versions"]["2.8"]["flaskKey"]) == (None, None)
            pub = build_public_status(full, default_policy())
            assert not {"mysqlPassword", "flaskKey", "muipKey"} & (set(pub) | set(pub["versions"]["1.6"])), \
                sorted(pub["versions"]["1.6"])
            write_text(os.path.join(stack, ".env"), env_of("Private_Root_41", "Private_Flask_41"))
            assert kinds() == ("custom", "vendor", "vendor"), "the Flask key is judged where the sdk loads it"
            info = secrets_info("1.6")
            assert (info["mysqlRootVendorDefault"], info["mysqlRootSource"], info["flaskVendorDefault"]) == (False, None, True)
            ensure_env_secrets("1.6", job(), cold=True)
            assert kinds() == ("custom", "custom", "vendor")
            stack = mk("h-unreadable", env=None)
            os.makedirs(os.path.join(stack, ".env"))  # open() fails with something else than "not found"
            write_text(os.path.join(stack, "sdk", "data", "config.json"), sdk_of("Private_Flask_43"))
            st16 = status16()
            assert (st16["mysqlPassword"], st16["flaskKey"], st16["present"]) == (None, "custom", True), "unreadable"
            write_text(os.path.join(stack, "sdk", "data", "config.json"), "{}\n")
            assert kinds()[:2] == (None, None), "no file names a value: unknown"

            # (I) installer-set, never editable through POST /agent/config -- by the reason, not just a 400
            for key in ("GIO_MYSQL_ROOT_PASSWORD", "GIO_FLASK_SECRET_KEY"):
                assert key not in AGENT_SETTINGS and key not in AGENT_SETTING_KEYS
                assert raises(400, lambda key=key: set_agent_config({"set": {key: "Abcdefgh_1"}})) \
                    == key + ": set when the agent is installed -- not editable here"

            # (J) the stack INTERNAL password (redis' requirepass + hk4e_work + hk4e_readonly): the real db
            #     stage, file level and logins from here on. The model's other half (mk, docker, fake_run) answers the
            #     logins as a game account over the stack network -- ok / refused / no clear answer --, runs redis
            #     with the password its rendered command line named when it was (re)created, answers `redis-cli ping`
            #     and `ps`, and judges every boot of the game services: their rendered files, both accounts and redis
            #     on ONE value? A mk_int() stack holds every kind of place: bootstrap.sql (with a hand-added account
            #     whose password is not this one), the compose template, prepare-db.sh (root's own lines name
            #     "$MYSQL_ROOT_PASSWORD"), two server XML templates -- and, bootstrapped, their rendered twins
            int_sql = ("SET NAMES utf8;\nSET time_zone = '+00:00';\n\n"
                       "CREATE USER IF NOT EXISTS 'hk4e_work'@'172.10.%%' IDENTIFIED BY '%s';\n"
                       "CREATE USER IF NOT EXISTS 'hk4e_readonly'@'172.10.%%' IDENTIFIED BY '%s';\n"
                       "CREATE USER IF NOT EXISTS 'backup'@'localhost' IDENTIFIED BY 'Backup_Own_0001';\n\n"
                       "GRANT ALL PRIVILEGES ON hk4e_db_user . * TO 'hk4e_work'@'172.10.%%';\n"
                       "GRANT SELECT ON hk4e_db_user . * TO 'hk4e_readonly'@'172.10.%%';\n"
                       "FLUSH PRIVILEGES;\n" % (VINT, VINT))
            prepare_db = ("#!/bin/bash\n\nsource .env\n"
                          "while ! mysqladmin ping --host 172.10.3.100 -u root -p\"$MYSQL_ROOT_PASSWORD\" "
                          "--connect-timeout 3; do\n  sleep 3\ndone\n"
                          "mysql -h172.10.3.100 -u root -p\"$MYSQL_ROOT_PASSWORD\" < bootstrap.sql\n"
                          "mysql -h172.10.3.100 -u hk4e_work -p%s < data.sql\n"
                          "mysql -h172.10.3.100 -u hk4e_work -p%s < adjust.sql\n" % (VINT, VINT))
            dbgate_tmpl = ('<?xml version="1.0" encoding="UTF-8"?>\n<Root>\n'
                           '  <Server id="1" host="172.10.3.1" inner_ip="172.10.3.1" outer_ip="%%OUTER_IP%%" />\n'
                           '  <Db index="1" name="user_id" host="172.10.3.100" user="hk4e_work" pwd="%s" />\n'
                           '  <Db index="2" name="online_id" host="172.10.3.100" user="hk4e_work" pwd="%s" />\n'
                           '  <Db index="9" name="config" host="172.10.3.100" user="hk4e_readonly" pwd="%s" />\n'
                           '</Root>\n' % (VINT, VINT, VINT))
            dbgate_rel = os.path.join("server", "dbgate", "conf", "dbgate.xml.tmpl")
            UP_REDIS, ALTER_INT = ("up", "-d", "redis"), "ALTER USER IF EXISTS " + ALTER_GAME
            where_ = "read it under Server secrets in the launcher or in creds.txt on the box"
            LINE_VENDOR = ("Stack internal password (redis, hk4e_work, hk4e_readonly): the vendor's published "
                           "password replaced with a random one -- %s." % where_)
            LINE_FRESH = ("Stack internal password (redis, hk4e_work, hk4e_readonly): the vendor's published password "
                          "replaced with a random one before the database is created -- %s." % where_)
            LINE_SAME = ("Stack internal password (redis, hk4e_work, hk4e_readonly): every source file names the same "
                         "value now, before the database is created -- %s." % where_)
            LINE_DISAGREE = ("Stack internal password (redis, hk4e_work, hk4e_readonly): the database and the "
                             "configuration files did not agree on it -- replaced with a random one everywhere -- %s."
                             % where_)
            LINE_FINISH = "Stack internal password: a change that had not finished was completed -- %s." % where_
            LINE_RESTORE = ("Stack internal password: the configuration files carried the vendor's published password "
                            "again (a re-extracted archive) -- the one this stack's database uses was put back.")
            LINE_REALIGN = ("Stack internal password: the configuration files were brought back in line with the "
                            "database.")
            LINE_RESTART = ("A change of the stack internal password had not finished -- restarting version 1.6 to "
                            "complete it.")
            UNFINISHED = "Start the server again -- the change is finished at that Start."
            BUSY = "A change of the stack internal password has not finished -- Start the version to complete it."
            INT_FILES = {"bootstrap.sql", "docker-compose.yml.tmpl", "prepare-db.sh", "dbgate.xml.tmpl",
                         "muipserver.xml.tmpl", "docker-compose.yml", "dbgate.xml", "muipserver.xml"}
            stage_runs = []  # the stack's files when a db stage began, while `stage_trees` is on (J1): its own effect
            stage_trees = []  # is the difference from there (no other case reads them: no walk of the stack for them)

            def watched_stage(version, job_, game_up=False):
                if stage_trees:
                    stage_runs.append(tree())
                return saved["ensure_internal_password"](version, job_, game_up=game_up)

            def handing_over(writer):
                """A file writer that hands fake_replace the bytes of its temp file (path + ".tmp", the encoding
                write_text uses) -- the timeline then never reads a file that was just written."""
                def write(path, text, **kw):
                    written[path + ".tmp"] = text.encode("utf-8", "surrogateescape")
                    try:
                        return writer(path, text, **kw)
                    finally:
                        written.pop(path + ".tmp", None)
                return write

            g.update({"write_text_durable": handing_over(saved["write_text_durable"]),
                      "write_text_atomic": handing_over(saved["write_text_atomic"])})
            g.update({"ensure_internal_password": watched_stage,
                      "ensure_internal_sources": saved["ensure_internal_sources"],
                      "game_services_up": saved["game_services_up"], "game_account_login": saved["game_account_login"],
                      # Every state write of section J would copy the state file to state.json.bak first: a durable
                      # write no case here reads (the state's own sections test the backup) -- not performed.
                      "_backup_state": lambda: None})
            timeline.append(True)

            def mk_int(name, crlf=False, lan=None, bootstrapped=True, vendor=False, **kw):
                """mk() with every kind of place of the internal password (above); crlf = every one of them CRLF;
                lan = the rendered files name that address where .env still says 127.0.0.1 (bootstrapped with a LAN
                IP, .env re-extracted since): a re-render would show; vendor = the MUIP and the Flask key are the
                vendor's too (a stack nobody secured) -- else an earlier run made them private already: these
                cases look at the internal password, and every cold start would replace both first (eight more files
                written per start; the root password stays whatever `env` says). Rendered once, after every source is
                there."""
                env_ = kw.pop("env", vendor_env)
                stack_ = mk(name, env=env_ if vendor or env_ is None else env_.replace(VFLASK, "Private_Flask_J00"),
                            bootstrapped=False, **kw)
                os.makedirs(os.path.dirname(os.path.join(stack_, INT_SOURCES[2])))
                os.makedirs(os.path.dirname(os.path.join(stack_, dbgate_rel)))
                muip_ = muip_tmpl if vendor else muip_tmpl.replace(VMUIP, "SelftestOwnMuipKey00000000000000J00")
                for rel, text in (("bootstrap.sql", int_sql), (INT_SOURCES[2], prepare_db), (dbgate_rel, dbgate_tmpl)) \
                        + ((("docker-compose.yml.tmpl", compose_tmpl),) if crlf else ()) \
                        + (((os.path.join("server", "muipserver", "conf", "muipserver.xml.tmpl"), muip_),)
                           if crlf or not vendor else ()):  # (mk() wrote the vendor's, LF)
                    write_text(os.path.join(stack_, rel), text.replace("\n", "\r\n") if crlf else text)
                if os.name != "nt":
                    os.chmod(os.path.join(stack_, INT_SOURCES[2]), 0o755)
                if bootstrapped:
                    render_stack_configs("1.6", _Job())
                    write_text(os.path.join(stack_, ".bootstrap.lock"), "\n")
                    for rel in ("docker-compose.yml", dbgate_rel[:-len(".tmpl")]) if lan else ():
                        write_text(os.path.join(stack_, rel), rd(rel).replace("127.0.0.1", lan))
                    if srv["up"]:
                        srv["redis"] = rendered_requirepass(stack_)  # (mk() found nothing rendered yet)
                del renders[:]
                return stack_

            def secure(value):
                """Every place of the current stack, both game accounts and a running redis on `value`: what an
                earlier change left behind."""
                for base, _dirs, names in os.walk(here[0]):
                    for n_ in names:
                        if place_values(read_text(os.path.join(base, n_))):
                            write_text(os.path.join(base, n_), read_text(os.path.join(base, n_)).replace(VINT, value))
                srv["game"] = {"hk4e_work": value, "hk4e_readonly": value}
                if srv["redis"] is not None:
                    srv["redis"] = value

            def reextract_int(full=True):
                """The archive's sources of the internal password extracted over the stack again: bootstrap.sql, the
                compose template, prepare-db.sh and the dbgate template name the vendor's value; with `full`, .env,
                creds.txt and the MUIP template too (reextract)."""
                if full:
                    reextract()
                for rel, text in (("bootstrap.sql", int_sql), (INT_SOURCES[2], prepare_db), (dbgate_rel, dbgate_tmpl),
                                  ("docker-compose.yml.tmpl", compose_tmpl)):
                    write_text(os.path.join(here[0], rel), text)

            def int_lines(job_):
                return [l for l in job_.lines if "stack internal password" in l.lower()]

            def pend():
                return note(read_creds_record("1.6")["internalPending"])

            def int_sec():
                return version_state("1.6").get("secrets") or {}

            def one_value(**kw):
                """The ONE value every place names now (an assertion when they name several)."""
                vals_ = placed(**kw)
                assert len(vals_) == 1, shown(vals_)
                return note(next(iter(vals_)))

            # the pure editors: EVERY place is set whatever it held (a crash may leave a file mixed), n = the places
            # that changed, nothing else -- not another account's CREATE USER, not root's lines of prepare-db.sh --,
            # LF / CRLF; a file without its places is no layout to write
            for nl_ in ("\n", "\r\n"):
                for kind, text in (("sql", int_sql), ("compose", compose_tmpl), ("sh", prepare_db),
                                   ("xml", dbgate_tmpl.replace(VINT, "Other_Value_01", 1))):
                    text = text.replace("\n", nl_)
                    new, n = set_internal_positions(kind, text, "Abcdefgh_123")
                    assert new == text.replace(VINT, "Abcdefgh_123").replace("Other_Value_01", "Abcdefgh_123"), kind
                    assert n == len(place_values(text)) > 0 and set_internal_positions(kind, new, "Abcdefgh_123") \
                        == (new, 0), kind
                    assert internal_position_values(kind, new) == (["Abcdefgh_123"] * n, False), kind
            for kind, text in (("sql", "CREATE USER IF NOT EXISTS 'hk4e_work'@'172.10.%' IDENTIFIED BY 'x';\n"),
                               ("compose", "    command: redis-server --requirepass \"quoted\"\n"),
                               ("sh", "mysql -h172.10.3.100 -u root -p\"$MYSQL_ROOT_PASSWORD\" < bootstrap.sql\n"),
                               ("xml", "<Root />\n")):
                assert internal_position_values(kind, text)[1], kind
            assert positions_value({"a": (["x", "x"], False), "b": (["x"], False)}) == "x"
            assert positions_value({"a": (["x"], False), "b": (["y"], False)}) is None
            assert positions_value({"a": (["x"], True)}) is None and positions_value({}) is None

            # (J1) a stack nobody secured -- every secret the vendor's --, stopped, Start: the root password first,
            #      then the internal one, in this order: the dry run and the probe (every file rewritten with its own
            #      bytes), who chose the value and the pending line, ONE statement for both game accounts, the
            #      verdict by logging in as both, every place of every file (nothing else -- LF and CRLF, no render:
            #      the rendered files name a LAN address .env no longer does), redis recreated and answering with it,
            #      the line cleared, creds.txt, the state, ONE job line -- before the game services boot, on one value
            for crlf in (False, True):
                stack = mk_int("j-start%d" % crlf, crlf=crlf, lan="192.0.2.10", vendor=True)
                j = job()
                stage_trees.append(True)
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                del stage_trees[:]
                t_ = one_value()
                root, flask, muip = env16(), env16("FLASK_SECRET_KEY"), muip16()
                assert res == READY and waited == 0, (res, waited, shown(j.lines))
                assert MYSQL_ROOT_RE.match(t_) and t_ not in public and t_ not in (root, flask), "a new, letter first"
                assert composes == [UP_DB, UP_REDIS, UP_ALL], "the staged start + redis, nothing else: %s" \
                    % shown(composes)
                assert alters == [ALTER_ROOT, ALTER_INT], "ONE statement for both game accounts: %s" % shown(alters)
                assert at_alter[1] == {"internal": t_, "source": "random", "held": {VINT}}, \
                    "value + chooser on record when the ALTER arrived, every file on the old value: " + shown(at_alter)
                probe = [w_ for w_ in writes if w_[0] in INT_FILES and w_[4] == 1]
                done = [w_ for w_ in writes if w_[0] in INT_FILES and w_[4] == 2]
                assert sorted(w_[0] for w_ in probe) == sorted(INT_FILES) and not any(w_[1] or w_[3] for w_ in probe), \
                    "the probe: every file once, its own bytes, before anything is on record: %s" % shown(probe)
                assert sorted(w_[0] for w_ in done) == sorted(INT_FILES) \
                    and all(w_[2] and w_[3] == t_ for w_ in done), \
                    "every file once, after the ALTER, the pending line on record meanwhile: %s" % shown(done)
                before, after = stage_runs[-1], tree()
                int_rels = sorted(k_ for k_ in before if os.path.basename(k_) in INT_FILES)
                assert sorted(k_ for k_ in set(before) | set(after) if before.get(k_) != after.get(k_)
                              and k_ != CREDS_RECORD) == sorted(int_rels + ["creds.txt"]), "the stage wrote those only"
                assert len(int_rels) == 8 and all(after[k_] == before[k_].replace(VINT.encode(), t_.encode())
                                                  for k_ in int_rels), \
                    "only the password's bytes changed -- line endings, the LAN address, the root line, the rest kept"
                assert renders == [] and ps_calls == [], "no render, and a cold start asks docker nothing"
                assert [(u_, v_, n_) for u_, _p, v_, n_ in logins] == [
                    ("hk4e_work", "ok", 1), ("hk4e_readonly", "ok", 1), ("hk4e_work", "ok", 2),
                    ("hk4e_readonly", "ok", 2)] and [p_ for _u, p_, _v, _n in logins] == [VINT, VINT, t_, t_], \
                    "learned, then proven: %s" % shown(logins)
                assert srv["game"] == {"hk4e_work": t_, "hk4e_readonly": t_} and srv["redis"] == t_ \
                    and srv["redis_recreated"] == 1 and pings == [(t_, "PONG")], shown(pings)
                assert boots == [True], "the game services booted once, on one value everywhere"
                assert pend() == "" and rec() == {"root": root, "pending": ""} \
                    and rd("creds.txt") == creds_of(root, flask, muip, t_)
                sec = int_sec()
                assert sec["internalSource"] == "random" and sec["internalChangedAt"] \
                    and not {"internalPendingSource", "internalPendingFresh"} & set(sec), sorted(sec)
                assert int_lines(j) == [LINE_VENDOR], shown(int_lines(j))
                if os.name != "nt":
                    assert os.stat(os.path.join(stack, INT_SOURCES[2])).st_mode & 0o777 == 0o755, "its mode kept"
                info = secrets_info("1.6")
                assert status16()["internalPassword"] == "custom" and (
                    info["internal"], info["internalVendorDefault"], info["internalPending"], info["internalSource"]) \
                    == (t_, False, False, "random"), shown(info)
                clean(j.lines, t_, root, flask, muip)
                # the steady state: stopped and started again, then started while it runs -- one private value in
                # every place, nothing pending: not a login, not a `ps`, no ALTER, no place written
                docker(stack, ("down",))
                for again in (1, 2):
                    for box in (composes, logins, pings, ps_calls, alters, writes):
                        del box[:]
                    res, waited = virtual(lambda: do_start("1.6", job(), provision="none"))
                    assert res == READY and composes == [UP_DB, UP_ALL] and (logins, pings, ps_calls, alters) \
                        == ([], [], [], []), shown(again, composes, len(logins), len(ps_calls))
                    assert placed() == {t_} and not [w_ for w_ in writes if w_[2]], (again, shown(writes))

            # (J2) ...and through Prepare server, in every progress mode (configuration, not player data): right after
            #      the root password, before anything is written into the database
            for mode in ("default", "keep", "fixes"):
                stack = mk_int("j-prov-" + mode, up=True)
                j = job()
                res, waited = virtual(lambda: do_provision("1.6", j, progress=mode))
                t_ = one_value()
                heads = [w for _s, w in sent]
                assert res["provisioned"] and waited == 0 and composes == [DOWN, UP_DB, UP_REDIS, UP_ALL], \
                    shown(mode, composes)
                assert alters == [ALTER_ROOT, ALTER_INT] and srv["game"] == {"hk4e_work": t_, "hk4e_readonly": t_}
                assert heads.index(ALTER_INT.split(" IDENTIFIED")[0]) < heads.index("-- events"), shown(mode, heads)
                assert srv["redis"] == t_ and boots == [True] and renders == [] and pend() == "", (mode, boots)
                assert int_lines(j) == [LINE_VENDOR] and int_sec()["internalSource"] == "random", shown(j.lines)
                clean(j.lines, t_)

            # (J3) a RUNNING stack still on the vendor's value: its root password is replaced (no service logs in as
            #      root), the internal one is not -- that restarts every service: no login, no place written,
            #      /status keeps saying "vendor"; the same when docker cannot tell whether a game service runs. A
            #      stack listed with nothing but mysql, redis and the sdk up (a reboot, a failed start) IS cold for it
            for ps_fail in (False, True):
                stack = mk_int("j-running%d" % ps_fail, up=True)
                srv["ps_fail"] = ps_fail
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                assert res == READY and alters == [ALTER_ROOT] and (logins, pings) == ([], []), shown(ps_fail, alters)
                assert len(ps_calls) == 1 and placed() == {VINT} and srv["game"]["hk4e_work"] == VINT == srv["redis"]
                assert composes == [UP_DB, UP_ALL] and boots == [] and int_lines(j) == [] and renders == [], \
                    shown(composes)
                assert status16()["internalPassword"] == "vendor", "kept reporting what it still is"
                assert secrets_info("1.6")["internalVendorDefault"] is True
            stack = mk_int("j-rebooted")
            srv.update(up=True, redis=VINT, services=dict.fromkeys(("mysql", "redis", "sdk"), "running"))
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            t_ = one_value()
            assert res == READY and t_ not in public and alters == [ALTER_ROOT, ALTER_INT] and len(ps_calls) == 1, \
                shown(alters)
            assert composes == [UP_DB, UP_REDIS, UP_ALL] and boots == [True] and int_lines(j) == [LINE_VENDOR], \
                shown(composes)
            # ...but a game service docker keeps restarting (the others exited) RUNS for this purpose: left alone
            stack = mk_int("j-restarting", env=env_of("Private_Root_59"))
            srv.update(up=True, redis=VINT, services=dict(dict.fromkeys(GAME_SERVICES, "exited"), mysql="running",
                                                          redis="running", gameserver="restarting"))
            res, waited = virtual(lambda: do_start("1.6", job(), provision="none"))
            assert res == READY and alters == [] and (logins, pings) == ([], []) and len(ps_calls) == 1, shown(alters)
            assert placed() == {VINT} and composes == [UP_DB, UP_ALL] and boots == [True], shown(composes)
            # ...and what stops the stage BEFORE anything changes: one WARNING -- no pending line, no ALTER, no place
            # written -- and the start goes on as it would have (on the vendor's value, consistent): a place missing
            # where it must be (found before any login), game accounts this agent does not know, a login that gets no
            # clear answer, a file that cannot be replaced (the probe). With a change on record, no clear answer is
            # a 500 and the version down
            for name, why, n_logins in (("j-layout", "does not hold it where this agent expects it", 0),
                                        ("j-accounts", "game accounts are not the ones this agent knows", 0),
                                        ("j-nologin", "the game accounts could not be checked", 1),
                                        ("j-probe", "a file that holds it cannot be written", 2)):
                stack = mk_int(name, env=env_of("Private_Root_57"))
                if name == "j-layout":
                    write_text(os.path.join(stack, dbgate_rel),
                               re.sub(r'\bpwd="[^"]*"', 'password="x"', rd(dbgate_rel)))
                elif name == "j-accounts":
                    srv["accounts"] = [("hk4e_work", "%"), ("hk4e_readonly", "%")]
                elif name == "j-nologin":
                    srv["login_unknown"] = True
                else:
                    failing.add("dbgate.xml")
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                warn = [l for l in int_lines(j) if l.startswith("WARNING: Stack internal password: ")]
                assert res == READY and len(int_lines(j)) == len(warn) == 1 and why in warn[0], shown(name, j.lines)
                assert alters == [] and placed() == {VINT} and pending_now() == "" and boots == [True], name
                assert not [w_ for w_ in writes if w_[2]] and "internalPendingSource" not in int_sec(), name
                assert len(logins) == n_logins and composes == [UP_DB, UP_ALL], shown(name, logins, composes)
            stack = mk_int("j-nologin-pending", env=env_of("Private_Root_58"))
            write_creds_record("1.6", internal_pending=note("Pending_Int_00058"))
            srv["login_unknown"] = True
            msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
            assert "the game accounts could not be checked" in msg and msg.endswith(UNFINISHED), shown(msg)
            assert composes == [UP_DB, DOWN] and boots == [] and alters == [] and pend() == "Pending_Int_00058", \
                shown(composes)

            # (J4) the archive extracted over a SECURED stack again: .env, creds.txt and every source name the
            #      vendor's values, while the rendered files, the database and redis keep the stack's own. /status
            #      judges what the stack runs on ("custom"); the Start learns that the database accepts the rendered
            #      value: RESTORE -- every source put back, no ALTER, no redis recreate, creds.txt names it again, the
            #      chooser on record stays. Sources that name another private value (a hand edit): the same way
            for name, edit in (("j-restore", None), ("j-realign", "Edited_Int_0053")):
                stack = mk_int(name, env=env_of("Private_Root_51", "Private_Flask_51"))
                secure(note("Kept_Int_00051"))
                write_creds_record("1.6", root="Private_Root_51")
                version_state_set("1.6", secrets={"internalSource": "admin", "internalChangedAt": "2026-01-01 00:00"})
                if edit:
                    write_text(os.path.join(stack, "bootstrap.sql"),
                               rd("bootstrap.sql").replace("Kept_Int_00051", note(edit)))
                else:
                    reextract_int()
                    assert status16()["internalPassword"] == "custom", "judged where the stack runs: the rendered files"
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                assert res == READY and waited == (0 if edit else 3) and placed() == {"Kept_Int_00051"}, \
                    (name, waited, shown(placed()))
                assert alters == [] and UP_REDIS not in composes and srv["redis_recreated"] == 0 and pings == [], \
                    shown(composes)
                assert [(u_, p_, v_) for u_, p_, v_, _n in logins] == [("hk4e_work", "Kept_Int_00051", "ok"),
                                                                       ("hk4e_readonly", "Kept_Int_00051", "ok")]
                assert int_lines(j) == [LINE_REALIGN if edit else LINE_RESTORE], shown(int_lines(j))
                assert rd("creds.txt").endswith("h4ke pass: Kept_Int_00051\r\n") and pend() == "" and boots == [True]
                assert int_sec()["internalSource"] == "admin" and int_sec()["internalChangedAt"] == "2026-01-01 00:00"
                assert sorted(w_[0] for w_ in writes if w_[2]) == (["bootstrap.sql"] if edit else sorted(
                    ("bootstrap.sql", "docker-compose.yml.tmpl", "prepare-db.sh", "dbgate.xml.tmpl",
                     "muipserver.xml.tmpl"))), "the sources only: %s" % shown(writes)
            # ...but when the database does NOT accept the rendered value (it never followed it) and accepts the
            # vendor's: replaced with a new one; and when it accepts none this agent knows while the files disagree:
            # replaced too
            for name, server_has, line in (("j-refused", VINT, LINE_VENDOR),
                                           ("j-disagree", "Lost_Int_00054", LINE_DISAGREE)):
                stack = mk_int(name, env=env_of("Private_Root_52"))
                secure(note("Kept_Int_00052"))
                srv["game"] = dict.fromkeys(("hk4e_work", "hk4e_readonly"), note(server_has))
                if server_has == VINT:
                    reextract_int(full=False)
                else:
                    write_text(os.path.join(stack, "bootstrap.sql"),
                               rd("bootstrap.sql").replace("Kept_Int_00052", "Edited_Int_0054"))
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                t_ = one_value()
                assert res == READY and t_ not in ("Kept_Int_00052", server_has) and alters == [ALTER_INT], name
                assert srv["game"] == {"hk4e_work": t_, "hk4e_readonly": t_} and srv["redis"] == t_ and boots == [True]
                assert int_lines(j) == [line], (name, shown(int_lines(j)))
            # ...and the RENDERED files behind the database (a rotation that died before its render: the sources and
            # both accounts on its value, every rendered file still on the vendor's): put back the same way -- and
            # redis, which the staged `up` created from the rendered compose with the old value, follows (`up -d
            # redis`, PONG) BEFORE the game services boot
            stack = mk_int("j-behind", env=env_of("Private_Root_53"))
            _apply_internal_plan(_internal_plan("1.6", note("Rotated_Int_0053"), sources_only=True)[0])
            srv["game"] = dict.fromkeys(("hk4e_work", "hk4e_readonly"), "Rotated_Int_0053")
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and placed() == {"Rotated_Int_0053"} and alters == [] and boots == [True], \
                shown(placed())
            assert composes == [UP_DB, UP_REDIS, UP_ALL] and srv["redis_recreated"] == 1 \
                and pings == [("Rotated_Int_0053", "PONG")] and int_lines(j) == [LINE_RESTORE], shown(composes, pings)

            # (J5) a FRESH install (Prepare server on a just-extracted stack; the Windows steps and the Linux script):
            #      the sources name ONE random value before the vendor bootstrap reads them -- the pending line and
            #      who chose it first --, so it creates both accounts with it, imports AS hk4e_work with it and
            #      renders redis and every XML with it; ONE job line. The provision's db stage only proves it:
            #      silently, no ALTER
            for win in (True, False):
                g["IS_WINDOWS"] = win
                stack = mk_int("j-fresh%d" % win, data=False, bootstrapped=False)
                j = job()
                res, waited = virtual(lambda: do_setup("1.6", j))
                p_ = one_value()
                assert res["provisioned"] and waited == 0 and p_ not in public and MYSQL_ROOT_RE.match(p_), (win, res)
                assert bootstraps == [(p_, {p_}, "random", True)], "on record (value, chooser, the hand-off) and in " \
                    "every source when the bootstrap read them: %s" % shown(bootstraps)
                moved = [w_ for w_ in writes if w_[0] in INT_FILES and w_[2]]
                assert len(moved) == 5 and all(w_[3] == p_ for w_ in moved), "the pending line FIRST: " + shown(moved)
                assert srv["game"] == {"hk4e_work": p_, "hk4e_readonly": p_} and srv["imports"] == [True, True], win
                assert srv["redis"] == p_ and srv["redis_recreated"] == 0 and alters == [] and boots == [True, True]
                assert composes == [DOWN + ("-t", "5"), UP_DB, UP_REDIS, UP_ALL] and pings == [(p_, "PONG")], \
                    shown(composes)
                assert int_lines(j) == [LINE_FRESH], "the provision's proof is silent: %s" % shown(int_lines(j))
                sec = int_sec()
                assert pend() == "" and sec["internalSource"] == "random" and sec["internalChangedAt"] \
                    and not {"internalPendingSource", "internalPendingFresh"} & set(sec), (win, sorted(sec))
                assert renders == [] and rd("creds.txt").endswith("h4ke pass: %s\r\n" % p_), (win, renders)
                clean(j.lines, p_)
            # ...a FORCED reinstall over an initialised data dir: on Linux the script's `sudo rm -rf mysql redis` may
            # fail (no working sudo, no `set -e`) -- CREATE USER IF NOT EXISTS then keeps both accounts on their value
            # and prepare-db.sh's imports AS hk4e_work would be refused with a new one. So sources that agree on the
            # vendor's value are LEFT ALONE there: the vendor bootstrap runs on that value (both imports taken) and the
            # provision's db stage replaces the value by ALTER before ITS game services boot. An EMPTY mysql/ (Linux),
            # and Windows -- _bootstrap_windows deletes mysql/ itself before the database is created -- get the new
            # value before the bootstrap, like a fresh stack (the provision's proof silent, no ALTER)
            for name, win, empty in (("j-force", False, False), ("j-force-empty", False, True),
                                     ("j-force-win", True, False)):
                g["IS_WINDOWS"] = win
                stack = mk_int(name, env=env_of("Private_Root_55", "Private_Flask_55"))
                if empty:
                    os.remove(os.path.join(stack, "mysql", "ibdata1"))
                srv["sudo"] = False
                j = job()
                res, waited = virtual(lambda: do_setup("1.6", j, force=True))
                p_ = one_value()
                early = win or empty  # (the sources take the new value before the bootstrap reads them)
                assert res["provisioned"] and p_ not in public and srv["redis"] == p_ and pend() == "" \
                    and srv["game"] == {"hk4e_work": p_, "hk4e_readonly": p_} and boots == [True, True], \
                    shown(name, boots)
                assert srv["imports"] == [True, True] and srv["inits"] == int(early), \
                    (name, srv["imports"], srv["inits"])
                assert bootstraps[0][:2] == ((p_, {p_}) if early else ("", {VINT})), shown(name, bootstraps)
                assert alters == ([] if early else [ALTER_INT]), shown(name, alters)
                assert int_lines(j) == [LINE_FRESH if early else LINE_VENDOR], shown(name, int_lines(j))
            # ...while a change on record, or sources that disagree, are brought in line FIRST there too (Linux, an
            # initialised data dir -- one the script does wipe, sudo works): the bootstrap reads ONE value -- the
            # pending one, still its chooser's, else a random one, the pending line first --, creates both accounts
            # and imports with it; the provision's proof is silent, no ALTER
            g["IS_WINDOWS"] = False
            for name, edit in (("j-force-pending", None), ("j-force-disagree", "Edited_Int_0075")):
                stack = mk_int(name, env=env_of("Private_Root_75", "Private_Flask_75"))
                if edit:
                    write_text(os.path.join(stack, "bootstrap.sql"), rd("bootstrap.sql").replace(VINT, note(edit)))
                else:
                    write_creds_record("1.6", internal_pending=note("Pending_Int_00075"))
                    version_state_set("1.6", secrets={"internalPendingSource": "admin"})
                j = job()
                res, waited = virtual(lambda: do_setup("1.6", j, force=True))
                p_ = one_value()
                assert (p_ == "Pending_Int_00075") if not edit else (p_ not in public + (edit,)), shown(name, p_)
                assert bootstraps == [(p_, {p_}, "random" if edit else "admin", True)], shown(name, bootstraps)
                moved = [w_ for w_ in writes if w_[0] in INT_FILES and w_[2]]
                assert len(moved) == 5 and all(w_[3] == p_ for w_ in moved), "the pending line FIRST: " + shown(moved)
                assert res["provisioned"] and srv["inits"] == 1 and srv["imports"] == [True, True] and alters == [] \
                    and srv["game"] == {"hk4e_work": p_, "hk4e_readonly": p_} and srv["redis"] == p_ and pend() == "" \
                    and boots == [True, True], shown(name, alters, boots)
                assert int_lines(j) == [LINE_FRESH if edit else LINE_SAME], shown(name, int_lines(j))
                assert int_sec()["internalSource"] == ("random" if edit else "admin"), sorted(int_sec())
            g["IS_WINDOWS"] = saved["IS_WINDOWS"]
            # ...sources that already name one private value are left alone (a forced reinstall of a secured stack);
            # sources that disagree get one random value -- and when they cannot be brought in line, nothing installs
            stack = mk_int("j-sources", data=False, bootstrapped=False)
            secure(note("Kept_Int_00056"))
            before = tree()
            j = job()
            assert ensure_internal_sources("1.6", j) is None and tree() == before and j.lines == [], shown(j.lines)
            write_text(os.path.join(stack, "bootstrap.sql"),
                       rd("bootstrap.sql").replace("Kept_Int_00056", "Edited_Int_0056"))
            assert ensure_internal_sources("1.6", j) == "random" \
                and one_value() not in ("Kept_Int_00056", "Edited_Int_0056")
            assert int_lines(j) == [LINE_SAME], shown(j.lines)
            write_creds_record("1.6", internal_pending="")
            write_text(os.path.join(stack, "bootstrap.sql"), int_sql)
            failing.add("docker-compose.yml.tmpl")
            msg = raises(500, lambda: virtual(lambda: do_setup("1.6", job())))
            assert "not installing" in msg and bootstraps == [] \
                and not os.path.exists(os.path.join(stack, ".bootstrap.lock")), shown(msg)
            failing.clear()
            # ...nor when a source write is lost AFTER the pending line went on record (the read-back finds it): 500,
            # the value stays pending, and the bootstrap never runs over sources that name two values
            stack = mk_int("j-sources-lost", data=False, bootstrapped=False)
            srv["write_lost"] = "docker-compose.yml.tmpl"
            msg = raises(500, lambda: virtual(lambda: do_setup("1.6", job())))
            assert "could not all be brought to the new value (docker-compose.yml.tmpl names another value) -- not " \
                   "installing" in msg and bootstraps == [] and pend() and placed(rendered=False) == {pend(), VINT} \
                and not os.path.exists(os.path.join(stack, ".bootstrap.lock")), shown(msg, placed())
            srv["write_lost"] = ""

            # (J6) the verdict after the ALTER (D4). The game accounts did not take it -- refused, or one account only
            #      (a multi-user ALTER is not atomic): the old value goes back, PROVEN by logging in again with every
            #      file still on it -- one WARNING, nothing changed, the start goes on consistent. No clear answer
            #      after the ALTER, an ALTER back that cannot be proven, no value the database held before: 500, the
            #      version DOWN, the change on record -- and the next Start completes it
            for how in ("refused", "half"):
                stack = mk_int("j-d4" + how, env=env_of("Private_Root_61"))
                srv["alter"] = how
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                t_ = note(at_alter[0]["internal"])
                assert res == READY and alters == [ALTER_INT, ALTER_INT] and at_alter[1]["internal"] == t_, \
                    shown(alters)
                assert [(u_, p_, v_) for u_, p_, v_, _n in logins[2:]] == [
                    ("hk4e_work", t_, "ok" if how == "half" else "refused"), ("hk4e_readonly", t_, "refused"),
                    ("hk4e_work", VINT, "ok"), ("hk4e_readonly", VINT, "ok")], shown(logins)
                assert srv["game"] == {"hk4e_work": VINT, "hk4e_readonly": VINT} and placed() == {VINT} and pend() == ""
                assert composes == [UP_DB, UP_ALL] and boots == [True] and srv["redis"] == VINT, shown(how, composes)
                assert len(int_lines(j)) == 1 and int_lines(j)[0].startswith(
                    "WARNING: Stack internal password: NOT replaced -- after ALTER USER the game accounts did not "
                    "take the new password (") and int_lines(j)[0].endswith("). Nothing was changed."), shown(j.lines)
                assert not {"internalSource", "internalPendingSource"} & set(int_sec()), sorted(int_sec())
                assert status16()["internalPassword"] == "vendor"
                clean(j.lines, t_, "Private_Root_61")
            for name, setup, text in (
                    ("j-d4unknown", {"unknown_after_alter": True}, "could not be proven to use either password"),
                    ("j-d4back", {"alter": "half refused"}, "the old one could not be proven back everywhere"),
                    ("j-d4none", {"alter": "refused", "game": dict.fromkeys(("hk4e_work", "hk4e_readonly"),
                                                                           note("Lost_Int_00062"))},
                     "could not be proven to use either password")):
                stack = mk_int(name, env=env_of("Private_Root_62"))
                srv.update(setup)
                j = job()
                msg = raises(500, lambda: virtual(lambda: do_start("1.6", j, provision="none")))
                t_ = pend()
                assert t_ and t_ == at_alter[0]["internal"] and text in msg and msg.endswith(UNFINISHED), \
                    shown(name, msg)
                assert msg.startswith("Stack internal password: ") and CREDS_RECORD in msg, shown(msg)
                assert composes == [UP_DB, DOWN] and not srv["up"] and srv["services"] == {} and boots == [], \
                    shown(composes)
                assert placed() == {VINT} and version_state("1.6")["runningOk"] is False, name
                assert status16()["internalPassword"] == "pending" and secrets_info("1.6")["internalPending"] is True
                clean([msg] + j.lines, t_)
                # ...the next Start (docker answers again): completed, with an ALTER only where the database lacks it
                srv.update(login_unknown=False, unknown_after_alter=False)
                for box in (composes, alters, logins):
                    del box[:]
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                assert res == READY and placed() == {t_} and pend() == "" and int_lines(j) == [LINE_FINISH], name
                assert alters == ([] if name == "j-d4unknown" else [ALTER_INT]) and srv["game"]["hk4e_readonly"] == t_
                assert composes == [UP_DB, UP_REDIS, UP_ALL] and boots == [True] and srv["redis"] == t_, \
                    shown(composes)
                assert int_sec()["internalSource"] == "random", sorted(int_sec())
            # ...and a refusal over files that did NOT all name D (a rendered XML a hand edit left on a third value):
            # the database is back on D, but "nothing was changed" also needs every file on it -- 500, the version
            # down, nothing boots
            stack = mk_int("j-d4mixed", env=env_of("Private_Root_63"))
            write_text(os.path.join(stack, dbgate_rel[:-len(".tmpl")]), rd(dbgate_rel[:-len(".tmpl")]).replace(
                'pwd="%s"' % VINT, 'pwd="%s"' % note("Stale_Hand_Edit_1"), 1))
            srv["alter"] = "refused"
            msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
            assert "the old one could not be proven back everywhere" in msg and msg.endswith(UNFINISHED), shown(msg)
            assert composes == [UP_DB, DOWN] and boots == [] and alters == [ALTER_INT, ALTER_INT] and pend() \
                and srv["game"] == {"hk4e_work": VINT, "hk4e_readonly": VINT}, shown(composes)

            # (J7) a failure AFTER the ALTER (D5) leaves the version DOWN with the change on record -- a file that
            #      cannot be written, a write the disk lost (the read-back finds it), redis that cannot be recreated,
            #      redis that never answers with it: no game service boots on files and a database that may
            #      disagree, and runningOk stays False (the watchdogs tend nothing). The next Start completes it: no
            #      second ALTER, ONE line
            for fault in ("file", "lost", "redis", "mute"):
                stack = mk_int("j-d5" + fault, env=env_of("Private_Root_65"))
                srv.update(file_dies="dbgate.xml" if fault == "file" else "", redis_mute=fault == "mute",
                           write_lost="dbgate.xml" if fault == "lost" else "")
                if fault == "redis":
                    compose_rc[UP_REDIS] = 1
                j = job()
                msg = raises(500, lambda: virtual(lambda: do_start("1.6", j, provision="none"), nap=0.5))
                t_ = pend()
                assert t_ and t_ == at_alter[0]["internal"] and srv["game"] == {"hk4e_work": t_, "hk4e_readonly": t_}
                assert msg.startswith("Stack internal password: ") and msg.endswith(UNFINISHED) \
                    and CREDS_RECORD in msg \
                    and {"file": "No space left on device (selftest)", "lost": "dbgate.xml names another value",
                         "redis": "docker compose up redis failed (code 1)",
                         "mute": "redis did not answer with the new password within %ds" % REDIS_READY_WAIT}[fault] \
                    in msg, shown(fault, msg)
                assert composes[-1] == DOWN and UP_ALL not in composes and boots == [] and not srv["up"], \
                    shown(fault, composes)
                assert placed() == ({t_, VINT} if fault in ("file", "lost") else {t_}), shown(fault, placed())
                assert version_state("1.6")["runningOk"] is False and status16()["internalPassword"] == "pending"
                assert fault != "mute" or (len(pings) > 1 and {a_ for _p, a_ in pings} == {
                    "LOADING Redis is loading the dataset in memory"}), "it waited for an answer"
                clean([msg] + j.lines, t_)
                if fault == "file":
                    # ...a Start while that file still cannot be written: its probe fails before anything is sent, but
                    # the database has the new value and the files name two -- the change is NOT dropped: 500, the
                    # version down again, the line kept, nothing boots
                    for box in (composes, alters):
                        del box[:]
                    msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
                    assert "a file that holds it cannot be written" in msg and msg.endswith(UNFINISHED) \
                        and composes == [UP_DB, DOWN] and alters == [] and boots == [] and pend() == t_ \
                        and placed() == {t_, VINT}, shown(msg, composes)
                failing.clear()
                compose_rc.clear()
                srv.update(file_dies="", write_lost="", redis_mute=False)
                for box in (composes, alters, pings):
                    del box[:]
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                assert res == READY and alters == [] and placed() == {t_} and pend() == "" and srv["redis"] == t_, fault
                assert composes == [UP_DB, UP_REDIS, UP_ALL] and boots == [True] and int_lines(j) == [LINE_FINISH], \
                    shown(composes)
                assert pings[-1] == (t_, "PONG") and version_state("1.6")["runningOk"] is True
            # ...the version DOWN means runningOk False on record first, whatever the caller left there, and a 500 that
            # never says "stopped" when the down failed (it names the exit code instead)
            stack = mk_int("j-d5down", env=env_of("Private_Root_65"), up=True)
            for rc_ in (1, 0):
                version_state_set("1.6", runningOk=True)
                compose_rc[DOWN] = rc_
                e_ = _internal_unfinished("1.6", job(), "a reason", recorded=bool(rc_))
                assert isinstance(e_, InternalChangeUnfinished) and e_.status == 500 and e_.message == (
                    "Stack internal password: a reason. The change is recorded as pending in %s in the stack folder. "
                    "Stopping the version failed (code 1) -- stop it, then Start it again. " % CREDS_RECORD if rc_
                    else "Stack internal password: a reason. The version was stopped. ") + UNFINISHED, shown(e_.message)
                assert version_state("1.6")["runningOk"] is False and composes[-1] == DOWN and srv["up"] is bool(rc_)
            compose_rc.clear()
            # ...redis that takes a moment (LOADING): the stage waits for its PONG
            stack = mk_int("j-d5loading", env=env_of("Private_Root_65"))
            srv["redis_loading"] = 2
            res, waited = virtual(lambda: do_start("1.6", job(), provision="none"), nap=0.5)
            t_ = one_value()
            assert res == READY and [a_ for _p, a_ in pings] == ["LOADING Redis is loading the dataset in memory"] * 2 \
                + ["PONG"] and boots == [True], shown(pings)
            # ...the agent KILLED right after the ALTER: no down ran, mysql + redis stay up and the project listed.
            # The next Start asks docker: nothing but mysql / redis runs -- cold for the stage, completed; had
            # somebody started the game services meanwhile, it brings the version down first (one line) and starts it
            # cold
            for by_hand in (False, True):
                stack = mk_int("j-kill%d" % by_hand, env=env_of("Private_Root_66"))
                srv["alter"] = "kill"
                try:
                    virtual(lambda: do_start("1.6", job(), provision="none"))
                    raise AssertionError("the kill did not happen")
                except _Killed:
                    pass
                t_ = pend()
                assert srv["game"] == {"hk4e_work": t_, "hk4e_readonly": t_} and placed() == {VINT} and srv["up"]
                assert set(srv["services"]) == {"mysql", "redis"} and boots == [], sorted(srv["services"])
                if by_hand:
                    srv["services"].update(dict.fromkeys(GAME_SERVICES, "running"))  # (`docker compose up -d`)
                for box in (composes, alters, ps_calls):
                    del box[:]
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                assert res == READY and alters == [] and len(ps_calls) == 1 and placed() == {t_} and pend() == "", \
                    by_hand
                assert composes == [DOWN] * by_hand + [UP_DB, UP_REDIS, UP_ALL] and boots == [True], \
                    shown(by_hand, composes)
                assert int_lines(j) == [LINE_RESTART] * by_hand + [LINE_FINISH], shown(int_lines(j))

            # (J8) where else a change on record stops things (D6). A Start that cannot tell whether game services
            #      run: 500 before anything (not a compose call, not a state write); MySQL that never answers: 500
            #      before the final `up -d`. Every other path that would boot a game service refuses with ONE 409
            #      and touches nothing; on a stopped stack the paths that boot nothing still work; the tower watchdog
            #      -- it acts on any listed stack, runningOk or not -- starts no job for that version
            stack = mk_int("j-d6", up=True, env=env_of("Private_Root_67"))
            write_creds_record("1.6", internal_pending=note("Pending_Int_00067"))
            srv["ps_fail"] = True
            state_before = _box_state_bytes(g["STATE_PATH"])
            msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
            assert "docker cannot tell whether the version's services run" in msg and composes == [] and sent == [], \
                shown(msg)
            assert _box_state_bytes(g["STATE_PATH"]) == state_before and pend() == "Pending_Int_00067"
            stack = mk_int("j-d6nodb", env=env_of("Private_Root_68"), server_root="Unknown_Root_0068")
            write_creds_record("1.6", internal_pending=note("Pending_Int_00068"))
            msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
            assert "MySQL did not answer" in msg and composes == [UP_DB] and boots == [], shown(msg, composes)
            assert pend() == "Pending_Int_00068"
            stack = mk_int("j-409", up=True, env=env_of("Private_Root_69"))
            write_creds_record("1.6", internal_pending=note("Pending_Int_00069"))
            write_text(os.path.join(td, "payloads", "1.6", "hotpatch.json"), "{}")  # (do_hotpatch reads it first)
            try:
                for name, fn in (("events", lambda: do_events("1.6", job())),
                                 ("txt fixes", lambda: do_txt_fixes("1.6", job())),
                                 ("netfix", lambda: do_netfix("1.6", job())),
                                 ("pathfinding on", lambda: do_pathfinding("1.6", job(), True)),
                                 ("pathfinding up", lambda: reconcile_pathfinding("1.6", job(), True)),
                                 ("towerfix", lambda: do_towerfix("1.6", job())),
                                 ("hotpatch", lambda: do_hotpatch("1.6", job(), False)),
                                 ("secrets", lambda: do_secrets("1.6", job(), {"flask": note("AdminFlask_69000")})),
                                 ("secrets internal",
                                  lambda: do_secrets("1.6", job(), {"internal": note("AdminInt_00069")}))):
                    before = tree()
                    for box in (composes, alters):
                        del box[:]
                    assert raises(409, fn) == BUSY, name
                    assert composes == [] and alters == [] and tree() == before and pend() == "Pending_Int_00069", name
            finally:
                os.remove(os.path.join(td, "payloads", "1.6", "hotpatch.json"))
            # ...and over a record that cannot be read (it may hold such a change): refused all the same, its own text
            os.remove(creds_record_path("1.6"))
            os.makedirs(creds_record_path("1.6"))
            for name, fn in (("events", lambda: do_events("1.6", job())),
                             ("towerfix", lambda: do_towerfix("1.6", job())),
                             ("secrets", lambda: do_secrets("1.6", job(), {"flask": note("AdminFlask_69000")}))):
                before = tree()
                msg = raises(409, fn)
                assert msg.startswith("Stack internal password: %s cannot be read (" % CREDS_RECORD) and msg.endswith(
                    ") -- make it readable, then try again.") and composes == [] and tree() == before, shown(name, msg)
            os.rmdir(creds_record_path("1.6"))
            write_creds_record("1.6", internal_pending="Pending_Int_00069")
            docker(stack, ("down",))
            assert do_txt_fixes("1.6", job()) == {"files": 0, "action": "apply"} and do_netfix("1.6", job()) == {
                "xml": True, "sql": False} and composes == [], "a stopped stack: nothing boots, nothing refused"
            srv["up"] = True
            os.makedirs(os.path.join(stack, os.path.dirname(TOWER_TXT)))
            write_text(os.path.join(stack, TOWER_TXT), "1\t2020-07-16 04:00:00\t2020-08-01 04:00:00\n")
            version_state_set("1.6", towerRestartPending=True)
            towerjobs = []
            g["start_job"] = lambda kind, v_, fn, **_k: towerjobs.append((kind, v_)) or type("J", (), {"id": "j0"})()
            for pending_, want in (("yes", []), ("unknown", []), ("no", [("towerfix", "1.6")])):
                if pending_ == "unknown":  # (a record that cannot be read may hold the change)
                    os.remove(creds_record_path("1.6"))
                    os.makedirs(creds_record_path("1.6"))
                elif pending_ == "no":
                    os.rmdir(creds_record_path("1.6"))
                naps = []

                def one_hour(s):
                    naps.append(s)
                    if len(naps) > 1:
                        raise _Killed()  # (its second hour: one sweep is what is looked at)

                time.sleep = one_hour
                try:
                    tower_watchdog()
                except _Killed:
                    pass
                finally:
                    time.sleep = saved_clock[1]
                assert towerjobs == want and naps == [3600, 3600], (pending_, towerjobs)
            g["start_job"] = saved["start_job"]

            # (J9) the OTHER re-renders keep the stack's own value (D8): over a re-extracted archive the templates
            #      name the vendor's value while the database, redis and every rendered file use the stack's own --
            #      the sources follow the rendered value BEFORE do_secrets' re-render (a run without `internal`;
            #      stopped, running) and before the loopback heal's: no login (what runs is the truth), ONE line.
            #      Skipped while a change is pending; a source that cannot be written: 500 before anything re-renders
            for up in (False, True):
                stack = mk_int("j-d8-%d" % up, env=env_of("Private_Root_71", "Private_Flask_71"), up=up)
                secure(note("Kept_Int_00071"))
                version_state_set("1.6", runningOk=up)
                reextract_int(full=False)
                j = job()
                res, waited = virtual(lambda: do_secrets("1.6", j, {"flask": note("AdminFlask_71000")}))
                assert res == {"changed": ["flask"]} and placed() == {"Kept_Int_00071"}, shown(up, placed())
                assert renders == ["1.6"] and alters == [] and logins == [] and int_lines(j) == [LINE_RESTORE], \
                    (up, renders, shown(j.lines))
                assert boots == [True] * up and srv["game"]["hk4e_work"] == "Kept_Int_00071", (up, boots)
                assert rd("creds.txt").endswith("h4ke pass: Kept_Int_00071\r\n") \
                    and "internalSource" not in int_sec(), "a restore names no new chooser"
            # ...and templates that disagree with no vendor value among them (one template edited by hand to a private
            # value): the same -- every rendered file keeps the stack's own value through the re-render
            stack = mk_int("j-d8edit", env=env_of("Private_Root_74", "Private_Flask_74"))
            secure(note("Kept_Int_00074"))
            write_text(os.path.join(stack, dbgate_rel),
                       rd(dbgate_rel).replace("Kept_Int_00074", note("Hand_Edit_Tmpl_74"), 1))
            j = job()
            res, waited = virtual(lambda: do_secrets("1.6", j, {"flask": note("AdminFlask_74000")}))
            assert res == {"changed": ["flask"]} and placed() == {"Kept_Int_00074"} and renders == ["1.6"] \
                and int_lines(j) == [LINE_REALIGN] and logins == [], shown(placed(), int_lines(j))
            stack = mk_int("j-d8heal", env=env_of("Private_Root_72", "Private_Flask_72"), up=True)
            secure(note("Kept_Int_00072"))
            reextract_int()  # (.env too: OUTER_IP=127.0.0.1 again -- the render is the loopback one now)
            g.update({"ADVERTISED_IP": "198.51.100.9",
                      "ensure_bind_ip": lambda v_, _j: write_env_value(v_, "OUTER_IP", "192.0.2.10")})
            j = job()
            try:
                res, waited = virtual(lambda: do_setup("1.6", j))
            finally:
                g.update({"ADVERTISED_IP": "", "ensure_bind_ip": saved["ensure_bind_ip"]})
            assert res["provisioned"] and waited == 3 and placed() == {"Kept_Int_00072"} and alters == [], \
                (res, waited)
            assert renders == ["1.6"] and int_lines(j) == [LINE_RESTORE] and boots == [True], (renders, shown(j.lines))
            stack = mk_int("j-d8more", env=env_of("Private_Root_73", "Private_Flask_73"))
            secure(note("Kept_Int_00073"))
            reextract_int(full=False)
            write_creds_record("1.6", internal_pending=note("Pending_Int_00073"))
            before = tree()
            assert restore_internal_sources("1.6", job()) is False and tree() == before, "a pending change: the Start's"
            write_creds_record("1.6", internal_pending="")
            failing.add("docker-compose.yml.tmpl")
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"flask": note("AdminFlask_73000")})))
            failing.clear()
            assert "nothing was re-rendered" in msg and renders == [] \
                and placed(sources=False) == {"Kept_Int_00073"}, shown(msg)
            assert "secretsPending" not in version_state("1.6") and env16("FLASK_SECRET_KEY") == "Private_Flask_73"

            # (J10) the admin's rotation (do_secrets with `internal`, D9): letter first -- redis-server reads a value
            #       that starts with '-' as an option of its own -- 400 before anything, never quoting it
            stack = mk_int("j-d9rule", env=env_of("Private_Root_80"), up=True)
            for bad in ("9DigitFirst_1234", "-Abcdefgh123", "--Abcdefg123", "_abcdefgh123"):
                msg = raises(400, lambda bad=bad: do_secrets("1.6", job(), {"internal": bad}))
                assert msg == "internal must be 8-128 characters: letters, digits, '_' or '-', starting with a " \
                              "letter." and bad not in msg, shown(msg)
            assert sent == [] and composes == [] and alters == [] and version_state("1.6") == {}
            #       ...the change on record (value + chooser "admin") before its ALTER -- before any file on a stack
            #       that has no database yet --, every place set, and cleared only once the stack RUNS on it: after
            #       verify_stack (running), after the final down (stopped), after the read-back (not bootstrapped)
            for kind in ("running", "stopped", "fresh"):
                stack = mk_int("j-d9" + kind, env=env_of("Private_Root_81"), up=kind == "running",
                               data=kind != "fresh", bootstrapped=kind != "fresh")
                version_state_set("1.6", runningOk=kind == "running")
                new = note("AdminInt_0081" + kind[0])
                j = job()
                res, waited = virtual(lambda: do_secrets("1.6", j, {"internal": new}))
                sec = int_sec()
                assert res == {"changed": ["internal"]} and placed() == {new} and pend() == "", shown(kind, placed())
                assert sec["internalSource"] == "admin" and sec["internalChangedAt"] \
                    and "internalPendingSource" not in sec, sorted(sec)
                assert [c_ for p_, c_ in record_writes if p_ == new][:1] == ["admin"], \
                    "who chose it was on record BEFORE the line went there: %s" % shown(record_writes)
                assert [l for l in j.lines if l.startswith("Stack internal password set in ")] == [
                    "Stack internal password set in %d file(s): bootstrap.sql, the compose files, prepare-db.sh, the "
                    "server XMLs." % (5 if kind == "fresh" else 8)], shown(j.lines)
                if kind == "fresh":
                    moved = [w_ for w_ in writes if w_[0] in INT_FILES and w_[2]]
                    assert len(moved) == 5 and all(w_[3] == new for w_ in moved) and sent == [] and composes == [], \
                        shown(moved)
                    continue
                assert at_alter == [{"internal": new, "source": "admin", "held": {VINT}}], shown(at_alter)
                assert srv["game"] == {"hk4e_work": new, "hk4e_readonly": new} and renders == ["1.6"]
                if kind == "running":
                    assert verified == [new] and composes == [DOWN, UP_DB, UP_ALL] and boots == [True], shown(composes)
                    assert srv["redis"] == new and version_state("1.6")["runningOk"] is True and logins == []
                else:  # (nothing booted to prove it: both accounts asked, while mysql was still up)
                    assert at_down == [new] and composes == [UP_DB, DOWN] and boots == [], shown(composes)
                    assert logins == [("hk4e_work", new, "ok", 1), ("hk4e_readonly", new, "ok", 1)], shown(logins)
            #       ...an internal-only statement that answers an error is judged by logging in as both accounts:
            #       refused -> nothing was changed (the record and the markers taken back); applied -> it goes on;
            #       one account only -> 500, the change stays on record -- and the next Start completes it, still the
            #       admin's
            for how in ("refused", "lost", "half"):
                stack = mk_int("j-d9" + how, env=env_of("Private_Root_82"), up=True)
                version_state_set("1.6", runningOk=True)
                srv["alter"] = how
                new = note("AdminInt_0082" + how[0])
                j = job()
                verdicts = {"refused": ["refused", "refused"], "lost": ["ok", "ok"], "half": ["ok", "refused"]}[how]
                if how == "lost":
                    res, waited = virtual(lambda: do_secrets("1.6", j, {"internal": new}))
                    assert res == {"changed": ["internal"]} and placed() == {new} and pend() == "", how
                else:
                    msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", j, {"internal": new})))
                    vs = version_state("1.6")
                    assert placed() == {VINT} and (vs.get("secretsPending") or {}).get("stage") != "restart", how
                    if how == "refused":
                        assert msg.startswith("ALTER USER failed -- nothing was changed: ") and pend() == "", \
                            shown(msg)
                        assert vs["runningOk"] is True and vs.get("secretsPending") is None, sorted(vs)
                        assert "internalPendingSource" not in int_sec()
                    else:
                        assert msg.startswith("ALTER USER failed (") and "could not be proven" in msg \
                            and pend() == new, shown(msg)
                        assert vs["runningOk"] is False and srv["game"] == {"hk4e_work": new, "hk4e_readonly": VINT}
                    clean([msg] + j.lines, new, "Private_Root_82")
                assert [(u_, p_) for u_, p_, _v, _n in logins] == [("hk4e_work", new), ("hk4e_readonly", new)] \
                    and [v_ for _u, _p, v_, _n in logins] == verdicts, shown(logins)
            for box in (composes, alters):
                del box[:]
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and placed() == {new} and pend() == "" and srv["game"]["hk4e_readonly"] == new
            assert composes == [DOWN, UP_DB, UP_REDIS, UP_ALL] and alters == [ALTER_INT] and boots == [True], \
                shown(composes)
            assert int_lines(j) == [LINE_RESTART, LINE_FINISH] and int_sec()["internalSource"] == "admin", \
                "the admin chose it -- the Start only completed it: %s" % shown(int_lines(j))
            #       ...and a stack whose places it cannot all set: 500 before anything is touched
            stack = mk_int("j-d9layout", env=env_of("Private_Root_83"), up=True)
            write_text(os.path.join(stack, dbgate_rel), re.sub(r'\bpwd="[^"]*"', 'password="x"', rd(dbgate_rel)))
            before = tree()
            msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"internal": note("AdminInt_00083")})))
            assert "does not hold it where this agent expects it" in msg and "Nothing was changed" in msg, shown(msg)
            assert tree() == before and sent == [] and composes == [] and alters == []
            #       ...game accounts that are not the two this agent alters (another host): ALTER USER IF EXISTS would
            #       answer 0 and change nothing -- and a listing that gets no answer tells nothing: 500 before anything
            #       is recorded or sent, the markers taken back, a mysql the run started stopped again
            for listed, why in (([("hk4e_work", "%"), ("hk4e_readonly", "%")],
                                 "this stack's game accounts are not the ones this agent knows"),
                                (None, "the game accounts could not be listed (MySQL gave no answer)")):
                for up in (True, False):
                    stack = mk_int("j-d9foreign%d%d" % (listed is None, up), env=env_of("Private_Root_84"), up=up)
                    version_state_set("1.6", runningOk=up)
                    srv["accounts"] = listed
                    msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(),
                                                                         {"internal": note("AdminInt_00084")})))
                    vs = version_state("1.6")
                    assert msg == "Stack internal password: %s -- nothing was changed." % why, shown(msg)
                    assert alters == [] and placed() == {VINT} and pend() == "" \
                        and not [p_ for p_, _c in record_writes if p_] and vs.get("secretsPending") is None \
                        and vs["runningOk"] is up and "internalPendingSource" not in (vs.get("secrets") or {}), \
                        shown(sorted(vs))
                    assert composes == ([] if up else [UP_DB, DOWN]), shown(composes)

            def refusing_chooser(data):
                """The state file refuses (disk full) every write that would put the admin's chooser on record."""
                if ((((data.get("versions") or {}).get("1.6") or {}).get("secrets") or {})
                        .get("internalPendingSource") == "admin"):
                    raise OSError(errno.ENOSPC, "No space left on device (selftest)")
                return saved["_write_state_atomic"](data)

            #       ...who chose it goes on record STRICTLY before the line: a state that cannot take it is a 507 with
            #       nothing recorded or sent (the markers taken back, a mysql the run started stopped again); a line
            #       that cannot be written is a 500 with nothing changed -- and the chooser on record put back as it
            #       was: none, a stale one, or that of an earlier change a stack not bootstrapped yet still has on
            #       record (a fresh install whose bootstrap failed after its sources took a random value)
            earlier = {"internalPendingSource": "random", "internalPendingFresh": True}
            for kind, fault, prior in (("running", "state", {}), ("stopped", "state", {}), ("fresh", "state", {}),
                                       ("running", "record", {}), ("stopped", "record", earlier),
                                       ("fresh", "record", earlier)):
                stack = mk_int("j-d9%s-%s" % (fault, kind), env=env_of("Private_Root_86"), up=kind == "running",
                               data=kind != "fresh", bootstrapped=kind != "fresh")
                version_state_set("1.6", runningOk=kind == "running", secrets=dict(prior))
                if kind != "fresh":
                    write_creds_record("1.6", root="Private_Root_86")  # (what the MySQL wait would note: nothing new)
                elif prior:  # (the earlier change: on record, every source on its value)
                    _apply_internal_plan(_internal_plan("1.6", note("Earlier_Int_0086"), sources_only=True)[0])
                    write_creds_record("1.6", internal_pending="Earlier_Int_0086")
                del record_writes[:]
                before = tree()
                if fault == "state":
                    g["_write_state_atomic"] = refusing_chooser
                else:
                    failing.add(CREDS_RECORD)
                try:
                    msg = raises(507 if fault == "state" else 500, lambda: virtual(lambda: do_secrets(
                        "1.6", job(), {"internal": note("AdminInt_00086")})))
                finally:
                    g["_write_state_atomic"] = saved["_write_state_atomic"]
                    failing.clear()
                vs = version_state("1.6")
                assert msg.startswith("Could not save the agent state (" if fault == "state" else
                                      "%s cannot be written (" % CREDS_RECORD) and msg.endswith(
                    " retry." if fault == "state" else " -- nothing was changed." if kind == "fresh" else
                    " -- nothing was changed: the new internal password must be on record there before the database "
                    "is altered."), shown(kind, fault, msg)
                assert alters == [] and tree() == before and not [p_ for p_, _c in record_writes if p_] \
                    and vs.get("secretsPending") is None and vs["runningOk"] is (kind == "running"), \
                    shown(kind, fault, sorted(vs))
                assert int_sec() == prior, "the chooser on record as it was: %s" % shown(kind, fault, int_sec())
                assert composes == ([UP_DB, DOWN] if kind == "stopped" else []), shown(kind, fault, composes)
            #       ...and on a STOPPED stack nothing boots to prove the change: both game accounts must accept the
            #       value -- asked while mysql is still up -- before its line goes. An ALTER that answered 0 and changed
            #       nothing, or hk4e_work only, keeps it: 500, the version down; the next Start completes the change,
            #       still the admin's
            for how in ("noop", "work-only"):
                stack = mk_int("j-d9" + how, env=env_of("Private_Root_85"))
                srv["alter"] = how
                new = note("AdminInt_0085" + how[0])
                msg = raises(500, lambda: virtual(lambda: do_secrets("1.6", job(), {"internal": new})))
                assert msg == "Stack internal password: after ALTER USER the game accounts could not be proven to " \
                              "use the new password -- it is recorded as pending in %s in the stack folder: the " \
                              "next Start of this version completes that change." % CREDS_RECORD, shown(how, msg)
                assert pend() == new and at_down == [new] and composes == [UP_DB, DOWN] and placed() == {new} \
                    and srv["game"] == {"hk4e_work": new if how == "work-only" else VINT, "hk4e_readonly": VINT} \
                    and not srv["up"], shown(how, composes)
                assert [(u_, p_, v_) for u_, p_, v_, _n in logins] == [
                    ("hk4e_work", new, "ok" if how == "work-only" else "refused"), ("hk4e_readonly", new, "refused")], \
                    shown(how, logins)
                for box in (composes, alters):
                    del box[:]
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                assert res == READY and alters == [ALTER_INT] \
                    and srv["game"] == {"hk4e_work": new, "hk4e_readonly": new} and pend() == "" \
                    and composes == [UP_DB, UP_REDIS, UP_ALL] and boots == [True], shown(how, composes)
                assert int_lines(j) == [LINE_FINISH] and int_sec()["internalSource"] == "admin", shown(int_lines(j))

            # (J11) the record (D10). One that cannot be read is trusted for nothing -- it may hold a change nobody can
            #       see (fail closed): a Start PROVES the stack consistent instead -- every place on one value, both
            #       game accounts and redis take it: one WARNING, nothing changed, the start goes on (a stopped stack,
            #       and one up with nothing but mysql / redis / sdk). Files and database that do not agree -- a value
            #       the accounts refuse, a place on another value, a login without a clear answer --, or redis that
            #       never answers with the files' value (named as such): 500, the version down (a down that fails is
            #       named too), nothing boots. Game services that run, or docker that cannot tell: 500 before
            #       anything. The file level: sources that disagree stop the install, sources that agree are left as
            #       they are; the restore before another re-render goes ahead. After the ALTER it is a failure like any
            #       other -- the version down, 500. A line this agent does not know survives every rewrite; a record
            #       that cannot be read -- EACCES too -- is the CALLER's OSError, never an empty record
            unread = "Stack internal password: %s cannot be read (" % CREDS_RECORD
            for rebooted in (False, True):
                stack = mk_int("j-d10-%d" % rebooted, env=env_of("Private_Root_90"))
                os.makedirs(os.path.join(stack, CREDS_RECORD))
                if rebooted:
                    srv.update(up=True, redis=VINT, services=dict.fromkeys(("mysql", "redis", "sdk"), "running"))
                j = job()
                res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
                assert res == READY and alters == [] and len(ps_calls) == rebooted and placed() == {VINT} \
                    and boots == [True] and pings == [(VINT, "PONG")], shown(rebooted, alters, pings)
                assert [(u_, p_, v_) for u_, p_, v_, _n in logins] == [("hk4e_work", VINT, "ok"),
                                                                       ("hk4e_readonly", VINT, "ok")], shown(logins)
                assert len(int_lines(j)) == 1 and int_lines(j)[0].startswith("WARNING: " + unread) \
                    and int_lines(j)[0].endswith(") -- the files and the database agree, starting anyway."), \
                    shown(j.lines)
                assert internal_change_pending("1.6")[0] == "unknown" and status16()["internalPassword"] is None \
                    and secrets_info("1.6")["internalPending"] is False
            for fault in ("db", "place", "redis", "login", "down"):
                stack = mk_int("j-d10" + fault, env=env_of("Private_Root_92"))
                os.makedirs(os.path.join(stack, CREDS_RECORD))
                if fault in ("db", "down"):
                    srv["game"] = dict.fromkeys(("hk4e_work", "hk4e_readonly"), note("Lost_Int_00092"))
                elif fault == "place":
                    write_text(os.path.join(stack, dbgate_rel[:-len(".tmpl")]), rd(dbgate_rel[:-len(".tmpl")]).replace(
                        'pwd="%s"' % VINT, 'pwd="%s"' % note("Stale_Hand_Edit_2"), 1))
                if fault == "down":
                    compose_rc[DOWN] = 1  # (...and the down that is to take the version down fails too)
                srv.update(redis_mute=fault == "redis", login_unknown=fault == "login")
                msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none"), nap=0.5))
                why = ("redis did not answer with the password the files name within %ds" % REDIS_READY_WAIT
                       if fault == "redis" else "the files and the database do not agree")
                assert msg.startswith(unread) and msg.endswith(
                    ") and %s -- make the file readable, then Start again.%s"
                    % (why, " Stopping the version failed (code 1) -- stop it, then Start it again."
                       if fault == "down" else "")), shown(fault, msg)
                assert composes == [UP_DB, DOWN] and boots == [] and alters == [] and srv["up"] is (fault == "down") \
                    and version_state("1.6")["runningOk"] is False, shown(fault, composes)
                assert bool(pings) is (fault == "redis"), "redis is asked once the files and both accounts agree: " \
                    + shown(fault, pings)
            compose_rc.clear()
            for ps_fail in (False, True):  # (game services that run -- or docker that cannot tell: nothing to prove on)
                stack = mk_int("j-d10up%d" % ps_fail, env=env_of("Private_Root_93"), up=True)
                os.makedirs(os.path.join(stack, CREDS_RECORD))
                srv["ps_fail"] = ps_fail
                state_before = _box_state_bytes(g["STATE_PATH"])
                msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
                running_ = ("docker cannot tell whether the version's game services run" if ps_fail
                            else "the version's game services run")
                assert msg.startswith(unread) and msg.endswith(
                    ") -- %s, so the files and the database cannot be proven to agree. Make the file readable, then "
                    "Start again." % running_), shown(ps_fail, msg)
                assert (composes, sent, logins) == ([], [], []) and _box_state_bytes(g["STATE_PATH"]) == state_before
            stack = mk_int("j-d10nodb", env=env_of("Private_Root_96"), server_root="Unknown_Root_0096")
            os.makedirs(os.path.join(stack, CREDS_RECORD))  # (...and MySQL that never answers: nothing to prove with)
            msg = raises(500, lambda: virtual(lambda: do_start("1.6", job(), provision="none")))
            assert msg.startswith(unread) and "MySQL did not answer" in msg and composes == [UP_DB] and boots == [] \
                and logins == [], shown(msg, composes)
            stack = mk_int("j-d10src", data=False, bootstrapped=False)  # (the file level, before a fresh bootstrap)
            os.makedirs(os.path.join(stack, CREDS_RECORD))
            before = tree()
            j = job()
            assert ensure_internal_sources("1.6", j) is None and tree() == before and len(j.lines) == 1 \
                and j.lines[0].startswith("WARNING: " + unread) and j.lines[0].endswith(
                    ") -- the source files are left as they are before the database is created."), shown(j.lines)
            write_text(os.path.join(stack, "bootstrap.sql"), int_sql.replace(VINT, note("Edited_Int_0095"), 1))
            before = tree()
            msg = raises(500, lambda: ensure_internal_sources("1.6", job()))
            assert "could not be brought in line (%s cannot be read (" % CREDS_RECORD in msg \
                and "-- not installing" in msg and tree() == before, shown(msg)
            # ...and before another re-render the sources follow what the stack runs on all the same (that writes no
            # record; do_secrets refuses such a stack before it gets there, the heal's provision then proves it)
            stack = mk_int("j-d10restore", env=env_of("Private_Root_94"))
            secure(note("Kept_Int_00094"))
            reextract_int(full=False)
            os.makedirs(os.path.join(stack, CREDS_RECORD))
            j = job()
            assert restore_internal_sources("1.6", j) is True and placed() == {"Kept_Int_00094"} and logins == [] \
                and int_lines(j) == [LINE_RESTORE], shown(placed(), j.lines)
            stack = mk_int("j-d10after", env=env_of("Private_Root_91"))
            srv["record_dies"] = True
            j = job()
            msg = raises(500, lambda: virtual(lambda: do_start("1.6", j, provision="none")))
            t_ = note(at_alter[0]["internal"])
            assert msg.endswith(UNFINISHED) and composes == [UP_DB, UP_REDIS, DOWN] and boots == [], \
                shown(msg, composes)
            assert placed() == {t_} and srv["game"]["hk4e_work"] == t_ and pending_now() is None
            assert status16()["internalPassword"] is None and version_state("1.6")["runningOk"] is False
            shutil.rmtree(os.path.join(stack, CREDS_RECORD))
            write_text(os.path.join(stack, CREDS_RECORD), "# an older head\nmysql/root: Private_Root_91\n"
                       "future (kind): kept as it is\r\ninternal (pending): %s\n" % t_)
            write_creds_record("1.6", internal_pending="")
            kept_ = "future (kind): kept as it is\n"
            assert rd(CREDS_RECORD) == _CREDS_RECORD_HEAD + "mysql/root: Private_Root_91\n" + kept_
            write_creds_record("1.6", root="", internal_pending=t_)
            assert rd(CREDS_RECORD) == _CREDS_RECORD_HEAD + "internal (pending): %s\n" % t_ + kept_
            write_text(os.path.join(stack, ".env"), vendor_env)  # (the rendered compose names a root .env does not)
            assert rendered_root_to_note("1.6", VROOT) == "Private_Root_91", "readable and empty: it would be noted"

            def denied(path_):
                if os.path.basename(path_) == CREDS_RECORD:
                    raise PermissionError(errno.EACCES, "Permission denied (selftest)")
                return saved["read_text"](path_)

            g["read_text"] = denied
            try:
                try:
                    read_creds_record("1.6")
                    raise AssertionError("a record EACCES refuses must be the caller's OSError, never an empty one")
                except PermissionError as e:
                    assert e.errno == errno.EACCES
                assert internal_change_pending("1.6")[0] == "unknown" and internal_kind("1.6") is None
                assert raises(409, lambda: refuse_while_internal_pending("1.6")).startswith(unread)
                assert rendered_root_to_note("1.6", VROOT) == "", "nobody can tell what it holds: nothing is noted"
                try:
                    write_creds_record("1.6", internal_pending="")
                    raise AssertionError("a record that cannot be read cannot be rewritten either")
                except PermissionError:
                    pass
            finally:
                g["read_text"] = saved["read_text"]
            assert pend() == t_, "...and it was not rebuilt without its lines"

            # (J12) reporting (D11): /status internalPassword "vendor" | "custom" | "pending" | null -- what the stack
            #       RUNS on (the rendered compose once bootstrapped, the templates before), never a value, never
            #       public; GET /server/secrets: internal (that value), internalVendorDefault, internalPending (never
            #       the pending VALUE), internalSource. (After a change: J1; a re-extraction: J4; no record: J11)
            stack = mk_int("j-report")
            info = secrets_info("1.6")
            assert status16()["internalPassword"] == "vendor" and (
                info["internal"], info["internalVendorDefault"], info["internalPending"], info["internalSource"]) \
                == (VINT, True, False, None)
            write_creds_record("1.6", internal_pending=note("Pending_Int_00095"))
            info = secrets_info("1.6")
            assert status16()["internalPassword"] == "pending" and (info["internalVendorDefault"],
                                                                   info["internalPending"]) == (False, True) \
                and "Pending_Int_00095" not in json.dumps(info), "never the pending value"
            full = g["status"]()
            pub = build_public_status(full, default_policy())
            dumps.extend((json.dumps(full), json.dumps(pub)))
            assert not [k_ for k_ in set(pub) | set(pub["versions"]["1.6"]) if k_.startswith("internal")], sorted(pub)
            assert full["versions"]["2.8"]["internalPassword"] is None, "no stack: null"
            stack = mk_int("j-report-fresh", data=False, bootstrapped=False)
            assert status16()["internalPassword"] == "vendor", "not bootstrapped: what the templates will render"
            secure(note("Kept_Int_00096"))
            assert status16()["internalPassword"] == "custom" and secrets_info("1.6")["internal"] == "Kept_Int_00096"
            write_text(os.path.join(stack, "docker-compose.yml.tmpl"),
                       compose_tmpl.replace(" --requirepass " + VINT, ""))
            write_text(os.path.join(stack, "bootstrap.sql"), "SET NAMES utf8;\n")
            assert status16()["internalPassword"] is None, "no value anywhere: null"

            # (J13) _uid_online asks redis with REDISCLI_AUTH -- never `redis-cli -a` (the password on its own argv):
            #       the model answers that shape only (anything else would be a process this block starts for real)
            stack = mk_int("j-uid", up=True)
            secure(note("Kept_Int_00097"))
            assert _uid_online("1.6", 4242) is False and spawned == [], shown(spawned)

            # (K) "Keep .env settings" (GIO_KEEP_ENV). While the switch is on the agent replaces nothing of a stack's
            #     own settings on its own initiative: every vendor value stays byte for byte -- no SQL, no login, no
            #     docker call of the stages' own --, OUTER_IP is never rewritten and a loopback render is neither
            #     healed nor refused. A private value is treated exactly as without the switch, a change on record is
            #     still finished, a record that cannot be read still fails closed -- and with the switch off the very
            #     same stacks are replaced as in the sections above.
            KEPT = "%s: still the vendor's published %s -- kept as it is (GIO_KEEP_ENV)."
            KEPT_MUIP, KEPT_FLASK = KEPT % ("MUIP sign key", "key"), KEPT % ("Flask secret key", "key")
            KEPT_ROOT = KEPT % ("MySQL root password", "password")
            KEPT_INT = KEPT % ("Stack internal password", "password")
            KEPT_BIND = ("OUTER_IP: GIO_BIND_IP=192.0.2.10 is not applied -- the stack's .env keeps OUTER_IP=127.0.0.1 "
                         "(GIO_KEEP_ENV).")
            # (...and what a loopback or empty OUTER_IP that stands means: a WARNING beside an advertised address)
            LOCAL_ONLY = ("OUTER_IP=%s in the stack's .env: the server's ports answer on this machine only%s -- .env "
                          "is kept as it is (GIO_KEEP_ENV). For players on other machines, set OUTER_IP in that .env "
                          "to this machine's address before Prepare server.")
            ADVERTISED_ALL_THE_SAME = ", although an advertised address is configured"
            KEPT_LOCAL = "WARNING: " + LOCAL_ONLY % ("127.0.0.1", ADVERTISED_ALL_THE_SAME)
            detected = []  # one entry per auto-detection of the box's own address

            def kept_lines(job_):
                return [l for l in job_.lines if "GIO_KEEP_ENV" in l]

            def changed(before_):
                """The files of the current stack that differ from `before_` (a tree()): written, new or gone."""
                after_ = tree()
                return sorted(k_ for k_ in set(before_) | set(after_) if before_.get(k_) != after_.get(k_))

            # (K1) OUTER_IP. The stack's .env is never written: GIO_BIND_IP is not applied (ONE line when it names
            #      another address), nothing is detected, and a render with its ports on 127.0.0.1 is neither a heal
            #      nor a 409 although the box advertises an address -- the stack counts as installed. A loopback or
            #      empty OUTER_IP that stands is SAID, in ONE line: the package ships 127.0.0.1, and a server prepared
            #      from it answers on this machine only -- a WARNING while an address is advertised (a host that has
            #      not resolved yet included), a plain line without one; an address of this machine needs no line.
            #      Only a value docker could not bind stops the job: a 500 that names the cause and both ways out
            g.update({"KEEP_ENV": True, "ADVERTISED_IP": "198.51.100.9",
                      "_bindable": lambda ip_: ip_ in ("127.0.0.1", "192.0.2.10"),
                      "detect_local_ip": lambda: detected.append(1) or "192.0.2.10"})
            stack = mk("k-bind")  # (the archive's .env -- OUTER_IP=127.0.0.1 -- and a render made from it)
            before = tree()
            assert not compose_binds_loopback("1.6") and status16()["bootstrapped"] is True
            for bind_ip, said in (("", [KEPT_LOCAL]), ("127.0.0.1", [KEPT_LOCAL]),
                                  ("192.0.2.10", [KEPT_BIND, KEPT_LOCAL])):
                g["BIND_IP"] = bind_ip
                j = job()
                assert ensure_bind_ip("1.6", j) == "127.0.0.1" and j.lines == said, (bind_ip, shown(j.lines))
            for host, ip, said in (("", "", LOCAL_ONLY % ("127.0.0.1", "")), ("game.example.com", "", KEPT_LOCAL)):
                g.update({"ADVERTISED_HOST": host, "ADVERTISED_IP": ip})
                j = job()
                assert ensure_bind_ip("1.6", j) == "127.0.0.1" and j.lines == [KEPT_BIND, said], shown(host, j.lines)
            g.update({"ADVERTISED_HOST": "", "ADVERTISED_IP": "198.51.100.9"})
            assert changed(before) == [] and detected == [], "nothing written, nothing detected"
            write_text(os.path.join(stack, ".env"), vendor_env.replace("OUTER_IP=127.0.0.1", "OUTER_IP="))
            j = job()
            assert ensure_bind_ip("1.6", j) == "" and j.lines == [
                KEPT_BIND.replace("keeps OUTER_IP=127.0.0.1", "keeps OUTER_IP=(empty)"),
                "WARNING: " + LOCAL_ONLY % ("(empty)", ADVERTISED_ALL_THE_SAME)], shown(j.lines)
            write_text(os.path.join(stack, ".env"), vendor_env.replace("OUTER_IP=127.0.0.1", "OUTER_IP=192.0.2.10"))
            j = job()
            assert ensure_bind_ip("1.6", j) == "192.0.2.10" and j.lines == [], shown(j.lines)
            write_text(os.path.join(stack, ".env"), vendor_env.replace("OUTER_IP=127.0.0.1", "OUTER_IP=192.0.2.123"))
            before = tree()
            msg = raises(500, lambda: ensure_bind_ip("1.6", job()))
            assert msg == ("OUTER_IP in the 1.6 stack's .env is 192.0.2.123, which is not an IP of this machine -- "
                           "docker cannot bind the server's ports to it. Correct OUTER_IP in that .env, or turn "
                           "\"Keep .env settings\" off (GIO_KEEP_ENV in the agent config) so the agent repairs it."), \
                shown(msg)
            assert changed(before) == [] and detected == []
            # ...the same stack with the switch off: its loopback render is refused, OUTER_IP is repaired -- with
            # GIO_BIND_IP, and without one by detecting the box's address
            g["KEEP_ENV"] = False
            assert compose_binds_loopback("1.6") and status16()["bootstrapped"] is False
            assert "Run Prepare server" in raises(409, lambda: do_start("1.6", job(), provision="none"))
            assert ensure_bind_ip("1.6", job()) == "192.0.2.10" == read_env("1.6")["OUTER_IP"] and detected == []
            write_text(os.path.join(stack, ".env"), vendor_env.replace("OUTER_IP=127.0.0.1", "OUTER_IP=192.0.2.123"))
            g["BIND_IP"] = ""
            assert ensure_bind_ip("1.6", job()) == "192.0.2.10" == read_env("1.6")["OUTER_IP"] and detected == [1]
            g.update({"ADVERTISED_IP": "", "_bindable": saved["_bindable"],
                      "detect_local_ip": saved["detect_local_ip"]})

            # (K2) the MUIP sign key: a vendor key stays -- ONE line, no file written, the state untouched --, and a
            #      configured GIO_MUIP_KEY is not applied either. A key that is not there is nothing to keep (silent --
            #      and no 500: nothing is being secured); a private key is silent, as without the switch
            g["KEEP_ENV"] = True
            stack = mk("k-muip")
            tmpl_k = os.path.join(stack, "server", "muipserver", "conf", "muipserver.xml.tmpl")
            before = tree()
            for cfg_key in ("", "Chosen_Key_12345"):
                g["MUIP_KEY"] = cfg_key
                j = job()
                assert ensure_muip_key("1.6", j) is None and j.lines == [KEPT_MUIP] and changed(before) == [], \
                    shown(cfg_key, j.lines)
            g["MUIP_KEY"] = ""
            assert version_state("1.6") == {} and kinds()[2] == "vendor"
            for text in ("<Root>\n  <ApiConf />\n</Root>\n",
                         muip_tmpl.replace(VMUIP, "SelftestOwnMuipKey0000000000000K02")):
                write_text(tmpl_k, text)
                before = tree()
                j = job()
                assert ensure_muip_key("1.6", j) is None and j.lines == [] and changed(before) == [], shown(j.lines)
            # ...the switch off: a template without sign_key cannot be prepared, the vendor's key is replaced
            g["KEEP_ENV"] = False
            write_text(tmpl_k, "<Root>\n  <ApiConf />\n</Root>\n")
            assert "muipserver.xml.tmpl" in raises(500, lambda: ensure_muip_key("1.6", job()))
            write_text(tmpl_k, muip_tmpl)
            assert ensure_muip_key("1.6", job()) == "random" and not is_vendor_muip_key(muip16())
            # ...and the one re-render that runs with the switch on -- a secrets rotation's -- loses no key the
            # stack really runs on: the archive extracted over this stack (the template the vendor's again, the
            # rendered muipserver.xml still the stack's own), then a rotation that names no MUIP key. The template
            # takes the stack's key back BEFORE the re-render, whatever the switch says -- a restore, not a
            # replacement: with the switch on nothing would ever replace a published key the re-render put there --
            # and the next ensure_muip_key finds nothing to keep. A key that IS the vendor's in both files stays
            pmuip = muip16()
            reextract()
            g["KEEP_ENV"] = True
            assert muip_keys() == (VMUIP, pmuip) and kinds()[2] == "vendor"
            j = job()
            res, waited = virtual(lambda: do_secrets("1.6", j, {"flask": note("AdminFlask_K2000")}))
            assert res == {"changed": ["flask"]} and muip_keys() == (pmuip, pmuip) and kinds()[2] == "custom", \
                shown(res, muip_keys())
            assert [l for l in j.lines if "MUIP" in l] == [LINE_MUIP_BACK] and kept_lines(j) == [] \
                and "MUIP_KEY: %s\r\n" % pmuip in rd("creds.txt"), shown(j.lines)
            clean(j.lines, pmuip)
            j = job()
            assert ensure_muip_key("1.6", j) is None and j.lines == [], shown(j.lines)
            stack = mk("k-muip-vendor")
            j = job()
            res, waited = virtual(lambda: do_secrets("1.6", j, {"flask": note("AdminFlask_K2001")}))
            assert res == {"changed": ["flask"]} and muip_keys() == (VMUIP, VMUIP) and kinds()[2] == "vendor" \
                and not [l for l in j.lines if "MUIP" in l], shown(j.lines)
            g["KEEP_ENV"] = False

            # (K3) the file level of the two .env secrets. On a just-extracted stack -- no database yet: without the
            #      switch both values are replaced right here -- nothing is written, whatever is configured: ONE line
            #      for the Flask key, none for the root password (the db stage says it), cold or not
            for cold in (True, False):
                stack = mk("k-env%d" % cold, data=False, bootstrapped=False)
                g.update({"KEEP_ENV": True, "MYSQL_ROOT_PASSWORD": "CfgRoot_12345",
                          "FLASK_SECRET_KEY": "CfgFlask_12345"})
                before = tree()
                j = job()
                assert ensure_env_secrets("1.6", j, cold=cold) == {} and j.lines == [KEPT_FLASK], shown(cold, j.lines)
                assert changed(before) == [] and events == [] and version_state("1.6") == {}, (cold, events)
                g.update({"KEEP_ENV": False, "MYSQL_ROOT_PASSWORD": "", "FLASK_SECRET_KEY": ""})
                out = ensure_env_secrets("1.6", job(), cold=cold)
                assert out == ({"flask": "random", "mysqlRoot": "random"} if cold else {"flask": "random"}), (cold, out)
            # ...the archive extracted over a secured stack (.env the vendor's again, the rendered files private):
            # the capture of the rendered root password is no replacement and happens as ever; the Flask key is NOT
            # put back -- .env stays the archive's, byte for byte -- and the sdk's rendered key stays the stack's own
            stack = mk("k-env-reextract", env=env_of("Private_Root_K03", "Private_Flask_K03"))
            write_text(os.path.join(stack, ".env"), vendor_env)
            g["KEEP_ENV"] = True
            before = tree()
            j = job()
            assert ensure_env_secrets("1.6", j, cold=True) == {"captured": True} and j.lines == [KEPT_FLASK], \
                shown(j.lines)
            assert changed(before) == [CREDS_RECORD] and rec() == {"root": "", "pending": "Private_Root_K03"}
            g["KEEP_ENV"] = False
            assert ensure_env_secrets("1.6", job(), cold=True) == {"flask": "restored"} \
                and rd(".env") == env_of(VROOT, "Private_Flask_K03"), "without the switch the sdk's key is put back"
            # ...and a PRIVATE .env whose rendered files are behind: they follow at a cold site, as without the switch
            stack = mk("k-env-follow")
            write_text(os.path.join(stack, ".env"), env_of("Private_Root_K04", "Private_Flask_K04"))
            g["KEEP_ENV"] = True
            j = job()
            assert ensure_env_secrets("1.6", j, cold=True) == {"sdkConfig": True, "compose": True} \
                and kept_lines(j) == [], shown(j.lines)
            assert rd("docker-compose.yml") == compose_of("Private_Root_K04") \
                and rd("sdk", "data", "config.json") == sdk_of("Private_Flask_K04")

            # (K4) the db stage of the root password: MySQL is up and accepts the vendor's -- ONE line; no probe of
            #      .env, no record line, no statement, whatever is configured. A private password: silent, as ever
            stack = mk("k-db", up=True)
            g["MYSQL_ROOT_PASSWORD"] = "CfgRoot_12345"
            before = tree()
            j = job()
            assert ensure_db_root_password("1.6", j) is False and j.lines == [KEPT_ROOT], shown(j.lines)
            assert (sent, composes, events) == ([], [], []) and changed(before) == [] \
                and srv["local"] == srv["any"] == VROOT, shown(sent, events)
            assert kinds()[0] == "vendor" and secrets_info("1.6")["mysqlRootVendorDefault"] is True
            g.update({"KEEP_ENV": False, "MYSQL_ROOT_PASSWORD": ""})
            assert ensure_db_root_password("1.6", job()) is True and alters == [ALTER_ROOT] \
                and env16() == srv["local"] == srv["any"] not in public, "without the switch: replaced by ALTER"
            stack = mk("k-db-private", env=env_of("Private_Root_K05"), up=True)
            g["KEEP_ENV"] = True
            before = tree()
            j = job()
            assert ensure_db_root_password("1.6", j) is False and j.lines == [] and sent == [] and changed(before) == []

            # (K5) the db stage of the internal password with no change on record: nothing is asked -- not docker
            #      (game_up None included), not MySQL, not redis -- and nothing written: ONE line while every place
            #      names the ONE vendor value, none while the places name several values (the archive's sources over
            #      a secured stack: not put back) or one private value
            stack = mk_int("k-int", env=env_of("Private_Root_K06"))
            before = tree()
            for game_up in (False, None):
                j = job()
                assert ensure_internal_password("1.6", j, game_up=game_up) is False and j.lines == [KEPT_INT], \
                    shown(game_up, j.lines)
            assert status16()["internalPassword"] == "vendor" and secrets_info("1.6")["internalVendorDefault"] is True
            secure(note("Kept_Int_000K6"))
            for sources in ("the stack's own", "the archive's"):
                if sources == "the archive's":
                    reextract_int(full=False)
                before = tree()
                j = job()
                assert ensure_internal_password("1.6", j, game_up=None) is False and j.lines == [] \
                    and changed(before) == [], shown(sources, j.lines)
            assert (sent, composes, logins, pings, ps_calls, spawned) == ([], [], [], [], [], []), \
                shown(sent, composes, logins, pings, ps_calls, spawned)

            # (K6) ...while a change ON RECORD is finished all the same -- the Start completes it: the ALTER, every
            #      place, redis, the line cleared, still its chooser's -- and a record that cannot be read still fails
            #      closed: the stack is proven consistent (both accounts, redis) before anything boots
            stack = mk_int("k-pending", env=env_of("Private_Root_K07"))
            write_creds_record("1.6", internal_pending=note("Pending_Int_000K7"))
            version_state_set("1.6", secrets={"internalPendingSource": "admin"})
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and placed() == {"Pending_Int_000K7"} and pend() == "" and alters == [ALTER_INT], \
                shown(res, placed(), alters)
            assert srv["game"] == {"hk4e_work": "Pending_Int_000K7", "hk4e_readonly": "Pending_Int_000K7"} \
                and srv["redis"] == "Pending_Int_000K7" and composes == [UP_DB, UP_REDIS, UP_ALL] and boots == [True], \
                shown(composes, boots)
            assert int_lines(j) == [LINE_FINISH] and kept_lines(j) == [] and int_sec()["internalSource"] == "admin", \
                shown(j.lines)
            stack = mk_int("k-unreadable", env=env_of("Private_Root_K08"))
            os.makedirs(os.path.join(stack, CREDS_RECORD))
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and alters == [] and placed() == {VINT} and boots == [True] \
                and pings == [(VINT, "PONG")], shown(res, alters, pings)
            assert [(u_, p_, v_) for u_, p_, v_, _n in logins] == [("hk4e_work", VINT, "ok"),
                                                                   ("hk4e_readonly", VINT, "ok")], shown(logins)
            assert len(int_lines(j)) == 1 and int_lines(j)[0].startswith("WARNING: " + unread) \
                and int_lines(j)[0].endswith(") -- the files and the database agree, starting anyway."), shown(j.lines)

            # (K7) the file level of the internal password, before a fresh bootstrap creates the database from the
            #      sources: ONE vendor value in every source is left as it is, silently (without the switch: a random
            #      one, the pending line first) -- while a change on record still reaches every source
            for keep in (True, False):
                stack = mk_int("k-src%d" % keep, data=False, bootstrapped=False)
                g["KEEP_ENV"] = keep
                before = tree()
                j = job()
                if keep:
                    assert ensure_internal_sources("1.6", j) is None and j.lines == [] and changed(before) == [] \
                        and version_state("1.6") == {}, shown(j.lines)
                else:
                    assert ensure_internal_sources("1.6", j) == "random" and int_lines(j) == [LINE_FRESH] \
                        and one_value(rendered=False) == pend() not in public, shown(j.lines)
            stack = mk_int("k-src-pending", data=False, bootstrapped=False)
            write_creds_record("1.6", internal_pending=note("Pending_Int_000K9"))
            version_state_set("1.6", secrets={"internalPendingSource": "admin"})
            g["KEEP_ENV"] = True
            j = job()
            assert ensure_internal_sources("1.6", j) == "admin" and placed(rendered=False) == {"Pending_Int_000K9"} \
                and int_lines(j) == [LINE_SAME] and pend() == "Pending_Int_000K9", shown(j.lines, placed())

            # (K8) end to end, through the real do_start / do_setup. A stack nobody secured -- every secret the
            #      vendor's, rendered from the archive's .env (its ports on 127.0.0.1) -- on a box that advertises an
            #      address and has every replacement configured, started with the switch on: not a file changes, no
            #      ALTER, no login as a game account, no ping, no `ps` -- only the staged start --, the game services
            #      boot on the vendor's values (consistent), ONE line per value, /status says keepEnv (never the
            #      public one) and keeps calling each value "vendor"
            stack = mk_int("k-start", vendor=True)
            g.update({"KEEP_ENV": True, "ADVERTISED_IP": "198.51.100.9", "BIND_IP": "192.0.2.10",
                      "MUIP_KEY": "Chosen_Key_12345", "MYSQL_ROOT_PASSWORD": "CfgRoot_12345",
                      "FLASK_SECRET_KEY": "CfgFlask_12345"})
            assert keep_env_unapplied() == ["GIO_BIND_IP", "GIO_MUIP_KEY", "GIO_MYSQL_ROOT_PASSWORD",
                                            "GIO_FLASK_SECRET_KEY"], "the start log names the idle keys, never a value"
            # ...and says "kept" where it would name what replaces a vendor value, configured or not; a configured
            # secret that cannot be used is a WARNING that promises no random one either
            assert [start_log_secret(v_) for v_ in ("Chosen_Key_12345", "")] == ["kept", "kept"]
            _warn_secret_ignored("GIO_MYSQL_ROOT_PASSWORD", "it is the vendor's published default", "password")
            assert journal[-1] == ("gio-agent: WARNING: GIO_MYSQL_ROOT_PASSWORD ignored -- it is the vendor's "
                                   "published default; while \"Keep .env settings\" is on (GIO_KEEP_ENV) each stack "
                                   "keeps the password it has."), journal[-1]
            before = tree()
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            assert res == READY and waited == 0 and changed(before) == [], (res, waited, shown(changed(before)))
            assert composes == [UP_DB, UP_ALL] and alters == [] and boots == [True] \
                and (logins, pings, ps_calls, renders) == ([], [], [], []) \
                and set(s_ for s_, _w in sent) == {"ok"}, shown(composes, alters, sent, boots)
            assert kept_lines(j) == [KEPT_MUIP, KEPT_FLASK, KEPT_ROOT, KEPT_INT], shown(kept_lines(j))
            assert srv["local"] == srv["any"] == VROOT and srv["redis"] == VINT \
                and srv["game"] == {"hk4e_work": VINT, "hk4e_readonly": VINT} and "secrets" not in version_state("1.6")
            full = g["status"]()
            pub = build_public_status(full, default_policy())
            dumps.extend((json.dumps(full), json.dumps(pub)))
            assert full["keepEnv"] is True and "keepEnv" not in json.dumps(pub), sorted(pub)
            assert re.fullmatch(r"[0-9a-f]{64}", full["build"]) and "build" not in pub \
                and full["build"] not in json.dumps(pub), sorted(pub)
            assert kinds() == ("vendor", "vendor", "vendor") and status16()["internalPassword"] == "vendor" \
                and status16()["bootstrapped"] is True
            # ...the same stack with the switch off: refused over its loopback render while the box advertises an
            # address; without one, every vendor value is replaced as in (F) and (J1)
            g["KEEP_ENV"] = False
            assert keep_env_unapplied() == [] and g["status"]()["keepEnv"] is False
            assert [start_log_secret(v_) for v_ in ("Chosen_Key_12345", "")] == ["config", "random"]
            _warn_secret_ignored("GIO_MUIP_KEY", _SECRET_VALUE_RULE, "key")
            assert journal[-1] == ("gio-agent: WARNING: GIO_MUIP_KEY ignored -- it must be 8-128 characters (letters, "
                                   "digits, '_' or '-'); a random key will be used."), journal[-1]
            docker(stack, ("down",))
            assert "Run Prepare server" in raises(409, lambda: do_start("1.6", job(), provision="none"))
            g.update({"ADVERTISED_IP": "", "BIND_IP": "", "MUIP_KEY": "", "MYSQL_ROOT_PASSWORD": "",
                      "FLASK_SECRET_KEY": ""})
            for box in (composes, sent, alters, logins, pings, boots):
                del box[:]
            j = job()
            res, waited = virtual(lambda: do_start("1.6", j, provision="none"))
            t_ = one_value()
            assert res == READY and alters == [ALTER_ROOT, ALTER_INT] and composes == [UP_DB, UP_REDIS, UP_ALL] \
                and boots == [True], shown(res, alters, composes)
            assert kept_lines(j) == [] and int_lines(j) == [LINE_VENDOR] and t_ not in public \
                and env16() not in public and env16("FLASK_SECRET_KEY") not in public \
                and not is_vendor_muip_key(muip16()), shown(j.lines)
            assert kinds() == ("custom", "custom", "custom") and status16()["internalPassword"] == "custom"
            # ...and Prepare server on a just-extracted stack (the Windows steps and the Linux script), again with an
            # advertised address and every replacement configured: every file the archive shipped is byte for byte
            # what it was -- .env with its OUTER_IP=127.0.0.1 too, and the render made from it is not refused --,
            # the vendor bootstrap reads the vendor's sources with nothing on record, MariaDB is created with the
            # vendor's root password and both game accounts with the vendor's internal one, no ALTER, no record --
            # the lines of the bootstrap (GIO_BIND_IP first, then the WARNING that such a server answers on this
            # machine only), then those of the provision
            for win in (True, False):
                g.update({"IS_WINDOWS": win, "KEEP_ENV": True, "ADVERTISED_IP": "198.51.100.9",
                          "BIND_IP": "192.0.2.10", "MUIP_KEY": "Chosen_Key_12345",
                          "MYSQL_ROOT_PASSWORD": "CfgRoot_12345", "FLASK_SECRET_KEY": "CfgFlask_12345"})
                stack = mk_int("k-fresh%d" % win, data=False, bootstrapped=False, vendor=True)
                before = tree()
                j = job()
                res, waited = virtual(lambda: do_setup("1.6", j))
                after = tree()
                assert res["provisioned"] and waited == 0, (win, res, waited)
                assert sorted(k_ for k_, v_ in before.items() if after.get(k_) != v_) == [], \
                    shown(win, sorted(k_ for k_, v_ in before.items() if after.get(k_) != v_))
                assert rd(".env") == vendor_env and rd("creds.txt") == vendor_creds \
                    and rd("docker-compose.yml") == compose_of(VROOT) and CREDS_RECORD not in after, win
                assert bootstraps == [("", {VINT}, None, None)], shown(win, bootstraps)
                assert srv["inits"] == 1 and srv["local"] == srv["any"] == VROOT and srv["redis"] == VINT \
                    and srv["game"] == {"hk4e_work": VINT, "hk4e_readonly": VINT} and srv["imports"] == [True, True], \
                    shown(win, srv["inits"], srv["imports"])
                assert alters == [] and (logins, pings, ps_calls) == ([], [], []) and boots == [True, True] \
                    and composes == [DOWN + ("-t", "5"), UP_DB, UP_ALL], shown(win, alters, boots, composes)
                assert kept_lines(j) == [KEPT_BIND, KEPT_LOCAL, KEPT_MUIP, KEPT_FLASK, KEPT_MUIP, KEPT_FLASK,
                                         KEPT_ROOT, KEPT_INT], shown(win, kept_lines(j))
                assert "secrets" not in version_state("1.6") and kinds() == ("vendor", "vendor", "vendor") \
                    and status16()["internalPassword"] == "vendor" and status16()["bootstrapped"] is True, win
            g.update({"IS_WINDOWS": saved["IS_WINDOWS"], "KEEP_ENV": False, "ADVERTISED_IP": "", "BIND_IP": "",
                      "MUIP_KEY": "", "MYSQL_ROOT_PASSWORD": "", "FLASK_SECRET_KEY": ""})

            # ...and no value of all the above ever left a stack folder: not in a job line, the agent log, the
            # state file, /status, the public projection or an error message
            learn()
            keep_state()
            needles = sorted(v_ for v_ in values if v_ and v_ not in public and not v_.isdigit())
            lines = [l for j_ in jobs for l in j_.lines]
            assert len(needles) > 100 and len(lines) > 200 and len(states) > 100 and len(dumps) > 10 and len(errors) > 10 \
                and len(streamed) > 100 and not spawned, (len(needles), len(lines), len(states), len(dumps),
                                                          len(errors), len(streamed), spawned)
            # (a command line of the logging runners is in the job log too: a login or a ping sent through them would
            # put its password there -- the selftest's fakes do not log, so they are swept on their own)
            for where, hay in (("a job line", lines), ("the agent log", journal), ("the state file", states),
                               ("/status or its public projection", dumps), ("an error message", errors),
                               ("a command line the job log shows", streamed)):
                blob = "\n".join(hay)
                assert not [v_ for v_ in needles if v_ in blob], "a secret value reached " + where
        finally:
            time.time, time.sleep = saved_clock
            os.fsync = saved_fsync
            g.update(saved)
            for v, (d_, p_) in saved_vdirs.items():
                VERSIONS[v]["dir"], VERSIONS[v]["project"] = d_, p_
            _STATE_RECOVERY.clear()
            _STATE_RECOVERY.update(saved_rec)
            _invalidate_public_status()
            shutil.rmtree(td, ignore_errors=True)

    _env_secrets_block()
