    assert tweak_resin(const_b, "134") == const_b == tweak_resin(const_b, "134", 160, 8), "no change = the original"
    assert tweak_resin(out, "134", 300, 4) == out, "idempotent"
    assert tweak_resin(const_b, "134", minutes=1) == const_b.replace(b"\t160\t8\t", b"\t160\t1\t")
    assert tweak_resin(const_b, "134", cap=2000).count(b"\t2000\t2000\t") == 1, "the cap may reach the hard limit"
    lf = const_b.replace(b"\r\n", b"\n")
