            rr_fresh()
            rr_apply({"resin": {"cap": 300}})
            os.remove(os.path.join(stack, *RR_C.split("/")))
            _tweaks_cache.clear()
            res = tweaks_info("1.6")["sections"]["resin"]
            assert res["ok"] is False and res["why"] == "missing" and res["revertFiles"] == [RR_C] == res["resetFiles"]
            j = _Job()
            assert do_tweaks("1.6", j, None, "", reset=["resin"]) \
                == {"version": "1.6", "changed": 1, "effect": "next-start", "clamped": 0, "blocked": []}
            assert rr_disk(RR_C) == rr_files[RR_C] and read_tweaks_record("1.6")["files"] == {} \
                and read_tweaks_record("1.6")["tweaks"] == {} and j.lines == [
                    "Gameplay settings: Reset of the Resin card -- 1 file is the original again.",
                    "The game server is not running -- 1 files are the originals again."], j.lines
            rr_apply({"resin": {"cap": 300}})
            bom_c = b"\xef\xbb\xbf" + rr_disk(RR_C)
