            rec = read_tweaks_record("1.6")
            assert rr_disk(RR_C) == rr_files[RR_C] and rr_disk(TWEAKS_DIR + "/hand/" + RR_C) == bom_c \
                and rec["files"][RR_C] == {"base": V_[RR_C], "out": V_[RR_C], "ok": True,
                                           "released": [rr_md5(bom_c)]} \
                and rec["tweaks"] == {"resin": {"cap": 300}} and rec["active"] == {}, rec
            # a Revert WHILE A REFUSAL STANDS puts back the settings that were in effect -- `active` with the keys the
            # take-over took out, what the next Start brings back --, the stored document with its own keys back,
            # and the refusal follows it
            rr_fresh()
            rr_apply({"resin": {"cap": 300}})
            rec = read_tweaks_record("1.6")
            write_tweaks_record("1.6", dict(rec, tweaks={"resin": {"cap": 400}}, refused={
                "at": 1, "error": "no", "digest": tweaks_digest({"resin": {"cap": 400}})}))
            rr_edit(RR_C, "134", lambda c: c[:2] + ["250"] + c[3:])
            rr_store()
            assert read_tweaks_record("1.6")["refused"]["digest"] == tweaks_digest({})
            j = _Job()
            got = do_tweaks("1.6", j, None, rr_take()["key"], revert=["resin"])
            rec = read_tweaks_record("1.6")
            assert got["effect"] == "next-start" and rec["active"] == {"resin": {"cap": 300}} \
                and rec["tweaks"] == {"resin": {"cap": 400}} \
                and rec["refused"] == {"at": 1, "error": "no", "digest": tweaks_digest({"resin": {"cap": 400}})} \
                and j.lines[-1] == ("The game server is not running -- the settings that were in effect are put back "
                                    "by the next Start (1 files)."), (rec, j.lines)
            got = tweaks_info("1.6")
            assert got["pending"] is True and got["refused"] == {"at": 1, "error": "no"}

            # (X) GET /server/tweaks over hand changes NOBODY STORED YET: every one the next job takes over, shown as it
            # will be -- the values of the bases with the game's own beside them where they differ, what gave way,
            # what is kept; the key the job is guarded with; nothing written
            rr_fresh()
            rr_apply({"quests": {"multiplier": {"world": 2}}, "domains": {"cost": 10, "multiplier": 2}})
