            rr_edit(RR_P, "82012711", lambda c: c[:6] + ["2"] + c[7:])  # (a row of domain 4200's reward tree)
            rr_edit(RR_C, "134", lambda c: c[:2] + ["250"] + c[3:])
            rr_edit(RR_V, "25", lambda c: c[:-1] + ["80"])
            rr_put(RR_S, tweak_group_slots(rr_files[RR_S], {"3001": 20010601}, cat["monsters"], cat["genericAffixes"]))
            rr_edit(RR_R, "100467", lambda c: c[:7] + ["100011", "7"] + c[9:])
            rr_edit(RR_R, "100351", lambda c: c[:7] + ["102", "300"] + c[9:])
            rr_edit(RR_D, "4200", lambda c: c[:31] + ["5"] + c[32:])
            before = rr_tree()
